_RUN_CACHE: ContextVar[dict[str, dict[Any, Any]] | None] = ContextVar(
    "ahmad_ref_engine_run_cache", default=None
)
_RUN_CALL_DEPTH: ContextVar[int] = ContextVar(
    "ahmad_ref_engine_run_call_depth", default=0
)
_SHIPWRECK_CALIBRATED_PRIOR: ContextVar[dict[str, Any] | None] = ContextVar(
    "shipwreck_calibrated_prior", default=None
)
_REFERENCE_INPUT_CHECKS: ContextVar[dict[str, Any] | None] = ContextVar(
    "reference_input_checks", default=None
)
_ENV_MISSING = object()


def _run_env_get(key: str, default: Any = None) -> Any:
    """Read one environment value at most once during a reference-engine run.

    Calibration switches are process configuration, but the hot combo path used to re-read and
    re-encode them more than a million times in one deep Gabriela round.  The context-local cache is
    reset for every public ``run_reference_engine`` call, so separate calls (and tests that monkeypatch
    the environment between calls) still observe the current configuration.  Direct helper calls
    outside an engine run retain the old immediate-read behaviour.
    """
    run_cache = _RUN_CACHE.get()
    if run_cache is None:
        return os.environ.get(key, default)
    env_cache = run_cache["env"]
    if key not in env_cache:
        env_cache[key] = os.environ.get(key, _ENV_MISSING)
    value = env_cache[key]
    return default if value is _ENV_MISSING else value


def _run_memoized(key: Any, factory: Callable[[], Any]) -> Any:
    run_cache = _RUN_CACHE.get()
    if run_cache is None:
        return factory()
    memo = run_cache["memo"]
    if key not in memo:
        memo[key] = factory()
    return memo[key]


def _draw_hero_count_keys() -> frozenset[str]:
    return _run_memoized("draw_hero_count_keys", _draw_hero_count_keys_uncached)


def _project_root() -> Path:
    env_root = os.environ.get("BIDKING_LAB_ROOT")
    if env_root:
        return Path(env_root).expanduser().resolve()
    return Path(__file__).resolve().parents[2]


def _static_data_candidates() -> tuple[Path, ...]:
    env_static = os.environ.get("BIDKING_AHMAD_STATIC_DATA")
    candidates: list[Path] = []
    if env_static:
        candidates.append(Path(env_static).expanduser())
    relative = Path(
        "external_references",
        "AuctionAnalyzer4.13.3",
        "_decompiled",
        "MapBidCalculator",
        "MapBidCalculator",
        "Models",
        "StaticData.cs",
    )
    candidates.append(ROOT / relative)
    bundle_root = getattr(sys, "_MEIPASS", None)
    if bundle_root:
        candidates.append(Path(bundle_root) / relative)
        candidates.append(Path(bundle_root) / "StaticData.cs")
    candidates.append(Path.cwd() / relative)
    return tuple(candidates)


def _resolve_static_data() -> Path:
    for candidate in _static_data_candidates():
        try:
            if candidate.exists():
                return candidate.resolve()
        except OSError:
            continue
    return _static_data_candidates()[0]


ROOT = _project_root()
STATIC_DATA = _resolve_static_data()

