def _grid_identity_hero_in_scope(hero_key: str) -> bool:
    def compute() -> bool:
        raw = _run_env_get(GRID_IDENTITY_HEROES_ENV)
        if not raw:
            return hero_key in GRID_IDENTITY_HEROES_DEFAULT
        return hero_key in {part.strip() for part in raw.split(",") if part.strip()}

    return _run_memoized(("grid_identity_hero_in_scope", hero_key), compute)


def _stable_public_avg_cell_value(raw_value: Any) -> tuple[bool, float | None]:
    """Project one present public avg-cell value without user-code coercion.

    The live contract is JSON-scalar only.  Exact builtin numbers and bounded
    plain numeric strings are stable across direct calls and JSON cloning;
    subclasses, containers and numeric protocol objects are deliberately not.
    """

    value: float
    if type(raw_value) is int:  # noqa: E721 - reject bool/subclasses/coercion
        if raw_value < 0 or raw_value > PUBLIC_AVG_CELLS_MAX_VALUE:
            return (False, None)
        value = float(raw_value)
    elif type(raw_value) is float:  # noqa: E721 - reject subclasses/coercion
        if (
            not math.isfinite(raw_value)
            or raw_value < 0.0
            or raw_value > PUBLIC_AVG_CELLS_MAX_VALUE
        ):
            return (False, None)
        value = raw_value
    elif type(raw_value) is str:  # noqa: E721 - subclasses may run user code
        if (
            not raw_value
            or len(raw_value) > PUBLIC_AVG_CELLS_TEXT_MAX_LENGTH
            or not raw_value.isascii()
            or PUBLIC_AVG_CELLS_TEXT_PATTERN.fullmatch(raw_value) is None
        ):
            return (False, None)
        try:
            value = float(raw_value)
        except (OverflowError, ValueError):
            return (False, None)
        if (
            not math.isfinite(value)
            or value < 0.0
            or value > PUBLIC_AVG_CELLS_MAX_VALUE
        ):
            return (False, None)
    else:
        return (False, None)
    return (True, value)


def _has_exact_bounded_json_keys(value: Any) -> bool:
    """Validate exact-dict keys without hashing or comparing any key."""

    if type(value) is not dict:  # noqa: E721 - exact builtin boundary
        return False
    for key in dict.keys(value):
        if (
            type(key) is not str  # noqa: E721 - reject str subclasses
            or len(key) > PUBLIC_AVG_JSON_MAX_STRING_LENGTH
        ):
            return False
    return True


def _stable_public_avg_scope_scalar(
    field: str,
    raw_value: Any,
) -> tuple[str, Any]:
    """Classify one scope value without invoking user-defined protocols."""

    if raw_value is _PUBLIC_AVG_SCOPE_ABSENT or raw_value is None:
        return ("missing", None)
    if field in {"hero", "phase"}:
        if type(raw_value) is not str:  # noqa: E721 - exact builtin only
            return ("invalid", None)
        if not raw_value:
            return ("missing", None)
        if len(raw_value) > PUBLIC_AVG_JSON_MAX_STRING_LENGTH:
            return ("invalid", None)
        return ("valid", raw_value)
    if field == "map_id":
        if type(raw_value) is int:  # noqa: E721 - reject bool/subclasses
            if raw_value == 0:
                return ("missing", None)
            if int.bit_length(raw_value) > PUBLIC_AVG_JSON_MAX_INT_BITS:
                return ("invalid", None)
            return ("valid", raw_value)
        if type(raw_value) is float:  # noqa: E721 - reject subclasses
            if raw_value == 0.0:
                return ("missing", None)
            if not math.isfinite(raw_value):
                return ("invalid", None)
            return ("valid", raw_value)
        if type(raw_value) is str:  # noqa: E721 - reject subclasses
            if not raw_value:
                return ("missing", None)
            if len(raw_value) > PUBLIC_AVG_JSON_MAX_STRING_LENGTH:
                return ("invalid", None)
            return ("valid", raw_value)
        return ("invalid", None)
    return ("invalid", None)


def _canonicalize_public_avg_scope(
    snapshot: dict[str, Any],
    raw_ui_contract: Any,
) -> tuple[dict[str, Any], bool]:
    """Return a copy whose downstream scope fallback is exact-builtin only.

    A context value owns its field when present.  Missing context values may
    fall back to the snapshot root, but an invalid selected value never falls
    through to another source.  This prevents later prepare/extract/summary
    consumers from re-reading the original protocol object after the public
    average projection has already declared it unsafe.
    """

    payload = dict.copy(snapshot)
    context: dict[str, Any] | None = None
    context_container_invalid = False
    if (
        type(raw_ui_contract) is dict  # noqa: E721 - exact builtin only
        and _has_exact_bounded_json_keys(raw_ui_contract)
    ):
        raw_context = dict.get(
            raw_ui_contract,
            "context",
            _PUBLIC_AVG_SCOPE_ABSENT,
        )
        if raw_context is _PUBLIC_AVG_SCOPE_ABSENT:
            pass
        elif (
            type(raw_context) is dict  # noqa: E721 - exact builtin only
            and _has_exact_bounded_json_keys(raw_context)
        ):
            context = raw_context
        else:
            # A missing context container permits root fallback.  A present
            # malformed container is declared scope evidence, so it invalidates
            # the complete UI transaction instead of silently borrowing root
            # scope and continuing to consume its public-average rows.
            context_container_invalid = True

    selected_invalid = context_container_invalid
    for field in ("hero", "phase", "map_id"):
        context_raw = (
            dict.get(context, field, _PUBLIC_AVG_SCOPE_ABSENT)
            if context is not None
            else _PUBLIC_AVG_SCOPE_ABSENT
        )
        context_status, context_value = _stable_public_avg_scope_scalar(
            field,
            context_raw,
        )
        if context_status == "valid":
            payload[field] = context_value
            continue
        if context_status == "invalid":
            root_status, root_value = _stable_public_avg_scope_scalar(
                field,
                dict.get(snapshot, field, _PUBLIC_AVG_SCOPE_ABSENT),
            )
            payload[field] = root_value if root_status == "valid" else None
            selected_invalid = True
            continue

        root_status, root_value = _stable_public_avg_scope_scalar(
            field,
            dict.get(snapshot, field, _PUBLIC_AVG_SCOPE_ABSENT),
        )
        if root_status == "valid":
            payload[field] = root_value
        else:
            payload[field] = None
            selected_invalid = selected_invalid or root_status == "invalid"

    return payload, selected_invalid


def _stable_public_avg_json_projection(raw_value: Any) -> Any:
    """Copy a JSON-shaped value without invoking user-defined protocols.

    Only exact builtin JSON containers and scalars are traversed.  Container or
    scalar subclasses, protocol objects, cycles and resource-exhaustion inputs
    invalidate the complete projection.  No valid prefix survives an invalid
    suffix, so semantic output cannot depend on dict/list traversal order.  The
    exact-builtin boundary also ensures ``get``/``items``/iteration/string/
    number magic cannot run before public-average classification.
    """

    active_container_ids: set[int] = set()
    node_budget = [0]

    def project(value: Any, depth: int) -> Any:
        node_budget[0] += 1
        if node_budget[0] > PUBLIC_AVG_JSON_MAX_NODES:
            return _PUBLIC_AVG_JSON_INVALID
        if value is None or type(value) is bool:  # noqa: E721 - reject subclasses
            return value
        if type(value) is int:  # noqa: E721 - reject subclasses/coercion
            if int.bit_length(value) > PUBLIC_AVG_JSON_MAX_INT_BITS:
                return _PUBLIC_AVG_JSON_INVALID
            return value
        if type(value) is float:  # noqa: E721 - reject subclasses/coercion
            return value if math.isfinite(value) else _PUBLIC_AVG_JSON_INVALID
        if type(value) is str:  # noqa: E721 - reject subclasses/coercion
            if len(value) > PUBLIC_AVG_JSON_MAX_STRING_LENGTH:
                return _PUBLIC_AVG_JSON_INVALID
            return value
        if depth >= PUBLIC_AVG_JSON_MAX_DEPTH:
            return _PUBLIC_AVG_JSON_INVALID
        if type(value) is dict:  # noqa: E721 - exact dict methods cannot be hooked
            if (
                len(value) > PUBLIC_AVG_JSON_MAX_CONTAINER_ITEMS
                or not _has_exact_bounded_json_keys(value)
            ):
                return _PUBLIC_AVG_JSON_INVALID
            identity = id(value)
            if identity in active_container_ids:
                return _PUBLIC_AVG_JSON_INVALID
            active_container_ids.add(identity)
            try:
                projected: dict[str, Any] = {}
                for key, child in dict.items(value):
                    projected_child = project(child, depth + 1)
                    if projected_child is _PUBLIC_AVG_JSON_INVALID:
                        return _PUBLIC_AVG_JSON_INVALID
                    projected[key] = projected_child
                return projected
            finally:
                active_container_ids.remove(identity)
        if type(value) is list:  # noqa: E721 - exact list iteration cannot be hooked
            if len(value) > PUBLIC_AVG_JSON_MAX_CONTAINER_ITEMS:
                return _PUBLIC_AVG_JSON_INVALID
            identity = id(value)
            if identity in active_container_ids:
                return _PUBLIC_AVG_JSON_INVALID
            active_container_ids.add(identity)
            try:
                projected_list: list[Any] = []
                for child in value:
                    projected_child = project(child, depth + 1)
                    if projected_child is _PUBLIC_AVG_JSON_INVALID:
                        return _PUBLIC_AVG_JSON_INVALID
                    projected_list.append(projected_child)
                return projected_list
            finally:
                active_container_ids.remove(identity)
        return _PUBLIC_AVG_JSON_INVALID

    projected = project(raw_value, 0)
    return None if projected is _PUBLIC_AVG_JSON_INVALID else projected


def _mask_public_avg_values_before_json_projection(
    snapshot: dict[str, Any],
    ui_contract: Any,
) -> Any:
    """Canonicalize scoped invalid values before the atomic JSON projection.

    A public-average value is a declared evidence slot, so a present invalid
    scalar has a stable semantic marker instead of invalidating unrelated
    quality evidence.  Every container on the route must already be an exact
    builtin; otherwise the atomic projector rejects the whole ``ui_contract``.
    """

    if (
        type(ui_contract) is not dict  # noqa: E721 - never call subclass hooks
        or not _has_exact_bounded_json_keys(ui_contract)
    ):
        return ui_contract
    context = dict.get(ui_contract, "context")
    if type(context) is not dict:  # noqa: E721 - malformed context is not traversed
        context = {}
    elif not _has_exact_bounded_json_keys(context):
        return ui_contract
    hero = dict.get(context, "hero")
    if hero is None:
        hero = dict.get(snapshot, "hero")
    map_id = dict.get(context, "map_id")
    if map_id is None:
        map_id = dict.get(snapshot, "map_id")
    phase = dict.get(context, "phase")
    if phase is None:
        phase = dict.get(snapshot, "phase")
    quality_avg_scope = (
        type(hero) is str  # noqa: E721
        and normalize_hero_key(hero) == "aisha"
        and (
            (type(map_id) is int and map_id == 4501)  # noqa: E721
            or (type(map_id) is str and map_id == "4501")  # noqa: E721
        )
        and type(phase) is str  # noqa: E721
        and phase.strip().lower() == "bidding"
    )

    constraints = dict.get(ui_contract, "constraints")
    if type(constraints) is not dict:  # noqa: E721
        return ui_contract
    if not _has_exact_bounded_json_keys(constraints):
        return ui_contract
    public_info = dict.get(constraints, "public_info")
    if type(public_info) is not dict:  # noqa: E721
        return ui_contract
    if not _has_exact_bounded_json_keys(public_info):
        return ui_contract
    rows = dict.get(public_info, "public_numeric_facts")
    container_invalid = False
    if type(rows) is list:  # noqa: E721
        source_rows: tuple[object, ...] = tuple(rows)
        changed = False
    elif type(rows) in (dict, tuple):  # noqa: E721
        source_rows, _ = _total_avg_cells_rows_container(rows)
        changed = True
    else:
        source_rows, container_invalid = _total_avg_cells_rows_container(rows)
        if not container_invalid:
            return ui_contract
        changed = True

    normalized_rows = list(source_rows)
    invalid_total_row = {
        "info_id": str(TOTAL_AVG_CELLS_INFO_ID),
        "value": {"status": "present_invalid"},
    }
    if container_invalid:
        # Preserve the non-target ui_contract through the JSON projection while
        # retaining an explicit stable conflict for the dedicated authority.
        normalized_rows.append(copy.deepcopy(invalid_total_row))

    for index, row in enumerate(source_rows):
        total_semantic, total_invalid = _total_avg_cells_row_semantic(row)
        if total_invalid:
            normalized_rows[index] = copy.deepcopy(invalid_total_row)
            changed = True
            continue
        if total_semantic is not None:
            raw_value = dict.get(row, "value")
            total_value_valid = (
                _strict_total_avg_cells_count(raw_value) is not None
                if total_semantic == "total_item_count"
                else _strict_total_avg_cells_mean(raw_value) is not None
            )
            if (
                not total_value_valid
                or _stable_public_avg_json_projection(row) is None
            ):
                normalized_rows[index] = copy.deepcopy(invalid_total_row)
                changed = True
            continue
        if not quality_avg_scope or type(row) is not dict:  # noqa: E721
            continue
        if not _has_exact_bounded_json_keys(row):
            return ui_contract
        semantic = dict.get(row, "semantic")
        if type(semantic) is not str or semantic not in PUBLIC_AVG_CELLS:
            continue
        valid, _value = _stable_public_avg_cell_value(dict.get(row, "value"))
        if valid:
            continue
        normalized_row = dict.copy(row)
        normalized_row["value"] = {"status": "present_invalid"}
        normalized_rows[index] = normalized_row
        changed = True
    if not changed:
        return ui_contract

    ui_copy = dict.copy(ui_contract)
    constraints_copy = dict.copy(constraints)
    public_info_copy = dict.copy(public_info)
    public_info_copy["public_numeric_facts"] = normalized_rows
    constraints_copy["public_info"] = public_info_copy
    ui_copy["constraints"] = constraints_copy
    return ui_copy


def _mask_hard_public_avg_values_before_json_projection(
    ui_contract: Any,
    *,
    invalid_owned_tiers: frozenset[str] = frozenset(),
    exact_owned_tiers: frozenset[str] = frozenset(),
) -> Any:
    """Stabilize targeted q4/q5 average-value rows without erasing siblings.

    The issue25 authority is evaluated before any lossy projection.  A malformed
    targeted row must still fail that authority closed, but it must not make the
    shared JSON projector discard an unrelated, valid issue26 total-grid ledger.
    Replace only targeted non-JSON rows with a stable invalid sentinel carrying
    the same claimed tier set; unrelated invalid data keeps the established
    whole-container rejection semantics.
    """

    if (
        type(ui_contract) is not dict  # noqa: E721 - exact JSON boundary
        or not _has_exact_bounded_json_keys(ui_contract)
    ):
        return ui_contract
    constraints = dict.get(ui_contract, "constraints")
    if (
        type(constraints) is not dict  # noqa: E721
        or not _has_exact_bounded_json_keys(constraints)
    ):
        return ui_contract
    public_info = dict.get(constraints, "public_info")
    if (
        type(public_info) is not dict  # noqa: E721
        or not _has_exact_bounded_json_keys(public_info)
    ):
        return ui_contract

    public_info_copy: dict[str, Any] | None = None
    for group_key in ("public_avg_values", "public_numeric_facts"):
        rows = dict.get(public_info, group_key, _ENV_MISSING)
        if rows is _ENV_MISSING:
            continue
        if type(rows) is dict:  # noqa: E721 - one aggregate row
            source_rows: tuple[object, ...] = (rows,)
            container_kind = "dict"
            container_untrusted = False
        elif type(rows) in (list, tuple):  # noqa: E721
            source_rows = tuple(rows)
            container_kind = "sequence"
            container_untrusted = False
        elif isinstance(rows, (dict, list, tuple)):
            source_rows, container_untrusted = (
                _hard_public_avg_value_container_rows(rows)
            )
            container_kind = "dict" if isinstance(rows, dict) else "sequence"
        else:
            continue

        normalized_rows = list(source_rows)
        changed = container_untrusted
        for index, row in enumerate(source_rows):
            if type(row) is dict:  # noqa: E721 - classifier avoids hooks
                claims, _aliases_valid = _hard_public_avg_value_row_claims(row)
                _issue26_semantic, issue26_targeted = (
                    _total_avg_cells_row_semantic(row)
                )
            elif isinstance(row, dict):
                claims = frozenset(("q4", "q5"))
                issue26_targeted = False
            else:
                claims = frozenset()
                issue26_targeted = False
            if (
                not claims
                and issue26_targeted
                and not _stable_total_avg_cells_invalid_row(row)
            ):
                # A malformed issue26 row can arrive in either aggregate
                # container. Its authority was decided from the original
                # snapshot, but even an exact JSON row must be replaced before
                # a foreign semantic reaches legacy issue25 consumers.
                normalized_rows[index] = {"status": "present_invalid"}
                changed = True
                continue
            if (
                _stable_public_avg_json_projection(row) is not None
                and not _hard_public_avg_value_explicit_claims(row)
                & invalid_owned_tiers
            ):
                continue
            if not claims:
                continue
            stable_soft_row = _stable_soft_public_avg_value_row(row)
            if (
                stable_soft_row is not None
                and not claims & invalid_owned_tiers
                and not claims & exact_owned_tiers
            ):
                normalized_rows[index] = stable_soft_row
                changed = True
                continue
            invalid_status = (
                "present_invalid"
                if _hard_public_avg_value_exact_claims(row)
                or claims & invalid_owned_tiers
                else "present_invalid_soft_keep"
            )
            if claims == frozenset(("q4",)):
                invalid_row: dict[str, Any] = {
                    "info_id": 200036,
                    "kind": "avg_value",
                    "value": {"status": invalid_status},
                }
            elif claims == frozenset(("q5",)):
                invalid_row = {
                    "info_id": 200037,
                    "kind": "avg_value",
                    "value": {"status": invalid_status},
                }
            else:
                invalid_row = {
                    "quality": {"status": "present_invalid"},
                    "kind": "avg_value",
                    "value": {"status": "present_invalid"},
                }
            normalized_rows[index] = invalid_row
            changed = True
        if not changed:
            continue
        if public_info_copy is None:
            public_info_copy = dict.copy(public_info)
        public_info_copy[group_key] = (
            normalized_rows[0]
            if container_kind == "dict"
            else normalized_rows
        )

    if public_info_copy is None:
        return ui_contract
    ui_copy = dict.copy(ui_contract)
    constraints_copy = dict.copy(constraints)
    constraints_copy["public_info"] = public_info_copy
    ui_copy["constraints"] = constraints_copy
    return ui_copy


def _stable_total_avg_cells_invalid_row(row: object) -> bool:
    """Recognize the dedicated issue26 sentinel without invoking protocols."""

    if type(row) is not dict:  # noqa: E721 - exact stable boundary
        return False
    row_keys = tuple(dict.__iter__(row))
    if (
        len(row_keys) != 2
        or any(type(key) is not str for key in row_keys)  # noqa: E721
        or frozenset(row_keys) != frozenset(("info_id", "value"))
    ):
        return False
    value = dict.get(row, "value")
    if type(value) is not dict:  # noqa: E721
        return False
    value_keys = tuple(dict.__iter__(value))
    if (
        len(value_keys) != 1
        or type(value_keys[0]) is not str  # noqa: E721
        or value_keys[0] != "status"
    ):
        return False
    return (
        type(dict.get(row, "info_id")) is str  # noqa: E721
        and dict.get(row, "info_id") == str(TOTAL_AVG_CELLS_INFO_ID)
        and type(dict.get(value, "status")) is str  # noqa: E721
        and dict.get(value, "status") == "present_invalid"
    )


def _mask_public_info_rows_before_json_projection(
    snapshot: dict[str, Any],
    *,
    invalid_owned_tiers: frozenset[str] = frozenset(),
    exact_owned_tiers: frozenset[str] = frozenset(),
) -> dict[str, Any]:
    """Stabilize raw public rows after authority decisions, before legacy use."""

    if type(snapshot) is not dict:  # noqa: E721 - exact root boundary
        return snapshot
    rows = dict.get(snapshot, "public_info_rows", _ENV_MISSING)
    if rows is _ENV_MISSING:
        return snapshot
    if type(rows) is dict:  # noqa: E721
        source_rows: tuple[object, ...] = (rows,)
        container_kind = "dict"
        changed = False
    elif type(rows) in (list, tuple):  # noqa: E721
        source_rows = tuple(rows)
        container_kind = "sequence"
        changed = False
    elif isinstance(rows, (dict, list, tuple)):
        source_rows, _container_untrusted = (
            _hard_public_avg_value_container_rows(rows)
        )
        container_kind = "dict" if isinstance(rows, dict) else "sequence"
        changed = True
    else:
        return snapshot

    normalized_rows: list[object] = []
    for row in source_rows:
        if type(row) is dict:  # noqa: E721 - classifier avoids hooks
            claims, _aliases_valid = _hard_public_avg_value_row_claims(row)
        elif isinstance(row, dict):
            claims = frozenset(("q4", "q5"))
        else:
            claims = frozenset()
        projected = _stable_public_avg_json_projection(row)
        if (
            projected is not None
            and not _hard_public_avg_value_explicit_claims(row)
            & invalid_owned_tiers
        ):
            normalized_rows.append(projected if changed else row)
            continue
        stable_soft_row = _stable_soft_public_avg_value_row(row)
        if (
            stable_soft_row is not None
            and not claims & invalid_owned_tiers
            and not claims & exact_owned_tiers
        ):
            normalized_rows.append(stable_soft_row)
            changed = True
            continue
        invalid_status = (
            "present_invalid"
            if _hard_public_avg_value_exact_claims(row)
            or claims & invalid_owned_tiers
            else "present_invalid_soft_keep"
        )
        if claims == frozenset(("q4",)):
            invalid_row: dict[str, Any] = {
                "info_id": 200036,
                "value": {"status": invalid_status},
            }
        elif claims == frozenset(("q5",)):
            invalid_row = {
                "info_id": 200037,
                "value": {"status": invalid_status},
            }
        elif claims:
            invalid_row = {
                "quality": {"status": "present_invalid"},
                "value": {"status": "present_invalid"},
            }
        else:
            invalid_row = {"status": "present_invalid"}
        normalized_rows.append(invalid_row)
        changed = True
    if not changed:
        return snapshot
    payload = dict.copy(snapshot)
    payload["public_info_rows"] = (
        normalized_rows[0]
        if container_kind == "dict" and normalized_rows
        else normalized_rows
    )
    return payload


def _project_public_avg_cell_rows(
    public_info: dict[str, Any],
) -> dict[int, tuple[str, bool, float | None]]:
    """Classify each public avg-cell row once for all scoped consumers."""

    projected: dict[int, tuple[str, bool, float | None]] = {}
    for row in public_info.get("public_numeric_facts") or ():
        if not isinstance(row, dict):
            continue
        raw_semantic = dict.get(row, "semantic")
        if type(raw_semantic) is not str or raw_semantic not in PUBLIC_AVG_CELLS:
            continue
        valid, value = _stable_public_avg_cell_value(dict.get(row, "value"))
        projected[id(row)] = (raw_semantic, valid, value)
    return projected


def _stabilize_aisha_public_avg_cell_snapshot(
    snapshot: dict[str, Any],
) -> dict[str, Any]:
    """Replace scoped present-invalid values before a product JSON clone.

    A JSON clone normalizes scalar subclasses into builtin scalar types.  Once
    that happens the engine cannot distinguish an original ``str``/``int``/
    ``float`` subclass from an allowed wire scalar.  Replacing invalid values
    with a JSON-stable marker before cloning keeps direct, dual-pass and mini
    product paths semantically identical without invoking value magic methods.
    """

    if (
        type(snapshot) is not dict  # noqa: E721 - root subclasses are untrusted
        or not _has_exact_bounded_json_keys(snapshot)
    ):
        return {}
    raw_ui_contract = dict.get(snapshot, "ui_contract")
    root_payload, _ = _canonicalize_public_avg_scope(
        snapshot,
        {},
    )
    projected_ui_contract = _stable_public_avg_json_projection(
        _mask_hard_public_avg_values_before_json_projection(
            _mask_public_avg_values_before_json_projection(
                root_payload,
                raw_ui_contract,
            ),
            exact_owned_tiers=_hard_public_avg_value_exact_owned_tiers(snapshot),
        )
    )
    if type(projected_ui_contract) is dict:  # noqa: E721 - stable exact boundary
        payload, scope_invalid = _canonicalize_public_avg_scope(
            snapshot,
            projected_ui_contract,
        )
        ui_contract = {} if scope_invalid else projected_ui_contract
    else:
        # Context scope is part of the ui_contract transaction.  A failed
        # projection must not leave a context prefix committed to the root
        # payload; keep only the independently classified root scope.
        payload = root_payload
        ui_contract = {}
    if type(ui_contract) is not dict:  # noqa: E721 - stable exact boundary
        ui_contract = {}
    payload["ui_contract"] = ui_contract
    context = dict.get(ui_contract, "context")
    if type(context) is not dict:  # noqa: E721 - stable exact boundary
        context = {}
    hero = dict.get(context, "hero")
    if hero is None:
        hero = dict.get(payload, "hero")
    map_id = dict.get(context, "map_id")
    if map_id is None:
        map_id = dict.get(payload, "map_id")
    phase = dict.get(context, "phase")
    if phase is None:
        phase = dict.get(payload, "phase")
    if (
        type(hero) is not str  # noqa: E721 - do not stringify scope metadata
        or normalize_hero_key(hero) != "aisha"
        or not (
            (type(map_id) is int and map_id == 4501)  # noqa: E721
            or (type(map_id) is str and map_id == "4501")  # noqa: E721
        )
        or type(phase) is not str  # noqa: E721 - do not stringify metadata
        or phase.strip().lower() != "bidding"
    ):
        return payload

    constraints = dict.get(ui_contract, "constraints")
    if type(constraints) is not dict:  # noqa: E721 - stable exact boundary
        return payload
    public_info = dict.get(constraints, "public_info")
    if type(public_info) is not dict:  # noqa: E721 - stable exact boundary
        return payload
    rows = dict.get(public_info, "public_numeric_facts")
    if type(rows) is not list:  # noqa: E721 - stable exact boundary
        return payload

    return payload


def _conflicting_public_avg_cell_semantics(
    projected_rows: dict[int, tuple[str, bool, float | None]],
    *,
    include_distinct_values: bool,
) -> frozenset[str]:
    """Return invalid groups and optionally duplicated distinct valid values.

    ``public_numeric_facts`` has no ordering or timestamp contract.  Treating its
    last row as authoritative makes the engine depend on serialization order.
    Repeated equivalent readings remain usable; distinct readings are ambiguous
    and must be ignored as a group by the scoped consumer.  Present-invalid rows
    are always conflicts, including rollback mode, because rollback must never
    restore conversion callbacks or exceptions.
    """

    first_values: dict[str, float] = {}
    conflicts: set[str] = set()
    for semantic, valid, value in projected_rows.values():
        if not valid or value is None:
            conflicts.add(semantic)
            continue
        previous = first_values.setdefault(semantic, value)
        if include_distinct_values and abs(previous - value) > 0.0001:
            conflicts.add(semantic)
    return frozenset(conflicts)


