def _q5_action_conflict_row() -> dict[str, Any]:
    return {
        "action_id": Q5_EXACT_TOTAL_ACTION_ID,
        "result_field": Q5_EXACT_TOTAL_RESULT_FIELD,
        "sort": Q5_ACTION_ROW_CONFLICT_SORT,
        "result": Q5_ACTION_ROW_CONFLICT_SORT,
    }


def _project_q5_action_row_container(value: Any) -> tuple[list[dict[str, Any]], bool]:
    """Project exact action rows without invoking container or key protocols."""

    if type(value) is list:  # noqa: E721 - subclasses can execute user code
        raw_rows = list.__iter__(value)
    elif type(value) is tuple:  # noqa: E721 - preserve the historical tuple bridge
        raw_rows = tuple.__iter__(value)
    elif type(value) is dict:  # noqa: E721 - historical single-row bridge
        raw_rows = iter((value,))
    else:
        return [_q5_action_conflict_row()], True

    projected: list[dict[str, Any]] = []
    for row in raw_rows:
        if type(row) is not dict:  # noqa: E721 - old consumers ignored non-dict rows
            continue
        keys = tuple(dict.keys(row))
        if any(type(key) is not str for key in keys):  # noqa: E721
            return [_q5_action_conflict_row()], True
        projected.append(dict.copy(row))
    return projected, False


def _stabilize_q5_action_row_snapshot(snapshot: dict[str, Any]) -> dict[str, Any]:
    """Atomically project both action bridges before any named row lookup."""

    if type(snapshot) is not dict:  # noqa: E721 - public engine input must be JSON-like
        return {"action_result_rows": [_q5_action_conflict_row()]}
    payload = dict.copy(snapshot)
    conflict = False

    top_rows = dict.get(snapshot, "action_result_rows", _Q5_ACTION_ROW_MISSING)
    if top_rows is not _Q5_ACTION_ROW_MISSING:
        projected_rows, invalid = _project_q5_action_row_container(top_rows)
        payload["action_result_rows"] = projected_rows
        conflict = conflict or invalid

    ui_contract = dict.get(snapshot, "ui_contract", _Q5_ACTION_ROW_MISSING)
    if type(ui_contract) is dict:  # noqa: E721 - never inspect a container subclass
        projected_ui = dict.copy(ui_contract)
        payload["ui_contract"] = projected_ui
        actions = dict.get(ui_contract, "actions", _Q5_ACTION_ROW_MISSING)
        if type(actions) is dict:  # noqa: E721
            projected_actions = dict.copy(actions)
            projected_ui["actions"] = projected_actions
            nested_rows = dict.get(actions, "results", _Q5_ACTION_ROW_MISSING)
            if nested_rows is not _Q5_ACTION_ROW_MISSING:
                projected_rows, invalid = _project_q5_action_row_container(
                    nested_rows
                )
                projected_actions["results"] = projected_rows
                conflict = conflict or invalid
        elif actions is not _Q5_ACTION_ROW_MISSING:
            projected_ui["actions"] = {
                "results": [_q5_action_conflict_row()]
            }
            conflict = True

    if conflict:
        # The top bridge is always consumed by the q5 selector. Publishing one
        # stable sentinel makes an invalid mirrored container an atomic conflict.
        payload["action_result_rows"] = [_q5_action_conflict_row()]
    return payload
