def _ethan_red_resid_lift_cap(*, q5_scan: bool) -> float:
    """Return the LIFT cap after the exact q5 scan action.

    The 1.10 default is scoped to exact scan provenance, not merely to an
    exact q5 value in evidence: a q5 appraisal game can gain exact q5 cells
    from a separate public fact, but its paired error profile still needs the
    historical 2.0 recovery range.  Roll back only this cap with
    ``ETHAN_DISABLE_RED_RESID_LIFT_Q5_SCAN_CAP=1``.
    """
    if not q5_scan:
        return 2.0
    if _run_env_get("ETHAN_DISABLE_RED_RESID_LIFT_Q5_SCAN_CAP") == "1":
        return 2.0
    raw = _run_env_get(
        "ETHAN_RED_RESID_LIFT_Q5_SCAN_CAP",
        ETHAN_RED_RESID_LIFT_Q5_SCAN_CAP_DEFAULT,
    )
    try:
        cap = float(raw)
    except (TypeError, ValueError, OverflowError):
        return ETHAN_RED_RESID_LIFT_Q5_SCAN_CAP_DEFAULT
    if not math.isfinite(cap):
        return ETHAN_RED_RESID_LIFT_Q5_SCAN_CAP_DEFAULT
    return min(2.0, max(1.0, cap))


def _aisha_exact_red_cells_value_curve(cells: float) -> float:
    """Return the cloud-truth median q6 total value for an exact total footprint."""
    points = AISHA_EXACT_RED_CELLS_VALUE_POINTS
    cells = max(0.0, float(cells))
    if cells <= points[0][0]:
        return points[0][1] * cells / points[0][0]
    for (x0, y0), (x1, y1) in zip(points, points[1:]):
        if cells <= x1:
            return y0 + (y1 - y0) * (cells - x0) / (x1 - x0)
    # The tail bins become sparse after 67 cells.  Continue monotonically at the stable pooled
    # global red $/cell rate instead of following noisy five-session medians.
    return points[-1][1] + (cells - points[-1][0]) * ETHAN_RESID_RED_PERCELL_GLOBAL


def _aisha_exact_red_cells_value_target(evidence: "RefEvidence") -> float | None:
    """Condition Aisha q6 total value on an exact total footprint."""
    if (
        os.environ.get(BIDKING_DISABLE_AISHA_EXACT_RED_CELLS_VALUE) == "1"
        or normalize_hero_key(evidence.hero) != "aisha"
        or evidence.phase != "bidding"
    ):
        return None
    cells = _quality_exact_cells("q6", evidence)
    if cells is None or cells < AISHA_EXACT_RED_CELLS_VALUE_MIN_CELLS:
        return None
    # Exact total value and per-item average are stronger direct evidence.  A partial known-item
    # value is already contained in this exact total footprint, however, so it must neither disable
    # the total-value target nor be added on top of it.
    if (
        _quality_exact_value("q6", evidence) is not None
        or evidence.avg_values.get("q6") is not None
    ):
        return None
    family = _ethan_map_family(evidence.map_id)
    family_percell = ETHAN_RESID_RED_PERCELL_BY_FAMILY.get(
        family, ETHAN_RESID_RED_PERCELL_GLOBAL
    )
    family_scale = family_percell / ETHAN_RESID_RED_PERCELL_GLOBAL
    return _aisha_exact_red_cells_value_curve(cells) * family_scale
