def _ethan_map_family(map_id: Any) -> str:
    try:
        prefix = int(map_id) // 100
    except (TypeError, ValueError):
        return "unknown"
    if prefix in (24, 34, 44):
        return "villa"
    if prefix in (25, 35, 45):
        return "shipwreck"
    if prefix == 26:
        return "hidden"
    return f"map_{prefix}xx"


def _ethan_nonred_cell_estimate(
    minimap_items: list[dict[str, Any]],
    total_grid: float,
    *,
    columns: int = AISHA_GRID_COLUMNS,
) -> tuple[int, int, int] | None:
    """(colored_red_cells, confirmed_nonred_cells, revealed_cells) from footprints, or None.

    v2 PRIOR-FILL semantics (v1 share-extrapolation was structurally wrong for ethan: his skill
    outlines carry NO quality, so invisible reds were counted as "non-red" and the residual
    collapsed to 0 on red-rich vaults — 2601 truth-186 design case). Only CONFIRMED quality
    splits count: colored red footprints vs colored non-red footprints; gray (quality-unknown)
    cells stay in the UNKNOWN mass, which the caller fills with the family red-share prior.
    Thin views (revealed/total < ETHAN_RED_RESIDUAL_MIN_REVEAL, default 0.35) return None."""
    if not minimap_items or not total_grid or total_grid <= 0:
        return None
    occupied: set[tuple[int, int]] = set()
    red_occupied: set[tuple[int, int]] = set()
    nonred_occupied: set[tuple[int, int]] = set()
    for item in minimap_items:
        row = _safe_int(item.get("row"))
        col = _safe_int(item.get("col"))
        if row is None or col is None:
            continue
        width = max(1, _safe_int(item.get("width")) or 1)
        height = max(1, _safe_int(item.get("height")) or 1)
        quality = _safe_int(item.get("quality"))
        for dr in range(height):
            for dc in range(width):
                cc = col + dc
                if 1 <= cc <= columns:
                    occupied.add((row + dr, cc))
                    if quality == 6:
                        red_occupied.add((row + dr, cc))
                    elif quality is not None and quality > 0:
                        nonred_occupied.add((row + dr, cc))
    revealed = len(occupied)
    if revealed <= 0:
        return None
    min_reveal = 0.35
    try:
        min_reveal = float(os.environ.get("ETHAN_RED_RESIDUAL_MIN_REVEAL", min_reveal))
    except (TypeError, ValueError):
        pass
    if revealed / float(total_grid) < min_reveal:
        return None
    return len(red_occupied), len(nonred_occupied), revealed


def _max_minimap_quality(items: list[dict[str, Any]]) -> int | None:
    qualities = [
        int(value)
        for item in items
        if (value := _safe_int(item.get("quality"))) is not None and int(value) > 0
    ]
    return max(qualities) if qualities else None


def _aisha_layout_footroom_multipliers(round_no: int) -> tuple[float, float, float]:
    """Conservative / balanced(P50) / aggressive multipliers on rows_below*cols base."""
    if int(round_no) <= 3:
        return (0.5, 0.75, 1.0)
    if int(round_no) == 4:
        return (0.75, 1.0, 1.35)
    return (1.0, 1.25, 1.5)


def _aisha_layout_footroom_raise_cap(round_no: int) -> int:
    if int(round_no) <= 3:
        return 15
    if int(round_no) == 4:
        return 22
    return 28


def _aisha_layout_viewport_fill_ratio(*, known_cells: int, deepest: int, columns: int) -> float:
    viewport_cells = max(1, int(deepest) * int(columns))
    return min(1.0, max(0.0, float(known_cells) / float(viewport_cells)))


def _aisha_layout_sparse_footroom_boost(fill_ratio: float) -> float:
    # Sparse early viewport (top-heavy scans) may leave more rows below; dense deep fill needs less.
    return max(0.2, min(0.85, 1.0 - float(fill_ratio)))


def _aisha_layout_target_looks_undershot(
    *,
    total_grid_target: float | None,
    known_cells: int,
    rows_below: int,
    columns: int,
    round_no: int,
) -> bool:
    if total_grid_target is None:
        return True
    baseline = float(total_grid_target)
    if baseline <= float(known_cells) + 0.5:
        return True
    # Early rounds: shallow visible depth with low target vs occupied viewport is a common undershoot.
    round_scale = 0.45 if int(round_no) <= 3 else (0.35 if int(round_no) == 4 else 0.28)
    implied_ceiling = float(known_cells) + float(rows_below) * float(columns) * round_scale
    return baseline + 0.5 < implied_ceiling


def _aisha_layout_mode_from_snapshot(snapshot: dict[str, Any]) -> str:
    raw = snapshot.get("audit_aisha_layout_mode")
    if isinstance(raw, str):
        mode = raw.strip().lower()
        if mode in VALID_AISHA_LAYOUT_MODES:
            return mode
    return DEFAULT_AISHA_LAYOUT_MODE


def _aisha_d1_mode_from_snapshot(snapshot: dict[str, Any]) -> str:
    raw = snapshot.get("audit_aisha_d1_mode")
    if isinstance(raw, str):
        mode = raw.strip().lower()
        if mode in VALID_AISHA_D1_MODES:
            return mode
    return DEFAULT_AISHA_D1_MODE


def _snapshot_round_no(snapshot: dict[str, Any]) -> int | None:
    ui_contract = snapshot.get("ui_contract")
    if isinstance(ui_contract, dict):
        context = ui_contract.get("context")
        if isinstance(context, dict):
            round_no = _safe_int(context.get("round"))
            if round_no is not None:
                return round_no
    return _safe_int(snapshot.get("round"))


def _snapshot_map_id(snapshot: dict[str, Any]) -> int | None:
    ui_contract = snapshot.get("ui_contract")
    if isinstance(ui_contract, dict):
        context = ui_contract.get("context")
        if isinstance(context, dict):
            mid = _safe_int(context.get("map_id"))
            if mid is not None:
                return mid
    return _safe_int(snapshot.get("map_id"))


def _aisha_pure_prior_red_keep(map_id: int | None) -> float:
    """Phantom-red value keep for pure-prior red, optionally per map FAMILY.

    Locate result (2026-06-19, full-library + user-export): the phantom-red over-value
    the user feels ("把把过估") is concentrated on LOW-red maps (villa 24xx) where a
    pure-prior red is almost always truly 0, while on high-red shipwreck (25/45xx) a
    pure-prior red is often a real hidden big red (keep must stay high). A single flat
    keep can't serve both -> allow a per-family override so the damp is asymmetric.

    Env `AISHA_PURE_PRIOR_RED_KEEP_BY_FAMILY` = "24:0.05,25:0.30,45:0.30" (family=map//100).
    Empty/unset -> flat `AISHA_PURE_PRIOR_RED_KEEP` (current behaviour, no-op default).
    """
    flat = float(os.environ.get("AISHA_PURE_PRIOR_RED_KEEP") or AISHA_PURE_PRIOR_RED_KEEP)
    spec = os.environ.get("AISHA_PURE_PRIOR_RED_KEEP_BY_FAMILY") or ""
    if not spec or map_id is None:
        return flat
    family = int(map_id) // 100
    for part in spec.split(","):
        part = part.strip()
        if not part or ":" not in part:
            continue
        fam_s, _, keep_s = part.partition(":")
        try:
            if int(fam_s.strip()) == family:
                return float(keep_s.strip())
        except ValueError:
            continue
    return flat


def _aisha_red_keep_evidence_ramp(q6_count_mid: float | None, base_keep: float) -> float:
    """Scale a pure-prior red keep UP toward AISHA_RED_KEEP_RAMP_TOP as the engine's own q6 COUNT
    estimate rises (see the constants block). Below LO -> flat base (phantom suppression intact);
    above HI -> the ceiling (genuine high red no longer halved); linear between."""
    if (
        base_keep >= 1.0
        or q6_count_mid is None
        or os.environ.get(AISHA_DISABLE_RED_KEEP_RAMP)
    ):
        return base_keep
    lo = float(os.environ.get("AISHA_RED_KEEP_RAMP_LO") or AISHA_RED_KEEP_RAMP_LO)
    hi = float(os.environ.get("AISHA_RED_KEEP_RAMP_HI") or AISHA_RED_KEEP_RAMP_HI)
    top = float(os.environ.get("AISHA_RED_KEEP_RAMP_TOP") or AISHA_RED_KEEP_RAMP_TOP)
    if hi <= lo:
        return base_keep
    fraction = max(0.0, min(1.0, (float(q6_count_mid) - lo) / (hi - lo)))
    ceiling = max(base_keep, top)
    return base_keep + (ceiling - base_keep) * fraction


def _aisha_d1_shadow_q6_discount(
    *,
    round_no: int,
    q6_count_range: tuple[int | None, int | None, int | None],
    total_grid_range: tuple[int | None, int | None, int | None],
    q6_count_locked: bool,
) -> float | None:
    """Shadow-only suggested down-weight on red value tail; live apply deferred to Phase 2."""
    if q6_count_locked:
        return None
    low, _mid, high = q6_count_range
    if low is None or high is None:
        return None
    span = max(0, int(high) - int(low))
    round_caps = {1: 0.55, 2: 0.65, 3: 0.75, 4: 0.85, 5: 0.90}
    discount = float(round_caps.get(min(max(int(round_no), 1), 5), 0.90))
    if span >= 2:
        discount *= max(0.45, 1.0 - 0.08 * min(span, 5))
    grid_low, _grid_mid, grid_high = total_grid_range
    if grid_low is not None and grid_high is not None and int(grid_high) - int(grid_low) >= 25:
        discount *= 0.92
    discount = round(max(0.35, min(1.0, discount)), 2)
    if discount >= 0.98:
        return None
    return discount


def _is_pure_prior_red(evidence: RefEvidence) -> bool:
    """True when red (q6) has zero evidence of any kind → its count comes purely
    from the map quality prior. Red is invisible to Aisha, so a pure-prior red can
    over-state value when the warehouse actually has 0 red (false-positive red)."""
    if int(evidence.fixed_counts.get("q6", 0) or 0) > 0:
        return False
    if int(evidence.min_counts.get("q6", 0) or 0) > 0:
        return False
    # any structured sum touching red constrains it → not pure prior
    for key in ("q6", "q5q6", "q5q6_min", "q4q5q6"):
        if evidence.count_sums.get(key) not in (None, ""):
            return False
    for table in (
        evidence.avg_cells,
        evidence.quality_cells,
        evidence.quality_cell_floors,
        evidence.avg_values,
        evidence.quality_values,
        evidence.quality_value_floors,
        evidence.split_counts,
        evidence.split_quality_cells,
        evidence.split_avg_cells,
    ):
        if table.get("q6") not in (None, "", 0, 0.0):
            return False
    return True


def _apply_aisha_d1_bid_adjustment(
    notes: list[str],
    *,
    snapshot: dict[str, Any],
    hero_key: str,
    quality_count_ranges: dict[str, tuple[int | None, int | None, int | None]],
    total_grid_range: tuple[int | None, int | None, int | None],
    evidence: RefEvidence,
    p50: float | None,
    rv50: float | None,
) -> float | None:
    """Red q6 value-tail adjustment.

    Two layered mechanisms over the *same* round-aware discount:
    - **pure-prior red value cap** (live default, env-reversible): when red has zero
      evidence (count comes purely from the map quality prior) the discount is
      *applied* to value p50, regardless of d1 audit mode. Mitigates an invisible
      false-positive red inflating the quote (2509/2507). Value-only; counts/grid/
      count_prior calibration untouched. Rollback: BIDKING_DISABLE_AISHA_RED_PRIOR_CAP=1.
    - **d1 audit mode** (off/shadow/apply): legacy experiment knob. shadow emits a
      note only; apply discounts value. Independent of the cap above.
    """
    if hero_key != "aisha":
        return None
    round_no = _snapshot_round_no(snapshot)
    if round_no is None:
        return None
    if evidence.fixed_counts.get("q6") not in (None, ""):
        return None
    q6_range = quality_count_ranges.get("q6")
    if not q6_range:
        return None
    discount = _aisha_d1_shadow_q6_discount(
        round_no=int(round_no),
        q6_count_range=q6_range,
        total_grid_range=total_grid_range,
        q6_count_locked=False,
    )
    # discount may be None (no shadow signal). It only gates the legacy pure-prior/d1 note + the
    # round-aware floor on F1's keep; F3 (evidenced red) does NOT depend on it.

    pure_prior_cap = (
        not os.environ.get("BIDKING_DISABLE_AISHA_RED_PRIOR_CAP")
        and _is_pure_prior_red(evidence)
        # LEVER1 already corrected the phantom red COUNT -> the value cap is double-correcting, skip it.
        and not _aisha_no_red_damp_active(evidence, int(round_no))
    )
    d1_mode = _aisha_d1_mode_from_snapshot(snapshot)

    # Notes: cap and d1-mode are orthogonal observability signals; emit both.
    if discount is not None:
        if pure_prior_cap:
            _append_source_note_once(notes, f"{AISHA_RED_PRIOR_CAP_NOTE}={discount:g}@r{int(round_no)}")
        if d1_mode == "shadow":
            _append_source_note_once(notes, f"{AISHA_D1_SHADOW_Q6_DISCOUNT_NOTE}={discount:g}@r{int(round_no)}")
        elif d1_mode == "apply":
            _append_source_note_once(notes, f"{AISHA_D1_APPLY_Q6_DISCOUNT_NOTE}={discount:g}@r{int(round_no)}")

    if p50 is None or rv50 is None or rv50 <= 0:
        return None
    non_red = max(0.0, float(p50) - float(rv50))

    # F1: pure-prior red (zero q6 evidence) -> phantom-red disasters. Trim the red tail to
    # AISHA_PURE_PRIOR_RED_KEEP, never weaker than the round-aware shadow discount.
    if pure_prior_cap or d1_mode == "apply":
        if pure_prior_cap:
            keep = _aisha_pure_prior_red_keep(_snapshot_map_id(snapshot))
            if discount is not None:
                keep = min(keep, float(discount))
            # Ramp AFTER the round/span discount: a genuinely red-heavy vault (high q6 count
            # estimate) should lift the keep back up even though its wide count span pushed the
            # discount down -- otherwise the span penalty re-buries the real red we just released.
            q6_count_mid = q6_range[1] if q6_range and len(q6_range) > 1 else None
            keep = _aisha_red_keep_evidence_ramp(q6_count_mid, keep)
        else:  # legacy d1 apply mode
            keep = float(discount) if discount is not None else 1.0
        if keep < 1.0:
            _append_source_note_once(notes, f"aisha_pure_prior_red_keep={keep:g}@r{int(round_no)}")
            return non_red + float(rv50) * keep
        return None

    # F3: evidenced red (has q6 evidence, not pure-prior) is still over-valued. Trim the red tail,
    # but EXEMPT true jackpots (rv50 > cap = acceptable hidden-big-red).
    if not os.environ.get(AISHA_DISABLE_EVID_RED_KEEP) and int(evidence.min_counts.get("q6", 0) or 0) > 0:
        evid_keep = float(os.environ.get("AISHA_EVID_RED_KEEP") or AISHA_EVID_RED_KEEP)
        jackpot_cap = float(os.environ.get("AISHA_EVID_RED_JACKPOT_CAP") or AISHA_EVID_RED_JACKPOT_CAP)
        if evid_keep < 1.0 and float(rv50) <= jackpot_cap:
            _append_source_note_once(notes, f"aisha_evid_red_keep={evid_keep:g}@r{int(round_no)}")
            return non_red + float(rv50) * evid_keep
    return None


def _apply_category_reveal_pure_prior_red_keep(
    notes: list[str],
    *,
    snapshot: dict[str, Any],
    hero_key: str,
    evidence: RefEvidence,
    quality_count_ranges: dict[str, tuple[int | None, int | None, int | None]],
    p50: float | None,
    rv50: float | None,
) -> float | None:
    """Phantom-red VALUE trim for category-reveal heroes, mirroring the aisha F1 keep.

    Category-reveal heroes (tatiana etc.) reveal one category's quality (never red), so on a
    no-red vault the map-prior red never decays and inflates the quote (proof 2401/374099586:
    truth q6=0 yet reference bakes red-value mid ~269k -> +90% over). When red has ZERO evidence
    (`_is_pure_prior_red`), trim its value tail to the keep fraction (`_aisha_pure_prior_red_keep`,
    lifted by the same q6-count ramp so a genuinely red-rich estimate is not over-suppressed).
    A revealed red (min_counts.q6>0 -> not pure-prior) is left untouched — that is the bidirectional
    "reveal red -> full value" half, and it is why the reused draw COUNT damp was inert here (it
    self-disables on any revealed red). Value-only; count/grid untouched. Gated default OFF."""
    if hero_key not in CATEGORY_REVEAL_HERO_KEYS:
        return None
    if os.environ.get("CATEGORY_REVEAL_ENABLE_PURE_PRIOR_RED_KEEP") != "1":
        return None
    if p50 is None or rv50 is None or rv50 <= 0:
        return None
    if not _is_pure_prior_red(evidence):
        return None
    keep = _aisha_pure_prior_red_keep(_snapshot_map_id(snapshot))
    q6_range = quality_count_ranges.get("q6")
    q6_count_mid = q6_range[1] if q6_range and len(q6_range) > 1 else None
    keep = _aisha_red_keep_evidence_ramp(q6_count_mid, keep)
    if keep >= 1.0:
        return None
    round_no = _snapshot_round_no(snapshot)
    non_red = max(0.0, float(p50) - float(rv50))
    round_tag = f"@r{int(round_no)}" if round_no is not None else ""
    _append_source_note_once(notes, f"category_reveal_pure_prior_red_keep={keep:g}{round_tag}")
    return non_red + float(rv50) * keep


def prepare_reference_engine_snapshot(snapshot: dict[str, Any]) -> dict[str, Any]:
    """Apply hero-specific live defaults without overriding explicit audit modes."""
    snapshot, _treasure_appraisal_wire_conflict = (
        _quarantine_malformed_treasure_appraisal_rows(snapshot)
    )
    # Keep raw owners for the scoped 5215 model and pending update606 routes.
    # Their public boundaries validate source identity before any projection.
    if (
        _wuqilin_5215_pending_scope_state(snapshot) is not None
        or _chenmei_zhenhai_pending_scope_state(snapshot) is not None
        or _update606_large_auction_pending_scope_state(snapshot) is not None
        or _update606_changed_route_scope_state(snapshot) is not None
    ):
        return snapshot
    snapshot = _stabilize_ahmed_current_action_publication(snapshot)
    snapshot = _with_ahmed_q1_q5_current_action_projection(snapshot)
    ahmed_q1_q5_context_targeted = (
        _ahmed_q1_q5_raw_context_guard_targeted(snapshot)
    )
    ahmed_q1_q5_raw_context_bound = (
        _ahmed_q1_q5_raw_context_binding_decision(snapshot)
        if ahmed_q1_q5_context_targeted
        else False
    )
    # Establish the Aisha 100107 target ledger before generic action-row
    # stabilization.  A malformed numeric alias must not reach an unrelated
    # consumer whose legacy coercion could invoke a user-defined protocol.
    snapshot = _aisha_q5_total_cells_fail_closed_snapshot(snapshot)
    hard_public_avg_value_enabled = (
        _run_env_get(HARD_QUALITY_AVG_VALUE_QUOTE_FLOOR_DISABLE) != "1"
    )
    hard_public_avg_value_decision = (
        _hard_public_avg_value_decision(snapshot)
        if hard_public_avg_value_enabled
        else _HardPublicAvgValueDecision(False, ())
    )
    total_avg_cells_authority_enabled = (
        _run_env_get(TOTAL_AVG_CELLS_GRID_OPTIONS_DISABLE) != "1"
    )
    prepared_total_avg_cells_authority = (
        _prepared_total_avg_cells_raw_authority(snapshot)
        if total_avg_cells_authority_enabled
        else None
    )
    total_avg_cells_authority = (
        prepared_total_avg_cells_authority
        if prepared_total_avg_cells_authority is not None
        else _strict_total_avg_cells_raw_authority(snapshot)
    )
    prepared_warehouse_quote_decision = (
        _prepared_warehouse_quote_provenance_decision(
            snapshot,
            map_id=4501,
        )
    )
    warehouse_quote_decision = (
        prepared_warehouse_quote_decision
        if prepared_warehouse_quote_decision is not None
        else _atomic_nonofficial_warehouse_quote_provenance(
            snapshot,
            map_id=4501,
        )
    )
    snapshot, raw_warehouse_source_status = (
        _stabilize_activity_and_warehouse_snapshot(snapshot)
    )
    action_stable_snapshot = _stabilize_q5_action_row_snapshot(snapshot)
    payload = _stabilize_aisha_public_avg_cell_snapshot(action_stable_snapshot)
    if payload is action_stable_snapshot:
        payload = dict(action_stable_snapshot)
    if (
        total_avg_cells_authority_enabled
        and total_avg_cells_authority.status in {"valid", "conflict"}
    ):
        payload[_TOTAL_AVG_CELLS_PREPARED_DECISION_KEY] = {
            "status": total_avg_cells_authority.status,
            "total_count": total_avg_cells_authority.total_count,
            "total_avg_cells": total_avg_cells_authority.total_avg_cells,
            "raw_binding": total_avg_cells_authority.raw_binding,
        }
        payload[_TOTAL_AVG_CELLS_PREPARED_MARKER_KEY] = (
            _total_avg_cells_prepared_marker(total_avg_cells_authority)
        )
    else:
        payload.pop(_TOTAL_AVG_CELLS_PREPARED_DECISION_KEY, None)
        payload.pop(_TOTAL_AVG_CELLS_PREPARED_MARKER_KEY, None)
    if hard_public_avg_value_enabled and hard_public_avg_value_decision.targeted:
        payload[_HARD_PUBLIC_AVG_VALUE_PREPARED_DECISION_KEY] = {
            "targeted": hard_public_avg_value_decision.targeted,
            "values": [
                [key, value]
                for key, value in hard_public_avg_value_decision.values
            ],
        }
        payload[_HARD_PUBLIC_AVG_VALUE_PREPARED_MARKER_KEY] = (
            _hard_public_avg_value_prepared_marker(
                hard_public_avg_value_decision
            )
        )
    else:
        payload.pop(_HARD_PUBLIC_AVG_VALUE_PREPARED_DECISION_KEY, None)
        payload.pop(_HARD_PUBLIC_AVG_VALUE_PREPARED_MARKER_KEY, None)
    if ahmed_q1_q5_context_targeted:
        payload[_AHMED_Q1_Q5_CONTEXT_PREPARED_DECISION_KEY] = (
            ahmed_q1_q5_raw_context_bound
        )
        payload[_AHMED_Q1_Q5_CONTEXT_PREPARED_MARKER_KEY] = (
            _ahmed_q1_q5_context_prepared_marker(
                ahmed_q1_q5_raw_context_bound
            )
        )
    else:
        payload.pop(_AHMED_Q1_Q5_CONTEXT_PREPARED_DECISION_KEY, None)
        payload.pop(_AHMED_Q1_Q5_CONTEXT_PREPARED_MARKER_KEY, None)
    hero = payload.get("hero")
    ui_contract = payload.get("ui_contract")
    if isinstance(ui_contract, dict):
        context = ui_contract.get("context")
        if isinstance(context, dict) and context.get("hero") not in (None, ""):
            hero = context.get("hero")
    hero_key = normalize_hero_key(str(hero or ""))
    if hero_key in {"ahmed", "gabriela"}:
        payload[_WAREHOUSE_QUOTE_PROVENANCE_PREPARED_DECISION_KEY] = {
            "legacy_qualification": warehouse_quote_decision.legacy_qualification,
            "gabriela_qualification": warehouse_quote_decision.gabriela_qualification,
        }
        payload[_WAREHOUSE_QUOTE_PROVENANCE_PREPARED_MARKER_KEY] = (
            _warehouse_quote_provenance_prepared_marker(
                warehouse_quote_decision,
            )
        )
    if hero_key == "ahmed":
        if raw_warehouse_source_status in {"unsafe", "invalid"}:
            payload = _drop_rejected_warehouse_quote_source_fields(payload)
        else:
            payload = _stabilize_nonofficial_warehouse_source_snapshot(payload)
    if hero_key in LAYOUT_DEPTH_HERO_KEYS:
        if payload.get("audit_aisha_layout_mode") in (None, ""):
            payload["audit_aisha_layout_mode"] = AISHA_LIVE_LAYOUT_MODE
    if hero_key == "aisha":
        if payload.get("audit_aisha_d1_mode") in (None, ""):
            payload["audit_aisha_d1_mode"] = AISHA_LIVE_D1_MODE
    return payload


def _apply_layout_depth_hints_from_snapshot(
    *,
    snapshot: dict[str, Any],
    hero: str,
    round_no: int | None,
    total_grid_target: float | None,
    source_notes: list[str],
    total_count: int | None = None,
) -> float | None:
    hero_key = normalize_hero_key(hero)
    if layout_depth_spec_for_hero(hero_key) is None:
        return total_grid_target
    items = _minimap_items_from_snapshot(snapshot)
    hard_total_locked = (
        _hard_total_grid_target_from_notes(total_grid_target, source_notes) is not None
    )
    return apply_layout_depth_hints(
        hero_key=hero_key,
        round_no=round_no,
        total_grid_target=total_grid_target,
        source_notes=source_notes,
        items=items,
        layout_mode=_aisha_layout_mode_from_snapshot(snapshot),
        hard_total_locked=hard_total_locked,
        total_count=total_count,
        # draw-hero no_reachable relax-retry: drop the sparse soft target so it stops over-constraining
        # the count-feasibility gate. Only sparse_early specs honor it (aisha=full/ahmed=None ignore).
        skip_early_viewport=bool(snapshot.get("_skip_sparse_early_soft_target")),
    )


def _append_aisha_layout_footroom_notes(
    *,
    source_notes: list[str],
    round_no: int,
    raw_hinted: float,
    capped_hinted: float,
    conservative_mult: float,
    balanced_mult: float,
    aggressive_mult: float,
    sparsity_boost: float,
) -> None:
    if raw_hinted > capped_hinted + 0.5:
        _append_source_note_once(source_notes, AISHA_LAYOUT_FOOTROOM_CAP_NOTE)
    if sparsity_boost >= 0.55:
        _append_source_note_once(source_notes, AISHA_LAYOUT_FOOTROOM_SPARSE_NOTE)
    _append_source_note_once(source_notes, AISHA_LAYOUT_GRID_HINT_NOTE)
    _append_source_note_once(source_notes, AISHA_LAYOUT_FOOTROOM_NOTE)
    _append_source_note_once(
        source_notes,
        f"{AISHA_LAYOUT_FOOTROOM_MULT_NOTE}:"
        f"{conservative_mult:g}/{balanced_mult:g}/{aggressive_mult:g}@r{int(round_no)}",
    )


def _aisha_layout_band_widen_delta(source_notes: Iterable[str]) -> int | None:
    for note in source_notes:
        text = str(note)
        if not text.startswith(f"{AISHA_LAYOUT_BAND_WIDEN_DELTA_NOTE}:"):
            continue
        try:
            return max(0, int(text.split(":", 1)[1]))
        except ValueError:
            return None
    return None


def _apply_aisha_layout_band_widen_to_range(
    grid_range: tuple[int | None, int | None, int | None],
    source_notes: list[str],
) -> tuple[int | None, int | None, int | None]:
    return apply_layout_band_widen_to_range(grid_range, source_notes)


def _aisha_layout_effective_deepest_row(
    items: list[dict[str, Any]],
    *,
    round_no: int,
    columns: int = AISHA_GRID_COLUMNS,
) -> int | None:
    deepest = _deepest_minimap_bottom_row(items, columns=columns)
    if deepest is None:
        return None
    if int(round_no) >= 4:
        return deepest
    low_bottoms: list[int] = []
    high_bottoms: list[int] = []
    for item in items:
        quality = _safe_int(item.get("quality"))
        bottom = _item_bottom_row(item, columns=columns)
        if bottom is None or quality is None:
            continue
        if int(quality) <= 1:
            low_bottoms.append(int(bottom))
        elif int(quality) >= 3:
            high_bottoms.append(int(bottom))
    if not low_bottoms or not high_bottoms:
        return deepest
    low_ref = max(low_bottoms)
    high_ref = max(high_bottoms)
    blended = int(round(0.35 * low_ref + 0.65 * high_ref))
    return max(AISHA_LAYOUT_DEEPEST_ROW_THRESHOLD, min(deepest, blended))


def _apply_aisha_early_round_viewport_hint(
    *,
    snapshot: dict[str, Any],
    hero: str,
    round_no: int | None,
    total_grid_target: float | None,
    source_notes: list[str],
) -> float | None:
    """R1–R2 viewport cue from white/green minimap; soft floor only, no R3+ point target."""
    if normalize_hero_key(hero) != "aisha":
        return total_grid_target
    if round_no is None or int(round_no) >= AISHA_LAYOUT_MIN_ROUND:
        return total_grid_target
    if _hard_total_grid_target_from_notes(total_grid_target, source_notes) is not None:
        return total_grid_target

    items = _minimap_items_from_snapshot(snapshot)
    if not items:
        return total_grid_target
    known_cells = _known_minimap_cells(items)
    if known_cells <= 0:
        return total_grid_target
    deepest = _aisha_layout_effective_deepest_row(items, round_no=int(round_no))
    if deepest is None or deepest < AISHA_LAYOUT_DEEPEST_ROW_THRESHOLD:
        return total_grid_target

    rows_below = max(0, AISHA_WAREHOUSE_ROWS - int(deepest))
    fill_ratio = _aisha_layout_viewport_fill_ratio(
        known_cells=known_cells,
        deepest=int(deepest),
        columns=AISHA_GRID_COLUMNS,
    )
    sparsity_boost = _aisha_layout_sparse_footroom_boost(fill_ratio)
    # R1 white-only scans leave more unknown below; R2 green skill tightens slightly.
    footroom_mult = 1.45 if int(round_no) <= 1 else 1.20
    footroom = rows_below * AISHA_GRID_COLUMNS * footroom_mult * sparsity_boost
    hinted = float(known_cells + footroom)
    max_quality = _max_minimap_quality(items)
    _append_source_note_once(source_notes, AISHA_EARLY_VIEWPORT_GRID_HINT_NOTE)

    # Product: R1 avoids pinning a point estimate when only white is visible.
    if int(round_no) <= 1 and max_quality is not None and max_quality <= 1:
        _append_source_note_once(
            source_notes,
            f"aisha_early_viewport_band_low:{int(round(hinted))}",
        )
        return total_grid_target

    if total_grid_target is not None and hinted <= float(total_grid_target) + 0.5:
        return total_grid_target
    if total_grid_target is None:
        capped = min(hinted, float(known_cells) + 52.0)
        rounded = float(int(round(capped)))
        _append_source_note_once(
            source_notes,
            f"aisha_early_viewport_soft_target:{int(round(rounded))}",
        )
        return rounded
    return total_grid_target


def _apply_aisha_layout_grid_hint(
    *,
    snapshot: dict[str, Any],
    hero: str,
    round_no: int | None,
    total_grid_target: float | None,
    source_notes: list[str],
) -> float | None:
    """R3+ shadow: layout footroom hint with target / shadow / band application modes."""
    if normalize_hero_key(hero) != "aisha":
        return total_grid_target
    mode = _aisha_layout_mode_from_snapshot(snapshot)
    if mode == "off":
        return total_grid_target
    if round_no is None or int(round_no) < AISHA_LAYOUT_MIN_ROUND:
        return total_grid_target
    if _hard_total_grid_target_from_notes(total_grid_target, source_notes) is not None:
        return total_grid_target

    items = _minimap_items_from_snapshot(snapshot)
    if not items:
        return total_grid_target

    max_quality = _max_minimap_quality(items)
    if max_quality is not None and max_quality <= 1 and int(round_no) <= AISHA_LAYOUT_WHITE_ONLY_MAX_ROUND:
        return total_grid_target

    deepest = _aisha_layout_effective_deepest_row(items, round_no=int(round_no))
    if deepest is None or deepest < AISHA_LAYOUT_DEEPEST_ROW_THRESHOLD:
        return total_grid_target

    known_cells = _known_minimap_cells(items)
    rows_below = max(0, AISHA_WAREHOUSE_ROWS - int(deepest))
    if not _aisha_layout_target_looks_undershot(
        total_grid_target=total_grid_target,
        known_cells=known_cells,
        rows_below=rows_below,
        columns=AISHA_GRID_COLUMNS,
        round_no=int(round_no),
    ):
        _append_source_note_once(source_notes, AISHA_LAYOUT_FOOTROOM_SKIP_NOTE)
        return total_grid_target

    fill_ratio = _aisha_layout_viewport_fill_ratio(
        known_cells=known_cells,
        deepest=int(deepest),
        columns=AISHA_GRID_COLUMNS,
    )
    sparsity_boost = _aisha_layout_sparse_footroom_boost(fill_ratio)
    base_footroom = rows_below * AISHA_GRID_COLUMNS
    conservative_mult, balanced_mult, aggressive_mult = _aisha_layout_footroom_multipliers(
        int(round_no)
    )
    footroom = base_footroom * balanced_mult * sparsity_boost
    raw_hinted = float(known_cells + footroom)
    baseline = float(total_grid_target if total_grid_target is not None else known_cells)
    raise_cap = _aisha_layout_footroom_raise_cap(int(round_no))
    capped_hinted = min(raw_hinted, baseline + float(raise_cap))
    hinted = capped_hinted
    if hinted <= baseline + 0.5:
        return total_grid_target

    _append_aisha_layout_footroom_notes(
        source_notes=source_notes,
        round_no=int(round_no),
        raw_hinted=raw_hinted,
        capped_hinted=capped_hinted,
        conservative_mult=conservative_mult,
        balanced_mult=balanced_mult,
        aggressive_mult=aggressive_mult,
        sparsity_boost=sparsity_boost,
    )
    _append_source_note_once(
        source_notes,
        f"{AISHA_LAYOUT_APPLICATION_MODE_NOTE}:{mode}",
    )
    delta = int(round(hinted - baseline))
    if mode == "shadow":
        return total_grid_target
    if mode == "band":
        _append_source_note_once(
            source_notes,
            f"{AISHA_LAYOUT_BAND_WIDEN_DELTA_NOTE}:{delta}",
        )
        return total_grid_target
    if total_grid_target is not None:
        _append_source_note_once(
            source_notes,
            f"total_grid_target_raised:{int(round(float(total_grid_target)))}->{int(round(hinted))}",
        )
    return hinted


def _filter_avg_value_candidates_by_session(
    key: str,
    candidates: list[int],
    *,
    total_count: int,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    count_sums: dict[str, int],
) -> list[int]:
    if not candidates:
        return []
    feasible: list[int] = []
    for count in candidates:
        trial = {quality: int(fixed_counts.get(quality, 0) or 0) for quality in QUALITY_KEYS}
        trial[key] = int(count)
        q4q5 = count_sums.get("q4q5")
        if q4q5 is not None and trial["q4"] + trial["q5"] != int(q4q5):
            continue
        q4q5q6 = count_sums.get("q4q5q6")
        if q4q5q6 is not None:
            if key == "q5" and "q6" not in fixed_counts:
                trial["q6"] = int(q4q5q6) - trial["q4"] - trial["q5"]
            if trial["q4"] + trial["q5"] + trial["q6"] != int(q4q5q6):
                continue
            if trial["q6"] < max(0, int(min_counts.get("q6", 0) or 0)):
                continue
        other_fixed = sum(
            int(fixed_counts.get(quality, 0) or 0)
            for quality in QUALITY_KEYS
            if quality != key
        )
        other_min = sum(
            max(0, int(min_counts.get(quality, 0) or 0))
            for quality in QUALITY_KEYS
            if quality != key and quality not in fixed_counts
        )
        if int(count) + other_fixed > int(total_count):
            continue
        if int(count) + other_fixed + other_min > int(total_count):
            continue
        feasible.append(int(count))
    return feasible


def _apply_avg_value_only_q5_count_derivation(
    *,
    total_count: int | None,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    count_sums: dict[str, int],
    avg_values: dict[str, float],
    avg_cells: dict[str, float],
    quality_cells: dict[str, float],
    source_notes: list[str],
) -> None:
    """Lock a unique q5 count implied by the public average's reduced denominator.

    This arithmetic constraint is independent of catalog identity: a non-catalog average must not
    invent an item/multiset match, but its exact fractional denominator still constrains the count
    because the tier total is an integer. The later q5 catalog projection may therefore fail open on
    identity/cells without discarding a unique count already proved by the integer product.
    """
    if total_count is None or int(total_count) <= 0:
        return
    if fixed_counts.get("q5") is not None:
        return
    if quality_cells.get("q5") not in (None, ""):
        return
    if avg_cells.get("q5") not in (None, ""):
        return
    avg = avg_values.get("q5")
    if not _avg_value_has_positive_signal(avg):
        return
    minimum = max(0, int(min_counts.get("q5", 0) or 0))
    candidates = [
        count
        for count in range(max(1, minimum), int(total_count) + 1)
        if _avg_value_count_matches_for_public_evidence(
            "q5", count, avg, source_notes
        )
    ]
    candidates = _filter_avg_value_candidates_by_session(
        "q5",
        candidates,
        total_count=int(total_count),
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        count_sums=count_sums,
    )
    if len(candidates) != 1:
        return
    fixed_counts["q5"] = candidates[0]
    min_counts["q5"] = max(min_counts.get("q5", 0), candidates[0])
    _append_source_note_once(source_notes, "avg_value_only_q5_count_derived")


def _apply_public_avg_value_integer_product_min_counts(
    *,
    soft_avg_value_keys: frozenset[str],
    avg_values: dict[str, float],
    min_counts: dict[str, int],
    quality_count_cells_options: dict[str, tuple[tuple[int, int], ...]],
    source_notes: list[str],
) -> None:
    """One-decimal .5 display avg (e.g. 33895.5): gold totals are integer → count must be even."""
    for key in soft_avg_value_keys:
        avg = avg_values.get(key)
        if not _avg_value_has_positive_signal(avg):
            continue
        if key in {"q4", "q5", "q6"} and _catalog_value_joint_projection_enabled(
            key
        ):
            supported_counts = {
                int(count)
                for count, _cells in quality_count_cells_options.get(key, ())
            }
            if supported_counts:
                minimum = min(supported_counts)
                if minimum > int(min_counts.get(key, 0) or 0):
                    min_counts[key] = minimum
                    _append_source_note_once(
                        source_notes,
                        f"public_{key}_avg_value_catalog_joint_min:{minimum}",
                    )
            continue
        normalized = _ref_normalize_avg_value_wire(avg)
        if normalized is None:
            continue
        rounded_one = round(normalized, 1)
        if abs(normalized - rounded_one) > 1e-9:
            continue
        if abs((normalized * 10.0) - round(normalized * 10.0)) > 1e-9:
            continue
        if int(round(normalized * 10.0)) % 10 != 5:
            continue
        if 2 > int(min_counts.get(key, 0) or 0):
            min_counts[key] = 2
            _append_source_note_once(
                source_notes,
                f"public_{key}_avg_value_integer_product_min:2",
            )


def _apply_exact_count_residuals(
    *,
    total_count: int | None,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    count_sums: dict[str, int],
    avg_values: dict[str, float],
    quality_values: dict[str, float],
    quality_cells: dict[str, float],
    split_counts: dict[str, int],
    source_notes: list[str],
) -> None:
    def set_residual_count(
        key: str,
        residual: int,
        note: str,
        hard_conflict_note: str,
    ) -> bool:
        minimum = max(0, int(min_counts.get(key, 0)))
        if key == "q1":
            minimum = max(
                minimum,
                sum(
                    int(split_counts[split_key])
                    for split_key in LOW_SPLIT_KEYS
                    if split_counts.get(split_key) is not None
                ),
            )
        exact_cells_raw = quality_cells.get(key)
        exact_cells = None
        if exact_cells_raw is not None:
            exact_cells = int(round(float(exact_cells_raw)))
        if (
            residual < minimum
            or not _quality_count_matches_value_inputs(
                int(residual),
                None
                if _public_avg_value_soft_pending(
                    key,
                    source_notes=source_notes,
                    fixed_counts=fixed_counts,
                    quality_values=quality_values,
                    avg_values=avg_values,
                )
                else avg_values.get(key),
                _safe_float(quality_values.get(key)),
            )
            or (
                exact_cells is not None
                and not _can_compose_grid_total_with_q6_catalog(
                    key, int(residual), exact_cells
                )
            )
        ):
            _append_source_note_once(source_notes, f"{note}_conflict")
            _append_source_note_once(source_notes, f"hard_conflict:{hard_conflict_note}")
            return False
        fixed_counts[key] = int(residual)
        min_counts[key] = max(min_counts.get(key, 0), int(residual))
        _append_source_note_once(source_notes, note)
        return True

    for _ in range(len(QUALITY_KEYS)):
        changed = False
        for group_key, group_keys in (
            ("q4q5", ("q4", "q5")),
            ("q4q5q6", ("q4", "q5", "q6")),
        ):
            group_total = count_sums.get(group_key)
            if group_total is None:
                continue
            missing = [key for key in group_keys if fixed_counts.get(key) is None]
            known_total = sum(int(fixed_counts[key]) for key in group_keys if key not in missing)
            if len(missing) == 0:
                if known_total != int(group_total):
                    _append_source_note_once(source_notes, f"count_sum_{group_key}_conflict")
                    _append_source_note_once(source_notes, f"hard_conflict:count_sum_{group_key}")
                continue
            if len(missing) != 1:
                continue
            missing_key = missing[0]
            residual = int(group_total) - known_total
            changed = (
                set_residual_count(
                    missing_key,
                    residual,
                    f"count_sum_{group_key}_{missing_key}_count_from_residual",
                    f"count_sum_{group_key}_{missing_key}_count_residual",
                )
                or changed
            )

        if total_count is not None:
            missing = [key for key in QUALITY_KEYS if fixed_counts.get(key) is None]
            known_total = sum(
                int(fixed_counts[key]) for key in QUALITY_KEYS if key not in missing
            )
            if len(missing) == 0:
                if known_total != int(total_count):
                    _append_source_note_once(source_notes, "quality_count_total_count_conflict")
                    _append_source_note_once(source_notes, "hard_conflict:quality_count_total_count")
            elif len(missing) == 1:
                missing_key = missing[0]
                residual = int(total_count) - known_total
                changed = (
                    set_residual_count(
                        missing_key,
                        residual,
                        f"quality_count_{missing_key}_from_total_count_residual",
                        f"quality_count_{missing_key}_total_count_residual",
                    )
                    or changed
                )
        if not changed:
            break


def _apply_quality_cells_total_grid_residual(
    *,
    total_grid_target: float | None,
    fixed_counts: dict[str, int],
    avg_cells: dict[str, float],
    quality_cells: dict[str, float],
    source_notes: list[str],
) -> None:
    target = _hard_total_grid_target_from_notes(total_grid_target, source_notes)
    if target is None:
        return
    missing: list[str] = []
    known_cells: dict[str, int] = {}
    for key in QUALITY_KEYS:
        raw = quality_cells.get(key)
        if raw is None:
            missing.append(key)
            continue
        rounded = int(round(float(raw)))
        if abs(float(raw) - rounded) > 0.0001:
            return
        known_cells[key] = rounded
    if not missing:
        if sum(known_cells.values()) != target:
            _append_source_note_once(source_notes, "quality_cells_total_grid_conflict")
            _append_source_note_once(source_notes, "hard_conflict:quality_cells_total_grid")
        return
    if len(missing) != 1:
        return
    missing_key = missing[0]
    residual = target - sum(known_cells.values())
    note = f"quality_cells_{missing_key}_from_total_grid_residual"
    hard_conflict_note = f"quality_cells_{missing_key}_total_grid_residual"
    count = fixed_counts.get(missing_key)
    if residual < 0:
        _append_source_note_once(source_notes, f"{note}_conflict")
        _append_source_note_once(source_notes, f"hard_conflict:{hard_conflict_note}")
        return
    if count is not None:
        count_int = int(count)
        if not _can_compose_grid_total_with_q6_catalog(missing_key, count_int, residual):
            _append_source_note_once(source_notes, f"{note}_conflict")
            _append_source_note_once(source_notes, f"hard_conflict:{hard_conflict_note}")
            return
        avg = avg_cells.get(missing_key)
        if not _avg_matches_exact_grid(count_int, avg, residual):
            _append_source_note_once(source_notes, f"{note}_avg_conflict")
            _append_source_note_once(source_notes, f"hard_conflict:{hard_conflict_note}")
            return
    quality_cells[missing_key] = float(residual)
    _append_source_note_once(source_notes, note)


def _apply_avg_value_cells_exact_count_intersection(
    *,
    total_count: int | None,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    avg_cells: dict[str, float],
    avg_values: dict[str, float],
    quality_cells: dict[str, float],
    quality_values: dict[str, float],
    split_counts: dict[str, int],
    source_notes: list[str],
) -> None:
    if total_count is None or total_count <= 0:
        return
    for key in QUALITY_KEYS:
        # High tiers must also prove that the implied price/count/cells tuple is reachable in the
        # dynamic catalog. Their unified projections run later, after correlated item facts exist.
        # The coarse arithmetic-only lock remains available solely on each projection rollback arm.
        if key in {"q4", "q5", "q6"} and _catalog_value_joint_projection_enabled(
            key
        ):
            continue
        if (
            fixed_counts.get(key) is not None
            or key in quality_cells
            or key in quality_values
            or key not in avg_cells
            or key not in avg_values
        ):
            continue
        avg_cell = avg_cells.get(key)
        avg_value = avg_values.get(key)
        if (
            avg_cell is None
            or avg_cell <= 0
            or not _avg_value_has_positive_signal(avg_value)
        ):
            continue
        minimum = max(1, int(min_counts.get(key, 0)))
        if key == "q1":
            minimum = max(
                minimum,
                sum(
                    int(split_counts[split_key])
                    for split_key in LOW_SPLIT_KEYS
                    if split_counts.get(split_key) is not None
                ),
            )
        candidates = [
            count
            for count in range(minimum, int(total_count) + 1)
            if _avg_value_count_matches_for_public_evidence(
                key, count, avg_value, source_notes
            )
            and _avg_grid_options(count, avg_cell, key)
        ]
        if len(candidates) != 1:
            continue
        fixed_counts[key] = candidates[0]
        min_counts[key] = max(min_counts.get(key, 0), candidates[0])
        _append_source_note_once(
            source_notes,
            f"avg_value_cells_{key}_count_derived",
        )


def _parse_ranges(text: Any) -> tuple[float | None, float | None, float | None]:
    parts = [p.strip() for p in str(text or "").split("/") if p.strip()]
    parsed = [_safe_float(part) for part in parts[:3]]
    while len(parsed) < 3:
        parsed.append(None)
    return (parsed[0], parsed[1], parsed[2])


def _quality_key(value: Any) -> str | None:
    text = str(value or "").strip().lower()
    if not text:
        return None
    if text in QUALITY_KEYS:
        return text
    if text.startswith("q") and text[1:] in QUALITY_NUM_TO_KEY:
        return QUALITY_NUM_TO_KEY[text[1:]]
    if text in QUALITY_NUM_TO_KEY:
        return QUALITY_NUM_TO_KEY[text]
    match = re.search(r"(?:bucket|quality)[._/-]?q?(?P<q>[1-6])", text)
    if match:
        return QUALITY_NUM_TO_KEY.get(match.group("q"))
    return None


def _quality_number_to_key(value: Any) -> str | None:
    parsed = _safe_int(value)
    if parsed is None:
        return _quality_key(value)
    return QUALITY_NUM_TO_KEY.get(str(parsed))


def _low_split_key(value: Any) -> str | None:
    text = str(value or "").strip().lower()
    if not text:
        return None
    return LOW_SPLIT_ALIASES.get(text)


def _iter_dicts(value: Any) -> Iterable[dict[str, Any]]:
    if isinstance(value, dict):
        yield value
        return
    if isinstance(value, (list, tuple)):
        for row in value:
            if isinstance(row, dict):
                yield row


def _total_avg_cells_semantic_alias(value: object) -> str | None:
    """Project a targeted semantic without invoking subclass protocols."""

    expected = ("total_item_count", "total_avg_cells")
    if type(value) is str:  # noqa: E721 - exact wire strings only
        return value if value in expected else None
    if isinstance(value, str):
        for semantic in expected:
            if str.__eq__(value, semantic) is True:
                return semantic
    return None


def _total_avg_cells_row_semantic(row: object) -> tuple[str | None, bool]:
    """Resolve one total-count/mean row without allowing alias fallback."""
    expected = {
        "total_item_count": (TOTAL_ITEM_COUNT_INFO_ID, "count"),
        "total_avg_cells": (TOTAL_AVG_CELLS_INFO_ID, "avg_cells"),
    }
    if type(row) is dict:  # noqa: E721 - exact wire container only
        if not _has_exact_bounded_json_keys(row):
            return None, False
        info_present = "info_id" in row
        semantic_present = "semantic" in row
        info_id = row.get("info_id")
        semantic = row.get("semantic")
    elif isinstance(row, dict):
        # A dict subclass is never an admissible wire row, but its builtin
        # storage can still claim this contract.  Inspect that storage without
        # invoking overridden mapping protocols so a targeted subclass cannot
        # disappear beside an otherwise valid sibling.
        info_present = dict.__contains__(row, "info_id")
        semantic_present = dict.__contains__(row, "semantic")
        info_id = dict.get(row, "info_id")
        semantic = dict.get(row, "semantic")
        targeted = (
            _total_avg_cells_info_alias(info_id) is not None
            or _total_avg_cells_semantic_alias(semantic) is not None
        )
        return None, targeted
    else:
        return None, False

    if _public_avg_value_row_domain_owner(row) == "issue25":
        # An exact q4/q5 owner makes foreign whole-warehouse aliases part of
        # that row's issue25 transaction. They must not poison the independent
        # issue26 ledger.
        return None, False

    candidates: set[str] = set()
    if type(info_id) is int:  # noqa: E721 - bool/subclasses are not wire ints
        for name, (expected_id, _) in expected.items():
            if info_id == expected_id:
                candidates.add(name)
    elif info_present:
        claimed = _total_avg_cells_info_alias(info_id)
        if claimed is not None:
            candidates.add(claimed)
            return None, True
    semantic_claim = _total_avg_cells_semantic_alias(semantic)
    if semantic_claim is not None:
        candidates.add(semantic_claim)
        if type(semantic) is not str:  # noqa: E721 - claimed wrong wire type
            return None, True
    elif semantic_present and type(semantic) is not str:  # noqa: E721
        # A malformed semantic is relevant only if the exact info_id identifies
        # one of our rows; unrelated public facts remain outside this contract.
        if candidates:
            return None, True
    if not candidates:
        return None, False
    if len(candidates) != 1:
        return None, True

    resolved = next(iter(candidates))
    expected_id, expected_kind = expected[resolved]
    if info_present and (type(info_id) is not int or info_id != expected_id):  # noqa: E721
        return None, True
    if semantic_present and (
        type(semantic) is not str or semantic != resolved  # noqa: E721
    ):
        return None, True
    if "kind" in row:
        kind = row.get("kind")
        if type(kind) is not str or kind != expected_kind:  # noqa: E721
            return None, True
    return resolved, False


def _total_avg_cells_info_alias(value: object) -> str | None:
    """Return the targeted semantic for exact or numeric-equal wire aliases."""

    by_id = {
        TOTAL_ITEM_COUNT_INFO_ID: "total_item_count",
        TOTAL_AVG_CELLS_INFO_ID: "total_avg_cells",
    }
    if type(value) is int:  # noqa: E721
        return by_id.get(value)
    if type(value) is float:  # noqa: E721
        if not math.isfinite(value) or not value.is_integer():
            return None
        return by_id.get(int(value))
    if type(value) is str:  # noqa: E721
        text = value.strip()
        return {
            str(TOTAL_ITEM_COUNT_INFO_ID): "total_item_count",
            str(TOTAL_AVG_CELLS_INFO_ID): "total_avg_cells",
        }.get(text)
    # Protocol-bearing scalar subclasses are not legal wire types, but their
    # builtin payload can still claim this authority domain.  Call the builtin
    # implementation directly so an override cannot make the claim disappear
    # or run code at the classifier boundary.
    if isinstance(value, int) and type(value) is not bool:  # noqa: E721
        for info_id, semantic in by_id.items():
            if int.__eq__(value, info_id) is True:
                return semantic
    if isinstance(value, float):
        for info_id, semantic in by_id.items():
            if float.__eq__(value, float(info_id)) is True:
                return semantic
    if isinstance(value, str):
        text = str.strip(value)
        return {
            str(TOTAL_ITEM_COUNT_INFO_ID): "total_item_count",
            str(TOTAL_AVG_CELLS_INFO_ID): "total_avg_cells",
        }.get(text)
    return None


def _total_avg_cells_rows_container(
    value: object,
) -> tuple[tuple[object, ...], bool]:
    """Read a row container and flag protocol-bearing targeted subclasses."""

    if type(value) is dict:  # noqa: E721
        return (value,), False
    if type(value) is list:  # noqa: E721
        return tuple(value), False
    if type(value) is tuple:  # noqa: E721
        return tuple(value), False
    if isinstance(value, dict):
        rows = (value,)
    elif isinstance(value, list):
        rows = tuple(list.__iter__(value))
    elif isinstance(value, tuple):
        rows = tuple(tuple.__iter__(value))
    else:
        return (), False
    targeted = any(
        semantic is not None or invalid
        for semantic, invalid in (
            _total_avg_cells_row_semantic(row) for row in rows
        )
    )
    return rows, targeted


def _strict_total_avg_cells_count(value: object) -> int | None:
    if type(value) is int:  # noqa: E721 - exact JSON number only
        return value if value > 0 else None
    if type(value) is not float or not math.isfinite(value) or not value.is_integer():  # noqa: E721
        return None
    return int(value) if value > 0 else None


def _strict_total_avg_cells_mean(value: object) -> float | None:
    if type(value) not in (int, float):  # noqa: E721 - bool/subclasses excluded
        return None
    try:
        parsed = float(value)
    except (OverflowError, TypeError, ValueError):
        return None
    return parsed if math.isfinite(parsed) and parsed > 0 else None


def _total_avg_cells_ahmed_packet_scope(
    snapshot: dict[str, Any],
) -> str:
    """Resolve the narrow hero scope without invoking scalar subclasses."""

    ui_contract = dict.get(snapshot, "ui_contract")
    context = (
        dict.get(ui_contract, "context")
        if type(ui_contract) is dict  # noqa: E721
        else None
    )
    sources = (snapshot, context) if type(context) is dict else (snapshot,)  # noqa: E721
    heroes: set[str] = set()
    for source in sources:
        if not dict.__contains__(source, "hero"):
            continue
        value = dict.get(source, "hero")
        if type(value) is not str or not value.strip():  # noqa: E721
            return "conflict"
        heroes.add(normalize_hero_key(value))
    if not heroes:
        return "other"
    if len(heroes) != 1:
        return "conflict"
    return "valid" if heroes == {"ahmed"} else "other"


def _strict_total_avg_cells_packet_count_mirrors(
    snapshot: dict[str, Any],
    total_count: int,
) -> bool:
    structured = dict.get(snapshot, "structured_ref_inputs")
    if type(structured) is not dict:  # noqa: E721
        return False
    structured_counts: set[int] = set()
    for key in (
        "total_count",
        "total_item_count",
        "session_total_count",
        "session_total_item_count",
    ):
        if not dict.__contains__(structured, key):
            continue
        value = dict.get(structured, key)
        parsed = _strict_total_avg_cells_count(value)
        if parsed is None or type(value) is not int:  # noqa: E721
            return False
        structured_counts.add(parsed)
    if structured_counts != {total_count}:
        return False

    for key in ("total_count", "total_item_count"):
        if not dict.__contains__(snapshot, key):
            continue
        value = dict.get(snapshot, key)
        if type(value) is not int or value != total_count:  # noqa: E721
            return False

    ui_contract = dict.get(snapshot, "ui_contract")
    if type(ui_contract) is not dict:  # noqa: E721
        return False
    constraints = dict.get(ui_contract, "constraints")
    baseline = dict.get(ui_contract, "baseline")
    if type(constraints) is not dict or type(baseline) is not dict:  # noqa: E721
        return False
    summary = dict.get(constraints, "summary")
    counts = dict.get(constraints, "counts")
    posterior = dict.get(baseline, "posterior")
    if (
        type(summary) is not dict  # noqa: E721
        or type(counts) is not dict  # noqa: E721
        or type(posterior) is not dict  # noqa: E721
    ):
        return False
    for container in (summary, counts, posterior):
        value = dict.get(container, "input_total_item_count")
        if type(value) is not int or value != total_count:  # noqa: E721
            return False
    status = dict.get(posterior, "total_item_count_status")
    return type(status) is str and status == "exact_input_constraint"  # noqa: E721


def _strict_total_avg_cells_packet_count_authority(
    snapshot: dict[str, Any],
) -> _TotalAvgCellsPacketCountAuthority:
    if _run_env_get(TOTAL_AVG_PACKET_COUNT_BRIDGE_DISABLE) == "1":
        return _TotalAvgCellsPacketCountAuthority("absent")
    constraints_present = dict.__contains__(
        snapshot,
        "inference_input_constraints",
    )
    if not constraints_present:
        return _TotalAvgCellsPacketCountAuthority("absent")
    constraints = dict.get(snapshot, "inference_input_constraints")
    if type(constraints) is not dict:  # noqa: E721
        return _TotalAvgCellsPacketCountAuthority("absent")
    if not dict.__contains__(constraints, "total_item_count"):
        return _TotalAvgCellsPacketCountAuthority("absent")
    count_row = dict.get(constraints, "total_item_count")
    if type(count_row) is not dict:  # noqa: E721
        # Legacy snapshots may carry a scalar total-count mirror while the
        # complete 200014+200017 public ledger remains authoritative.  Only a
        # producer-shaped packet envelope opts into this bridge.
        return _TotalAvgCellsPacketCountAuthority("absent")
    scope = _total_avg_cells_ahmed_packet_scope(snapshot)
    if scope == "other":
        return _TotalAvgCellsPacketCountAuthority("absent")
    if scope != "valid":
        return _TotalAvgCellsPacketCountAuthority("conflict")
    if (
        type(dict.get(constraints, "mode")) is not str  # noqa: E721
        or dict.get(constraints, "mode")
        != "pre_settlement_trusted_totals"
    ):
        return _TotalAvgCellsPacketCountAuthority("conflict")
    value = dict.get(count_row, "value")
    count = _strict_total_avg_cells_count(value)
    if (
        count is None
        or count > 512
        or type(value) is not int  # noqa: E721
        or type(dict.get(count_row, "source")) is not str  # noqa: E721
        or dict.get(count_row, "source") != "packet"
        or type(dict.get(count_row, "confidence")) is not str  # noqa: E721
        or dict.get(count_row, "confidence") != "exact"
        or type(dict.get(count_row, "sequence")) is not int  # noqa: E721
        or dict.get(count_row, "sequence") < 0
        or not _strict_total_avg_cells_packet_count_mirrors(
            snapshot,
            count,
        )
    ):
        return _TotalAvgCellsPacketCountAuthority("conflict")
    return _TotalAvgCellsPacketCountAuthority("valid", count)


def _total_avg_cells_context_container_invalid(
    snapshot: dict[str, Any],
) -> bool:
    """Keep a present malformed context from becoming an absent fallback."""

    ui_contract = dict.get(snapshot, "ui_contract")
    if type(ui_contract) is not dict:  # noqa: E721 - outer scope is separate
        return False
    if not dict.__contains__(ui_contract, "context"):
        return False
    return type(dict.get(ui_contract, "context")) is not dict  # noqa: E721


def _total_avg_cells_current_anchor(
    snapshot: dict[str, Any],
    field: str,
) -> object | None:
    ui_contract = dict.get(snapshot, "ui_contract")
    raw_context = (
        dict.get(ui_contract, "context")
        if type(ui_contract) is dict  # noqa: E721
        else None
    )
    context = raw_context if isinstance(raw_context, dict) else {}
    context_present = dict.__contains__(context, field)
    root_present = dict.__contains__(snapshot, field)
    context_value = dict.get(context, field)
    root_value = dict.get(snapshot, field)
    if context_present and root_present:
        if (
            not _total_avg_cells_identity_valid(context_value)
            or not _total_avg_cells_identity_valid(root_value)
            or type(context_value) is not type(root_value)  # noqa: E721
            or context_value != root_value
        ):
            return _TOTAL_AVG_CELLS_IDENTITY_CONFLICT
        return context_value
    if context_present:
        return context_value
    return root_value if root_present else None


def _total_avg_cells_identity_sources(
    snapshot: dict[str, Any],
    field: str,
) -> tuple[tuple[bool, object | None], tuple[bool, object | None]]:
    ui_contract = dict.get(snapshot, "ui_contract")
    raw_context = (
        dict.get(ui_contract, "context")
        if type(ui_contract) is dict  # noqa: E721
        else None
    )
    context = raw_context if isinstance(raw_context, dict) else {}
    return (
        (
            dict.__contains__(snapshot, field),
            dict.get(snapshot, field),
        ),
        (
            dict.__contains__(context, field),
            dict.get(context, field),
        ),
    )


def _total_avg_cells_identity_valid(value: object) -> bool:
    if type(value) is str:  # noqa: E721 - exact builtin identity only
        return bool(value.strip())
    return type(value) is int  # noqa: E721 - bool/subclasses are invalid


def _total_avg_cells_current_scope_invalid(
    snapshot: dict[str, Any],
) -> bool:
    if _total_avg_cells_context_container_invalid(snapshot):
        return True
    for identity_field in ("session_id", "session_epoch", "epoch"):
        root_source, context_source = _total_avg_cells_identity_sources(
            snapshot,
            identity_field,
        )
        for present, value in (root_source, context_source):
            if present and not _total_avg_cells_identity_valid(value):
                return True
        if root_source[0] and context_source[0] and (
            type(root_source[1]) is not type(context_source[1])  # noqa: E721
            or root_source[1] != context_source[1]
        ):
            return True
    return False


def _total_avg_cells_binding_atom(value: object) -> tuple[str, str]:
    """Project one raw scalar without invoking conversion protocols."""

    if value is None:
        return "none", ""
    if type(value) is bool:  # noqa: E721
        return "bool", "1" if value else "0"
    if type(value) is int:  # noqa: E721
        return "int", str(value)
    if type(value) is float:  # noqa: E721
        return "float", value.hex() if math.isfinite(value) else repr(value)
    if type(value) is str:  # noqa: E721
        return "str", value
    return "invalid", ""


def _total_avg_cells_packet_count_binding(
    snapshot: dict[str, Any],
) -> list[object]:
    """Bind the exact packet count and every mirror used to authorize it."""

    constraints_present = dict.__contains__(
        snapshot,
        "inference_input_constraints",
    )
    constraints = dict.get(snapshot, "inference_input_constraints")
    count_row = (
        dict.get(constraints, "total_item_count")
        if type(constraints) is dict  # noqa: E721
        else None
    )
    structured_present = dict.__contains__(snapshot, "structured_ref_inputs")
    structured = dict.get(snapshot, "structured_ref_inputs")
    ui_contract = dict.get(snapshot, "ui_contract")
    raw_constraints = (
        dict.get(ui_contract, "constraints")
        if type(ui_contract) is dict  # noqa: E721
        else None
    )
    baseline = (
        dict.get(ui_contract, "baseline")
        if type(ui_contract) is dict  # noqa: E721
        else None
    )
    summary = (
        dict.get(raw_constraints, "summary")
        if type(raw_constraints) is dict  # noqa: E721
        else None
    )
    counts = (
        dict.get(raw_constraints, "counts")
        if type(raw_constraints) is dict  # noqa: E721
        else None
    )
    posterior = (
        dict.get(baseline, "posterior")
        if type(baseline) is dict  # noqa: E721
        else None
    )

    def field(container: object, key: str) -> list[object]:
        present = type(container) is dict and dict.__contains__(container, key)  # noqa: E721
        value = dict.get(container, key) if present else None
        return [
            key,
            present,
            *(
                _total_avg_cells_binding_atom(value)
                if present
                else ("missing", "")
            ),
        ]

    return [
        ["constraints", constraints_present, type(constraints) is dict],  # noqa: E721
        field(constraints, "mode"),
        ["count_row", type(count_row) is dict],  # noqa: E721
        *[
            field(count_row, key)
            for key in ("value", "source", "confidence", "sequence")
        ],
        ["structured", structured_present, type(structured) is dict],  # noqa: E721
        *[
            field(structured, key)
            for key in (
                "total_count",
                "total_item_count",
                "session_total_count",
                "session_total_item_count",
            )
        ],
        field(snapshot, "total_count"),
        field(snapshot, "total_item_count"),
        field(summary, "input_total_item_count"),
        field(counts, "input_total_item_count"),
        field(posterior, "input_total_item_count"),
        field(posterior, "total_item_count_status"),
    ]


def _total_avg_cells_raw_binding(
    snapshot: dict[str, Any],
    rows: tuple[object, ...],
    *,
    container_invalid: bool,
) -> str:
    """Bind a prepared decision to its canonical targeted raw ledger and scope."""

    scoped: list[list[object]] = []
    for identity_field in ("session_id", "session_epoch", "epoch"):
        root_source, context_source = _total_avg_cells_identity_sources(
            snapshot,
            identity_field,
        )
        scoped.append(
            [
                identity_field,
                [
                    "root",
                    root_source[0],
                    *_total_avg_cells_binding_atom(root_source[1]),
                ],
                [
                    "context",
                    context_source[0],
                    *_total_avg_cells_binding_atom(context_source[1]),
                ],
                [
                    "resolved",
                    *_total_avg_cells_binding_atom(
                        _total_avg_cells_current_anchor(
                            snapshot,
                            identity_field,
                        )
                    ),
                ],
            ]
        )
    row_fields = (
        "info_id",
        "semantic",
        "kind",
        "value",
        "stale",
        "is_stale",
        "current",
        "session_id",
        "session_epoch",
        "epoch",
    )
    canonical_rows: list[list[object]] = []
    for row in rows:
        semantic, invalid = _total_avg_cells_row_semantic(row)
        if semantic is None and not invalid:
            continue
        if not isinstance(row, dict):
            canonical_rows.append([["row", "invalid"]])
            continue
        record: list[object] = [["classification", semantic or "invalid"]]
        for row_field in row_fields:
            present = dict.__contains__(row, row_field)
            record.append(
                [
                    row_field,
                    present,
                    *(
                        _total_avg_cells_binding_atom(
                            dict.get(row, row_field)
                        )
                        if present
                        else ("missing", "")
                    ),
                ]
            )
        canonical_rows.append(record)
    canonical_rows.sort(
        key=lambda record: json.dumps(
            record,
            ensure_ascii=True,
            separators=(",", ":"),
        )
    )
    payload = json.dumps(
        {
            "container_invalid": container_invalid,
            "context_container_invalid": (
                _total_avg_cells_context_container_invalid(snapshot)
            ),
            "packet_count": _total_avg_cells_packet_count_binding(snapshot),
            "rows": canonical_rows,
            "scope": scoped,
            "version": 2,
        },
        ensure_ascii=True,
        separators=(",", ":"),
        sort_keys=True,
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def _total_avg_cells_raw_row_current(
    snapshot: dict[str, Any],
    row: dict[str, Any],
) -> str:
    """Return current, stale, or invalid for a targeted raw public row."""
    for marker in ("stale", "is_stale"):
        if marker not in row:
            continue
        value = row.get(marker)
        if type(value) is not bool:  # noqa: E721
            return "invalid"
        if value:
            return "stale"
    if "current" in row:
        current = row.get("current")
        if type(current) is not bool:  # noqa: E721
            return "invalid"
        if not current:
            return "stale"

    for identity_field in ("session_id", "session_epoch", "epoch"):
        if identity_field not in row:
            continue
        row_identity = row.get(identity_field)
        current_identity = _total_avg_cells_current_anchor(
            snapshot,
            identity_field,
        )
        if not _total_avg_cells_identity_valid(row_identity):
            return "invalid"
        if not _total_avg_cells_identity_valid(current_identity):
            return "invalid"
        if type(row_identity) is not type(current_identity):  # noqa: E721
            return "invalid"
        if row_identity != current_identity:
            return "stale"
    return "current"


def _strict_total_avg_cells_raw_authority(
    snapshot: dict[str, Any],
) -> _TotalAvgCellsRawAuthority:
    rows = dict.get(snapshot, "public_info_rows")
    raw_rows, container_invalid = _total_avg_cells_rows_container(rows)
    raw_binding = _total_avg_cells_raw_binding(
        snapshot,
        raw_rows,
        container_invalid=container_invalid,
    )
    packet_count_authority = (
        _strict_total_avg_cells_packet_count_authority(snapshot)
    )

    def decision(
        status: str,
        total_count: int | None = None,
        total_avg_cells: float | None = None,
    ) -> _TotalAvgCellsRawAuthority:
        return _TotalAvgCellsRawAuthority(
            status,
            total_count,
            total_avg_cells,
            raw_binding,
        )

    raw_targeted = any(
        semantic is not None or invalid
        for semantic, invalid in (
            _total_avg_cells_row_semantic(row) for row in raw_rows
        )
    )
    if container_invalid or (
        raw_targeted
        and (
            _total_avg_cells_current_scope_invalid(snapshot)
            or packet_count_authority.status == "conflict"
        )
    ):
        return decision("conflict")

    counts: set[int] = set()
    averages: set[float] = set()
    count_rows = 0
    average_rows = 0
    targeted = False
    for row in raw_rows:
        semantic, invalid_alias = _total_avg_cells_row_semantic(row)
        if invalid_alias:
            return decision("conflict")
        if semantic is None:
            continue
        targeted = True
        assert isinstance(row, dict)  # narrowed by _total_avg_cells_row_semantic
        current_status = _total_avg_cells_raw_row_current(snapshot, row)
        if current_status == "stale":
            continue
        if current_status != "current":
            return decision("conflict")
        if semantic == "total_item_count":
            count_rows += 1
            if count_rows > 1:
                return decision("conflict")
            count = _strict_total_avg_cells_count(row.get("value"))
            if count is None:
                return decision("conflict")
            counts.add(count)
        else:
            average_rows += 1
            if average_rows > 1:
                return decision("conflict")
            average = _strict_total_avg_cells_mean(row.get("value"))
            if average is None:
                return decision("conflict")
            averages.add(average)
    if (
        packet_count_authority.status == "valid"
        and packet_count_authority.total_count is not None
    ):
        counts.add(packet_count_authority.total_count)
    if len(counts) > 1 or len(averages) > 1:
        return decision("conflict")
    if len(counts) == 1 and len(averages) == 1:
        return decision(
            "valid",
            next(iter(counts)),
            next(iter(averages)),
        )
    return decision("incomplete" if targeted else "absent")


def _strict_total_avg_cells_prepared_authority(
    public_info: dict[str, Any],
) -> _TotalAvgCellsRawAuthority:
    rows = public_info.get("public_numeric_facts")
    prepared_rows, container_invalid = _total_avg_cells_rows_container(rows)
    if container_invalid:
        return _TotalAvgCellsRawAuthority("conflict")
    counts: set[int] = set()
    averages: set[float] = set()
    count_rows = 0
    average_rows = 0
    targeted = False
    for row in prepared_rows:
        semantic, invalid_alias = _total_avg_cells_row_semantic(row)
        if invalid_alias:
            return _TotalAvgCellsRawAuthority("conflict")
        if semantic is None:
            continue
        targeted = True
        assert isinstance(row, dict)
        if semantic == "total_item_count":
            count_rows += 1
            if count_rows > 1:
                return _TotalAvgCellsRawAuthority("conflict")
            count = _strict_total_avg_cells_count(row.get("value"))
            if count is None:
                return _TotalAvgCellsRawAuthority("conflict")
            counts.add(count)
        else:
            average_rows += 1
            if average_rows > 1:
                return _TotalAvgCellsRawAuthority("conflict")
            average = _strict_total_avg_cells_mean(row.get("value"))
            if average is None:
                return _TotalAvgCellsRawAuthority("conflict")
            averages.add(average)
    if len(counts) > 1 or len(averages) > 1:
        return _TotalAvgCellsRawAuthority("conflict")
    if len(counts) == 1 and len(averages) == 1:
        return _TotalAvgCellsRawAuthority(
            "valid",
            next(iter(counts)),
            next(iter(averages)),
        )
    return _TotalAvgCellsRawAuthority("incomplete" if targeted else "absent")


def _total_avg_cells_authority_auth_payload(
    decision: _TotalAvgCellsRawAuthority,
) -> bytes | None:
    if type(decision.status) is not str:  # noqa: E721
        return None
    if decision.status not in {"absent", "incomplete", "conflict", "valid"}:
        return None
    if (
        type(decision.raw_binding) is not str  # noqa: E721
        or re.fullmatch(r"[0-9a-f]{64}", decision.raw_binding) is None
    ):
        return None
    if decision.status != "valid":
        if decision.total_count is not None or decision.total_avg_cells is not None:
            return None
        return (
            f"v2\n{decision.status}\n-\n-\n{decision.raw_binding}"
        ).encode("ascii")
    if (
        type(decision.total_count) is not int  # noqa: E721
        or decision.total_count <= 0
        or type(decision.total_avg_cells) is not float  # noqa: E721
        or not math.isfinite(decision.total_avg_cells)
        or decision.total_avg_cells <= 0
    ):
        return None
    return (
        f"v2\nvalid\n{decision.total_count}\n"
        f"{decision.total_avg_cells.hex()}\n{decision.raw_binding}"
    ).encode("ascii")


def _total_avg_cells_prepared_marker(
    decision: _TotalAvgCellsRawAuthority,
) -> str:
    payload = _total_avg_cells_authority_auth_payload(decision)
    if payload is None:
        raise ValueError("invalid total average cells authority decision")
    return hmac.digest(
        _TOTAL_AVG_CELLS_PREPARED_AUTH_KEY,
        payload,
        "sha256",
    ).hex()


def _total_avg_cells_prepared_decision_row(
    raw_decision: object,
) -> _TotalAvgCellsRawAuthority | None:
    if type(raw_decision) is not dict or set(dict.keys(raw_decision)) != {  # noqa: E721
        "status",
        "total_count",
        "total_avg_cells",
        "raw_binding",
    }:
        return None
    decision = _TotalAvgCellsRawAuthority(
        status=dict.get(raw_decision, "status"),
        total_count=dict.get(raw_decision, "total_count"),
        total_avg_cells=dict.get(raw_decision, "total_avg_cells"),
        raw_binding=dict.get(raw_decision, "raw_binding"),
    )
    return (
        decision
        if _total_avg_cells_authority_auth_payload(decision) is not None
        else None
    )


def _prepared_total_avg_cells_raw_authority(
    snapshot: object,
) -> _TotalAvgCellsRawAuthority | None:
    if type(snapshot) is not dict:  # noqa: E721
        return None
    current = _strict_total_avg_cells_raw_authority(snapshot)
    invalid = _TotalAvgCellsRawAuthority(
        "conflict",
        raw_binding=current.raw_binding,
    )
    marker = dict.get(
        snapshot,
        _TOTAL_AVG_CELLS_PREPARED_MARKER_KEY,
        _ENV_MISSING,
    )
    raw_decision = dict.get(
        snapshot,
        _TOTAL_AVG_CELLS_PREPARED_DECISION_KEY,
        _ENV_MISSING,
    )
    if marker is _ENV_MISSING and raw_decision is _ENV_MISSING:
        return None
    if type(marker) is not str or len(marker) != 64:  # noqa: E721
        return invalid
    decision = _total_avg_cells_prepared_decision_row(raw_decision)
    if decision is None:
        return invalid
    expected = _total_avg_cells_prepared_marker(decision)
    if not hmac.compare_digest(marker, expected):
        return invalid
    # A copied marker cannot bless a different raw ledger. Sanitization may
    # only make a prior conflict look valid, which remains fail-closed here.
    return decision if current == decision else invalid


def _total_avg_cells_raw_authority_decision(
    snapshot: dict[str, Any],
) -> _TotalAvgCellsRawAuthority:
    active = _TOTAL_AVG_CELLS_RAW_AUTHORITY.get()
    if active is not None:
        return active
    prepared = _prepared_total_avg_cells_raw_authority(snapshot)
    if prepared is not None:
        return prepared
    return _strict_total_avg_cells_raw_authority(snapshot)


def _bounded_q5_action_integer(
    value: Any,
    *,
    maximum: int,
) -> int | None:
    """Parse one exact action scalar without float overflow or user protocols."""
    parsed: int
    if type(value) is int:
        parsed = value
    elif type(value) is float:
        if not math.isfinite(value) or not value.is_integer():
            return None
        if value < 0 or value > maximum:
            return None
        parsed = int(value)
    elif type(value) is str:
        if (
            len(value) > 32
            or not value.isascii()
            or any(ord(char) < 0x20 or ord(char) == 0x7F for char in value)
        ):
            return None
        text = value.strip(" ")
        if re.fullmatch(r"[+-]?[0-9]+", text) is None:
            return None
        parsed = int(text)
    else:
        return None
    if parsed < 0 or parsed > maximum:
        return None
    return parsed


def _q5_action_scalar_missing(value: Any) -> bool:
    if value is None:
        return True
    if type(value) is not str:
        return False
    if (
        len(value) > 32
        or not value.isascii()
        or any(ord(char) < 0x20 or ord(char) == 0x7F for char in value)
    ):
        return False
    return not value.strip(" ")


def _select_current_q5_exact_total_action(
    snapshot: Mapping[str, Any],
    action_results: Any,
    *,
    current_session: str | None,
    current_round: int | None,
) -> tuple[str, float | None]:
    """Select one monotonic q5 total-value action without list-order fallback.

    Monitor artifacts can mirror the same row at the snapshot and ui-contract
    levels.  Equal mirrors are harmless, while two different values for the
    same session/round/sort/action/result-field are contradictory evidence.
    Only a strictly newer sort may replace an earlier value.
    """
    values_by_sort: dict[int, set[float]] = {}
    for rows in (snapshot.get("action_result_rows"), action_results):
        for row in _iter_dicts(rows):
            if str(row.get("action_id") or "") != Q5_EXACT_TOTAL_ACTION_ID:
                continue
            result_field_raw = row.get("result_field")
            if _q5_action_scalar_missing(result_field_raw):
                continue
            result_field = _bounded_q5_action_integer(
                result_field_raw,
                maximum=Q5_EXACT_TOTAL_ACTION_INDEX_MAX,
            )
            if result_field is None:
                return "conflict", None
            if result_field != Q5_EXACT_TOTAL_RESULT_FIELD:
                continue
            row_session = row.get("session_id")
            if (
                current_session is not None
                and row_session is not None
                and row_session != current_session
            ):
                continue
            row_round_raw = row.get("round")
            if _q5_action_scalar_missing(row_round_raw):
                row_round_raw = row.get("action_round")
            row_round = None
            if not _q5_action_scalar_missing(row_round_raw):
                row_round = _bounded_q5_action_integer(
                    row_round_raw,
                    maximum=Q5_EXACT_TOTAL_ACTION_INDEX_MAX,
                )
                if row_round is None:
                    return "conflict", None
            if (
                current_round is not None
                and row_round is not None
                and row_round > current_round
            ):
                return "conflict", None
            sort_raw = row.get("sort")
            if _q5_action_scalar_missing(sort_raw):
                sort_raw = row.get("sort_id")
            sort_id = _bounded_q5_action_integer(
                sort_raw,
                maximum=Q5_EXACT_TOTAL_ACTION_INDEX_MAX,
            )
            value = _bounded_q5_action_integer(
                row.get("result"),
                maximum=Q5_EXACT_TOTAL_ACTION_VALUE_MAX,
            )
            if sort_id is None or value is None:
                return "conflict", None
            values_by_sort.setdefault(sort_id, set()).add(float(value))
    if not values_by_sort:
        return "absent", None
    if any(len(values) != 1 for values in values_by_sort.values()):
        return "conflict", None
    latest_sort = max(values_by_sort)
    latest_values = values_by_sort[latest_sort]
    return "selected", next(iter(latest_values))


def _merge_quality_values(
    out: dict[str, float],
    raw: Any,
    *,
    note_prefix: str,
    source_notes: list[str],
) -> None:
    if not isinstance(raw, dict):
        return
    for raw_key, raw_value in raw.items():
        key = _quality_key(raw_key)
        value = _safe_float(raw_value)
        if key is None or value is None or not math.isfinite(value):
            continue
        out[key] = value
        source_notes.append(f"{note_prefix}_{key}")


def _merge_structured_avg_cells(
    out: dict[str, float],
    raw: Any,
    *,
    source_notes: list[str],
) -> None:
    """Merge structured averages with a protocol-free direct-q6 boundary."""

    if type(raw) is not dict:  # noqa: E721 - exact input container boundary
        return
    for raw_key, raw_value in dict.items(raw):
        key = _quality_key(raw_key)
        if key is None:
            continue
        if key != "q6":
            value = _safe_float(raw_value)
            if value is None:
                continue
        elif type(raw_value) is int:  # noqa: E721 - reject bool/subclasses/coercion
            if raw_value <= 0 or raw_value > PUBLIC_AVG_CELLS_MAX_VALUE:
                continue
            value = float(raw_value)
        elif type(raw_value) is float:  # noqa: E721 - reject subclasses/coercion
            if (
                not math.isfinite(raw_value)
                or raw_value <= 0.0
                or raw_value > PUBLIC_AVG_CELLS_MAX_VALUE
            ):
                continue
            value = raw_value
        else:
            continue
        out[key] = value
        source_notes.append(f"structured_ref_bridge_avg_cells_{key}")


