def _merge_count_sums(
    out: dict[str, int],
    raw: Any,
    *,
    note_prefix: str,
    source_notes: list[str],
) -> None:
    if not isinstance(raw, dict):
        return
    for raw_key, raw_value in raw.items():
        key = str(raw_key or "").strip().lower().replace("+", "")
        value = _safe_int(raw_value)
        if value is None:
            continue
        if key in {"q4q5", "45"}:
            out["q4q5"] = value
            source_notes.append(f"{note_prefix}_q4q5")
        elif (
            key in {"q5q6_min", "56min", "minq5q6"}
            and os.environ.get("BIDKING_DISABLE_POSTUPDATE_NINE_HERO_SKILL_COMPAT") != "1"
        ):
            out["q5q6_min"] = value
            source_notes.append(f"{note_prefix}_q5q6_min")
        elif key in {"q4q5q6", "456"}:
            out["q4q5q6"] = value
            source_notes.append(f"{note_prefix}_q4q5q6")


def _has_shape_reveal(item: dict[str, Any]) -> bool:
    shape_code = item.get("shape_code")
    if shape_code not in (None, "", 0):
        return True
    shape_key = str(item.get("shape_key") or "").strip()
    return bool(shape_key)


def _is_coarse_quality_reveal_item(item: dict[str, Any]) -> bool:
    if _quality_number_to_key(item.get("quality")) is None:
        return False
    return not _has_shape_reveal(item)


def _is_fully_disclosed_catalog_item(item: dict[str, Any]) -> bool:
    """Game disclosed catalog id + footprint + base price (200048/200021/100163 class).

    Coarse quality markers (quality+pos only) and anchor-only minimap rows stay out;
    long-tail normalization still applies there. Full public/action/skill item reveals
    carry the item's catalog value and must floor at that price, not drop-table EV.
    """
    if item.get("item_id") is None:
        return False
    if (_safe_float(item.get("value")) or 0.0) <= 0:
        return False
    return _has_shape_reveal(item)


def _revealed_q6_footprint_catalog_floor(
    item: dict[str, Any],
    key: str,
) -> tuple[int, float] | None:
    """Return ``(cells, minimum catalog value)`` for an exact q6 footprint.

    Gabriela can reveal an item's quality and complete outline without disclosing
    its catalog identity/value. The identity is still unknown, but every real
    q6 collectible with that footprint has a bounded minimum price. That
    minimum is hard evidence; using the tier-average value alone can otherwise
    quote below the cheapest item the revealed outline could physically be.

    Shape is required because some quality-only rows carry anchor/placeholder
    cells. A missing or conflicting catalog entry fails open.
    """
    if (
        key != "q6"
        or os.environ.get(KNOWN_Q6_FOOTPRINT_VALUE_FLOOR_DISABLE) == "1"
        or not _has_shape_reveal(item)
    ):
        return None
    shape_cells = _shape_cells(item.get("shape_code") or item.get("shape_key"))
    if shape_cells is None or shape_cells <= 0:
        return None
    raw_cells = _safe_int(item.get("cells"))
    if raw_cells is not None and raw_cells > 0 and raw_cells != shape_cells:
        return None
    table_quality = QUALITY_TIER_NUMBER.get(key)
    minimum = _catalog_min_value_by_quality_and_cells().get(
        (int(table_quality), int(shape_cells))
    )
    if minimum is None or minimum <= 0:
        return None
    return int(shape_cells), float(minimum)


def _revealed_item_value_for_floor(item: dict[str, Any], key: str) -> float | None:
    raw = _safe_float(item.get("value"))
    if raw is None or raw <= 0:
        return None
    if key != "q6":
        return float(raw)
    if _is_fully_disclosed_catalog_item(item):
        return float(raw)
    normalized = _normalized_red_value(item)
    if normalized is None or normalized <= 0:
        return None
    return float(normalized)


def _quality_reveal_item_identity(item: dict[str, Any], key: str, *, fallback: str) -> tuple[str, str]:
    return (
        str(
            item.get("runtime_id")
            or item.get("local_index")
            or item.get("item_id")
            or fallback
        ),
        key,
    )


def _iter_skill_reveal_dict_rows(
    snapshot: dict[str, Any],
) -> Iterable[dict[str, Any]]:
    seen: set[int] = set()
    for key in ("skill_reveal_rows", "skill_reveals"):
        for row in _iter_dicts(snapshot.get(key)):
            if not isinstance(row, dict):
                continue
            row_id = id(row)
            if row_id in seen:
                continue
            seen.add(row_id)
            yield row


def _is_maria_skill_quality_reveal_row(row: dict[str, Any]) -> bool:
    return (
        _safe_int(row.get("hero_id")) == MARIA_HERO_ID
        and _safe_int(row.get("skill_id")) == MARIA_SKILL_QUALITY_REVEAL_ID
    )


def _apply_maria_skill_evidence(
    snapshot: dict[str, Any],
    *,
    total_count: int | None,
    min_counts: dict[str, int],
    split_counts: dict[str, int],
    count_sums: dict[str, int],
    quality_value_floors: dict[str, float],
    source_notes: list[str],
) -> None:
    counts = {key: 0 for key in QUALITY_KEYS}
    split = {key: 0 for key in LOW_SPLIT_KEYS}
    seen: set[tuple[str, str]] = set()
    maria_sources: set[str] = set()

    for row in _iter_skill_reveal_dict_rows(snapshot):
        if not _is_maria_skill_quality_reveal_row(row):
            continue
        skill_id = _safe_int(row.get("skill_id"))
        prefix = f"maria_skill_{skill_id or 'quality'}"
        items = row.get("observed_items") or row.get("revealed_items_detail") or ()
        for item_idx, item in enumerate(_iter_dicts(items)):
            if not isinstance(item, dict):
                continue
            quality = _safe_int(item.get("quality"))
            if quality is None or quality > 3:
                continue
            key = _quality_number_to_key(quality)
            if key is None or not _is_coarse_quality_reveal_item(item):
                continue
            identity = _quality_reveal_item_identity(
                item,
                key,
                fallback=f"{prefix}-{item_idx}",
            )
            if identity in seen:
                continue
            seen.add(identity)
            counts[key] += 1
            maria_sources.add(prefix)
            split_key = LOW_QUALITY_NUMBER_TO_SPLIT.get(str(quality))
            if split_key is not None:
                split[split_key] += 1

    for row in _iter_skill_reveal_dict_rows(snapshot):
        if _safe_int(row.get("hero_id")) != MARIA_HERO_ID:
            continue
        if _is_maria_skill_quality_reveal_row(row):
            continue
        skill_key = str(row.get("skill_id") or "")
        quality_key = MARIA_SKILL_VALUE_BY_ID.get(skill_key)
        if quality_key is None:
            continue
        value = _safe_float(row.get("result"))
        if value is None or value <= 0:
            continue
        quality_value_floors[quality_key] = max(
            quality_value_floors.get(quality_key, 0.0),
            float(value),
        )
        source_notes.append(f"maria_skill_{quality_key}_value_floor")

    if any(counts.values()):
        for key, value in counts.items():
            min_counts[key] = max(min_counts.get(key, 0), value)
        source_notes.append("maria_skill_coarse_quality_min_counts")
        for prefix in sorted(maria_sources):
            source_notes.append(f"maria_skill_coarse_quality_source:{prefix}")
    if any(split.values()):
        for key, value in split.items():
            split_counts[key] = max(split_counts.get(key, 0), value)
        source_notes.append("maria_skill_coarse_quality_split_counts")

    # 高品合计件数推导 —— 玛丽亚估价的核心杠杆。玛丽亚 R1 品质技能揭示【所有】低品(白/绿/蓝)的品质
    # (作者确认 + 2407 回放坐实: 揭示白5绿7蓝23 = 结算 q1/q2/q3), 故低品件数精确且完整。配合总件数,
    # 高品三档(紫/金/红)合计 = 总件数 - 低品件数(各档仍未知)。不做这步, 高品(价值大头)全靠先验 →
    # 严重欠估(2407 实测欠估 39%)。走 count_sums["q4q5q6"](与 victor 高品合计同一消费通道)。
    # 回滚: BIDKING_DISABLE_MARIA_HIGH_TIER_COUNT_SUM=1。
    if (
        os.environ.get("BIDKING_DISABLE_MARIA_HIGH_TIER_COUNT_SUM") != "1"
        and any(counts.values())
        and total_count is not None
        and "q4q5q6" not in count_sums
    ):
        low_total = sum(int(v) for v in counts.values())
        high_total = int(total_count) - low_total
        if high_total >= 0:
            count_sums["q4q5q6"] = high_total
            source_notes.append(f"maria_high_tier_count_sum_derived:{high_total}")


def _outline_item_cells(item: Mapping[str, Any]) -> int | None:
    cells = _safe_int(item.get("cells"))
    if cells is not None and cells > 0:
        return cells
    return _shape_cells(item.get("shape_code") or item.get("shape_key"))


def _outline_item_shape_identity(item: Mapping[str, Any]) -> int | None:
    shape = _safe_int(item.get("shape_code") or item.get("shape_key"))
    if _shape_cells(shape) is None:
        return None
    return shape


def _maria_exact_int(value: Any, *, minimum: int = 0) -> int | None:
    """Maria physical identity/quality fields are exact wire integers."""

    if type(value) is not int:
        return None
    return value if value >= minimum else None


MARIA_PROTOBUF_UINT64_MAX = (1 << 64) - 1
MARIA_PROTOBUF_UINT64_DECIMAL_DIGITS = 20
MARIA_REVEALED_ITEMS_MAX = 1024  # Fatbeans protobuf walker field limit.
MARIA_SHAPE_CODE_MAX = 99  # width/height are the two decimal digits.


def _maria_decimal_int(
    value: Any,
    *,
    minimum: int = 0,
    maximum: int,
) -> int | None:
    """Accept an exact int or a canonical unsigned decimal string, never float/bool."""

    if type(value) is int:
        parsed = value
    elif type(value) is str:
        if (
            len(value) > MARIA_PROTOBUF_UINT64_DECIMAL_DIGITS
            or re.fullmatch(r"(?:0|[1-9][0-9]*)", value) is None
        ):
            return None
        try:
            parsed = int(value)
        except (ValueError, OverflowError):
            return None
    else:
        return None
    return parsed if minimum <= parsed <= maximum else None


def _maria_shape(value: Any) -> tuple[int, int] | None:
    parsed = _maria_decimal_int(
        value,
        minimum=1,
        maximum=MARIA_SHAPE_CODE_MAX,
    )
    if parsed is None:
        return None
    width, height = divmod(parsed, 10)
    if width <= 0 or height <= 0:
        return None
    return min(width, height), max(width, height)


def _maria_row_items(
    row: Mapping[str, Any],
    *,
    allow_empty: bool,
) -> list[Mapping[str, Any]] | None:
    raw = row.get("observed_items")
    if raw is None:
        raw = row.get("revealed_items_detail")
    if not isinstance(raw, (list, tuple)):
        return None
    if not raw and not allow_empty:
        return None
    if any(not isinstance(item, Mapping) for item in raw):
        return None
    return list(raw)


def _maria_full_outline_item_signature(
    items: list[Mapping[str, Any]],
) -> tuple[tuple[int, int, int, int, int], ...] | None:
    identity = _validated_outline_identity_cells(
        items,
        require_runtime_ids=True,
    )
    if identity is None or len(identity) != len(items):
        return None
    cells_by_runtime = dict(identity)
    signature: list[tuple[int, int, int, int, int]] = []
    for item in items:
        runtime_id = _maria_exact_int(item.get("runtime_id"), minimum=1)
        if runtime_id is None:
            return None
        raw_shape = item.get("shape_code")
        if raw_shape in (None, ""):
            raw_shape = item.get("shape_key")
        shape = _maria_shape(raw_shape)
        if shape is None:
            return None
        if item.get("shape_code") not in (None, "") and item.get("shape_key") not in (
            None,
            "",
        ):
            shape_key = _maria_shape(item.get("shape_key"))
            if shape_key != shape:
                return None
        cells = shape[0] * shape[1]
        if cells_by_runtime.get(runtime_id) != cells:
            return None
        raw_cells = item.get("cells")
        if (
            raw_cells not in (None, "")
            and _maria_exact_int(raw_cells, minimum=1) != cells
        ):
            return None
        raw_local_index = item.get("local_index")
        local_index = _maria_exact_int(raw_local_index, minimum=0)
        if raw_local_index not in (None, "") and local_index is None:
            return None
        raw_quality = item.get("quality")
        quality = _maria_exact_int(raw_quality, minimum=1)
        if raw_quality not in (None, "") and quality is None:
            return None
        signature.append(
            (runtime_id, shape[0], shape[1], local_index or 0, quality or 0)
        )
    return tuple(sorted(signature)) if signature else None


def _maria_select_full_warehouse_outline(
    snapshot: Mapping[str, Any],
    *,
    session_id: str,
) -> tuple[list[Mapping[str, Any]] | None, str]:
    groups: list[Any] = [snapshot.get("action_result_rows")]
    ui_contract = snapshot.get("ui_contract")
    if isinstance(ui_contract, Mapping):
        actions = ui_contract.get("actions")
        if isinstance(actions, Mapping):
            groups.append(actions.get("results"))

    candidates: list[
        tuple[
            int,
            tuple[tuple[int, int, int, int, int], ...] | None,
            list[Mapping[str, Any]],
        ]
    ] = []
    for rows in groups:
        if not isinstance(rows, (list, tuple)):
            continue
        for row in rows:
            if not isinstance(row, Mapping):
                continue
            if _maria_decimal_int(
                row.get("action_id"),
                minimum=1,
                maximum=MARIA_PROTOBUF_UINT64_MAX,
            ) != 100100:
                continue
            items = _maria_row_items(row, allow_empty=False)
            # The compact ui_contract mirror intentionally omits item details.  It is
            # not evidence by itself and must not invalidate the richer packet row.
            if items is None:
                continue
            sort_id = _maria_decimal_int(
                row.get("sort"),
                minimum=0,
                maximum=MARIA_PROTOBUF_UINT64_MAX,
            )
            row_session = row.get("session_id")
            source_kind = row.get("source_kind")
            revealed_count = _maria_decimal_int(
                row.get("revealed_items"),
                minimum=1,
                maximum=MARIA_REVEALED_ITEMS_MAX,
            )
            valid_metadata = (
                sort_id is not None
                and type(row_session) is str
                and row_session == session_id
                and source_kind in (None, "", "direct_action_response")
                and revealed_count == len(items)
            )
            signature = (
                _maria_full_outline_item_signature(items)
                if valid_metadata
                else None
            )
            candidates.append((sort_id or -1, signature, items))
    if not candidates:
        return None, "missing_full_warehouse"
    newest = max(sort_id for sort_id, _signature, _items in candidates)
    latest = [entry for entry in candidates if entry[0] == newest]
    if any(signature is None for _sort, signature, _items in latest):
        return None, "malformed_full_warehouse"
    signatures = {signature for _sort, signature, _items in latest}
    if len(signatures) != 1:
        return None, "conflicting_full_warehouse"
    return latest[0][2], "ok"


def _maria_quality_marker_signature(
    items: list[Mapping[str, Any]],
) -> tuple[tuple[int, int], ...] | None:
    signature: list[tuple[int, int]] = []
    seen_runtime_ids: set[int] = set()
    for item in items:
        runtime_id = _maria_exact_int(item.get("runtime_id"), minimum=1)
        quality = _maria_exact_int(item.get("quality"), minimum=1)
        if (
            runtime_id is None
            or runtime_id in seen_runtime_ids
            or quality not in (1, 2, 3)
        ):
            return None
        seen_runtime_ids.add(runtime_id)
        signature.append((runtime_id, quality))
    return tuple(sorted(signature))


def _maria_select_complete_low_quality_markers(
    snapshot: Mapping[str, Any],
    *,
    session_id: str,
) -> tuple[dict[int, int] | None, str]:
    candidates: list[
        tuple[int, tuple[tuple[int, int], ...] | None, bool]
    ] = []
    for row in _iter_skill_reveal_dict_rows(dict(snapshot)):
        if not isinstance(row, Mapping):
            continue
        if _maria_decimal_int(
            row.get("hero_id"),
            minimum=1,
            maximum=MARIA_PROTOBUF_UINT64_MAX,
        ) != MARIA_HERO_ID or _maria_decimal_int(
            row.get("skill_id"),
            minimum=1,
            maximum=MARIA_PROTOBUF_UINT64_MAX,
        ) != MARIA_SKILL_QUALITY_REVEAL_ID:
            continue
        items = _maria_row_items(row, allow_empty=True)
        if items is None:
            continue
        sort_id = _maria_decimal_int(
            row.get("sort"),
            minimum=0,
            maximum=MARIA_PROTOBUF_UINT64_MAX,
        )
        row_session = row.get("session_id")
        stale_session = (
            row_session not in (None, "") and row_session != session_id
        )
        explicit_count = row.get("revealed_items")
        has_complete_count = False
        malformed_count = False
        if explicit_count not in (None, ""):
            parsed_count = _maria_decimal_int(
                explicit_count,
                minimum=0,
                maximum=MARIA_REVEALED_ITEMS_MAX,
            )
            malformed_count = parsed_count is None or parsed_count != len(items)
            has_complete_count = not malformed_count
        signature = (
            _maria_quality_marker_signature(items)
            if sort_id is not None and not malformed_count and not stale_session
            else None
        )
        candidates.append((sort_id or -1, signature, has_complete_count))
    if not candidates:
        return None, "missing_maria_quality_markers"
    newest = max(sort_id for sort_id, _signature, _complete in candidates)
    latest = [entry for entry in candidates if entry[0] == newest]
    if any(signature is None for _sort, signature, _complete in latest):
        return None, "malformed_maria_quality_markers"
    signatures = {signature for _sort, signature, _complete in latest}
    if len(signatures) != 1:
        return None, "conflicting_maria_quality_markers"
    if not any(complete for _sort, _signature, complete in latest):
        return None, "unproven_maria_quality_marker_completeness"
    signature = next(iter(signatures))
    return {runtime_id: quality for runtime_id, quality in signature}, "ok"


def _apply_maria_complete_low_quality_counts(
    snapshot: Mapping[str, Any],
    *,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    split_counts: dict[str, int],
) -> str:
    """Promote Maria's complete q1/q2/q3 marker list to exact counts.

    The skill enumerates every low-quality runtime but does not reveal its
    footprint.  Counts can therefore lock immediately, while cells remain
    probabilistic until an independent outline/shape source arrives.
    """

    ui_contract = snapshot.get("ui_contract")
    context = (
        ui_contract.get("context")
        if isinstance(ui_contract, Mapping)
        and isinstance(ui_contract.get("context"), Mapping)
        else {}
    )
    hero = normalize_hero_key(context.get("hero") or snapshot.get("hero"))
    if hero != "maria":
        return "hero_out_of_scope"
    phase = str(context.get("phase") or snapshot.get("phase") or "").strip().lower()
    # Maria's complete low-quality list is present in the session-opening
    # reading snapshot, before the first action/quote transitions to bidding.
    # Count completeness is identical across the two live quoting phases;
    # footprints remain gated by the separate full-warehouse outline join below.
    if phase not in {"reading", "bidding"}:
        return "phase_out_of_scope"
    session_id = context.get("session_id") or snapshot.get("session_id")
    if type(session_id) is not str or not session_id:  # noqa: E721
        return "missing_current_session"

    low_qualities, status = _maria_select_complete_low_quality_markers(
        snapshot,
        session_id=session_id,
    )
    if low_qualities is None:
        return status

    raw_counts = {1: 0, 2: 0, 3: 0}
    for quality in low_qualities.values():
        raw_counts[quality] += 1
    canonical_counts = {
        "q1": raw_counts[1] + raw_counts[2],
        "q3": raw_counts[3],
    }
    split_values = {"white": raw_counts[1], "green": raw_counts[2]}

    for key, expected in canonical_counts.items():
        existing_fixed = fixed_counts.get(key)
        if existing_fixed is not None and (
            type(existing_fixed) is not int or existing_fixed != expected  # noqa: E721
        ):
            return f"existing_{key}_count_conflict"
        existing_min = min_counts.get(key)
        if existing_min is not None and (
            type(existing_min) is not int or existing_min > expected  # noqa: E721
        ):
            return f"existing_{key}_minimum_conflict"
    for key, expected in split_values.items():
        existing = split_counts.get(key)
        if existing is not None and (
            type(existing) is not int or existing > expected  # noqa: E721
        ):
            return f"existing_{key}_count_conflict"

    fixed_counts.update(canonical_counts)
    for key, value in canonical_counts.items():
        min_counts[key] = value
    split_counts.update(split_values)
    return "applied"


def _apply_maria_full_warehouse_low_quality_cells(
    snapshot: Mapping[str, Any],
    *,
    exact_total_count: int | None,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    quality_cells: dict[str, float],
    split_counts: dict[str, int],
    split_quality_cells: dict[str, float],
) -> str:
    """Join Maria's complete low-quality markers to full-outline footprints.

    The skill proves which current-session runtimes are q1/q2/q3.  The full
    warehouse action independently proves every runtime's footprint.  Neither
    row is sufficient alone; only their strict runtime join can lock the low
    quality count/cell dimensions while leaving q4-q6 unpartitioned.
    """

    ui_contract = snapshot.get("ui_contract")
    context = (
        ui_contract.get("context")
        if isinstance(ui_contract, Mapping)
        and isinstance(ui_contract.get("context"), Mapping)
        else {}
    )
    hero = normalize_hero_key(context.get("hero") or snapshot.get("hero"))
    if hero != "maria":
        return "hero_out_of_scope"
    phase = str(context.get("phase") or snapshot.get("phase") or "").strip().lower()
    if phase != "bidding":
        return "phase_out_of_scope"
    session_id = context.get("session_id") or snapshot.get("session_id")
    if type(session_id) is not str or not session_id:
        return "missing_current_session"
    if type(exact_total_count) is not int or exact_total_count <= 0:
        return "missing_exact_total_count"

    outline_items, outline_status = _maria_select_full_warehouse_outline(
        snapshot,
        session_id=session_id,
    )
    if outline_items is None:
        return outline_status
    if len(outline_items) != exact_total_count:
        return "full_warehouse_total_count_mismatch"
    low_qualities, quality_status = _maria_select_complete_low_quality_markers(
        snapshot,
        session_id=session_id,
    )
    if low_qualities is None:
        return quality_status

    outline_by_runtime: dict[int, tuple[int, int | None]] = {}
    for item in outline_items:
        runtime_id = _maria_exact_int(item.get("runtime_id"), minimum=1)
        raw_shape = item.get("shape_code")
        if raw_shape in (None, ""):
            raw_shape = item.get("shape_key")
        shape = _maria_shape(raw_shape)
        raw_quality = item.get("quality")
        explicit_quality = _maria_exact_int(raw_quality, minimum=1)
        if (
            runtime_id is None
            or runtime_id in outline_by_runtime
            or shape is None
            or (raw_quality not in (None, "") and explicit_quality is None)
        ):
            return "malformed_full_warehouse_identity"
        outline_by_runtime[runtime_id] = (
            shape[0] * shape[1],
            explicit_quality,
        )
    if not set(low_qualities).issubset(outline_by_runtime):
        return "low_quality_identity_outside_full_warehouse"

    raw_counts = {1: 0, 2: 0, 3: 0}
    raw_cells = {1: 0, 2: 0, 3: 0}
    for runtime_id, quality in low_qualities.items():
        cells, explicit_quality = outline_by_runtime[runtime_id]
        if explicit_quality is not None and explicit_quality != quality:
            return "full_warehouse_low_quality_identity_conflict"
        raw_counts[quality] += 1
        raw_cells[quality] += cells

    canonical_counts = {
        "q1": raw_counts[1] + raw_counts[2],
        "q3": raw_counts[3],
    }
    canonical_cells = {
        "q1": float(raw_cells[1] + raw_cells[2]),
        "q3": float(raw_cells[3]),
    }
    split_count_values = {"white": raw_counts[1], "green": raw_counts[2]}
    split_cell_values = {
        "white": float(raw_cells[1]),
        "green": float(raw_cells[2]),
    }

    for key, expected in canonical_counts.items():
        existing_fixed = fixed_counts.get(key)
        if existing_fixed is not None and (
            type(existing_fixed) is not int or existing_fixed != expected
        ):
            return f"existing_{key}_count_conflict"
        existing_min = min_counts.get(key)
        if existing_min is not None and (
            type(existing_min) is not int or existing_min > expected
        ):
            return f"existing_{key}_minimum_conflict"
    for key, expected in split_count_values.items():
        existing = split_counts.get(key)
        if existing is not None and (
            type(existing) is not int or existing != expected
        ):
            return f"existing_{key}_count_conflict"
    for mapping, values, label in (
        (quality_cells, canonical_cells, "quality"),
        (split_quality_cells, split_cell_values, "split"),
    ):
        for key, expected in values.items():
            existing = mapping.get(key)
            if existing is not None and (
                type(existing) not in (int, float)
                or not math.isfinite(float(existing))
                or abs(float(existing) - expected) > 0.0001
            ):
                return f"existing_{label}_{key}_cells_conflict"

    fixed_counts.update(canonical_counts)
    for key, value in canonical_counts.items():
        min_counts[key] = max(min_counts.get(key, 0), value)
    quality_cells.update(canonical_cells)
    split_counts.update(split_count_values)
    split_quality_cells.update(split_cell_values)
    return "applied"


def _maria_full_warehouse_shape_red_items(
    snapshot: Mapping[str, Any],
    *,
    exact_total_count: int | None,
    hard_fixed_counts: Mapping[str, int],
    hard_quality_cells: Mapping[str, float],
    hard_quality_values: Mapping[str, float],
    known_reveal_rows: Sequence[tuple[str, Mapping[str, Any]]],
) -> tuple[tuple[dict[str, Any], ...], str]:
    """Infer only the Maria 5x4 blue-or-red complement as hard red evidence.

    The full-outline action proves every physical runtime and footprint.  Maria's
    complete low-tier scan proves every q1/q2/q3 runtime.  A 5x4 runtime absent
    from that scan is red only when the cross-checked current catalog says the
    footprint belongs to exactly q3 or q6.  Any incomplete identity, stale
    session, row conflict, or catalog disagreement suppresses the inference.
    """
    if os.environ.get(MARIA_FULL_WAREHOUSE_SHAPE_RED_DISABLE) == "1":
        return (), "disabled"
    ui_contract = snapshot.get("ui_contract")
    context = (
        ui_contract.get("context")
        if isinstance(ui_contract, Mapping)
        and isinstance(ui_contract.get("context"), Mapping)
        else {}
    )
    hero = normalize_hero_key(context.get("hero") or snapshot.get("hero"))
    if hero != "maria":
        return (), "hero_out_of_scope"
    phase = str(context.get("phase") or snapshot.get("phase") or "").strip().lower()
    if phase != "bidding":
        return (), "phase_out_of_scope"
    session_id = context.get("session_id") or snapshot.get("session_id")
    if type(session_id) is not str or not session_id:
        return (), "missing_current_session"

    outline_items, outline_status = _maria_select_full_warehouse_outline(
        snapshot,
        session_id=session_id,
    )
    if outline_items is None:
        return (), outline_status
    if type(exact_total_count) is not int or exact_total_count <= 0:
        return (), "missing_exact_total_count"
    if len(outline_items) != exact_total_count:
        return (), "full_warehouse_total_count_mismatch"
    low_qualities, quality_status = _maria_select_complete_low_quality_markers(
        snapshot,
        session_id=session_id,
    )
    if low_qualities is None:
        return (), quality_status

    outline_runtime_ids = {
        int(item["runtime_id"])
        for item in outline_items
        if type(item.get("runtime_id")) is int
    }
    if not set(low_qualities).issubset(outline_runtime_ids):
        return (), "low_quality_identity_outside_full_warehouse"

    target_items: list[Mapping[str, Any]] = []
    for item in outline_items:
        runtime_id = int(item["runtime_id"])
        raw_explicit_quality = item.get("quality")
        explicit_quality = _maria_exact_int(raw_explicit_quality, minimum=1)
        if raw_explicit_quality not in (None, "") and explicit_quality is None:
            return (), "full_warehouse_quality_malformed"
        if runtime_id in low_qualities:
            if explicit_quality is not None and explicit_quality != low_qualities[runtime_id]:
                return (), "full_warehouse_low_quality_identity_conflict"
            continue
        raw_shape = item.get("shape_code")
        if raw_shape in (None, ""):
            raw_shape = item.get("shape_key")
        if _maria_shape(raw_shape) != (4, 5):
            continue
        if explicit_quality is not None and explicit_quality != 6:
            return (), "full_warehouse_5x4_quality_conflict"
        target_items.append(item)
    if not target_items:
        return (), "no_unmarked_5x4_outline"

    inferred_runtime_ids = {
        int(item["runtime_id"])
        for item in target_items
    }
    for _source_prefix, known_item in known_reveal_rows:
        runtime_id = _maria_exact_int(known_item.get("runtime_id"), minimum=1)
        if runtime_id not in inferred_runtime_ids:
            continue
        quality = _maria_exact_int(known_item.get("quality"), minimum=1)
        if quality is None:
            continue
        if quality != 6:
            return (), "direct_runtime_quality_conflict"
        direct_cells = _outline_item_cells(known_item)
        if direct_cells is not None and direct_cells != 20:
            return (), "direct_runtime_q6_cells_conflict"

    inferred_count = len(target_items)
    fixed_q6 = hard_fixed_counts.get("q6")
    if fixed_q6 is not None and int(fixed_q6) < inferred_count:
        return (), "hard_q6_count_conflict"
    exact_q6_cells = hard_quality_cells.get("q6")
    if (
        exact_q6_cells is not None
        and float(exact_q6_cells) + 0.0001 < 20.0 * inferred_count
    ):
        return (), "hard_q6_cells_conflict"

    catalog_qualities, catalog_status = _maria_validated_5x4_catalog_qualities()
    if catalog_status != "ok":
        return (), f"catalog_{catalog_status}"
    if catalog_qualities != frozenset({3, 6}):
        return (), "catalog_not_blue_red_only"
    catalog_red_floor = _catalog_min_value_by_quality_and_cells().get((6, 20))
    if catalog_red_floor is None or catalog_red_floor <= 0:
        return (), "catalog_red_value_floor_unavailable"
    hard_q6_value = hard_quality_values.get("q6")
    if (
        hard_q6_value is not None
        and float(hard_q6_value) + 0.0001
        < float(catalog_red_floor) * inferred_count
    ):
        return (), "hard_q6_value_conflict"
    for _source_prefix, known_item in known_reveal_rows:
        runtime_id = _maria_exact_int(known_item.get("runtime_id"), minimum=1)
        if runtime_id not in inferred_runtime_ids:
            continue
        direct_value = _revealed_item_value_for_floor(dict(known_item), "q6")
        if direct_value is not None and direct_value + 0.0001 < catalog_red_floor:
            return (), "direct_runtime_q6_value_conflict"

    inferred: list[dict[str, Any]] = []
    for item in target_items:
        enriched = dict(item)
        enriched["quality"] = 6
        enriched["cells"] = 20
        inferred.append(enriched)
    return tuple(inferred), "applied"


def _validated_outline_identity_cells(
    items: Any,
    *,
    require_runtime_ids: bool,
) -> tuple[tuple[int, int], ...] | None:
    """Return one complete, order-stable outline identity or fail closed.

    A full-outline row is exact only when every item has a footprint and every
    present runtime id is unique.  Anonymous items remain usable for a semantic
    full-outline action, but never for the cross-action Mirror Eye join.
    """

    cells_by_runtime: dict[int, int] = {}
    anonymous_cells: list[int] = []
    rows = list(_iter_dicts(items))
    if not rows:
        return None
    for item in rows:
        cells = _outline_item_cells(item)
        if cells is None:
            return None
        raw_runtime_id = item.get("runtime_id")
        runtime_id = (
            raw_runtime_id
            if type(raw_runtime_id) is int and raw_runtime_id > 0
            else None
        )
        if runtime_id is None:
            if require_runtime_ids:
                return None
            anonymous_cells.append(cells)
            continue
        if runtime_id in cells_by_runtime:
            return None
        cells_by_runtime[runtime_id] = cells

    identity = sorted(cells_by_runtime.items())
    identity.extend(
        (-index, cells)
        for index, cells in enumerate(sorted(anonymous_cells), start=1)
    )
    return tuple(identity) if identity else None


def _outline_totals_from_items(items: Any) -> tuple[int, int] | None:
    identity = _validated_outline_identity_cells(
        items,
        require_runtime_ids=False,
    )
    if identity is None:
        return None
    return len(identity), sum(cells for _runtime_id, cells in identity)


def _mirror_quality_runtime_ids(snapshot: dict[str, Any]) -> frozenset[int] | None:
    identity_sets: set[frozenset[int]] = set()
    row_groups = (
        snapshot.get("action_result_rows"),
        _dig(snapshot, "ui_contract", "actions", "results"),
    )
    seen_rows: set[int] = set()
    for rows in row_groups:
        for row in _iter_dicts(rows):
            if not isinstance(row, dict):
                continue
            row_id = id(row)
            if row_id in seen_rows:
                continue
            seen_rows.add(row_id)
            if str(row.get("action_id") or "") != str(MIRROR_EYE_ACTION_ID):
                continue
            runtime_ids: set[int] = set()
            items = list(
                _iter_dicts(
                    row.get("revealed_items_detail") or row.get("observed_items")
                )
            )
            if not items:
                return None
            for item in items:
                raw_runtime_id = item.get("runtime_id")
                raw_quality = item.get("quality")
                if (
                    type(raw_runtime_id) is not int
                    or raw_runtime_id <= 0
                    or type(raw_quality) is not int
                    or raw_quality <= 0
                    or raw_runtime_id in runtime_ids
                ):
                    return None
                runtime_ids.add(raw_runtime_id)
            identity_sets.add(frozenset(runtime_ids))
    if len(identity_sets) != 1:
        return None
    return next(iter(identity_sets))


def _apply_ethan_skill_evidence(
    snapshot: dict[str, Any],
    *,
    set_total_count: Callable[[Any, str], None],
    set_total_grid_target: Callable[[Any, str], None],
    source_notes: list[str],
) -> None:
    mirror_runtime_ids = _mirror_quality_runtime_ids(snapshot)
    full_outline_identities: set[tuple[tuple[int, int], ...]] = set()
    invalid_semantic_full_outline = False
    saw_partial_outline = False

    for row in _iter_skill_reveal_dict_rows(snapshot):
        if _safe_int(row.get("hero_id")) != ETHAN_HERO_ID:
            continue
        skill_id = _safe_int(row.get("skill_id"))
        items = row.get("observed_items") or row.get("revealed_items_detail") or ()
        if skill_id == ETHAN_SKILL_R1_OUTLINE:
            totals = _outline_totals_from_items(items)
            saw_partial_outline = bool(list(_iter_dicts(items)))
            if totals is not None:
                source_notes.append(
                    f"ethan_skill_r1_outline:{totals[0]}:{totals[1]}"
                )
            continue
        if skill_id == ETHAN_SKILL_FULL_OUTLINE:
            identity = _validated_outline_identity_cells(
                items,
                require_runtime_ids=False,
            )
            if identity is None:
                invalid_semantic_full_outline = True
            else:
                full_outline_identities.add(identity)
            continue
        if skill_id in ETHAN_QUALITY_OUTLINE_SKILL_IDS:
            saw_partial_outline = True
        if skill_id not in ETHAN_QUALITY_OUTLINE_SKILL_IDS or not mirror_runtime_ids:
            continue
        identity = _validated_outline_identity_cells(
            items,
            require_runtime_ids=True,
        )
        if identity is None:
            continue
        outline_runtime_ids = frozenset(runtime_id for runtime_id, _cells in identity)
        if outline_runtime_ids == mirror_runtime_ids:
            full_outline_identities.add(identity)

    if invalid_semantic_full_outline or len(full_outline_identities) != 1:
        if invalid_semantic_full_outline or len(full_outline_identities) > 1:
            source_notes.append("ethan_full_outline_identity_conflict")
        # R1-R4 partial reveal: no exact total — the grid used to fall to the map prior (the author's
        # 2601 design cases: truth 135 -> R1-R4 101-122 under; truth 186 -> R1 235 over). Occupancy
        # estimator anchors the grid to the revealed footprints instead. DEFAULT ON (author 2026-07-04,
        # net-gain verified: real-58 R1-R4 MAE 15.4%->5.5%, overshoot 3%, R5/non-ethan untouched);
        # kill-switch ETHAN_DISABLE_OCCUPANCY_GRID=1.
        if (
            os.environ.get("ETHAN_DISABLE_OCCUPANCY_GRID") != "1"
            and not snapshot.get("_ethan_disable_occupancy_target")
            and saw_partial_outline
        ):
            occ = _ethan_occupancy_grid_estimate(_minimap_items_from_snapshot(snapshot))
            if occ is not None:
                estimate, parts = occ
                set_total_grid_target(estimate, "ethan_occupancy_grid_estimate")
                source_notes.append(
                    "ethan_occupancy_grid_parts:"
                    f"deep{parts['raw_deepest']}:adj{parts['adjusted_rect']}:"
                    f"floor{parts['full_row_floor']}:seen{parts['distinct']}"
                )
        return
    full_outline_identity = next(iter(full_outline_identities))
    count = len(full_outline_identity)
    cells = sum(item_cells for _runtime_id, item_cells in full_outline_identity)
    set_total_count(count, "ethan_skill_full_outline_count")
    set_total_grid_target(cells, "ethan_skill_full_outline_cells")


def _hero_skill_quality_rows_with_footprints(
    snapshot: dict[str, Any],
) -> Iterable[tuple[str, dict[str, Any]]]:
    """Carry an Ivan R1 outline into R2/R3 only for the same physical item.

    Cross-runtime "largest still-unknown" bounds and Carlos category footprints
    are intentionally deferred: the hotfix1 real-sample A/B found mixed count
    movement and worse quote MAE. Same-runtime cells are exact and independently
    reversible, without inventing identity, value, or a category distribution.
    """
    rows = list(_iter_skill_reveal_dict_rows(snapshot))
    context = snapshot.get("ui_contract")
    context = context.get("context") if isinstance(context, dict) else {}
    raw_hero = (
        context.get("hero") if isinstance(context, dict) else None
    ) or snapshot.get("hero")
    hero = normalize_hero_key(raw_hero)
    if _is_unknown_hero(hero):
        reveal_hero_ids = {
            _safe_int(row.get("hero_id"))
            for row in rows
            if _safe_int(row.get("hero_id")) is not None
        }
        if len(reveal_hero_ids) == 1:
            hero = HERO_BY_ID.get(next(iter(reveal_hero_ids)), hero)

    if hero != "ivan":
        for row_index, row in enumerate(rows):
            if _is_maria_skill_quality_reveal_row(row):
                continue
            skill_id = str(row.get("skill_id") or "")
            prefix = f"skill_{skill_id or row_index}"
            for item in _iter_dicts(
                row.get("observed_items") or row.get("revealed_items_detail")
            ):
                if _quality_number_to_key(item.get("quality")) is not None:
                    yield prefix, item
        return

    outline_footprints: dict[int, tuple[int, int | None]] = {}
    outline_conflicts: set[int] = set()
    for row in rows:
        if (
            _safe_int(row.get("hero_id")) != IVAN_HERO_ID
            or _safe_int(row.get("skill_id")) != IVAN_SKILL_R1_OUTLINE
        ):
            continue
        for item in _iter_dicts(
            row.get("observed_items") or row.get("revealed_items_detail")
        ):
            runtime_id = _safe_int(item.get("runtime_id"))
            cells = _outline_item_cells(item)
            if runtime_id is None or cells is None:
                continue
            shape_identity = _outline_item_shape_identity(item)
            previous = outline_footprints.get(runtime_id)
            if previous is not None and (
                previous[0] != cells
                or (
                    previous[1] is not None
                    and shape_identity is not None
                    and previous[1] != shape_identity
                )
            ):
                outline_conflicts.add(runtime_id)
                continue
            previous_shape = previous[1] if previous is not None else None
            outline_footprints[runtime_id] = (
                cells,
                shape_identity if shape_identity is not None else previous_shape,
            )
    for runtime_id in outline_conflicts:
        outline_footprints.pop(runtime_id, None)

    for row_index, row in enumerate(rows):
        if _is_maria_skill_quality_reveal_row(row):
            continue
        skill_id_int = _safe_int(row.get("skill_id"))
        skill_id = str(row.get("skill_id") or "")
        prefix = f"skill_{skill_id or row_index}"
        items = list(
            _iter_dicts(
                row.get("observed_items") or row.get("revealed_items_detail")
            )
        )
        for item in items:
            if _quality_number_to_key(item.get("quality")) is None:
                continue
            if (
                os.environ.get("BIDKING_DISABLE_IVAN_SAME_RUNTIME_FOOTPRINT")
                == "1"
                or _safe_int(row.get("hero_id")) != IVAN_HERO_ID
                or skill_id_int not in IVAN_MAX_UNKNOWN_QUALITY_SKILL_IDS
                or _outline_item_cells(item) is not None
            ):
                yield prefix, item
                continue

            runtime_id = _safe_int(item.get("runtime_id"))
            footprint = (
                outline_footprints.get(runtime_id) if runtime_id is not None else None
            )
            exact_cells = footprint[0] if footprint is not None else None
            if exact_cells is not None:
                enriched = dict(item)
                enriched["cells"] = exact_cells
                yield (
                    f"{prefix}_ivan_same_runtime_cells_{exact_cells}",
                    enriched,
                )
                continue
            yield prefix, item


def _iter_quality_reveal_item_rows(
    snapshot: dict[str, Any],
) -> Iterable[tuple[str, dict[str, Any]]]:
    runtime_qualities = _runtime_quality_by_observed_id(snapshot)
    resolve_treasure_top_quality = (
        os.environ.get("BIDKING_DISABLE_TREASURE_TOP_QUALITY_RESOLVE") != "1"
    )
    has_known_q6 = 6 in runtime_qualities.values()
    for row in _iter_dicts(snapshot.get("public_info_rows")):
        info_id = _safe_int(row.get("info_id"))
        if info_id in PUBLIC_BUCKET_OUTLINE_QUALITY:
            continue
        prefix = f"public_info_{info_id}" if info_id is not None else "public_info"
        for item in _iter_dicts(row.get("revealed_items_detail")):
            if _quality_number_to_key(item.get("quality")) is not None:
                yield prefix, item
    row_groups = (
        ("action_result", snapshot.get("action_result_rows")),
        (
            "action_result",
            _dig(snapshot, "ui_contract", "actions", "results"),
        ),
    )
    seen_rows: set[int] = set()
    for prefix, rows in row_groups:
        for row_idx, row in enumerate(_iter_dicts(rows)):
            if not isinstance(row, dict):
                continue
            row_id = id(row)
            if row_id in seen_rows:
                continue
            seen_rows.add(row_id)
            action_id = str(row.get("action_id") or "")
            source_prefix = (
                f"{prefix}_{action_id}"
                if action_id
                else f"{prefix}_{row_idx}"
            )
            for item in _iter_dicts(row.get("revealed_items_detail")):
                if _quality_number_to_key(item.get("quality")) is not None:
                    yield source_prefix, item
                    continue
                if not (
                    resolve_treasure_top_quality
                    and action_id in TREASURE_HIGHEST_ITEM_FOOTPRINT_ACTION_IDS
                ):
                    continue
                runtime_id = _safe_int(item.get("runtime_id"))
                resolved_quality = (
                    runtime_qualities.get(runtime_id) if runtime_id is not None else None
                )
                resolution = (
                    f"same_runtime_q{resolved_quality}"
                    if resolved_quality is not None
                    else "highest_known_q6" if has_known_q6 else None
                )
                if resolved_quality is None and has_known_q6:
                    resolved_quality = 6
                if resolved_quality is not None and resolution is not None:
                    resolved = dict(item)
                    resolved["quality"] = resolved_quality
                    yield f"{source_prefix}_{resolution}", resolved

    for prefix, item in _hero_skill_quality_rows_with_footprints(snapshot):
        yield prefix, item


_TREASURE_APPRAISAL_CORRELATED_INT_FIELDS = (
    "runtime_id",
    "local_index",
    "item_id",
    "quality",
    "cells",
    "shape_code",
    "shape_key",
    "value",
)
_TREASURE_APPRAISAL_WIRE_CONFLICT_KEY = "_treasure_appraisal_wire_conflict"
_TREASURE_APPRAISAL_SANITIZE_MAX_DEPTH = 64
_TREASURE_APPRAISAL_SANITIZE_MAX_CONTAINERS = 20_000
_TREASURE_APPRAISAL_SANITIZE_MAX_COLLECTION_ITEMS = 20_000
_TREASURE_APPRAISAL_SANITIZE_MAX_TOTAL_ITEMS = 50_000


def _strip_untrusted_treasure_appraisal_markers(
    value: object,
) -> tuple[object, bool]:
    """Strip the old marker from bounded, exact JSON containers.

    This is a public raw-input boundary.  It accepts only exact ``dict``/``list``
    containers, permits acyclic shared references, and rejects active cycles and
    over-limit trees as an empty exact dict.  The limits are container nesting,
    unique container count, one collection size, and aggregate collection items;
    they bound attacker-controlled local snapshots while leaving the engine's
    8k/50k posterior-combination limits unrelated.
    """

    if type(value) is not dict:  # noqa: E721 - public snapshot boundary
        return {}, True

    changed = False
    containers = 0
    total_items = 0
    seen: set[int] = set()
    active: set[int] = set()
    stack: list[tuple[str, object, int]] = [("enter", value, 0)]
    while stack:
        operation, current, depth = stack.pop()
        if operation == "exit":
            active.remove(id(current))
            continue
        current_type = type(current)
        if current_type not in (dict, list):  # noqa: E721 - exact JSON types
            # A dict/list subclass could run an overridden protocol downstream.
            if isinstance(current, (dict, list)):
                return {}, True
            continue
        current_id = id(current)
        if current_id in active:
            return {}, True
        if current_id in seen:
            continue
        if depth > _TREASURE_APPRAISAL_SANITIZE_MAX_DEPTH:
            return {}, True
        seen.add(current_id)
        containers += 1
        if containers > _TREASURE_APPRAISAL_SANITIZE_MAX_CONTAINERS:
            return {}, True
        active.add(current_id)
        stack.append(("exit", current, depth))
        if current_type is dict:  # noqa: E721 - exact JSON object only
            entries = tuple(dict.items(current))
            if len(entries) > _TREASURE_APPRAISAL_SANITIZE_MAX_COLLECTION_ITEMS:
                return {}, True
            total_items += len(entries)
            if total_items > _TREASURE_APPRAISAL_SANITIZE_MAX_TOTAL_ITEMS:
                return {}, True
            for key, nested in entries:
                if type(key) is not str:  # noqa: E721 - JSON object keys only
                    return {}, True
                if key == _TREASURE_APPRAISAL_WIRE_CONFLICT_KEY:
                    changed = True
                stack.append(("enter", nested, depth + 1))
        else:
            length = list.__len__(current)
            if length > _TREASURE_APPRAISAL_SANITIZE_MAX_COLLECTION_ITEMS:
                return {}, True
            total_items += length
            if total_items > _TREASURE_APPRAISAL_SANITIZE_MAX_TOTAL_ITEMS:
                return {}, True
            for index in range(length):
                stack.append(("enter", list.__getitem__(current, index), depth + 1))

    if not changed:
        return value, False

    payloads: dict[int, object] = {id(value): {}}
    copy_stack: list[object] = [value]
    while copy_stack:
        current = copy_stack.pop()
        payload = payloads[id(current)]
        if type(current) is dict:  # noqa: E721 - scan above froze exact types
            for key, nested in dict.items(current):
                if key == _TREASURE_APPRAISAL_WIRE_CONFLICT_KEY:
                    continue
                if type(nested) in (dict, list):  # noqa: E721 - exact JSON types
                    nested_id = id(nested)
                    nested_payload = payloads.get(nested_id)
                    if nested_payload is None:
                        nested_payload = {} if type(nested) is dict else []  # noqa: E721
                        payloads[nested_id] = nested_payload
                        copy_stack.append(nested)
                    dict.__setitem__(payload, key, nested_payload)
                else:
                    dict.__setitem__(payload, key, nested)
        else:
            for nested in current:
                if type(nested) in (dict, list):  # noqa: E721 - exact JSON types
                    nested_id = id(nested)
                    nested_payload = payloads.get(nested_id)
                    if nested_payload is None:
                        nested_payload = {} if type(nested) is dict else []  # noqa: E721
                        payloads[nested_id] = nested_payload
                        copy_stack.append(nested)
                    list.append(payload, nested_payload)
                else:
                    list.append(payload, nested)
    return payloads[id(value)], True


def _treasure_appraisal_row_has_plain_correlated_wire(row: object) -> bool:
    """Validate target scalars without invoking user-defined protocols."""

    if type(row) is not dict or any(type(key) is not str for key in row):  # noqa: E721
        return False
    revealed_items = dict.get(row, "revealed_items")
    if revealed_items is not None and type(revealed_items) is not int:  # noqa: E721
        return False
    for detail_key in ("revealed_items_detail", "observed_items"):
        details = dict.get(row, detail_key)
        if details is None:
            continue
        if type(details) is not list:  # noqa: E721 - packet JSON array
            return False
        for item in details:
            if type(item) is not dict or any(type(key) is not str for key in item):  # noqa: E721
                return False
            for field_name in _TREASURE_APPRAISAL_CORRELATED_INT_FIELDS:
                value = dict.get(item, field_name)
                if value is not None and type(value) is not int:  # noqa: E721
                    return False
    return True


def _treasure_appraisal_target_action_row_ids(
    snapshot: object,
) -> frozenset[int]:
    """Return target row identities using exact packet scalars only."""

    if type(snapshot) is not dict:  # noqa: E721 - exact product snapshot
        return frozenset()
    rows_by_owner = (
        dict.get(snapshot, "action_result_rows"),
        _dig(snapshot, "ui_contract", "actions", "results"),
    )
    row_ids: set[int] = set()
    targeted_ids = {int(value) for value in TREASURE_HIGHEST_ITEM_VALUE_ACTION_IDS}
    for rows in rows_by_owner:
        if type(rows) is not list:  # noqa: E721 - monitor JSON list
            continue
        for row in rows:
            if not isinstance(row, dict):
                continue
            raw_action_id = dict.get(row, "action_id")
            if type(raw_action_id) is int and raw_action_id in targeted_ids:  # noqa: E721
                row_ids.add(id(row))
            elif (
                type(raw_action_id) is str  # noqa: E721 - malformed target mirror
                and raw_action_id.isascii()
                and raw_action_id.isdigit()
                and int(raw_action_id) in targeted_ids
            ):
                row_ids.add(id(row))
    return frozenset(row_ids)


def _quarantine_malformed_treasure_appraisal_rows(
    snapshot: dict[str, Any],
) -> tuple[dict[str, Any], bool]:
    """Remove malformed target rows before any generic item consumer can inspect them."""

    sanitized, _marker_removed = _strip_untrusted_treasure_appraisal_markers(
        snapshot
    )
    if type(sanitized) is not dict:  # noqa: E721 - typed public boundary
        return snapshot, False
    snapshot = sanitized
    target_row_ids = _treasure_appraisal_target_action_row_ids(snapshot)
    if not target_row_ids:
        return snapshot, False

    root_rows = dict.get(snapshot, "action_result_rows")
    ui_contract = dict.get(snapshot, "ui_contract")
    actions = (
        dict.get(ui_contract, "actions")
        if type(ui_contract) is dict  # noqa: E721 - exact JSON object
        else None
    )
    ui_rows = (
        dict.get(actions, "results")
        if type(actions) is dict  # noqa: E721 - exact JSON object
        else None
    )
    malformed = False
    if type(root_rows) is list:  # noqa: E721 - monitor JSON list
        malformed = any(
            id(row) in target_row_ids
            and not _treasure_appraisal_row_has_plain_correlated_wire(row)
            for row in root_rows
        )
    if not malformed and type(ui_rows) is list:  # noqa: E721
        malformed = any(
            id(row) in target_row_ids
            and type(row) is dict  # noqa: E721
            and (
                dict.get(row, "revealed_items_detail") is not None
                or dict.get(row, "observed_items") is not None
            )
            and not _treasure_appraisal_row_has_plain_correlated_wire(row)
            for row in ui_rows
        )
    if not malformed:
        return snapshot, False

    payload = dict.copy(snapshot)
    if type(root_rows) is list:  # noqa: E721
        payload["action_result_rows"] = [
            row for row in root_rows if id(row) not in target_row_ids
        ]
    if type(ui_contract) is dict and type(actions) is dict and type(ui_rows) is list:  # noqa: E721
        filtered_actions = dict.copy(actions)
        filtered_actions["results"] = [
            row for row in ui_rows if id(row) not in target_row_ids
        ]
        filtered_ui_contract = dict.copy(ui_contract)
        filtered_ui_contract["actions"] = filtered_actions
        payload["ui_contract"] = filtered_ui_contract
    return payload, True


def _iter_observed_item_fact_rows(
    snapshot: dict[str, Any],
    *,
    quarantined_action_row_ids: frozenset[int] = frozenset(),
) -> Iterable[tuple[str, str, dict[str, Any]]]:
    """Yield every raw item row that may carry one part of a correlated item fact."""
    for row_index, row in enumerate(_iter_dicts(snapshot.get("public_info_rows"))):
        info_id = str(row.get("info_id") or row_index)
        for item in _iter_dicts(
            row.get("revealed_items_detail") or row.get("observed_items")
        ):
            yield f"public_info_{info_id}", "", item

    action_groups = (
        snapshot.get("action_result_rows"),
        _dig(snapshot, "ui_contract", "actions", "results"),
    )
    seen_rows: set[int] = set()
    for rows in action_groups:
        for row_index, row in enumerate(_iter_dicts(rows)):
            if id(row) in quarantined_action_row_ids:
                continue
            if id(row) in seen_rows:
                continue
            seen_rows.add(id(row))
            action_id = str(row.get("action_id") or "")
            source = f"action_{action_id or row_index}"
            for item in _iter_dicts(
                row.get("revealed_items_detail") or row.get("observed_items")
            ):
                yield source, action_id, item

    for row_index, row in enumerate(_iter_skill_reveal_dict_rows(snapshot)):
        skill_id = str(row.get("skill_id") or row_index)
        for item in _iter_dicts(
            row.get("observed_items") or row.get("revealed_items_detail")
        ):
            yield f"skill_{skill_id}", "", item

    # The live bridge publishes category/shape singleton promotion as one generation-bound domain
    # plus the corresponding minimap row.  Consume that row as a correlated physical item only when
    # both copies agree exactly on runtime/local identity, quality, cells, item ID and value.  A bare
    # minimap value, an ambiguous domain or conflicting duplicate sources remains display-only.
    domain_by_runtime = {
        int(domain["runtime_id"]): domain
        for domain in _normalized_physical_candidate_domain_rows(snapshot)
        if domain.get("exact_item_id") is not None
        and domain.get("exact_value") is not None
        and domain.get("hard_eligible") is True
    }
    seen_domain_runtime_ids: set[int] = set()
    for item in _minimap_items_from_snapshot(snapshot):
        runtime_id = _safe_int(item.get("runtime_id"))
        if runtime_id is None or runtime_id in seen_domain_runtime_ids:
            continue
        domain = domain_by_runtime.get(int(runtime_id))
        if domain is None:
            continue
        local_index = _safe_int(item.get("local_index"))
        domain_local_index = _safe_int(domain.get("local_index"))
        quality = _safe_int(item.get("quality"))
        cells = _outline_item_cells(item)
        item_id = _safe_int(item.get("item_id"))
        value = _safe_int(item.get("value"))
        if (
            local_index != domain_local_index
            or quality != _safe_int(domain.get("quality"))
            or cells != _safe_int(domain.get("cells"))
            or item_id != _safe_int(domain.get("exact_item_id"))
            or value != _safe_int(domain.get("exact_value"))
        ):
            continue
        seen_domain_runtime_ids.add(int(runtime_id))
        yield "physical_category_domain", "", item


def _correlated_known_item_facts(
    snapshot: dict[str, Any],
    *,
    target_quality: int,
    catalog: tuple[tuple[tuple[int, int], ...], tuple[tuple[int, int, int], ...], str],
    quarantined_action_row_ids: frozenset[int] = frozenset(),
) -> tuple[tuple[str, int, int], ...]:
    """Merge value/footprint rows only when they identify the same physical collectible."""
    pairs, catalog_rows, catalog_status = catalog
    if catalog_status != "ok":
        return ()
    pair_set = set(pairs)
    catalog_by_id = {
        int(item_id): (int(value), int(cells))
        for item_id, value, cells in catalog_rows
    }

    parent: dict[str, str] = {}

    def find(key: str) -> str:
        parent.setdefault(key, key)
        while parent[key] != key:
            parent[key] = parent[parent[key]]
            key = parent[key]
        return key

    def union(left: str, right: str) -> None:
        left_root, right_root = find(left), find(right)
        if left_root != right_root:
            parent[right_root] = left_root

    rows: list[
        tuple[list[str], int | None, int | None, int | None, int | None]
    ] = []
    for _, action_id, item in _iter_observed_item_fact_rows(
        snapshot,
        quarantined_action_row_ids=quarantined_action_row_ids,
    ):
        runtime_id = _safe_int(item.get("runtime_id"))
        local_index = _safe_int(item.get("local_index"))
        item_id = _safe_int(item.get("item_id"))
        quality = _safe_int(item.get("quality"))
        cells = _outline_item_cells(item)
        raw_value = _safe_float(item.get("value"))
        value = None
        if (
            raw_value is not None
            and raw_value > 0
            and math.isfinite(raw_value)
            and abs(raw_value - round(raw_value)) <= 0.0001
        ):
            value = int(round(raw_value))

        # 至宝估价的 value-only 行只补全所有同价目录项一致同意的字段。若格子有歧义，则必须
        # 等待同 runtime/local-index 的轮廓行提供，不能拿最小格伪装成精确事实。
        if action_id in TREASURE_HIGHEST_ITEM_VALUE_ACTION_IDS and value is not None:
            appraisal_rows = _catalog_items_by_value().get(value) or ()
            appraisal_qualities = {row[0] for row in appraisal_rows}
            appraisal_cells = {row[1] for row in appraisal_rows}
            if quality is None and len(appraisal_qualities) == 1:
                quality = next(iter(appraisal_qualities))
            if cells is None and len(appraisal_cells) == 1:
                cells = next(iter(appraisal_cells))

        identities: list[str] = []
        if runtime_id is not None:
            identities.append(f"runtime:{runtime_id}")
        if local_index is not None:
            identities.append(f"local:{local_index}")
        if not identities:
            # No physical identity: require a self-contained row and deduplicate equal copies.  True
            # duplicate collectibles remain distinct whenever the packet supplies runtime/local IDs.
            if quality == target_quality and cells and value:
                identities.append(
                    f"anonymous:q{target_quality}:{item_id or 0}:{int(cells)}:{int(value)}"
                )
            else:
                continue
        for identity in identities:
            find(identity)
        for identity in identities[1:]:
            union(identities[0], identity)
        rows.append((identities, quality, cells, value, item_id))

    grouped: dict[str, dict[str, set[Any]]] = {}
    for identities, quality, cells, value, item_id in rows:
        root = find(identities[0])
        group = grouped.setdefault(
            root,
            {
                "identities": set(),
                "qualities": set(),
                "cells": set(),
                "values": set(),
                "item_ids": set(),
            },
        )
        group["identities"].update(identities)
        if quality is not None:
            group["qualities"].add(int(quality))
        if cells is not None and cells > 0:
            group["cells"].add(int(cells))
        if value is not None and value > 0:
            group["values"].add(int(value))
        if item_id is not None:
            group["item_ids"].add(int(item_id))

    facts: list[tuple[str, int, int]] = []
    for group in grouped.values():
        qualities = group["qualities"]
        cells_set = group["cells"]
        values = group["values"]
        item_ids = group["item_ids"]
        if qualities != {target_quality} or len(cells_set) != 1 or len(values) != 1:
            continue
        cells = next(iter(cells_set))
        value = next(iter(values))
        if (value, cells) not in pair_set:
            continue
        if item_ids and any(
            catalog_by_id.get(item_id) != (value, cells) for item_id in item_ids
        ):
            continue
        identities = sorted(str(identity) for identity in group["identities"])
        facts.append((identities[0], int(cells), int(value)))
    return tuple(sorted(set(facts)))


