def _iter_coarse_quality_reveal_items(
    snapshot: dict[str, Any],
) -> Iterable[tuple[str, dict[str, Any]]]:
    for source_prefix, item in _iter_quality_reveal_item_rows(snapshot):
        if _is_coarse_quality_reveal_item(item):
            yield source_prefix, item


def _random_sample_quality_counts(snapshot: dict[str, Any]) -> dict[str, int]:
    """Per-quality counts of the uniform-random public sample (200028 "随机显示N件藏品",
    author-confirmed whole-vault uniform random). Deduped by reveal identity (runtime_id) so
    the same physical item shown across rounds counts once. This is a random SAMPLE of the vault
    → its quality proportions estimate the population's, consumed as a hypergeometric likelihood
    in the combo weight (`_random_sample_hypergeom_log`). Only 200028 for now (the one source the
    author confirmed uniform-random); other reveal channels (skill outlines, 宝光鉴定) are targeted,
    not uniform, so excluded."""
    counts: dict[str, int] = {}
    seen: set[tuple[str, str]] = set()
    for source_prefix, item in _iter_quality_reveal_item_rows(snapshot):
        if not source_prefix.startswith("public_info_200028"):
            continue
        key = _quality_number_to_key(item.get("quality"))
        if key is None:
            continue
        identity = _quality_reveal_item_identity(item, key, fallback=f"{source_prefix}-{id(item)}")
        if identity in seen:
            continue
        seen.add(identity)
        counts[key] = counts.get(key, 0) + 1
    return counts


RANDOM_SAMPLE_RED_GATE_DEFAULT_STRENGTH = 2.0  # workflow-calibrated for the gated form (see below)


def _random_sample_hypergeom_log(
    counts: dict[str, int],
    evidence: RefEvidence,
    probs: dict[str, float] | None = None,
) -> float:
    """Multivariate-hypergeometric log-likelihood of the 200028 uniform-random sample given a combo.

    The sample (evidence.random_sample = deduped per-quality counts s_k, drawn WITHOUT replacement
    from the vault) has, under a hypothesized population c_k per quality, probability ∝ Π_k C(c_k, s_k)
    (the -log C(total, N) normaliser is constant across combos of the same total, so dropped). A combo
    that can't even contain the sampled items (s_k > c_k) is impossible. This replaces the "sample →
    min-count floor only" behaviour with a proper likelihood: a red-rich sample lifts red counts, a
    red-poor one lowers them — fixing ahmed red UNDER-count when 200028 shows many reds (4511 R4:
    sample 3red/9 → truth 10red, engine was 5). Author-confirmed 200028 is whole-vault uniform random.

    TWO modes (both DEFAULT OFF):

    (1) BLANKET — env AHMAD_ENABLE_RANDOM_SAMPLE_HYPERGEOM=1, strength AHMAD_RANDOM_SAMPLE_STRENGTH.
    ⚠️ FULL-POOL CALIBRATION DONE (workflow 2026-07-02, DECISIVE): the blanket form is NET-NEGATIVE and
    must NEVER be default-ON. Coverage is only ~5% ahmed / ~6% aisha (200028 present); the 9-item sample
    is too weak for rare tiers — when a tier shows 0 in the sample the OTHER tiers' terms indirectly
    PRESS it DOWN, and the harm pool (red-empty sample but truth red>0, ahmed N=65) dwarfs the benefit
    pool (red-rich N=17); gold MAE degrades monotonically with strength; combined (red+gold) MAE is worse
    than OFF at EVERY strength. Kept for research only.

    (2) RED-RICH LIFT-ONLY GATE — env AHMAD_ENABLE_RANDOM_SAMPLE_RED_GATE=1, strength
    AHMAD_RANDOM_SAMPLE_STRENGTH (defaults to 2.0), threshold AHMAD_RANDOM_SAMPLE_RED_GATE_MIN_SRED
    (defaults to 2). Applies ONLY the red (q6) term, and ONLY when the sample shows >=MIN_SRED reds AND is
    red-RICHER than the current prior (s_red/N > probs['q6']). "lift-only": a red-empty sample (s_red=0)
    is a pure no-op (harm pool eliminated), a red-poor sample is a no-op (never presses red down), a
    red-rich sample lifts red via log C(c_red,s_red); the s_red>c_red floor is a legitimate lower bound.
    ⚠️ VERIFIED FULL-POOL A/B (2026-07-02, MAIN data, 145 ahmed / 25 aisha 200028-covered samples):
    this gate does NOT net-improve. ahmed red MAE 0.421→0.421 (FLAT), aisha red 1.16→1.12 (marginal) with
    aisha GOLD MAE 1.68→1.76 (WORSE). The prior workflow lead 'ahmed 0.41→0.35 / aisha 2.20→1.60' did NOT
    reproduce — a 9-item uniform sample is too weak to estimate red count even gated (2 reds in 9 still
    over-represents a low-red vault: e.g. 5603 truth red 2 lifted to 5). ONLY a genuinely strong red-rich
    sample helps cleanly (2532 R4 sR=3: red 5→8=truth, gold 9→6=truth). So this stays DEFAULT-OFF; it is
    kept env-gated for that strong-red-rich regime only. No-op guarantee verified (81 s_red=0 rows
    byte-identical OFF vs gate). See memory ahmed-random-sample-red-rate-underused."""
    blanket = os.environ.get("AHMAD_ENABLE_RANDOM_SAMPLE_HYPERGEOM") == "1"
    red_gate = os.environ.get("AHMAD_ENABLE_RANDOM_SAMPLE_RED_GATE") == "1"
    if not (blanket or red_gate):
        return 0.0
    sample = evidence.random_sample
    if not sample:
        return 0.0

    if red_gate:
        # Red-rich + lift-only: q6 term only, gated on the sample being red-richer than the prior.
        try:
            strength = float(
                os.environ.get(
                    "AHMAD_RANDOM_SAMPLE_STRENGTH", RANDOM_SAMPLE_RED_GATE_DEFAULT_STRENGTH
                )
            )
        except (TypeError, ValueError):
            strength = RANDOM_SAMPLE_RED_GATE_DEFAULT_STRENGTH
        if strength <= 0:
            return 0.0
        total_sampled = sum(int(v) for v in sample.values())
        s_red = int(sample.get("q6", 0))
        if total_sampled <= 0 or s_red <= 0:
            return 0.0  # no red sampled -> pure no-op (never press red down)
        # A single red in a ~9-item sample (~11%) is within baseline noise (map red rate ~7.4%) and
        # a lift there over-shoots (full-pool A/B: s_red==1 firings hurt red MAE). Require >=2 sampled
        # reds (~22%, ~3x baseline) so the gate only fires on genuine red-enrichment.
        try:
            min_sred = int(os.environ.get("AHMAD_RANDOM_SAMPLE_RED_GATE_MIN_SRED", 2))
        except (TypeError, ValueError):
            min_sred = 2
        if s_red < min_sred:
            return 0.0
        prior_red = float((probs or {}).get("q6", 0.0))
        if s_red <= prior_red * total_sampled:
            return 0.0  # sample not red-richer than the prior -> do nothing (lift-only gate)
        c_red = int(counts.get("q6", 0))
        if s_red > c_red:
            return -60.0  # combo cannot contain the sampled reds -> ~impossible (legitimate floor)
        return strength * (_log_fact(c_red) - _log_fact(s_red) - _log_fact(c_red - s_red))

    # Blanket form (research only, default OFF).
    try:
        strength = float(os.environ.get("AHMAD_RANDOM_SAMPLE_STRENGTH", 1.0))
    except (TypeError, ValueError):
        strength = 1.0
    if strength <= 0:
        return 0.0
    logw = 0.0
    for key, s in sample.items():
        s = int(s)
        if s <= 0:
            continue
        c = int(counts.get(key, 0))
        if s > c:
            return -60.0  # combo cannot contain the sampled items of this quality -> ~impossible
        logw += _log_fact(c) - _log_fact(s) - _log_fact(c - s)
    return strength * logw


def _coarse_quality_reveal_floors(
    snapshot: dict[str, Any],
    *,
    source_notes: list[str],
    exact_total_count: int | None = None,
    hard_fixed_counts: Mapping[str, int] | None = None,
    hard_quality_cells: Mapping[str, float] | None = None,
    hard_quality_values: Mapping[str, float] | None = None,
) -> tuple[
    dict[str, int],
    dict[str, float],
    dict[str, float],
    dict[str, float],
    dict[str, int],
    dict[str, int],
    dict[str, float],
    dict[str, int],
]:
    counts = {key: 0 for key in QUALITY_KEYS}
    cell_floors: dict[str, float] = {}
    cell_floor_item_counts: dict[str, int] = {}
    value_floors: dict[str, float] = {}
    catalog_min_value_floors: dict[str, float] = {}
    value_floor_item_counts: dict[str, int] = {}
    split_counts = {key: 0 for key in LOW_SPLIT_KEYS}
    split_value_floors: dict[str, float] = {}
    seen: set[tuple[str, str]] = set()
    floor_seen: set[tuple[str, str]] = set()
    count_source_prefixes: set[str] = set()
    # bug② (2026-07-02): draw heroes (gabriela/sophie) reveal random shaped OUTLINES via skill/tools;
    # those belong in the coarse count but the gate below (= not _has_shape_reveal) dropped them, so a
    # shaped skill-revealed item contributed only a cell_floor, never a count -> min_counts undercounts
    # the revealed low-tier/red items -> the multinomial then over-deposits phantom red (gabriela lib:
    # red bias +3.29, MAE 3.69). Count skill/action shaped outlines too (dedup by runtime_id below),
    # including fully-disclosed catalog items (item_id+value+shape). The latter have value/cell floor
    # consumers but no separate live count consumer; excluding them produced a split-brain state where
    # q6 knew the item's cells/value but not that another physical red existed (2543 R4: three distinct
    # red runtimes displayed as 2/2/3). DRAW-HERO gated: aisha's skill reveals are a different
    # exact-count-lock mechanic and live-carry 40-70 shaped reveals per round that would double-count,
    # so restrict to draw heroes -> aisha/ahmed provably no-op. Measured (65 gabriela / 310 aisha /
    # 1180 ahmed, offline replay): gabriela red bias +3.29->+2.29, MAE 3.69->2.63, 36 samples all toward
    # truth & 0 away; aisha/ahmed byte-unchanged (incl a live aisha capture WITH shaped reveals present);
    # 200028 random-reveal invariant + full test suite unchanged. Rollback: env
    # AHMAD_DISABLE_DRAW_SHAPED_OUTLINE_COUNT=1. sophie (also draw) shares the path; its live effect is
    # not yet offline-verifiable (no live capture) — revisit via uploaded ref_inputs.
    _ctx = snapshot.get("ui_contract") if isinstance(snapshot.get("ui_contract"), dict) else {}
    _ctx = _ctx.get("context") if isinstance(_ctx, dict) and isinstance(_ctx.get("context"), dict) else {}
    _bug2_hero = (_ctx.get("hero") if isinstance(_ctx, dict) else None) or snapshot.get("hero")
    _count_draw_shaped_outline = (
        os.environ.get("AHMAD_DISABLE_DRAW_SHAPED_OUTLINE_COUNT") != "1"
        and normalize_hero_key(_bug2_hero) in _draw_hero_count_keys()
    )

    # Two skills can reveal the SAME physical item (same runtime_id): e.g. gabriela 二抽 gives the full
    # item (item_id+value+shape) while 宝光四鉴 gives quality-only (item_id/value=None). Floors dedup by
    # runtime_id, and in row order the value-less quality-only reveal would claim the identity FIRST ->
    # `floor_seen` then skips the value-bearing twin -> the identified red (明红) loses its exact catalog
    # value floor and falls back to the quality/drop-table prior. (gabriela 2401 R4: 氦-3燃料罐 313.2k
    # floor dropped -> red_value floor 190k, headline "直接降下来".) Pre-resolve the RICHEST reveal per
    # identity (has-value, then value, then cells) so the floor accumulates from the item that actually
    # carries the price, independent of reveal order. Counts (`seen`) are unaffected -- 1 red either way.
    # Materialize once: treasure top-item rows may be resolved into synthetic quality-bearing dicts.
    # Both passes below must see the SAME objects so the richest-reveal id comparison stays stable.
    reveal_rows = list(_iter_quality_reveal_item_rows(snapshot))
    maria_shape_red_items, maria_shape_red_status = (
        _maria_full_warehouse_shape_red_items(
            snapshot,
            exact_total_count=exact_total_count,
            hard_fixed_counts=hard_fixed_counts or {},
            hard_quality_cells=hard_quality_cells or {},
            hard_quality_values=hard_quality_values or {},
            known_reveal_rows=reveal_rows,
        )
    )
    if maria_shape_red_status == "applied":
        reveal_rows.extend(
            (MARIA_FULL_WAREHOUSE_SHAPE_RED_NOTE, item)
            for item in maria_shape_red_items
        )
        source_notes.append(
            f"{MARIA_FULL_WAREHOUSE_SHAPE_RED_NOTE}:"
            f"count:{len(maria_shape_red_items)}:shape:4x5"
        )
    elif maria_shape_red_status not in {
        "disabled",
        "hero_out_of_scope",
        "phase_out_of_scope",
        "missing_full_warehouse",
        "missing_exact_total_count",
        "no_unmarked_5x4_outline",
    }:
        source_notes.append(
            f"{MARIA_FULL_WAREHOUSE_SHAPE_RED_NOTE}_suppressed:"
            f"{maria_shape_red_status}"
        )
    for prefix in sorted({
        source_prefix
        for source_prefix, _item in reveal_rows
        if "_same_runtime_cells_" in source_prefix
    }):
        source_notes.append(f"hero_skill_footprint:{prefix}")
    for prefix in sorted({
        source_prefix
        for source_prefix, _item in reveal_rows
        if "_same_runtime_q" in source_prefix or source_prefix.endswith("_highest_known_q6")
    }):
        source_notes.append(f"treasure_top_quality_resolved:{prefix}")
    floor_rep: dict[tuple[str, str], tuple[tuple[int, float, int], int]] = {}
    for source_prefix, item in reveal_rows:
        rep_key = _quality_number_to_key(item.get("quality"))
        if rep_key is None:
            continue
        rep_identity = _quality_reveal_item_identity(
            item, rep_key, fallback=f"floor-{source_prefix}-{id(item)}"
        )
        rep_value = _revealed_item_value_for_floor(item, rep_key) or 0.0
        rep_cells = (
            _safe_int(item.get("cells"))
            or _shape_cells(item.get("shape_code") or item.get("shape_key"))
            or 0
        )
        rep_rank = (1 if rep_value > 0 else 0, float(rep_value), int(rep_cells))
        prev = floor_rep.get(rep_identity)
        if prev is None or rep_rank > prev[0]:
            floor_rep[rep_identity] = (rep_rank, id(item))

    for source_prefix, item in reveal_rows:
        quality = _safe_int(item.get("quality"))
        if quality is None:
            continue
        key = _quality_number_to_key(quality)
        if key is None:
            continue

        _count_this = _is_coarse_quality_reveal_item(item)
        if source_prefix == MARIA_FULL_WAREHOUSE_SHAPE_RED_NOTE:
            _count_this = True
        if (
            not _count_this
            and _count_draw_shaped_outline
            and source_prefix.startswith(("skill_", "action_result"))
            and _has_shape_reveal(item)
        ):
            # A complete reveal is still a revealed physical item. Runtime/local identity dedupe below
            # prevents a quality-only row and its later complete reveal from counting twice.
            _count_this = True
        if _count_this:
            identity = _quality_reveal_item_identity(
                item,
                key,
                fallback=f"{source_prefix}-{id(item)}",
            )
            if identity not in seen:
                seen.add(identity)
                counts[key] += 1
                count_source_prefixes.add(source_prefix)
                split_key = LOW_QUALITY_NUMBER_TO_SPLIT.get(str(quality))
                if split_key is not None:
                    split_counts[split_key] += 1

        floor_identity = _quality_reveal_item_identity(
            item,
            key,
            fallback=f"floor-{source_prefix}-{id(item)}",
        )
        if floor_identity in floor_seen:
            continue
        rep = floor_rep.get(floor_identity)
        if rep is not None and rep[1] != id(item):
            continue  # a richer reveal of this same physical item carries the floor
        floor_seen.add(floor_identity)

        item_cells = _safe_int(item.get("cells"))
        if item_cells is None or item_cells <= 0:
            item_cells = _shape_cells(item.get("shape_code") or item.get("shape_key"))
        if item_cells is not None and item_cells > 0:
            cell_floors[key] = cell_floors.get(key, 0.0) + float(item_cells)
            # Track how many ITEMS actually contributed cells to this floor. Anchor-only reveals
            # (position, no shape -- 沉底大红 as 1-cell marker, see _minimap_item_footprint_known)
            # carry no usable cells and are NOT counted here; the display-center fix uses
            # (min_count - floor_items) as the "revealed but unknown-size" population sized by the
            # quality's grid mean instead of the placeholder (2401 R3: car 15格 known + 2 anchor reds
            # -> center 15+2*3.2≈21.4, truth 21; the old count*mean default ranked options to 15-17).
            cell_floor_item_counts[key] = cell_floor_item_counts.get(key, 0) + 1

        item_value = _revealed_item_value_for_floor(item, key)
        footprint_floor = _revealed_q6_footprint_catalog_floor(item, key)
        if (
            footprint_floor is not None
            and (item_value is None or footprint_floor[1] > item_value)
        ):
            floor_cells, floor_value = footprint_floor
            catalog_min_value_floors[key] = (
                catalog_min_value_floors.get(key, 0.0) + float(floor_value)
            )
            source_notes.append(
                f"{KNOWN_Q6_FOOTPRINT_VALUE_FLOOR_NOTE}:"
                f"{floor_cells}:{int(round(floor_value))}"
            )
        elif item_value is not None and item_value > 0:
            value_floors[key] = value_floors.get(key, 0.0) + float(item_value)
            value_floor_item_counts[key] = value_floor_item_counts.get(key, 0) + 1
            split_key = LOW_QUALITY_NUMBER_TO_SPLIT.get(str(quality))
            if split_key is not None and _is_coarse_quality_reveal_item(item):
                split_value_floors[split_key] = (
                    split_value_floors.get(split_key, 0.0) + float(item_value)
                )

    if any(counts.values()):
        source_notes.append("coarse_quality_reveal_min_counts")
        for prefix in sorted(count_source_prefixes):
            source_notes.append(f"coarse_quality_reveal_source:{prefix}")

    return (
        {key: value for key, value in counts.items() if value > 0},
        cell_floors,
        value_floors,
        catalog_min_value_floors,
        {key: value for key, value in value_floor_item_counts.items() if value > 0},
        {key: value for key, value in split_counts.items() if value > 0},
        split_value_floors,
        {key: value for key, value in cell_floor_item_counts.items() if value > 0},
    )


def _iter_all_item_quality_scan_items(
    snapshot: dict[str, Any],
) -> Iterable[tuple[str, dict[str, Any]]]:
    for row in _iter_dicts(snapshot.get("public_info_rows")):
        info_id = _safe_int(row.get("info_id"))
        if info_id not in ALL_ITEM_QUALITY_PUBLIC_INFO_IDS:
            continue
        prefix = f"public_info_{info_id}" if info_id is not None else "public_info"
        for item in _iter_dicts(row.get("revealed_items_detail")):
            if isinstance(item, dict) and _quality_number_to_key(item.get("quality")) is not None:
                yield prefix, item

    for reveal in _iter_skill_reveal_dict_rows(snapshot):
        skill_id = _safe_int(reveal.get("skill_id"))
        if skill_id != RAVEN_ALL_ITEM_QUALITY_SKILL_ID:
            continue
        prefix = f"skill_{skill_id}"
        for item in _iter_dicts(reveal.get("observed_items") or reveal.get("revealed_items_detail")):
            if isinstance(item, dict) and _quality_number_to_key(item.get("quality")) is not None:
                yield prefix, item


def _count_all_item_quality_scan(snapshot: dict[str, Any]) -> tuple[dict[str, int], int, bool]:
    """Count coarse per-tier items from a full-warehouse quality scan only."""
    counts = {key: 0 for key in QUALITY_KEYS}
    seen: set[tuple[str, str]] = set()
    has_raven_r5_skill = False
    for source_prefix, item in _iter_all_item_quality_scan_items(snapshot):
        if source_prefix.startswith("skill_"):
            has_raven_r5_skill = True
        if not _is_coarse_quality_reveal_item(item):
            continue
        key = _quality_number_to_key(item.get("quality"))
        if key is None:
            continue
        identity = _quality_reveal_item_identity(
            item,
            key,
            fallback=f"{source_prefix}-{id(item)}",
        )
        if identity in seen:
            continue
        seen.add(identity)
        counts[key] += 1
    return counts, len(seen), has_raven_r5_skill


def _all_item_quality_scan_is_complete(
    snapshot: dict[str, Any],
    *,
    hero: str,
    total_count: int | None,
    scan_count: int,
    has_raven_r5_skill: bool,
) -> bool:
    if scan_count <= 0:
        return False
    if total_count is not None and int(total_count) == int(scan_count):
        return True
    if (
        normalize_hero_key(hero) == "raven"
        and has_raven_r5_skill
        and (_snapshot_round_no(snapshot) or 0) >= 5
    ):
        return True
    return False


def _apply_all_item_quality_exact_counts(
    snapshot: dict[str, Any],
    *,
    hero: str,
    total_count: int | None,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    quality_cells: dict[str, float],
    set_total_count,
    source_notes: list[str],
) -> int | None:
    """Lock exact per-tier counts when a full-warehouse quality scan is complete.

    Raven R5 (skill 100301) and matching public all-item-quality rows reveal every
    item's quality. Missing tiers (e.g. no red) must lock to zero, not stay on
    count_prior ranges.
    """
    scanned_counts, scan_count, has_raven_r5_skill = _count_all_item_quality_scan(snapshot)
    if not _all_item_quality_scan_is_complete(
        snapshot,
        hero=hero,
        total_count=total_count,
        scan_count=scan_count,
        has_raven_r5_skill=has_raven_r5_skill,
    ):
        return total_count

    if total_count is None and has_raven_r5_skill and normalize_hero_key(hero) == "raven":
        set_total_count(scan_count, "raven_skill_100301_all_item_quality_count")
        total_count = scan_count

    conflict = False
    for key in QUALITY_KEYS:
        exact = int(scanned_counts.get(key, 0))
        existing = fixed_counts.get(key)
        existing_min = int(min_counts.get(key, 0))
        if existing is not None and int(existing) != exact:
            source_notes.append(f"all_item_quality_{key}_count_conflict")
            source_notes.append(f"hard_conflict:all_item_quality_{key}_count")
            conflict = True
            break
        if existing is None and existing_min > exact:
            source_notes.append(f"all_item_quality_{key}_min_conflict")
            source_notes.append(f"hard_conflict:all_item_quality_{key}_min")
            conflict = True
            break
    if conflict:
        return total_count

    for key in QUALITY_KEYS:
        exact = int(scanned_counts.get(key, 0))
        fixed_counts[key] = exact
        min_counts[key] = exact
        if exact == 0:
            source_notes.append(f"all_item_quality_zero_{key}")
            if key not in quality_cells:
                quality_cells[key] = 0.0
        else:
            source_notes.append(f"all_item_quality_exact_{key}:{exact}")
    source_notes.append("all_item_quality_exact_counts")
    return total_count


def _public_quality_reveal_min_counts(snapshot: dict[str, Any]) -> dict[str, int]:
    counts, _, _, _, _, _, _, _ = _coarse_quality_reveal_floors(
        snapshot, source_notes=[]
    )
    return counts


def _public_quality_reveal_floors(
    snapshot: dict[str, Any],
) -> tuple[dict[str, int], dict[str, float], dict[str, float]]:
    (
        counts,
        cell_floors,
        value_floors,
        _catalog_min_value_floors,
        _value_floor_item_counts,
        _split_counts,
        _split_value_floors,
        _cell_floor_item_counts,
    ) = _coarse_quality_reveal_floors(snapshot, source_notes=[])
    return counts, cell_floors, value_floors


def _shape_cells(value: Any) -> int | None:
    parsed = _safe_int(value)
    if parsed is None:
        return None
    width = parsed // 10
    height = parsed % 10
    if width <= 0 or height <= 0:
        return None
    return width * height


def _apply_public_info_exact_numeric_rows(
    snapshot: dict[str, Any],
    *,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    quality_cells: dict[str, float],
    set_total_count,
    set_total_grid_target,
    source_notes: list[str],
) -> None:
    for row in _iter_dicts(snapshot.get("public_info_rows")):
        info_id = _safe_int(row.get("info_id"))
        value = _safe_float(row.get("value"))
        if info_id is None or value is None:
            continue
        if info_id == 200017:
            set_total_count(value, "public_info_total_item_count")
            continue
        if info_id == 200009:
            set_total_grid_target(value, "public_info_total_cells")
            continue
        quality_key = PUBLIC_EXACT_QUALITY_CELLS_INFO.get(info_id)
        if quality_key is not None:
            existing = quality_cells.get(quality_key)
            if existing is not None and abs(float(existing) - float(value)) > 0.0001:
                source_notes.append(f"public_info_{info_id}_{quality_key}_cells_conflict")
                continue
            quality_cells[quality_key] = float(value)
            source_notes.append(f"public_info_{info_id}_{quality_key}_cells")
            continue
        count_key = PUBLIC_EXACT_QUALITY_COUNT_INFO.get(info_id)
        if count_key is None:
            continue
        count_int = int(round(value))
        existing = fixed_counts.get(count_key)
        if existing is not None and int(existing) != count_int:
            source_notes.append(f"public_info_{info_id}_{count_key}_count_conflict")
            continue
        fixed_counts[count_key] = count_int
        min_counts[count_key] = max(min_counts.get(count_key, 0), count_int)
        source_notes.append(f"public_info_{info_id}_{count_key}_count")


def _runtime_quality_by_observed_id(snapshot: dict[str, Any]) -> dict[int, int]:
    qualities: dict[int, int] = {}

    def ingest(items: Any) -> None:
        for item in _iter_dicts(items):
            runtime_id = _safe_int(item.get("runtime_id"))
            quality = _safe_int(item.get("quality"))
            if runtime_id is None or quality is None or quality <= 0:
                continue
            qualities[runtime_id] = max(qualities.get(runtime_id, 0), quality)

    for row in _iter_skill_reveal_dict_rows(snapshot):
        ingest(row.get("observed_items") or row.get("revealed_items_detail"))
    for row in _iter_dicts(snapshot.get("action_result_rows")):
        ingest(row.get("revealed_items_detail") or row.get("observed_items"))
    for row in _iter_dicts(snapshot.get("public_info_rows")):
        ingest(row.get("revealed_items_detail"))
    uc = snapshot.get("ui_contract") if isinstance(snapshot.get("ui_contract"), dict) else {}
    actions = uc.get("actions") if isinstance(uc.get("actions"), dict) else {}
    for row in actions.get("results") or ():
        if not isinstance(row, dict):
            continue
        ingest(row.get("revealed_items_detail") or row.get("observed_items"))
    return qualities


def _extract_public_max_quality(
    snapshot: dict[str, Any],
    *,
    treasure_appraisal: tuple[str, int, float] | None = None,
) -> int | None:
    max_quality: int | None = None
    runtime_qualities = _runtime_quality_by_observed_id(snapshot)
    has_known_q6 = 6 in runtime_qualities.values()
    resolve_treasure_top_quality = (
        os.environ.get("BIDKING_DISABLE_TREASURE_TOP_QUALITY_RESOLVE") != "1"
    )

    def consider(quality: Any) -> None:
        nonlocal max_quality
        parsed = _safe_int(quality)
        if parsed is None or parsed <= 0:
            return
        max_quality = parsed if max_quality is None else min(max_quality, parsed)

    for row in _iter_dicts(snapshot.get("public_info_rows")):
        if _safe_int(row.get("info_id")) != PUBLIC_MAX_QUALITY_INFO_ID:
            continue
        for item in _iter_dicts(row.get("revealed_items_detail")):
            consider(item.get("quality"))

    for reveal in _iter_dicts(snapshot.get("skill_reveals")):
        if str(reveal.get("skill_id") or "") not in PUBLIC_MAX_QUALITY_SKILL_IDS:
            continue
        for item in _iter_dicts(reveal.get("observed_items")):
            consider(item.get("quality"))

    uc = snapshot.get("ui_contract") if isinstance(snapshot.get("ui_contract"), dict) else {}
    actions = uc.get("actions") if isinstance(uc.get("actions"), dict) else {}
    for row in actions.get("results") or ():
        if not isinstance(row, dict):
            continue
        action_id = str(row.get("action_id") or "")
        if action_id not in PUBLIC_MAX_QUALITY_SKILL_IDS:
            continue
        for item in _iter_dicts(
            row.get("revealed_items_detail") or row.get("observed_items")
        ):
            consider(item.get("quality"))

    treasure_row_groups = (
        snapshot.get("action_result_rows"),
        actions.get("results") or (),
    )
    seen_rows: set[int] = set()
    for rows in treasure_row_groups:
        for row in _iter_dicts(rows):
            if id(row) in seen_rows:
                continue
            seen_rows.add(id(row))
            action_id = str(row.get("action_id") or "")
            if action_id not in TREASURE_HIGHEST_ITEM_ACTION_IDS:
                continue
            for item in _iter_dicts(
                row.get("revealed_items_detail") or row.get("observed_items")
            ):
                quality = _safe_int(item.get("quality"))
                runtime_id = _safe_int(item.get("runtime_id"))
                if quality is None and runtime_id is not None:
                    quality = runtime_qualities.get(runtime_id)
                if (
                    quality is None
                    and resolve_treasure_top_quality
                    and action_id in TREASURE_HIGHEST_ITEM_FOOTPRINT_ACTION_IDS
                    and has_known_q6
                ):
                    quality = 6
                consider(quality)

    if (
        treasure_appraisal is not None
        and os.environ.get("BIDKING_DISABLE_TREASURE_APPRAISAL") != "1"
        # Narrow rollback for the highest-quality ceiling. The count/cells/value
        # appraisal stays active so this switch remains independently testable.
        and os.environ.get("BIDKING_DISABLE_TREASURE_APPRAISAL_MAX_QUALITY")
        != "1"
    ):
        consider(QUALITY_TIER_NUMBER.get(treasure_appraisal[0]))

    return max_quality


def _apply_public_max_quality_ceiling(
    max_quality: int | None,
    *,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    source_notes: list[str],
) -> None:
    if max_quality is None or max_quality >= 6:
        return
    source_notes.append(f"public_max_quality_ceiling:{max_quality}")
    for key, tier in QUALITY_TIER_NUMBER.items():
        if tier <= max_quality:
            continue
        existing = fixed_counts.get(key)
        existing_min = int(min_counts.get(key, 0))
        if (existing is not None and int(existing) > 0) or existing_min > 0:
            source_notes.append(f"hard_conflict:public_max_quality_zero_{key}")
            continue
        fixed_counts[key] = 0
        min_counts[key] = 0
        source_notes.append(f"public_max_quality_zero_{key}")


def _public_bucket_outline_totals(snapshot: dict[str, Any]) -> dict[str, tuple[int, int | None]]:
    totals: dict[str, tuple[int, int | None]] = {}
    seen: set[tuple[str, str]] = set()
    for row in _iter_dicts(snapshot.get("public_info_rows")):
        key = PUBLIC_BUCKET_OUTLINE_QUALITY.get(_safe_int(row.get("info_id")) or -1)
        if key is None:
            continue
        count = 0
        cells = 0
        missing_cells = False
        for idx, item in enumerate(_iter_dicts(row.get("revealed_items_detail"))):
            item_key = _quality_number_to_key(item.get("quality")) or key
            if item_key != key:
                continue
            identity = (
                str(
                    item.get("runtime_id")
                    or item.get("local_index")
                    or item.get("item_id")
                    or f"row-{id(row)}-{idx}"
                ),
                key,
            )
            if identity in seen:
                continue
            seen.add(identity)
            count += 1
            item_cells = _safe_int(item.get("cells"))
            if item_cells is None or item_cells <= 0:
                item_cells = _shape_cells(item.get("shape_code") or item.get("shape_key"))
            if item_cells is None or item_cells <= 0:
                missing_cells = True
            else:
                cells += item_cells
        # Record the count even when it is 0: a PRESENT "show all <quality> outlines" reveal
        # with zero items is the game telling us there are 0 of that quality (villa 4405 R2 紫=0).
        # Dropping the 0 case left the quality on its soft prior (e.g. 紫 [2,4,6] vs真 0). The row
        # only exists when the game actually broadcast that quality's outline reveal, so this never
        # zero-locks a quality that hasn't been revealed yet.
        prev_count, prev_cells = totals.get(key, (0, 0))
        next_cells: int | None
        if count == 0:
            next_cells = 0 if prev_cells is not None else None
        elif missing_cells or prev_cells is None:
            next_cells = None
        else:
            next_cells = prev_cells + cells
        totals[key] = (prev_count + count, next_cells)
    return totals


def _random_avg_sample_count(row: dict[str, Any]) -> int | None:
    # Presence is authoritative: a malformed explicit count must not fall through to
    # the semantic name and acquire a different valid meaning.  These public rows are
    # JSON-shaped, so accepting subclasses/protocols here only creates coercion side
    # channels (for example 3.9 -> 3 through ``_safe_int``).
    if type(row) is not dict:
        return None
    if "sample_count" in row:
        sample_count = row["sample_count"]
        if type(sample_count) is int and sample_count in RANDOM_AVG_SAMPLE_COUNTS:
            return sample_count
        return None
    semantic = row.get("semantic")
    if type(semantic) is not str:
        return None
    match = re.fullmatch(
        r"random[_-](?P<count>3|6|9|12)[_-]avg[_-]value",
        semantic,
    )
    if match:
        return int(match.group("count"))
    return None


def _quality_key_from_avg_value_row(row: dict[str, Any]) -> str | None:
    quality = _quality_number_to_key(row.get("quality"))
    if quality in {"q4", "q5", "q6"}:
        return quality
    semantic = str(row.get("semantic") or "")
    return PUBLIC_AVG_VALUES.get(semantic)


def _public_quality_avg_values(public_info: dict[str, Any]) -> dict[str, float]:
    rows: list[dict[str, Any]] = []
    rows.extend(_iter_dicts(public_info.get("public_avg_values")))
    rows.extend(_iter_dicts(public_info.get("public_numeric_facts")))
    values: dict[str, float] = {}
    for row in rows:
        kind = str(row.get("kind") or "")
        semantic = str(row.get("semantic") or "")
        if kind != "avg_value" and semantic not in PUBLIC_AVG_VALUES:
            continue
        key = _quality_key_from_avg_value_row(row)
        value = _safe_float(row.get("value"))
        if key is None or value is None:
            continue
        values[key] = value
    return values


def _strict_positive_public_avg_value(value: object) -> float | None:
    """Parse one raw/aggregate public value without coercion side channels."""
    if type(value) not in (int, float):  # noqa: E721 - exact JSON scalar only
        return None
    try:
        parsed = float(value)
    except (OverflowError, TypeError, ValueError):
        return None
    return parsed if math.isfinite(parsed) and parsed > 0.0 else None


def _builtin_scalar_payload(value: object) -> object | None:
    """Copy one builtin scalar payload without invoking subclass overrides."""
    if isinstance(value, str):
        return value if type(value) is str else str.__str__(value)  # noqa: E721
    if isinstance(value, bool):
        return value
    if isinstance(value, int):
        return value if type(value) is int else int.__int__(value)  # noqa: E721
    if isinstance(value, float):
        return value if type(value) is float else float.__float__(value)  # noqa: E721
    return None


def _hard_public_avg_value_info_id_claim(value: object) -> str | None:
    """Project a numeric-equal q4/q5 id without executing scalar protocols."""
    payload = _builtin_scalar_payload(value)
    if isinstance(payload, bool):
        return None
    if type(payload) is int:  # noqa: E721
        return HARD_QUALITY_PUBLIC_AVG_VALUE_INFO_IDS.get(payload)
    if type(payload) is float:  # noqa: E721
        if math.isfinite(payload) and payload.is_integer():
            return HARD_QUALITY_PUBLIC_AVG_VALUE_INFO_IDS.get(int(payload))
        return None
    if type(payload) is str:  # noqa: E721
        return {
            "200036": "q4",
            "200037": "q5",
        }.get(payload.strip())
    return None


def _hard_public_avg_value_semantic_claim(value: object) -> str | None:
    """Project only the q4/q5 semantic actually carried by a string scalar."""
    payload = _builtin_scalar_payload(value)
    if type(payload) is not str:  # noqa: E721
        return None
    claim = PUBLIC_AVG_VALUES.get(payload)
    return claim if claim in {"q4", "q5"} else None


def _quality_public_avg_cells_info_claim(value: object) -> str | None:
    """Resolve the separate avg-cells wire domain without scalar coercion."""

    if type(value) is int:  # noqa: E721 - bool/subclasses are not wire ids
        return QUALITY_PUBLIC_AVG_CELLS_INFO_IDS.get(value)
    if type(value) is float:  # noqa: E721
        if math.isfinite(value) and value.is_integer():
            return QUALITY_PUBLIC_AVG_CELLS_INFO_IDS.get(int(value))
        return None
    if type(value) is str:  # noqa: E721
        return {
            "200013": "q4",
            "200015": "q5",
            "200016": "q6",
        }.get(value.strip())
    return None


def _quality_public_avg_cells_semantic_claim(value: object) -> str | None:
    if type(value) is not str:  # noqa: E721 - exact JSON semantic only
        return None
    return PUBLIC_AVG_CELLS.get(value)


def _malformed_public_avg_value_quality_claim(value: object) -> str | None:
    """Project a malformed scalar payload onto the legacy claimed tier.

    This projection does not authorize the scalar.  It only makes the strict
    authority ledger reject every q4/q5 alias that the legacy public-average
    parser could otherwise consume later (for example ``"5.0"``, ``"05"``
    or ``"bucket-q5"``).  Keeping both parsers on one claimed-tier domain
    prevents an invalid sibling from becoming an order-dependent last write.
    """
    payload = _builtin_scalar_payload(value)
    if type(payload) is float and not math.isfinite(payload):  # noqa: E721
        return None
    if type(payload) is int:  # noqa: E721 - exact ints were handled by caller
        return HARD_QUALITY_PUBLIC_AVG_VALUE_QUALITIES.get(payload)
    if type(payload) not in (str, float):  # noqa: E721 - scalar payload only
        return None
    claim = _quality_number_to_key(payload)
    return claim if claim in {"q4", "q5"} else None


def _hard_public_avg_value_explicit_claims(row: object) -> frozenset[str]:
    """Return q4/q5 tiers identified by safely readable aliases only."""
    if (
        type(row) is not dict  # noqa: E721 - exact JSON row only
        or not _has_exact_bounded_json_keys(row)
    ):
        return frozenset()
    owner = _public_avg_value_row_domain_owner(row)
    if owner is not None and owner != "issue25":
        return frozenset()
    claims: set[str] = set()
    if "info_id" in row:
        claim = _hard_public_avg_value_info_id_claim(row.get("info_id"))
        if claim is not None:
            claims.add(claim)
    if "semantic" in row:
        claim = _hard_public_avg_value_semantic_claim(row.get("semantic"))
        if claim is not None:
            claims.add(claim)
    if "quality" in row:
        quality = row.get("quality")
        claim = (
            HARD_QUALITY_PUBLIC_AVG_VALUE_QUALITIES.get(quality)
            if type(quality) is int  # noqa: E721 - bool excluded
            else _malformed_public_avg_value_quality_claim(quality)
        )
        if claim is not None:
            claims.add(claim)
    return frozenset(claims)


def _hard_public_avg_value_exact_claims(row: object) -> frozenset[str]:
    """Return q4/q5 tiers owned by at least one exact wire alias."""
    if type(row) is not dict or not _has_exact_bounded_json_keys(row):  # noqa: E721
        return frozenset()
    owner = _public_avg_value_row_domain_owner(row)
    if owner is not None and owner != "issue25":
        return frozenset()
    claims: set[str] = set()
    info_id = row.get("info_id")
    if type(info_id) is int:  # noqa: E721 - bool excluded
        claim = HARD_QUALITY_PUBLIC_AVG_VALUE_INFO_IDS.get(info_id)
        if claim is not None:
            claims.add(claim)
    semantic = row.get("semantic")
    if type(semantic) is str:  # noqa: E721
        claim = PUBLIC_AVG_VALUES.get(semantic)
        if claim in {"q4", "q5"}:
            claims.add(claim)
    quality = row.get("quality")
    if type(quality) is int:  # noqa: E721 - bool excluded
        claim = HARD_QUALITY_PUBLIC_AVG_VALUE_QUALITIES.get(quality)
        if claim is not None:
            claims.add(claim)
    return frozenset(claims)


def _public_avg_value_row_domain_owner(row: object) -> str | None:
    """Resolve one safely readable row owner before interpreting aliases.

    ``info_id`` is the primary wire discriminator, followed by ``semantic``;
    quality is issue25-only. Once an owner is known, foreign-domain siblings
    belong to that owner's validation transaction and cannot claim the other
    authority.
    """

    if (
        type(row) is not dict  # noqa: E721 - exact row boundary
        or not _has_exact_bounded_json_keys(row)
    ):
        return None
    info_id = row.get("info_id")
    if _hard_public_avg_value_info_id_claim(info_id) is not None:
        return "issue25"
    if _total_avg_cells_info_alias(info_id) is not None:
        return "issue26"
    if _quality_public_avg_cells_info_claim(info_id) is not None:
        return "avg_cells"
    semantic = row.get("semantic")
    if _hard_public_avg_value_semantic_claim(semantic) is not None:
        return "issue25"
    if _total_avg_cells_semantic_alias(semantic) is not None:
        return "issue26"
    if _quality_public_avg_cells_semantic_claim(semantic) is not None:
        return "avg_cells"
    kind = row.get("kind")
    if type(kind) is str and kind == "avg_cells":  # noqa: E721
        return "avg_cells"
    if "quality" not in row:
        return None
    quality = row.get("quality")
    claim = (
        HARD_QUALITY_PUBLIC_AVG_VALUE_QUALITIES.get(quality)
        if type(quality) is int  # noqa: E721 - bool excluded
        else _malformed_public_avg_value_quality_claim(quality)
    )
    return "issue25" if claim is not None else None


def _hard_public_avg_value_row_claims(
    row: object,
) -> tuple[frozenset[str], bool]:
    """Return every claimed q4/q5 tier and whether all present aliases agree."""
    if type(row) is not dict:  # noqa: E721 - exact JSON row only
        return frozenset(), False
    if not _has_exact_bounded_json_keys(row):
        return frozenset(("q4", "q5")), False
    if _public_avg_value_row_domain_owner(row) in {"issue26", "avg_cells"}:
        return frozenset(), True
    claims: set[str] = set()
    aliases_valid = True
    ambiguous_target_alias = False
    issue26_domain_claimed = False

    if "info_id" in row:
        info_id = row.get("info_id")
        issue26_domain_claimed = _total_avg_cells_info_alias(info_id) is not None
        info_key = _hard_public_avg_value_info_id_claim(info_id)
        if type(info_id) is not int or info_key is None:  # noqa: E721
            aliases_valid = False
            if (
                info_id is not None
                and _builtin_scalar_payload(info_id) is None
            ):
                ambiguous_target_alias = True
        if info_key is not None:
            claims.add(info_key)

    if "semantic" in row:
        semantic = row.get("semantic")
        issue26_domain_claimed = (
            issue26_domain_claimed
            or _total_avg_cells_semantic_alias(semantic) is not None
        )
        semantic_key = _hard_public_avg_value_semantic_claim(semantic)
        if semantic_key in {"q4", "q5"}:
            claims.add(semantic_key)
            if type(semantic) is not str:  # noqa: E721
                aliases_valid = False
        else:
            aliases_valid = False
            if not isinstance(semantic, str) and semantic is not None:
                ambiguous_target_alias = True

    if "quality" in row:
        quality = row.get("quality")
        quality_key = (
            HARD_QUALITY_PUBLIC_AVG_VALUE_QUALITIES.get(quality)
            if type(quality) is int  # noqa: E721 - bool excluded
            else _malformed_public_avg_value_quality_claim(quality)
        )
        if quality_key is not None:
            claims.add(quality_key)
        if type(quality) is not int or quality_key is None:  # noqa: E721
            aliases_valid = False
            quality_payload = _builtin_scalar_payload(quality)
            if type(quality_payload) is float and not math.isfinite(  # noqa: E721
                quality_payload
            ):
                ambiguous_target_alias = True
            if not isinstance(quality, (int, float, str)) and quality is not None:
                ambiguous_target_alias = True

    if "kind" in row:
        kind = row.get("kind")
        if type(kind) is not str or kind != "avg_value":  # noqa: E721
            aliases_valid = False
    if (
        ambiguous_target_alias
        and not issue26_domain_claimed
        and not claims
    ):
        # Arbitrary objects are not JSON wire values, but the legacy parser
        # stringifies them.  Builtin scalar subclasses were already projected
        # from their copied payload above.  Only an uninspectable row without
        # an exact issue26 domain owner must conservatively invalidate both
        # hard public floors; a targeted issue26 row is quarantined by its own
        # authority and must not erase an independent issue25 floor.
        claims.update(("q4", "q5"))
    if not claims:
        return frozenset(), True
    return frozenset(claims), aliases_valid and len(claims) == 1


def _stable_soft_public_avg_value_row(
    row: object,
) -> dict[str, object] | None:
    """Project one legacy-only q4/q5 scalar subclass without authorizing it.

    The historical soft fallback accepts a semantic or quality alias without a
    current raw authority row.  A builtin scalar subclass can carry the same
    safe payload while making the JSON projector reject the row.  Preserve that
    soft value through an exact builtin ``quality`` string, which the legacy
    parser understands but the hard authority deliberately rejects.  Exact-wire
    owners and multi-alias rows stay on the strict invalid path.
    """

    if (
        type(row) is not dict  # noqa: E721 - never call mapping subclass hooks
        or not _has_exact_bounded_json_keys(row)
        or "info_id" in row
        or ("semantic" in row) == ("quality" in row)
    ):
        return None
    kind = row.get("kind")
    if kind is not None and (type(kind) is not str or kind != "avg_value"):  # noqa: E721
        return None
    if _hard_public_avg_value_exact_claims(row):
        return None
    claims = _hard_public_avg_value_explicit_claims(row)
    if len(claims) != 1:
        return None
    tier = next(iter(claims))
    value = _strict_positive_public_avg_value(row.get("value"))
    if value is None:
        return None
    return {
        "kind": "avg_value",
        "quality": "4" if tier == "q4" else "5",
        "value": value,
    }


def _hard_public_avg_value_invalid_exact_tiers(
    snapshot: object,
) -> frozenset[str]:
    """Find exact-owned tiers whose row transaction is malformed."""
    if type(snapshot) is not dict:  # noqa: E721
        return frozenset()
    ui_contract = dict.get(snapshot, "ui_contract")
    constraints = (
        dict.get(ui_contract, "constraints")
        if type(ui_contract) is dict  # noqa: E721
        else None
    )
    public_info = (
        dict.get(constraints, "public_info")
        if type(constraints) is dict  # noqa: E721
        else None
    )
    containers: list[object] = [dict.get(snapshot, "public_info_rows")]
    if type(public_info) is dict:  # noqa: E721
        containers.extend(
            dict.get(public_info, key)
            for key in ("public_avg_values", "public_numeric_facts")
        )
    invalid: set[str] = set()
    for container in containers:
        rows, _untrusted = _hard_public_avg_value_container_rows(container)
        for row in rows:
            if type(row) is not dict:  # noqa: E721
                continue
            if _public_avg_value_row_domain_owner(row) in {"issue26", "avg_cells"}:
                # Projection bookkeeping must follow the same primary-owner
                # boundary as the hard authority.  A foreign q4/q5 semantic on
                # an issue26 row belongs to that row's invalid transaction and
                # cannot invalidate a separate, exact issue25 fallback row.
                continue
            claims = _hard_public_avg_value_exact_claims(row)
            if not claims:
                continue
            _all_claims, aliases_valid = _hard_public_avg_value_row_claims(row)
            raw_value = row.get("value")
            soft_keep = (
                type(raw_value) is dict  # noqa: E721
                and raw_value.get("status") == "present_invalid_soft_keep"
            )
            if not soft_keep and (
                not aliases_valid
                or _strict_positive_public_avg_value(raw_value) is None
            ):
                invalid.update(claims)
    return frozenset(invalid)


def _hard_public_avg_value_exact_owned_tiers(
    snapshot: object,
) -> frozenset[str]:
    """Return tiers already carrying an exact aggregate soft fallback.

    Raw rows are hard-authority evidence only and are never consumed by the
    legacy aggregate fallback.  A stale or cross-session exact raw row must not
    suppress an otherwise valid soft-only subclass projection.
    """

    if type(snapshot) is not dict:  # noqa: E721
        return frozenset()
    ui_contract = dict.get(snapshot, "ui_contract")
    constraints = (
        dict.get(ui_contract, "constraints")
        if type(ui_contract) is dict  # noqa: E721
        else None
    )
    public_info = (
        dict.get(constraints, "public_info")
        if type(constraints) is dict  # noqa: E721
        else None
    )
    containers: list[object] = []
    if type(public_info) is dict:  # noqa: E721
        containers = [
            dict.get(public_info, key)
            for key in ("public_avg_values", "public_numeric_facts")
        ]
    owned: set[str] = set()
    for container in containers:
        rows, _untrusted = _hard_public_avg_value_container_rows(container)
        for row in rows:
            owned.update(_hard_public_avg_value_exact_claims(row))
    return frozenset(owned)


def _public_avg_value_row_current_status(
    row: dict[str, Any],
    *,
    snapshot: Mapping[str, Any],
    context: Mapping[str, Any],
) -> str:
    """Classify a targeted raw row as current, stale, or invalid.

    Monitor-produced ``public_info_rows`` are already filtered to the active
    session and historically omit ``session_id``.  When identity fields are
    present, however, they must agree with the snapshot context.
    """
    for marker in ("stale", "current"):
        if marker not in row:
            continue
        value = row.get(marker)
        if type(value) is not bool:  # noqa: E721
            return "invalid"
        if marker == "stale" and value:
            return "stale"
        if marker == "current" and not value:
            return "stale"
    for identity_field in ("session_id", "session_epoch", "epoch"):
        if identity_field not in row:
            continue
        row_identity = row.get(identity_field)
        current_identity = context.get(identity_field)
        if current_identity is None:
            current_identity = snapshot.get(identity_field)
        if current_identity is None:
            return "invalid"
        if type(row_identity) not in (str, int) or type(row_identity) is not type(  # noqa: E721
            current_identity
        ):
            return "invalid"
        if type(row_identity) is str and (  # noqa: E721
            not row_identity.strip() or not current_identity.strip()
        ):
            return "invalid"
        if row_identity != current_identity:
            return "stale"
    return "current"


def _hard_public_avg_value_container_rows(
    value: object,
) -> tuple[tuple[object, ...], bool]:
    """Read aggregate rows without executing container-subclass protocols."""

    if type(value) is dict:  # noqa: E721 - exact builtin boundary
        return (value,), False
    if type(value) is list:  # noqa: E721
        return tuple(value), False
    if type(value) is tuple:  # noqa: E721
        return tuple(value), False
    if isinstance(value, dict):
        return (value,), True
    if isinstance(value, list):
        return tuple(list.__iter__(value)), True
    if isinstance(value, tuple):
        return tuple(tuple.__iter__(value)), True
    return (), False


def _hard_quality_public_avg_value_authorities(
    snapshot: Mapping[str, Any],
    public_info: Mapping[str, Any],
    context: Mapping[str, Any],
) -> _HardPublicAvgValueDecision:
    """Join current raw q4/q5 rows to a conflict-free aggregate ledger."""
    aggregate_values: dict[str, set[float]] = {"q4": set(), "q5": set()}
    aggregate_invalid: set[str] = set()
    targeted = False
    for group_key in ("public_avg_values", "public_numeric_facts"):
        group_rows, container_untrusted = _hard_public_avg_value_container_rows(
            public_info.get(group_key)
        )
        container_claims: set[str] = set()
        for row in group_rows:
            if type(row) is not dict:  # noqa: E721 - exact JSON rows only
                targeted = True
                aggregate_invalid.update(("q4", "q5"))
                continue
            if not _has_exact_bounded_json_keys(row):
                targeted = True
                aggregate_invalid.update(("q4", "q5"))
                continue
            claims, identity_valid = _hard_public_avg_value_row_claims(row)
            container_claims.update(claims)
            if not claims:
                continue
            targeted = True
            value = _strict_positive_public_avg_value(row.get("value"))
            if not identity_valid or value is None:
                aggregate_invalid.update(claims)
                continue
            aggregate_values[next(iter(claims))].add(value)
        if container_untrusted:
            if group_key == "public_avg_values":
                container_claims.update(("q4", "q5"))
            if container_claims:
                targeted = True
                aggregate_invalid.update(container_claims)

    raw_values: dict[str, set[float]] = {"q4": set(), "q5": set()}
    raw_invalid: set[str] = set()
    raw_rows = snapshot.get("public_info_rows")
    raw_group_rows, raw_container_untrusted = (
        _hard_public_avg_value_container_rows(raw_rows)
    )
    raw_container_claims: set[str] = set()
    for row in raw_group_rows:
        if type(row) is not dict:  # noqa: E721 - exact JSON rows only
            targeted = True
            raw_invalid.update(("q4", "q5"))
            continue
        if not _has_exact_bounded_json_keys(row):
            targeted = True
            raw_invalid.update(("q4", "q5"))
            continue
        claims, aliases_valid = _hard_public_avg_value_row_claims(row)
        raw_container_claims.update(claims)
        if not claims:
            continue
        targeted = True
        current_status = _public_avg_value_row_current_status(
            row,
            snapshot=snapshot,
            context=context,
        )
        if current_status == "stale":
            continue
        if current_status != "current" or not aliases_valid:
            raw_invalid.update(claims)
            continue
        value = _strict_positive_public_avg_value(row.get("value"))
        if value is None:
            raw_invalid.update(claims)
            continue
        raw_values[next(iter(claims))].add(value)
    if raw_container_untrusted and raw_container_claims:
        targeted = True
        raw_invalid.update(raw_container_claims)

    authorities: dict[str, float] = {}
    for key in ("q4", "q5"):
        aggregate = aggregate_values[key]
        raw = raw_values[key]
        if key in aggregate_invalid or len(aggregate) > 1:
            continue
        elif key in raw_invalid or len(raw) > 1:
            continue
        elif not aggregate:
            continue
        elif not raw:
            continue
        else:
            aggregate_value = next(iter(aggregate))
            raw_value = next(iter(raw))
            if aggregate_value == raw_value:
                authorities[key] = aggregate_value
    return _HardPublicAvgValueDecision(
        targeted=targeted,
        values=tuple(sorted(authorities.items())),
    )


def _hard_public_avg_value_decision_from_snapshot(
    snapshot: Mapping[str, Any],
) -> _HardPublicAvgValueDecision:
    ui_contract = snapshot.get("ui_contract")
    ui_contract = ui_contract if type(ui_contract) is dict else {}  # noqa: E721
    context = ui_contract.get("context")
    context = context if type(context) is dict else {}  # noqa: E721
    constraints = ui_contract.get("constraints")
    constraints = constraints if type(constraints) is dict else {}  # noqa: E721
    public_info = constraints.get("public_info")
    public_info = public_info if type(public_info) is dict else {}  # noqa: E721
    return _hard_quality_public_avg_value_authorities(
        snapshot,
        public_info,
        context,
    )


def _hard_public_avg_value_decision_auth_payload(
    decision: _HardPublicAvgValueDecision,
) -> bytes | None:
    if type(decision.targeted) is not bool:  # noqa: E721
        return None
    rows: list[str] = ["v1", "1" if decision.targeted else "0"]
    seen: set[str] = set()
    for key, value in decision.values:
        if (
            type(key) is not str  # noqa: E721
            or key not in {"q4", "q5"}
            or key in seen
            or type(value) is not float  # noqa: E721
            or not math.isfinite(value)
            or value <= 0
        ):
            return None
        seen.add(key)
        rows.append(f"{key}={value.hex()}")
    if tuple(sorted(decision.values)) != decision.values:
        return None
    return "\n".join(rows).encode("ascii")


def _hard_public_avg_value_prepared_marker(
    decision: _HardPublicAvgValueDecision,
) -> str:
    payload = _hard_public_avg_value_decision_auth_payload(decision)
    if payload is None:
        raise ValueError("invalid hard public average value decision")
    return hmac.digest(
        _HARD_PUBLIC_AVG_VALUE_PREPARED_AUTH_KEY,
        payload,
        "sha256",
    ).hex()


def _hard_public_avg_value_prepared_decision_row(
    raw: object,
) -> _HardPublicAvgValueDecision | None:
    if type(raw) is not dict or set(dict.keys(raw)) != {  # noqa: E721
        "targeted",
        "values",
    }:
        return None
    raw_values = dict.get(raw, "values")
    if type(raw_values) is not list:  # noqa: E721
        return None
    values: list[tuple[str, float]] = []
    for row in raw_values:
        if type(row) is not list or len(row) != 2:  # noqa: E721
            return None
        key, value = row
        values.append((key, value))
    decision = _HardPublicAvgValueDecision(
        targeted=dict.get(raw, "targeted"),
        values=tuple(values),
    )
    return (
        decision
        if _hard_public_avg_value_decision_auth_payload(decision) is not None
        else None
    )


def _prepared_hard_public_avg_value_decision(
    snapshot: object,
) -> _HardPublicAvgValueDecision | None:
    invalid = _HardPublicAvgValueDecision(True, ())
    if type(snapshot) is not dict:  # noqa: E721
        return None
    marker = dict.get(
        snapshot,
        _HARD_PUBLIC_AVG_VALUE_PREPARED_MARKER_KEY,
        _ENV_MISSING,
    )
    raw_decision = dict.get(
        snapshot,
        _HARD_PUBLIC_AVG_VALUE_PREPARED_DECISION_KEY,
        _ENV_MISSING,
    )
    if marker is _ENV_MISSING and raw_decision is _ENV_MISSING:
        return None
    if type(marker) is not str or len(marker) != 64:  # noqa: E721
        return invalid
    decision = _hard_public_avg_value_prepared_decision_row(raw_decision)
    if decision is None:
        return invalid
    expected = _hard_public_avg_value_prepared_marker(decision)
    if not hmac.compare_digest(marker, expected):
        return invalid
    current = _hard_public_avg_value_decision_from_snapshot(snapshot)
    return decision if current == decision else invalid


def _hard_public_avg_value_decision(
    snapshot: dict[str, Any],
) -> _HardPublicAvgValueDecision:
    active = _HARD_PUBLIC_AVG_VALUE_RUN_DECISION.get()
    if active is not None:
        return active
    prepared = _prepared_hard_public_avg_value_decision(snapshot)
    if prepared is not None:
        return prepared
    return _hard_public_avg_value_decision_from_snapshot(snapshot)


# Random-N avg-value red anchor: a random N-item sample averaging >= this implies at least one
# item worth >= this (max >= avg), and empirically (scripts/survey_random_avg_value_anchor.py,
# 198 samples) a per-item random avg >= 50k means a red(q6) item is present in 100% of cases
# (15/15) vs an 83% baseline. We anchor at 100k (稳健, chosen 2026-06-16) to stay clear of the
# thin 50-100k tail. Above this we force q6 >= 1.
RANDOM_AVG_RED_ANCHOR_THRESHOLD = 100_000.0
RANDOM_AVG_SAMPLE_COUNTS = frozenset({3, 6, 9, 12})


def _public_random_value_floors(
    public_info: dict[str, Any],
) -> tuple[tuple[int, int | float], ...]:
    rows: list[dict[str, Any]] = []
    rows.extend(_iter_dicts(public_info.get("public_random_avg_values")))
    rows.extend(_iter_dicts(public_info.get("public_numeric_facts")))
    floors: dict[int, int | float] = {}
    for row in rows:
        if type(row) is not dict:
            continue
        kind = row.get("kind")
        semantic = row.get("semantic")
        kind_matches = type(kind) is str and kind == "random_avg_value"
        semantic_matches = (
            type(semantic) is str
            and re.fullmatch(
                r"random[_-][0-9]+[_-]avg[_-]value",
                semantic,
            )
            is not None
        )
        if not kind_matches and not semantic_matches:
            continue
        sample_count = _random_avg_sample_count(row)
        raw_avg_value = row.get("value")
        if type(raw_avg_value) not in (int, float):
            continue
        if sample_count not in RANDOM_AVG_SAMPLE_COUNTS or raw_avg_value <= 0:
            continue
        if type(raw_avg_value) is int:
            total_value: int | float = sample_count * raw_avg_value
            try:
                total_value_float = float(total_value)
            except (OverflowError, TypeError, ValueError):
                continue
            if not math.isfinite(total_value_float):
                continue
        else:
            if not math.isfinite(raw_avg_value):
                continue
            total_value = sample_count * raw_avg_value
            if not math.isfinite(total_value):
                continue
        if total_value <= 0:
            continue
        floors[sample_count] = max(floors.get(sample_count, 0.0), total_value)
    return tuple(sorted(floors.items()))


def _public_category_total_value_floor(
    snapshot: dict[str, Any],
    public_info: dict[str, Any],
) -> float:
    if os.environ.get(BIDKING_DISABLE_PUBLIC_CATEGORY_TOTAL_VALUE_FLOOR) == "1":
        return 0.0
    row_groups: list[object] = [snapshot.get("public_info_rows")]
    if type(public_info) is dict:  # noqa: E721 - exact JSON container only
        row_groups.extend(
            (
                public_info.get("public_exact_subset_values"),
                public_info.get("public_numeric_facts"),
            )
        )
    floor = 0.0
    for group in row_groups:
        rows = (
            (group,)
            if type(group) is dict  # noqa: E721 - exact JSON container only
            else group
            if type(group) in (list, tuple)  # noqa: E721
            else ()
        )
        for row in rows:
            # Raw wire rows carry info_id; the runtime mirror may instead carry
            # the canonical semantic.  A present but invalid/conflicting info_id
            # must never fall back to the semantic alias.  Exact container and
            # scalar checks also keep diagnostic/replay inputs from invoking
            # equality, string, integer, or float protocols at this boundary.
            value = _public_category_total_value_or_none(row)
            if value is None:
                continue
            floor = max(floor, value)
    return floor


def _public_category_total_value_or_none(row: object) -> float | None:
    if type(row) is not dict:  # noqa: E721 - subclasses are untrusted inputs
        return None
    if "info_id" in row:
        info_id = row.get("info_id")
        if (
            type(info_id) is not int  # noqa: E721 - exact wire scalar only
            or info_id != PUBLIC_AUCTION_CATEGORY_TOTAL_VALUE_INFO_ID
        ):
            return None
    else:
        semantic = row.get("semantic")
        if (
            type(semantic) is not str  # noqa: E721 - exact JSON scalar only
            or semantic != "auction_category_total_value"
        ):
            return None
    raw_value = row.get("value")
    if type(raw_value) not in (int, float) or raw_value <= 0:  # noqa: E721
        return None
    try:
        value = float(raw_value)
    except (OverflowError, TypeError, ValueError):
        return None
    return value if math.isfinite(value) else None


def _strict_public_category_rows(value: object) -> tuple[object, bool]:
    """Drop unsafe 200044 aliases before generic public-row consumers run."""
    if type(value) is dict:  # noqa: E721 - exact JSON container only
        rows: tuple[object, ...] = (value,)
        single = True
    elif type(value) in (list, tuple):  # noqa: E721
        rows = tuple(value)
        single = False
    else:
        return value, False
    kept: list[object] = []
    changed = False
    for row in rows:
        if isinstance(row, dict) and type(row) is not dict:  # noqa: E721
            changed = True
            continue
        if type(row) is not dict:  # noqa: E721
            kept.append(row)
            continue
        if "info_id" in row:
            info_id = row.get("info_id")
            if type(info_id) is not int:  # noqa: E721
                changed = True
                continue
            category_row = info_id == PUBLIC_AUCTION_CATEGORY_TOTAL_VALUE_INFO_ID
        else:
            semantic = row.get("semantic")
            category_row = (
                type(semantic) is str  # noqa: E721
                and semantic == "auction_category_total_value"
            )
        if category_row and _public_category_total_value_or_none(row) is None:
            changed = True
            continue
        kept.append(row)
    if not changed:
        return value, False
    if single:
        return (kept[0] if kept else ()), True
    return (tuple(kept) if type(value) is tuple else kept), True  # noqa: E721


def _stabilize_public_category_total_value_snapshot(
    snapshot: dict[str, Any],
) -> dict[str, Any]:
    """Fail closed on unsafe 200044 rows before any coercive legacy scan."""
    if type(snapshot) is not dict:  # noqa: E721 - exact JSON container only
        return snapshot
    payload: dict[str, Any] = snapshot
    raw_rows, raw_changed = _strict_public_category_rows(
        snapshot.get("public_info_rows")
    )
    if raw_changed:
        payload = dict(snapshot)
        payload["public_info_rows"] = raw_rows

    ui_contract = snapshot.get("ui_contract")
    if type(ui_contract) is not dict:  # noqa: E721
        return payload
    constraints = ui_contract.get("constraints")
    if type(constraints) is not dict:  # noqa: E721
        return payload
    public_info = constraints.get("public_info")
    if type(public_info) is not dict:  # noqa: E721
        return payload

    public_updates: dict[str, object] = {}
    for key in ("public_exact_subset_values", "public_numeric_facts"):
        rows, changed = _strict_public_category_rows(public_info.get(key))
        if changed:
            public_updates[key] = rows
    if not public_updates:
        return payload
    stabilized_public_info = dict(public_info)
    stabilized_public_info.update(public_updates)
    stabilized_constraints = dict(constraints)
    stabilized_constraints["public_info"] = stabilized_public_info
    stabilized_contract = dict(ui_contract)
    stabilized_contract["constraints"] = stabilized_constraints
    if payload is snapshot:
        payload = dict(snapshot)
    payload["ui_contract"] = stabilized_contract
    return payload


def _candidate_structured_inputs(snapshot: dict[str, Any], ui_contract: dict[str, Any], constraints: dict[str, Any]) -> list[dict[str, Any]]:
    candidates: list[dict[str, Any]] = []
    for value in (
        snapshot.get("structured_ref_inputs"),
        ui_contract.get("structured_ref_inputs"),
        constraints.get("structured_ref_inputs"),
        snapshot.get("hero_ref_inputs"),
        ui_contract.get("hero_ref_inputs"),
        constraints.get("hero_ref_inputs"),
        snapshot.get("aisha_ref_inputs"),
        ui_contract.get("aisha_ref_inputs"),
        constraints.get("aisha_ref_inputs"),
        snapshot.get("ahmad_ref_inputs"),
        ui_contract.get("ahmad_ref_inputs"),
        constraints.get("ahmad_ref_inputs"),
        snapshot.get("victor_ref_inputs"),
        ui_contract.get("victor_ref_inputs"),
        constraints.get("victor_ref_inputs"),
    ):
        if isinstance(value, dict):
            candidates.append(value)
    return candidates


def _low_green_action_values(rows: Any) -> dict[str, float]:
    values: dict[str, float] = {}
    for row in rows or ():
        if not isinstance(row, dict):
            continue
        action_id = str(row.get("action_id") or "")
        if action_id not in {
            GREEN_COUNT_ACTION,
            GREEN_VALUE_SUM_ACTION,
        }:
            continue
        parsed = _safe_float(row.get("result"))
        if parsed is not None:
            values[action_id] = parsed
    return values


def _normalize_legacy_monitor_low_green_inputs(
    inputs: dict[str, Any], action_values: dict[str, float]
) -> dict[str, Any]:
    """Repair snapshots written before green-only action fields had split paths.

    Older monitors serialized 100104/100116/100122 as exact merged-q1 fields.
    Only rewrite the monitor-owned bridge, and only when the matching action row
    proves where the value came from; manual/user q1 values remain untouched.
    """
    if (
        str(inputs.get("source") or "") != "monitor_pre_settlement_field_updates"
        or not action_values
    ):
        return inputs

    normalized = copy.deepcopy(inputs)
    specs = (
        (
            GREEN_COUNT_ACTION,
            ("fixed_counts", "counts"),
            "split_counts",
            "green",
            {"count"},
        ),
        (
            GREEN_VALUE_SUM_ACTION,
            ("quality_values", "value_sums", "values"),
            "quality_value_floors",
            "q1",
            {"value", "value_sum", "total_value"},
        ),
    )
    rewritable_fields: dict[str, tuple[float, set[str]]] = {}
    for action_id, source_names, target_name, target_key, fields in specs:
        expected = action_values.get(action_id)
        if expected is None:
            continue
        target = normalized.setdefault(target_name, {})
        if not isinstance(target, dict):
            continue
        existing = _safe_float(target.get(target_key))
        if existing is not None and abs(existing - expected) > 0.0001:
            continue
        moved = False
        for source_name in source_names:
            source = normalized.get(source_name)
            if not isinstance(source, dict):
                continue
            for key in ("q1", "1", 1):
                parsed = _safe_float(source.get(key))
                if parsed is None or abs(parsed - expected) > 0.0001:
                    continue
                source.pop(key, None)
                moved = True
        if moved:
            target[target_key] = int(round(expected)) if target_name == "split_counts" else expected
            rewritable_fields[action_id] = (expected, fields)

    if rewritable_fields and isinstance(normalized.get("field_updates"), list):
        rewritten_rows: list[Any] = []
        for raw_row in normalized["field_updates"]:
            if not isinstance(raw_row, dict):
                rewritten_rows.append(raw_row)
                continue
            path_raw = raw_row.get("path") or raw_row.get("field")
            path = (
                tuple(str(part) for part in path_raw)
                if isinstance(path_raw, (list, tuple))
                else ()
            )
            parsed = _safe_float(raw_row.get("value"))
            replacement = None
            if len(path) >= 3 and path[0] == "bucket" and path[1] in {"1", "q1"}:
                for action_id, (expected, fields) in rewritable_fields.items():
                    if parsed is None or abs(parsed - expected) > 0.0001 or path[2] not in fields:
                        continue
                    replacement = dict(raw_row)
                    replacement["path"] = ["bucket_split", "green", path[2]]
                    break
            rewritten_rows.append(replacement if replacement is not None else raw_row)
        normalized["field_updates"] = rewritten_rows
    return normalized


def _path_tuple(value: Any) -> tuple[str, ...]:
    if isinstance(value, str):
        return tuple(part for part in re.split(r"[./]", value) if part)
    if isinstance(value, (list, tuple)):
        return tuple(str(part) for part in value)
    return ()


def _bridge_from_field_updates(
    inputs: dict[str, Any],
    *,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    count_sums: dict[str, int],
    avg_cells: dict[str, float],
    quality_cells: dict[str, float],
    avg_values: dict[str, float],
    quality_values: dict[str, float],
    quality_value_floors: dict[str, float],
    split_counts: dict[str, int],
    split_quality_cells: dict[str, float],
    split_avg_cells: dict[str, float],
    source_notes: list[str],
) -> tuple[int | None, float | None]:
    total_count: int | None = None
    total_grid_target: float | None = None
    for row in inputs.get("field_updates") or ():
        if not isinstance(row, dict):
            continue
        path = _path_tuple(row.get("path") or row.get("field"))
        value = row.get("value")
        if len(path) >= 2 and path[0] == "session":
            if path[1] in {"total_count", "total_item_count"}:
                parsed = _safe_int(value)
                if parsed is not None:
                    total_count = parsed
                    source_notes.append("field_update_total_count")
            elif path[1] in {"total_cells", "warehouse_total_cells"}:
                parsed_float = _safe_float(value)
                if parsed_float is not None:
                    total_grid_target = parsed_float
                    source_notes.append("field_update_total_cells")
        elif len(path) >= 3 and path[0] == "bucket_group":
            parsed_count = _safe_int(value)
            group_key = str(path[1] or "").strip().lower().replace("+", "")
            if parsed_count is not None and path[2] == "count":
                if group_key in {"q4q5", "45"}:
                    count_sums["q4q5"] = parsed_count
                    source_notes.append("field_update_q4q5_count_sum")
                elif group_key in {"q4q5q6", "456"}:
                    count_sums["q4q5q6"] = parsed_count
                    source_notes.append("field_update_q4q5q6_count_sum")
        elif len(path) >= 3 and path[0] == "bucket":
            key = _quality_number_to_key(path[1])
            if key is None:
                continue
            parsed = _safe_float(value)
            if parsed is None:
                continue
            if path[2] == "avg_cells":
                avg_cells[key] = parsed
                source_notes.append(f"field_update_{key}_avg_cells")
            elif path[2] == "count":
                fixed_counts[key] = int(round(parsed))
                min_counts[key] = int(round(parsed))
                source_notes.append(f"field_update_{key}_count")
            elif path[2] in {"cells", "total_cells"}:
                quality_cells[key] = parsed
                source_notes.append(f"field_update_{key}_cells")
            elif path[2] in {"avg_value", "average_value"}:
                avg_values[key] = parsed
                source_notes.append(f"field_update_{key}_avg_value")
            elif path[2] in {"value", "value_sum", "total_value"}:
                quality_values[key] = parsed
                source_notes.append(f"field_update_{key}_value_sum")
        elif len(path) >= 3 and path[0] == "bucket_split":
            key = _low_split_key(path[1])
            if key is None:
                continue
            parsed = _safe_float(value)
            if parsed is None:
                continue
            if path[2] == "avg_cells":
                split_avg_cells[key] = parsed
                source_notes.append(f"field_update_split_{key}_avg_cells")
            elif path[2] == "count":
                split_counts[key] = int(round(parsed))
                source_notes.append(f"field_update_split_{key}_count")
            elif path[2] in {"cells", "total_cells"}:
                split_quality_cells[key] = parsed
                source_notes.append(f"field_update_split_{key}_cells")
            elif path[2] in {"value", "value_sum", "total_value"} and key == "green":
                quality_value_floors["q1"] = max(
                    quality_value_floors.get("q1", 0.0), parsed
                )
                source_notes.append("field_update_split_green_value_floor")
    return total_count, total_grid_target


def _extract_structured_bridge_inputs(
    snapshot: dict[str, Any],
    ui_contract: dict[str, Any],
    constraints: dict[str, Any],
    *,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    count_sums: dict[str, int],
    avg_cells: dict[str, float],
    quality_cells: dict[str, float],
    avg_values: dict[str, float],
    quality_values: dict[str, float],
    quality_value_floors: dict[str, float],
    split_counts: dict[str, int],
    split_quality_cells: dict[str, float],
    split_avg_cells: dict[str, float],
    source_notes: list[str],
    action_results: Any = (),
) -> tuple[int | None, float | None]:
    total_count: int | None = None
    total_grid_target: float | None = None
    low_green_values = _low_green_action_values(action_results)
    for raw_inputs in _candidate_structured_inputs(snapshot, ui_contract, constraints):
        inputs = _normalize_legacy_monitor_low_green_inputs(raw_inputs, low_green_values)
        parsed_total = _safe_int(
            inputs.get("total_count")
            or inputs.get("total_item_count")
            or inputs.get("session_total_count")
            or inputs.get("session_total_item_count")
        )
        if parsed_total is not None:
            total_count = parsed_total
            source_notes.append("structured_ref_bridge_total_count")
        parsed_cells = _safe_float(
            inputs.get("total_cells")
            or inputs.get("total_grid")
            or inputs.get("warehouse_total_cells")
            or inputs.get("session_total_cells")
        )
        if parsed_cells is not None:
            total_grid_target = parsed_cells
            source_notes.append("structured_ref_bridge_total_cells")
        _merge_structured_avg_cells(
            avg_cells,
            inputs.get("avg_cells") or inputs.get("average_cells"),
            source_notes=source_notes,
        )
        _merge_quality_values(
            quality_cells,
            inputs.get("quality_cells") or inputs.get("cells"),
            note_prefix="structured_ref_bridge_cells",
            source_notes=source_notes,
        )
        _merge_quality_values(
            avg_values,
            inputs.get("avg_values") or inputs.get("average_values"),
            note_prefix="structured_ref_bridge_avg_value",
            source_notes=source_notes,
        )
        _merge_quality_values(
            quality_values,
            inputs.get("quality_values")
            or inputs.get("value_sums")
            or inputs.get("values"),
            note_prefix="structured_ref_bridge_value_sum",
            source_notes=source_notes,
        )
        _merge_quality_values(
            quality_value_floors,
            inputs.get("quality_value_floors") or inputs.get("value_floors"),
            note_prefix="structured_ref_bridge_value_floor",
            source_notes=source_notes,
        )
        _merge_split_values(
            split_avg_cells,
            inputs.get("split_avg_cells") or inputs.get("low_quality_avg_cells"),
            note_prefix="structured_ref_bridge_split_avg_cells",
            source_notes=source_notes,
        )
        _merge_split_values(
            split_quality_cells,
            (
                inputs.get("split_quality_cells")
                or inputs.get("split_cells")
                or inputs.get("low_quality_cells")
            ),
            note_prefix="structured_ref_bridge_split_cells",
            source_notes=source_notes,
        )
        _merge_quality_counts(
            fixed_counts,
            inputs.get("fixed_counts") or inputs.get("counts"),
            note_prefix="structured_ref_bridge_count",
            source_notes=source_notes,
        )
        _merge_split_counts(
            split_counts,
            inputs.get("split_counts") or inputs.get("low_quality_counts"),
            note_prefix="structured_ref_bridge_split_count",
            source_notes=source_notes,
        )
        _merge_quality_counts(
            min_counts,
            inputs.get("min_counts"),
            note_prefix="structured_ref_bridge_min_count",
            source_notes=source_notes,
        )
        _merge_count_sums(
            count_sums,
            inputs.get("count_sums") or inputs.get("countSums"),
            note_prefix="structured_ref_bridge_count_sum",
            source_notes=source_notes,
        )
        field_total, field_cells = _bridge_from_field_updates(
            inputs,
            fixed_counts=fixed_counts,
            min_counts=min_counts,
            count_sums=count_sums,
            avg_cells=avg_cells,
            quality_cells=quality_cells,
            avg_values=avg_values,
            quality_values=quality_values,
            quality_value_floors=quality_value_floors,
            split_counts=split_counts,
            split_quality_cells=split_quality_cells,
            split_avg_cells=split_avg_cells,
            source_notes=source_notes,
        )
        if field_total is not None:
            total_count = field_total
        if field_cells is not None:
            total_grid_target = field_cells
    return total_count, total_grid_target


def _parse_static_arrays(text: str, name: str) -> dict[str, list[float]]:
    anchor = f"{name} = new Dictionary"
    start = text.find(anchor)
    if start < 0:
        return {}
    end = text.find("};", start)
    if end < 0:
        return {}
    block = text[start:end]
    pattern = re.compile(
        r'\{\s*"(?P<key>[^"]+)"\s*,\s*new double\[\d+\]\s*\{(?P<values>[^}]+)\}\s*\}',
        re.MULTILINE,
    )
    result: dict[str, list[float]] = {}
    for match in pattern.finditer(block):
        values = [
            float(item.strip())
            for item in match.group("values").split(",")
            if item.strip()
        ]
        result[match.group("key")] = values
    return result


def _parse_map_nests(text: str) -> dict[int, tuple[str, str]]:
    result: dict[int, tuple[str, str]] = {}
    current_map: str | None = None
    current_name: str | None = None
    for raw_line in text.splitlines():
        line = raw_line.strip()
        map_match = re.search(r'MapId\s*=\s*"(?P<id>\d+)"', line)
        if map_match:
            current_map = map_match.group("id")
            current_name = None
            continue
        name_match = re.search(r'MapName\s*=\s*"(?P<name>[^"]*)"', line)
        if name_match and current_map is not None:
            current_name = name_match.group("name")
            continue
        nest_match = re.search(r'NestId\s*=\s*"(?P<nest>[^"]+)"', line)
        if nest_match and current_map is not None:
            result[int(current_map)] = (nest_match.group("nest"), current_name or "")
            current_map = None
            current_name = None
    return result


