@lru_cache(maxsize=1)
def _load_red_longtail_normalized(path: Path = RED_LONGTAIL_NORM_PATH) -> dict[int, int]:
    try:
        raw = _moat_json(path)   # 加密包解密 / 源码明文直读
    except Exception:  # noqa: BLE001  缺 K(DataKeyUnavailable)/错 K/篡改(InvalidTag)/损坏 -> 空 -> 回退 raw(优雅降级, 不崩)
        return {}
    out: dict[int, int] = {}
    for k, v in raw.items():
        try:
            out[int(k)] = int(v)
        except (TypeError, ValueError):
            continue
    return out


def _normalized_red_value(item: dict[str, Any]) -> int | None:
    """Revealed-red item value with q6 long-tail normalization applied (non-long-tail reds unchanged,
    e.g. 4403 麒麟芯片 54,600). Returns the raw value when normalization is disabled / id absent."""
    raw = _safe_int(item.get("value"))
    iid = item.get("item_id")
    if raw is None or iid is None or os.environ.get("AHMAD_DISABLE_RED_LONGTAIL_NORM") == "1":
        return raw
    return _load_red_longtail_normalized().get(int(iid), raw)


