def _load_drop_weight_items(
    path: Path | None = None,
) -> dict[int, dict[str, Any]]:
    """Check current qualification before returning even a warmed item model."""
    if _current_rankmap_distribution_generation_status()[0] != "ok":
        return {}
    if _aisha_q5_total_cells_catalog_generation_status()[0] != "ok":
        return {}
    result = _load_drop_weight_items_verified(path)
    if not result:
        # A transient read/provider failure after qualification is not a
        # permanent negative cache. A later healthy call may load normally.
        _load_drop_weight_items_verified.cache_clear()
    return result


@lru_cache(maxsize=1)
def _load_drop_weight_items_verified(
    path: Path | None = None,
) -> dict[int, dict[str, Any]]:
    """Load only the generation-bound item-level map-weight authority.

    The table may be transparently encrypted, so authority is checked against
    the authenticated plaintext rather than the randomized BKENC envelope.
    Missing, stale, mixed-generation, malformed, or excluded-route input
    returns an empty mapping instead of reaching a legacy/uniform fallback.
    """
    resolved = DROP_WEIGHT_ITEMS_PATH if path is None else Path(path)
    if resolved != DROP_WEIGHT_ITEMS_PATH:
        return {}
    try:
        raw_bytes = _aisha_q5_total_cells_plaintext_bytes(resolved)
    except Exception:  # noqa: BLE001 - fail closed at the RF1 consumer
        return {}
    raw = _aisha_q5_total_cells_parse_drop_weights(raw_bytes)
    if raw is None:
        return {}
    out: dict[int, dict[str, Any]] = {}
    for raw_map_id, payload in raw.items():
        map_id = _safe_int(raw_map_id)
        if map_id is None or not isinstance(payload, dict):
            continue
        out[int(map_id)] = payload
    if path is None:
        status, _generation = _current_rankmap_distribution_generation_status()
        if status == "ok":
            try:
                current = _moat_json(CURRENT_RANKMAP_WEIGHTS_PATH)
            except Exception:  # noqa: BLE001 - current models are one input set
                return {}
            if type(current) is not dict:  # noqa: E721
                return {}
            for raw_map_id, payload in current.items():
                if (
                    type(raw_map_id) is str  # noqa: E721
                    and raw_map_id.isascii()
                    and raw_map_id.isdecimal()
                    and type(payload) is dict  # noqa: E721
                ):
                    out[int(raw_map_id)] = payload
    return out


_load_drop_weight_items.cache_clear = _load_drop_weight_items_verified.cache_clear


@lru_cache(maxsize=4)
def load_reference_static_data(path: Path = STATIC_DATA) -> dict[str, Any]:
    try:
        text = _moat_text(path)   # 加密包解密 / 源码明文直读(StaticData.cs)
    except Exception:  # noqa: BLE001  缺 K/错 K/篡改(InvalidTag)/损坏 -> None -> 空表(优雅降级, 不崩)
        text = None
    base = (
        {
            "drop_weights": _parse_static_arrays(text, "DropWeights"),
            "nest_prices": _parse_static_arrays(text, "NestWeightedPrices"),
            "map_nests": _parse_map_nests(text),
        }
        if text is not None
        else {"drop_weights": {}, "nest_prices": {}, "map_nests": {}}
    )
    base["drop_table_priors"] = _load_drop_table_priors()
    base["drop_table_priors"].update(_load_current_rankmap_priors())
    return base


def _map_tier(map_id: int | None) -> str:
    if map_id is None:
        return "104"
    family = int(map_id) // 100
    if family == 21:
        return "101"
    if family == 22:
        return "102"
    if family == 23:
        return "103"
    if family == 24:
        return "104"
    if family in {25, 45}:
        return "105"
    if family == 26:
        return "106"
    return "104"


def _activity_price_alias_map_id(
    map_id: int | None,
    static_data: dict[str, Any],
) -> tuple[int | None, str]:
    if map_id is None:
        return None, ""
    source_map_id = int(map_id)
    map_nests: dict[int, tuple[str, str]] = static_data.get("map_nests", {})
    nest_prices: dict[str, list[float]] = static_data.get("nest_prices", {})
    current_nest_id = map_nests.get(source_map_id, ("", ""))[0]
    if current_nest_id and nest_prices.get(current_nest_id):
        return map_id, ""

    candidates: list[tuple[str, int]] = []
    if 2541 <= source_map_id <= 2550:
        # 2026-07-16 red-crate activity is a positional copy of 2501-2510. This alias
        # borrows prices only; the independent q6 prior is applied later from source_map_id.
        candidates.append(("red_crate_shipwreck_minus40", source_map_id - 40))
    elif 2521 <= source_map_id <= 2540:
        # Only 2501-2510 carry configured nest prices (2511-2520 do NOT), so 2521-2530 alias via -20
        # and 2531-2540 via -30 -- both land in the configured 2501-2510 base. -10 kept as a fallback.
        candidates.append(("activity_shipwreck_minus20", source_map_id - 20))
        candidates.append(("activity_shipwreck_minus30", source_map_id - 30))
        candidates.append(("activity_shipwreck_minus10", source_map_id - 10))
    elif 4541 <= source_map_id <= 4550:
        # Live modeling aliases these maps to 4501-4510, but StaticData has no 45xx nest
        # prices. Price the corresponding sealed-cabin index on 2501-2510 while retaining
        # the original 454x source id in evidence and diagnostics.
        sealed_cabin = 2501 + ((source_map_id - 1) % 10)
        candidates.append(("red_crate_shipwreck_45xx_to_sealed_cabin", sealed_cabin))
    elif 4501 <= source_map_id <= 4540:
        # Deep-sea blind auction (暗拍) is tier105 like the 25xx sealed cabins and differs
        # only in hiding rival bids; the reference StaticData carries no 45xx nest at all,
        # so price via the SAME cabin index on the configured 2501-2510 base:
        #   4501/4521/4531 -> 2501, 4502/4532 -> 2502, ... 4510/4540 -> 2510.
        sealed_cabin = 2501 + ((source_map_id - 1) % 10)
        candidates.append(("blind_auction_to_sealed_cabin", sealed_cabin))

    for mode, candidate in candidates:
        nest_id = map_nests.get(candidate, ("", ""))[0]
        prices = nest_prices.get(nest_id)
        if prices and len(prices) >= 6:
            return candidate, f"{mode}:{map_id}->{candidate}"
    return map_id, ""


# Heroes migrated to the truth-anchored drop-table VALUE regime (Phase 5). Each maps to its
# re-calibrated quote safety factor: the drop-table quality_values are the empirical settled per-quality
# means (build_empirical_quality_values) — honest, so the raw p50 is well-centered (ahmed +4.7%) and the
# legacy 0.85 safety over-discounts balanced to -11%; the per-hero factor here re-centers balanced to the
# blessed conservative band (~-2~-5%). Heroes NOT listed keep legacy nest-price values + 0.85 (until
# their own re-tune). AHMAD_USE_DROP_TABLE_VALUE forces this globally on (=1, A/B) or off (=0).
_VALUE_REGIME_HERO_SAFETY: dict[str, float] = {
    "ahmed": 0.92,  # ahmed A/B (40 NEW samples): p50 +4.7% -> balanced 0.92*p50 ~ -3% (count/cells exact)
}

# ---- Q5 size-conditioned unit value (审计窗口 2026-07-11 · 血色 5611 案) ----
# 症状: 金件数+金均格【全知】(道具 100119 + 极品均格)时金仍按扁平经验均值估 -> 6件×9.5格/件大金
# 真值 403,802 只估 ~18万, 报价欠 22%(件数锁全对·"整数假锁"体感的真源)。
# 校准(云端库 29,131 个 q5 结算点·全族): corr(格/件, 单件价)=0.88~0.91 且族间分箱中位几乎同值 ->
# 用全局分箱中位表按【已知】格/件条件化 q5 单价。触发窄门: 只在 q5 的格/件被证据精确给出时
# (avg_cells.q5 直接给, 或 quality_cells.q5+fixed_counts.q5 双知), 且 hero 在 truth-value regime
# (与 drop_table_value 同域·当前=ahmed)。估计值(engine 自己猜的 count/cells)不触发。
# 表点=(分箱中心 cpi, 单件价中位); 5611 案 cpi=9.5 -> 64,890 ×6 = 389K vs 真 404K(-3.6%)。
# p25-p75 带宽中段 ±12%(紧)。q6 红同分析 corr 仅 0.26-0.46(散)-> 不动红(H2 域)。
Q5_SIZE_VALUE_POINTS: tuple[tuple[float, float], ...] = (
    (1.5, 16200.0), (2.5, 24793.0), (3.5, 31474.0), (4.5, 37637.0), (5.5, 43681.0),
    (6.5, 49801.0), (7.5, 55633.0), (8.5, 61143.0), (9.5, 64890.0), (10.5, 72098.0),
    (11.5, 76576.0), (12.5, 85800.0),
)
# 默认 ON(2026-07-11 300行 ahmed clean_eval sweep 后定): 隔离硬门过(未触发行0变化);
# 分桶 bal med/MAE(OFF→ON): cpi≥6.5 −44.4→−32.9%/43.6→34.0(血色5611域·大赢) · 5-6.5 −14.2→−10.1
# · 2-5 −6.8→−6.3(平/微正·保守破线58→50) · 【cpi<2 med −1.6→−8.0 变差→下限2.0排除】。
# 全fired(≥2): over+10% 86→80·cons>truth 79→71。kill: AHMAD_ENABLE_Q5_SIZE_VALUE=0;
# 强开(绕过 regime 门, A/B)=1; 下限阈值 env AHMAD_Q5_SIZE_VALUE_MIN_CPI(默认2.0·收紧到5.0=只修大金)。
AHMAD_Q5_SIZE_VALUE_DEFAULT_ON = True
AHMAD_Q5_SIZE_VALUE_MIN_CPI = 2.0
Q5_SIZE_VALUE_NOTE_PREFIX = "q5_size_value:"


def _q5_size_unit_value(cpi: float) -> float:
    """已知格/件 -> q5 单件价(表点线性插值·端点截断)。"""
    pts = Q5_SIZE_VALUE_POINTS
    if cpi <= pts[0][0]:
        return pts[0][1]
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if cpi <= x1:
            return y0 + (y1 - y0) * (cpi - x0) / (x1 - x0)
    return pts[-1][1]


def _apply_q5_size_conditioned_value(
    item_values: dict[str, float], evidence: "RefEvidence", value_on: bool
) -> tuple[dict[str, float], str | None]:
    """q5 单价按【证据精确已知】的格/件条件化(见上方常量块)。返回(可能替换过的 values, note|None)。"""
    env = os.environ.get("AHMAD_ENABLE_Q5_SIZE_VALUE")
    if env == "0":
        return item_values, None
    if env != "1" and not (value_on and AHMAD_Q5_SIZE_VALUE_DEFAULT_ON):
        return item_values, None
    cpi: float | None = None
    avg = evidence.avg_cells.get("q5")
    # 公开软均格(count 未锁·soft prior)不可当精确 cpi——只认道具级精确均格(不在 soft 集合里)。
    if avg is not None and "q5" not in (evidence.soft_avg_cell_keys or frozenset()):
        try:
            cpi = float(avg)
        except (TypeError, ValueError):
            cpi = None
    if cpi is None:
        cells = evidence.quality_cells.get("q5")
        cnt = evidence.fixed_counts.get("q5")
        try:
            if cells is not None and cnt not in (None, "") and float(cnt) > 0:
                cpi = float(cells) / float(cnt)
        except (TypeError, ValueError, ZeroDivisionError):
            cpi = None
    if cpi is None or cpi <= 0:
        return item_values, None
    try:
        min_cpi = float(os.environ.get("AHMAD_Q5_SIZE_VALUE_MIN_CPI") or AHMAD_Q5_SIZE_VALUE_MIN_CPI)
    except (TypeError, ValueError):
        min_cpi = AHMAD_Q5_SIZE_VALUE_MIN_CPI
    if cpi < min_cpi:   # 小金域(cpi<2)sweep 中位变差 -> 不动, 保持扁平均值
        return item_values, None
    unit = _q5_size_unit_value(cpi)
    out = dict(item_values)
    out["q5"] = unit
    return out, f"{Q5_SIZE_VALUE_NOTE_PREFIX}cpi={cpi:g}:{int(round(unit))}"


def _maybe_overlay_drop_table_values(
    map_id: int | None,
    static_data: dict[str, Any],
    values: dict[str, float],
    note: str,
    value_on: bool = False,
) -> tuple[dict[str, float], str]:
    """Overlay the NEW truth-anchored per-quality values (empirical settled means) onto the legacy
    nest-price values. Active when ``value_on`` (the hero is in the value regime) OR the env forces it;
    env AHMAD_USE_DROP_TABLE_VALUE is tri-state: "1" force on (A/B), "0" force off, unset -> use value_on.
    item_values scales every _combo_value/base_total, so this is rolled out per-hero. Per-quality overlay:
    a table value is used only when >0 (express q5/q6 are 0 = no such drops -> keep the legacy floor)."""
    env = os.environ.get("AHMAD_USE_DROP_TABLE_VALUE")
    active = False if env == "0" else (True if (env and env != "0") else value_on)
    if not isinstance(map_id, int) or not active:
        return values, note
    tv = (static_data.get("drop_table_priors", {}).get(map_id) or {}).get("quality_values") or {}
    overlaid = dict(values)
    used: list[str] = []
    for key in QUALITY_KEYS:
        v = tv.get(key)
        if v and float(v) > 0:
            overlaid[key] = float(v)
            used.append(key)
    if used:
        return overlaid, f"{note};drop_table_value:{map_id}:{''.join(used)}"
    return values, note


def _quality_item_values(
    map_id: int | None,
    static_data: dict[str, Any],
    value_on: bool = False,
) -> tuple[dict[str, float], str]:
    map_nests: dict[int, tuple[str, str]] = static_data.get("map_nests", {})
    nest_prices: dict[str, list[float]] = static_data.get("nest_prices", {})
    price_map_id, alias_note = _activity_price_alias_map_id(map_id, static_data)
    nest_id = map_nests.get(int(price_map_id or 0), ("", ""))[0]
    prices = nest_prices.get(nest_id)
    if not prices or len(prices) < 6:
        return _maybe_overlay_drop_table_values(
            map_id, static_data, dict(DEFAULT_ITEM_VALUES), "fallback_default_price", value_on
        )
    q1_indexes = QUALITY_TO_INDEX["q1"]
    values = {
        "q1": sum(prices[index] for index in q1_indexes) / len(q1_indexes),
        "q3": prices[2],
        "q4": prices[3],
        "q5": prices[4],
        "q6": prices[5],
    }
    note = f"nest_price:{nest_id}"
    if alias_note:
        note = f"{note};{alias_note}"
    return _maybe_overlay_drop_table_values(map_id, static_data, values, note, value_on)


EXACT_CATALOG_ITEM_VALUE_LOCK_NOTE = "exact_catalog_item_value_lock"
