@lru_cache(maxsize=1)
def _catalog_value_bounds_by_quality() -> dict[int, tuple[int, int]]:
    """quality -> (cheapest, dearest) collectible price. A tier's per-item price cannot leave this
    band, so a candidate count whose implied unit value falls outside it is ARITHMETICALLY impossible
    (not merely unlikely) — the hard half of the 唯一解 enumeration below."""
    try:
        grouped: dict[int, list[int]] = {}
        for item in _current_calculation_items():
            if int(item.value) <= 0:
                continue
            grouped.setdefault(int(item.quality), []).append(int(item.value))
        return {q: (min(v), max(v)) for q, v in grouped.items() if v}
    except Exception:
        return {}


def _unique_count_from_avg_and_total_value(
    key: str, avg: float, total_value: float, ceiling: int
) -> int | None:
    """#10 (作者 2026-07-11: "价格、均格、总格、件数四个里有两个满足就该能枚举唯一解").

    Enumerate the counts that survive EVERY hard constraint of the (均格 + 总价) pair:
      1. the integer-product rule — avg × count must compose an integer cell total
      2. the physical ceiling — the tier cannot hold more items than the vault has left
      3. the catalog price band — total_value / count must be a price a collectible of this tier can
         actually have (q5 spans 7,800..199,900; a count implying 3,000/件 or 400,000/件 is impossible)
    Return the count only when EXACTLY ONE survives. Ambiguity is left to the soft plausibility bias
    (BUG-G) — never guess a lock. Kill: BIDKING_DISABLE_UNIQUE_COUNT_TWO_SIGNALS=1.
    """
    if os.environ.get("BIDKING_DISABLE_UNIQUE_COUNT_TWO_SIGNALS") == "1":
        return None
    if avg <= 0 or total_value <= 0 or ceiling <= 0:
        return None
    tier = _quality_key_item_table_quality(key) or QUALITY_TIER_NUMBER.get(key)
    bounds = _catalog_value_bounds_by_quality().get(int(tier)) if tier else None
    survivors: list[int] = []
    for count in range(1, int(ceiling) + 1):
        if not _avg_grid_options(count, avg, key):
            continue
        if bounds is not None:
            unit = float(total_value) / count
            if unit < bounds[0] * 0.98 or unit > bounds[1] * 1.02:
                continue  # a price no collectible of this tier can carry
        survivors.append(count)
        if len(survivors) > 1:
            return None
    return survivors[0] if survivors else None


@lru_cache(maxsize=3)
def _validated_quality_catalog(
    quality: int,
) -> tuple[tuple[tuple[int, int], ...], tuple[tuple[int, int, int], ...], str]:
    """Return cross-checked catalog pairs, ID rows, and a status for one quality.

    A hard lock must be stable in both source and packaged builds.  Therefore the raw Item.txt view
    and the processed droppable catalog must agree exactly on every item ID, value, and footprint;
    a missing file or any disagreement fails open instead of silently trusting one checkout shape.
    """
    try:
        from bidking_lab.extract.item_table import load_item_table

        raw_path = ROOT / "data" / "raw" / "tables" / "Item.txt"
        processed_path = ROOT / "data" / "processed" / "items_droppable.json"
        if not raw_path.is_file() or not processed_path.is_file():
            return (), (), "catalog_unavailable"
        raw: dict[int, tuple[int, int]] = {}
        for item in load_item_table(raw_path).values():
            if (
                int(item.quality) != int(quality)
                or int(item.value) <= 0
                or not _is_lockable_collectible(item)
            ):
                continue
            raw[int(item.item_id)] = (
                int(item.value),
                int(item.shape_w) * int(item.shape_h),
            )
        payload = _moat_json(processed_path)
        if not isinstance(payload, list):
            return (), (), "catalog_unavailable"
        processed: dict[int, tuple[int, int]] = {}
        processed_ids: set[int] = set()
        for row in payload:
            if not isinstance(row, dict) or _safe_int(row.get("quality")) != int(quality):
                continue
            item_id = _safe_int(row.get("item_id"))
            if item_id is not None:
                if int(item_id) in processed_ids:
                    return (), (), "catalog_duplicate_item_id"
                processed_ids.add(int(item_id))
            value = _safe_int(row.get("value"))
            width = _safe_int(row.get("shape_w"))
            height = _safe_int(row.get("shape_h"))
            if (
                None in (item_id, value, width, height)
                or value <= 0
                or width <= 0
                or height <= 0
            ):
                continue
            processed[int(item_id)] = (int(value), int(width) * int(height))
        if int(quality) == 6:
            # The processed droppable q6 table intentionally omits a few raw event-only reds.  For
            # identity correlation, use only the packaged intersection and require every packaged
            # row to agree byte-for-byte with Item.txt.  Unlike the q5 exact solver, this path does
            # not need the raw and packaged populations to be identical.
            if not processed or any(
                raw.get(item_id) != pair for item_id, pair in processed.items()
            ):
                return (), (), "catalog_mismatch"
            validated = processed
        else:
            if not raw or raw != processed:
                return (), (), "catalog_mismatch"
            validated = raw
        pairs = tuple(sorted(set(validated.values())))
        id_rows = tuple(
            sorted(
                (item_id, value, cells)
                for item_id, (value, cells) in validated.items()
            )
        )
        return pairs, id_rows, "ok"
    except Exception:
        return (), (), "catalog_unavailable"


@lru_cache(maxsize=1)
def _validated_q4_catalog(
) -> tuple[tuple[tuple[int, int], ...], tuple[tuple[int, int, int], ...], str]:
    return _validated_quality_catalog(4)


@lru_cache(maxsize=1)
def _validated_q5_catalog(
) -> tuple[tuple[tuple[int, int], ...], tuple[tuple[int, int, int], ...], str]:
    return _validated_quality_catalog(5)


@lru_cache(maxsize=1)
def _validated_q6_catalog(
) -> tuple[tuple[tuple[int, int], ...], tuple[tuple[int, int, int], ...], str]:
    return _validated_quality_catalog(6)


def _validated_map_quality_catalog(
    map_id: int,
    quality: int,
) -> tuple[
    tuple[tuple[int, int], ...],
    tuple[tuple[int, int, int], ...],
    str,
    str,
]:
    """Return the canonical map-reachable value/cell catalog for one quality.

    The physical category/shape domain already validates the packaged droppable rows, category
    memory and per-map positive-weight support as one generation.  Reuse that generation here and
    cross-check it against this engine's raw/processed quality catalog before a value constraint can
    become hard.  Missing, stale, duplicate or unreachable support fails open; no global catalog row
    may make a map-local average look like a one-item fact.
    """

    quality = int(quality)
    if quality == 4:
        pairs, id_rows, base_status = _validated_q4_catalog()
    elif quality == 5:
        pairs, id_rows, base_status = _validated_q5_catalog()
    elif quality == 6:
        pairs, id_rows, base_status = _validated_q6_catalog()
    else:
        return (), (), "unsupported_quality", ""
    if base_status != "ok":
        return (), (), base_status, ""
    try:
        from bidking_lab.inference.v2 import _validated_physical_category_catalog

        catalog, reachable_by_map, status, generation = (
            _validated_physical_category_catalog()
        )
    except Exception:
        return (), (), "map_catalog_unavailable", ""
    if status != "ok":
        return (), (), str(status or "map_catalog_unavailable"), str(generation or "")
    reachable = reachable_by_map.get(int(map_id))
    if reachable is None:
        return (), (), "map_catalog_unavailable", str(generation or "")

    base_by_id = {
        int(item_id): (int(value), int(cells))
        for item_id, value, cells in id_rows
    }
    rows: list[tuple[int, int, int]] = []
    for item_id in sorted(reachable):
        row = catalog.get(int(item_id))
        if row is None:
            return (), (), "map_catalog_item_identity_mismatch", str(generation or "")
        row_quality, value, width, height, _categories = row
        if int(row_quality) != int(quality):
            continue
        cells = int(width) * int(height)
        if base_by_id.get(int(item_id)) != (int(value), cells):
            return (), (), "map_catalog_item_identity_mismatch", str(generation or "")
        rows.append((int(item_id), int(value), cells))
    if not rows:
        return (), (), "map_quality_support_empty", str(generation or "")
    return (
        tuple(sorted({(value, cells) for _item_id, value, cells in rows})),
        tuple(rows),
        "ok",
        str(generation or ""),
    )


