def _current_rankmap_distribution_generation_status() -> tuple[str, str]:
    checks = _REFERENCE_INPUT_CHECKS.get()
    if checks is None:
        return _current_rankmap_fresh_generation_status()
    if "rankmap" not in checks:
        checks["rankmap"] = _current_rankmap_fresh_generation_status()
    return checks["rankmap"]


def _current_rankmap_fresh_generation_status() -> tuple[str, str]:
    """Validate the atomic current RankMap package authority."""

    try:
        manifest = _moat_json(ROOT / "scripts" / "package_data_fingerprints.json")
    except Exception:  # noqa: BLE001 - absence/malformed input is no authority
        return "authority_manifest_unavailable", ""
    if type(manifest) is not dict:  # noqa: E721
        return "authority_manifest_malformed", ""
    if (
        manifest.get("baseline_id") != AISHA_Q5_TOTAL_CELLS_PACKAGE_BASELINE_ID
        or type(manifest.get("files")) is not dict  # noqa: E721
    ):
        return "authority_manifest_mixed", ""
    files = manifest["files"]
    for relative, (expected_size, expected_sha) in (
        _CURRENT_RANKMAP_GENERATION_FILES.items()
    ):
        spec = files.get(relative)
        if (
            type(spec) is not dict  # noqa: E721
            or spec.get("size") != expected_size
            or spec.get("sha256") != expected_sha
        ):
            return "authority_manifest_mixed", ""
        identity = _aisha_q5_total_cells_plaintext_identity(ROOT / relative)
        if identity is None:
            return "authority_input_unavailable", ""
        if identity != (expected_size, expected_sha):
            return "authority_input_hash_mismatch", ""
    # Cache parsing, not the current identity decision. A warmed model must not
    # hide a missing/changed encrypted input or a lost decryption provider.
    result = _current_rankmap_verified_payload_status()
    if result[0] != "ok":
        _current_rankmap_verified_payload_status.cache_clear()
    return result


@lru_cache(maxsize=1)
def _current_rankmap_verified_payload_status() -> tuple[str, str]:
    """Decode only after the caller has verified all fixed plaintext pins."""
    try:
        authority = _moat_json(CURRENT_RANKMAP_AUTHORITY_PATH)
        weights = _moat_json(CURRENT_RANKMAP_WEIGHTS_PATH)
        priors = _moat_json(CURRENT_RANKMAP_PRIORS_PATH)
    except Exception:  # noqa: BLE001 - authenticated plaintext must parse atomically
        return "authority_payload_unavailable", ""
    expected_keys = {str(map_id) for map_id in CURRENT_RANKMAP_MAP_IDS}
    if (
        type(authority) is not dict  # noqa: E721
        or authority.get("schema")
        != "bidking_official_20261008_model_authority_v1"
        or authority.get("package_generation") != CURRENT_RANKMAP_PACKAGE_GENERATION
        or authority.get("authority_mode") != CURRENT_RANKMAP_AUTHORITY_MODE
        or authority.get("drop_or_dropmap_absence_is_not_a_blocker") is not True
        or authority.get("claims_item_level_drop_graph") is not False
        or authority.get("official_distribution_authority") is not False
        or authority.get("model_distribution_authority") is not True
        or authority.get("runtime_open_claim") is not False
        or type(weights) is not dict  # noqa: E721
        or type(priors) is not dict  # noqa: E721
        or set(weights) != expected_keys
        or set(priors) != expected_keys
    ):
        return "authority_payload_malformed", ""
    scopes = authority.get("scopes")
    if type(scopes) is not dict:  # noqa: E721
        return "authority_scope_malformed", ""
    # Opening schedules are not distribution authority. Use the exact modeled
    # profile even when it deliberately does not assert any server live opening.
    expected_scopes = {"ordinary": (101, 72), "ranked": (18, 18)}
    for name, (map_count, prior_count) in expected_scopes.items():
        row = scopes.get(name)
        if (type(row) is not dict or row.get("maps") != map_count
                or row.get("priors") != prior_count):
            return "authority_scope_malformed", ""
    if set(scopes["ranked"].get("supports", {})) != expected_keys:
        return "authority_scope_malformed", ""
    return "ok", CURRENT_RANKMAP_PACKAGE_GENERATION


# Preserve the existing test/reload invalidation interface without caching the
# outer file/manifest authority. Clearing it invalidates only verified parsing.
_current_rankmap_distribution_generation_status.cache_clear = _current_rankmap_verified_payload_status.cache_clear


def _auction_hall_6001_strict_json(raw: bytes) -> Any:
    def reject_duplicates(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        out: dict[str, Any] = {}
        for key, value in pairs:
            if key in out:
                raise ValueError(f"duplicate key: {key}")
            out[key] = value
        return out

    def reject_constant(value: str) -> None:
        raise ValueError(f"invalid numeric constant: {value}")

    return json.loads(
        raw.decode("utf-8"),
        object_pairs_hook=reject_duplicates,
        parse_constant=reject_constant,
    )


@lru_cache(maxsize=1)
def _load_auction_hall_6001_shadow() -> tuple[str, dict[str, Any]]:
    """Load the exact 6001 provisional sidecar or return a fail-closed status."""

    if _run_env_get(AUCTION_HALL_6001_PROVISIONAL_DISABLE) == "1":
        return "disabled", {}
    # 6001's provisional model belongs to the historical 4ae generation.
    # The eb1 official update removed the live entry; keep the bytes for
    # historical inspection but do not make them a current quote provider.
    if CURRENT_RANKMAP_PACKAGE_GENERATION != AUCTION_HALL_6001_HISTORICAL_GENERATION:
        return "dormant_current_generation", {}
    try:
        manifest = _moat_json(ROOT / "scripts" / "package_data_fingerprints.json")
    except Exception:  # noqa: BLE001 - package authority is fail closed
        return "manifest_unavailable", {}
    files = manifest.get("files") if type(manifest) is dict else None  # noqa: E721
    if (
        type(manifest) is not dict  # noqa: E721
        or manifest.get("baseline_id")
        != AISHA_Q5_TOTAL_CELLS_PACKAGE_BASELINE_ID
        or type(files) is not dict  # noqa: E721
        or files.get(AUCTION_HALL_6001_SHADOW_RELATIVE)
        != {
            "sha256": AUCTION_HALL_6001_SHADOW_SHA256,
            "size": AUCTION_HALL_6001_SHADOW_BYTES,
        }
    ):
        return "manifest_mixed", {}
    try:
        text = _moat_text(AUCTION_HALL_6001_SHADOW_PATH, encoding="utf-8")
        raw = text.encode("utf-8")
    except Exception:  # noqa: BLE001 - missing key/tamper/malformed input
        return "sidecar_unavailable", {}
    if (
        len(raw) != AUCTION_HALL_6001_SHADOW_BYTES
        or hashlib.sha256(raw).hexdigest()
        != AUCTION_HALL_6001_SHADOW_SHA256
    ):
        return "sidecar_identity_mismatch", {}
    try:
        document = _auction_hall_6001_strict_json(raw)
    except (UnicodeError, ValueError, json.JSONDecodeError):
        return "sidecar_malformed", {}
    algorithm = document.get("algorithm") if type(document) is dict else None  # noqa: E721
    summary = document.get("summary") if type(document) is dict else None  # noqa: E721
    scenarios = summary.get("scenarios") if type(summary) is dict else None  # noqa: E721
    items = document.get("items") if type(document) is dict else None  # noqa: E721
    if (
        document.get("schema")
        != "bidking_auction_hall_6001_shadow_distribution_v1"
        or document.get("generation") != AUCTION_HALL_6001_HISTORICAL_GENERATION
        or document.get("map_id") != 6001
        or document.get("lifecycle") != "recognized_provisional_shadow"
        or document.get("distribution_authority") is not False
        or document.get("official_distribution_eligible") is not False
        or document.get("quote_authority") is not False
        or document.get("official_quote_authority") is not False
        or document.get("provisional_distribution_available") is not True
        or document.get("provisional_quote_available") is not True
        or document.get("affects_bid") is not True
        or document.get("bid_mode") != "provisional_estimated_only"
        or type(algorithm) is not dict  # noqa: E721
        or algorithm.get("primary_scenario")
        != AUCTION_HALL_6001_PRIMARY_SCENARIO
        or algorithm.get("upper_envelope_scenario")
        != AUCTION_HALL_6001_UPPER_SCENARIO
        or algorithm.get("round_skill_group_ids") != [103, 103, 103, 104, 105]
        or algorithm.get("round_skill_group_policy")
        != "identity_only_not_distribution_input"
        or algorithm.get("count_policy") != "observed_count_only"
        or type(scenarios) is not dict  # noqa: E721
        or set(scenarios)
        != {
            AUCTION_HALL_6001_PRIMARY_SCENARIO,
            AUCTION_HALL_6001_UPPER_SCENARIO,
        }
        or type(items) is not list  # noqa: E721
        or len(items) != 680
        or summary.get("catalog_envelope_only_ids")
        != [1006001, 1006002, 1006003, 1006004, 1006005, 1006006, 1006007]
    ):
        return "sidecar_contract_mismatch", {}
    probability_sums = {
        AUCTION_HALL_6001_PRIMARY_SCENARIO: 0.0,
        AUCTION_HALL_6001_UPPER_SCENARIO: 0.0,
    }
    support_counts = {
        AUCTION_HALL_6001_PRIMARY_SCENARIO: 0,
        AUCTION_HALL_6001_UPPER_SCENARIO: 0,
    }
    item_ids: set[int] = set()
    forbidden_ids = {
        1016007,
        1036006,
        1036007,
        1036008,
        1046010,
        1046011,
        1046012,
    }
    for row in items:
        if type(row) is not dict:  # noqa: E721
            return "sidecar_item_mismatch", {}
        item_id = row.get("item_id")
        quality = row.get("quality")
        raw_value = row.get("raw_value")
        normalized_value = row.get("normalized_value")
        probabilities = row.get("scenario_probabilities")
        probability_range = row.get("probability_range_per_draw")
        if (
            type(item_id) is not int  # noqa: E721
            or item_id in item_ids
            or item_id in forbidden_ids
            or type(quality) is not int  # noqa: E721
            or quality not in {1, 2, 3, 4, 5, 6}
            or type(raw_value) is not int  # noqa: E721
            or raw_value <= 0
            or type(normalized_value) is not int  # noqa: E721
            or normalized_value <= 0
            or type(probabilities) is not dict  # noqa: E721
            or set(probabilities) != set(probability_sums)
            or type(probability_range) is not list  # noqa: E721
            or len(probability_range) != 2
        ):
            return "sidecar_item_mismatch", {}
        parsed_probabilities: list[float] = []
        for scenario_name in probability_sums:
            probability = probabilities.get(scenario_name)
            if (
                type(probability) not in {int, float}
                or type(probability) is bool
                or not math.isfinite(float(probability))
                or not 0.0 <= float(probability) <= 1.0
            ):
                return "sidecar_probability_mismatch", {}
            parsed = float(probability)
            parsed_probabilities.append(parsed)
            probability_sums[scenario_name] += parsed
            support_counts[scenario_name] += int(parsed > 0.0)
        if probability_range != [
            min(parsed_probabilities),
            max(parsed_probabilities),
        ]:
            return "sidecar_probability_mismatch", {}
        item_ids.add(item_id)
    expected_support = {
        AUCTION_HALL_6001_PRIMARY_SCENARIO: 673,
        AUCTION_HALL_6001_UPPER_SCENARIO: 680,
    }
    for scenario_name, expected_count in expected_support.items():
        scenario = scenarios.get(scenario_name)
        quality_mass = (
            scenario.get("quality_mass") if type(scenario) is dict else None  # noqa: E721
        )
        if (
            type(scenario) is not dict  # noqa: E721
            or scenario.get("support_items") != expected_count
            or support_counts[scenario_name] != expected_count
            or type(scenario.get("probability_sum")) is not float  # noqa: E721
            or type(quality_mass) is not dict  # noqa: E721
            or set(quality_mass) != set(QUALITY_KEYS)
            or any(
                type(quality_mass.get(key)) is not float  # noqa: E721
                or not math.isfinite(quality_mass[key])
                or not 0.0 <= quality_mass[key] <= 1.0
                for key in QUALITY_KEYS
            )
            or not math.isclose(
                sum(quality_mass[key] for key in QUALITY_KEYS),
                1.0,
                rel_tol=0.0,
                abs_tol=2e-12,
            )
            or not math.isclose(
                probability_sums[scenario_name],
                1.0,
                rel_tol=0.0,
                abs_tol=2e-12,
            )
            or not math.isclose(
                probability_sums[scenario_name],
                scenario["probability_sum"],
                rel_tol=0.0,
                abs_tol=1e-15,
            )
        ):
            return "sidecar_probability_mismatch", {}
    return "ok", document
