@dataclass(frozen=True)
class _AishaQ5TotalCellsValueArm:
    q5_count: int
    q5_cells: int
    value_points: tuple[tuple[float, float], ...]
    floor_value: int
    p50_value: int
    p90_value: int
    catalog_context: str
    q6_count: int | None = None
    q6_cells: int | None = None
    q6_value_points: tuple[tuple[float, float], ...] = ()
    q6_floor_value: int | None = None
    q6_p50_value: int | None = None
    q6_p90_value: int | None = None
    high_value_points: tuple[tuple[float, float], ...] = ()
    high_floor_value: int | None = None
    high_p50_value: int | None = None
    high_p90_value: int | None = None
    physical_likelihood: float = 1.0


@dataclass(frozen=True)
class _AishaQ5TotalCellsValueContext:
    arms: tuple[_AishaQ5TotalCellsValueArm, ...]
    session_id: str
    epoch: int
    round_no: int
    total_count: int | None
    residual_count: int | None
    source_ids: tuple[int, ...] = (
        _AISHA_Q5_TOTAL_CELLS_ACTION_ID,
        _AISHA_TOTAL_COUNT_ACTION_ID,
        *_AISHA_Q5_TOTAL_CELLS_SKILLS,
    )
    physical_domain_count: int = 0
    physical_joint: bool = False

    def arm_for_combo(
        self, combo: RefCombo
    ) -> _AishaQ5TotalCellsValueArm | None:
        q5_count = int(combo.counts.get("q5", 0))
        q5_cells = int(round(float(combo.grids.get("q5", 0.0))))
        q6_count = int(combo.counts.get("q6", 0))
        q6_cells = int(round(float(combo.grids.get("q6", 0.0))))
        return next(
            (
                arm
                for arm in self.arms
                if arm.q5_count == q5_count
                and arm.q5_cells == q5_cells
                and (arm.q6_count is None or arm.q6_count == q6_count)
                and (arm.q6_cells is None or arm.q6_cells == q6_cells)
            ),
            None,
        )


