def _aisha_q5_total_cells_plaintext_bytes(path: Path) -> bytes:
    """Read one moat member's authenticated plaintext deterministically."""

    text = _moat_text(path, encoding="utf-8-sig")
    if type(text) is not str:  # noqa: E721 - reject loader protocol objects
        raise ValueError("conditional-value package input is not exact text")
    return text.encode("utf-8")


def _aisha_q5_total_cells_plaintext_identity(path: Path) -> tuple[int, str] | None:
    try:
        plain = _aisha_q5_total_cells_plaintext_bytes(path)
    except Exception:  # noqa: BLE001 - encrypted/missing/wrong-key is unavailable
        return None
    return len(plain), hashlib.sha256(plain).hexdigest()


def _aisha_q5_total_cells_parse_drop_weights(
    raw: bytes,
) -> dict[str, Any] | None:
    if (
        type(raw) is not bytes  # noqa: E721 - no bytes subclass/protocol
        or len(raw) != AISHA_Q5_TOTAL_CELLS_DROP_WEIGHTS_BYTES
        or hashlib.sha256(raw).hexdigest()
        != AISHA_Q5_TOTAL_CELLS_DROP_WEIGHTS_SHA256
    ):
        return None
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError):
        return None
    if type(payload) is not dict:  # noqa: E721 - exact generated object
        return None
    map_ids: list[int] = []
    for raw_map_id, entry in payload.items():
        if (
            type(raw_map_id) is not str  # noqa: E721
            or not raw_map_id.isascii()
            or not raw_map_id.isdecimal()
            or str(int(raw_map_id)) != raw_map_id
            or type(entry) is not dict  # noqa: E721
        ):
            return None
        map_ids.append(int(raw_map_id))
    map_ids.sort()
    identity = hashlib.sha256(
        json.dumps(map_ids, separators=(",", ":")).encode("ascii")
    ).hexdigest()
    if (
        len(map_ids) != AISHA_Q5_TOTAL_CELLS_DROP_WEIGHTS_MAPS
        or identity != AISHA_Q5_TOTAL_CELLS_DROP_WEIGHTS_MAP_IDS_SHA256
        or _AISHA_Q5_TOTAL_CELLS_FORBIDDEN_WEIGHT_MAP_IDS.intersection(map_ids)
    ):
        return None
    return payload


def _aisha_q5_total_cells_catalog_generation_status() -> tuple[str, str]:
    """Requalify catalogs per call; only verified parsing may persist."""
    checks = _REFERENCE_INPUT_CHECKS.get()
    if checks is None:
        return _aisha_q5_total_cells_fresh_catalog_generation_status()
    if "catalog" not in checks:
        checks["catalog"] = _aisha_q5_total_cells_fresh_catalog_generation_status()
    return checks["catalog"]


def _aisha_q5_total_cells_fresh_catalog_generation_status() -> tuple[str, str]:
    try:
        manifest = _moat_json(ROOT / "scripts" / "package_data_fingerprints.json")
    except Exception:  # noqa: BLE001 - a conditional value lane must fail closed
        return "catalog_generation_unavailable", ""
    if not isinstance(manifest, dict):
        return "catalog_generation_malformed", ""
    baseline_id = manifest.get("baseline_id")
    files = manifest.get("files")
    if (
        type(baseline_id) is not str  # noqa: E721
        or baseline_id != AISHA_Q5_TOTAL_CELLS_PACKAGE_BASELINE_ID
        or type(files) is not dict  # noqa: E721
    ):
        return "catalog_generation_malformed", ""
    for relative, (approved_size, approved_sha) in (
        _AISHA_Q5_TOTAL_CELLS_GENERATION_FILES.items()
    ):
        spec = files.get(relative)
        if not isinstance(spec, dict):
            return "catalog_generation_incomplete", ""
        expected_sha = spec.get("sha256")
        expected_size = spec.get("size")
        if (
            type(expected_sha) is not str  # noqa: E721
            or re.fullmatch(r"[0-9a-f]{64}", expected_sha) is None
            or type(expected_size) is not int  # noqa: E721
            or expected_size <= 0
        ):
            return "catalog_generation_malformed", ""
        if expected_size != approved_size or expected_sha != approved_sha:
            return "catalog_generation_mixed", ""
        path = ROOT / relative
        identity = _aisha_q5_total_cells_plaintext_identity(path)
        if identity is None:
            return "catalog_generation_unavailable", ""
        if identity != (approved_size, approved_sha):
            return (
                "drop_weight_generation_hash_mismatch"
                if relative == "data/processed/drop_weights_all_maps_0627.json"
                else "catalog_generation_hash_mismatch"
            ), ""
    result = _aisha_q5_total_cells_verified_catalog_status()
    if result[0] != "ok":
        _aisha_q5_total_cells_verified_catalog_status.cache_clear()
    return result


@lru_cache(maxsize=1)
def _aisha_q5_total_cells_verified_catalog_status() -> tuple[str, str]:
    try:
        weights_plain = _aisha_q5_total_cells_plaintext_bytes(
            DROP_WEIGHT_ITEMS_PATH
        )
    except Exception:  # noqa: BLE001 - fail closed at the consumer boundary
        return "drop_weight_generation_unavailable", ""
    if _aisha_q5_total_cells_parse_drop_weights(weights_plain) is None:
        return "drop_weight_generation_inventory_mismatch", ""
    return "ok", AISHA_Q5_TOTAL_CELLS_PACKAGE_BASELINE_ID


_aisha_q5_total_cells_catalog_generation_status.cache_clear = _aisha_q5_total_cells_verified_catalog_status.cache_clear


def _aisha_q5_total_cells_wire_int(
    value: Any,
    *,
    minimum: int = 0,
) -> int | None:
    if isinstance(value, bool) or value is None:
        return None
    if type(value) is int:  # noqa: E721 - exact external scalar
        parsed = value
    elif type(value) is str and re.fullmatch(r"0|[1-9][0-9]*", value):  # noqa: E721
        parsed = int(value)
    else:
        return None
    return parsed if parsed >= minimum else None


def _aisha_q5_total_cells_float32_count(
    row: Mapping[str, Any],
    *,
    ui_mirror: bool,
) -> int | None:
    """Accept only the product producer's field-9 little-endian float32 count."""
    required = {
        "result",
        "result_field",
        "result_wire_type",
        "result_raw_hex",
    }
    if not required <= row.keys():
        return None
    field = row.get("result_field")
    if ui_mirror:
        field_ok = type(field) is str and field == "9"  # noqa: E721
    else:
        field_ok = type(field) is int and field == 9  # noqa: E721
    wire_type = row.get("result_wire_type")
    if (
        not field_ok
        or type(wire_type) is not str  # noqa: E721
        or wire_type != "float32"
    ):
        return None
    raw_hex = row.get("result_raw_hex")
    if (
        type(raw_hex) is not str  # noqa: E721
        or re.fullmatch(r"[0-9a-f]{8}", raw_hex) is None
    ):
        return None
    raw_value = row.get("result")
    if ui_mirror:
        if type(raw_value) is not str or re.fullmatch(  # noqa: E721
            r"(?:0|[1-9][0-9]*)\.0",
            raw_value,
        ) is None:
            return None
        parsed = float(raw_value)
    else:
        if type(raw_value) is not float:  # noqa: E721 - exact product scalar
            return None
        parsed = raw_value
    if not math.isfinite(parsed) or parsed <= 0 or not parsed.is_integer():
        return None
    try:
        wire_value = struct.unpack("<f", bytes.fromhex(raw_hex))[0]
        canonical_raw = struct.pack("<f", parsed).hex()
    except (OverflowError, struct.error, ValueError):
        return None
    if (
        not math.isfinite(wire_value)
        or wire_value != parsed
        or raw_hex != canonical_raw
    ):
        return None
    return int(parsed)


def _aisha_total_count_varint(
    row: Mapping[str, Any],
    *,
    ui_mirror: bool,
) -> int | None:
    """Freeze action 100115 to the product's field-7 varint representation."""
    required = {
        "result",
        "result_field",
        "result_wire_type",
        "result_raw_hex",
    }
    if not required <= row.keys():
        return None
    field = row.get("result_field")
    raw_hex = row.get("result_raw_hex")
    result = row.get("result")
    wire_type = row.get("result_wire_type")
    if ui_mirror:
        canonical = (
            type(field) is str  # noqa: E721
            and field == "7"
            and type(result) is str  # noqa: E721
            and re.fullmatch(r"[1-9][0-9]*", result) is not None
            and type(raw_hex) is str  # noqa: E721
            and raw_hex == ""
        )
    else:
        canonical = (
            type(field) is int  # noqa: E721
            and field == 7
            and type(result) is int  # noqa: E721
            and result > 0
            and raw_hex is None
        )
    if (
        not canonical
        or type(wire_type) is not str  # noqa: E721
        or wire_type != "varint"
    ):
        return None
    return int(result)


def _aisha_q5_total_cells_scope(
    snapshot: Any,
) -> tuple[dict[str, Any], str, int, int] | None:
    if type(snapshot) is not dict:  # noqa: E721
        return None
    ui_contract = dict.get(snapshot, "ui_contract")
    context = dict.get(ui_contract, "context") if type(ui_contract) is dict else None  # noqa: E721
    if type(context) is not dict:  # noqa: E721
        return None
    root_hero = dict.get(snapshot, "hero")
    context_hero = dict.get(context, "hero")
    root_phase = dict.get(snapshot, "phase")
    context_phase = dict.get(context, "phase")
    root_map = dict.get(snapshot, "map_id")
    context_map = dict.get(context, "map_id")
    root_round = dict.get(snapshot, "round", dict.get(snapshot, "action_round"))
    context_round = dict.get(context, "round", dict.get(context, "action_round"))
    root_session = dict.get(snapshot, "session_id")
    context_session = dict.get(context, "session_id")
    if (
        type(root_hero) is not str  # noqa: E721
        or type(context_hero) is not str  # noqa: E721
        or normalize_hero_key(root_hero) != "aisha"
        or normalize_hero_key(context_hero) != "aisha"
        or type(root_phase) is not str  # noqa: E721
        or type(context_phase) is not str  # noqa: E721
        or root_phase.strip().lower() != "bidding"
        or context_phase.strip().lower() != "bidding"
        or type(root_map) is not int  # noqa: E721
        or type(context_map) is not int  # noqa: E721
        or root_map <= 0
        or root_map != context_map
        or type(root_round) is not int  # noqa: E721
        or type(context_round) is not int  # noqa: E721
        or root_round != context_round
        or root_round not in {4, 5}
        or type(root_session) is not str  # noqa: E721
        or type(context_session) is not str  # noqa: E721
        or root_session != context_session
        or not root_session.isascii()
    ):
        return None
    match = re.fullmatch(r"(?P<map>[1-9][0-9]*):(?P<epoch>[1-9][0-9]*)", root_session)
    if match is None or int(match.group("map")) != root_map:
        return None
    epoch = int(match.group("epoch"))
    for owner in (snapshot, context):
        for key in ("session_epoch", "epoch"):
            if key in owner and (
                type(owner[key]) is not int or owner[key] != epoch  # noqa: E721
            ):
                return None
    return ui_contract, root_session, epoch, root_round


def _aisha_q5_total_cells_row_scope_ok(
    row: Mapping[str, Any],
    *,
    session_id: str,
    epoch: int,
    round_no: int,
) -> bool:
    if "session_id" in row and (
        type(row["session_id"]) is not str  # noqa: E721
        or row["session_id"] != session_id
    ):
        return False
    for key in ("session_epoch", "epoch"):
        if key in row and _aisha_q5_total_cells_wire_int(row[key], minimum=1) != epoch:
            return False
    for key in ("round", "action_round"):
        if key in row:
            row_round = _aisha_q5_total_cells_wire_int(row[key], minimum=1)
            if row_round is None or row_round > round_no:
                return False
    return True


def _aisha_q5_total_cells_row_container(
    value: Any,
) -> tuple[list[dict[str, Any]], bool]:
    if value is None:
        return [], False
    if type(value) is dict:  # noqa: E721
        values = (value,)
    elif type(value) in {list, tuple}:  # noqa: E721
        values = value
    else:
        return [], True
    rows: list[dict[str, Any]] = []
    for row in values:
        if type(row) is not dict or any(type(key) is not str for key in row):  # noqa: E721
            return [], True
        rows.append(dict(row))
    return rows, False


def _aisha_q5_total_cells_select_actions(
    snapshot: dict[str, Any],
    ui_contract: dict[str, Any],
    *,
    session_id: str,
    epoch: int,
    round_no: int,
) -> tuple[int, int] | None:
    if "action_result_rows" not in snapshot:
        return None
    actions = ui_contract.get("actions")
    if type(actions) is not dict or "results" not in actions:  # noqa: E721
        return None
    containers: tuple[tuple[Any, bool], ...] = (
        (snapshot["action_result_rows"], False),
        (actions["results"], True),
    )
    mirror_pairs: list[tuple[int, int]] = []
    for container, ui_mirror in containers:
        rows, malformed = _aisha_q5_total_cells_row_container(container)
        if malformed:
            return None
        values: dict[int, set[int]] = {
            _AISHA_Q5_TOTAL_CELLS_ACTION_ID: set(),
            _AISHA_TOTAL_COUNT_ACTION_ID: set(),
        }
        for row in rows:
            raw_action_id = row.get("action_id")
            if ui_mirror:
                action_id = (
                    int(raw_action_id)
                    if type(raw_action_id) is str  # noqa: E721
                    and re.fullmatch(r"[1-9][0-9]*", raw_action_id)
                    else None
                )
            else:
                action_id = (
                    raw_action_id
                    if type(raw_action_id) is int  # noqa: E721
                    and raw_action_id > 0
                    else None
                )
            if action_id not in values:
                continue
            if not _aisha_q5_total_cells_row_scope_ok(
                row,
                session_id=session_id,
                epoch=epoch,
                round_no=round_no,
            ):
                return None
            result = (
                _aisha_q5_total_cells_float32_count(row, ui_mirror=ui_mirror)
                if action_id == _AISHA_Q5_TOTAL_CELLS_ACTION_ID
                else _aisha_total_count_varint(row, ui_mirror=ui_mirror)
            )
            if result is None:
                return None
            values[action_id].add(result)
        if any(len(candidates) != 1 for candidates in values.values()):
            return None
        mirror_pairs.append(
            (
                next(iter(values[_AISHA_Q5_TOTAL_CELLS_ACTION_ID])),
                next(iter(values[_AISHA_TOTAL_COUNT_ACTION_ID])),
            )
        )
    return mirror_pairs[0] if mirror_pairs[0] == mirror_pairs[1] else None


def _aisha_q5_total_cells_outline_item_signature(
    item: Any,
) -> tuple[int, int, int, int, int, int | None] | None:
    if type(item) is not dict:  # noqa: E721
        return None
    runtime_id = _aisha_q5_total_cells_wire_int(
        item.get("runtime_id"),
        minimum=1,
    )
    local_index = _aisha_q5_total_cells_wire_int(item.get("local_index"))
    shape_code = _aisha_q5_total_cells_wire_int(
        item.get("shape_code"),
        minimum=1,
    )
    cells = _aisha_q5_total_cells_wire_int(item.get("cells"), minimum=1)
    shape = _raven_shape(shape_code)
    if (
        runtime_id is None
        or local_index is None
        or shape is None
        or cells != shape[0] * shape[1]
    ):
        return None
    raw_quality = item.get("quality")
    quality = (
        None
        if raw_quality is None
        else _aisha_q5_total_cells_wire_int(raw_quality, minimum=1)
    )
    if raw_quality is not None and quality not in {1, 2, 3, 4, 5, 6}:
        return None
    return runtime_id, local_index, shape[0], shape[1], cells, quality


def _aisha_q5_total_cells_outline_row_signature(
    row: Mapping[str, Any],
) -> tuple[tuple[int, int, int, int, int, int | None], ...] | None:
    groups = [row.get("observed_items"), row.get("revealed_items_detail")]
    if any(type(group) not in {list, tuple} for group in groups):  # noqa: E721
        return None
    signatures: list[
        tuple[tuple[int, int, int, int, int, int | None], ...]
    ] = []
    for group in groups:
        parsed = [
            _aisha_q5_total_cells_outline_item_signature(item)
            for item in group
        ]
        if any(item is None for item in parsed):
            return None
        signature = tuple(sorted(item for item in parsed if item is not None))
        if (
            not signature
            or len({item[0] for item in signature}) != len(signature)
            or len({item[1] for item in signature}) != len(signature)
            or {item[1] for item in signature} != set(range(len(signature)))
        ):
            return None
        signatures.append(signature)
    if len(set(signatures)) != 1:
        return None
    signature = signatures[0]
    if _aisha_q5_total_cells_wire_int(row.get("revealed_items")) != len(signature):
        return None
    return signature


def _aisha_q5_total_cells_select_full_outline(
    snapshot: dict[str, Any],
    ui_contract: dict[str, Any],
    *,
    session_id: str,
    epoch: int,
    round_no: int,
) -> tuple[tuple[int, int, int, int, int, int | None], ...] | None:
    actions = ui_contract.get("actions")
    if (
        "action_result_rows" not in snapshot
        or type(actions) is not dict  # noqa: E721
        or "results" not in actions
    ):
        return None
    mirror_signatures: list[
        tuple[tuple[int, int, int, int, int, int | None], ...]
    ] = []
    for container, ui_mirror in (
        (snapshot["action_result_rows"], False),
        (actions["results"], True),
    ):
        rows, malformed = _aisha_q5_total_cells_row_container(container)
        if malformed:
            return None
        candidates: set[
            tuple[tuple[int, int, int, int, int, int | None], ...]
        ] = set()
        for row in rows:
            raw_action_id = row.get("action_id")
            action_id_ok = (
                type(raw_action_id) is str  # noqa: E721
                and raw_action_id == str(_AISHA_FULL_OUTLINE_ACTION_ID)
                if ui_mirror
                else type(raw_action_id) is int  # noqa: E721
                and raw_action_id == _AISHA_FULL_OUTLINE_ACTION_ID
            )
            if not action_id_ok:
                continue
            if not _aisha_q5_total_cells_row_scope_ok(
                row,
                session_id=session_id,
                epoch=epoch,
                round_no=round_no,
            ):
                return None
            signature = _aisha_q5_total_cells_outline_row_signature(row)
            if signature is None:
                return None
            candidates.add(signature)
        if len(candidates) != 1:
            return None
        mirror_signatures.append(next(iter(candidates)))
    return (
        mirror_signatures[0]
        if mirror_signatures[0] == mirror_signatures[1]
        else None
    )


def _aisha_q5_total_cells_physical_high_states(
    snapshot: dict[str, Any],
    ui_contract: dict[str, Any],
    skills: Mapping[
        int,
        tuple[tuple[int, int | None, int, int, int], ...],
    ],
    *,
    session_id: str,
    epoch: int,
    round_no: int,
    total_count: int,
    q5_cells: int,
) -> frozenset[tuple[int, int, int, int]] | None:
    outline = _aisha_q5_total_cells_select_full_outline(
        snapshot,
        ui_contract,
        session_id=session_id,
        epoch=epoch,
        round_no=round_no,
    )
    if outline is None or len(outline) != int(total_count):
        return None
    low_items = {
        runtime_id: (local_index, width, height, cells, quality)
        for skill_id, rows in skills.items()
        for quality in (_AISHA_Q5_TOTAL_CELLS_SKILLS[skill_id],)
        for runtime_id, local_index, width, height, cells in rows
    }
    outline_by_runtime = {
        runtime_id: (local_index, width, height, cells, quality)
        for runtime_id, local_index, width, height, cells, quality in outline
    }
    if any(
        runtime_id not in outline_by_runtime
        or outline_by_runtime[runtime_id][:4] != expected[:4]
        or (
            outline_by_runtime[runtime_id][4] is not None
            and outline_by_runtime[runtime_id][4] != expected[4]
        )
        for runtime_id, expected in low_items.items()
    ):
        return None
    high_items = [
        (width, height, cells, quality)
        for runtime_id, _local_index, width, height, cells, quality in outline
        if runtime_id not in low_items
    ]
    if len(high_items) != int(total_count) - len(low_items):
        return None
    _q5_pairs, q5_catalog, q5_status = _validated_q5_catalog()
    q6_catalog, q6_status = _validated_q6_outline_catalog()
    if q5_status != "ok" or not q5_catalog or q6_status != "ok" or not q6_catalog:
        return None
    q5_cell_sizes = {int(cells) for _item_id, _value, cells in q5_catalog}
    q6_shapes = {
        (min(int(width), int(height)), max(int(width), int(height)))
        for _item_id, _value, width, height in q6_catalog
    }
    states: set[tuple[int, int, int, int]] = {(0, 0, 0, 0)}
    for width, height, cells, quality in high_items:
        next_states: set[tuple[int, int, int, int]] = set()
        for q5_count, q5_total, q6_count, q6_total in states:
            if quality in {None, 5} and cells in q5_cell_sizes:
                next_states.add(
                    (q5_count + 1, q5_total + cells, q6_count, q6_total)
                )
            if quality in {None, 6} and (width, height) in q6_shapes:
                next_states.add(
                    (q5_count, q5_total, q6_count + 1, q6_total + cells)
                )
        if (
            not next_states
            or len(next_states) > AISHA_Q5_TOTAL_CELLS_VALUE_MAX_STATES
        ):
            return None
        states = next_states
    matching = frozenset(state for state in states if state[1] == int(q5_cells))
    return matching or None


def _aisha_q5_total_cells_raw_q6_authority(
    snapshot: dict[str, Any],
) -> tuple[str, int | None, int | None]:
    """Classify explicit q6 count/cells without accepting derived siblings.

    Generic evidence normalization deliberately derives zero count from zero cells
    (and the reverse).  That is useful elsewhere, but this Lane may force a single
    q5 arm only when both q6 fields were independently present on the same raw
    structured input.  Keep aliases local to one input and require every duplicate
    mirror to agree so partial or cross-container evidence cannot be unioned.
    """

    ui_contract = (
        snapshot.get("ui_contract")
        if type(snapshot.get("ui_contract")) is dict  # noqa: E721
        else {}
    )
    constraints = (
        ui_contract.get("constraints")
        if type(ui_contract.get("constraints")) is dict  # noqa: E721
        else {}
    )
    raw_candidates = (
        snapshot.get("structured_ref_inputs"),
        ui_contract.get("structured_ref_inputs"),
        constraints.get("structured_ref_inputs"),
        snapshot.get("hero_ref_inputs"),
        ui_contract.get("hero_ref_inputs"),
        constraints.get("hero_ref_inputs"),
        snapshot.get("aisha_ref_inputs"),
        ui_contract.get("aisha_ref_inputs"),
        constraints.get("aisha_ref_inputs"),
        snapshot.get("ahmad_ref_inputs"),
        ui_contract.get("ahmad_ref_inputs"),
        constraints.get("ahmad_ref_inputs"),
    )

    def explicit_values(
        raw_input: dict[str, Any],
        aliases: tuple[str, ...],
        *,
        count: bool,
    ) -> tuple[str, int | None]:
        values: list[int] = []
        for alias in aliases:
            if alias not in raw_input:
                continue
            container = raw_input.get(alias)
            if type(container) is not dict:  # noqa: E721
                return "invalid", None
            if "q6" not in container:
                continue
            value = container.get("q6")
            if count:
                if type(value) is not int or value < 0:  # noqa: E721
                    return "invalid", None
                parsed = int(value)
            elif type(value) is int and value >= 0:  # noqa: E721
                parsed = int(value)
            elif (
                type(value) is float  # noqa: E721
                and math.isfinite(value)
                and value >= 0
                and value.is_integer()
            ):
                parsed = int(value)
            else:
                return "invalid", None
            values.append(parsed)
        if not values:
            return "absent", None
        if len(set(values)) != 1:
            return "invalid", None
        return "present", values[0]

    pairs: list[tuple[int, int]] = []
    for raw_input in raw_candidates:
        if raw_input is None:
            continue
        if type(raw_input) is not dict:  # noqa: E721
            return "invalid", None, None
        count_status, q6_count = explicit_values(
            raw_input,
            ("fixed_counts", "counts"),
            count=True,
        )
        cells_status, q6_cells = explicit_values(
            raw_input,
            ("quality_cells", "cells"),
            count=False,
        )
        if count_status == cells_status == "absent":
            continue
        if (
            count_status != "present"
            or cells_status != "present"
            or q6_count is None
            or q6_cells is None
            or (q6_count == 0) != (q6_cells == 0)
        ):
            return "invalid", None, None
        pairs.append((q6_count, q6_cells))
    if not pairs:
        return "absent", None, None
    if len(set(pairs)) != 1:
        return "invalid", None, None
    q6_count, q6_cells = pairs[0]
    return (
        "exact_zero" if q6_count == 0 else "exact_positive",
        q6_count,
        q6_cells,
    )


def _aisha_q5_total_cells_fail_closed_snapshot(
    snapshot: dict[str, Any],
    *,
    physical_target_ledger: _AishaQ5PhysicalTargetLedger | None = None,
) -> dict[str, Any]:
    """Quarantine malformed target and non-finite rows before generic extraction."""
    ledger = physical_target_ledger
    if ledger is None:
        ledger = _AISHA_Q5_PHYSICAL_TARGET_LEDGER.get()
    if ledger is None:
        ledger = _aisha_q5_physical_target_ledger(snapshot)
    snapshot = _aisha_q5_physical_quarantine_target_rows(snapshot, ledger)
    scope = _aisha_q5_total_cells_scope(snapshot)
    if scope is None:
        return snapshot
    ui_contract = (
        snapshot.get("ui_contract")
        if type(snapshot.get("ui_contract")) is dict  # noqa: E721
        else {}
    )
    containers: list[Any] = [snapshot.get("action_result_rows")]
    actions = ui_contract.get("actions")
    if type(actions) is dict:  # noqa: E721
        containers.append(actions.get("results"))

    def is_nonfinite_candidate(row: Mapping[str, Any]) -> bool:
        action_id = _aisha_q5_total_cells_wire_int(
            row.get("action_id"),
            minimum=1,
        )
        if action_id not in {
            _AISHA_Q5_TOTAL_CELLS_ACTION_ID,
            _AISHA_TOTAL_COUNT_ACTION_ID,
        }:
            return False
        value = row.get("result")
        if type(value) is float:  # noqa: E721
            return not math.isfinite(value)
        if type(value) is str:  # noqa: E721
            try:
                return not math.isfinite(float(value))
            except ValueError:
                return False
        return False

    nonfinite_seen = False
    for container in containers:
        rows, malformed = _aisha_q5_total_cells_row_container(container)
        if malformed:
            continue
        nonfinite_seen = nonfinite_seen or any(
            is_nonfinite_candidate(row) for row in rows
        )
    if not nonfinite_seen:
        return snapshot

    sanitized = dict.copy(snapshot)

    def without_nonfinite(value: Any) -> list[dict[str, Any]]:
        rows, malformed = _aisha_q5_total_cells_row_container(value)
        if malformed:
            return []
        return [row for row in rows if not is_nonfinite_candidate(row)]

    sanitized["action_result_rows"] = without_nonfinite(
        sanitized.get("action_result_rows")
    )
    sanitized["_aisha_q5_total_cells_wire_invalid"] = True
    sanitized_ui = sanitized.get("ui_contract")
    if type(sanitized_ui) is dict:  # noqa: E721
        sanitized_ui = dict.copy(sanitized_ui)
        sanitized["ui_contract"] = sanitized_ui
        sanitized_actions = sanitized_ui.get("actions")
        if type(sanitized_actions) is dict:  # noqa: E721
            sanitized_actions = dict.copy(sanitized_actions)
            sanitized_ui["actions"] = sanitized_actions
            sanitized_actions["results"] = without_nonfinite(
                sanitized_actions.get("results")
            )
    return sanitized


def _aisha_q5_total_cells_item_signature(
    item: Any,
    *,
    expected_quality: int,
) -> tuple[int, int | None, int, int, int] | None:
    if type(item) is not dict:  # noqa: E721
        return None
    runtime_id = _aisha_q5_total_cells_wire_int(item.get("runtime_id"), minimum=1)
    quality = _aisha_q5_total_cells_wire_int(item.get("quality"), minimum=1)
    shape_code = _aisha_q5_total_cells_wire_int(item.get("shape_code"), minimum=1)
    if runtime_id is None or quality != expected_quality or shape_code is None:
        return None
    shape = _raven_shape(shape_code)
    if shape is None:
        return None
    raw_local_index = item.get("local_index")
    local_index = (
        None
        if raw_local_index is None
        else _aisha_q5_total_cells_wire_int(raw_local_index)
    )
    if raw_local_index is not None and local_index is None:
        return None
    cells = shape[0] * shape[1]
    if item.get("cells") is not None:
        direct_cells = _aisha_q5_total_cells_wire_int(item.get("cells"), minimum=1)
        if direct_cells != cells:
            return None
    return runtime_id, local_index, shape[0], shape[1], cells


def _aisha_q5_total_cells_skill_row_signature(
    row: Mapping[str, Any],
    *,
    expected_quality: int,
) -> tuple[tuple[int, int | None, int, int, int], ...] | None:
    groups = [
        row.get(key)
        for key in ("observed_items", "revealed_items_detail")
        if row.get(key) is not None
    ]
    if not groups:
        return None
    signatures: list[tuple[tuple[int, int | None, int, int, int], ...]] = []
    for group in groups:
        if type(group) not in {list, tuple}:  # noqa: E721
            return None
        parsed: list[tuple[int, int | None, int, int, int]] = []
        for item in group:
            signature = _aisha_q5_total_cells_item_signature(
                item,
                expected_quality=expected_quality,
            )
            if signature is None:
                return None
            parsed.append(signature)
        parsed.sort(key=lambda item: item[0])
        if len({item[0] for item in parsed}) != len(parsed):
            return None
        signatures.append(tuple(parsed))
    if len(set(signatures)) != 1:
        return None
    signature = signatures[0]
    if _aisha_q5_total_cells_wire_int(row.get("revealed_items")) != len(signature):
        return None
    return signature


def _aisha_q5_total_cells_select_skills(
    snapshot: dict[str, Any],
    *,
    session_id: str,
    epoch: int,
    round_no: int,
) -> dict[int, tuple[tuple[int, int | None, int, int, int], ...]] | None:
    containers = [snapshot.get("skill_reveal_rows"), snapshot.get("skill_reveals")]
    signatures: dict[
        int,
        set[tuple[tuple[int, int | None, int, int, int], ...]],
    ] = {skill_id: set() for skill_id in _AISHA_Q5_TOTAL_CELLS_SKILLS}
    for container in containers:
        rows, malformed = _aisha_q5_total_cells_row_container(container)
        if malformed:
            return None
        for row in rows:
            skill_id = _aisha_q5_total_cells_wire_int(row.get("skill_id"), minimum=1)
            if skill_id not in signatures:
                continue
            hero_id = row.get("hero_id")
            if hero_id is not None and _aisha_q5_total_cells_wire_int(hero_id) != 103:
                return None
            if not _aisha_q5_total_cells_row_scope_ok(
                row,
                session_id=session_id,
                epoch=epoch,
                round_no=round_no,
            ):
                return None
            signature = _aisha_q5_total_cells_skill_row_signature(
                row,
                expected_quality=_AISHA_Q5_TOTAL_CELLS_SKILLS[skill_id],
            )
            if signature is None:
                return None
            signatures[skill_id].add(signature)
    if any(len(candidates) != 1 for candidates in signatures.values()):
        return None
    return {
        skill_id: next(iter(candidates))
        for skill_id, candidates in signatures.items()
    }


def _aisha_q5_total_cells_low_outline_matches(
    snapshot: dict[str, Any],
    skills: Mapping[
        int,
        tuple[tuple[int, int | None, int, int, int], ...],
    ],
) -> bool:
    rows = snapshot.get("minimap_grid_items")
    if type(rows) not in {list, tuple}:  # noqa: E721
        return False
    expected: dict[int, tuple[int, int | None, int, int, int]] = {}
    for skill_id, items in skills.items():
        quality = _AISHA_Q5_TOTAL_CELLS_SKILLS[skill_id]
        for runtime_id, local_index, width, height, cells in items:
            if runtime_id in expected:
                return False
            expected[runtime_id] = (
                quality,
                local_index,
                width,
                height,
                cells,
            )
    observed: dict[int, tuple[int, int | None, int, int, int]] = {}
    for row in rows:
        if type(row) is not dict:  # noqa: E721
            return False
        quality = _aisha_q5_total_cells_wire_int(row.get("quality"), minimum=1)
        if quality not in {1, 2, 3, 4}:
            continue
        runtime_id = _aisha_q5_total_cells_wire_int(row.get("runtime_id"), minimum=1)
        width = _aisha_q5_total_cells_wire_int(row.get("width"), minimum=1)
        height = _aisha_q5_total_cells_wire_int(row.get("height"), minimum=1)
        cells = _aisha_q5_total_cells_wire_int(row.get("cells"), minimum=1)
        raw_local_index = row.get("local_index")
        local_index = (
            None
            if raw_local_index is None
            else _aisha_q5_total_cells_wire_int(raw_local_index)
        )
        if (
            runtime_id is None
            or width is None
            or height is None
            or cells != width * height
            or (raw_local_index is not None and local_index is None)
            or runtime_id in observed
        ):
            return False
        observed[runtime_id] = (
            quality,
            local_index,
            min(width, height),
            max(width, height),
            cells,
        )
    if set(observed) != set(expected):
        return False
    for runtime_id, expected_row in expected.items():
        actual_row = observed[runtime_id]
        if actual_row[0] != expected_row[0] or actual_row[2:] != expected_row[2:]:
            return False
        if expected_row[1] is not None and actual_row[1] != expected_row[1]:
            return False
    return True


def _aisha_q5_total_cells_quantile_bins(
    distribution: Mapping[int, float],
    *,
    bins: int,
    normalize: bool = True,
) -> tuple[tuple[int, float], ...]:
    rows = [
        (int(value), float(weight))
        for value, weight in sorted(distribution.items())
        if math.isfinite(float(weight)) and float(weight) > 0
    ]
    total = sum(weight for _value, weight in rows)
    if not rows or not math.isfinite(total) or total <= 0 or bins <= 0:
        return ()
    bin_count = min(int(bins), len(rows))
    compressed: dict[int, float] = {}
    for index in range(bin_count):
        low = total * index / bin_count
        high = total * (index + 1) / bin_count
        cumulative = 0.0
        selected_weight = 0.0
        selected_value = 0.0
        for value, weight in rows:
            overlap = max(
                0.0,
                min(high, cumulative + weight) - max(low, cumulative),
            )
            if overlap > 0:
                selected_weight += overlap
                selected_value += overlap * value
            cumulative += weight
        if selected_weight > 0:
            representative = int(round(selected_value / selected_weight))
            compressed[representative] = (
                compressed.get(representative, 0.0) + selected_weight
            )
    compressed_total = sum(compressed.values())
    if not math.isfinite(compressed_total) or compressed_total <= 0:
        return ()
    return tuple(
        (
            value,
            weight / compressed_total if normalize else weight,
        )
        for value, weight in sorted(compressed.items())
    )


def _aisha_q5_total_cells_linear_quantile_bins(
    distribution: Mapping[int, float],
    *,
    bins: int,
    normalize: bool = True,
) -> tuple[tuple[int, float], ...]:
    """Compress a large discrete convolution in one ordered pass.

    The historical helper above deliberately favors clarity and exact overlap
    accounting for small final distributions.  Reusing it at every intermediate
    physical-domain convolution is quadratic in ``rows * bins`` and made the
    high-count tail take tens of seconds.  This equivalent ordered sweep keeps a
    bounded number of deterministic equal-mass representatives while preserving
    the exact raw catalog floor separately.
    """

    rows = [
        (int(value), float(weight))
        for value, weight in sorted(distribution.items())
        if math.isfinite(float(weight)) and float(weight) > 0
    ]
    total = math.fsum(weight for _value, weight in rows)
    if not rows or not math.isfinite(total) or total <= 0 or bins <= 0:
        return ()
    if len(rows) <= int(bins):
        scale = total if normalize else 1.0
        return tuple((value, weight / scale) for value, weight in rows)

    compressed: dict[int, float] = {}
    row_index = 0
    row_start = 0.0
    bin_count = int(bins)
    for bin_index in range(bin_count):
        low = total * bin_index / bin_count
        high = total * (bin_index + 1) / bin_count
        selected_weight = 0.0
        selected_value = 0.0
        while row_index < len(rows) and row_start < high:
            value, weight = rows[row_index]
            row_end = row_start + weight
            overlap = max(
                0.0,
                min(high, row_end) - max(low, row_start),
            )
            if overlap > 0:
                selected_weight += overlap
                selected_value += overlap * value
            if row_end <= high + 1e-15:
                row_start = row_end
                row_index += 1
            else:
                break
        if selected_weight > 0:
            representative = int(round(selected_value / selected_weight))
            compressed[representative] = (
                compressed.get(representative, 0.0) + selected_weight
            )
    compressed_total = math.fsum(compressed.values())
    if not math.isfinite(compressed_total) or compressed_total <= 0:
        return ()
    scale = compressed_total if normalize else 1.0
    return tuple(
        (value, weight / scale)
        for value, weight in sorted(compressed.items())
    )


def _aisha_q5_total_cells_joint_quantile_bins(
    distribution: Mapping[tuple[int, int], float],
    *,
    bins: int,
    normalize: bool = True,
) -> tuple[tuple[int, int, float], ...]:
    """Bound a correlated q5/q6 value distribution without breaking the pair."""

    rows = [
        (int(q5_value), int(q6_value), float(weight))
        for (q5_value, q6_value), weight in sorted(
            distribution.items(),
            key=lambda row: (sum(row[0]), row[0][0], row[0][1]),
        )
        if math.isfinite(float(weight)) and float(weight) > 0
    ]
    total = math.fsum(weight for _q5, _q6, weight in rows)
    if not rows or not math.isfinite(total) or total <= 0 or bins <= 0:
        return ()
    if len(rows) <= int(bins):
        scale = total if normalize else 1.0
        return tuple(
            (q5_value, q6_value, weight / scale)
            for q5_value, q6_value, weight in rows
        )

    compressed: dict[tuple[int, int], float] = {}
    row_index = 0
    row_start = 0.0
    bin_count = int(bins)
    for bin_index in range(bin_count):
        low = total * bin_index / bin_count
        high = total * (bin_index + 1) / bin_count
        selected_weight = 0.0
        selected_q5 = 0.0
        selected_q6 = 0.0
        while row_index < len(rows) and row_start < high:
            q5_value, q6_value, weight = rows[row_index]
            row_end = row_start + weight
            overlap = max(0.0, min(high, row_end) - max(low, row_start))
            if overlap > 0:
                selected_weight += overlap
                selected_q5 += overlap * q5_value
                selected_q6 += overlap * q6_value
            if row_end <= high + 1e-15:
                row_start = row_end
                row_index += 1
            else:
                break
        if selected_weight > 0:
            representative = (
                int(round(selected_q5 / selected_weight)),
                int(round(selected_q6 / selected_weight)),
            )
            compressed[representative] = (
                compressed.get(representative, 0.0) + selected_weight
            )
    compressed_total = math.fsum(compressed.values())
    if not math.isfinite(compressed_total) or compressed_total <= 0:
        return ()
    scale = compressed_total if normalize else 1.0
    return tuple(
        (q5_value, q6_value, weight / scale)
        for (q5_value, q6_value), weight in sorted(
            compressed.items(),
            key=lambda row: (sum(row[0]), row[0][0], row[0][1]),
        )
    )


@lru_cache(maxsize=128)
def _aisha_map_quality_value_distributions(
    map_id: int,
    quality: int,
    targets: tuple[tuple[int, int], ...],
) -> tuple[
    str,
    tuple[
        tuple[
            int,
            int,
            tuple[tuple[float, float], ...],
            int,
            int,
            int,
        ],
        ...,
    ],
    str,
]:
    """Return bounded discrete value posteriors for every requested count/cells arm."""

    normalized_targets = tuple(sorted(set((int(count), int(cells)) for count, cells in targets)))
    if (
        not normalized_targets
        or any(count < 0 or cells < 0 for count, cells in normalized_targets)
        or any((count == 0) != (cells == 0) for count, cells in normalized_targets)
        or int(quality) not in {5, 6}
    ):
        return "invalid_target", (), ""
    generation_status, baseline_id = _aisha_q5_total_cells_catalog_generation_status()
    if generation_status != "ok":
        return generation_status, (), ""
    _pairs, catalog_rows, catalog_status, physical_generation = (
        _validated_map_quality_catalog(int(map_id), int(quality))
    )
    if catalog_status != "ok" or not catalog_rows or not physical_generation:
        return catalog_status, (), ""
    map_payload = _load_drop_weight_items().get(int(map_id))
    item_payload = map_payload.get("items") if isinstance(map_payload, Mapping) else None
    if not isinstance(item_payload, Mapping):
        return "drop_weight_map_unavailable", (), ""

    raw_rows: list[tuple[int, int, int, float]] = []
    for item_id, raw_value, cells in catalog_rows:
        raw_weight = item_payload.get(str(item_id))
        if raw_weight is None:
            raw_weight = item_payload.get(item_id)
        if not isinstance(raw_weight, (list, tuple)) or len(raw_weight) < 3:
            return "drop_weight_catalog_incomplete", (), ""
        try:
            weight = float(raw_weight[0])
            row_raw_value = float(raw_weight[1])
            fitted_value = float(raw_weight[2])
        except (TypeError, ValueError, OverflowError):
            return "drop_weight_row_malformed", (), ""
        if (
            not all(math.isfinite(value) for value in (weight, row_raw_value, fitted_value))
            or weight < 0
            or not row_raw_value.is_integer()
            or not fitted_value.is_integer()
            or int(row_raw_value) != int(raw_value)
            or fitted_value <= 0
        ):
            return "drop_weight_catalog_mismatch", (), ""
        if weight > 0:
            raw_rows.append((int(cells), int(raw_value), int(fitted_value), weight))
    if not raw_rows:
        return "drop_weight_catalog_empty", (), ""

    floor_by_cells: dict[int, int] = {}
    for cells, raw_value, _fitted_value, _weight in raw_rows:
        floor_by_cells[cells] = min(floor_by_cells.get(cells, raw_value), raw_value)
    raw_options: dict[int, dict[int, float]] = {}
    for cells, _raw_value, fitted_value, weight in raw_rows:
        value = max(floor_by_cells[cells], fitted_value)
        values = raw_options.setdefault(cells, {})
        values[value] = values.get(value, 0.0) + weight
    cell_options: dict[int, dict[int, float]] = {}
    for cells, values in raw_options.items():
        compressed = _aisha_q5_total_cells_linear_quantile_bins(
            values,
            bins=AISHA_Q5_TOTAL_CELLS_VALUE_CATALOG_BINS,
            normalize=False,
        )
        if not compressed:
            return "drop_weight_catalog_empty", (), ""
        cell_options[cells] = dict(compressed)

    max_count = max(count for count, _cells in normalized_targets)
    max_cells = max(cells for _count, cells in normalized_targets)
    target_set = set(normalized_targets)
    catalog_cell_sizes = tuple(sorted(cell_options))
    min_catalog_cells = min(catalog_cell_sizes)
    max_catalog_cells = max(catalog_cell_sizes)

    def can_reach_target_from_prefix(count: int, cells: int) -> bool:
        return any(
            target_count >= count
            and target_cells >= cells
            and min_catalog_cells * (target_count - count)
            <= target_cells - cells
            <= max_catalog_cells * (target_count - count)
            for target_count, target_cells in target_set
        )

    distributions: dict[tuple[int, int], dict[int, float]] = {}
    floors: dict[tuple[int, int], int] = {}
    if (0, 0) in target_set:
        distributions[(0, 0)] = {0: 1.0}
        floors[(0, 0)] = 0
    dp: dict[int, dict[int, float]] = {0: {0: 1.0}}
    floor_dp: dict[int, int] = {0: 0}
    for count in range(1, max_count + 1):
        next_dp: dict[int, dict[int, float]] = {}
        next_floors: dict[int, int] = {}
        for prior_cells, prior_values in dp.items():
            for item_cells, item_values in cell_options.items():
                total_cells = prior_cells + item_cells
                if (
                    total_cells > max_cells
                    or not can_reach_target_from_prefix(count, total_cells)
                ):
                    continue
                combined = next_dp.setdefault(total_cells, {})
                for prior_value, prior_weight in prior_values.items():
                    for item_value, item_weight in item_values.items():
                        total_value = int(prior_value) + int(item_value)
                        combined[total_value] = (
                            combined.get(total_value, 0.0)
                            + float(prior_weight) * float(item_weight)
                        )
                candidate_floor = floor_dp[prior_cells] + floor_by_cells[item_cells]
                next_floors[total_cells] = min(
                    next_floors.get(total_cells, candidate_floor),
                    candidate_floor,
                )
        dp = {}
        for total_cells, values in next_dp.items():
            compressed = _aisha_q5_total_cells_linear_quantile_bins(
                values,
                bins=AISHA_Q5_TOTAL_CELLS_PHYSICAL_INTERMEDIATE_BINS,
                normalize=False,
            )
            if compressed:
                dp[total_cells] = dict(compressed)
        floor_dp = {cells: next_floors[cells] for cells in dp}
        if sum(len(values) for values in dp.values()) > AISHA_Q5_TOTAL_CELLS_VALUE_MAX_STATES:
            return "distribution_complexity_guard", (), ""
        for target_count, target_cells in target_set:
            if target_count == count and target_cells in dp:
                distributions[(target_count, target_cells)] = dp[target_cells]
                floors[(target_count, target_cells)] = floor_dp[target_cells]

    if any(target not in distributions or target not in floors for target in normalized_targets):
        return "catalog_physical_support_empty", (), ""
    output: list[
        tuple[
            int,
            int,
            tuple[tuple[float, float], ...],
            int,
            int,
            int,
        ]
    ] = []
    for count, cells in normalized_targets:
        distribution = distributions[(count, cells)]
        p50 = _raven_weighted_quantile(distribution, 0.50)
        p90 = _raven_weighted_quantile(distribution, 0.90)
        points = _aisha_q5_total_cells_linear_quantile_bins(
            distribution,
            bins=AISHA_Q5_TOTAL_CELLS_PHYSICAL_VALUE_BINS,
        )
        if p50 is None or p90 is None or not points:
            return "distribution_empty", (), ""
        floor = int(floors[(count, cells)])
        output.append(
            (
                count,
                cells,
                tuple((float(value), float(weight)) for value, weight in points),
                floor,
                max(floor, int(p50)),
                max(int(p50), int(p90)),
            )
        )
    context = (
        f"package_data_fingerprints:{baseline_id};"
        f"drop_weights_all_maps_0627:{int(map_id)}:"
        f"{AISHA_Q5_TOTAL_CELLS_DROP_WEIGHTS_SHA256[:12]};"
        f"physical_generation:{physical_generation};q{int(quality)};"
        f"intermediate_bins:{AISHA_Q5_TOTAL_CELLS_PHYSICAL_INTERMEDIATE_BINS};"
        "convolution:discrete"
    )
    return "ok", tuple(output), context


@lru_cache(maxsize=512)
def _aisha_q5_total_cells_value_distribution(
    map_id: int,
    q5_count: int,
    q5_cells: int,
) -> tuple[
    str,
    tuple[tuple[float, float], ...],
    int | None,
    int | None,
    int | None,
    str,
]:
    generation_status, baseline_id = _aisha_q5_total_cells_catalog_generation_status()
    if generation_status != "ok":
        return generation_status, (), None, None, None, ""
    _pairs, catalog_rows, catalog_status = _validated_q5_catalog()
    if catalog_status != "ok" or not catalog_rows:
        return catalog_status, (), None, None, None, ""
    map_payload = _load_drop_weight_items().get(int(map_id))
    item_payload = map_payload.get("items") if isinstance(map_payload, Mapping) else None
    if not isinstance(item_payload, Mapping):
        return "drop_weight_map_unavailable", (), None, None, None, ""
    if q5_count <= 0 or q5_cells <= 0:
        return "invalid_target", (), None, None, None, ""

    raw_rows: list[tuple[int, int, int, float]] = []
    for item_id, raw_value, cells in catalog_rows:
        raw_weight = item_payload.get(str(item_id))
        if raw_weight is None:
            raw_weight = item_payload.get(item_id)
        if not isinstance(raw_weight, (list, tuple)) or len(raw_weight) < 3:
            return "drop_weight_catalog_incomplete", (), None, None, None, ""
        try:
            weight = float(raw_weight[0])
            row_raw_value = float(raw_weight[1])
            fitted_value = float(raw_weight[2])
        except (TypeError, ValueError, OverflowError):
            return "drop_weight_row_malformed", (), None, None, None, ""
        if (
            not all(math.isfinite(value) for value in (weight, row_raw_value, fitted_value))
            or weight < 0
            or not row_raw_value.is_integer()
            or not fitted_value.is_integer()
            or int(row_raw_value) != int(raw_value)
            or fitted_value <= 0
        ):
            return "drop_weight_catalog_mismatch", (), None, None, None, ""
        if weight > 0:
            raw_rows.append((int(cells), int(raw_value), int(fitted_value), weight))
    if not raw_rows:
        return "drop_weight_catalog_empty", (), None, None, None, ""

    floor_by_cells: dict[int, int] = {}
    for cells, raw_value, _fitted_value, _weight in raw_rows:
        floor_by_cells[cells] = min(
            floor_by_cells.get(cells, raw_value),
            raw_value,
        )
    weighted_by_cells: dict[int, dict[int, float]] = {}
    for cells, _raw_value, fitted_value, weight in raw_rows:
        value = max(floor_by_cells[cells], fitted_value)
        value_weights = weighted_by_cells.setdefault(cells, {})
        value_weights[value] = value_weights.get(value, 0.0) + weight
    cell_options: dict[int, dict[int, float]] = {}
    for cells, value_weights in weighted_by_cells.items():
        compressed = _aisha_q5_total_cells_quantile_bins(
            value_weights,
            bins=AISHA_Q5_TOTAL_CELLS_VALUE_CATALOG_BINS,
            normalize=False,
        )
        if not compressed:
            return "drop_weight_catalog_empty", (), None, None, None, ""
        cell_options[cells] = dict(compressed)
    cell_sizes = tuple(sorted(cell_options))

    compositions: list[tuple[int, ...]] = []

    def visit(
        index: int,
        remaining_count: int,
        remaining_cells: int,
        prefix: tuple[int, ...],
    ) -> None:
        if index == len(cell_sizes):
            if remaining_count == 0 and remaining_cells == 0:
                compositions.append(prefix)
            return
        cells = cell_sizes[index]
        maximum = min(remaining_count, remaining_cells // cells)
        for used in range(maximum + 1):
            visit(
                index + 1,
                remaining_count - used,
                remaining_cells - used * cells,
                prefix + (used,),
            )

    visit(0, int(q5_count), int(q5_cells), ())
    if not compositions:
        return "catalog_physical_support_empty", (), None, None, None, ""

    def convolve(
        left: Mapping[int, float],
        right: Mapping[int, float],
    ) -> dict[int, float] | None:
        combined: dict[int, float] = {}
        for left_value, left_weight in left.items():
            for right_value, right_weight in right.items():
                value = int(left_value) + int(right_value)
                combined[value] = (
                    combined.get(value, 0.0)
                    + float(left_weight) * float(right_weight)
                )
            if len(combined) > AISHA_Q5_TOTAL_CELLS_VALUE_MAX_STATES:
                return None
        return combined

    group_cache: dict[tuple[int, int], dict[int, float]] = {}

    def group_distribution(cells: int, count: int) -> dict[int, float] | None:
        key = (cells, count)
        if key in group_cache:
            return group_cache[key]
        if count == 0:
            group_cache[key] = {0: 1.0}
            return group_cache[key]
        prior = group_distribution(cells, count - 1)
        if prior is None:
            return None
        current = convolve(prior, cell_options[cells])
        if current is not None:
            group_cache[key] = current
        return current

    distribution: dict[int, float] = {}
    floor_value: int | None = None
    for composition in compositions:
        current: dict[int, float] = {0: 1.0}
        denominator = 1
        composition_floor = 0
        for cells, count in zip(cell_sizes, composition):
            if count <= 0:
                continue
            grouped = group_distribution(cells, count)
            if grouped is None:
                return "distribution_complexity_guard", (), None, None, None, ""
            combined = convolve(current, grouped)
            if combined is None:
                return "distribution_complexity_guard", (), None, None, None, ""
            current = combined
            denominator *= math.factorial(count)
            composition_floor += floor_by_cells[cells] * count
        multiplier = math.factorial(q5_count) / denominator
        floor_value = (
            composition_floor
            if floor_value is None
            else min(floor_value, composition_floor)
        )
        for value, weight in current.items():
            distribution[value] = distribution.get(value, 0.0) + weight * multiplier
        if len(distribution) > AISHA_Q5_TOTAL_CELLS_VALUE_MAX_STATES:
            return "distribution_complexity_guard", (), None, None, None, ""
    p50 = _raven_weighted_quantile(distribution, 0.50)
    p90 = _raven_weighted_quantile(distribution, 0.90)
    points = _aisha_q5_total_cells_quantile_bins(
        distribution,
        bins=AISHA_Q5_TOTAL_CELLS_VALUE_POSTERIOR_BINS,
    )
    if floor_value is None or p50 is None or p90 is None or not points:
        return "distribution_empty", (), None, None, None, ""
    context = (
        f"package_data_fingerprints:{baseline_id};"
        f"drop_weights_all_maps_0627:{int(map_id)}:"
        f"{AISHA_Q5_TOTAL_CELLS_DROP_WEIGHTS_SHA256[:12]};"
        f"q5_catalog_ids:{len(catalog_rows)};"
        f"catalog_bins:{AISHA_Q5_TOTAL_CELLS_VALUE_CATALOG_BINS};"
        f"states:{len(distribution)};convolution:discrete"
    )
    return (
        "ok",
        tuple((float(value), float(weight)) for value, weight in points),
        int(floor_value),
        max(int(floor_value), int(p50)),
        max(int(p50), int(p90)),
        context,
    )


def _aisha_q5_total_cells_value_context(
    snapshot: dict[str, Any],
    evidence: RefEvidence,
    combos: Sequence[RefCombo],
) -> _AishaQ5TotalCellsValueContext | None:
    if (
        _run_env_get(AISHA_Q5_TOTAL_CELLS_VALUE_DISABLE) == "1"
        or snapshot.get("_aisha_q5_total_cells_wire_invalid") is True
        or not combos
        or normalize_hero_key(evidence.hero) != "aisha"
        or str(evidence.phase).strip().lower() != "bidding"
        or evidence.map_id is None
        or evidence.total_count is None
        or evidence.fixed_counts.get("q5") is not None
        or evidence.avg_cells.get("q5") is not None
        or evidence.quality_values.get("q5") is not None
        or evidence.quality_values.get("q6") is not None
        or evidence.quality_value_floors.get("q5") is not None
        or evidence.quality_value_floors.get("q6") is not None
        or evidence.q5_known_item_facts
        or evidence.q6_known_item_facts
        or "q5" in (evidence.quality_count_cells_options or {})
        or "q6" in (evidence.quality_count_cells_options or {})
        or _hard_total_grid_target_int(evidence) is not None
        or any("conflict" in str(note) for note in evidence.source_notes)
    ):
        return None
    q5_cells = _exact_integer_quality_cell(evidence.quality_cells.get("q5"))
    if q5_cells is None or q5_cells <= 0:
        return None
    scope = _aisha_q5_total_cells_scope(snapshot)
    if scope is None:
        return None
    ui_contract, session_id, epoch, round_no = scope
    actions = _aisha_q5_total_cells_select_actions(
        snapshot,
        ui_contract,
        session_id=session_id,
        epoch=epoch,
        round_no=round_no,
    )
    skills = _aisha_q5_total_cells_select_skills(
        snapshot,
        session_id=session_id,
        epoch=epoch,
        round_no=round_no,
    )
    if actions is None or skills is None:
        return None
    action_q5_cells, action_total_count = actions
    if action_q5_cells != q5_cells or action_total_count != int(evidence.total_count):
        return None
    if not _aisha_q5_total_cells_low_outline_matches(snapshot, skills):
        return None

    skill_counts = {
        quality: len(skills[skill_id])
        for skill_id, quality in _AISHA_Q5_TOTAL_CELLS_SKILLS.items()
    }
    skill_cells = {
        quality: sum(item[4] for item in skills[skill_id])
        for skill_id, quality in _AISHA_Q5_TOTAL_CELLS_SKILLS.items()
    }
    expected_low_counts = {
        "q1": skill_counts[1] + skill_counts[2],
        "q3": skill_counts[3],
        "q4": skill_counts[4],
    }
    if (
        evidence.split_counts.get("white") != skill_counts[1]
        or evidence.split_counts.get("green") != skill_counts[2]
        or _exact_integer_quality_cell(evidence.split_quality_cells.get("white"))
        != skill_cells[1]
        or _exact_integer_quality_cell(evidence.split_quality_cells.get("green"))
        != skill_cells[2]
        or any(
            evidence.fixed_counts.get(key) is not None
            and evidence.fixed_counts.get(key) != expected
            for key, expected in expected_low_counts.items()
        )
        or _exact_integer_quality_cell(evidence.quality_cells.get("q1"))
        != skill_cells[1] + skill_cells[2]
        or _exact_integer_quality_cell(evidence.quality_cells.get("q3"))
        != skill_cells[3]
        or _exact_integer_quality_cell(evidence.quality_cells.get("q4"))
        != skill_cells[4]
    ):
        return None
    residual_count = int(evidence.total_count) - sum(skill_counts.values())
    if residual_count <= 0:
        return None
    q5_counts = sorted({int(combo.counts.get("q5", 0)) for combo in combos})
    if any(
        int(round(float(combo.grids.get("q5", 0.0)))) != q5_cells
        or int(combo.counts.get("q5", 0)) + int(combo.counts.get("q6", 0))
        != residual_count
        or any(
            int(combo.counts.get(key, 0)) != expected
            for key, expected in expected_low_counts.items()
        )
        for combo in combos
    ):
        return None
    fixed_q6 = evidence.fixed_counts.get("q6")
    exact_q6_cells = _exact_integer_quality_cell(
        evidence.quality_cells.get("q6")
    )
    q6_avg_cells = _safe_float(evidence.avg_cells.get("q6"))
    raw_q6_status, raw_q6_count, raw_q6_cells = (
        _aisha_q5_total_cells_raw_q6_authority(snapshot)
    )
    if fixed_q6 is None and exact_q6_cells is None:
        if (
            raw_q6_status != "absent"
            or q6_avg_cells is not None
            or len(q5_counts) < 2
        ):
            return None
    elif fixed_q6 == 0 and exact_q6_cells == 0:
        if (
            (raw_q6_status, raw_q6_count, raw_q6_cells)
            != ("exact_zero", 0, 0)
            or q6_avg_cells is not None
            or len(q5_counts) != 1
            or any(
            int(combo.counts.get("q6", 0)) != 0
            or int(round(float(combo.grids.get("q6", 0.0)))) != 0
            for combo in combos
            )
        ):
            return None
    elif (
        type(fixed_q6) is int  # noqa: E721
        and fixed_q6 > 0
        and exact_q6_cells is not None
        and exact_q6_cells > 0
        and (raw_q6_status, raw_q6_count, raw_q6_cells)
        == ("exact_positive", int(fixed_q6), int(exact_q6_cells))
        and (
            q6_avg_cells is None
            or (
                "q6" not in evidence.soft_avg_cell_keys
                and abs(
                    q6_avg_cells
                    - float(exact_q6_cells) / float(fixed_q6)
                )
                <= 1e-9
            )
        )
    ):
        physical_states = _aisha_q5_total_cells_physical_high_states(
            snapshot,
            ui_contract,
            skills,
            session_id=session_id,
            epoch=epoch,
            round_no=round_no,
            total_count=int(evidence.total_count),
            q5_cells=q5_cells,
        )
        combo_states = {
            (
                int(combo.counts.get("q5", 0)),
                int(round(float(combo.grids.get("q5", 0.0)))),
                int(combo.counts.get("q6", 0)),
                int(round(float(combo.grids.get("q6", 0.0)))),
            )
            for combo in combos
        }
        if (
            physical_states is None
            or len(physical_states) != 1
            or combo_states != set(physical_states)
            or len(q5_counts) != 1
            or next(iter(physical_states))[2:] != (
                int(fixed_q6),
                int(exact_q6_cells),
            )
        ):
            return None
    else:
        return None
    arms: list[_AishaQ5TotalCellsValueArm] = []
    projected_points = 0
    for q5_count in q5_counts:
        status, points, floor, p50, p90, catalog_context = (
            _aisha_q5_total_cells_value_distribution(
                int(evidence.map_id),
                q5_count,
                q5_cells,
            )
        )
        if (
            status != "ok"
            or not points
            or None in (floor, p50, p90)
            or not catalog_context
        ):
            return None
        projected_points += len(points) * len(VALUE_DISTRIBUTION_POINTS)
        if projected_points > AISHA_Q5_TOTAL_CELLS_VALUE_MAX_POSTERIOR_POINTS:
            return None
        arms.append(
            _AishaQ5TotalCellsValueArm(
                q5_count=q5_count,
                q5_cells=q5_cells,
                value_points=points,
                floor_value=int(floor),
                p50_value=int(p50),
                p90_value=int(p90),
                catalog_context=catalog_context,
            )
        )
    return _AishaQ5TotalCellsValueContext(
        arms=tuple(arms),
        session_id=session_id,
        epoch=epoch,
        round_no=round_no,
        total_count=int(evidence.total_count),
        residual_count=residual_count,
    )


def _aisha_q5_physical_varint_cells(
    row: Mapping[str, Any],
    *,
    ui_mirror: bool,
) -> int | None:
    """Accept the live producer's field-14 varint form of action 100107."""

    required = {"result", "result_field", "result_wire_type", "result_raw_hex"}
    if not required <= row.keys():
        return None
    result = row.get("result")
    field = row.get("result_field")
    raw_hex = row.get("result_raw_hex")
    if ui_mirror:
        canonical = (
            type(field) is str  # noqa: E721 - exact JSON mirror scalar
            and field == "14"
            and type(result) is str  # noqa: E721
            and re.fullmatch(r"[1-9][0-9]*", result) is not None
            and type(raw_hex) is str  # noqa: E721
            and raw_hex == ""
        )
    else:
        canonical = (
            type(field) is int  # noqa: E721 - exact producer scalar
            and field == 14
            and type(result) is int  # noqa: E721
            and result > 0
            and raw_hex is None
        )
    if (
        not canonical
        or type(row.get("result_wire_type")) is not str  # noqa: E721
        or row.get("result_wire_type") != "varint"
    ):
        return None
    return int(result)


def _aisha_q5_physical_action_id_state(
    value: object,
    *,
    ui_mirror: bool,
) -> str:
    """Classify one action id without invoking an instance conversion protocol."""

    target = _AISHA_Q5_TOTAL_CELLS_ACTION_ID
    value_type = type(value)
    if ui_mirror:
        if value_type is str and value == str(target):
            return "target"
    elif value_type is int and value == target:
        return "target"

    targeted = False
    if value_type is int:  # bool is not an admissible wire int
        targeted = value == target
    elif value_type is float:
        targeted = math.isfinite(value) and value == float(target)
    elif value_type is str:
        text = value.strip()
        if len(text) <= 32 and re.fullmatch(
            r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?",
            text,
        ):
            try:
                targeted = Fraction(text) == target
            except (ValueError, ZeroDivisionError):
                targeted = False
    else:
        # ``isinstance(value, ...)`` can read an arbitrary instance's user-owned
        # ``__class__`` property.  Read the real type directly, then inspect its
        # actual MRO through the builtin type descriptor; both operations bypass
        # instance and metaclass protocols.
        value_mro = type.__getattribute__(value_type, "__mro__")
        if any(base is int for base in value_mro) and value_type is not bool:
            targeted = int.__eq__(value, target) is True
        elif any(base is float for base in value_mro):
            targeted = float.__eq__(value, float(target)) is True
        elif any(base is str for base in value_mro):
            text = str.strip(value)
            if str.__len__(text) <= 32 and re.fullmatch(
                r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?",
                text,
            ):
                try:
                    targeted = Fraction(text) == target
                except (ValueError, ZeroDivisionError):
                    targeted = False
        elif any(base is Decimal for base in value_mro):
            # Call the builtin implementation directly; a Decimal subclass cannot
            # substitute its own equality protocol here.
            targeted = Decimal.__eq__(value, Decimal(target)) is True
        elif any(base is Fraction for base in value_mro):
            try:
                fraction_members = type.__getattribute__(Fraction, "__dict__")
                numerator = fraction_members["_numerator"].__get__(value, Fraction)
                denominator = fraction_members["_denominator"].__get__(value, Fraction)
            except (AttributeError, TypeError):
                targeted = False
            else:
                targeted = (
                    type(numerator) is int  # noqa: E721
                    and type(denominator) is int  # noqa: E721
                    and numerator == target
                    and denominator == 1
                )
        elif any(base is complex for base in value_mro):
            targeted = complex.__eq__(value, complex(target, 0)) is True
    if targeted:
        return "malformed_target"
    if (
        value_type is type(None)
        or value_type is bool
        or value_type is int
        or value_type is float
        or value_type is str
        or value_type is bytes
    ):
        return "unrelated"
    # The value is unrelated, but a later legacy ``str(value)`` would invoke a
    # user-defined protocol.  Quarantine only this row and retain the valid
    # target ledger rather than false-killing the Lane.
    return "unsafe_unrelated"


def _aisha_q5_physical_target_ledger(
    snapshot: dict[str, Any],
) -> _AishaQ5PhysicalTargetLedger:
    """Build one duplicate-safe 100107 ledger before generic q5 consumers."""

    def indexed_rows(value: Any) -> tuple[list[tuple[int, dict[str, Any]]], bool]:
        if value is None:
            return [], False
        if type(value) is dict:  # noqa: E721
            values = (value,)
        elif type(value) in {list, tuple}:  # noqa: E721
            values = value
        else:
            return [], True
        rows: list[tuple[int, dict[str, Any]]] = []
        malformed = False
        for index, row in enumerate(values):
            if type(row) is not dict or any(  # noqa: E721
                type(key) is not str for key in row  # noqa: E721
            ):
                malformed = True
                continue
            rows.append((index, dict(row)))
        return rows, malformed

    if dict.get(snapshot, _AISHA_Q5_PHYSICAL_TARGET_INVALID_KEY) is True:
        return _AishaQ5PhysicalTargetLedger("invalid")
    scope = _aisha_q5_total_cells_scope(snapshot)
    if scope is None:
        return _AishaQ5PhysicalTargetLedger("out_of_scope")
    ui_contract, session_id, epoch, round_no = scope
    actions = dict.get(ui_contract, "actions")
    ui_results = (
        dict.get(actions, "results")
        if type(actions) is dict  # noqa: E721
        else None
    )

    candidate_values: list[list[int]] = []
    quarantine_indices: list[tuple[int, ...]] = []
    invalid = False
    for container, ui_mirror in (
        (dict.get(snapshot, "action_result_rows"), False),
        (ui_results, True),
    ):
        rows, malformed = indexed_rows(container)
        if malformed:
            invalid = True
        candidates: list[int] = []
        quarantined: list[int] = []
        for index, row in rows:
            action_id_state = _aisha_q5_physical_action_id_state(
                dict.get(row, "action_id"),
                ui_mirror=ui_mirror,
            )
            if action_id_state == "malformed_target":
                invalid = True
                quarantined.append(index)
                continue
            if action_id_state == "unsafe_unrelated":
                quarantined.append(index)
                continue
            if action_id_state != "target":
                continue
            if not _aisha_q5_total_cells_row_scope_ok(
                row,
                session_id=session_id,
                epoch=epoch,
                round_no=round_no,
            ):
                invalid = True
                continue
            value = _aisha_q5_physical_varint_cells(
                row,
                ui_mirror=ui_mirror,
            )
            if value is None:
                invalid = True
                continue
            candidates.append(value)
        if len(candidates) > 1:
            invalid = True
        candidate_values.append(candidates)
        quarantine_indices.append(tuple(quarantined))

    root_candidates, ui_candidates = candidate_values
    if invalid:
        return _AishaQ5PhysicalTargetLedger(
            "invalid",
            session_id=session_id,
            epoch=epoch,
            round_no=round_no,
            root_quarantine_indices=quarantine_indices[0],
            ui_quarantine_indices=quarantine_indices[1],
        )
    if not root_candidates and not ui_candidates:
        return _AishaQ5PhysicalTargetLedger(
            "absent",
            session_id=session_id,
            epoch=epoch,
            round_no=round_no,
            root_quarantine_indices=quarantine_indices[0],
            ui_quarantine_indices=quarantine_indices[1],
        )
    if (
        len(root_candidates) != 1
        or len(ui_candidates) != 1
        or root_candidates[0] != ui_candidates[0]
    ):
        return _AishaQ5PhysicalTargetLedger(
            "invalid",
            session_id=session_id,
            epoch=epoch,
            round_no=round_no,
            root_quarantine_indices=quarantine_indices[0],
            ui_quarantine_indices=quarantine_indices[1],
        )
    return _AishaQ5PhysicalTargetLedger(
        "valid",
        session_id=session_id,
        epoch=epoch,
        round_no=round_no,
        q5_cells=root_candidates[0],
        root_quarantine_indices=quarantine_indices[0],
        ui_quarantine_indices=quarantine_indices[1],
    )


def _aisha_q5_physical_quarantine_target_rows(
    snapshot: dict[str, Any],
    ledger: _AishaQ5PhysicalTargetLedger,
) -> dict[str, Any]:
    """Remove only malformed target aliases before legacy row coercion."""

    if (
        ledger.status != "invalid"
        and not ledger.root_quarantine_indices
        and not ledger.ui_quarantine_indices
    ):
        return snapshot
    sanitized = dict.copy(snapshot)
    if ledger.status == "invalid":
        sanitized[_AISHA_Q5_PHYSICAL_TARGET_INVALID_KEY] = True

    def without_quarantined(value: Any, rejected: set[int]) -> list[dict[str, Any]]:
        if type(value) is dict:  # noqa: E721
            values = (value,)
        elif type(value) in {list, tuple}:  # noqa: E721
            values = value
        else:
            return []
        return [
            dict(row)
            for index, row in enumerate(values)
            if index not in rejected
            and type(row) is dict  # noqa: E721
            and all(type(key) is str for key in row)  # noqa: E721
        ]

    if ledger.root_quarantine_indices:
        rejected = set(ledger.root_quarantine_indices)
        sanitized["action_result_rows"] = without_quarantined(
            dict.get(snapshot, "action_result_rows"), rejected
        )

    ui_contract = dict.get(snapshot, "ui_contract")
    actions = dict.get(ui_contract, "actions") if type(ui_contract) is dict else None  # noqa: E721
    if ledger.ui_quarantine_indices:
        rejected = set(ledger.ui_quarantine_indices)
        sanitized_ui = dict.copy(ui_contract)
        sanitized_actions = dict.copy(actions)
        sanitized_actions["results"] = without_quarantined(
            dict.get(actions, "results"), rejected
        )
        sanitized_ui["actions"] = sanitized_actions
        sanitized["ui_contract"] = sanitized_ui
    return sanitized


def _aisha_q5_physical_select_action(
    snapshot: dict[str, Any],
    ui_contract: dict[str, Any],
    *,
    session_id: str,
    epoch: int,
    round_no: int,
) -> int | None:
    """Read the run-owned target ledger; direct helper calls rebuild it once."""

    ledger = _AISHA_Q5_PHYSICAL_TARGET_LEDGER.get()
    if ledger is None:
        ledger = _aisha_q5_physical_target_ledger(snapshot)
    if (
        ledger.status != "valid"
        or ledger.session_id != session_id
        or ledger.epoch != epoch
        or ledger.round_no != round_no
    ):
        return None
    return ledger.q5_cells


def _aisha_q5_physical_skill_signature(
    row: Mapping[str, Any],
    *,
    expected_quality: int,
    require_declared_count: bool,
) -> tuple[tuple[int, int | None, int, int, int], ...] | None:
    groups = [
        row.get(key)
        for key in ("observed_items", "revealed_items_detail")
        if row.get(key) is not None
    ]
    if not groups:
        return None
    signatures: list[tuple[tuple[int, int | None, int, int, int], ...]] = []
    for group in groups:
        if type(group) not in {list, tuple}:  # noqa: E721
            return None
        parsed: list[tuple[int, int | None, int, int, int]] = []
        for item in group:
            signature = _aisha_q5_total_cells_item_signature(
                item,
                expected_quality=expected_quality,
            )
            if signature is None:
                return None
            parsed.append(signature)
        parsed.sort(key=lambda item: item[0])
        if len({item[0] for item in parsed}) != len(parsed):
            return None
        signatures.append(tuple(parsed))
    if len(set(signatures)) != 1:
        return None
    signature = signatures[0]
    if require_declared_count and "revealed_items" not in row:
        return None
    if "revealed_items" in row and (
        _aisha_q5_total_cells_wire_int(row.get("revealed_items")) != len(signature)
    ):
        return None
    return signature


def _aisha_q5_physical_select_skills(
    snapshot: dict[str, Any],
    *,
    session_id: str,
    epoch: int,
    round_no: int,
) -> dict[int, tuple[tuple[int, int | None, int, int, int], ...]] | None:
    """Require one complete root row and one identical producer mirror per reveal."""

    containers = (
        (snapshot.get("skill_reveal_rows"), True),
        (snapshot.get("skill_reveals"), False),
    )
    mirrors: list[
        dict[int, tuple[tuple[int, int | None, int, int, int], ...]]
    ] = []
    for container, require_declared_count in containers:
        rows, malformed = _aisha_q5_total_cells_row_container(container)
        if malformed:
            return None
        selected: dict[int, tuple[tuple[int, int | None, int, int, int], ...]] = {}
        for row in rows:
            skill_id = _aisha_q5_total_cells_wire_int(row.get("skill_id"), minimum=1)
            if skill_id not in _AISHA_Q5_TOTAL_CELLS_SKILLS:
                continue
            if skill_id in selected:
                return None
            hero_id = row.get("hero_id")
            if hero_id is not None and _aisha_q5_total_cells_wire_int(hero_id) != 103:
                return None
            if not _aisha_q5_total_cells_row_scope_ok(
                row,
                session_id=session_id,
                epoch=epoch,
                round_no=round_no,
            ):
                return None
            signature = _aisha_q5_physical_skill_signature(
                row,
                expected_quality=_AISHA_Q5_TOTAL_CELLS_SKILLS[skill_id],
                require_declared_count=require_declared_count,
            )
            if signature is None:
                return None
            selected[skill_id] = signature
        if set(selected) != set(_AISHA_Q5_TOTAL_CELLS_SKILLS):
            return None
        mirrors.append(selected)
    return mirrors[0] if mirrors[0] == mirrors[1] else None


def _aisha_q5_physical_high_domains(
    snapshot: Mapping[str, Any],
    evidence: RefEvidence,
    skills: Mapping[
        int,
        tuple[tuple[int, int | None, int, int, int], ...],
    ],
) -> tuple[dict[str, Any], ...] | None:
    """Validate every mirrored domain against the active map catalog generation."""

    domains = tuple(evidence.physical_candidate_domains or ())
    if not domains:
        return None
    structured = snapshot.get("structured_ref_inputs")
    outline_rows = (
        structured.get("minimap_items")
        if isinstance(structured, Mapping)
        else None
    )
    if not isinstance(outline_rows, list):
        return None
    outline_by_runtime: dict[int, tuple[int | None, int, int, int, int | None]] = {}
    for row in outline_rows:
        if type(row) is not dict:  # noqa: E721
            return None
        runtime_id = row.get("runtime_id")
        local_index = row.get("local_index")
        width = row.get("width")
        height = row.get("height")
        cells = row.get("cells")
        quality = row.get("quality")
        if (
            type(runtime_id) is not int  # noqa: E721
            or runtime_id <= 0
            or runtime_id in outline_by_runtime
            or (local_index is not None and type(local_index) is not int)  # noqa: E721
            or type(width) is not int  # noqa: E721
            or type(height) is not int  # noqa: E721
            or width <= 0
            or height <= 0
            or type(cells) is not int  # noqa: E721
            or cells != width * height
            or (
                quality is not None
                and (type(quality) is not int or not 1 <= quality <= 6)  # noqa: E721
            )
        ):
            return None
        outline_by_runtime[runtime_id] = (
            local_index,
            min(width, height),
            max(width, height),
            cells,
            quality,
        )
    if len(outline_by_runtime) != len(domains):
        return None
    try:
        from bidking_lab.inference.v2 import (
            _category_membership,
            _validated_physical_category_catalog,
        )

        catalog, reachable_by_map, status, generation = (
            _validated_physical_category_catalog()
        )
    except Exception:
        return None
    if status != "ok" or not generation or evidence.map_id is None:
        return None
    reachable = reachable_by_map.get(int(evidence.map_id))
    if reachable is None:
        return None

    low_expected = {
        runtime_id: (quality, local_index, width, height, cells)
        for skill_id, items in skills.items()
        for quality in (_AISHA_Q5_TOTAL_CELLS_SKILLS[skill_id],)
        for runtime_id, local_index, width, height, cells in items
    }
    matched_low: set[int] = set()
    high: list[dict[str, Any]] = []
    for domain in domains:
        if (
            type(domain) is not dict  # noqa: E721
            or domain.get("catalog_status") != "ok"
            or domain.get("catalog_generation") != generation
            or domain.get("physical_support_eligible") is not True
        ):
            return None
        shape_key = domain.get("shape_key")
        if type(shape_key) is not str or len(shape_key) != 2 or not shape_key.isdigit():  # noqa: E721
            return None
        width, height = int(shape_key[0]), int(shape_key[1])
        cells = int(domain.get("cells"))
        required = tuple(domain.get("required_categories") or ())
        excluded = tuple(domain.get("excluded_categories") or ())
        excluded_qualities = set(domain.get("excluded_qualities") or ())
        observed_quality = domain.get("observed_quality")
        candidates: list[tuple[int, int, int]] = []
        membership_complete = True
        for item_id in sorted(reachable):
            row = catalog.get(int(item_id))
            if row is None:
                return None
            quality, value, item_width, item_height, _categories = row
            if (int(item_width), int(item_height)) != (width, height):
                continue
            if int(item_width) * int(item_height) != cells:
                continue
            if observed_quality is not None and int(quality) != int(observed_quality):
                continue
            if int(quality) in excluded_qualities:
                continue
            required_states = tuple(
                _category_membership(row, int(category)) for category in required
            )
            excluded_states = tuple(
                _category_membership(row, int(category)) for category in excluded
            )
            if "no" in required_states or "yes" in excluded_states:
                continue
            membership_complete = membership_complete and all(
                state == "yes" for state in required_states
            ) and all(state == "no" for state in excluded_states)
            candidates.append((int(item_id), int(quality), int(value)))
        if (
            not candidates
            or not membership_complete
            or tuple(domain.get("candidate_item_ids") or ())
            != tuple(item_id for item_id, _quality, _value in candidates)
            or tuple(domain.get("candidate_qualities") or ())
            != tuple(sorted({quality for _item_id, quality, _value in candidates}))
            or tuple(domain.get("candidate_values") or ())
            != tuple(sorted({value for _item_id, _quality, value in candidates}))
        ):
            return None
        runtime_id = int(domain["runtime_id"])
        outline_identity = outline_by_runtime.get(runtime_id)
        if (
            outline_identity is None
            or outline_identity
            != (
                domain.get("local_index"),
                min(width, height),
                max(width, height),
                cells,
                observed_quality,
            )
        ):
            return None
        expected_low = low_expected.get(runtime_id)
        if expected_low is not None:
            quality, local_index, low_width, low_height, low_cells = expected_low
            if (
                runtime_id in matched_low
                or domain.get("observed_quality") != quality
                or tuple(domain.get("candidate_qualities") or ()) != (quality,)
                or domain.get("hard_eligible") is not True
                or domain.get("local_index") != local_index
                or min(width, height) != low_width
                or max(width, height) != low_height
                or cells != low_cells
            ):
                return None
            matched_low.add(runtime_id)
            continue
        candidate_qualities = tuple(domain.get("candidate_qualities") or ())
        if (
            domain.get("observed_quality") is not None
            or domain.get("quality") is not None
            or domain.get("hard_eligible") is not False
            or not candidate_qualities
            or not set(candidate_qualities).issubset({5, 6})
        ):
            return None
        high.append(dict(domain))
    if (
        set(low_expected) != matched_low
        or set(outline_by_runtime)
        != {int(domain["runtime_id"]) for domain in domains}
        or not high
    ):
        return None
    if len(high) > AISHA_Q5_TOTAL_CELLS_PHYSICAL_MAX_DOMAINS:
        return None
    return tuple(high)


def _aisha_q5_physical_joint_value_context(
    snapshot: dict[str, Any],
    evidence: RefEvidence,
    combos: Sequence[RefCombo],
) -> _AishaQ5TotalCellsValueContext | None:
    """Condition every reachable q5/q6 count/cells arm on the physical catalog."""

    if (
        _run_env_get(AISHA_Q5_TOTAL_CELLS_VALUE_DISABLE) == "1"
        or snapshot.get("_aisha_q5_total_cells_wire_invalid") is True
        or not combos
        or normalize_hero_key(evidence.hero) != "aisha"
        or str(evidence.phase).strip().lower() != "bidding"
        or evidence.map_id is None
        or evidence.total_count is not None
        or any(evidence.fixed_counts.get(key) is not None for key in ("q5", "q6"))
        or any(evidence.avg_cells.get(key) is not None for key in ("q5", "q6"))
        or any(evidence.avg_values.get(key) is not None for key in ("q5", "q6"))
        or any(evidence.quality_values.get(key) is not None for key in ("q5", "q6"))
        or any(evidence.quality_value_floors.get(key) is not None for key in ("q5", "q6"))
        or evidence.q5_known_item_facts
        or evidence.q6_known_item_facts
        or "q5" in (evidence.quality_count_cells_options or {})
        or "q6" in (evidence.quality_count_cells_options or {})
        or _hard_total_grid_target_int(evidence) is not None
        or any("conflict" in str(note) for note in evidence.source_notes)
    ):
        return None
    q5_cells = _exact_integer_quality_cell(evidence.quality_cells.get("q5"))
    if q5_cells is None or q5_cells <= 0:
        return None
    scope = _aisha_q5_total_cells_scope(snapshot)
    if scope is None:
        return None
    ui_contract, session_id, epoch, round_no = scope
    action_q5_cells = _aisha_q5_physical_select_action(
        snapshot,
        ui_contract,
        session_id=session_id,
        epoch=epoch,
        round_no=round_no,
    )
    skills = _aisha_q5_physical_select_skills(
        snapshot,
        session_id=session_id,
        epoch=epoch,
        round_no=round_no,
    )
    if action_q5_cells != q5_cells or skills is None:
        return None
    skill_counts = {
        quality: len(skills[skill_id])
        for skill_id, quality in _AISHA_Q5_TOTAL_CELLS_SKILLS.items()
    }
    skill_cells = {
        quality: sum(item[4] for item in skills[skill_id])
        for skill_id, quality in _AISHA_Q5_TOTAL_CELLS_SKILLS.items()
    }
    expected_low_counts = {
        "q1": skill_counts[1] + skill_counts[2],
        "q3": skill_counts[3],
        "q4": skill_counts[4],
    }
    if (
        evidence.split_counts.get("white") != skill_counts[1]
        or evidence.split_counts.get("green") != skill_counts[2]
        or _exact_integer_quality_cell(evidence.split_quality_cells.get("white"))
        != skill_cells[1]
        or _exact_integer_quality_cell(evidence.split_quality_cells.get("green"))
        != skill_cells[2]
        or any(evidence.fixed_counts.get(key) != expected for key, expected in expected_low_counts.items())
        or _exact_integer_quality_cell(evidence.quality_cells.get("q1"))
        != skill_cells[1] + skill_cells[2]
        or _exact_integer_quality_cell(evidence.quality_cells.get("q3")) != skill_cells[3]
        or _exact_integer_quality_cell(evidence.quality_cells.get("q4")) != skill_cells[4]
    ):
        return None
    high_domains = _aisha_q5_physical_high_domains(snapshot, evidence, skills)
    if high_domains is None:
        return None

    q5_catalog = _validated_map_quality_catalog(int(evidence.map_id), 5)
    q6_catalog = _validated_map_quality_catalog(int(evidence.map_id), 6)
    if q5_catalog[2] != "ok" or q6_catalog[2] != "ok":
        return None
    if (
        not q5_catalog[3]
        or q5_catalog[3] != q6_catalog[3]
        or any(domain["catalog_generation"] != q5_catalog[3] for domain in high_domains)
    ):
        return None
    catalog_by_id = {
        int(item_id): (quality, int(raw_value), int(cells))
        for quality, catalog_rows in ((5, q5_catalog[1]), (6, q6_catalog[1]))
        for item_id, raw_value, cells in catalog_rows
    }
    map_payload = _load_drop_weight_items().get(int(evidence.map_id))
    item_payload = (
        map_payload.get("items") if isinstance(map_payload, Mapping) else None
    )
    if not isinstance(item_payload, Mapping):
        return None

    physical_distributions: dict[
        tuple[int, int, int, int],
        dict[tuple[int, int], float],
    ] = {(0, 0, 0, 0): {(0, 0): 1.0}}
    physical_floors: dict[
        tuple[int, int, int, int],
        tuple[int, int],
    ] = {(0, 0, 0, 0): (0, 0)}
    for domain in high_domains:
        cells = int(domain["cells"])
        candidate_options: list[tuple[int, int, int, float]] = []
        for item_id in domain["candidate_item_ids"]:
            catalog_row = catalog_by_id.get(int(item_id))
            raw_weight = item_payload.get(str(item_id))
            if raw_weight is None:
                raw_weight = item_payload.get(item_id)
            if (
                catalog_row is None
                or not isinstance(raw_weight, (list, tuple))
                or len(raw_weight) < 3
            ):
                return None
            quality, raw_value, catalog_cells = catalog_row
            try:
                weight = float(raw_weight[0])
                weighted_raw_value = float(raw_weight[1])
                fitted_value = float(raw_weight[2])
            except (TypeError, ValueError, OverflowError):
                return None
            if (
                quality not in {5, 6}
                or catalog_cells != cells
                or not all(
                    math.isfinite(value)
                    for value in (weight, weighted_raw_value, fitted_value)
                )
                or weight < 0
                or not weighted_raw_value.is_integer()
                or int(weighted_raw_value) != raw_value
                or not fitted_value.is_integer()
                or fitted_value <= 0
            ):
                return None
            if weight > 0:
                candidate_options.append(
                    (quality, raw_value, int(fitted_value), weight)
                )
        option_total = math.fsum(option[3] for option in candidate_options)
        if not candidate_options or not math.isfinite(option_total) or option_total <= 0:
            return None

        next_distributions: dict[
            tuple[int, int, int, int],
            dict[tuple[int, int], float],
        ] = {}
        next_floors: dict[
            tuple[int, int, int, int],
            tuple[int, int],
        ] = {}
        for state, distribution in physical_distributions.items():
            old_q5_count, old_q5_cells, old_q6_count, old_q6_cells = state
            old_q5_floor, old_q6_floor = physical_floors[state]
            for quality, raw_value, fitted_value, raw_weight in candidate_options:
                option_weight = raw_weight / option_total
                if quality == 5:
                    next_state = (
                        old_q5_count + 1,
                        old_q5_cells + cells,
                        old_q6_count,
                        old_q6_cells,
                    )
                    next_floor = (old_q5_floor + raw_value, old_q6_floor)
                else:
                    next_state = (
                        old_q5_count,
                        old_q5_cells,
                        old_q6_count + 1,
                        old_q6_cells + cells,
                    )
                    next_floor = (old_q5_floor, old_q6_floor + raw_value)
                target = next_distributions.setdefault(next_state, {})
                for (q5_value, q6_value), prior_weight in distribution.items():
                    next_values = (
                        q5_value + fitted_value if quality == 5 else q5_value,
                        q6_value + fitted_value if quality == 6 else q6_value,
                    )
                    target[next_values] = (
                        target.get(next_values, 0.0)
                        + prior_weight * option_weight
                    )
                if next_state in next_floors:
                    old_floor = next_floors[next_state]
                    next_floors[next_state] = (
                        min(old_floor[0], next_floor[0]),
                        min(old_floor[1], next_floor[1]),
                    )
                else:
                    next_floors[next_state] = next_floor
        physical_distributions = {}
        for state, distribution in next_distributions.items():
            compressed = _aisha_q5_total_cells_joint_quantile_bins(
                distribution,
                bins=AISHA_Q5_TOTAL_CELLS_PHYSICAL_INTERMEDIATE_BINS,
                normalize=False,
            )
            if compressed:
                physical_distributions[state] = {
                    (q5_value, q6_value): weight
                    for q5_value, q6_value, weight in compressed
                }
        physical_floors = {
            state: next_floors[state] for state in physical_distributions
        }
        if (
            not physical_distributions
            or sum(len(values) for values in physical_distributions.values())
            > AISHA_Q5_TOTAL_CELLS_VALUE_MAX_STATES
        ):
            return None

    q5_sizes = tuple(sorted({int(row[2]) for row in q5_catalog[1]}))
    q6_sizes = tuple(sorted({int(row[2]) for row in q6_catalog[1]}))
    compose_cache: dict[tuple[int, int, tuple[int, ...]], bool] = {}

    def can_compose(count: int, cells: int, sizes: tuple[int, ...]) -> bool:
        key = (int(count), int(cells), sizes)
        if key in compose_cache:
            return compose_cache[key]
        if count == 0:
            result = cells == 0
        elif count < 0 or cells <= 0:
            result = False
        else:
            result = any(
                can_compose(count - 1, cells - size, sizes)
                for size in sizes
                if cells >= size
            )
        compose_cache[key] = result
        return result

    compatible_by_state: dict[
        tuple[int, int, int, int],
        tuple[tuple[int, int, int, int], ...],
    ] = {}
    for combo in combos:
        state = (
            int(combo.counts.get("q5", 0)),
            int(round(float(combo.grids.get("q5", 0.0)))),
            int(combo.counts.get("q6", 0)),
            int(round(float(combo.grids.get("q6", 0.0)))),
        )
        if (
            state[1] != q5_cells
            or any(int(combo.counts.get(key, 0)) != expected for key, expected in expected_low_counts.items())
        ):
            return None
        compatible = tuple(
            physical_state
            for physical_state in physical_distributions
            for (
                visible_q5_count,
                visible_q5_cells,
                visible_q6_count,
                visible_q6_cells,
            ) in (physical_state,)
            if state[0] >= visible_q5_count
            and state[1] >= visible_q5_cells
            and state[2] >= visible_q6_count
            and state[3] >= visible_q6_cells
            and can_compose(
                state[0] - visible_q5_count,
                state[1] - visible_q5_cells,
                q5_sizes,
            )
            and can_compose(
                state[2] - visible_q6_count,
                state[3] - visible_q6_cells,
                q6_sizes,
            )
        )
        if compatible:
            compatible_by_state[state] = compatible
    if not compatible_by_state:
        return None
    q5_targets = tuple(
        sorted(
            {
                (state[0] - physical[0], state[1] - physical[1])
                for state, physical_states in compatible_by_state.items()
                for physical in physical_states
            }
        )
    )
    q6_targets = tuple(
        sorted(
            {
                (state[2] - physical[2], state[3] - physical[3])
                for state, physical_states in compatible_by_state.items()
                for physical in physical_states
            }
        )
    )
    q5_status, q5_rows, q5_context = _aisha_map_quality_value_distributions(
        int(evidence.map_id),
        5,
        q5_targets,
    )
    q6_status, q6_rows, q6_context = _aisha_map_quality_value_distributions(
        int(evidence.map_id),
        6,
        q6_targets,
    )
    if q5_status != "ok" or q6_status != "ok":
        return None
    q5_by_target = {(row[0], row[1]): row[2:] for row in q5_rows}
    q6_by_target = {(row[0], row[1]): row[2:] for row in q6_rows}
    arms: list[_AishaQ5TotalCellsValueArm] = []
    projected_points = 0
    for q5_count, q5_total, q6_count, q6_total in sorted(compatible_by_state):
        state = (q5_count, q5_total, q6_count, q6_total)
        q5_distribution: dict[int, float] = {}
        q6_distribution: dict[int, float] = {}
        high_distribution: dict[int, float] = {}
        q5_floor_candidates: list[int] = []
        q6_floor_candidates: list[int] = []
        for physical_state in compatible_by_state[state]:
            physical_distribution = physical_distributions[physical_state]
            residual_q5_target = (
                q5_count - physical_state[0],
                q5_total - physical_state[1],
            )
            residual_q6_target = (
                q6_count - physical_state[2],
                q6_total - physical_state[3],
            )
            residual_q5_points, residual_q5_floor, _p50, _p90 = (
                q5_by_target[residual_q5_target]
            )
            residual_q6_points, residual_q6_floor, _p50, _p90 = (
                q6_by_target[residual_q6_target]
            )
            physical_q5: dict[int, float] = {}
            physical_q6: dict[int, float] = {}
            physical_high: dict[int, float] = {}
            for (physical_q5_value, physical_q6_value), weight in physical_distribution.items():
                physical_q5[physical_q5_value] = (
                    physical_q5.get(physical_q5_value, 0.0) + weight
                )
                physical_q6[physical_q6_value] = (
                    physical_q6.get(physical_q6_value, 0.0) + weight
                )
                physical_total = physical_q5_value + physical_q6_value
                physical_high[physical_total] = (
                    physical_high.get(physical_total, 0.0) + weight
                )
            residual_high: dict[int, float] = {}
            for q5_value, q5_weight in residual_q5_points:
                for q6_value, q6_weight in residual_q6_points:
                    total_value = int(round(q5_value + q6_value))
                    residual_high[total_value] = (
                        residual_high.get(total_value, 0.0)
                        + q5_weight * q6_weight
                    )
            residual_high_points = _aisha_q5_total_cells_linear_quantile_bins(
                residual_high,
                bins=AISHA_Q5_TOTAL_CELLS_PHYSICAL_VALUE_BINS,
            )
            for physical_value, physical_weight in physical_q5.items():
                for residual_value, residual_weight in residual_q5_points:
                    total_value = int(round(physical_value + residual_value))
                    q5_distribution[total_value] = (
                        q5_distribution.get(total_value, 0.0)
                        + physical_weight * residual_weight
                    )
            for physical_value, physical_weight in physical_q6.items():
                for residual_value, residual_weight in residual_q6_points:
                    total_value = int(round(physical_value + residual_value))
                    q6_distribution[total_value] = (
                        q6_distribution.get(total_value, 0.0)
                        + physical_weight * residual_weight
                    )
            for physical_value, physical_weight in physical_high.items():
                for residual_value, residual_weight in residual_high_points:
                    total_value = int(round(physical_value + residual_value))
                    high_distribution[total_value] = (
                        high_distribution.get(total_value, 0.0)
                        + physical_weight * residual_weight
                    )
            physical_q5_floor, physical_q6_floor = physical_floors[physical_state]
            q5_floor_candidates.append(physical_q5_floor + int(residual_q5_floor))
            q6_floor_candidates.append(physical_q6_floor + int(residual_q6_floor))
            if len(q5_distribution) > AISHA_Q5_TOTAL_CELLS_PHYSICAL_INTERMEDIATE_BINS:
                q5_distribution = dict(
                    _aisha_q5_total_cells_linear_quantile_bins(
                        q5_distribution,
                        bins=AISHA_Q5_TOTAL_CELLS_PHYSICAL_INTERMEDIATE_BINS,
                        normalize=False,
                    )
                )
            if len(q6_distribution) > AISHA_Q5_TOTAL_CELLS_PHYSICAL_INTERMEDIATE_BINS:
                q6_distribution = dict(
                    _aisha_q5_total_cells_linear_quantile_bins(
                        q6_distribution,
                        bins=AISHA_Q5_TOTAL_CELLS_PHYSICAL_INTERMEDIATE_BINS,
                        normalize=False,
                    )
                )
            if len(high_distribution) > AISHA_Q5_TOTAL_CELLS_PHYSICAL_INTERMEDIATE_BINS:
                high_distribution = dict(
                    _aisha_q5_total_cells_linear_quantile_bins(
                        high_distribution,
                        bins=AISHA_Q5_TOTAL_CELLS_PHYSICAL_INTERMEDIATE_BINS,
                        normalize=False,
                    )
                )
        q5_points = _aisha_q5_total_cells_linear_quantile_bins(
            q5_distribution,
            bins=AISHA_Q5_TOTAL_CELLS_PHYSICAL_VALUE_BINS,
        )
        q6_points = _aisha_q5_total_cells_linear_quantile_bins(
            q6_distribution,
            bins=AISHA_Q5_TOTAL_CELLS_PHYSICAL_VALUE_BINS,
        )
        high_points = _aisha_q5_total_cells_linear_quantile_bins(
            high_distribution,
            bins=AISHA_Q5_TOTAL_CELLS_PHYSICAL_VALUE_BINS,
        )
        q5_p50 = _raven_weighted_quantile(q5_distribution, 0.50)
        q5_p90 = _raven_weighted_quantile(q5_distribution, 0.90)
        q6_p50 = _raven_weighted_quantile(q6_distribution, 0.50)
        q6_p90 = _raven_weighted_quantile(q6_distribution, 0.90)
        high_p50 = _raven_weighted_quantile(high_distribution, 0.50)
        high_p90 = _raven_weighted_quantile(high_distribution, 0.90)
        state_likelihood = math.fsum(high_distribution.values())
        if (
            not q5_points
            or not q6_points
            or not high_points
            or q5_p50 is None
            or q5_p90 is None
            or q6_p50 is None
            or q6_p90 is None
            or high_p50 is None
            or high_p90 is None
            or not math.isfinite(state_likelihood)
            or state_likelihood <= 0
            or not q5_floor_candidates
            or not q6_floor_candidates
        ):
            return None
        projected_points += len(high_points) * len(VALUE_DISTRIBUTION_POINTS)
        if projected_points > AISHA_Q5_TOTAL_CELLS_VALUE_MAX_POSTERIOR_POINTS:
            return None
        arms.append(
            _AishaQ5TotalCellsValueArm(
                q5_count=q5_count,
                q5_cells=q5_total,
                value_points=tuple(
                    (float(value), float(weight)) for value, weight in q5_points
                ),
                floor_value=min(q5_floor_candidates),
                p50_value=int(q5_p50),
                p90_value=int(q5_p90),
                catalog_context=(
                    f"{q5_context};{q6_context};"
                    f"physical_domains:{len(high_domains)};"
                    "owner_composition:conditioned"
                ),
                q6_count=q6_count,
                q6_cells=q6_total,
                q6_value_points=tuple(
                    (float(value), float(weight)) for value, weight in q6_points
                ),
                q6_floor_value=min(q6_floor_candidates),
                q6_p50_value=int(q6_p50),
                q6_p90_value=int(q6_p90),
                high_value_points=tuple(
                    (float(value), float(weight)) for value, weight in high_points
                ),
                high_floor_value=min(
                    q5_floor + q6_floor
                    for q5_floor, q6_floor in zip(
                        q5_floor_candidates,
                        q6_floor_candidates,
                    )
                ),
                high_p50_value=int(high_p50),
                high_p90_value=int(high_p90),
                physical_likelihood=state_likelihood,
            )
        )
    return _AishaQ5TotalCellsValueContext(
        arms=tuple(arms),
        session_id=session_id,
        epoch=epoch,
        round_no=round_no,
        total_count=None,
        residual_count=None,
        source_ids=(
            _AISHA_Q5_TOTAL_CELLS_ACTION_ID,
            *_AISHA_Q5_TOTAL_CELLS_SKILLS,
        ),
        physical_domain_count=len(high_domains),
        physical_joint=True,
    )


def _aisha_q5_total_cells_exact_zero_count_overrides(
    snapshot: dict[str, Any],
    evidence: RefEvidence,
    total: int,
) -> tuple[dict[str, tuple[int, ...]], dict[str, float]] | None:
    """Admit only the q5 complement proven by full low reveals and exact q6 zero."""
    if (
        _run_env_get(AISHA_Q5_TOTAL_CELLS_VALUE_DISABLE) == "1"
        or snapshot.get("_aisha_q5_total_cells_wire_invalid") is True
        or evidence.total_count is None
        or int(evidence.total_count) != int(total)
        or evidence.fixed_counts.get("q6") != 0
        or _exact_integer_quality_cell(evidence.quality_cells.get("q6")) != 0
        or _aisha_q5_total_cells_raw_q6_authority(snapshot)
        != ("exact_zero", 0, 0)
    ):
        return None
    scope = _aisha_q5_total_cells_scope(snapshot)
    if scope is None:
        return None
    ui_contract, session_id, epoch, round_no = scope
    actions = _aisha_q5_total_cells_select_actions(
        snapshot,
        ui_contract,
        session_id=session_id,
        epoch=epoch,
        round_no=round_no,
    )
    skills = _aisha_q5_total_cells_select_skills(
        snapshot,
        session_id=session_id,
        epoch=epoch,
        round_no=round_no,
    )
    if actions is None or skills is None:
        return None
    action_q5_cells, action_total = actions
    low_counts = {
        "q1": len(skills[1001034]) + len(skills[1001033]),
        "q3": len(skills[1001032]),
        "q4": len(skills[1001031]),
    }
    q5_count = int(total) - sum(low_counts.values())
    if action_total != int(total) or q5_count <= 0:
        return None
    counts = {**low_counts, "q5": q5_count, "q6": 0}
    grids = {
        "q1": float(
            sum(item[4] for item in skills[1001034])
            + sum(item[4] for item in skills[1001033])
        ),
        "q3": float(sum(item[4] for item in skills[1001032])),
        "q4": float(sum(item[4] for item in skills[1001031])),
        "q5": float(action_q5_cells),
        "q6": 0.0,
    }
    probe = RefCombo(
        counts=counts,
        grids=grids,
        value=0.0,
        weight=0.0,
        total_grid=sum(grids.values()),
    )
    context = _aisha_q5_total_cells_value_context(snapshot, evidence, (probe,))
    if context is None or len(context.arms) != 1:
        return None
    return (
        {key: (int(value),) for key, value in counts.items()},
        grids,
    )


def _raven_outline_summary_template(
    *,
    status: str = "unavailable",
    reason: str = "",
    quality_scan_count: int = 0,
    outline_count: int = 0,
    red_count: int = 0,
    paired_red_count: int = 0,
) -> dict[str, Any]:
    """Return the stable additive RF1 view-model in every eligibility state."""
    return {
        "status": status,
        "eligibility_complete": False,
        "floor_kind": "per_item_footprint_catalog_min",
        "floor_value": None,
        "p50_value": None,
        "p90_value": None,
        "quality_scan_count": int(max(0, quality_scan_count)),
        "outline_count": int(max(0, outline_count)),
        "red_count": int(max(0, red_count)),
        "paired_red_count": int(max(0, paired_red_count)),
        "footprint_cells": [],
        "catalog_context": "",
        "source_ids": [100100, RAVEN_ALL_ITEM_QUALITY_SKILL_ID],
        "conflicts": [reason] if reason else [],
    }


def _raven_strict_int(value: Any, *, minimum: int = 0) -> int | None:
    if isinstance(value, bool) or value in (None, ""):
        return None
    if isinstance(value, int):
        parsed = value
    elif isinstance(value, float):
        if not math.isfinite(value) or not value.is_integer():
            return None
        parsed = int(value)
    elif isinstance(value, str):
        text = value.strip()
        if re.fullmatch(r"-?\d+", text) is None:
            return None
        parsed = int(text)
    else:
        return None
    return parsed if parsed >= int(minimum) else None


def _raven_shape(value: Any) -> tuple[int, int] | None:
    parsed = _raven_strict_int(value, minimum=1)
    if parsed is None:
        return None
    width = parsed // 10
    height = parsed % 10
    if width <= 0 or height <= 0:
        return None
    return min(width, height), max(width, height)


def _raven_row_items(row: Mapping[str, Any]) -> list[Mapping[str, Any]] | None:
    raw_items = row.get("observed_items")
    if raw_items is None:
        raw_items = row.get("revealed_items_detail")
    if not isinstance(raw_items, (list, tuple)) or not raw_items:
        return None
    if any(not isinstance(item, Mapping) for item in raw_items):
        return None
    return list(raw_items)


def _raven_row_signature(row: Mapping[str, Any]) -> tuple[Any, ...]:
    raw_items = row.get("observed_items")
    if raw_items is None:
        raw_items = row.get("revealed_items_detail")
    if not isinstance(raw_items, (list, tuple)):
        return ("invalid-items", type(raw_items).__name__)
    signatures: list[tuple[str, ...]] = []
    for item in raw_items:
        if not isinstance(item, Mapping):
            signatures.append(("invalid-item", type(item).__name__))
            continue
        signatures.append(
            tuple(
                str(item.get(key))
                for key in (
                    "runtime_id",
                    "local_index",
                    "quality",
                    "shape_code",
                    "shape_key",
                    "cells",
                )
            )
        )
    return tuple(sorted(signatures))


def _raven_select_latest_row(
    rows: Iterable[Mapping[str, Any]],
) -> tuple[Mapping[str, Any] | None, str]:
    candidates = [row for row in rows if isinstance(row, Mapping)]
    if not candidates:
        return None, "missing"
    with_sort = [
        (sort_id, row)
        for row in candidates
        if (sort_id := _raven_strict_int(row.get("sort"), minimum=0)) is not None
    ]
    if with_sort:
        newest = max(sort_id for sort_id, _row in with_sort)
        candidates = [row for sort_id, row in with_sort if sort_id == newest]
    unique: dict[tuple[Any, ...], Mapping[str, Any]] = {}
    for row in candidates:
        unique.setdefault(_raven_row_signature(row), row)
    if len(unique) != 1:
        return None, "conflicting_latest_rows"
    return next(iter(unique.values())), "ok"


def _raven_full_outline_rows(
    snapshot: Mapping[str, Any],
) -> Iterable[Mapping[str, Any]]:
    groups: list[Any] = [snapshot.get("action_result_rows")]
    ui_contract = snapshot.get("ui_contract")
    if isinstance(ui_contract, Mapping):
        actions = ui_contract.get("actions")
        if isinstance(actions, Mapping):
            groups.append(actions.get("results"))
    for rows in groups:
        if not isinstance(rows, (list, tuple)):
            continue
        for row in rows:
            if (
                isinstance(row, Mapping)
                and _raven_strict_int(row.get("action_id"), minimum=1) == 100100
            ):
                yield row


def _raven_full_quality_rows(
    snapshot: Mapping[str, Any],
) -> Iterable[Mapping[str, Any]]:
    for key in ("skill_reveal_rows", "skill_reveals"):
        rows = snapshot.get(key)
        if not isinstance(rows, (list, tuple)):
            continue
        for row in rows:
            if not isinstance(row, Mapping):
                continue
            if (
                _raven_strict_int(row.get("skill_id"), minimum=1)
                != RAVEN_ALL_ITEM_QUALITY_SKILL_ID
                or _raven_strict_int(row.get("hero_id"), minimum=1)
                != RAVEN_HERO_ID
            ):
                continue
            yield row


def _raven_official_distribution_status(
    snapshot: Mapping[str, Any],
) -> tuple[bool, str, str]:
    """Require an explicit, internally consistent official-source contract.

    The hard per-shape catalog floor is source-agnostic, but RF1 publishes it
    together with P50/P90 derived from official per-map item weights.  Unknown
    and confirmed player-custom warehouses therefore cannot consume the
    three-number summary as one eligible unit.
    """
    missing = object()
    warehouse_source = snapshot.get("warehouse_source", missing)
    if warehouse_source is missing:
        return False, "unavailable", "warehouse_source_eligibility_missing"
    if not isinstance(warehouse_source, Mapping):
        return False, "conflict", "warehouse_source_eligibility_malformed"
    ui_contract = snapshot.get("ui_contract", missing)
    if ui_contract is missing:
        return False, "unavailable", "warehouse_source_eligibility_missing"
    if not isinstance(ui_contract, Mapping):
        return False, "conflict", "warehouse_source_eligibility_malformed"
    context = ui_contract.get("context", missing)
    if context is missing:
        return False, "unavailable", "warehouse_source_eligibility_missing"
    if not isinstance(context, Mapping):
        return False, "conflict", "warehouse_source_eligibility_malformed"
    context_source = context.get("warehouse_source", missing)
    if context_source is missing:
        return False, "unavailable", "warehouse_source_eligibility_missing"
    if not isinstance(context_source, Mapping):
        return False, "conflict", "warehouse_source_eligibility_malformed"

    qualifications = (
        snapshot.get("warehouse_source_qualification", missing),
        warehouse_source.get("qualification", missing),
        context.get("warehouse_source_qualification", missing),
        context_source.get("qualification", missing),
    )
    if any(value is missing for value in qualifications):
        return False, "unavailable", "warehouse_source_eligibility_missing"
    if any(
        not isinstance(value, str)
        or value
        not in {
            "official_random_warehouse",
            "postupdate_unknown_warehouse_source",
            "player_custom_warehouse",
        }
        for value in qualifications
    ):
        return False, "conflict", "warehouse_source_eligibility_malformed"
    qualification_set = set(qualifications)
    if len(qualification_set) != 1:
        return False, "conflict", "warehouse_source_eligibility_conflict"
    if "official_random_warehouse" not in qualification_set:
        return (
            False,
            "unavailable",
            "warehouse_source_not_official_distribution_eligible",
        )

    candidates = (
        snapshot.get("official_distribution_eligible", missing),
        warehouse_source.get("official_distribution_eligible", missing),
        context.get("official_distribution_eligible", missing),
        context_source.get("official_distribution_eligible", missing),
    )
    if any(value is missing for value in candidates):
        return False, "unavailable", "warehouse_source_eligibility_missing"
    if any(not isinstance(value, bool) for value in candidates):
        return False, "conflict", "warehouse_source_eligibility_malformed"
    flags = set(candidates)
    if len(flags) != 1:
        return False, "conflict", "warehouse_source_eligibility_conflict"
    if True not in flags:
        return (
            False,
            "unavailable",
            "warehouse_source_not_official_distribution_eligible",
        )
    return True, "ok", ""


def _raven_pair_quality_and_outline_items(
    quality_items: Sequence[Mapping[str, Any]],
    outline_items: Sequence[Mapping[str, Any]],
) -> tuple[
    tuple[tuple[Mapping[str, Any], Mapping[str, Any]], ...],
    str,
]:
    """Pair complete all-item rows without crossing physical identities.

    Runtime identity is the normal wire contract.  A strict all-local fallback
    is allowed only when at least one side lacks runtime identity; if both
    sides publish different runtime IDs for one local position, the evidence
    conflicts instead of silently pairing by position.
    """
    if len(quality_items) != len(outline_items):
        return (), "item_count_mismatch"

    def ids(
        items: Sequence[Mapping[str, Any]],
        key: str,
    ) -> list[int | None]:
        minimum = 1 if key == "runtime_id" else 0
        return [_raven_strict_int(item.get(key), minimum=minimum) for item in items]

    quality_runtime = ids(quality_items, "runtime_id")
    outline_runtime = ids(outline_items, "runtime_id")
    if all(value is not None for value in quality_runtime + outline_runtime):
        if len(set(quality_runtime)) != len(quality_runtime):
            return (), "duplicate_quality_runtime_id"
        if len(set(outline_runtime)) != len(outline_runtime):
            return (), "duplicate_outline_runtime_id"
        outline_by_runtime = {
            int(runtime_id): item
            for runtime_id, item in zip(outline_runtime, outline_items)
            if runtime_id is not None
        }
        if set(int(value) for value in quality_runtime if value is not None) != set(
            outline_by_runtime
        ):
            return (), "runtime_identity_set_mismatch"
        return (
            tuple(
                (quality_item, outline_by_runtime[int(runtime_id)])
                for quality_item, runtime_id in zip(quality_items, quality_runtime)
                if runtime_id is not None
            ),
            "runtime_id",
        )

    quality_local = ids(quality_items, "local_index")
    outline_local = ids(outline_items, "local_index")
    if any(value is None for value in quality_local + outline_local):
        return (), "missing_stable_identity"
    if len(set(quality_local)) != len(quality_local):
        return (), "duplicate_quality_local_index"
    if len(set(outline_local)) != len(outline_local):
        return (), "duplicate_outline_local_index"
    outline_by_local = {
        int(local_index): (item, runtime_id)
        for local_index, runtime_id, item in zip(
            outline_local, outline_runtime, outline_items
        )
        if local_index is not None
    }
    if set(int(value) for value in quality_local if value is not None) != set(
        outline_by_local
    ):
        return (), "local_identity_set_mismatch"
    pairs: list[tuple[Mapping[str, Any], Mapping[str, Any]]] = []
    for quality_item, local_index, quality_runtime_id in zip(
        quality_items, quality_local, quality_runtime
    ):
        if local_index is None:
            return (), "missing_quality_local_index"
        outline_item, outline_runtime_id = outline_by_local[int(local_index)]
        if (
            quality_runtime_id is not None
            and outline_runtime_id is not None
            and int(quality_runtime_id) != int(outline_runtime_id)
        ):
            return (), "runtime_conflict_on_local_fallback"
        pairs.append((quality_item, outline_item))
    return tuple(pairs), "local_index"


@lru_cache(maxsize=1)
def _validated_q6_outline_catalog(
) -> tuple[tuple[tuple[int, int, int, int], ...], str]:
    """Cross-check q6 item identity, value, and canonical footprint shape."""
    _pairs, id_rows, status = _validated_q6_catalog()
    if status != "ok" or not id_rows:
        return (), status
    validated_ids = {int(item_id) for item_id, _value, _cells in id_rows}
    try:
        payload = _moat_json(ROOT / "data" / "processed" / "items_droppable.json")
        from bidking_lab.extract.item_table import load_item_table

        raw_items = load_item_table(ROOT / "data" / "raw" / "tables" / "Item.txt")
    except Exception:  # noqa: BLE001 - a summary must fail closed
        return (), "catalog_unavailable"
    if not isinstance(payload, list):
        return (), "catalog_unavailable"

    processed: dict[int, tuple[int, int, int]] = {}
    processed_ids: set[int] = set()
    for row in payload:
        if not isinstance(row, Mapping) or _raven_strict_int(row.get("quality")) != 6:
            continue
        item_id = _raven_strict_int(row.get("item_id"), minimum=1)
        if item_id is None:
            return (), "catalog_malformed"
        if int(item_id) in processed_ids:
            return (), "catalog_duplicate_item_id"
        processed_ids.add(int(item_id))
        value = _raven_strict_int(row.get("value"), minimum=1)
        width = _raven_strict_int(row.get("shape_w"), minimum=1)
        height = _raven_strict_int(row.get("shape_h"), minimum=1)
        if None in (item_id, value, width, height):
            return (), "catalog_malformed"
        processed[int(item_id)] = (
            int(value),
            min(int(width), int(height)),
            max(int(width), int(height)),
        )
    if set(processed) != validated_ids:
        return (), "catalog_identity_mismatch"

    rows: list[tuple[int, int, int, int]] = []
    for item_id in sorted(processed):
        item = raw_items.get(item_id)
        if item is None or not _is_lockable_collectible(item):
            return (), "catalog_raw_identity_mismatch"
        expected = (
            int(item.value),
            min(int(item.shape_w), int(item.shape_h)),
            max(int(item.shape_w), int(item.shape_h)),
        )
        if processed[item_id] != expected:
            return (), "catalog_shape_mismatch"
        value, width, height = expected
        rows.append((item_id, value, width, height))
    return tuple(rows), "ok"


def _ivan_full_outline_shape_avg_unique_red_facts(
    snapshot: dict[str, Any],
    *,
    hero: str,
    phase: str,
    current_session: str | None,
) -> tuple[tuple[str, int, int], ...]:
    """Resolve singleton footprint averages only with current full-outline proof.

    The 100169-100173 result is an average over all items of one footprint.
    When a complete current-session 100100 outline proves that bucket contains
    exactly one item, the Float32 interval becomes that item's exact integer
    value.  It is hard red evidence only when the complete droppable catalog has
    exactly one matching ``(value, canonical shape)`` identity and it is q6.
    """
    if (
        _run_env_get(IVAN_FULL_OUTLINE_SHAPE_AVG_RED_IDENTITY_DISABLE) == "1"
        or normalize_hero_key(hero) != "ivan"
        or str(phase).strip().lower() != "bidding"
        or not isinstance(current_session, str)
        or re.fullmatch(r"\d{4}:\d+", current_session) is None
    ):
        return ()

    outline_identities: set[tuple[tuple[int, int, int], ...]] = set()
    for row in _iter_dicts(snapshot.get("action_result_rows")):
        if (
            _safe_int(row.get("action_id")) != 100100
            or row.get("session_id") != current_session
        ):
            continue
        items = list(
            _iter_dicts(
                row.get("revealed_items_detail") or row.get("observed_items")
            )
        )
        if not items:
            return ()
        if _validated_outline_identity_cells(items, require_runtime_ids=True) is None:
            return ()
        identity: list[tuple[int, int, int]] = []
        for item in items:
            runtime_id = _safe_int(item.get("runtime_id"))
            shape = _raven_shape(item.get("shape_code") or item.get("shape_key"))
            if runtime_id is None or runtime_id <= 0 or shape is None:
                return ()
            identity.append((runtime_id, shape[0], shape[1]))
        outline_identities.add(tuple(sorted(identity)))
    if len(outline_identities) != 1:
        return ()
    outline = next(iter(outline_identities))
    items_by_cells: dict[int, list[tuple[int, int, int]]] = {}
    for runtime_id, width, height in outline:
        items_by_cells.setdefault(width * height, []).append(
            (runtime_id, width, height)
        )

    try:
        from bidking_lab.inference.size_avg_evidence import (
            SIZE_AVG_ACTION_FOOTPRINT,
            shape_average_value_evidence_from_action_rows,
        )
    except Exception:  # pragma: no cover - packaged import failure must no-op
        return ()
    posterior_targets = [
        {
            "cells": cells,
            "count_exact": len(items),
            "count_provenance": ["ivan_action_100100_full_outline"],
        }
        for cells, items in sorted(items_by_cells.items())
    ]
    # Atomically validate every current-session observation of a footprint
    # bucket.  A malformed duplicate is a conflict, not an ignorable row that
    # lets a neighbouring valid copy manufacture hard evidence.  Cross-session
    # and unrelated actions are outside this current evidence epoch.
    current_size_avg_rows = tuple(
        row
        for row in _iter_dicts(snapshot.get("action_result_rows"))
        if row.get("session_id") == current_session
        and _safe_int(row.get("action_id")) in SIZE_AVG_ACTION_FOOTPRINT
    )
    structured = shape_average_value_evidence_from_action_rows(
        current_size_avg_rows,
        current_session_id=current_session,
        posterior_targets=posterior_targets,
    )
    q6_catalog, q6_catalog_status = _validated_q6_outline_catalog()
    all_catalog_by_value = _catalog_items_by_value()
    if q6_catalog_status != "ok" or not q6_catalog or not all_catalog_by_value:
        return ()

    facts: set[tuple[str, int, int]] = set()
    observations_by_cells: dict[int, list[Mapping[str, Any]]] = {}
    for evidence in structured:
        cells = _safe_int(evidence.get("footprint_cells"))
        if cells is not None:
            observations_by_cells.setdefault(cells, []).append(evidence)

    for cells, observations in observations_by_cells.items():
        bucket = items_by_cells.get(cells, ())
        candidate_facts: list[tuple[str, int, int] | None] = []
        bucket_invalid = len(bucket) != 1 or not observations
        for evidence in observations:
            interval = evidence.get("total_value_interval")
            if (
                evidence.get("status") != "interval_only"
                or evidence.get("count_status") != "exact"
                or evidence.get("conflicts")
                or not isinstance(interval, list)
                or len(interval) != 2
                or type(interval[0]) is not int
                or type(interval[1]) is not int
                or interval[0] != interval[1]
            ):
                bucket_invalid = True
                continue
            if len(bucket) != 1:
                bucket_invalid = True
                continue
            runtime_id, width, height = bucket[0]
            value = int(interval[0])
            all_quality_candidates = tuple(
                row
                for row in all_catalog_by_value.get(value, ())
                if row[1] == cells
            )
            q6_candidates = tuple(
                row
                for row in q6_catalog
                if row[1:] == (value, width, height)
            )
            candidate_facts.append(
                (f"runtime:{runtime_id}", int(cells), value)
                if (
                    len(all_quality_candidates) == 1
                    and all_quality_candidates[0][0] == 6
                    and len(q6_candidates) == 1
                    and q6_candidates[0][0] == all_quality_candidates[0][2]
                )
                else None
            )
        if (
            bucket_invalid
            or len(candidate_facts) != len(observations)
            or any(fact is None for fact in candidate_facts)
        ):
            continue
        unique_facts = set(candidate_facts)
        fact = next(iter(unique_facts)) if len(unique_facts) == 1 else None
        if fact is not None:
            facts.add(fact)
    return tuple(sorted(facts))


def _raven_weighted_quantile(
    distribution: Mapping[int, float],
    probability: float,
) -> int | None:
    total = sum(
        float(weight)
        for weight in distribution.values()
        if math.isfinite(float(weight)) and float(weight) > 0
    )
    if total <= 0:
        return None
    threshold = max(0.0, min(1.0, float(probability))) * total
    cumulative = 0.0
    for value, weight in sorted(distribution.items()):
        if not math.isfinite(float(weight)) or float(weight) <= 0:
            continue
        cumulative += float(weight)
        if cumulative + 1e-15 >= threshold:
            return int(value)
    return int(max(distribution))


@lru_cache(maxsize=128)
def _gabriela_q6_known_item_exact_cells_distribution(
    map_id: int,
    total_count: int,
    total_cells: int,
    known_item_facts: tuple[tuple[str, int, int], ...],
) -> tuple[str, float, tuple[tuple[float, float], ...], str]:
    """Return P(exact cells | count) and the matching q6 value distribution."""
    if total_count <= 0 or total_cells <= 0 or not known_item_facts:
        return "evidence_unavailable", 0.0, (), ""
    identities = [fact[0] for fact in known_item_facts]
    if (
        any(
            type(identity) is not str  # noqa: E721 - internal exact fact row
            or not identity
            or type(cells) is not int  # noqa: E721 - reject bool/subclasses
            or cells <= 0
            or type(value) is not int  # noqa: E721 - reject bool/subclasses
            or value <= 0
            for identity, cells, value in known_item_facts
        )
        or len(set(identities)) != len(identities)
    ):
        return "known_item_fact_malformed", 0.0, (), ""
    known_count = len(known_item_facts)
    known_cells = sum(fact[1] for fact in known_item_facts)
    known_value = sum(fact[2] for fact in known_item_facts)
    remaining_count = total_count - known_count
    remaining_cells = total_cells - known_cells
    if remaining_count <= 0 or remaining_cells < remaining_count:
        return "residual_unavailable", 0.0, (), ""

    catalog_rows, catalog_status = _validated_q6_outline_catalog()
    if catalog_status != "ok" or not catalog_rows:
        return catalog_status, 0.0, (), ""
    map_payload = _load_drop_weight_items().get(map_id)
    item_payload = map_payload.get("items") if isinstance(map_payload, Mapping) else None
    if not isinstance(item_payload, Mapping):
        return "drop_weight_map_unavailable", 0.0, (), ""
    longtail = _load_red_longtail_normalized()
    options: list[tuple[int, int, float]] = []
    for item_id, raw_value, width, height in catalog_rows:
        raw_weight = item_payload.get(str(item_id))
        if raw_weight is None:
            raw_weight = item_payload.get(item_id)
        if raw_weight is None:
            continue
        if not isinstance(raw_weight, (list, tuple)) or len(raw_weight) < 3:
            return "drop_weight_row_malformed", 0.0, (), ""
        try:
            weight = float(raw_weight[0])
            row_raw_value = float(raw_weight[1])
            fitted_value = float(raw_weight[2])
        except (TypeError, ValueError, OverflowError):
            return "drop_weight_row_malformed", 0.0, (), ""
        if (
            not all(
                math.isfinite(candidate)
                for candidate in (weight, row_raw_value, fitted_value)
            )
            or weight < 0
            or not row_raw_value.is_integer()
            or not fitted_value.is_integer()
            or int(row_raw_value) != int(raw_value)
            or int(fitted_value) != int(longtail.get(int(item_id), int(raw_value)))
        ):
            return "drop_weight_row_malformed", 0.0, (), ""
        if weight > 0:
            options.append((int(width) * int(height), int(fitted_value), weight))
    total_weight = sum(option[2] for option in options)
    if total_weight <= 0:
        return "drop_weight_support_empty", 0.0, (), ""
    normalized = tuple(
        (cells, value, weight / total_weight)
        for cells, value, weight in options
    )

    # State is keyed only by occupied cells and retains exact conditional
    # probability, first/second value moments, and the hard value floor.
    states: dict[int, tuple[float, float, float, int]] = {
        0: (1.0, 0.0, 0.0, 0)
    }
    for _index in range(remaining_count):
        next_states: dict[int, tuple[float, float, float, int]] = {}
        for (
            prior_cells,
            (
                prior_probability,
                prior_first_moment,
                prior_second_moment,
                prior_minimum,
            ),
        ) in states.items():
            for item_cells, item_value, item_weight in normalized:
                combined_cells = prior_cells + item_cells
                if combined_cells > remaining_cells:
                    continue
                (
                    next_probability,
                    next_first_moment,
                    next_second_moment,
                    next_minimum,
                ) = next_states.get(combined_cells, (0.0, 0.0, 0.0, sys.maxsize))
                weighted_probability = prior_probability * item_weight
                next_states[combined_cells] = (
                    next_probability + weighted_probability,
                    next_first_moment
                    + item_weight
                    * (prior_first_moment + prior_probability * item_value),
                    next_second_moment
                    + item_weight
                    * (
                        prior_second_moment
                        + 2.0 * item_value * prior_first_moment
                        + prior_probability * item_value**2
                    ),
                    min(next_minimum, prior_minimum + item_value),
                )
        if not next_states:
            return "distribution_complexity_guard", 0.0, (), ""
        states = next_states
    (
        cell_likelihood,
        residual_first_moment,
        residual_second_moment,
        residual_minimum,
    ) = states.get(remaining_cells, (0.0, 0.0, 0.0, 0))
    if not math.isfinite(cell_likelihood) or cell_likelihood <= 0:
        return "exact_cells_support_missing", 0.0, (), ""
    residual_mean = residual_first_moment / cell_likelihood
    residual_second = residual_second_moment / cell_likelihood
    residual_variance = max(0.0, residual_second - residual_mean * residual_mean)
    center = float(known_value) + residual_mean
    spread = math.sqrt(residual_variance)
    floor = float(known_value + residual_minimum)
    points = _value_distribution_points_with_floor(center, spread, floor)
    context = (
        f"drop_weights_all_maps_0627:{map_id};"
        "items_droppable:q6-validated;"
        "red_longtail_normalized_0627:validated;"
        "sampling:with_replacement;moments:exact;"
        f"known:{known_count};remaining:{remaining_count};cells:{remaining_cells}"
    )
    return "ok", cell_likelihood, tuple(points), context


@lru_cache(maxsize=128)
def _raven_red_outline_value_distribution(
    map_id: int,
    footprint_shapes: tuple[tuple[int, int], ...],
) -> tuple[str, int | None, int | None, int | None, str]:
    catalog_rows, catalog_status = _validated_q6_outline_catalog()
    if catalog_status != "ok" or not catalog_rows:
        return catalog_status, None, None, None, ""
    map_payload = _load_drop_weight_items().get(int(map_id))
    item_payload = map_payload.get("items") if isinstance(map_payload, Mapping) else None
    if not isinstance(item_payload, Mapping):
        return "drop_weight_map_unavailable", None, None, None, ""

    longtail = _load_red_longtail_normalized()
    by_shape: dict[tuple[int, int], list[tuple[int, int, float]]] = {}
    for item_id, raw_value, width, height in catalog_rows:
        raw_weight = item_payload.get(str(item_id))
        if raw_weight is None:
            raw_weight = item_payload.get(item_id)
        if raw_weight is None:
            continue
        if not isinstance(raw_weight, (list, tuple)) or len(raw_weight) < 3:
            return "drop_weight_row_malformed", None, None, None, ""
        try:
            weight = float(raw_weight[0])
            row_raw_value = float(raw_weight[1])
            fitted_value = float(raw_weight[2])
        except (TypeError, ValueError):
            return "drop_weight_row_malformed", None, None, None, ""
        if not all(math.isfinite(value) for value in (weight, row_raw_value, fitted_value)):
            return "drop_weight_row_malformed", None, None, None, ""
        if weight < 0 or not row_raw_value.is_integer() or not fitted_value.is_integer():
            return "drop_weight_row_malformed", None, None, None, ""
        if int(row_raw_value) != int(raw_value):
            return "drop_weight_catalog_value_mismatch", None, None, None, ""
        expected_fitted = int(longtail.get(int(item_id), int(raw_value)))
        if int(fitted_value) != expected_fitted:
            return "drop_weight_longtail_mismatch", None, None, None, ""
        if weight <= 0:
            continue
        by_shape.setdefault((int(width), int(height)), []).append(
            (int(raw_value), int(fitted_value), float(weight))
        )

    floor = 0
    conditioned: list[tuple[tuple[int, float], ...]] = []
    for shape in footprint_shapes:
        options = by_shape.get(tuple(shape)) or []
        if not options:
            return "footprint_weight_support_missing", None, None, None, ""
        shape_floor = min(raw_value for raw_value, _fitted, _weight in options)
        floor += int(shape_floor)
        value_weights: dict[int, float] = {}
        for _raw, fitted, weight in options:
            value = max(int(shape_floor), int(fitted))
            value_weights[value] = value_weights.get(value, 0.0) + float(weight)
        total_weight = sum(value_weights.values())
        if total_weight <= 0:
            return "footprint_weight_support_empty", None, None, None, ""
        conditioned.append(
            tuple(
                (int(value), float(weight) / total_weight)
                for value, weight in sorted(value_weights.items())
            )
        )

    distribution: dict[int, float] = {0: 1.0}
    for options in conditioned:
        next_distribution: dict[int, float] = {}
        for prior_value, prior_weight in distribution.items():
            for item_value, item_weight in options:
                combined = int(prior_value) + int(item_value)
                next_distribution[combined] = (
                    next_distribution.get(combined, 0.0)
                    + float(prior_weight) * float(item_weight)
                )
        if len(next_distribution) > RAVEN_RED_OUTLINE_VALUE_MAX_STATES:
            return "distribution_complexity_guard", None, None, None, ""
        distribution = next_distribution
    p50 = _raven_weighted_quantile(distribution, 0.50)
    p90 = _raven_weighted_quantile(distribution, 0.90)
    if p50 is None or p90 is None:
        return "distribution_empty", None, None, None, ""
    p50 = max(int(floor), int(p50))
    p90 = max(int(p50), int(p90))
    context = (
        f"drop_weights_all_maps_0627:{int(map_id)};"
        "items_droppable:q6-validated;"
        "red_longtail_normalized_0627:validated;"
        "sampling:with_replacement"
    )
    return "ok", int(floor), int(p50), int(p90), context


def _derive_raven_red_outline_value_summary(
    snapshot: Mapping[str, Any],
    result: RefResult,
) -> dict[str, Any]:
    """Derive Raven's complete-outline red floor/P50/P90 without repricing."""
    if _run_env_get(RAVEN_RED_OUTLINE_VALUE_SUMMARY_DISABLE) == "1":
        return _raven_outline_summary_template(reason="disabled")
    evidence = result.evidence
    if normalize_hero_key(evidence.hero) != "raven":
        return _raven_outline_summary_template(reason="hero_not_raven")
    if str(evidence.phase or "").strip().lower() != "bidding":
        return _raven_outline_summary_template(reason="phase_not_bidding")
    if (_snapshot_round_no(dict(snapshot)) or 0) < 5:
        return _raven_outline_summary_template(reason="round_before_r5")
    if result.status not in {"ok", "count_prior"}:
        return _raven_outline_summary_template(reason=f"engine_status:{result.status}")
    source_eligible, source_status, source_reason = (
        _raven_official_distribution_status(snapshot)
    )
    if not source_eligible:
        return _raven_outline_summary_template(
            status=source_status,
            reason=source_reason,
        )

    outline_row, outline_status = _raven_select_latest_row(
        _raven_full_outline_rows(snapshot)
    )
    quality_row, quality_status = _raven_select_latest_row(
        _raven_full_quality_rows(snapshot)
    )
    if outline_row is None or quality_row is None:
        reason = (
            "missing_full_outline"
            if outline_status == "missing"
            else "missing_full_quality_scan"
            if quality_status == "missing"
            else f"row_selection:{outline_status}:{quality_status}"
        )
        status = (
            "unavailable"
            if "missing" in {outline_status, quality_status}
            else "conflict"
        )
        return _raven_outline_summary_template(status=status, reason=reason)

    outline_items = _raven_row_items(outline_row)
    quality_items = _raven_row_items(quality_row)
    if outline_items is None or quality_items is None:
        return _raven_outline_summary_template(
            status="conflict",
            reason="malformed_or_empty_complete_row",
        )
    quality_scan_count = len(quality_items)
    outline_count = len(outline_items)
    invalid_quality = [
        item
        for item in quality_items
        if _quality_number_to_key(item.get("quality")) is None
    ]
    if invalid_quality:
        return _raven_outline_summary_template(
            status="conflict",
            reason="quality_scan_contains_invalid_quality",
            quality_scan_count=quality_scan_count,
            outline_count=outline_count,
        )

    pairs, identity_status = _raven_pair_quality_and_outline_items(
        quality_items,
        outline_items,
    )
    if not pairs:
        return _raven_outline_summary_template(
            status="conflict",
            reason=identity_status,
            quality_scan_count=quality_scan_count,
            outline_count=outline_count,
        )
    red_pairs = [
        (quality_item, outline_item)
        for quality_item, outline_item in pairs
        if _raven_strict_int(quality_item.get("quality")) == 6
    ]
    red_count = len(red_pairs)
    exact_red_count = evidence.fixed_counts.get("q6")
    if (
        "all_item_quality_exact_counts" not in evidence.source_notes
        or exact_red_count is None
        or int(exact_red_count) != int(red_count)
        or evidence.total_count is None
        or int(evidence.total_count) != int(quality_scan_count)
        or int(quality_scan_count) != int(outline_count)
    ):
        return _raven_outline_summary_template(
            status="conflict",
            reason="completeness_count_mismatch",
            quality_scan_count=quality_scan_count,
            outline_count=outline_count,
            red_count=red_count,
            paired_red_count=len(red_pairs),
        )

    footprint_shapes: list[tuple[int, int]] = []
    footprint_cells: list[int] = []
    for _quality_item, outline_item in red_pairs:
        shape = _raven_shape(
            outline_item.get("shape_code") or outline_item.get("shape_key")
        )
        if shape is None:
            return _raven_outline_summary_template(
                status="conflict",
                reason="red_outline_shape_missing",
                quality_scan_count=quality_scan_count,
                outline_count=outline_count,
                red_count=red_count,
                paired_red_count=len(footprint_shapes),
            )
        cells = int(shape[0]) * int(shape[1])
        explicit_cells = outline_item.get("cells")
        if explicit_cells not in (None, ""):
            parsed_cells = _raven_strict_int(explicit_cells, minimum=1)
            if parsed_cells is None or int(parsed_cells) != cells:
                return _raven_outline_summary_template(
                    status="conflict",
                    reason="red_outline_shape_cells_conflict",
                    quality_scan_count=quality_scan_count,
                    outline_count=outline_count,
                    red_count=red_count,
                    paired_red_count=len(footprint_shapes),
                )
        footprint_shapes.append(shape)
        footprint_cells.append(cells)

    if red_count == 0:
        return {
            **_raven_outline_summary_template(
                status="outline_complete",
                quality_scan_count=quality_scan_count,
                outline_count=outline_count,
                red_count=0,
                paired_red_count=0,
            ),
            "eligibility_complete": True,
            "floor_value": 0,
            "p50_value": 0,
            "p90_value": 0,
            "catalog_context": "zero_red:no_value_distribution_required",
            "conflicts": [],
        }
    map_id = evidence.map_id
    if map_id is None:
        return _raven_outline_summary_template(
            status="conflict",
            reason="map_id_missing",
            quality_scan_count=quality_scan_count,
            outline_count=outline_count,
            red_count=red_count,
            paired_red_count=len(footprint_shapes),
        )
    distribution_status, floor, p50, p90, catalog_context = (
        _raven_red_outline_value_distribution(
            int(map_id),
            tuple(sorted(footprint_shapes)),
        )
    )
    if (
        distribution_status != "ok"
        or floor is None
        or p50 is None
        or p90 is None
        or not (int(floor) <= int(p50) <= int(p90))
    ):
        return _raven_outline_summary_template(
            status="conflict",
            reason=f"value_distribution:{distribution_status}",
            quality_scan_count=quality_scan_count,
            outline_count=outline_count,
            red_count=red_count,
            paired_red_count=len(footprint_shapes),
        )
    return {
        **_raven_outline_summary_template(
            status="outline_complete",
            quality_scan_count=quality_scan_count,
            outline_count=outline_count,
            red_count=red_count,
            paired_red_count=len(footprint_shapes),
        ),
        "eligibility_complete": True,
        "floor_value": int(floor),
        "p50_value": int(p50),
        "p90_value": int(p90),
        "footprint_cells": sorted(int(value) for value in footprint_cells),
        "catalog_context": catalog_context,
        "conflicts": [],
    }


@lru_cache(maxsize=32)
def _max_footprint_avg_catalog_floor(
    key: str,
    avg_cells: float | None,
) -> tuple[int, int, tuple[int, ...]] | None:
    """Resolve a hard maximum-footprint average to a whole-quality value floor.

    If the average equals the tier's largest catalog footprint, every item in the tier
    must have that footprint. The item identity is unique only when the returned ID tuple
    has length one; count remains unknown in either case.
    """
    quality = _quality_key_item_table_quality(key) or QUALITY_TIER_NUMBER.get(key)
    if quality not in (4, 5, 6) or avg_cells is None or float(avg_cells) <= 0:
        return None
    _pairs, rows, status = _validated_quality_catalog(int(quality))
    if status != "ok" or not rows:
        return None
    max_cells = max(int(cells) for _item_id, _value, cells in rows)
    if abs(float(avg_cells) - float(max_cells)) > 0.0001:
        return None
    max_rows = tuple(
        (int(item_id), int(value))
        for item_id, value, cells in rows
        if int(cells) == max_cells
    )
    if not max_rows:
        return None
    return min(value for _item_id, value in max_rows), max_cells, tuple(
        item_id for item_id, _value in max_rows
    )


@lru_cache(maxsize=8)
def _catalog_count_cell_value_extrema(
    catalog_pairs: tuple[tuple[int, int], ...], max_count: int
) -> tuple[tuple[tuple[int, int, int], ...], ...]:
    """Exact min/max value envelope for every reachable (item_count, cells) state."""
    per_cells: dict[int, tuple[int, int]] = {}
    for value, cells in catalog_pairs:
        previous = per_cells.get(int(cells))
        if previous is None:
            per_cells[int(cells)] = (int(value), int(value))
        else:
            per_cells[int(cells)] = (
                min(previous[0], int(value)),
                max(previous[1], int(value)),
            )
    layers: list[dict[int, tuple[int, int]]] = [{0: (0, 0)}]
    for _ in range(int(max_count)):
        current: dict[int, tuple[int, int]] = {}
        for prior_cells, (prior_min, prior_max) in layers[-1].items():
            for cells, (cell_min, cell_max) in per_cells.items():
                next_cells = prior_cells + cells
                candidate = (prior_min + cell_min, prior_max + cell_max)
                previous = current.get(next_cells)
                if previous is None:
                    current[next_cells] = candidate
                else:
                    current[next_cells] = (
                        min(previous[0], candidate[0]),
                        max(previous[1], candidate[1]),
                    )
        layers.append(current)
    return tuple(
        tuple((cells, bounds[0], bounds[1]) for cells, bounds in sorted(layer.items()))
        for layer in layers
    )


def _exact_count_cells_candidates_from_catalog(
    catalog_pairs: tuple[tuple[int, int], ...],
    total_value: float | int,
    avg_cells: float | None,
    ceiling: int,
    *,
    known_items: tuple[tuple[int, int], ...] = (),
    fixed_count: int | None = None,
    fixed_cells: int | None = None,
    quality_key: str = "q5",
    max_count: int = Q5_EXACT_MAX_COUNT,
    max_residual_value: int = Q5_EXACT_MAX_RESIDUAL_VALUE,
    value_only_max: int = Q5_EXACT_VALUE_ONLY_MAX,
) -> tuple[str, tuple[tuple[int, int], ...]]:
    """Solve exact repeat-allowed catalog multisets for (total count, total cells).

    ``known_items`` are correlated (cells, value) facts already included in ``total_value``.  The
    solver subtracts them and solves only the residual. ``fixed_count`` and ``fixed_cells`` are
    whole-quality facts. It never truncates the theoretical count range: inputs beyond the bounded
    live-safe envelope return ``complexity_guard`` and do not lock.
    """
    pairs = tuple(
        sorted(
            {
                (int(value), int(cells))
                for value, cells in catalog_pairs
                if value > 0 and cells > 0
            }
        )
    )
    parsed_value = _safe_float(total_value)
    parsed_avg = _safe_float(avg_cells)
    if (
        not pairs
        or parsed_value is None
        or (avg_cells is not None and (parsed_avg is None or parsed_avg <= 0))
        or ceiling <= 0
    ):
        return "invalid_input", ()
    target_value = int(round(parsed_value))
    if target_value <= 0 or abs(float(parsed_value) - target_value) > 0.0001:
        return "invalid_input", ()
    pair_set = set(pairs)
    normalized_known = tuple((int(cells), int(value)) for cells, value in known_items)
    if any((value, cells) not in pair_set for cells, value in normalized_known):
        return "invalid_known_item", ()
    known_count = len(normalized_known)
    known_cells = sum(cells for cells, _ in normalized_known)
    known_value = sum(value for _, value in normalized_known)
    residual_value = target_value - known_value
    if known_count > int(ceiling) or residual_value < 0:
        return "invalid_known_residual", ()
    min_value = min(value for value, _ in pairs)
    theoretical_max = known_count + (residual_value // min_value)
    full_max_count = min(int(ceiling), int(theoretical_max))
    if full_max_count < known_count:
        return "ok", ()
    parsed_fixed_count = None if fixed_count is None else int(fixed_count)
    parsed_fixed_cells = None if fixed_cells is None else int(fixed_cells)
    if parsed_fixed_cells is not None and parsed_fixed_cells <= 0:
        return "invalid_fixed_cells", ()
    if parsed_fixed_count is not None:
        if parsed_fixed_count < known_count or parsed_fixed_count > int(ceiling):
            return "invalid_fixed_count", ()
        if parsed_fixed_count > full_max_count:
            return "ok", ()
        count_values = (parsed_fixed_count,)
        required_max_count = parsed_fixed_count
    else:
        count_values = tuple(range(known_count, full_max_count + 1))
        required_max_count = full_max_count
    # 64 covers the current 525-game truth pool (observed full candidate ceiling max=54).  Returning a
    # guard is semantically different from solving only 1..64: the latter can manufacture uniqueness.
    if required_max_count > int(max_count) or residual_value > int(
        max_residual_value
    ):
        return "complexity_guard", ()
    if (
        parsed_avg is None
        and parsed_fixed_count is None
        and parsed_fixed_cells is None
        and residual_value > int(value_only_max)
    ):
        return "value_only_guard", ()

    # Build the configured full envelope once; varying per-snapshot maxima would churn the cache.
    extrema_rows = _catalog_count_cell_value_extrema(pairs, int(max_count))
    extrema = [
        {cells: (minimum, maximum) for cells, minimum, maximum in row}
        for row in extrema_rows
    ]
    targets: list[tuple[int, int, int, int]] = []
    for total_count in count_values:
        residual_count = total_count - known_count
        if parsed_fixed_cells is not None:
            total_cell_options = (parsed_fixed_cells,)
        elif parsed_avg is None:
            total_cell_options = (
                known_cells + residual_cells
                for residual_cells in extrema[residual_count]
            )
        else:
            total_cell_options = _avg_grid_options(
                total_count, float(parsed_avg), quality_key
            )
        for total_cells in total_cell_options:
            residual_cells = int(total_cells) - known_cells
            bounds = extrema[residual_count].get(residual_cells)
            if bounds is None or not (bounds[0] <= residual_value <= bounds[1]):
                continue
            targets.append((total_count, int(total_cells), residual_count, residual_cells))
    if not targets:
        return "ok", ()

    max_residual_count = max(target[2] for target in targets)
    allowed: list[dict[int, tuple[int, int]]] = [
        {} for _ in range(max_residual_count + 1)
    ]
    for _, _, target_count, target_cells in targets:
        for used_count in range(target_count + 1):
            future = extrema[target_count - used_count]
            for used_cells, (used_min, used_max) in extrema[used_count].items():
                future_bounds = future.get(target_cells - used_cells)
                if future_bounds is None:
                    continue
                low = max(0, used_min, residual_value - future_bounds[1])
                high = min(residual_value, used_max, residual_value - future_bounds[0])
                if low > high:
                    continue
                previous = allowed[used_count].get(used_cells)
                allowed[used_count][used_cells] = (
                    (low, high)
                    if previous is None
                    else (min(previous[0], low), max(previous[1], high))
                )

    # Each bitset is offset to its state's still-useful value interval, avoiding a giant 0..V mask.
    states: dict[int, tuple[int, int]] = {0: (0, 1)}
    target_by_residual_count: dict[int, list[tuple[int, int, int]]] = {}
    for total_count, total_cells, residual_count, residual_cells in targets:
        target_by_residual_count.setdefault(residual_count, []).append(
            (total_count, total_cells, residual_cells)
        )
    survivors: set[tuple[int, int]] = set()

    def collect(layer_count: int) -> None:
        for total_count, total_cells, residual_cells in target_by_residual_count.get(
            layer_count, ()
        ):
            state = states.get(residual_cells)
            if state is None:
                continue
            offset, bits = state
            bit_index = residual_value - offset
            if bit_index >= 0 and ((bits >> bit_index) & 1):
                survivors.add((total_count, total_cells))

    collect(0)
    for used_count in range(1, max_residual_count + 1):
        next_states: dict[int, tuple[int, int]] = {}
        for prior_cells, (prior_offset, prior_bits) in states.items():
            for value, cells in pairs:
                next_cells = prior_cells + cells
                interval = allowed[used_count].get(next_cells)
                if interval is None:
                    continue
                low, high = interval
                shift = prior_offset + value - low
                shifted = prior_bits << shift if shift >= 0 else prior_bits >> (-shift)
                shifted &= (1 << (high - low + 1)) - 1
                if not shifted:
                    continue
                previous = next_states.get(next_cells)
                next_states[next_cells] = (
                    (low, shifted)
                    if previous is None
                    else (low, previous[1] | shifted)
                )
        states = next_states
        if not states:
            break
        collect(used_count)
    return "ok", tuple(sorted(survivors))


@lru_cache(maxsize=512)
def _exact_fixed_count_cells_value_candidates_from_catalog(
    catalog_pairs: tuple[tuple[int, int], ...],
    total_lower: int,
    total_upper: int,
    fixed_count: int,
    avg_cells: float | None,
    known_items: tuple[tuple[int, int], ...] = (),
    fixed_cells: int | None = None,
    quality_key: str = "q6",
) -> tuple[str, tuple[tuple[int, int, int], ...]]:
    """Solve one count-fixed Float32 total window in signed mean deviations.

    Absolute q6 totals can exceed the legacy value-bitset guard even when the equation is trivial
    (for example, repeating one 19m current-map item).  Centering every catalog value on the wire
    mean makes the DP depend on reachable deviations instead of raw price magnitude.  Returned rows
    keep ``(count, cells, total_value)`` correlated; a safety-budget overflow is an explicit status
    consumed as a whole-lane failure by the caller, never a partial uniqueness proof.
    """

    pairs = tuple(
        sorted(
            {
                (int(value), int(cells))
                for value, cells in catalog_pairs
                if int(value) > 0 and int(cells) > 0
            }
        )
    )
    count = int(fixed_count)
    lower = int(total_lower)
    upper = int(total_upper)
    parsed_avg = _safe_float(avg_cells)
    parsed_fixed_cells = None if fixed_cells is None else int(fixed_cells)
    if (
        not pairs
        or count <= 0
        or count > Q5_EXACT_MAX_COUNT
        or lower <= 0
        or upper < lower
        or upper - lower + 1 > 4096
        or (avg_cells is not None and (parsed_avg is None or parsed_avg <= 0))
        or (parsed_fixed_cells is not None and parsed_fixed_cells <= 0)
    ):
        return "complexity_guard" if count > Q5_EXACT_MAX_COUNT else "invalid_input", ()

    pair_set = set(pairs)
    normalized_known = tuple((int(cells), int(value)) for cells, value in known_items)
    if any((value, cells) not in pair_set for cells, value in normalized_known):
        return "invalid_known_item", ()
    known_count = len(normalized_known)
    if known_count > count:
        return "invalid_known_residual", ()
    known_cells = sum(cells for cells, _value in normalized_known)

    base_value = ((lower + upper) // 2) // count
    centered_pairs = tuple(
        sorted({(value - base_value, cells) for value, cells in pairs})
    )
    known_delta = sum(value - base_value for _cells, value in normalized_known)
    residual_count = count - known_count
    target_lower = lower - base_value * count - known_delta
    target_upper = upper - base_value * count - known_delta

    if residual_count > 0:
        minimum_delta = min(delta for delta, _cells in centered_pairs)
        maximum_delta = max(delta for delta, _cells in centered_pairs)
        centered_pairs = tuple(
            (delta, cells)
            for delta, cells in centered_pairs
            if delta + (residual_count - 1) * minimum_delta <= target_upper
            and delta + (residual_count - 1) * maximum_delta >= target_lower
        )
        if not centered_pairs:
            return "ok", ()

    extrema_rows = _catalog_count_cell_value_extrema(
        centered_pairs,
        residual_count,
    )
    extrema = [
        {cells: (minimum, maximum) for cells, minimum, maximum in row}
        for row in extrema_rows
    ]
    if parsed_fixed_cells is not None:
        total_cell_options: Iterable[int] = (parsed_fixed_cells,)
    elif parsed_avg is not None:
        total_cell_options = _avg_grid_options(count, float(parsed_avg), quality_key)
    else:
        total_cell_options = tuple(
            known_cells + residual_cells
            for residual_cells in extrema[residual_count]
        )

    targets: list[tuple[int, int]] = []
    for total_cells in total_cell_options:
        residual_cells = int(total_cells) - known_cells
        bounds = extrema[residual_count].get(residual_cells)
        if bounds is None or bounds[1] < target_lower or bounds[0] > target_upper:
            continue
        targets.append((int(total_cells), residual_cells))
    if not targets:
        return "ok", ()

    allowed: list[dict[int, tuple[int, int]]] = [
        {} for _ in range(residual_count + 1)
    ]
    for _total_cells, target_cells in targets:
        for used_count in range(residual_count + 1):
            future = extrema[residual_count - used_count]
            for used_cells, (used_min, used_max) in extrema[used_count].items():
                future_bounds = future.get(target_cells - used_cells)
                if future_bounds is None:
                    continue
                low = max(used_min, target_lower - future_bounds[1])
                high = min(used_max, target_upper - future_bounds[0])
                if low > high:
                    continue
                previous = allowed[used_count].get(used_cells)
                allowed[used_count][used_cells] = (
                    (low, high)
                    if previous is None
                    else (min(previous[0], low), max(previous[1], high))
                )
    if any(
        sum(high - low + 1 for low, high in layer.values())
        > Q6_FULL_AVG_DP_LAYER_BIT_BUDGET
        for layer in allowed
    ):
        return "deviation_complexity_guard", ()

    states: dict[int, tuple[int, int]] = {0: (0, 1)}
    for used_count in range(1, residual_count + 1):
        next_states: dict[int, tuple[int, int]] = {}
        for prior_cells, (prior_offset, prior_bits) in states.items():
            for delta, cells in centered_pairs:
                next_cells = prior_cells + cells
                interval = allowed[used_count].get(next_cells)
                if interval is None:
                    continue
                low, high = interval
                shift = prior_offset + delta - low
                shifted = prior_bits << shift if shift >= 0 else prior_bits >> (-shift)
                shifted &= (1 << (high - low + 1)) - 1
                if not shifted:
                    continue
                previous = next_states.get(next_cells)
                next_states[next_cells] = (
                    (low, shifted)
                    if previous is None
                    else (low, previous[1] | shifted)
                )
        states = next_states
        if not states:
            break

    survivors: set[tuple[int, int, int]] = set()
    for total_cells, residual_cells in targets:
        state = states.get(residual_cells)
        if state is None:
            continue
        offset, bits = state
        low = max(target_lower, offset)
        high = min(target_upper, offset + bits.bit_length() - 1)
        if low > high:
            continue
        selected = (bits >> (low - offset)) & ((1 << (high - low + 1)) - 1)
        while selected:
            least_bit = selected & -selected
            delta = low + least_bit.bit_length() - 1
            full_total = delta + known_delta + base_value * count
            survivors.add((count, int(total_cells), int(full_total)))
            selected ^= least_bit
    return "ok", tuple(sorted(survivors))


def _exact_q5_count_cells_candidates(
    total_value: float | int,
    avg_cells: float | None,
    ceiling: int,
    *,
    known_facts: tuple[tuple[str, int, int], ...] = (),
    fixed_count: int | None = None,
) -> tuple[str, tuple[tuple[int, int], ...]]:
    if os.environ.get("BIDKING_DISABLE_UNIQUE_COUNT_TWO_SIGNALS") == "1":
        return "disabled", ()
    pairs, _, catalog_status = _validated_q5_catalog()
    if catalog_status != "ok":
        return catalog_status, ()
    return _exact_count_cells_candidates_from_catalog(
        pairs,
        total_value,
        avg_cells,
        ceiling,
        known_items=tuple(
            (int(cells), int(value)) for _, cells, value in known_facts
        ),
        fixed_count=fixed_count,
    )


@lru_cache(maxsize=256)
def _cached_aisha_q5_exact_value_public_avg_support(
    total_value: float,
    avg_cells: float,
    total_count: int,
    known_facts: tuple[tuple[str, int, int], ...],
) -> tuple[str, tuple[tuple[int, int], ...]]:
    """Cache the bounded catalog solve shared by every combo in one posterior."""
    return _exact_q5_count_cells_candidates(
        total_value,
        avg_cells,
        total_count,
        known_facts=known_facts,
    )


@lru_cache(maxsize=4096)
def _cached_exact_q4_count_cells_candidates(
    catalog_pairs: tuple[tuple[int, int], ...],
    total_value: float | int,
    avg_cells: float | None,
    ceiling: int,
    known_items: tuple[tuple[int, int], ...],
    fixed_count: int | None,
    fixed_cells: int | None,
) -> tuple[str, tuple[tuple[int, int], ...]]:
    """Cache repeated dual-pass/live refresh solves for one immutable q4 evidence state."""
    return _exact_count_cells_candidates_from_catalog(
        catalog_pairs,
        total_value,
        avg_cells,
        ceiling,
        known_items=known_items,
        fixed_count=fixed_count,
        fixed_cells=fixed_cells,
        quality_key="q4",
    )


Q5_CATALOG_PROJECTION_NOTE = "q5_catalog_projection"


def _quality_total_from_public_avg(avg: float | None, count: int) -> int | None:
    """Recover the integer quality total encoded by a public float32 average and a count."""
    if not _avg_value_has_positive_signal(avg) or not _avg_value_count_matches(count, avg):
        return None
    product = float(avg) * int(count)
    if not math.isfinite(product):
        return None
    total = int(round(product))
    return total if total > 0 else None


def _q5_catalog_projection_candidates(
    *,
    key: str = "q5",
    map_id: int | None = None,
    total_count: int | None,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    count_sums: dict[str, int],
    avg_cells: dict[str, float],
    avg_values: dict[str, float],
    quality_cells: dict[str, float],
    quality_values: dict[str, float],
    source_notes: list[str],
    known_facts: tuple[tuple[str, int, int], ...] = (),
) -> tuple[str, tuple[tuple[int, int, int], ...]]:
    """Intersect q5/q6 signals against one repeat-allowed catalog multiset.

    Returned states are ``(count, cells, total_value)``.  A public avg price is authoritative only
    as an integer-product constraint; public avg-cells remains soft, while a tool avg-cells action is
    exact.  The caller projects fields independently, so ambiguity in cells need not hide an exact
    count (and vice versa).
    """
    key = str(key or "").strip().lower()
    if key not in {"q5", "q6"}:
        return "invalid_quality", ()
    if os.environ.get("BIDKING_DISABLE_UNIQUE_COUNT_TWO_SIGNALS") == "1":
        return "disabled", ()
    if key == "q5" and os.environ.get(Q5_EXACT_VALUE_CELLS_DISABLE) == "1":
        return "disabled", ()
    if key == "q6" and os.environ.get(Q6_CATALOG_VALUE_JOINT_DISABLE) == "1":
        return "disabled", ()
    exact_value = _safe_float(quality_values.get(key))
    public_avg_value = _safe_float(avg_values.get(key))
    has_avg_value = _avg_value_has_positive_signal(public_avg_value)
    if (exact_value is None or exact_value <= 0) and not has_avg_value:
        return "not_applicable", ()
    if map_id is not None:
        pairs, _, catalog_status, _generation = _validated_map_quality_catalog(
            int(map_id), int(QUALITY_TIER_NUMBER[key])
        )
    elif key == "q5":
        pairs, _, catalog_status = _validated_q5_catalog()
    else:
        pairs, _, catalog_status = _validated_q6_catalog()
    if catalog_status != "ok":
        return catalog_status, ()

    fixed_quality = fixed_counts.get(key)
    if fixed_quality is not None:
        ceiling = max(0, int(fixed_quality))
    elif total_count is not None and int(total_count) > 0:
        committed = sum(
            max(0, int(fixed_counts[other]))
            if fixed_counts.get(other) is not None
            else max(0, int(min_counts.get(other, 0) or 0))
            for other in QUALITY_KEYS
            if other != key
        )
        ceiling = max(0, int(total_count) - committed)
    elif exact_value is not None and exact_value > 0:
        ceiling = int(exact_value) // min(value for value, _ in pairs)
    else:
        # An average alone admits arbitrarily many repeated equal-price items without a vault/count
        # ceiling.  There is no finite uniqueness proof in that state.
        return "missing_ceiling", ()
    if ceiling <= 0:
        return "invalid_input", ()

    minimum = max(1, int(min_counts.get(key, 0) or 0))
    if fixed_quality is not None:
        count_candidates = (
            [int(fixed_quality)] if int(fixed_quality) >= minimum else []
        )
    else:
        count_candidates = list(range(minimum, ceiling + 1))
    if total_count is not None and int(total_count) > 0:
        count_candidates = _filter_avg_value_candidates_by_session(
            key,
            count_candidates,
            total_count=int(total_count),
            fixed_counts=fixed_counts,
            min_counts=min_counts,
            count_sums=count_sums,
        )
    if has_avg_value:
        if exact_value is not None and exact_value > 0:
            count_candidates = [
                count
                for count in count_candidates
                if _quality_count_product_tolerance_match(
                    count,
                    public_avg_value,
                    exact_value,
                )
            ]
        else:
            count_candidates = [
                count
                for count in count_candidates
                if _avg_value_count_matches_for_public_evidence(
                    key, count, public_avg_value, source_notes
                )
            ]
    if not count_candidates:
        return "ok", ()
    if (
        (exact_value is None or exact_value <= 0)
        and len(count_candidates) > Q5_EXACT_AVG_ONLY_MAX_COUNTS
    ):
        # An integer public average can admit every count up to the vault total. Solving dozens of
        # different derived totals is poor live behavior and cannot safely claim uniqueness from a
        # truncated subset, so keep the whole signal soft beyond this bounded candidate envelope.
        return "avg_value_only_guard", ()

    tool_avg_cells = any(
        re.fullmatch(rf"action_\d+_{re.escape(key)}_avg_cells(?:_.*)?", str(note))
        is not None
        for note in source_notes
    )
    public_avg_cells = f"public_{key}_avg_cells" in source_notes
    hard_avg_cells = (
        _safe_float(avg_cells.get(key))
        if tool_avg_cells or (key in avg_cells and not public_avg_cells)
        else None
    )
    exact_cells_raw = _safe_float(quality_cells.get(key))
    exact_cells = None
    if exact_cells_raw is not None:
        rounded_cells = int(round(exact_cells_raw))
        if abs(exact_cells_raw - rounded_cells) > 0.0001:
            return "invalid_exact_cells", ()
        exact_cells = rounded_cells

    states: set[tuple[int, int, int]] = set()
    statuses: set[str] = set()

    def add_solve(target_value: int, *, count: int | None) -> None:
        status, pairs_found = _exact_count_cells_candidates_from_catalog(
            pairs,
            target_value,
            hard_avg_cells,
            ceiling,
            known_items=tuple(
                (int(cells), int(value)) for _, cells, value in known_facts
            ),
            fixed_count=count,
            quality_key=key,
            max_residual_value=(
                Q6_EXACT_MAX_RESIDUAL_VALUE
                if key == "q6"
                else Q5_EXACT_MAX_RESIDUAL_VALUE
            ),
            value_only_max=(
                Q6_EXACT_VALUE_ONLY_MAX
                if key == "q6"
                else Q5_EXACT_VALUE_ONLY_MAX
            ),
        )
        statuses.add(status)
        if status != "ok":
            return
        for found_count, found_cells in pairs_found:
            if found_count not in count_candidates:
                continue
            if exact_cells is not None and int(found_cells) != exact_cells:
                continue
            states.add((int(found_count), int(found_cells), int(target_value)))

    if exact_value is not None and exact_value > 0:
        target_value = int(round(exact_value))
        if abs(exact_value - target_value) > 0.0001:
            return "invalid_input", ()
        # Count/avg-value constraints allow high totals to stay bounded.  With neither, use the
        # solver's low-total value-only guard and enumerate the whole count range in one pass.
        if fixed_quality is not None or has_avg_value:
            for count in count_candidates:
                add_solve(target_value, count=count)
        else:
            add_solve(target_value, count=None)
    else:
        for count in count_candidates:
            derived_total = _quality_total_from_public_avg(public_avg_value, count)
            if derived_total is not None:
                add_solve(derived_total, count=count)

    unsafe_statuses = statuses - {"ok"}
    if unsafe_statuses:
        return sorted(unsafe_statuses)[0], ()
    return "ok", tuple(sorted(states))


def _apply_q5_catalog_projection(
    *,
    map_id: int | None = None,
    total_count: int | None,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    count_sums: dict[str, int],
    avg_cells: dict[str, float],
    avg_values: dict[str, float],
    quality_cells: dict[str, float],
    quality_values: dict[str, float],
    quality_count_cells_options: dict[str, tuple[tuple[int, int], ...]],
    source_notes: list[str],
    known_facts: tuple[tuple[str, int, int], ...] = (),
) -> str:
    status, states = _q5_catalog_projection_candidates(
        key="q5",
        map_id=map_id,
        total_count=total_count,
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        count_sums=count_sums,
        avg_cells=avg_cells,
        avg_values=avg_values,
        quality_cells=quality_cells,
        quality_values=quality_values,
        source_notes=source_notes,
        known_facts=known_facts,
    )
    if status not in {"disabled", "not_applicable"}:
        _append_source_note_once(
            source_notes,
            f"{Q5_EXACT_VALUE_CELLS_NOTE}:{status}:{len(states)}",
        )
    if status != "ok" or not states:
        return status

    # The bounded solver has already capped avg-only count candidates.  Preserve its correlated
    # count/cell support even when several states survive; projecting only unique marginals can
    # manufacture a count/cell pair that no repeat-allowed item multiset realizes.
    if os.environ.get(Q5_CATALOG_JOINT_STATE_DISABLE) != "1":
        joint_options = tuple(sorted({(int(count), int(cells)) for count, cells, _ in states}))
        if joint_options:
            quality_count_cells_options["q5"] = joint_options
            _append_source_note_once(
                source_notes,
                f"{Q5_CATALOG_JOINT_STATE_NOTE}:{len(joint_options)}",
            )

    counts = {count for count, _, _ in states}
    cells = {cell_count for _, cell_count, _ in states}
    values = {value for _, _, value in states}
    if len(counts) == 1:
        unique_count = next(iter(counts))
        if fixed_counts.get("q5") is None:
            fixed_counts["q5"] = unique_count
            min_counts["q5"] = max(int(min_counts.get("q5", 0) or 0), unique_count)
        # The count may already be fixed by the independent fractional-average denominator. A
        # surviving single catalog count still confirms that projection and must remain visible in
        # diagnostics; only an empty/ambiguous catalog result omits this proof note.
        _append_source_note_once(
            source_notes,
            f"{Q5_CATALOG_PROJECTION_NOTE}:count:{unique_count}",
        )
        if "q5" in avg_values and "q5" in quality_values:
            strict_count = _avg_value_count_from_total(
                avg_values.get("q5"),
                quality_values.get("q5"),
            )
            _append_source_note_once(
                source_notes,
                "quality_value_q5_count_derived"
                if strict_count == unique_count
                else "quality_value_q5_count_derived_product_tolerance",
            )
        if (
            "q5" in avg_cells
            and "q5" in avg_values
            and "public_q5_avg_cells" not in source_notes
        ):
            _append_source_note_once(
                source_notes,
                "avg_value_cells_q5_count_derived",
            )
    if len(cells) == 1 and quality_cells.get("q5") is None:
        unique_cells = next(iter(cells))
        quality_cells["q5"] = float(unique_cells)
        _append_source_note_once(
            source_notes,
            f"{Q5_CATALOG_PROJECTION_NOTE}:cells:{unique_cells}",
        )
    if len(values) == 1 and quality_values.get("q5") is None:
        unique_value = next(iter(values))
        quality_values["q5"] = float(unique_value)
        _append_source_note_once(
            source_notes,
            f"{Q5_CATALOG_PROJECTION_NOTE}:value:{unique_value}",
        )
    if len(counts) == 1 and len(cells) == 1:
        _append_source_note_once(
            source_notes,
            f"{UNIQUE_COUNT_TWO_SIGNAL_NOTE}:q5:{next(iter(counts))}:{next(iter(cells))}:exact_multiset",
        )
    return status


def _apply_q6_catalog_projection(
    *,
    map_id: int | None,
    total_count: int | None,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    count_sums: dict[str, int],
    avg_cells: dict[str, float],
    avg_values: dict[str, float],
    quality_cells: dict[str, float],
    quality_values: dict[str, float],
    quality_count_cells_options: dict[str, tuple[tuple[int, int], ...]],
    source_notes: list[str],
    known_facts: tuple[tuple[str, int, int], ...] = (),
) -> str:
    """Project red price evidence through the same repeat-allowed joint solver as q5."""

    status, states = _q5_catalog_projection_candidates(
        key="q6",
        map_id=map_id,
        total_count=total_count,
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        count_sums=count_sums,
        avg_cells=avg_cells,
        avg_values=avg_values,
        quality_cells=quality_cells,
        quality_values=quality_values,
        source_notes=source_notes,
        known_facts=known_facts,
    )
    if status not in {"disabled", "not_applicable"}:
        _append_source_note_once(
            source_notes,
            f"{Q6_CATALOG_VALUE_JOINT_NOTE}:{status}:{len(states)}",
        )
    if status != "ok" or not states:
        return status

    joint_options = tuple(
        sorted({(int(count), int(cells)) for count, cells, _value in states})
    )
    if joint_options:
        quality_count_cells_options["q6"] = joint_options
        _append_source_note_once(
            source_notes,
            f"{Q6_CATALOG_JOINT_STATE_NOTE}:{len(joint_options)}",
        )

    counts = {int(count) for count, _cells, _value in states}
    cells = {int(cell_count) for _count, cell_count, _value in states}
    values = {int(value) for _count, _cells, value in states}
    if len(counts) == 1:
        unique_count = next(iter(counts))
        if fixed_counts.get("q6") is None:
            fixed_counts["q6"] = unique_count
            min_counts["q6"] = max(
                int(min_counts.get("q6", 0) or 0), unique_count
            )
        _append_source_note_once(
            source_notes,
            f"{Q6_CATALOG_PROJECTION_NOTE}:count:{unique_count}",
        )
    if len(cells) == 1 and quality_cells.get("q6") is None:
        unique_cells = next(iter(cells))
        quality_cells["q6"] = float(unique_cells)
        _append_source_note_once(
            source_notes,
            f"{Q6_CATALOG_PROJECTION_NOTE}:cells:{unique_cells}",
        )
    if len(values) == 1 and quality_values.get("q6") is None:
        unique_value = next(iter(values))
        quality_values["q6"] = float(unique_value)
        _append_source_note_once(
            source_notes,
            f"{Q6_CATALOG_PROJECTION_NOTE}:value:{unique_value}",
        )
    if len(counts) == 1 and len(cells) == 1:
        _append_source_note_once(
            source_notes,
            f"{UNIQUE_COUNT_TWO_SIGNAL_NOTE}:q6:{next(iter(counts))}:"
            f"{next(iter(cells))}:exact_multiset",
        )
    return status


def _strict_q6_full_avg_evidence(
    public_info: Mapping[str, Any],
    *,
    current_session: str | None,
) -> Any:
    rows: list[Mapping[str, Any]] = []
    for key in ("public_numeric_facts", "public_avg_values"):
        raw_rows = public_info.get(key)
        if not isinstance(raw_rows, Sequence) or isinstance(raw_rows, (str, bytes)):
            continue
        rows.extend(row for row in raw_rows if type(row) is dict)  # noqa: E721
    if not any(row.get("info_id") == Q6_FULL_AVG_INFO_ID for row in rows):
        return None
    try:
        from bidking_lab.inference.q6_full_avg_evidence import (
            q6_full_average_value_evidence_from_public_rows,
        )
    except Exception:
        # An exact 200038 row must never fall through to the approximate legacy
        # q6-average lane merely because packaging omitted the strict helper.
        return SimpleNamespace(
            status="conflict",
            conflicts=("strict_evidence_helper_unavailable",),
        )
    return q6_full_average_value_evidence_from_public_rows(
        rows,
        current_session_id=current_session,
    )


def _q6_full_avg_integer_total_bounds(
    mean_evidence: Any,
    count: int,
) -> tuple[str, int | None, int | None]:
    try:
        from bidking_lab.inference.q6_full_avg_evidence import (
            integer_total_bounds_from_q6_full_average,
        )

        bounds = integer_total_bounds_from_q6_full_average(
            mean_evidence,
            int(count),
        )
        return (
            str(bounds.status),
            _safe_int(bounds.lower),
            _safe_int(bounds.upper),
        )
    except Exception:
        return "integer_interval_unavailable", None, None


def _apply_q6_full_avg_multiset_support(
    *,
    mean_evidence: Any,
    map_id: int | None,
    total_count: int | None,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    count_sums: dict[str, int],
    avg_cells: dict[str, float],
    quality_cells: dict[str, float],
    quality_cell_floors: dict[str, float],
    quality_min_total_value_floors: dict[str, float],
    quality_values: dict[str, float],
    quality_count_cells_options: dict[str, tuple[tuple[int, int], ...]],
    quality_count_cells_value_options: dict[
        str, tuple[tuple[int, int, int], ...]
    ],
    source_notes: list[str],
    known_facts: tuple[tuple[str, int, int], ...] = (),
    physical_candidate_domains: tuple[dict[str, Any], ...] = (),
) -> tuple[str, tuple[tuple[str, int, int], ...], dict[str, Any]]:
    """Intersect strict 200038 mean intervals with canonical map-q6 multisets."""

    empty_summary: dict[str, Any] = {
        "status": "not_applicable",
        "catalog_generation": "",
        "joint_states": [],
        "count_one": {},
        "global_floors": {},
    }
    if mean_evidence is None or getattr(mean_evidence, "status", None) != "ok":
        status = str(getattr(mean_evidence, "status", "unavailable") or "unavailable")
        empty_summary["status"] = status
        return status, (), empty_summary
    if map_id is None:
        empty_summary["status"] = "map_catalog_unavailable"
        return "map_catalog_unavailable", (), empty_summary

    pairs, id_rows, catalog_status, generation = _validated_map_quality_catalog(
        int(map_id), 6
    )
    empty_summary["catalog_generation"] = str(generation or "")
    if catalog_status != "ok" or not pairs or not id_rows:
        empty_summary["status"] = catalog_status
        return catalog_status, (), empty_summary

    canonical_by_id = {
        int(item_id): (int(value), int(cells))
        for item_id, value, cells in id_rows
    }
    mandatory_units: list[dict[str, Any]] = []
    domain_aliases: dict[str, int] = {}
    for domain in physical_candidate_domains:
        if (
            domain.get("hard_eligible") is not True
            or domain.get("catalog_status") != "ok"
            or _safe_int(domain.get("quality")) != 6
        ):
            continue
        candidate_ids = tuple(
            int(item_id)
            for item_id in domain.get("candidate_item_ids", ())
            if type(item_id) is int and item_id > 0  # noqa: E721
        )
        domain_cells = _safe_int(domain.get("cells"))
        if not candidate_ids or domain_cells is None or domain_cells <= 0:
            empty_summary["status"] = "physical_domain_conflict"
            return "physical_domain_conflict", (), empty_summary
        candidate_rows = tuple(
            (item_id, *canonical_by_id[item_id])
            for item_id in candidate_ids
            if item_id in canonical_by_id
        )
        declared_values = {
            int(value)
            for value in domain.get("candidate_values", ())
            if type(value) is int and value > 0  # noqa: E721
        }
        if (
            len(candidate_rows) != len(candidate_ids)
            or any(cells != domain_cells for _item_id, _value, cells in candidate_rows)
            or {value for _item_id, value, _cells in candidate_rows}
            != declared_values
        ):
            empty_summary["status"] = "physical_domain_catalog_conflict"
            return "physical_domain_catalog_conflict", (), empty_summary
        aliases = {f"runtime:{int(domain['runtime_id'])}"}
        if type(domain.get("local_index")) is int:  # noqa: E721
            aliases.add(f"local:{int(domain['local_index'])}")
        if any(alias in domain_aliases for alias in aliases):
            empty_summary["status"] = "physical_domain_identity_conflict"
            return "physical_domain_identity_conflict", (), empty_summary
        unit_index = len(mandatory_units)
        for alias in aliases:
            domain_aliases[alias] = unit_index
        mandatory_units.append(
            {
                "identity": min(aliases),
                "aliases": tuple(sorted(aliases)),
                "options": tuple(
                    sorted({(value, cells) for _item_id, value, cells in candidate_rows})
                ),
                "ids_by_pair": {
                    (value, cells): tuple(
                        sorted(
                            item_id
                            for item_id, row_value, row_cells in candidate_rows
                            if (row_value, row_cells) == (value, cells)
                        )
                    )
                    for value, cells in {
                        (row_value, row_cells)
                        for _item_id, row_value, row_cells in candidate_rows
                    }
                },
                "candidate_ids": candidate_ids,
            }
        )

    for identity, cells, value in known_facts:
        domain_index = domain_aliases.get(str(identity))
        pair = (int(value), int(cells))
        if domain_index is not None:
            if pair not in mandatory_units[domain_index]["options"]:
                empty_summary["status"] = "physical_domain_known_fact_conflict"
                return "physical_domain_known_fact_conflict", (), empty_summary
            continue
        if pair not in set(pairs):
            empty_summary["status"] = "invalid_known_item"
            return "invalid_known_item", (), empty_summary
        mandatory_units.append(
            {
                "identity": str(identity),
                "aliases": (str(identity),),
                "options": (pair,),
                "ids_by_pair": None,
                "candidate_ids": (),
            }
        )

    mandatory_states: dict[
        tuple[int, int, int], tuple[tuple[int, int], ...]
    ] = {(0, 0, 0): ()}
    for unit in mandatory_units:
        next_states: dict[
            tuple[int, int, int], tuple[tuple[int, int], ...]
        ] = {}
        for (known_count, known_cells, known_value), selected_pairs in mandatory_states.items():
            for value, cells in unit["options"]:
                key = (known_count + 1, known_cells + cells, known_value + value)
                next_states.setdefault(key, (*selected_pairs, (cells, value)))
        if len(next_states) > 4096:
            empty_summary["status"] = "physical_domain_complexity_guard"
            return "physical_domain_complexity_guard", (), empty_summary
        mandatory_states = next_states

    fixed_quality = fixed_counts.get("q6")
    if fixed_quality is not None:
        ceiling = max(0, int(fixed_quality))
    elif total_count is not None and int(total_count) > 0:
        committed = sum(
            max(0, int(fixed_counts[other]))
            if fixed_counts.get(other) is not None
            else max(0, int(min_counts.get(other, 0) or 0))
            for other in QUALITY_KEYS
            if other != "q6"
        )
        ceiling = max(0, int(total_count) - committed)
    else:
        ceiling = 0

    interval = getattr(mean_evidence, "avg_interval", None)
    if (
        not isinstance(interval, tuple)
        or len(interval) != 2
        or not all(isinstance(value, (int, float)) for value in interval)
    ):
        empty_summary["status"] = "invalid_interval"
        return "invalid_interval", (), empty_summary
    mean_floor = max(1, int(math.ceil(float(interval[0]))))
    min_counts["q6"] = max(1, int(min_counts.get("q6", 0) or 0))
    quality_min_total_value_floors["q6"] = max(
        float(quality_min_total_value_floors.get("q6", 0.0) or 0.0),
        float(mean_floor),
    )

    if ceiling <= 0:
        cells_floor = min(int(cells) for _value, cells in pairs)
        quality_cell_floors["q6"] = max(
            float(quality_cell_floors.get("q6", 0.0) or 0.0),
            float(cells_floor),
        )
        summary = {
            **empty_summary,
            "status": "missing_ceiling",
            "global_floors": {
                "count": 1,
                "cells": cells_floor,
                "total_value": mean_floor,
            },
        }
        return "missing_ceiling", (), summary

    minimum = max(1, int(min_counts.get("q6", 0) or 0))
    count_candidates = (
        [int(fixed_quality)]
        if fixed_quality is not None and int(fixed_quality) >= minimum
        else list(range(minimum, ceiling + 1))
        if fixed_quality is None
        else []
    )
    if total_count is not None and int(total_count) > 0:
        count_candidates = _filter_avg_value_candidates_by_session(
            "q6",
            count_candidates,
            total_count=int(total_count),
            fixed_counts=fixed_counts,
            min_counts=min_counts,
            count_sums=count_sums,
        )
    exact_total_raw = _safe_float(quality_values.get("q6"))
    exact_total = None
    if exact_total_raw is not None:
        rounded_total = int(round(exact_total_raw))
        if rounded_total <= 0 or abs(exact_total_raw - rounded_total) > 0.0001:
            empty_summary["status"] = "invalid_exact_total"
            return "invalid_exact_total", (), empty_summary
        exact_total = rounded_total
    exact_cells_raw = _safe_float(quality_cells.get("q6"))
    exact_cells = None
    if exact_cells_raw is not None:
        rounded_cells = int(round(exact_cells_raw))
        if rounded_cells <= 0 or abs(exact_cells_raw - rounded_cells) > 0.0001:
            empty_summary["status"] = "invalid_exact_cells"
            return "invalid_exact_cells", (), empty_summary
        exact_cells = rounded_cells
    tool_avg_cells = any(
        re.fullmatch(r"action_\d+_q6_avg_cells(?:_.*)?", str(note)) is not None
        for note in source_notes
    )
    public_avg_cells = "public_q6_avg_cells" in source_notes
    hard_avg_cells = (
        _safe_float(avg_cells.get("q6"))
        if tool_avg_cells or ("q6" in avg_cells and not public_avg_cells)
        else None
    )

    states: set[tuple[int, int, int]] = set()
    count_one_ids_by_state: dict[tuple[int, int, int], set[int]] = {}
    statuses: set[str] = set()
    # Probe the widest residual first.  A safety-budget overflow invalidates the whole strict
    # support, so descending order reaches that explicit fail-closed result without first paying
    # for smaller-N states that must then be discarded.
    for count in reversed(count_candidates):
        bounds_status, total_lower, total_upper = _q6_full_avg_integer_total_bounds(
            mean_evidence,
            count,
        )
        if bounds_status == "empty_integer_total_interval":
            continue
        statuses.add(bounds_status)
        if (
            bounds_status != "ok"
            or total_lower is None
            or total_upper is None
        ):
            empty_summary["status"] = bounds_status
            return bounds_status, (), empty_summary
        if exact_total is not None:
            total_lower = max(int(total_lower), int(exact_total))
            total_upper = min(int(total_upper), int(exact_total))
            if total_lower > total_upper:
                continue
        for (
            known_count,
            known_cells,
            known_value,
        ), selected_pairs in mandatory_states.items():
            if (
                known_count > int(count)
                or known_value > int(total_upper)
                or (exact_cells is not None and known_cells > exact_cells)
            ):
                continue
            status, found_states = (
                _exact_fixed_count_cells_value_candidates_from_catalog(
                    pairs,
                    int(total_lower),
                    int(total_upper),
                    int(count),
                    hard_avg_cells,
                    selected_pairs,
                    exact_cells,
                    "q6",
                )
            )
            statuses.add(status)
            if status != "ok":
                empty_summary["status"] = status
                return status, (), empty_summary
            for found_count, found_cells, target_value in found_states:
                state = (
                    int(found_count),
                    int(found_cells),
                    int(target_value),
                )
                states.add(state)
                if int(found_count) != 1:
                    continue
                pair = (int(target_value), int(found_cells))
                if not mandatory_units:
                    candidate_ids = {
                        int(item_id)
                        for item_id, value, cells in id_rows
                        if (int(value), int(cells)) == pair
                    }
                elif len(mandatory_units) == 1:
                    ids_by_pair = mandatory_units[0]["ids_by_pair"]
                    candidate_ids = (
                        {
                            int(item_id)
                            for item_id, value, cells in id_rows
                            if (int(value), int(cells)) == pair
                        }
                        if ids_by_pair is None
                        else set(ids_by_pair.get(pair, ()))
                    )
                else:
                    candidate_ids = set()
                count_one_ids_by_state.setdefault(state, set()).update(
                    candidate_ids
                )
    unsafe_statuses = statuses - {"ok"}
    if unsafe_statuses:
        status = sorted(unsafe_statuses)[0]
        empty_summary["status"] = status
        return status, (), empty_summary
    if not states:
        empty_summary["status"] = "no_support"
        return "no_support", (), empty_summary

    ordered_states = tuple(sorted(states))
    quality_count_cells_value_options["q6"] = ordered_states
    quality_count_cells_options["q6"] = tuple(
        sorted({(count, cells) for count, cells, _value in ordered_states})
    )
    counts = {count for count, _cells, _value in ordered_states}
    cells = {cell_count for _count, cell_count, _value in ordered_states}
    values = {value for _count, _cells, value in ordered_states}
    count_floor = min(counts)
    cells_floor = min(cells)
    value_floor = min(values)
    min_counts["q6"] = max(int(min_counts.get("q6", 0) or 0), count_floor)
    quality_cell_floors["q6"] = max(
        float(quality_cell_floors.get("q6", 0.0) or 0.0),
        float(cells_floor),
    )
    quality_min_total_value_floors["q6"] = max(
        float(quality_min_total_value_floors.get("q6", 0.0) or 0.0),
        float(value_floor),
    )
    if len(counts) == 1 and fixed_counts.get("q6") is None:
        fixed_counts["q6"] = next(iter(counts))
    if len(cells) == 1 and quality_cells.get("q6") is None:
        quality_cells["q6"] = float(next(iter(cells)))

    count_one_states = tuple(row for row in ordered_states if row[0] == 1)
    count_one_candidates = tuple(
        sorted(
            {
                (int(item_id), int(value), int(cells_value))
                for item_id, value, cells_value in id_rows
                if any(int(item_id) in count_one_ids_by_state.get(state, set())
                       for state in count_one_states)
            }
        )
    )
    count_one_common: dict[str, Any] = {"quality": 6}
    if count_one_candidates:
        candidate_cells = {row[2] for row in count_one_candidates}
        candidate_values = {row[1] for row in count_one_candidates}
        if len(candidate_cells) == 1:
            count_one_common["cells"] = next(iter(candidate_cells))
        if len(candidate_values) == 1:
            count_one_common["value"] = next(iter(candidate_values))
    conditional_item_fact = None
    if len(count_one_candidates) == 1:
        item_id, item_value, item_cells = count_one_candidates[0]
        conditional_item_fact = {
            "identity": f"catalog:{item_id}",
            "item_id": item_id,
            "cells": item_cells,
            "value": item_value,
        }
    promoted: tuple[tuple[str, int, int], ...] = ()
    if conditional_item_fact is not None and len(count_one_states) == len(ordered_states):
        promoted = (
            (
                str(conditional_item_fact["identity"]),
                int(conditional_item_fact["cells"]),
                int(conditional_item_fact["value"]),
            ),
        )

    summary = {
        "status": "ok",
        "catalog_generation": str(generation or ""),
        "wire": {
            "raw_bits_hex": getattr(mean_evidence, "raw_bits_hex", None),
            "raw_value": getattr(mean_evidence, "raw_value", None),
            "avg_interval": [float(interval[0]), float(interval[1])],
            "session_id": getattr(mean_evidence, "source_session_id", None),
        },
        "joint_states": [list(row) for row in ordered_states],
        "count_one": {
            "candidate_count": len(count_one_candidates),
            "common_facts": count_one_common if count_one_candidates else {},
            "correlated_item_fact": conditional_item_fact,
        },
        "global_floors": {
            "count": count_floor,
            "cells": cells_floor,
            "total_value": value_floor,
        },
        "physical_domain_residuals": [
            {
                "identity": unit["identity"],
                "candidate_count": len(unit["candidate_ids"]),
                "candidate_ids": list(unit["candidate_ids"]),
                "value_cells_options": [
                    [value, cells] for value, cells in unit["options"]
                ],
            }
            for unit in mandatory_units
            if unit["candidate_ids"]
        ],
        "global_correlated_item_fact": (
            conditional_item_fact if promoted else None
        ),
    }
    return "ok", promoted, summary


def _q4_catalog_projection_candidates(
    *,
    map_id: int | None = None,
    total_count: int | None,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    count_sums: dict[str, int],
    avg_cells: dict[str, float],
    avg_values: dict[str, float],
    quality_cells: dict[str, float],
    quality_values: dict[str, float],
    source_notes: list[str],
    known_facts: tuple[tuple[str, int, int], ...] = (),
) -> tuple[str, tuple[tuple[int, int, int], ...]]:
    """Intersect q4 count/cells/value signals against the repeat-allowed catalog multiset."""
    if (
        os.environ.get(Q4_EXACT_VALUE_CELLS_DISABLE) == "1"
        or os.environ.get("BIDKING_DISABLE_UNIQUE_COUNT_TWO_SIGNALS") == "1"
    ):
        return "disabled", ()

    exact_value = _safe_float(quality_values.get("q4"))
    public_avg_value = _safe_float(avg_values.get("q4"))
    has_avg_value = _avg_value_has_positive_signal(public_avg_value)
    if (exact_value is None or exact_value <= 0) and not has_avg_value:
        return "not_applicable", ()

    if map_id is None:
        pairs, _, catalog_status = _validated_q4_catalog()
    else:
        pairs, _, catalog_status, _generation = _validated_map_quality_catalog(
            int(map_id), 4
        )
    if catalog_status != "ok":
        return catalog_status, ()
    public_avg_cells = "public_q4_avg_cells" in source_notes
    hard_avg_cells = (
        _safe_float(avg_cells.get("q4"))
        if "q4" in avg_cells and not public_avg_cells
        else None
    )
    exact_cells_raw = _safe_float(quality_cells.get("q4"))
    exact_cells = None
    if exact_cells_raw is not None:
        rounded_cells = int(round(exact_cells_raw))
        if abs(exact_cells_raw - rounded_cells) > 0.0001:
            return "invalid_exact_cells", ()
        exact_cells = rounded_cells

    fixed_q4 = fixed_counts.get("q4")
    has_exact_value = exact_value is not None and exact_value > 0
    if not has_exact_value and not has_avg_value:
        return "not_applicable", ()
    if not has_exact_value and not any(
        (
            fixed_q4 is not None,
            hard_avg_cells is not None,
            exact_cells is not None,
            bool(known_facts),
        )
    ):
        # A public average price is a soft prior until an independent q4 fact supplies the count,
        # cells, hard footprint mean, or a correlated physical item.
        return "not_applicable", ()
    if has_exact_value and not any(
        (
            fixed_q4 is not None,
            hard_avg_cells is not None,
            exact_cells is not None,
            has_avg_value,
            bool(known_facts),
        )
    ):
        # A lone purple total is deliberately not a new hard lane.  This projector is for correlated
        # two-signal (or richer) states; q5's separately calibrated low-value-only behavior is unchanged.
        return "not_applicable", ()

    if fixed_q4 is not None:
        ceiling = max(0, int(fixed_q4))
    elif total_count is not None and int(total_count) > 0:
        committed = sum(
            max(0, int(fixed_counts[other]))
            if fixed_counts.get(other) is not None
            else max(0, int(min_counts.get(other, 0) or 0))
            for other in QUALITY_KEYS
            if other != "q4"
        )
        ceiling = max(0, int(total_count) - committed)
    elif has_exact_value:
        ceiling = int(exact_value) // min(value for value, _ in pairs)
    else:
        return "missing_ceiling", ()
    if ceiling <= 0:
        return "invalid_input", ()

    minimum = max(1, int(min_counts.get("q4", 0) or 0))
    if fixed_q4 is not None:
        count_candidates = [int(fixed_q4)] if int(fixed_q4) >= minimum else []
    else:
        count_candidates = list(range(minimum, ceiling + 1))
    if total_count is not None and int(total_count) > 0:
        count_candidates = _filter_avg_value_candidates_by_session(
            "q4",
            count_candidates,
            total_count=int(total_count),
            fixed_counts=fixed_counts,
            min_counts=min_counts,
            count_sums=count_sums,
        )
    if has_avg_value:
        if has_exact_value:
            count_candidates = [
                count
                for count in count_candidates
                if _quality_count_product_tolerance_match(
                    count, public_avg_value, exact_value
                )
            ]
        else:
            count_candidates = [
                count
                for count in count_candidates
                if _avg_value_count_matches_for_public_evidence(
                    "q4", count, public_avg_value, source_notes
                )
            ]
    if not count_candidates:
        return "ok", ()
    if not has_exact_value and len(count_candidates) > Q5_EXACT_AVG_ONLY_MAX_COUNTS:
        return "avg_value_only_guard", ()

    states: set[tuple[int, int, int]] = set()
    statuses: set[str] = set()
    allowed_counts = set(count_candidates)

    def add_solve(target_value: int, *, count: int | None) -> None:
        status, candidates = _cached_exact_q4_count_cells_candidates(
            pairs,
            target_value,
            hard_avg_cells,
            ceiling,
            tuple(
                (int(cells), int(value)) for _, cells, value in known_facts
            ),
            count,
            exact_cells,
        )
        statuses.add(status)
        if status != "ok":
            return
        states.update(
            (int(found_count), int(found_cells), int(target_value))
            for found_count, found_cells in candidates
            if int(found_count) in allowed_counts
        )

    if has_exact_value:
        target_value = int(round(exact_value))
        if abs(exact_value - target_value) > 0.0001:
            return "invalid_input", ()
        add_solve(target_value, count=fixed_q4)
    else:
        for count in count_candidates:
            derived_total = _quality_total_from_public_avg(public_avg_value, count)
            if derived_total is not None:
                add_solve(derived_total, count=count)

    unsafe_statuses = statuses - {"ok"}
    if unsafe_statuses:
        return sorted(unsafe_statuses)[0], ()
    return "ok", tuple(sorted(states))


def _apply_q4_catalog_projection(
    *,
    map_id: int | None = None,
    total_count: int | None,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    count_sums: dict[str, int],
    avg_cells: dict[str, float],
    avg_values: dict[str, float],
    quality_cells: dict[str, float],
    quality_values: dict[str, float],
    quality_count_cells_options: dict[str, tuple[tuple[int, int], ...]],
    source_notes: list[str],
    known_facts: tuple[tuple[str, int, int], ...] = (),
) -> str:
    status, states = _q4_catalog_projection_candidates(
        map_id=map_id,
        total_count=total_count,
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        count_sums=count_sums,
        avg_cells=avg_cells,
        avg_values=avg_values,
        quality_cells=quality_cells,
        quality_values=quality_values,
        source_notes=source_notes,
        known_facts=known_facts,
    )
    if status not in {"disabled", "not_applicable"}:
        _append_source_note_once(
            source_notes,
            f"{Q4_EXACT_VALUE_CELLS_NOTE}:{status}:{len(states)}",
        )
    if status != "ok" or not states:
        return status

    joint_options = tuple(
        sorted({(int(count), int(cells)) for count, cells, _ in states})
    )
    quality_count_cells_options["q4"] = joint_options
    _append_source_note_once(
        source_notes,
        f"{Q4_CATALOG_JOINT_STATE_NOTE}:{len(joint_options)}",
    )

    counts = {count for count, _, _ in states}
    cells = {cell_count for _, cell_count, _ in states}
    if len(counts) == 1:
        unique_count = next(iter(counts))
        if fixed_counts.get("q4") is None:
            fixed_counts["q4"] = unique_count
            min_counts["q4"] = max(
                int(min_counts.get("q4", 0) or 0), unique_count
            )
        _append_source_note_once(
            source_notes,
            f"{Q4_CATALOG_PROJECTION_NOTE}:count:{unique_count}",
        )
    if len(cells) == 1 and quality_cells.get("q4") is None:
        unique_cells = next(iter(cells))
        quality_cells["q4"] = float(unique_cells)
        _append_source_note_once(
            source_notes,
            f"{Q4_CATALOG_PROJECTION_NOTE}:cells:{unique_cells}",
        )
    values = {value for _, _, value in states}
    if len(values) == 1 and quality_values.get("q4") is None:
        unique_value = next(iter(values))
        quality_values["q4"] = float(unique_value)
        _append_source_note_once(
            source_notes,
            f"{Q4_CATALOG_PROJECTION_NOTE}:value:{unique_value}",
        )
    if len(counts) == 1 and len(cells) == 1:
        _append_source_note_once(
            source_notes,
            f"{UNIQUE_COUNT_TWO_SIGNAL_NOTE}:q4:{next(iter(counts))}:{next(iter(cells))}:exact_multiset",
        )
    return status


@lru_cache(maxsize=1)
def _catalog_items_by_value() -> dict[int, tuple[tuple[int, int, int], ...]]:
    """exact catalog value -> the collectibles priced at it, as (quality, cells, item_id).

    Backs the 至宝估价 (100163/100162) wiring: that tool discloses ONLY the top item's VALUE (no
    quality, no outline — just a rough anchor point), but a collectible's price is near-unique in the
    catalog (585 distinct values; 84% belong to exactly one item), so the price identifies the item —
    the author's framing: "这个价格在游戏中一般唯一对应一个藏品,基本等同于抽检出了这个藏品".
    Ambiguous prices keep every candidate; the caller only uses what ALL candidates agree on.
    """
    try:
        grouped: dict[int, list[tuple[int, int, int]]] = {}
        for item in _current_calculation_items():
            if int(item.value) <= 0:
                continue
            cells = int(item.shape_w) * int(item.shape_h)
            grouped.setdefault(int(item.value), []).append(
                (int(item.quality), cells, int(item.item_id))
            )
        return {value: tuple(rows) for value, rows in grouped.items()}
    except Exception:
        return {}


@lru_cache(maxsize=1)
def _catalog_min_value_by_quality_and_cells() -> dict[tuple[int, int], int]:
    """Return the cheapest real collectible for each ``(quality, cells)`` pair."""
    minimums: dict[tuple[int, int], int] = {}
    for value, rows in _catalog_items_by_value().items():
        for quality, cells, _item_id in rows:
            if int(cells) <= 0:
                continue
            key = (int(quality), int(cells))
            current = minimums.get(key)
            if current is None or int(value) < current:
                minimums[key] = int(value)
    return minimums


@lru_cache(maxsize=4096)
def _catalog_min_total_value_for_quality_count_cells(
    table_quality: int,
    count: int,
    cells: int,
) -> int | None:
    """Cheapest catalog-composable value for an exact quality/count/cell triple."""
    if count < 0 or cells < 0:
        return None
    if count == 0:
        return 0 if cells == 0 else None
    per_size = {
        size: value
        for (quality, size), value in _catalog_min_value_by_quality_and_cells().items()
        if int(quality) == int(table_quality)
    }
    if not per_size:
        return None
    reachable: dict[int, int] = {0: 0}
    for _ in range(int(count)):
        next_reachable: dict[int, int] = {}
        for used_cells, used_value in reachable.items():
            for item_cells, item_value in per_size.items():
                total_cells = used_cells + int(item_cells)
                if total_cells > int(cells):
                    continue
                total_value = used_value + int(item_value)
                current = next_reachable.get(total_cells)
                if current is None or total_value < current:
                    next_reachable[total_cells] = total_value
        reachable = next_reachable
        if not reachable:
            return None
    return reachable.get(int(cells))


def _hard_joint_catalog_quote_floor(
    quality_count_cells_candidates: Mapping[str, Any],
    quality_lock: Mapping[str, Any],
) -> int:
    """Return a catalog floor only for one strict, physical red joint state."""
    if _run_env_get(HARD_JOINT_CATALOG_QUOTE_FLOOR_DISABLE) == "1":
        return 0
    raw_rows = quality_count_cells_candidates.get("q6")
    raw_lock = quality_lock.get("q6")
    if (
        type(raw_rows) not in (list, tuple)
        or len(raw_rows) != 1
        or type(raw_lock) is not dict  # noqa: E721 - internal JSON boundary
        or dict.get(raw_lock, "strength") != "exact"
    ):
        return 0
    row = raw_rows[0]
    if type(row) is tuple and len(row) == 3:  # noqa: E721 - engine-native row
        count, cells, probability = row
    elif type(row) is dict:  # noqa: E721 - serialized boundary/control harness
        count = dict.get(row, "count")
        cells = dict.get(row, "cells")
        probability = dict.get(row, "prob")
    else:
        return 0
    if (
        type(count) is not int  # noqa: E721 - reject bool/subclasses
        or type(cells) is not int  # noqa: E721 - reject bool/subclasses
        or count <= 0
        or cells <= 0
        or probability not in (1, 1.0)
    ):
        return 0
    minimum = _catalog_min_total_value_for_quality_count_cells(6, count, cells)
    return int(minimum or 0)


def _treasure_appraisal_match(value: float | int | None) -> tuple[str, int, float] | None:
    """(quality_key, cells, value) for a 至宝估价 price, or None when it cannot be pinned.

    Uses only what EVERY catalog candidate at that price agrees on: the quality must be unique
    (otherwise we do not know which tier gained an item) and the cells are the MINIMUM across
    candidates (a floor is safe; claiming the max would over-state the footprint).
    """
    parsed = _safe_float(value)
    if parsed is None or parsed <= 0:
        return None
    rows = _catalog_items_by_value().get(int(round(parsed)))
    if not rows:
        return None
    qualities = {row[0] for row in rows}
    if len(qualities) != 1:
        return None
    quality = next(iter(qualities))
    key = next((k for k, q in QUALITY_TIER_NUMBER.items() if int(q) == int(quality)), None)
    if key is None:
        return None
    cells = min(row[1] for row in rows)
    if cells <= 0:
        return None
    return key, int(cells), float(parsed)


def _strict_treasure_appraisal_evidence(
    snapshot: Any,
    *,
    hero: str,
    phase: str,
    map_id: int | None,
    current_session: str | None,
    current_round: int | None,
) -> tuple[str, tuple[str, int, float] | None]:
    """Select one current value-only 至宝估价 item atomically.

    The monitor keeps the item-bearing raw action row at the snapshot root;
    ``ui_contract.actions.results`` is a string-only diagnostic mirror and
    intentionally omits ``revealed_items_detail``. Bind the raw row to the
    exact root/context runtime instead of trusting that lossy mirror.
    """

    absent = (TREASURE_APPRAISAL_CONTEXT_STATUS_ABSENT, None)
    conflict = (TREASURE_APPRAISAL_CONTEXT_STATUS_CONFLICT, None)
    if type(snapshot) is not dict:  # noqa: E721 - exact product snapshot
        return conflict
    raw_rows = dict.get(snapshot, "action_result_rows")
    if raw_rows is None:
        return absent
    if type(raw_rows) is not list:  # noqa: E721 - monitor emits a JSON list
        return conflict

    targeted: list[dict[str, Any]] = []
    targeted_ids = {int(value) for value in TREASURE_HIGHEST_ITEM_VALUE_ACTION_IDS}
    for row in raw_rows:
        if type(row) is not dict or any(type(key) is not str for key in row):  # noqa: E721
            return conflict
        raw_action_id = dict.get(row, "action_id")
        raw_details = dict.get(row, "revealed_items_detail")
        claims_value = bool(
            type(raw_details) is list  # noqa: E721 - exact monitor container
            and any(
                type(item) is dict  # noqa: E721 - exact observed-item row
                and dict.get(item, "value") is not None
                for item in raw_details
            )
        )
        # 100162 is also the footprint/volume sibling in current captures.
        # Its cells-only row may legitimately coexist with the value-bearing
        # 100163 row and must not look like a duplicate appraisal.
        if raw_action_id == 100162 and not claims_value:
            continue
        if type(raw_action_id) is int and raw_action_id in targeted_ids:  # noqa: E721
            targeted.append(row)
            continue
        if (
            type(raw_action_id) is str  # noqa: E721 - malformed raw mirror
            and raw_action_id.isascii()
            and raw_action_id.isdigit()
            and int(raw_action_id) in targeted_ids
        ):
            return conflict
    if not targeted:
        return absent
    if len(targeted) != 1:
        return conflict
    row = targeted[0]
    if not _treasure_appraisal_row_has_plain_correlated_wire(row):
        return conflict

    ui_contract = dict.get(snapshot, "ui_contract")
    context = (
        dict.get(ui_contract, "context")
        if type(ui_contract) is dict  # noqa: E721 - exact JSON object
        else None
    )
    if type(context) is not dict:  # noqa: E721 - exact JSON object
        return conflict
    root_hero = dict.get(snapshot, "hero")
    context_hero = dict.get(context, "hero")
    root_phase = dict.get(snapshot, "phase")
    context_phase = dict.get(context, "phase")
    root_map = dict.get(snapshot, "map_id")
    context_map = dict.get(context, "map_id")
    root_session = dict.get(snapshot, "session_id")
    context_session = dict.get(context, "session_id")
    if (
        type(root_hero) is not str  # noqa: E721 - reject scalar subclasses
        or type(context_hero) is not str  # noqa: E721
        or normalize_hero_key(root_hero) != normalize_hero_key(context_hero)
        or normalize_hero_key(root_hero) != normalize_hero_key(hero)
        or type(root_phase) is not str  # noqa: E721
        or type(context_phase) is not str  # noqa: E721
        or root_phase.strip().lower() != "bidding"
        or context_phase.strip().lower() != "bidding"
        or str(phase or "").strip().lower() != "bidding"
        or type(root_map) is not int  # noqa: E721 - reject bool/subclasses
        or type(context_map) is not int  # noqa: E721
        or root_map <= 0
        or root_map != context_map
        or root_map != map_id
        or type(root_session) is not str  # noqa: E721
        or type(context_session) is not str  # noqa: E721
        or root_session != context_session
        or root_session != current_session
    ):
        return conflict
    session_match = re.fullmatch(
        r"(?P<map>[1-9][0-9]*):(?P<runtime>[1-9][0-9]*)",
        root_session,
    )
    if session_match is None or int(session_match.group("map")) != root_map:
        return conflict

    round_values = (
        dict.get(snapshot, "round"),
        dict.get(snapshot, "action_round"),
        dict.get(context, "round"),
        dict.get(context, "action_round"),
    )
    observed_values = (
        dict.get(snapshot, "observed_round"),
        dict.get(context, "observed_round"),
    )
    if (
        current_round is None
        or type(current_round) is not int  # noqa: E721
        or current_round <= 0
        or any(type(value) is not int for value in round_values)  # noqa: E721
        or any(value != current_round for value in round_values)
        or any(type(value) is not int for value in observed_values)  # noqa: E721
        or observed_values[0] != observed_values[1]
        or not 1 <= observed_values[0] <= current_round
    ):
        return conflict

    row_session = dict.get(row, "session_id")
    row_round = dict.get(row, "round")
    row_sort = dict.get(row, "sort")
    source_message_id = dict.get(row, "source_message_id")
    source_kind = dict.get(row, "source_kind")
    if (
        type(row_session) is not str  # noqa: E721
        or row_session != current_session
        or type(row_round) is not int  # noqa: E721
        or not 1 <= row_round <= current_round
        or type(row_sort) is not int  # noqa: E721
        or row_sort < 0
        or type(source_message_id) is not int  # noqa: E721
        or source_message_id <= 0
        or type(source_kind) is not str  # noqa: E721
        or source_kind not in {"direct_action_response", "state_replay"}
        or (source_message_id == 0x0027)
        != (source_kind == "direct_action_response")
        or type(dict.get(row, "revealed_items")) is not int  # noqa: E721
        or dict.get(row, "revealed_items") != 1
    ):
        return conflict
    details = dict.get(row, "revealed_items_detail")
    if type(details) is not list or len(details) != 1:  # noqa: E721
        return conflict
    item = details[0]
    if type(item) is not dict or any(type(key) is not str for key in item):  # noqa: E721
        return conflict
    quality = dict.get(item, "quality")
    if quality is not None:
        return (
            (TREASURE_APPRAISAL_CONTEXT_STATUS_NOT_APPLICABLE, None)
            if type(quality) is int and not isinstance(quality, bool) and 1 <= quality <= 6
            else conflict
        )
    runtime_id = dict.get(item, "runtime_id")
    value = dict.get(item, "value")
    if (
        type(runtime_id) is not int  # noqa: E721 - exact packet varint
        or runtime_id <= 0
        or runtime_id > Q5_EXACT_TOTAL_ACTION_INDEX_MAX
        or type(value) is not int  # noqa: E721 - exact catalog currency unit
        or value <= 0
        or value > Q5_EXACT_TOTAL_ACTION_VALUE_MAX
    ):
        return conflict
    match = _treasure_appraisal_match(value)
    if match is None:
        return (TREASURE_APPRAISAL_CONTEXT_STATUS_UNSUPPORTED, None)
    return (TREASURE_APPRAISAL_CONTEXT_STATUS_OK, match)


def _quality_key_item_table_quality(key: str) -> int | None:
    return QUALITY_KEY_TO_ITEM_TABLE_QUALITY.get(str(key or "").strip().lower())


def _exact_catalog_contains_value(key: str, value: float | int | None) -> bool:
    parsed = _safe_float(value)
    if parsed is None or parsed <= 0:
        return False
    table_quality = _quality_key_item_table_quality(key)
    if table_quality is None:
        return False
    values = _exact_item_values_by_table_quality().get(int(table_quality))
    if not values:
        return False
    return int(round(float(parsed))) in values


def _avg_is_exact_catalog_item_value(key: str, avg: float | None) -> bool:
    normalized = _ref_normalize_avg_value_wire(avg)
    if normalized is None or normalized <= 0:
        return False
    return _exact_catalog_contains_value(key, normalized)


def _apply_exact_catalog_value_locks(
    *,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    avg_values: dict[str, float],
    quality_values: dict[str, float],
    source_notes: list[str],
) -> None:
    """Keep q6 exact-total semantics; catalog-equal averages are support only."""
    for key in EXACT_CATALOG_VALUE_KEYS:
        if fixed_counts.get(key) is not None:
            continue
        exact_total = quality_values.get(key)
        if (
            key == "q6"
            and exact_total is not None
            and _exact_catalog_contains_value(key, exact_total)
        ):
            derived = 1
            avg = avg_values.get(key)
            if avg is not None:
                parsed = _avg_value_count_from_total(avg, exact_total)
                if parsed is not None:
                    derived = int(parsed)
            fixed_counts[key] = int(derived)
            min_counts[key] = max(int(min_counts.get(key, 0) or 0), int(derived))
            _append_source_note_once(
                source_notes,
                f"{EXACT_CATALOG_ITEM_VALUE_LOCK_NOTE}:{key}:"
                f"{int(round(float(exact_total)))}",
            )
            continue
        joint_enabled = not (
            key == "q6"
            and os.environ.get(Q6_CATALOG_VALUE_JOINT_DISABLE) == "1"
        )
        if key == "q5" or joint_enabled:
            avg = avg_values.get(key)
            if (
                avg is not None
                and _avg_value_has_positive_signal(avg)
                and not _avg_is_exact_catalog_item_value(key, avg)
            ):
                _append_source_note_once(
                    source_notes,
                    f"{EXACT_CATALOG_AVG_NO_ITEM_MATCH_NOTE}:{key}",
                )
            elif avg is not None and _avg_value_has_positive_signal(avg):
                _append_source_note_once(
                    source_notes,
                    f"catalog_avg_candidate_support:{key}:{int(round(float(avg)))}",
                )
            if exact_total is not None and _exact_catalog_contains_value(
                key, exact_total
            ):
                _append_source_note_once(
                    source_notes,
                    f"catalog_total_candidate_support:{key}:"
                    f"{int(round(float(exact_total)))}",
                )
            continue
        # Bounded rollback for the historical q6 shortcut.  It intentionally restores the exact
        # pre-successor behavior, including its over-hard count-one semantics.
        if exact_total is not None and _exact_catalog_contains_value(key, exact_total):
            derived = 1
            avg = avg_values.get(key)
            if avg is not None:
                parsed = _avg_value_count_from_total(avg, exact_total)
                if parsed is not None:
                    derived = int(parsed)
            fixed_counts[key] = int(derived)
            min_counts[key] = max(int(min_counts.get(key, 0) or 0), int(derived))
            _append_source_note_once(
                source_notes,
                f"{EXACT_CATALOG_ITEM_VALUE_LOCK_NOTE}:{key}:{int(round(float(exact_total)))}",
            )
            continue
        avg = avg_values.get(key)
        if avg is None or not _avg_value_has_positive_signal(avg):
            continue
        if not _avg_is_exact_catalog_item_value(key, avg):
            _append_source_note_once(
                source_notes,
                f"{EXACT_CATALOG_AVG_NO_ITEM_MATCH_NOTE}:{key}",
            )
            continue
        if not _avg_value_count_matches(1, avg):
            continue
        fixed_counts[key] = 1
        min_counts[key] = max(int(min_counts.get(key, 0) or 0), 1)
        _append_source_note_once(
            source_notes,
            f"{EXACT_CATALOG_ITEM_VALUE_LOCK_NOTE}:{key}:{int(round(float(avg)))}",
        )


# 排位图(family 56)在第三方 StaticData DropWeights 里没有条目(那张表只到 2601)→ 不接的话
# _map_tier(56xx) 落到 "104"(经典档, q6≈5%), 把红率压成经典图的一半。实测(1000+局, data/processed/
# quality_weights_measured.json 的 402 档; 6.25 又独立从 200 局 7353 件结算真值复核 q6=10.0%, 逐图
# 8.3-12.8% 紧致)显示排位红率是经典的 ~2 倍。注入实测 402 分布(6 元 [q1,q2,q3,q4,q5,q6], q2 并入 q1,
# 引擎下面会再 collapse 一次)。只覆盖 family-56 的品质先验, 不动 _map_tier(避免影响别处 tier 判断)。
# 若 quality_weights_measured.json 的 402 档显著变动需同步此常量。env 回退见下。
_RANK_TIER_402_QUALITY_WEIGHTS = [0.298, 0.0, 0.240, 0.249, 0.113, 0.100]


def _quality_probabilities(
    map_id: int | None,
    static_data: dict[str, Any],
) -> tuple[dict[str, float], str]:
    # NEW procedural drop-table prior (post-2026-06-25-noon). Per-map quality mix derived from
    # drop_weights_all_maps_0627 (品质权重×col6). For the 145 covered maps this supersedes both the
    # StaticData DropWeights[tier] and the hardcoded 56xx patch (it is the same measured source, so
    # ~identical except family-21 express, which the table makes more conservative on q5/q6). Default
    # ON; AHMAD_DISABLE_DROP_TABLE_QUALITY=1 reverts to the legacy StaticData path for old-era replay/AB.
    if isinstance(map_id, int) and os.environ.get("AHMAD_DISABLE_DROP_TABLE_QUALITY") != "1":
        tp = static_data.get("drop_table_priors", {}).get(map_id)
        qp = (tp or {}).get("quality_probs") or {}
        if all(k in qp for k in QUALITY_KEYS):
            total = sum(float(qp[k]) for k in QUALITY_KEYS) or 1.0
            return {k: max(1e-9, float(qp[k]) / total) for k in QUALITY_KEYS}, f"drop_table_prob:{map_id}"
    drop_weights: dict[str, list[float]] = static_data.get("drop_weights", {})
    tier = _map_tier(map_id)
    weights = drop_weights.get(tier) or drop_weights.get("104") or []
    family = (map_id // 100) if isinstance(map_id, int) else None
    if family == 56 and os.environ.get("AHMAD_DISABLE_RANK56_QUALITY_PRIOR") != "1":
        weights = _RANK_TIER_402_QUALITY_WEIGHTS
        tier = "402"
    if len(weights) < 6:
        return {key: 1.0 / len(QUALITY_KEYS) for key in QUALITY_KEYS}, "fallback_uniform_prob"
    collapsed = {
        "q1": weights[0] + weights[1],
        "q3": weights[2],
        "q4": weights[3],
        "q5": weights[4],
        "q6": weights[5],
    }
    total = sum(collapsed.values()) or 1.0
    return {key: max(1e-9, value / total) for key, value in collapsed.items()}, f"tier_prob:{tier}"


def _grid_fixed_for_total_target(
    key: str,
    *,
    counts: dict[str, int],
    avg_cells: dict[str, float],
    fixed_grid_keys: set[str],
    soft_avg_cell_keys: frozenset[str],
) -> bool:
    if counts.get(key, 0) == 0:
        return True
    if key in fixed_grid_keys:
        return True
    if key in avg_cells and key not in soft_avg_cell_keys:
        return True
    return False


@lru_cache(maxsize=4096)
def _fit_grid_option_domain_cached(
    key: str | None,
    count: int,
    remaining: int,
    respect_cell_floor: bool,
    cell_floor: float,
    q6_catalog_disabled: bool = False,
) -> tuple[int, ...]:
    """Composable options for one fit tier, keyed by every domain-changing input."""
    composable = (
        _composable_grid_options(int(count))
        if str(key or "").strip().lower() == "q6" and q6_catalog_disabled
        else _composable_grid_options_with_q6_catalog(key, count)
    )
    return tuple(
        option
        for option in composable
        if option <= remaining
        and (not respect_cell_floor or option + 1e-6 >= cell_floor)
    )


def _fit_grid_option_domain(
    count: int,
    remaining: int,
    *,
    key: str | None = None,
    respect_cell_floor: bool,
    cell_floor: float,
) -> tuple[int, ...]:
    if _run_env_get("AHMAD_DISABLE_FIT_OPTION_DOMAIN_CACHE") == "1":
        return tuple(
            option
            for option in _composable_grid_options_with_q6_catalog(key, count)
            if option <= remaining
            and (not respect_cell_floor or option + 1e-6 >= cell_floor)
        )
    return _fit_grid_option_domain_cached(
        key,
        count,
        remaining,
        respect_cell_floor,
        cell_floor,
        _run_env_get(Q6_CATALOG_CELL_COMPOSE_DISABLE) == "1",
    )


def _fit_grids_to_total_target(
    grids: dict[str, float],
    counts: dict[str, int],
    avg_cells: dict[str, float],
    target: float | None,
    fixed_grid_keys: set[str] | None = None,
    soft_avg_cell_keys: frozenset[str] | None = None,
    cell_floors: dict[str, float] | None = None,
    exact_dp: bool = True,
    option_overrides: dict[str, tuple[int, ...]] | None = None,
    prefer_contiguous_slack_exact: bool = False,
) -> dict[str, float]:
    """`exact_dp=False` skips the composable subset-sum DP and goes straight to the proportional
    fallback below. Used by the 族D reconcile pass, for two reasons:
      * cost — the DP is this engine's known hot spot and it runs per combo. aisha never paid it before
        (no total target => early return), so switching it on for every combo took p90 526ms -> 2143ms
        and the worst vault to 6.5s. That is the "推理中" hang, not an acceptable price for a display fix.
      * fit — 族D only ever reconciles UPWARD, so the scale factor is >1, no cell floor can bind, and the
        proportional split lands Σ exactly on the target anyway. Spreading the orphan cells across the
        scalable tiers in proportion to what they already hold IS the intended allocation; the DP's
        composable-integer refinement buys nothing here (the value model takes floats, and the display
        re-snaps to a composable option around the center)."""
    if target is None or target <= 0:
        return grids
    fixed_grid_keys = fixed_grid_keys or set()
    soft_avg_cell_keys = soft_avg_cell_keys or frozenset()
    fixed_values = [
        grids[key]
        for key in QUALITY_KEYS
        if _grid_fixed_for_total_target(
            key,
            counts=counts,
            avg_cells=avg_cells,
            fixed_grid_keys=fixed_grid_keys,
            soft_avg_cell_keys=soft_avg_cell_keys,
        )
    ]
    scalable_keys = [
        key
        for key in QUALITY_KEYS
        if not _grid_fixed_for_total_target(
            key,
            counts=counts,
            avg_cells=avg_cells,
            fixed_grid_keys=fixed_grid_keys,
            soft_avg_cell_keys=soft_avg_cell_keys,
        )
    ]
    if _grid_alloc_true_means_on() and scalable_keys:
        # Re-anchor the FREE tiers on the true mean cells/item before dealing out the (pinned) total, so
        # the split stops handing gold/red's cells to the low tiers. Pinned tiers are untouched, and Σ is
        # forced to `target` either way — see GRID_ALLOC_TRUE_MEANS_ENABLE for why that bound is what makes
        # this safe to do at all.
        grids = dict(grids)
        for key in scalable_keys:
            if counts.get(key, 0) > 0:
                grids[key] = float(counts[key]) * VALUE_SIZE_PREMIUM_REF_CELLS[key]
    # Revealed footprints are lower bounds on tier cells, not item-count hints. Apply them while
    # constructing the exact-DP domain: allowing the DP to choose a smaller option and relying on the
    # caller's post-fit check rejects the whole count combo. Gabriela 2405 exposed that failure mode:
    # the valid q6=1 / 10-cell combo was fit to 9 cells, discarded, and only q6=4 combos survived.
    # Keep the existing B3 rollback switch as one coherent A/B for both exact-DP and fallback paths.
    _cell_floor_map = cell_floors or {}
    _respect_cell_floors = (
        cell_floors is not None
        and _run_env_get("DRAW_HERO_DISABLE_FIT_CELLFLOOR_FLOOR") != "1"
    )
    target_int = int(round(target))
    if (
        exact_dp
        and scalable_keys
        and abs(float(target) - target_int) <= 0.25
        and all(abs(value - round(value)) <= 1e-6 for value in fixed_values)
    ):
        fixed_total_int = sum(int(round(value)) for value in fixed_values)
        remaining = target_int - fixed_total_int
        _option_overrides = option_overrides or {}
        option_map = {
            key: tuple(
                option
                for option in _option_overrides[key]
                if option <= remaining
                and (
                    not _respect_cell_floors
                    or option + 1e-6 >= float(_cell_floor_map.get(key, 0.0))
                )
            )
            if key in _option_overrides
            else _fit_grid_option_domain(
                int(counts[key]),
                remaining,
                key=key,
                respect_cell_floor=_respect_cell_floors,
                cell_floor=float(_cell_floor_map.get(key, 0.0)),
            )
            for key in scalable_keys
        }
        if (
            prefer_contiguous_slack_exact
            and remaining >= 0
            and all(option_map.values())
        ):
            # Whole-warehouse display averages can yield two adjacent hard totals on
            # large vaults.  The generic DP complexity guard intentionally falls back
            # to proportional floats there, but those floats are not catalog states.
            # Most unconstrained non-red domains are contiguous, so one such tier can
            # absorb the exact residual in O(number of options) without bypassing the
            # catalog or paying the large-vault subset-sum cost per combo.
            for slack_key in sorted(
                scalable_keys,
                key=lambda key: (-len(option_map[key]), key),
            ):
                slack_options = option_map[slack_key]
                if any(
                    right != left + 1
                    for left, right in zip(slack_options, slack_options[1:])
                ):
                    continue
                selected: dict[str, int] = {}
                for key in scalable_keys:
                    if key == slack_key:
                        continue
                    selected[key] = min(
                        option_map[key],
                        key=lambda option: (abs(option - grids[key]), option),
                    )
                slack_value = remaining - sum(selected.values())
                if slack_value not in slack_options:
                    continue
                fitted = dict(grids)
                fitted[slack_key] = float(slack_value)
                for key, option in selected.items():
                    fitted[key] = float(option)
                return fitted
        # Exact-DP complexity cap (2026-07-04, tatiana 2513 R1 群友卡顿: 公开总格=219 EQUALITY 锚 +
        # R1 最宽 count 先验 → 每 combo 的 exact 子集和 DP ~300k 状态转移 × 2500 combos = live fast
        # 1.4-1.7s/帧、full ~43s 被 too-heavy skip、overlay"推理中24s"。实测复杂度谱: 正常无锚局
        # 0 次 fit;伊森带锚局 36k-130k(保留 exact);病理≥~200k 只有大总格+宽 count 早轮。超过
        # 上限降级到下方比例缩放兜底(同 settled-ui-freeze max_combos cap 先例: 早轮口径本就宽松,
        # 总格锚不丢,只有逐档拆分从 exact 变比例)。Rollback/调阈: AHMAD_FITGRIDS_EXACT_DP_CAP
        # (默认 150000; 0=不设限)。
        _dp_cap = 150000
        try:
            _dp_cap = int(_run_env_get("AHMAD_FITGRIDS_EXACT_DP_CAP", _dp_cap))
        except (TypeError, ValueError):
            pass
        _dp_est = remaining * sum(len(options) for options in option_map.values())
        if (
            remaining >= 0
            and all(option_map.values())
            and (_dp_cap <= 0 or _dp_est <= _dp_cap)
        ):
            if _run_env_get("AHMAD_DISABLE_FITGRIDS_BACKPTR") == "1":
                # Original assignment-dict DP (kept for A/B byte-identity verification).
                states: dict[int, tuple[float, dict[str, int]]] = {0: (0.0, {})}
                for key in scalable_keys:
                    default = grids[key]
                    scale = max(1.0, abs(default))
                    next_states: dict[int, tuple[float, dict[str, int]]] = {}
                    for current_sum, (cost, assignment) in states.items():
                        for option in option_map[key]:
                            new_sum = current_sum + option
                            if new_sum > remaining:
                                continue
                            new_cost = cost + ((option - default) / scale) ** 2
                            existing = next_states.get(new_sum)
                            if existing is not None and existing[0] <= new_cost:
                                continue
                            next_assignment = dict(assignment)
                            next_assignment[key] = option
                            next_states[new_sum] = (new_cost, next_assignment)
                    states = next_states
                    if not states:
                        break
                exact = states.get(remaining)
                if exact is not None:
                    fitted = dict(grids)
                    for key, option in exact[1].items():
                        fitted[key] = float(option)
                    return fitted
            else:
                # Backpointer DP: same min-cost subset-sum, but store only cost per partial
                # sum + a per-layer backpointer (prev_sum, option) instead of copying the full
                # assignment dict on every transition. Reconstruct the chosen options at the end
                # by walking the layers backward. Behaviour-identical to the dict-DP above
                # (same tie-break: first/lowest-cost wins via `existing <= new_cost`), pure
                # speedup — the assignment-dict copy was ~half the per-combo grid-fit cost on
                # rich activity-map rounds. Rollback: AHMAD_DISABLE_FITGRIDS_BACKPTR=1.
                # Forward/backward reachability bound (default ON, rollback
                # AHMAD_DISABLE_FITGRIDS_REACH_BOUND=1): precompute, per scalable key in
                # iteration order, the suffix min/max of the *remaining* keys' option_maps.
                # During each layer we drop partial sums that provably cannot end at exactly
                # `remaining`: if new_sum + suffix_max(rest) < remaining it can never grow
                # enough; if new_sum + suffix_min(rest) > remaining it has already overshot an
                # exact-sum target. Such states never appear in state_cost[remaining], so the
                # min-cost value and reconstructed assignment are byte-identical — pure prune,
                # 68-78% fewer transitions on the largest-target (overlay-freezing) rounds.
                _reach_bound = _run_env_get("AHMAD_DISABLE_FITGRIDS_REACH_BOUND") != "1"
                suffix_min: list[int] = [0] * (len(scalable_keys) + 1)
                suffix_max: list[int] = [0] * (len(scalable_keys) + 1)
                if _reach_bound:
                    for i in range(len(scalable_keys) - 1, -1, -1):
                        opts = option_map[scalable_keys[i]]
                        suffix_min[i] = suffix_min[i + 1] + min(opts)
                        suffix_max[i] = suffix_max[i + 1] + max(opts)
                if _run_env_get("AHMAD_DISABLE_FITGRIDS_ARRAY_DP") == "1":
                    # Rollback path for the original dict-backed backpointer DP.
                    state_cost: dict[int, float] = {0: 0.0}
                    layers: list[dict[int, tuple[int, int]]] = []
                    for idx, key in enumerate(scalable_keys):
                        default = grids[key]
                        scale = max(1.0, abs(default))
                        opt_costs = [
                            (option, ((option - default) / scale) ** 2)
                            for option in option_map[key]
                        ]
                        next_cost: dict[int, float] = {}
                        dict_back: dict[int, tuple[int, int]] = {}
                        rest_min = suffix_min[idx + 1]
                        rest_max = suffix_max[idx + 1]
                        for current_sum, cost in state_cost.items():
                            for option, oc in opt_costs:
                                new_sum = current_sum + option
                                if new_sum > remaining:
                                    continue
                                if _reach_bound and (
                                    new_sum + rest_max < remaining
                                    or new_sum + rest_min > remaining
                                ):
                                    continue
                                new_cost = cost + oc
                                existing = next_cost.get(new_sum)
                                if existing is not None and existing <= new_cost:
                                    continue
                                next_cost[new_sum] = new_cost
                                dict_back[new_sum] = (current_sum, option)
                        state_cost = next_cost
                        layers.append(dict_back)
                        if not state_cost:
                            break
                    if state_cost.get(remaining) is not None:
                        fitted = dict(grids)
                        cur = remaining
                        for key, layer_back in zip(reversed(scalable_keys), reversed(layers)):
                            prev_sum, option = layer_back[cur]
                            fitted[key] = float(option)
                            cur = prev_sum
                        return fitted
                else:
                    # Sums are dense integers in [0, remaining]. Lists avoid millions of hash-table
                    # lookups while ``state_order`` preserves the dict DP's insertion/tie order exactly.
                    state_values = [math.inf] * (remaining + 1)
                    state_values[0] = 0.0
                    state_order = [0]
                    array_layers: list[list[tuple[int, int] | None]] = []
                    for idx, key in enumerate(scalable_keys):
                        default = grids[key]
                        scale = max(1.0, abs(default))
                        opt_costs = [
                            (option, ((option - default) / scale) ** 2)
                            for option in option_map[key]
                        ]
                        next_values = [math.inf] * (remaining + 1)
                        next_order: list[int] = []
                        array_back: list[tuple[int, int] | None] = [None] * (remaining + 1)
                        rest_min = suffix_min[idx + 1]
                        rest_max = suffix_max[idx + 1]
                        for current_sum in state_order:
                            cost = state_values[current_sum]
                            for option, oc in opt_costs:
                                new_sum = current_sum + option
                                if new_sum > remaining:
                                    continue
                                if _reach_bound and (
                                    new_sum + rest_max < remaining
                                    or new_sum + rest_min > remaining
                                ):
                                    continue
                                new_cost = cost + oc
                                existing = next_values[new_sum]
                                if existing <= new_cost:
                                    continue
                                if existing == math.inf:
                                    next_order.append(new_sum)
                                next_values[new_sum] = new_cost
                                array_back[new_sum] = (current_sum, option)
                        state_values = next_values
                        state_order = next_order
                        array_layers.append(array_back)
                        if not state_order:
                            break
                    if state_values[remaining] != math.inf:
                        fitted = dict(grids)
                        cur = remaining
                        for key, layer_back in zip(reversed(scalable_keys), reversed(array_layers)):
                            link = layer_back[cur]
                            if link is None:  # pragma: no cover - guarded by the reachable final state
                                break
                            prev_sum, option = link
                            fitted[key] = float(option)
                            cur = prev_sum
                        else:
                            return fitted

    # A proportional fallback must not invent a value between hard discrete states.  Keep the
    # nearest legal state selected by the caller fixed and scale only the remaining free tiers.
    _override_keys = set(option_overrides or {})
    fallback_scalable_keys = [key for key in scalable_keys if key not in _override_keys]
    fixed_total = sum(fixed_values) + sum(
        grids[key] for key in scalable_keys if key in _override_keys
    )
    scalable_total = sum(grids[key] for key in fallback_scalable_keys)
    if not fallback_scalable_keys or scalable_total <= 0:
        return grids
    remaining = max(0.0, target - fixed_total)
    scale = remaining / scalable_total
    fitted = dict(grids)
    # B3 (gabriela 2408 star-map latch): when the exact-DP subset-sum can't reach an INFEASIBLE soft
    # target (sparse_early cap 47 << the cell-floor-respecting minimum), this proportional fallback
    # collapses each grid toward its count. Without the cell_floor term a quality whose floor is ONE
    # revealed item's footprint (q6 star-map = 6 cells) folds to grid≈count, then the post-fit floor
    # check (fitted[q6] < cell_floor) rejects every combo with count<6 -> the count LATCHES to 6, mis-
    # reading a 6-cell footprint as a 6-item count. Floor the fold at cell_floor so the known footprint
    # survives and the count is free to be the true low value. Kill (exact-DP + fallback):
    # DRAW_HERO_DISABLE_FIT_CELLFLOOR_FLOOR=1.
    for key in fallback_scalable_keys:
        _cf = float(_cell_floor_map.get(key, 0.0)) if _respect_cell_floors else 0.0
        fitted[key] = max(float(counts[key]), _cf, grids[key] * scale)
    return fitted


# aisha hero_id + 逐轮揭示顺序(skill_id): 白(R1)→绿(R2)→蓝(R3)→紫(R4)。引擎白+绿合并为低品 q1。
_AISHA_HERO_ID = 103
_AISHA_REVEAL_SEQUENCE = (1001034, 1001033, 1001032, 1001031)
_AISHA_LOW_SPLIT_SKILL = {
    1001034: "white",
    1001033: "green",
}
AISHA_SPLIT_PROVENANCE_ANTILOCK_DISABLE = (
    "BIDKING_DISABLE_AISHA_SPLIT_PROVENANCE_ANTILOCK"
)
AISHA_SPLIT_PROVENANCE_ANTILOCK_NOTE = "aisha_split_provenance_q1_antilock"
AISHA_POST_SPLIT_TOTAL_GRID_RESIDUAL_DISABLE = (
    "BIDKING_DISABLE_POST_SPLIT_TOTAL_GRID_RESIDUAL_CLOSURE"
)
AISHA_POST_SPLIT_TOTAL_GRID_RESIDUAL_NOTE = (
    "aisha_post_split_total_grid_residual_closure"
)


def _aisha_split_count_is_exact(
    split_key: str,
    *,
    seen_skill_ids: set[int],
    source_notes: list[str],
) -> bool:
    """Whether a white/green split count is warehouse-exact, not a sample floor."""
    skill_id = next(
        (sid for sid, key in _AISHA_LOW_SPLIT_SKILL.items() if key == split_key),
        None,
    )
    if skill_id is not None and skill_id in seen_skill_ids:
        return True
    exact_notes = {
        f"structured_ref_bridge_split_count_{split_key}",
        f"field_update_split_{split_key}_count",
        f"aisha_absent_{split_key}_inferred_zero",
        f"split_low_quality_{split_key}_count_derived",
        f"split_low_quality_{split_key}_count_from_q1_exact",
        f"split_low_quality_{split_key}_zero_avg_count_zero",
    }
    if split_key == "green":
        exact_notes.update(
            {
                f"action_{GREEN_COUNT_ACTION}_green_count",
                f"action_{GREEN_COUNT_ACTION}_green_count_inferred_zero",
                f"action_{GREEN_VALUE_SUM_ACTION}_green_count_inferred_zero",
            }
        )
    return any(note in exact_notes for note in source_notes)


def _apply_aisha_absent_low_quality_zero(
    snapshot: dict[str, Any],
    hero: Any,
    *,
    split_counts: dict[str, int],
    split_count_exact_keys: set[str],
    split_quality_cells: dict[str, float],
    infer_zero_cells: bool,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    source_notes: list[str],
) -> None:
    """aisha 顺序揭白(R1)→绿(R2)→蓝(R3)→紫(R4), 引擎白+绿合并为低品 q1。**0 白/0 绿仓时游戏不发该品质
    揭示帧**(该 skill 全局缺席)→ 该低品件永不锁死(仅 floor)→ 早轮空/低品虚高 → 严重低估。修: 某低品
    (白/绿)揭示缺席但**顺序更靠后的品质揭示已到**(该低品揭示窗口已确定关闭)→ 该品质=0;白+绿都定 →
    q1=白+绿 精确锁。覆盖: 白=0(绿/蓝/紫任一在)、绿=0(白已明确且蓝/紫任一在)；白绿都缺少
    正锚点时保持保守，不从后期残缺快照双推 0。
    当前 replay-active truth-qualified 样本池(2026-07-20, 1001 局 aisha)中: 67 局绿帧缺席均停在蓝/紫
    揭示之前，"绿缺席+蓝/紫已到"误锁候选 0; 5607 live 正例则白帧明确、结算绿=0 且蓝/紫正常到达。
    绿=0 还要求白拆分已经明确，避免只保留后期帧的残缺/合成快照把白绿同时误锁 0。**默认 ON**;
    白/绿分别可用 `AISHA_DISABLE_ABSENT_WHITE_ZERO=1` / `AISHA_DISABLE_ABSENT_GREEN_ZERO=1` 回退。
    ⚠️丢包 caveat: 前置帧被丢也表现为缺席; 仅在"更靠后品质已揭示"(窗口确定关闭)才推断，仍需观察 live
    样本。注: ahmed 等【白绿均格/总格=0】走 avg_cells.q1/quality_cells.q1 显式通道，与本条不同。"""
    disabled_splits: set[str] = set()
    if os.environ.get("AISHA_DISABLE_ABSENT_WHITE_ZERO") == "1":
        disabled_splits.add("white")
    if os.environ.get("AISHA_DISABLE_ABSENT_GREEN_ZERO") == "1":
        disabled_splits.add("green")
    if len(disabled_splits) == len(_AISHA_LOW_SPLIT_SKILL):
        return
    if normalize_hero_key(hero) != "aisha":
        return
    seen: set[int] = set()
    for row in list(_iter_skill_reveal_dict_rows(snapshot)) + list(_iter_dicts(snapshot.get("skill_reveals"))):
        if _safe_int(row.get("hero_id")) != _AISHA_HERO_ID:
            continue
        sid = _safe_int(row.get("skill_id"))
        if sid is not None:
            seen.add(sid)
    provenance_antilock = (
        _run_env_get(AISHA_SPLIT_PROVENANCE_ANTILOCK_DISABLE) != "1"
    )
    white_anchor = (
        "white" in split_count_exact_keys
        if provenance_antilock
        else split_counts.get("white") is not None
        or _AISHA_REVEAL_SEQUENCE[0] in seen
    )
    for idx, sid in enumerate(_AISHA_REVEAL_SEQUENCE):
        qname = _AISHA_LOW_SPLIT_SKILL.get(sid)
        if qname is None:  # 蓝/紫 非低品 q1 档, 不推断
            continue
        if qname in disabled_splits:
            continue
        if qname == "green" and not white_anchor:
            continue  # 无白色正锚点的后期残缺快照不能证明白/绿揭示链完整
        if split_counts.get(qname) is not None:
            continue  # 该品质已知(揭示到, 含 present-0) → 不推断
        if sid in seen:
            continue  # 该品质揭示其实存在 → 不推断
        if not any(later in seen for later in _AISHA_REVEAL_SEQUENCE[idx + 1:]):
            continue  # 更靠后品质未揭示 → 该品质揭示窗口未确定关闭(帧或许还没到), 保守不锁
        split_counts[qname] = 0
        split_count_exact_keys.add(qname)
        source_notes.append(f"aisha_absent_{qname}_inferred_zero")
        if infer_zero_cells and split_quality_cells.get(qname) is None:
            split_quality_cells[qname] = 0.0
            _append_source_note_once(
                source_notes,
                f"aisha_absent_{qname}_cells_inferred_zero",
            )
    white, green = split_counts.get("white"), split_counts.get("green")
    if white is not None and green is not None and fixed_counts.get("q1") is None:
        q1 = int(white) + int(green)  # 白+绿 低品档
        min_counts["q1"] = max(int(min_counts.get("q1", 0)), q1)
        split_counts_exact = all(
            split_key in split_count_exact_keys
            for split_key in _AISHA_LOW_SPLIT_SKILL.values()
        )
        if not provenance_antilock or split_counts_exact:
            fixed_counts["q1"] = q1
            source_notes.append("aisha_absent_low_quality_q1_lock")
        else:
            _append_source_note_once(
                source_notes,
                AISHA_SPLIT_PROVENANCE_ANTILOCK_NOTE,
            )


def _apply_low_quality_split_evidence(
    *,
    total_count: int | None,
    split_counts: dict[str, int],
    split_count_exact_keys: set[str],
    split_quality_cells: dict[str, float],
    split_avg_cells: dict[str, float],
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    avg_cells: dict[str, float],
    quality_cells: dict[str, float],
    source_notes: list[str],
) -> None:
    has_split_signal = bool(split_counts or split_quality_cells or split_avg_cells)
    if has_split_signal and fixed_counts.get("q1") is None and total_count is not None:
        other_keys = tuple(key for key in QUALITY_KEYS if key != "q1")
        if all(fixed_counts.get(key) is not None for key in other_keys):
            residual = int(total_count) - sum(int(fixed_counts[key]) for key in other_keys)
            known_split_count = sum(
                int(split_counts[key])
                for key in LOW_SPLIT_KEYS
                if split_counts.get(key) is not None
            )
            min_q1 = max(int(min_counts.get("q1", 0)), known_split_count)
            if residual < min_q1:
                source_notes.append("split_low_quality_q1_count_total_residual_conflict")
                source_notes.append("hard_conflict:split_low_quality_q1_count_total_residual")
            elif residual >= 0:
                fixed_counts["q1"] = residual
                min_counts["q1"] = max(min_counts.get("q1", 0), residual)
                source_notes.append("split_low_quality_q1_count_from_total_residual")

    if has_split_signal and fixed_counts.get("q1") is None and quality_cells.get("q1") is not None:
        derived_count = _avg_count_from_cells(
            avg_cells.get("q1"), quality_cells.get("q1"), "q1"
        )
        if derived_count is not None:
            fixed_counts["q1"] = derived_count
            min_counts["q1"] = max(min_counts.get("q1", 0), derived_count)
            source_notes.append("split_low_quality_q1_count_from_avg_cells")

    if has_split_signal and quality_cells.get("q1") is None and fixed_counts.get("q1") is not None:
        options = _avg_grid_options(
            int(fixed_counts["q1"]), avg_cells.get("q1"), "q1"
        )
        if len(options) == 1:
            quality_cells["q1"] = float(options[0])
            source_notes.append("split_low_quality_q1_cells_from_avg_count")

    if has_split_signal and fixed_counts.get("q1") is not None:
        missing_counts = [
            key for key in LOW_SPLIT_KEYS if split_counts.get(key) is None
        ]
        known_counts = [
            int(split_counts[key])
            for key in LOW_SPLIT_KEYS
            if split_counts.get(key) is not None
        ]
        if len(missing_counts) == 1 and len(known_counts) == 1:
            missing = int(fixed_counts["q1"]) - known_counts[0]
            if missing < 0:
                source_notes.append("split_low_quality_q1_count_complement_conflict")
                source_notes.append("hard_conflict:split_low_quality_q1_count_complement")
            else:
                split_counts[missing_counts[0]] = missing
                split_count_exact_keys.add(missing_counts[0])
                source_notes.append(f"split_low_quality_{missing_counts[0]}_count_from_q1_exact")

    if has_split_signal and quality_cells.get("q1") is not None:
        missing_cells = [
            key for key in LOW_SPLIT_KEYS if split_quality_cells.get(key) is None
        ]
        known_cells = [
            float(split_quality_cells[key])
            for key in LOW_SPLIT_KEYS
            if split_quality_cells.get(key) is not None
        ]
        if len(missing_cells) == 1 and len(known_cells) == 1:
            missing = float(quality_cells["q1"]) - known_cells[0]
            if missing < -0.0001:
                source_notes.append("split_low_quality_q1_cells_complement_conflict")
                source_notes.append("hard_conflict:split_low_quality_q1_cells_complement")
            else:
                split_quality_cells[missing_cells[0]] = max(0.0, missing)
                source_notes.append(f"split_low_quality_{missing_cells[0]}_cells_from_q1_exact")

    for split_key in LOW_SPLIT_KEYS:
        count = split_counts.get(split_key)
        cells = split_quality_cells.get(split_key)
        avg = split_avg_cells.get(split_key)
        if avg == 0 and count is None:
            split_counts[split_key] = 0
            split_count_exact_keys.add(split_key)
            count = 0
            source_notes.append(f"split_low_quality_{split_key}_zero_avg_count_zero")
        if count is None and avg is not None and cells is not None:
            derived_count = _avg_count_from_cells(avg, cells)
            if derived_count is None:
                source_notes.append(f"split_low_quality_{split_key}_avg_cells_conflict")
                source_notes.append(f"hard_conflict:split_low_quality_{split_key}_avg_cells")
            else:
                split_counts[split_key] = derived_count
                split_count_exact_keys.add(split_key)
                count = derived_count
                source_notes.append(f"split_low_quality_{split_key}_count_derived")
        if cells is None and count is not None and avg is not None:
            options = _avg_grid_options(int(count), avg)
            if len(options) == 1:
                split_quality_cells[split_key] = float(options[0])
                cells = float(options[0])
                source_notes.append(f"split_low_quality_{split_key}_cells_derived")
            elif not options:
                source_notes.append(f"split_low_quality_{split_key}_avg_count_conflict")
                source_notes.append(f"hard_conflict:split_low_quality_{split_key}_avg_count")
        if avg is None and count is not None and cells is not None:
            if not can_compose_grid_total(int(count), int(round(float(cells)))):
                source_notes.append(f"split_low_quality_{split_key}_count_cells_conflict")
                source_notes.append(f"hard_conflict:split_low_quality_{split_key}_count_cells")
                continue
            if int(count) == 0:
                if abs(float(cells)) > 0.0001:
                    source_notes.append(f"split_low_quality_{split_key}_count_cells_conflict")
                    source_notes.append(f"hard_conflict:split_low_quality_{split_key}_count_cells")
                else:
                    split_avg_cells[split_key] = 0.0
                    source_notes.append(f"split_low_quality_{split_key}_avg_derived")
            else:
                split_avg_cells[split_key] = float(cells) / float(count)
                source_notes.append(f"split_low_quality_{split_key}_avg_derived")
        elif avg is not None and count is not None and cells is not None:
            cells_int = int(round(float(cells)))
            if not can_compose_grid_total(int(count), cells_int) or not _avg_matches_exact_grid(
                int(count),
                avg,
                cells_int,
            ):
                source_notes.append(f"split_low_quality_{split_key}_avg_count_cells_conflict")
                source_notes.append(f"hard_conflict:split_low_quality_{split_key}_avg_count_cells")

    known_count_sum = sum(
        int(split_counts[key])
        for key in LOW_SPLIT_KEYS
        if split_counts.get(key) is not None
    )
    if known_count_sum > 0:
        min_counts["q1"] = max(min_counts.get("q1", 0), known_count_sum)
        source_notes.append("split_low_quality_q1_min_count")
    if _split_low_quality_q1_grid_extra_from_maps(split_counts, split_quality_cells) > 0:
        source_notes.append("split_low_quality_q1_grid_floor")

    have_all_counts = all(split_counts.get(key) is not None for key in LOW_SPLIT_KEYS)
    have_all_cells = all(split_quality_cells.get(key) is not None for key in LOW_SPLIT_KEYS)
    coarse_split_floor = (
        "coarse_quality_reveal_split_counts" in source_notes
        or "maria_skill_coarse_quality_split_counts" in source_notes
    )
    split_counts_exact = (not coarse_split_floor) or all(
        key in split_count_exact_keys for key in LOW_SPLIT_KEYS
    )
    if have_all_counts:
        merged_count = sum(int(split_counts[key]) for key in LOW_SPLIT_KEYS)
        existing_count = fixed_counts.get("q1")
        if existing_count is None and not split_counts_exact:
            # White/green split counts seen so far came from random public/skill sample
            # reveals (e.g. "未知别墅" shows a random subset). Those are floors: there may
            # be more white/green items that were never sampled. Without an exact q1 to
            # anchor against, treat the sampled sum as a minimum for q1 instead of
            # locking q1 to the sampled count, which would badly under-count low items
            # and over-allocate the total to higher tiers.
            min_counts["q1"] = max(min_counts.get("q1", 0), merged_count)
            source_notes.append("split_low_quality_q1_coarse_floor_only")
        elif existing_count is not None and int(existing_count) != merged_count:
            if (
                int(existing_count) > merged_count
                and "coarse_quality_reveal_split_counts" in source_notes
            ):
                # Public coarse split counts come from random sample floors, not an
                # exact white/green warehouse breakdown. Exact q1 skill/count wins.
                min_counts["q1"] = max(min_counts.get("q1", 0), int(existing_count))
                source_notes.append("split_low_quality_q1_exact_overrides_coarse_split")
            else:
                source_notes.append("split_low_quality_q1_count_conflict")
                source_notes.append("hard_conflict:split_low_quality_q1_count")
        else:
            fixed_counts["q1"] = merged_count
            min_counts["q1"] = max(min_counts.get("q1", 0), merged_count)
            source_notes.append("split_low_quality_q1_count_merged")
    if have_all_cells:
        merged_cells = sum(float(split_quality_cells[key]) for key in LOW_SPLIT_KEYS)
        existing_cells = quality_cells.get("q1")
        if existing_cells is not None and abs(float(existing_cells) - merged_cells) > 0.0001:
            source_notes.append("split_low_quality_q1_cells_conflict")
            source_notes.append("hard_conflict:split_low_quality_q1_cells")
        else:
            quality_cells["q1"] = merged_cells
            source_notes.append("split_low_quality_q1_cells_merged")
    if fixed_counts.get("q1") is not None and quality_cells.get("q1") is not None and "q1" not in avg_cells:
        count = int(fixed_counts["q1"])
        cells = float(quality_cells["q1"])
        if count > 0:
            avg_cells["q1"] = cells / count
            source_notes.append("split_low_quality_q1_avg_derived")
        elif abs(cells) <= 0.0001:
            avg_cells["q1"] = 0.0
            source_notes.append("split_low_quality_q1_avg_derived")


def _layout_stage_warehouse_cells_p50(snapshot: dict[str, Any]) -> float | None:
    rows = snapshot.get("layout_stage_rows") or ()
    for row in reversed(tuple(rows)):
        if not isinstance(row, dict):
            continue
        estimate = str(row.get("布局估计") or "").strip()
        parts = [part.strip() for part in estimate.split("/") if part.strip()]
        if len(parts) < 2:
            continue
        parsed = _safe_float(parts[1])
        if parsed is not None and parsed > 0:
            return parsed
    return None


def _complete_settlement_truth_total_cells(
    snapshot: dict[str, Any],
    truth: Mapping[str, Any],
) -> float | None:
    """Return the closed item/quality cell truth for a complete settlement only.

    Layout rows are retained across rounds and can therefore be a useful fallback for
    an incomplete capture, but they must not overrule a fully closed settlement.  Keep
    this gate deliberately strict so a partial capture cannot be promoted to truth.
    """
    if str(snapshot.get("phase") or "").strip().lower() != "settled":
        return None
    if snapshot.get("settlement_incomplete") is not False:
        return None
    if truth.get("complete") is not True or truth.get("partial") is True:
        return None

    total_items = _safe_int(truth.get("total_items"))
    total_cells = _safe_int(truth.get("total_cells"))
    if total_items is None or total_cells is None:
        return None

    inventory_count = _safe_int(snapshot.get("inventory_count"))
    inventory_cells = _safe_int(snapshot.get("inventory_cells"))
    captured_items = _safe_int(truth.get("captured_items"))
    captured_cells = _safe_int(truth.get("captured_cells"))
    declared_items = _safe_int(truth.get("declared_items"))
    declared_cells = _safe_int(truth.get("declared_cells"))
    strict_fields = (
        _run_env_get("BIDKING_DISABLE_STRICT_COMPLETE_SETTLEMENT_TRUTH") != "1"
    )
    if strict_fields:
        if inventory_count is None or inventory_count != total_items:
            return None
        if inventory_cells is None or inventory_cells != total_cells:
            return None
        if captured_items is None or captured_items != total_items:
            return None
        if captured_cells is None or captured_cells != total_cells:
            return None
        if declared_items is not None and declared_items != total_items:
            return None
        if declared_cells is not None and declared_cells != total_cells:
            return None
    else:
        if inventory_count is not None and inventory_count != total_items:
            return None
        if inventory_cells is not None and inventory_cells != total_cells:
            return None
        if captured_items is not None and captured_items != total_items:
            return None
        if declared_items is not None and (
            captured_items is None or declared_items != captured_items
        ):
            return None

    quality_counts, quality_cells = _settlement_quality_truth(snapshot)
    if not quality_counts or not quality_cells:
        return None
    if sum(quality_counts.values()) != total_items:
        return None
    if sum(quality_cells.values()) != total_cells:
        return None
    return float(total_cells)


def _settlement_review_total_cells(snapshot: dict[str, Any], truth: Mapping[str, Any]) -> float | None:
    complete_truth_cells = _complete_settlement_truth_total_cells(snapshot, truth)
    if complete_truth_cells is not None:
        return complete_truth_cells
    item_cells = _safe_float(truth.get("total_cells"))
    if item_cells is None:
        item_cells = _safe_float(snapshot.get("inventory_cells"))
    layout_cells = _layout_stage_warehouse_cells_p50(snapshot)
    if layout_cells is not None and (item_cells is None or float(layout_cells) > float(item_cells)):
        return float(layout_cells)
    return item_cells


def _normalized_physical_candidate_domain_rows(
    snapshot: dict[str, Any],
) -> tuple[dict[str, Any], ...]:
    raw_sources: list[Any] = []
    if "physical_candidate_domains" in snapshot:
        raw_sources.append(snapshot.get("physical_candidate_domains"))
    ui_contract = snapshot.get("ui_contract")
    constraints = (
        ui_contract.get("constraints")
        if isinstance(ui_contract, dict)
        and isinstance(ui_contract.get("constraints"), dict)
        else {}
    )
    for candidate in _candidate_structured_inputs(
        snapshot,
        ui_contract if isinstance(ui_contract, dict) else {},
        constraints,
    ):
        if "physical_candidate_domains" in candidate:
            raw_sources.append(candidate.get("physical_candidate_domains"))
    if not raw_sources:
        return ()

    normalized_sources: list[tuple[dict[str, Any], ...]] = []
    for raw_rows in raw_sources:
        if not isinstance(raw_rows, list):
            return ()
        normalized: list[dict[str, Any]] = []
        seen_runtime_ids: set[int] = set()
        for raw in raw_rows:
            if not isinstance(raw, dict):
                return ()
            runtime_id = raw.get("runtime_id")
            local_index = raw.get("local_index")
            cells = raw.get("cells")
            shape_key = raw.get("shape_key")
            required = raw.get("required_categories")
            excluded = raw.get("excluded_categories")
            excluded_quality_rows = raw.get("excluded_qualities", [])
            candidate_ids = raw.get("candidate_item_ids")
            candidate_qualities = raw.get("candidate_qualities")
            candidate_values = raw.get("candidate_values")
            hard_eligible = raw.get("hard_eligible")
            catalog_status = raw.get("catalog_status")
            generation = raw.get("catalog_generation")
            if (
                type(runtime_id) is not int
                or runtime_id <= 0
                or runtime_id in seen_runtime_ids
                or (local_index is not None and type(local_index) is not int)
                or type(cells) is not int
                or cells <= 0
                or type(shape_key) is not str
                or len(shape_key) != 2
                or not shape_key.isdigit()
                or int(shape_key[0]) * int(shape_key[1]) != cells
                or type(hard_eligible) is not bool
                or catalog_status not in {"ok", "no_candidates"}
                or type(generation) is not str
                or not generation.startswith("physical-category-v1:")
            ):
                return ()

            def exact_int_tuple(
                value: Any,
                *,
                minimum: int,
                maximum: int | None = None,
            ) -> tuple[int, ...] | None:
                if not isinstance(value, list) or any(
                    type(entry) is not int
                    or entry < minimum
                    or (maximum is not None and entry > maximum)
                    for entry in value
                ):
                    return None
                result = tuple(value)
                if result != tuple(sorted(set(result))):
                    return None
                return result

            required_categories = exact_int_tuple(
                required,
                minimum=101,
                maximum=110,
            )
            excluded_categories = exact_int_tuple(
                excluded,
                minimum=101,
                maximum=110,
            )
            excluded_qualities = exact_int_tuple(
                excluded_quality_rows,
                minimum=1,
                maximum=5,
            )
            item_ids = exact_int_tuple(candidate_ids, minimum=1)
            qualities = exact_int_tuple(
                candidate_qualities,
                minimum=1,
                maximum=6,
            )
            values = exact_int_tuple(candidate_values, minimum=1)
            if (
                required_categories is None
                or excluded_categories is None
                or excluded_qualities is None
                or not (required_categories or excluded_categories)
                or item_ids is None
                or qualities is None
                or values is None
                or set(required_categories) & set(excluded_categories)
                or (catalog_status == "ok" and not item_ids)
                or (catalog_status == "no_candidates" and item_ids)
            ):
                return ()
            observed_quality = raw.get("observed_quality")
            quality = raw.get("quality")
            quality_source = raw.get("quality_source")
            if observed_quality is not None and (
                type(observed_quality) is not int
                or not 1 <= observed_quality <= 6
            ):
                return ()
            if (
                observed_quality is not None
                and observed_quality in excluded_qualities
            ):
                return ()
            if quality is None:
                if quality_source not in {None, ""}:
                    return ()
            elif type(quality) is not int or qualities != (quality,):
                return ()
            elif observed_quality is not None:
                if quality != observed_quality or quality_source not in {
                    None,
                    "",
                    "observed",
                }:
                    return ()
            elif (
                quality != 6
                or quality_source != "catalog_red_domain"
                or not hard_eligible
                or not required_categories
            ):
                return ()
            exact_item_id = raw.get("exact_item_id")
            exact_value = raw.get("exact_value")
            if (exact_item_id is None) != (exact_value is None):
                return ()
            if exact_item_id is not None and (
                type(exact_item_id) is not int
                or type(exact_value) is not int
                or not hard_eligible
                or item_ids != (exact_item_id,)
                or values != (exact_value,)
            ):
                return ()
            seen_runtime_ids.add(runtime_id)
            normalized.append(dict(raw))
        normalized_sources.append(tuple(normalized))
    if any(source != normalized_sources[0] for source in normalized_sources[1:]):
        return ()
    return normalized_sources[0]


def _shape_average_skill_round_current(row, snapshot, current_round):
    """Qualify projected skill time without overwriting its wire round units."""
    if not any(key in row for key in ("round_index", "round_index_state", "state_round_index")):
        # Existing explicitly scoped evaluator rows use the one-based round.
        value = row.get("round")
        return type(value) is int and type(current_round) is int and 1 <= value <= current_round
    from bidking_lab.live.monitor import (
        _EXPECTED_WIRE_SKILL_ROUND_INDEX,
        _skill_reveal_round_projection,
        _valid_semantic_session_id,
    )
    if not _valid_semantic_session_id(row.get("session_id")):
        return False
    status = row.get("round_index_state")
    value = row.get("round_index")
    if status not in {"wire", "skill_canonical"} or type(value) is not int or value < 0:
        return False
    projected = _skill_reveal_round_projection(hero_id=row.get("hero_id"), skill_id=row.get("skill_id"),
        wire_round_index=value if status == "wire" else None)
    if projected != (value, status, None) or row.get("round_index_wire") is not None:
        return False
    state_round = row.get("state_round_index")
    context = _dig(snapshot, "ui_contract", "context")
    context = context if isinstance(context, Mapping) else {}
    observed_values = [source.get("observed_round") for source in (snapshot, context)
                       if source.get("observed_round") is not None]
    if any(type(value) is not int or value < 0 for value in observed_values) or len(set(observed_values)) > 1:
        return False
    observed = observed_values[0] if observed_values else None
    if type(current_round) is not int or current_round < 1:
        return False
    for source in (snapshot, context):
        for key in ("round", "action_round"):
            if source.get(key) is not None and (type(source[key]) is not int or source[key] != current_round):
                return False
    if row.get("round") is not None and (type(row["round"]) is not int or not 1 <= row["round"] <= current_round):
        return False
    # Bidding current/action is after each already-observed state coordinate.
    # Equality is unsafe; exact +1 is not universal when the latest state has
    # no round and the caller falls back to the sent-bid count instead.
    for coordinate in (state_round, observed):
        if coordinate is not None and (type(coordinate) is not int or coordinate < 0
                                       or coordinate >= current_round or value > coordinate):
            return False
    if state_round is not None and observed is not None and state_round > observed:
        return False
    if row.get("skill_id") in {ETHAN_SKILL_FULL_OUTLINE, RAVEN_ALL_ITEM_QUALITY_SKILL_ID}:
        # Skill identity supplies the established R5 scope, not a wire==5
        # claim. No real R5 packet establishes that raw index here.
        expected_hero = 208 if row["skill_id"] == ETHAN_SKILL_FULL_OUTLINE else 301
        if row.get("hero_id") != expected_hero or current_round < 5:
            return False
    if state_round is not None or observed is not None:
        return True  # Generic projected-coordinate compatibility, not packet provenance.
    canonical_r1 = _skill_reveal_round_projection(hero_id=row.get("hero_id"), skill_id=row.get("skill_id"),
        wire_round_index=None) == (0, "skill_canonical", None)
    known_wire = (row.get("hero_id"), row.get("skill_id")) in _EXPECTED_WIRE_SKILL_ROUND_INDEX
    return (canonical_r1 and value == 0) or (known_wire and value < current_round)


def _shape_average_physical_context(snapshot, *, session, map_id, domains, total_count,
                                    physical_domains):
    """Reconcile current raw physical identities; no display-count authority."""
    from bidking_lab.inference.v2 import _validated_physical_category_catalog
    catalog, reachable, status, generation = _validated_physical_category_catalog()
    if status != "ok" or map_id not in reachable:
        return None
    candidates = {item.item_id: item for domain in domains.values() for item in domain.candidates}
    parent = {}
    def find(key):
        parent.setdefault(key, key)
        while parent[key] != key:
            parent[key] = parent[parent[key]]
            key = parent[key]
        return key
    def aliases(item):
        keys = []
        for field, minimum, prefix in (("runtime_id", 1, "runtime"), ("local_index", 0, "local")):
            value = item.get(field)
            if value is not None:
                if type(value) is not int or value < minimum:
                    raise ValueError("physical_identity_invalid")
                keys.append(f"{prefix}:{value}")
        if not keys:
            return ()
        for key in keys:
            find(key)
        for key in keys[1:]:
            parent[find(key)] = find(keys[0])
        return tuple(keys)
    rows = []
    complete_outlines = []
    current_round = _safe_int(snapshot.get("round") or _dig(snapshot, "ui_contract", "context", "round"))
    try:
        for name, id_key in (("action_result_rows", "action_id"), ("skill_reveal_rows", "skill_id"),
                             ("public_info_rows", "info_id")):
            raw = snapshot.get(name, ())
            if name == "skill_reveal_rows" and not raw:
                raw = snapshot.get("skill_reveals", ())
            if not isinstance(raw, (list, tuple)):
                return None
            for source in raw:
                if not isinstance(source, Mapping) or source.get("session_id") != session:
                    continue
                round_no = source.get("round")
                if type(round_no) is int and current_round is not None and round_no > current_round:
                    return None
                if name == "skill_reveal_rows" and not _shape_average_skill_round_current(source, snapshot, current_round):
                    return None
                items = source.get("revealed_items_detail") or source.get("observed_items") or ()
                if not isinstance(items, (list, tuple)):
                    return None
                full = ((name == "action_result_rows" and source.get(id_key) == 100100)
                        or (name == "skill_reveal_rows" and source.get(id_key) == 1002085))
                outline = []
                for item in items:
                    if not isinstance(item, Mapping):
                        return None
                    keys = aliases(item)
                    if not keys:
                        if full:
                            return None
                        continue
                    rows.append((keys, item, None))
                    if full:
                        shape = _raven_shape(item.get("shape_code") or item.get("shape_key"))
                        if shape is None:
                            return None
                        outline.append((keys[0], shape[0] * shape[1]))
                if full:
                    if not outline or len({key for key, _ in outline}) != len(outline):
                        return None
                    complete_outlines.append(outline)
        for domain in physical_domains:
            if domain.get("catalog_generation") != generation or domain.get("catalog_status") != "ok":
                return None
            keys = aliases(domain)
            if not keys:
                return None
            # Recheck candidate membership from the same complete taxonomy;
            # serialized soft weights or a narrowed list are never authority.
            shape = _raven_shape(domain.get("shape_key"))
            if shape is None:
                return None
            encoded_shape = int(domain["shape_key"])
            domain_orientation = (encoded_shape // 10, encoded_shape % 10)
            allowed = set()
            for item_id in reachable[map_id]:
                item = catalog[item_id]
                if (item.width, item.height) != domain_orientation:
                    continue
                quality = domain.get("observed_quality")
                if quality is not None and item.quality != quality:
                    continue
                if item.quality in domain.get("excluded_qualities", ()):
                    continue
                if any(value in item.category_no for value in domain.get("required_categories", ())):
                    continue
                if any(value in item.category_yes for value in domain.get("excluded_categories", ())):
                    continue
                allowed.add(item_id)
            if set(domain.get("candidate_item_ids", ())) != allowed:
                return None
            rows.append((keys, {"cells": domain["cells"], "shape_key":domain["shape_key"],
                                "quality":domain.get("observed_quality")}, allowed))
        grouped = {}
        for keys, item, allowed in rows:
            group = grouped.setdefault(find(keys[0]), {"keys":set(), "cells":set(), "shapes":set(), "qualities":set(),
                "values":set(), "ids":set(), "domains":[]})
            group["keys"].update(keys)
            shape = _raven_shape(item.get("shape_code") or item.get("shape_key"))
            cells = item.get("cells")
            if cells is not None and (type(cells) is not int or cells <= 0):
                return None
            if shape is not None:
                group["shapes"].add(shape)
                shaped_cells = shape[0] * shape[1]
                if cells is not None and cells != shaped_cells:
                    return None
                cells = shaped_cells
            if cells is not None:
                group["cells"].add(cells)
            for field, target in (("quality", "qualities"), ("item_id", "ids"), ("value", "values")):
                value = item.get(field)
                if value is None:
                    continue
                if field == "value" and type(value) is float and math.isfinite(value) and value.is_integer():
                    value = int(value)
                if type(value) is not int or value <= 0 or (field == "quality" and value > 6):
                    return None
                group[target].add(value)
            if allowed is not None:
                group["domains"].append(allowed)
        units = {}
        counts = {}
        for key, group in grouped.items():
            if (sum(name.startswith("runtime:") for name in group["keys"]) > 1
                    or any(len(group[name]) > 1 for name in ("cells", "shapes", "qualities", "values", "ids"))):
                return None
            eligible = set(candidates)
            if group["ids"]:
                eligible &= group["ids"]  # exact anchor precedes a same-identity option domain
            else:
                for allowed in group["domains"]:
                    eligible &= allowed
            eligible = {item_id for item_id in eligible if
                        (not group["cells"] or candidates[item_id].cells in group["cells"])
                        and (not group["shapes"] or tuple(sorted((candidates[item_id].width,candidates[item_id].height))) in group["shapes"])
                        and (not group["qualities"] or candidates[item_id].quality in group["qualities"])
                        and (not group["values"] or candidates[item_id].value in group["values"])}
            if not eligible:
                return None
            areas = {candidates[item_id].cells for item_id in eligible}
            if len(areas) != 1:
                continue  # unpaired value/quality cannot invent an exact physical bucket
            cells = next(iter(areas))
            counts[cells] = counts.get(cells, 0) + 1
            units.setdefault(cells, []).append({"identity":key, "candidate_item_ids":sorted(eligible),
                                               "catalog_generation":generation})
        outlines = [{find(key):cells for key,cells in outline} for outline in complete_outlines]
        if outlines and (any(outline != outlines[0] for outline in outlines[1:])
                         or set(outlines[0]) != set(grouped)
                         or len(outlines[0]) != sum(counts.values())):
            return None
        exact = bool(outlines) or (type(total_count) is int and total_count > 0
                                  and total_count == len(grouped) == sum(counts.values()))
        if outlines and total_count is not None and total_count != len(outlines[0]):
            return None
        targets = [{"cells":cells, "count_exact" if exact else "count_partial":counts.get(cells, 0),
                    "count_provenance":["semantic_full_outline" if outlines else
                                        "exact_total_item_count_trusted_identities" if exact else "partial_revealed_footprints"]}
                   for cells in (1, 2, 3, 4, 6) if exact or counts.get(cells)]
        return targets, units, (sum(counts.values()) if exact else total_count), (
            sum(cells*n for cells,n in counts.items()) if exact else None)
    except (KeyError, TypeError, ValueError):
        return None


def _shape_average_active_joint_facts(
    snapshot: dict[str, Any],
    *,
    phase: str,
    current_session: str | None,
    map_id: int | None,
    total_count: int | None,
    fixed_counts: Mapping[str, int],
    quality_cells: Mapping[str, float],
    physical_candidate_domains: Sequence[Mapping[str, Any]],
    source_notes: Sequence[str],
) -> tuple[dict[str, float], tuple[dict[str, Any], ...]]:
    """Promote complete current physical mean support, never an inferred CID."""

    if (
        phase.strip().lower() != "bidding"
        or type(current_session) is not str  # noqa: E721
        or not current_session
        or type(map_id) is not int  # noqa: E721
        or map_id <= 0
    ):
        return {}, ()
    try:
        from bidking_lab.inference.size_avg_evidence import (
            SHAPE_AVG_ACTIVE_JOINT_DISABLE,
            SIZE_AVG_ACTION_FOOTPRINT,
            MEAN_SUPPORT_MAX_COUNT,
            _join_shape_average_support,
            exact_quality_footprint_count_options,
            shape_average_value_evidence_from_action_rows,
        )
        from bidking_lab.inference.v2 import _canonical_map_all_footprint_domains
    except Exception:  # pragma: no cover - packaged import failure must no-op
        return {}, ()
    if _run_env_get(SHAPE_AVG_ACTIVE_JOINT_DISABLE) == "1":
        return {}, ()

    raw_rows: Any
    if "action_result_rows" in snapshot:
        raw_rows = snapshot.get("action_result_rows")
    else:
        ui_contract = snapshot.get("ui_contract")
        actions = (
            ui_contract.get("actions")
            if isinstance(ui_contract, dict)
            and isinstance(ui_contract.get("actions"), dict)
            else {}
        )
        raw_rows = actions.get("results")
    if not isinstance(raw_rows, Sequence) or isinstance(raw_rows, (str, bytes)):
        return {}, ()
    target_rows = tuple(
        row
        for row in raw_rows
        if isinstance(row, Mapping) and _safe_int(row.get("action_id")) in SIZE_AVG_ACTION_FOOTPRINT
    )
    if not target_rows:
        return {}, ()
    # Valid foreign sessions are historical and ignored.  A target row without
    # a usable identity is not silently discarded because it may be the current
    # observation whose authority was lost in projection.
    if any(
        not isinstance(row.get("session_id"), str)
        or not row.get("session_id")
        for row in target_rows
    ):
        return {}, ()
    current_rows = tuple(
        row for row in target_rows if row.get("session_id") == current_session
    )
    if not current_rows:
        return {}, ()
    domains = _canonical_map_all_footprint_domains(map_id)
    target_cells = {SIZE_AVG_ACTION_FOOTPRINT[int(row["action_id"])] for row in current_rows}
    if not target_cells.issubset(domains):
        return {}, ()
    raw_physical = snapshot.get("physical_candidate_domains")
    if raw_physical and not physical_candidate_domains:
        return {}, ()
    physical = _shape_average_physical_context(snapshot, session=current_session, map_id=map_id,
        domains=domains, total_count=total_count, physical_domains=physical_candidate_domains)
    if physical is None:
        return {}, ()
    targets, mandatory, resolved_total, physical_cells = physical
    exact_cells: dict[str, int] = {}
    exact_counts: dict[str, int] = {}
    for key in ("q1", "q3", "q4", "q5", "q6"):
        count = fixed_counts.get(key)
        cells = _exact_integer_quality_cell(quality_cells.get(key))
        if type(count) is int and count >= 0:  # noqa: E721
            exact_counts[key] = int(count)
            if count == 0 and cells is None:
                cells = 0
        if key == "q6" and "quality_cells_q6_from_total_grid_residual" in source_notes:
            cells = None
        if cells is not None and cells >= 0:
            exact_cells[key] = int(cells)
    if resolved_total is None and len(exact_counts) == 5:
        resolved_total = sum(exact_counts.values())
    exact_warehouse_total_cells = (
        sum(exact_cells.values()) if len(exact_cells) == 5 else None
    )
    if physical_cells is not None:
        if exact_warehouse_total_cells is not None and exact_warehouse_total_cells != physical_cells:
            return {}, ()
        exact_warehouse_total_cells = physical_cells
    if type(resolved_total) is not int or not 0 < resolved_total <= MEAN_SUPPORT_MAX_COUNT:
        return {}, ()
    complete_quality_inputs = len(exact_counts) == 5 and all(key in exact_cells for key in ("q1", "q3", "q4", "q5"))
    options_by_cells = {}
    for cells in target_cells:
        options = exact_quality_footprint_count_options(
            footprint_cells=cells, exact_quality_counts=exact_counts, exact_quality_cells=exact_cells,
            candidate_domains_by_cells=domains, exact_total_item_count=resolved_total,
            exact_warehouse_total_cells=exact_warehouse_total_cells)
        if options is not None:
            options_by_cells[cells] = options
        elif complete_quality_inputs:
            return {}, ()  # A guarded/conflicting exact input is not an absent constraint.
    exact_joint = len(target_cells) > 1 or bool(mandatory) or len(options_by_cells) != len(target_cells)
    evidence_rows = shape_average_value_evidence_from_action_rows(
        current_rows,
        current_session_id=current_session,
        posterior_targets=targets,
        candidate_domains_by_cells=domains,
        mandatory_units_by_cells=mandatory,
        exact_total_item_count=resolved_total,
        exact_warehouse_total_cells=exact_warehouse_total_cells,
        quality_count_options_by_cells=options_by_cells,
        active_joint=True,
        exact_joint_signatures=exact_joint,
    )
    if not evidence_rows or any(
        row.get("support_complete") is not True
        or row.get("active_status") != "active"
        for row in evidence_rows
    ):
        return {}, ()
    canonical_rows: dict[str, dict[str, Any]] = {}
    floors: dict[str, float] = {}
    # The raw validator has already checked duplicate observations for conflict.
    # A bucket is a single disjoint subset, irrespective of repeated packets.
    buckets = {int(row["footprint_cells"]): row for row in sorted(
        evidence_rows, key=lambda row: row.get("source_sort") or 0)}
    context = None
    if exact_joint:
        context = _join_shape_average_support(tuple(buckets.values()), domains=domains,
            exact_counts=exact_counts, exact_cells=exact_cells, total_count=resolved_total,
            total_cells=exact_warehouse_total_cells, mandatory_units_by_cells=mandatory)
        if context.get("status") != "ok":
            return {}, ()
        floors = {key:float(value) for key,value in context["quality_value_floors"].items() if value > 0}
        subset_floor = int(context["total_value_floor"])
    else:
        subset_floor = sum(int(row["common_facts"]["total_value_floor"]) for row in buckets.values())
    for row in buckets.values():
        evidence_id = row.get("evidence_id")
        if not isinstance(evidence_id, str) or not evidence_id:
            return {}, ()
        public_row = dict(row)
        joint_support = public_row.pop("joint_support", None)
        if not isinstance(joint_support, Sequence) or isinstance(
            joint_support, (str, bytes)
        ):
            return {}, ()
        public_row["joint_support_publication"] = "complete_digest_only"
        public_row["joint_support_sha256"] = hashlib.sha256(
            json.dumps(
                list(joint_support),
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        public_row["combined_total_value_floor"] = subset_floor
        if context is not None:
            public_row["joint_context"] = context
        canonical_rows[evidence_id] = public_row
        constraints = row.get("active_constraints")
        if not isinstance(constraints, Sequence) or isinstance(
            constraints, (str, bytes)
        ):
            return {}, ()
        for constraint in constraints:
            if not isinstance(constraint, Mapping):
                return {}, ()
            key = constraint.get("quality")
            value = constraint.get("value")
            if constraint.get("kind") == "footprint_value_floor":
                continue
            if (
                constraint.get("kind") != "quality_value_floor"
                or key not in (*QUALITY_KEYS, "q2")
                or type(value) is not int  # noqa: E721
                or value <= 0
            ):
                return {}, ()
            if context is None:
                key = "q1" if key == "q2" else str(key)
                floors[key] = floors.get(key, 0.0) + float(value)
    if not floors and subset_floor <= 0:
        return {}, ()
    return floors, tuple(canonical_rows[key] for key in sorted(canonical_rows))


def extract_evidence(snapshot: dict[str, Any]) -> RefEvidence:
    # ``extract_evidence`` is also a public diagnostic boundary.  It must not
    # assume callers already went through ``prepare_reference_engine_snapshot``.
    snapshot, treasure_appraisal_wire_conflict = (
        _quarantine_malformed_treasure_appraisal_rows(snapshot)
    )
    ahmed_q1_q5_current_context_bound = (
        _ahmed_q1_q5_raw_context_binding_decision(snapshot)
    )
    physical_target_ledger = _AISHA_Q5_PHYSICAL_TARGET_LEDGER.get()
    if physical_target_ledger is None:
        physical_target_ledger = _aisha_q5_physical_target_ledger(snapshot)
    snapshot = _aisha_q5_total_cells_fail_closed_snapshot(
        snapshot,
        physical_target_ledger=physical_target_ledger,
    )
    hard_public_avg_value_decision = (
        _hard_public_avg_value_decision(snapshot)
        if _run_env_get(HARD_QUALITY_AVG_VALUE_QUOTE_FLOOR_DISABLE) != "1"
        else _HardPublicAvgValueDecision(False, ())
    )
    total_avg_cells_authority_enabled = (
        _run_env_get(TOTAL_AVG_CELLS_GRID_OPTIONS_DISABLE) != "1"
    )
    total_avg_cells_raw_authority = (
        _total_avg_cells_raw_authority_decision(snapshot)
    )
    raw_ui_contract = dict.get(snapshot, "ui_contract")
    raw_constraints = (
        dict.get(raw_ui_contract, "constraints")
        if type(raw_ui_contract) is dict  # noqa: E721
        else None
    )
    raw_public_info = (
        dict.get(raw_constraints, "public_info")
        if type(raw_constraints) is dict  # noqa: E721
        else None
    )
    total_avg_cells_prepared_authority = (
        _strict_total_avg_cells_prepared_authority(raw_public_info)
        if total_avg_cells_authority_enabled
        and type(raw_public_info) is dict  # noqa: E721
        else _TotalAvgCellsRawAuthority("absent")
    )
    invalid_owned_tiers = _hard_public_avg_value_invalid_exact_tiers(snapshot)
    exact_owned_tiers = _hard_public_avg_value_exact_owned_tiers(snapshot)
    snapshot = _mask_public_info_rows_before_json_projection(
        snapshot,
        invalid_owned_tiers=invalid_owned_tiers,
        exact_owned_tiers=exact_owned_tiers,
    )
    masked_ui_contract = _mask_hard_public_avg_values_before_json_projection(
        _mask_public_avg_values_before_json_projection(
            snapshot,
            raw_ui_contract,
        ),
        invalid_owned_tiers=invalid_owned_tiers,
        exact_owned_tiers=exact_owned_tiers,
    )
    if masked_ui_contract is not raw_ui_contract:
        snapshot = dict.copy(snapshot)
        snapshot["ui_contract"] = masked_ui_contract
    snapshot = _stabilize_public_category_total_value_snapshot(snapshot)
    snapshot = _stabilize_nonofficial_warehouse_source_snapshot(snapshot)
    snapshot = _stabilize_q5_action_row_snapshot(snapshot)
    physical_candidate_domains = _normalized_physical_candidate_domain_rows(
        snapshot
    )
    uc = snapshot.get("ui_contract") if isinstance(snapshot.get("ui_contract"), dict) else {}
    context = uc.get("context") if isinstance(uc.get("context"), dict) else {}
    baseline = uc.get("baseline") if isinstance(uc.get("baseline"), dict) else {}
    decision = baseline.get("decision") if isinstance(baseline.get("decision"), dict) else {}
    posterior = baseline.get("posterior") if isinstance(baseline.get("posterior"), dict) else {}
    constraints = uc.get("constraints") if isinstance(uc.get("constraints"), dict) else {}
    counts = constraints.get("counts") if isinstance(constraints.get("counts"), dict) else {}
    summary = constraints.get("summary") if isinstance(constraints.get("summary"), dict) else {}
    public_info = constraints.get("public_info") if isinstance(constraints.get("public_info"), dict) else {}
    total_avg_cells_authorized = (
        total_avg_cells_authority_enabled
        and total_avg_cells_raw_authority.status == "valid"
        and total_avg_cells_prepared_authority.status == "valid"
        and total_avg_cells_raw_authority.total_count
        == total_avg_cells_prepared_authority.total_count
        and total_avg_cells_raw_authority.total_avg_cells
        == total_avg_cells_prepared_authority.total_avg_cells
    )
    actions = uc.get("actions") if isinstance(uc.get("actions"), dict) else {}
    truth = uc.get("truth") if isinstance(uc.get("truth"), dict) else {}
    source_notes: list[str] = []

    hero = _hero_from_context(
        context.get("hero") or snapshot.get("hero"),
        context.get("hero_id"),
        context.get("player_hero_id"),
        context.get("current_player_hero_id"),
        snapshot.get("hero_id"),
        snapshot.get("player_hero_id"),
        snapshot.get("current_player_hero_id"),
    )
    if _is_unknown_hero(hero):
        for candidate in _candidate_structured_inputs(snapshot, uc, constraints):
            structured_hero = _hero_from_context(candidate.get("hero"))
            if not _is_unknown_hero(structured_hero):
                hero = structured_hero
                source_notes.append("structured_hero")
                break
    if _is_unknown_hero(hero):
        reveal_hero_ids = {
            _safe_int(row.get("hero_id"))
            for row in _iter_skill_reveal_dict_rows(snapshot)
            if _safe_int(row.get("hero_id")) is not None
        }
        if len(reveal_hero_ids) == 1:
            mapped = HERO_BY_ID.get(next(iter(reveal_hero_ids)))
            if mapped:
                hero = mapped
                source_notes.append("skill_reveal_hero_id")
    map_id = _safe_int(context.get("map_id") or snapshot.get("map_id"))
    catalog_map_id = _safe_int(
        context.get("physical_catalog_map_id")
        or context.get("model_map_id")
        or snapshot.get("physical_catalog_map_id")
        or snapshot.get("model_map_id")
        or map_id
    )
    phase = str(context.get("phase") or snapshot.get("phase") or "")
    current_session_raw = context.get("session_id")
    if current_session_raw is None:
        current_session_raw = snapshot.get("session_id")
    current_session = (
        current_session_raw
        if type(current_session_raw) is str and current_session_raw
        else None
    )
    current_round = _safe_int(
        context.get("round")
        or context.get("action_round")
        or snapshot.get("action_round")
        or snapshot.get("round")
    )
    q5_exact_total_action_scoped = (
        normalize_hero_key(hero) == "aisha"
        and phase.strip().lower() == "bidding"
    )
    q5_exact_total_action_status, q5_exact_total_action_value = (
        _select_current_q5_exact_total_action(
            snapshot,
            actions.get("results") or (),
            current_session=current_session,
            current_round=current_round,
        )
        if q5_exact_total_action_scoped
        else ("absent", None)
    )
    fixed_counts: dict[str, int] = {}
    min_counts: dict[str, int] = {}
    count_sums: dict[str, int] = {}
    avg_cells: dict[str, float] = {}
    quality_cells: dict[str, float] = {}
    quality_cell_floors: dict[str, float] = {}
    quality_cell_floor_item_counts: dict[str, int] = {}
    avg_values: dict[str, float] = {}
    quality_values: dict[str, float] = {}
    quality_value_floors: dict[str, float] = {}
    quality_catalog_min_value_floors: dict[str, float] = {}
    quality_min_total_value_floors: dict[str, float] = {}
    quality_value_floor_item_counts: dict[str, int] = {}
    split_counts: dict[str, int] = {}
    split_quality_cells: dict[str, float] = {}
    split_avg_cells: dict[str, float] = {}
    random_value_floors: tuple[tuple[int, int | float], ...] = ()
    public_category_total_value_floor = _public_category_total_value_floor(
        snapshot,
        public_info,
    )
    if public_category_total_value_floor > 0:
        source_notes.append(
            "public_info_200044_category_total_value_floor:"
            f"{int(round(public_category_total_value_floor))}"
        )
    q4_known_item_facts: tuple[tuple[str, int, int], ...] = ()
    q5_known_item_facts: tuple[tuple[str, int, int], ...] = ()
    q6_known_item_facts: tuple[tuple[str, int, int], ...] = ()
    quality_count_cells_options: dict[str, tuple[tuple[int, int], ...]] = {}
    quality_count_cells_value_options: dict[
        str, tuple[tuple[int, int, int], ...]
    ] = {}
    quality_avg_value_intervals: dict[str, tuple[float, float]] = {}
    q6_full_avg_support: dict[str, Any] = {}

    bridge_total_count, bridge_total_cells = _extract_structured_bridge_inputs(
        snapshot,
        uc,
        constraints,
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        count_sums=count_sums,
        avg_cells=avg_cells,
        quality_cells=quality_cells,
        avg_values=avg_values,
        quality_values=quality_values,
        quality_value_floors=quality_value_floors,
        split_counts=split_counts,
        split_quality_cells=split_quality_cells,
        split_avg_cells=split_avg_cells,
        source_notes=source_notes,
        action_results=actions.get("results") or (),
    )
    if q5_exact_total_action_status != "absent":
        source_notes[:] = [
            note
            for note in source_notes
            if note
            not in {
                "structured_ref_bridge_value_sum_q5",
                "field_update_q5_value_sum",
            }
        ]
    if q5_exact_total_action_status == "conflict":
        quality_values.pop("q5", None)
        _append_source_note_once(
            source_notes,
            Q5_EXACT_TOTAL_ACTION_CONFLICT_NOTE,
        )
    elif (
        q5_exact_total_action_status == "selected"
        and q5_exact_total_action_value is not None
    ):
        quality_values["q5"] = q5_exact_total_action_value
        _append_source_note_once(
            source_notes,
            "action_100125_q5_value_sum",
        )
    split_count_exact_keys = {
        key
        for key in LOW_SPLIT_KEYS
        if split_counts.get(key) is not None
        and _aisha_split_count_is_exact(
            key,
            seen_skill_ids=set(),
            source_notes=source_notes,
        )
    }

    total_count = bridge_total_count
    if total_count is None:
        total_count = _safe_int(summary.get("input_total_item_count"))
    if total_count is None:
        total_count = _safe_int(counts.get("input_total_item_count"))
    total_count_conflicted = False

    def set_total_count(value: Any, note: str) -> None:
        nonlocal total_count, total_count_conflicted
        parsed = _safe_int(value)
        if parsed is None:
            return
        if total_count is not None and int(total_count) != int(parsed):
            total_count_conflicted = True
            source_notes.append(f"{note}_conflicts_total_count:{total_count}->{parsed}")
        total_count = int(parsed)
        source_notes.append(note)

    settlement_total_count = _safe_int(truth.get("total_items"))
    if phase == "settled" and settlement_total_count is not None:
        if total_count is not None and int(total_count) != int(settlement_total_count):
            source_notes.append("settlement_review_total_count_overrode_bridge")
        total_count = settlement_total_count
        if "settlement_review_total_count" not in source_notes:
            source_notes.append("settlement_review_total_count")

    total_grid_target = bridge_total_cells
    if total_grid_target is None:
        total_grid_target = _safe_float(summary.get("input_warehouse_total_cells"))
    if total_grid_target is None:
        total_grid_target = _safe_float(counts.get("input_warehouse_total_cells"))
    total_grid_options: tuple[int, ...] = ()
    public_total_avg_cells_values: list[float] = []

    def set_total_grid_target(value: Any, note: str) -> None:
        nonlocal total_grid_target
        parsed = _safe_float(value)
        if parsed is None:
            return
        if (
            total_grid_target is not None
            and abs(float(total_grid_target) - float(parsed)) > 0.0001
        ):
            source_notes.append(f"{note}_conflicts_total_grid:{total_grid_target}->{parsed}")
        total_grid_target = float(parsed)
        source_notes.append(note)

    if total_grid_target is None:
        public_constraints = public_info.get("input_constraints")
        if isinstance(public_constraints, dict):
            set_total_grid_target(
                public_constraints.get("total_cells")
                or public_constraints.get("warehouse_total_cells"),
                "public_total_cells",
            )
    settlement_total_cells = _settlement_review_total_cells(snapshot, truth)
    if phase == "settled" and settlement_total_cells is not None:
        layout_cells = _layout_stage_warehouse_cells_p50(snapshot)
        item_cells = _safe_float(truth.get("total_cells")) or _safe_float(snapshot.get("inventory_cells"))
        complete_truth_cells = _complete_settlement_truth_total_cells(snapshot, truth)
        if (
            layout_cells is not None
            and item_cells is not None
            and float(layout_cells) > float(item_cells) + 0.5
        ):
            if complete_truth_cells is not None:
                source_notes.append("settlement_review_complete_truth_over_layout_replay")
            else:
                source_notes.append("settlement_review_total_grid_from_layout_replay")
        if (
            total_grid_target is not None
            and abs(float(total_grid_target) - float(settlement_total_cells)) > 0.0001
        ):
            source_notes.append("settlement_review_total_grid_overrode_bridge")
        total_grid_target = settlement_total_cells
        if "settlement_review_total_grid" not in source_notes:
            source_notes.append("settlement_review_total_grid")

    known_quality_counts: dict[str, int] = {}
    known_quality_source = ""
    if phase == "settled":
        known_quality_counts.update(_parse_quality_kv(str(snapshot.get("final_quality_counts") or "")))
        known_quality_source = "settlement"
    if not known_quality_counts:
        raw_known = counts.get("known_quality_counts")
        known_quality_source = "constraints"
        if isinstance(raw_known, dict):
            known_quality_counts.update(
                {str(k): int(v) for k, v in raw_known.items() if _safe_int(v) is not None}
            )
    q1_combined = (
        _safe_int(known_quality_counts.get("q1") or 0) or 0
    ) + (_safe_int(known_quality_counts.get("q2") or 0) or 0)
    quality_counts = {
        "q1": q1_combined,
        "q3": _safe_int(known_quality_counts.get("q3")) or 0,
        "q4": _safe_int(known_quality_counts.get("q4")) or 0,
        "q5": _safe_int(known_quality_counts.get("q5")) or 0,
        "q6": _safe_int(known_quality_counts.get("q6")) or 0,
    }
    if phase == "settled":
        known_quality_cells = _parse_quality_kv(str(snapshot.get("final_quality_cells") or ""))
        q1_cells_combined = (
            _safe_int(known_quality_cells.get("q1") or 0) or 0
        ) + (_safe_int(known_quality_cells.get("q2") or 0) or 0)
        for key, value in {
            "q1": q1_cells_combined,
            "q3": _safe_int(known_quality_cells.get("q3")) or 0,
            "q4": _safe_int(known_quality_cells.get("q4")) or 0,
            "q5": _safe_int(known_quality_cells.get("q5")) or 0,
            "q6": _safe_int(known_quality_cells.get("q6")) or 0,
        }.items():
            if value > 0:
                existing_cells = quality_cells.get(key)
                if (
                    existing_cells is not None
                    and abs(float(existing_cells) - float(value)) > 0.0001
                    and "settlement_review_quality_cells_overrode_live" not in source_notes
                ):
                    source_notes.append("settlement_review_quality_cells_overrode_live")
                quality_cells[key] = float(value)
                avg_cells.pop(key, None)

    if known_quality_source == "settlement":
        for key in QUALITY_KEYS:
            fixed_counts.pop(key, None)
            min_counts.pop(key, None)

    for key, value in quality_counts.items():
        if value > 0:
            min_counts.setdefault(key, value)
    if total_count is not None and sum(quality_counts.values()) == total_count:
        fixed_counts.update(
            {
                key: value
                for key, value in quality_counts.items()
                if key not in fixed_counts
            }
        )
        if phase == "settled" or known_quality_source == "settlement":
            source_notes.append("settlement_review_known_quality_counts_sum_to_total")
        else:
            source_notes.append("known_quality_counts_sum_to_total")
    elif phase == "settled" and total_count is not None:
        fixed_counts.update(
            {
                key: value
                for key, value in quality_counts.items()
                if key not in fixed_counts
            }
        )
        source_notes.append("settlement_review_fixed_counts")

    if phase != "settled":
        (
            public_quality_counts,
            public_quality_cell_floors,
            public_quality_value_floors,
            public_quality_catalog_min_value_floors,
            public_quality_value_floor_item_counts,
            coarse_split_counts,
            _coarse_split_value_floors,
            public_quality_cell_floor_item_counts,
        ) = _coarse_quality_reveal_floors(
            snapshot,
            source_notes=source_notes,
            exact_total_count=total_count,
            hard_fixed_counts=fixed_counts,
            hard_quality_cells=quality_cells,
            hard_quality_values=quality_values,
        )
        if public_quality_cell_floor_item_counts:
            for key, value in public_quality_cell_floor_item_counts.items():
                quality_cell_floor_item_counts[key] = max(
                    quality_cell_floor_item_counts.get(key, 0), int(value)
                )
        if public_quality_counts:
            for key, value in public_quality_counts.items():
                min_counts[key] = max(min_counts.get(key, 0), value)
            if "public_quality_reveal_min_counts" not in source_notes:
                source_notes.append("public_quality_reveal_min_counts")
        if coarse_split_counts:
            for key, value in coarse_split_counts.items():
                if not (
                    normalize_hero_key(hero) == "aisha"
                    and key in split_count_exact_keys
                ):
                    split_counts[key] = max(split_counts.get(key, 0), value)
            source_notes.append("coarse_quality_reveal_split_counts")
        if public_quality_cell_floors:
            for key, value in public_quality_cell_floors.items():
                quality_cell_floors[key] = max(
                    quality_cell_floors.get(key, 0.0),
                    float(value),
                )
                source_notes.append(f"public_quality_reveal_{key}_cell_floor")
        if public_quality_value_floors:
            for key, value in public_quality_value_floors.items():
                quality_value_floors[key] = max(
                    quality_value_floors.get(key, 0.0),
                    float(value),
                )
                source_notes.append(f"public_quality_reveal_{key}_value_floor")
        if public_quality_catalog_min_value_floors:
            for key, value in public_quality_catalog_min_value_floors.items():
                quality_catalog_min_value_floors[key] = max(
                    quality_catalog_min_value_floors.get(key, 0.0),
                    float(value),
                )
        if public_quality_value_floor_item_counts:
            for key, value in public_quality_value_floor_item_counts.items():
                quality_value_floor_item_counts[key] = max(
                    quality_value_floor_item_counts.get(key, 0),
                    int(value),
                )
        _apply_maria_skill_evidence(
            snapshot,
            total_count=total_count,
            min_counts=min_counts,
            split_counts=split_counts,
            count_sums=count_sums,
            quality_value_floors=quality_value_floors,
            source_notes=source_notes,
        )
        maria_low_quality_count_status = (
            _apply_maria_complete_low_quality_counts(
                snapshot,
                fixed_counts=fixed_counts,
                min_counts=min_counts,
                split_counts=split_counts,
            )
        )
        if maria_low_quality_count_status == "applied":
            source_notes.append(MARIA_COMPLETE_LOW_QUALITY_COUNT_NOTE)
        maria_low_quality_cells_status = (
            _apply_maria_full_warehouse_low_quality_cells(
                snapshot,
                exact_total_count=total_count,
                fixed_counts=fixed_counts,
                min_counts=min_counts,
                quality_cells=quality_cells,
                split_counts=split_counts,
                split_quality_cells=split_quality_cells,
            )
        )
        if maria_low_quality_cells_status == "applied":
            source_notes.append(MARIA_FULL_WAREHOUSE_LOW_QUALITY_CELLS_NOTE)
        _apply_ethan_skill_evidence(
            snapshot,
            set_total_count=set_total_count,
            set_total_grid_target=set_total_grid_target,
            source_notes=source_notes,
        )
        total_count = _apply_all_item_quality_exact_counts(
            snapshot,
            hero=hero,
            total_count=total_count,
            fixed_counts=fixed_counts,
            min_counts=min_counts,
            quality_cells=quality_cells,
            set_total_count=set_total_count,
            source_notes=source_notes,
        )
        public_outline_totals = _public_bucket_outline_totals(snapshot)
        for key, (count, cells) in public_outline_totals.items():
            existing_count = fixed_counts.get(key)
            if existing_count is not None and int(existing_count) != int(count):
                source_notes.append(f"public_bucket_outline_{key}_count_conflict")
                continue
            fixed_counts[key] = count
            min_counts[key] = max(min_counts.get(key, 0), count)
            source_notes.append(f"public_bucket_outline_{key}_count")
            if cells is None:
                continue
            existing_cells = quality_cells.get(key)
            if existing_cells is not None and abs(float(existing_cells) - float(cells)) > 0.0001:
                source_notes.append(f"public_bucket_outline_{key}_cells_conflict")
                continue
            quality_cells[key] = float(cells)
            source_notes.append(f"public_bucket_outline_{key}_cells")

    for row in actions.get("results") or ():
        if not isinstance(row, dict):
            continue
        action_id = str(row.get("action_id") or "")
        diagnostic_semantic = ACTION_DIAGNOSTIC_ONLY.get(action_id)
        if diagnostic_semantic is not None:
            source_notes.append(f"action_{action_id}_{diagnostic_semantic}_diagnostic_only")
            revealed_count = _safe_int(row.get("revealed_items"))
            if revealed_count is not None and revealed_count > 0:
                source_notes.append(f"action_{action_id}_revealed_items:{revealed_count}")
        value = _safe_float(row.get("result"))
        if value is None:
            continue
        note_suffix = "_inferred_zero" if row.get("inferred_zero") else ""
        quality_for_avg = ACTION_AVG_CELLS.get(action_id)
        quality_for_cells = ACTION_TOTAL_CELLS.get(action_id)
        quality_for_value = ACTION_VALUE_SUM.get(action_id)
        quality_for_count = ACTION_COUNTS.get(action_id)
        if action_id == GREEN_VALUE_SUM_ACTION:
            if value > 0:
                quality_value_floors["q1"] = max(
                    quality_value_floors.get("q1", 0.0), value
                )
            else:
                split_counts["green"] = 0
                split_count_exact_keys.add("green")
                source_notes.append(f"action_{action_id}_green_count_inferred_zero")
            source_notes.append(f"action_{action_id}_green_value_floor{note_suffix}")
        elif action_id == GREEN_COUNT_ACTION:
            split_counts["green"] = int(round(value))
            split_count_exact_keys.add("green")
            source_notes.append(f"action_{action_id}_green_count{note_suffix}")
        elif quality_for_avg is not None:
            avg_cells[quality_for_avg] = value
            source_notes.append(f"action_{action_id}_{quality_for_avg}_avg_cells{note_suffix}")
        elif quality_for_cells is not None:
            quality_cells[quality_for_cells] = value
            source_notes.append(f"action_{action_id}_{quality_for_cells}_cells{note_suffix}")
        elif (
            quality_for_value == "q5"
            and q5_exact_total_action_scoped
        ):
            continue
        elif quality_for_value is not None:
            quality_values[quality_for_value] = value
            source_notes.append(f"action_{action_id}_{quality_for_value}_value_sum{note_suffix}")
        elif quality_for_count is not None:
            fixed_counts[quality_for_count] = int(round(value))
            min_counts[quality_for_count] = int(round(value))
            source_notes.append(f"action_{action_id}_{quality_for_count}_count{note_suffix}")
        elif action_id in {"100115", "100204"}:
            set_total_count(value, f"action_{action_id}_total_count")
        elif action_id == "100103":
            set_total_grid_target(value, "action_100103_total_cells")

    scoped_public_avg_cell_semantics = (
        normalize_hero_key(hero) == "aisha"
        and str(phase or "").strip().lower() == "bidding"
    )
    projected_public_avg_cell_rows = (
        _project_public_avg_cell_rows(public_info)
        if scoped_public_avg_cell_semantics
        else {}
    )
    conflicting_public_avg_cell_semantics = (
        _conflicting_public_avg_cell_semantics(
            projected_public_avg_cell_rows,
            include_distinct_values=(
                _run_env_get(AISHA_PUBLIC_AVG_SEMANTIC_CONFLICT_DISABLE) != "1"
            ),
        )
        if scoped_public_avg_cell_semantics
        else frozenset()
    )
    for semantic in sorted(conflicting_public_avg_cell_semantics):
        _append_source_note_once(
            source_notes,
            (
                f"{AISHA_PUBLIC_AVG_SEMANTIC_CONFLICT_NOTE_PREFIX}:"
                f"{PUBLIC_AVG_CELLS[semantic]}"
            ),
        )

    for row in public_info.get("public_numeric_facts") or ():
        if not isinstance(row, dict):
            continue
        projected_avg_cell = projected_public_avg_cell_rows.get(id(row))
        if projected_avg_cell is not None:
            semantic, valid, value = projected_avg_cell
            if not valid or value is None:
                continue
        else:
            semantic = str(row.get("semantic") or "")
            value = _safe_float(row.get("value"))
            if value is None:
                continue
        if semantic == "total_item_count":
            set_total_count(value, "public_total_item_count")
        elif semantic == "total_cells":
            set_total_grid_target(value, "public_total_cells")
        elif semantic == "total_avg_cells":
            # Keep the all-items mean outside the per-quality namespace.  Its hard-count
            # arithmetic is finalized after every public row has been parsed, so row order
            # cannot decide whether total_count is visible yet.
            if _run_env_get(TOTAL_AVG_CELLS_GRID_OPTIONS_DISABLE) == "1":
                if value and value > 0:
                    avg_cells["total"] = float(value)
                if total_count is not None:
                    implied = float(value) * float(total_count)
                    if abs(implied - round(implied)) <= 0.25:
                        set_total_grid_target(implied, "public_total_cells")
                    else:
                        set_total_grid_target(
                            implied,
                            "public_total_avg_cells_target",
                        )
                else:
                    source_notes.append(
                        "public_total_avg_cells_count_constraint"
                    )
            elif not total_avg_cells_authorized:
                continue
            elif value is None or not math.isfinite(float(value)) or value <= 0:
                continue
            else:
                avg_cells["total"] = float(value)
                if not any(
                    abs(float(existing) - float(value)) <= 0.0001
                    for existing in public_total_avg_cells_values
                ):
                    public_total_avg_cells_values.append(float(value))
        elif semantic == "total_avg_value":
            source_notes.append("public_total_avg_value_diagnostic_only")
        elif semantic in PUBLIC_AVG_CELLS:
            if semantic in conflicting_public_avg_cell_semantics:
                continue
            avg_cells[PUBLIC_AVG_CELLS[semantic]] = value
            source_notes.append(f"public_{PUBLIC_AVG_CELLS[semantic]}_avg_cells")
        elif semantic in PUBLIC_COUNTS:
            key = PUBLIC_COUNTS[semantic]
            fixed_counts[key] = int(round(value))
            min_counts[key] = int(round(value))
            source_notes.append(f"public_{key}_count")

    if len(public_total_avg_cells_values) > 1:
        avg_cells.pop("total", None)
        _append_source_note_once(
            source_notes,
            (
                f"{TOTAL_AVG_CELLS_GRID_OPTIONS_NOTE}:conflict:avg_values="
                + ",".join(
                    f"{value:g}" for value in sorted(public_total_avg_cells_values)
                )
            ),
        )
    elif public_total_avg_cells_values:
        public_total_avg_cells_value = public_total_avg_cells_values[0]
        explicit_total_count = (
            total_count is not None
            and (
                _has_explicit_total_count_source(tuple(source_notes))
                or "public_total_item_count" in source_notes
            )
        )
        if total_count is None:
            _append_source_note_once(
                source_notes,
                "public_total_avg_cells_count_constraint",
            )
        elif str(phase or "").strip().lower() == "settled":
            _append_source_note_once(
                source_notes,
                f"{TOTAL_AVG_CELLS_GRID_OPTIONS_NOTE}:settled_no_injection",
            )
        elif (
            total_count_conflicted
            or total_avg_cells_raw_authority.total_count is None
            or int(total_count)
            != int(total_avg_cells_raw_authority.total_count)
        ):
            _append_source_note_once(
                source_notes,
                f"{TOTAL_AVG_CELLS_GRID_OPTIONS_NOTE}:conflict:total_count",
            )
        elif explicit_total_count:
            options = _public_total_avg_cells_grid_options(
                int(total_count),
                public_total_avg_cells_value,
            )
            existing_hard_total = _hard_total_grid_target_from_notes(
                total_grid_target,
                source_notes,
            )
            if existing_hard_total is not None:
                if existing_hard_total in options:
                    total_grid_options = (existing_hard_total,)
                    _append_source_note_once(
                        source_notes,
                        (
                            f"{TOTAL_AVG_CELLS_GRID_OPTIONS_NOTE}:"
                            f"consistent:{existing_hard_total}"
                        ),
                    )
                else:
                    _append_source_note_once(
                        source_notes,
                        (
                            f"{TOTAL_AVG_CELLS_GRID_OPTIONS_NOTE}:conflict:"
                            f"target={existing_hard_total}:options="
                            + ",".join(str(option) for option in options)
                        ),
                    )
            elif len(options) == 1:
                total_grid_options = options
                set_total_grid_target(options[0], "public_total_cells")
                _append_source_note_once(
                    source_notes,
                    f"{TOTAL_AVG_CELLS_GRID_OPTIONS_NOTE}:unique:{options[0]}",
                )
            elif len(options) > 1:
                total_grid_options = options
                # The options are a hard disjunction.  Keeping their arithmetic
                # midpoint as a scalar target would let downstream code collapse
                # them back to one arm before enumeration.
                total_grid_target = None
                _append_source_note_once(
                    source_notes,
                    (
                        f"{TOTAL_AVG_CELLS_GRID_OPTIONS_NOTE}:multi:"
                        + ",".join(str(option) for option in options)
                    ),
                )
            else:
                _append_source_note_once(
                    source_notes,
                    f"{TOTAL_AVG_CELLS_GRID_OPTIONS_NOTE}:unreachable",
                )

    # Ahmed's numeric hero skills travel in ``skill_reveals`` rather than
    # ``ui_contract.actions.results``. Their values already reach the structured
    # bridge, but without source provenance a same-tier public average downgrades
    # the exact skill reading to a soft prior below. Only harden matching rows;
    # conflicting duplicate/stale rows fail open.
    for row in _iter_skill_reveal_dict_rows(snapshot):
        skill_id = str(row.get("skill_id") or "")
        key = ACTION_AVG_CELLS.get(skill_id)
        value = _safe_float(row.get("result"))
        if key is None or value is None:
            continue
        existing = _safe_float(avg_cells.get(key))
        if existing is not None and abs(float(existing) - float(value)) > 0.0001:
            _append_source_note_once(
                source_notes,
                f"skill_{skill_id}_{key}_avg_cells_conflict",
            )
            continue
        if existing is None:
            avg_cells[key] = float(value)
        _append_source_note_once(
            source_notes,
            f"skill_{skill_id}_{key}_avg_cells",
        )

    hard_public_avg_values = dict(hard_public_avg_value_decision.values)

    q6_full_avg_feature_enabled = bool(
        _run_env_get(Q6_FULL_AVG_MULTISET_DISABLE) != "1"
        and _catalog_value_joint_projection_enabled("q6")
    )
    q6_full_avg_evidence = (
        _strict_q6_full_avg_evidence(
            public_info,
            current_session=current_session,
        )
        if q6_full_avg_feature_enabled
        else None
    )
    q6_full_avg_claimed = bool(
        q6_full_avg_feature_enabled
        and q6_full_avg_evidence is not None
        and getattr(q6_full_avg_evidence, "status", None) != "not_applicable"
    )
    # Settlement rows are review truth, not bidding evidence.  Still claim a
    # targeted 200038 row so the legacy q6-average path cannot consume it, but
    # do not publish a SAV3 equation/support or let it alter settled inference.
    q6_full_avg_enabled = bool(
        q6_full_avg_feature_enabled
        and str(phase or "").strip().lower() != "settled"
    )
    for key, value in _public_quality_avg_values(public_info).items():
        if key == "q6" and q6_full_avg_claimed:
            continue
        normalized = _ref_normalize_avg_value_wire(value)
        if normalized is None:
            continue
        avg_values[key] = float(normalized)
        source_notes.append(f"public_{key}_avg_value")
        if abs(float(normalized) - float(value)) > 1e-9:
            source_notes.append(f"public_{key}_avg_value_wire_normalized")
    if (
        q6_full_avg_enabled
        and q6_full_avg_claimed
        and q6_full_avg_evidence is not None
    ):
        q6_full_avg_status = str(
            getattr(q6_full_avg_evidence, "status", "unavailable") or "unavailable"
        )
        if q6_full_avg_status != "not_applicable":
            _append_source_note_once(
                source_notes,
                f"{Q6_FULL_AVG_EVIDENCE_NOTE}:{q6_full_avg_status}",
            )
            q6_full_avg_support = {
                "status": q6_full_avg_status,
                "conflicts": list(
                    getattr(q6_full_avg_evidence, "conflicts", ()) or ()
                ),
                "joint_states": [],
            }
        if q6_full_avg_status == "ok":
            raw_value = _safe_float(getattr(q6_full_avg_evidence, "raw_value", None))
            interval = getattr(q6_full_avg_evidence, "avg_interval", None)
            if (
                raw_value is not None
                and raw_value > 0
                and isinstance(interval, tuple)
                and len(interval) == 2
            ):
                avg_values["q6"] = float(raw_value)
                quality_avg_value_intervals["q6"] = (
                    float(interval[0]),
                    float(interval[1]),
                )
                min_counts["q6"] = max(int(min_counts.get("q6", 0) or 0), 1)
                _append_source_note_once(source_notes, "public_q6_avg_value")

    # A positive public tier mean proves that the tier exists even when its approximate value cannot
    # coexist with the other hard evidence. The no-combo retry removes the conflicting mean, but marks
    # the affected tier here so the weaker presence fact survives that downgrade.
    for key in _public_avg_value_presence_fallback_keys(snapshot):
        min_counts[key] = max(int(min_counts.get(key, 0) or 0), 1)
        _append_source_note_once(
            source_notes,
            f"public_{key}_avg_value_presence_fallback",
        )

    _apply_exact_catalog_value_locks(
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        avg_values=avg_values,
        quality_values=quality_values,
        source_notes=source_notes,
    )

    if phase != "settled":
        random_value_floors = _public_random_value_floors(public_info)
        for sample_count, value_floor in random_value_floors:
            source_notes.append(
                f"public_random_avg_value_floor_{sample_count}:{int(round(value_floor))}"
            )
        # Red anchor. A high random per-item avg is caused, with near-certainty, by a red item in
        # the draw that carries ~97-99% of the draw value (Monte-Carlo, 956k draws). So we bind the
        # implied value to RED rather than flat-clamping the total: anchor >=1 red whose value
        # floor is ~the draw total (N*avg). The count prior then adds the warehouse's other reds
        # (3-4 typical) on top, so the estimate floats above the floor with spread instead of
        # hugging it. value_floor = N*avg, avg = value_floor / sample_count.
        max_random_avg = max(
            (value_floor / sample_count for sample_count, value_floor in random_value_floors if sample_count > 0),
            default=0.0,
        )
        # tightest implied draw total = the largest N*avg seen (this is the jackpot red's value).
        red_value_floor = max((value_floor for _sc, value_floor in random_value_floors), default=0.0)
        # This anchor is a COUNT/value-hero mechanism (aisha/ahmed): it floors q6 value at 0.95*N*avg on
        # the premise N*avg <= vault total (~1 jackpot red carries the draw). Ethan is CELL-centric — red
        # value comes from red CELLS x per-cell price (red residual chain), not a value floor — so the
        # anchor conflicts with ethan's valuation and, when the random-check avg reflects the item's
        # CATALOG/tier value rather than a poor vault's cheap instance value, over-reaches badly:
        # ethan 5605 (villa/56xx poor vault) 9*120k=1.08M floored onto a 239k vault -> +332% over-bid;
        # disabling it there lands +6% (253,744 vs truth 239,291). Measured across ethan/aisha/ahmed
        # clean_eval (480 decision rounds) it fires only twice: ethan 5605 (floor/total 4.30, catastrophic)
        # and ahmed 2401 (floor/total 0.46, rich vault, working) — and never on any ethan 3+red vault, so
        # ethan gets zero benefit and one catastrophe. Hence default-OFF for ethan (force-on for A/B via
        # ETHAN_ENABLE_RANDOM_AVG_RED_ANCHOR=1), ON for other heroes. Global kill: BIDKING_DISABLE_...=1.
        _anchor_ethan_off = (
            normalize_hero_key(hero) == "ethan"
            and os.environ.get("ETHAN_ENABLE_RANDOM_AVG_RED_ANCHOR") != "1"
        )
        if (
            os.environ.get("BIDKING_DISABLE_RANDOM_AVG_RED_ANCHOR") != "1"
            and not _anchor_ethan_off
            and max_random_avg >= RANDOM_AVG_RED_ANCHOR_THRESHOLD
            and int(fixed_counts.get("q6", 1) or 0) >= 1
        ):
            if int(min_counts.get("q6", 0) or 0) < 1:
                min_counts["q6"] = 1
            # 0.95x of the draw total. The drawn red(s) carry ~0.97-0.99 of the draw value
            # (Monte-Carlo), so 0.95x is a safe lower bound on the drawn red value; the warehouse's
            # OTHER reds/items (3-4 reds total vs ~1 drawn) are computed on top, so the total floats
            # above the hard floor V (=N*avg <= truth) with spread instead of hugging it.
            # round() keeps it a whole value -- never surface a fractional figure to the UI.
            anchored_red_value = float(round(0.95 * red_value_floor))
            if anchored_red_value > quality_value_floors.get("q6", 0.0):
                quality_value_floors["q6"] = anchored_red_value
                quality_value_floor_item_counts["q6"] = max(
                    1, int(quality_value_floor_item_counts.get("q6", 0) or 0)
                )
                source_notes.append(
                    f"random_avg_red_anchor_q6_value_floor:{int(round(anchored_red_value))}"
                )

    if phase == "settled":
        _apply_settlement_quality_truth(
            snapshot,
            fixed_counts=fixed_counts,
            min_counts=min_counts,
            avg_cells=avg_cells,
            quality_cells=quality_cells,
            split_counts=split_counts,
            split_quality_cells=split_quality_cells,
            split_avg_cells=split_avg_cells,
            source_notes=source_notes,
        )

    _apply_avg_value_cells_exact_count_intersection(
        total_count=total_count,
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        avg_cells=avg_cells,
        avg_values=avg_values,
        quality_cells=quality_cells,
        quality_values=quality_values,
        split_counts=split_counts,
        source_notes=source_notes,
    )
    if not _catalog_value_joint_projection_enabled("q5"):
        _apply_avg_value_only_q5_count_derivation(
            total_count=total_count,
            fixed_counts=fixed_counts,
            min_counts=min_counts,
            count_sums=count_sums,
            avg_values=avg_values,
            avg_cells=avg_cells,
            quality_cells=quality_cells,
            source_notes=source_notes,
        )
    _apply_exact_count_residuals(
        total_count=total_count,
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        count_sums=count_sums,
        avg_values=avg_values,
        quality_values=quality_values,
        quality_cells=quality_cells,
        split_counts=split_counts,
        source_notes=source_notes,
    )
    _apply_quality_cells_total_grid_residual(
        total_grid_target=total_grid_target,
        fixed_counts=fixed_counts,
        avg_cells=avg_cells,
        quality_cells=quality_cells,
        source_notes=source_notes,
    )

    if normalize_hero_key(hero) == "aisha":
        seen_aisha_skill_ids = {
            sid
            for row in _iter_skill_reveal_dict_rows(snapshot)
            if _safe_int(row.get("hero_id")) == _AISHA_HERO_ID
            and (sid := _safe_int(row.get("skill_id"))) is not None
        }
        for split_key in LOW_SPLIT_KEYS:
            if split_counts.get(split_key) is not None and _aisha_split_count_is_exact(
                split_key,
                seen_skill_ids=seen_aisha_skill_ids,
                source_notes=source_notes,
            ):
                split_count_exact_keys.add(split_key)

    post_split_total_grid_residual_enabled = (
        normalize_hero_key(hero) == "aisha"
        and phase.strip().lower() == "bidding"
        and _run_env_get(AISHA_POST_SPLIT_TOTAL_GRID_RESIDUAL_DISABLE) != "1"
    )
    q1_cells_before_split = quality_cells.get("q1")
    _apply_aisha_absent_low_quality_zero(
        snapshot,
        hero,
        split_counts=split_counts,
        split_count_exact_keys=split_count_exact_keys,
        split_quality_cells=split_quality_cells,
        infer_zero_cells=post_split_total_grid_residual_enabled,
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        source_notes=source_notes,
    )
    _apply_low_quality_split_evidence(
        total_count=total_count,
        split_counts=split_counts,
        split_count_exact_keys=split_count_exact_keys,
        split_quality_cells=split_quality_cells,
        split_avg_cells=split_avg_cells,
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        avg_cells=avg_cells,
        quality_cells=quality_cells,
        source_notes=source_notes,
    )
    q1_cells_closed_from_split = (
        post_split_total_grid_residual_enabled
        and q1_cells_before_split is None
        and quality_cells.get("q1") is not None
        and all(split_quality_cells.get(key) is not None for key in LOW_SPLIT_KEYS)
        and not any(
            note.startswith("hard_conflict:split_low_quality")
            for note in source_notes
        )
    )
    if quality_value_floors.get("q1", 0.0) > 0 and split_counts.get("green") is not None:
        quality_value_floor_item_counts["q1"] = max(
            quality_value_floor_item_counts.get("q1", 0),
            int(split_counts["green"]),
        )

    _apply_public_info_exact_numeric_rows(
        snapshot,
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        quality_cells=quality_cells,
        set_total_count=set_total_count,
        set_total_grid_target=set_total_grid_target,
        source_notes=source_notes,
    )
    public_info_conflict = any(
        note.startswith("public_") and "conflict" in note
        for note in source_notes
    )
    if q1_cells_closed_from_split and not public_info_conflict:
        quality_cells_before_residual = dict(quality_cells)
        _apply_quality_cells_total_grid_residual(
            total_grid_target=total_grid_target,
            fixed_counts=fixed_counts,
            avg_cells=avg_cells,
            quality_cells=quality_cells,
            source_notes=source_notes,
        )
        if quality_cells != quality_cells_before_residual:
            _append_source_note_once(
                source_notes,
                AISHA_POST_SPLIT_TOTAL_GRID_RESIDUAL_NOTE,
            )

    # BUG-M (2026-07-11, 群友 #12 aisha 5609: "他不算至宝估价的"): 至宝估价 (100163/100162) discloses the
    # TOP item's VALUE only — no quality, no outline, just a rough anchor point. The engine read the row
    # solely to derive a max-QUALITY ceiling, and that path needs `quality`, which this tool never sends
    # (observed: value=458000, local_index=34, quality=None) -> the price was dropped entirely. But a
    # collectible's price is near-unique in the catalog (585 distinct values, 84% belong to exactly one
    # item), so the price IDENTIFIES the item — 作者: "基本等同于抽检出了这个藏品". 458,000 -> 1916003 =
    # RED, 3x2 = 6 cells. Wire it as a full reveal of ONE item of that tier: min_count >= 1, cell floor
    # >= its footprint, value floor >= its price. Ambiguous prices (16% share a value) only contribute
    # when every candidate agrees on the tier. Kill: BIDKING_DISABLE_TREASURE_APPRAISAL=1.
    treasure_appraisal_status, selected_treasure_appraisal = (
        (TREASURE_APPRAISAL_CONTEXT_STATUS_CONFLICT, None)
        if treasure_appraisal_wire_conflict
        else _strict_treasure_appraisal_evidence(
            snapshot,
            hero=hero,
            phase=phase,
            map_id=map_id,
            current_session=current_session,
            current_round=current_round,
        )
    )
    treasure_appraisal = (
        selected_treasure_appraisal
        if os.environ.get("BIDKING_DISABLE_TREASURE_APPRAISAL") != "1"
        else None
    )
    quarantined_treasure_action_row_ids = (
        _treasure_appraisal_target_action_row_ids(snapshot)
        if treasure_appraisal_status == TREASURE_APPRAISAL_CONTEXT_STATUS_CONFLICT
        else frozenset()
    )
    if (
        treasure_appraisal_status == TREASURE_APPRAISAL_CONTEXT_STATUS_OK
        and treasure_appraisal is not None
    ):
        key, cells, value = treasure_appraisal
        min_counts[key] = max(min_counts.get(key, 0), 1)
        quality_cell_floors[key] = max(
            float(quality_cell_floors.get(key, 0.0)), float(cells)
        )
        quality_cell_floor_item_counts[key] = max(
            int(quality_cell_floor_item_counts.get(key, 0)), 1
        )
        quality_value_floors[key] = max(
            float(quality_value_floors.get(key, 0.0)), float(value)
        )
        quality_value_floor_item_counts[key] = max(
            int(quality_value_floor_item_counts.get(key, 0)), 1
        )
        source_notes.append(
            f"{TREASURE_APPRAISAL_NOTE}:{key}:{int(value)}:{cells}cells"
        )

    q4_known_item_facts = _correlated_q4_known_item_facts(
        snapshot,
        quarantined_action_row_ids=quarantined_treasure_action_row_ids,
    )
    if q4_known_item_facts:
        source_notes.append(
            f"{Q4_EXACT_VALUE_CELLS_NOTE}:known_items:{len(q4_known_item_facts)}"
        )
    q5_known_item_facts = _correlated_q5_known_item_facts(
        snapshot,
        quarantined_action_row_ids=quarantined_treasure_action_row_ids,
    )
    if q5_known_item_facts:
        source_notes.append(
            f"{Q5_EXACT_VALUE_CELLS_NOTE}:known_items:{len(q5_known_item_facts)}"
        )
    q6_known_item_facts = _correlated_q6_known_item_facts(
        snapshot,
        quarantined_action_row_ids=quarantined_treasure_action_row_ids,
    )
    ivan_shape_avg_red_facts = _ivan_full_outline_shape_avg_unique_red_facts(
        snapshot,
        hero=hero,
        phase=phase,
        current_session=current_session,
    )
    if ivan_shape_avg_red_facts:
        merged_q6_facts = {
            identity: (cells, value)
            for identity, cells, value in q6_known_item_facts
        }
        added = 0
        for identity, cells, value in ivan_shape_avg_red_facts:
            existing = merged_q6_facts.get(identity)
            if existing is not None and existing != (cells, value):
                continue
            if existing is None:
                added += 1
            merged_q6_facts[identity] = (cells, value)
        if added:
            q6_known_item_facts = tuple(
                sorted(
                    (identity, cells, value)
                    for identity, (cells, value) in merged_q6_facts.items()
                )
            )
            known_count = len(q6_known_item_facts)
            known_cells = sum(cells for _identity, cells, _value in q6_known_item_facts)
            known_value = sum(value for _identity, _cells, value in q6_known_item_facts)
            min_counts["q6"] = max(int(min_counts.get("q6", 0) or 0), known_count)
            quality_cell_floors["q6"] = max(
                float(quality_cell_floors.get("q6", 0.0)), float(known_cells)
            )
            quality_cell_floor_item_counts["q6"] = max(
                int(quality_cell_floor_item_counts.get("q6", 0) or 0), known_count
            )
            quality_value_floors["q6"] = max(
                float(quality_value_floors.get("q6", 0.0)), float(known_value)
            )
            quality_value_floor_item_counts["q6"] = max(
                int(quality_value_floor_item_counts.get("q6", 0) or 0), known_count
            )
            _append_source_note_once(
                source_notes,
                f"{IVAN_FULL_OUTLINE_SHAPE_AVG_RED_IDENTITY_NOTE}:known_items:{added}",
            )

    q5_projection_status = _apply_q5_catalog_projection(
        map_id=catalog_map_id,
        total_count=total_count,
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        count_sums=count_sums,
        avg_cells=avg_cells,
        avg_values=avg_values,
        quality_cells=quality_cells,
        quality_values=quality_values,
        quality_count_cells_options=quality_count_cells_options,
        source_notes=source_notes,
        known_facts=q5_known_item_facts,
    )

    if (
        q6_full_avg_enabled
        and q6_full_avg_evidence is not None
        and getattr(q6_full_avg_evidence, "status", None) == "ok"
    ):
        (
            q6_projection_status,
            q6_full_avg_promoted_facts,
            q6_full_avg_support,
        ) = _apply_q6_full_avg_multiset_support(
            mean_evidence=q6_full_avg_evidence,
            map_id=catalog_map_id,
            total_count=total_count,
            fixed_counts=fixed_counts,
            min_counts=min_counts,
            count_sums=count_sums,
            avg_cells=avg_cells,
            quality_cells=quality_cells,
            quality_cell_floors=quality_cell_floors,
            quality_min_total_value_floors=quality_min_total_value_floors,
            quality_values=quality_values,
            quality_count_cells_options=quality_count_cells_options,
            quality_count_cells_value_options=quality_count_cells_value_options,
            source_notes=source_notes,
            known_facts=q6_known_item_facts,
            physical_candidate_domains=physical_candidate_domains,
        )
        if q6_full_avg_promoted_facts:
            q6_known_item_facts = tuple(
                dict.fromkeys((*q6_known_item_facts, *q6_full_avg_promoted_facts))
            )
        _append_source_note_once(
            source_notes,
            f"{Q6_FULL_AVG_SUPPORT_NOTE}:{q6_projection_status}:"
            f"{len(quality_count_cells_value_options.get('q6', ()))}",
        )
    else:
        q6_projection_status = _apply_q6_catalog_projection(
            map_id=catalog_map_id,
            total_count=total_count,
            fixed_counts=fixed_counts,
            min_counts=min_counts,
            count_sums=count_sums,
            avg_cells=avg_cells,
            avg_values=avg_values,
            quality_cells=quality_cells,
            quality_values=quality_values,
            quality_count_cells_options=quality_count_cells_options,
            source_notes=source_notes,
            known_facts=q6_known_item_facts,
        )

    q4_projection_status = _apply_q4_catalog_projection(
        map_id=catalog_map_id,
        total_count=total_count,
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        count_sums=count_sums,
        avg_cells=avg_cells,
        avg_values=avg_values,
        quality_cells=quality_cells,
        quality_values=quality_values,
        quality_count_cells_options=quality_count_cells_options,
        source_notes=source_notes,
        known_facts=q4_known_item_facts,
    )

    # q5 is handled by its unified projection. q4 uses its exact projection whenever at least two
    # independent quality signals apply; its named rollback restores this legacy coarse gate.
    if total_count is not None:
        # only a TOOL-sourced avg is hard enough to lock on (a public avg is a soft prior — BUG-I)
        _tool_avg_keys_u = {
            m.group(1)
            for note in source_notes
            if (m := re.fullmatch(r"action_\d+_(q[1-6])_avg_cells(?:_.*)?", str(note))) is not None
        }
        for key in ("q4", "q6"):
            projection_status = {
                "q4": q4_projection_status,
                "q6": q6_projection_status,
            }[key]
            if projection_status not in {"disabled", "not_applicable"}:
                continue
            if key in fixed_counts or key not in _tool_avg_keys_u:
                continue
            avg_for_key = _safe_float(avg_cells.get(key))
            value_for_key = _safe_float(quality_values.get(key))
            if not avg_for_key or not value_for_key or avg_for_key <= 0 or value_for_key <= 0:
                continue
            committed = 0
            for other in QUALITY_KEYS:
                if other == key:
                    continue
                fixed_other = fixed_counts.get(other)
                committed += (
                    max(0, int(fixed_other))
                    if fixed_other is not None
                    else max(0, int(min_counts.get(other, 0) or 0))
                )
            ceiling = max(0, int(total_count) - committed)
            unique = _unique_count_from_avg_and_total_value(
                key, float(avg_for_key), float(value_for_key), ceiling
            )
            if unique is None:
                continue
            fixed_counts[key] = unique
            min_counts[key] = max(min_counts.get(key, 0), unique)
            cells_for_key = _avg_grid_options(unique, float(avg_for_key), key)
            if len(cells_for_key) == 1 and key not in quality_cells:
                quality_cells[key] = float(cells_for_key[0])
            source_notes.append(f"{UNIQUE_COUNT_TWO_SIGNAL_NOTE}:{key}:{unique}")

    for key, avg in tuple(avg_cells.items()):
        if avg == 0 and key not in fixed_counts:
            fixed_counts[key] = 0
            min_counts[key] = 0
            source_notes.append(f"zero_avg_cells_{key}_count_zero")

    for key, avg in tuple(avg_values.items()):
        avg_fraction = _avg_value_fraction(avg)
        if avg_fraction == 0 and key not in fixed_counts:
            fixed_counts[key] = 0
            min_counts[key] = 0
            source_notes.append(f"zero_avg_value_{key}_count_zero")

    for key, cells in tuple(quality_cells.items()):
        if key in fixed_counts:
            continue
        parsed_cells = _safe_float(cells)
        if parsed_cells is not None and abs(parsed_cells) <= 0.0001:
            fixed_counts[key] = 0
            min_counts[key] = 0
            source_notes.append(f"zero_quality_cells_{key}_count_zero")

    for key, count in fixed_counts.items():
        if int(count) == 0 and key not in quality_cells:
            quality_cells[key] = 0.0

    for key, value in tuple(quality_values.items()):
        if key in avg_values:
            continue
        count = fixed_counts.get(key)
        parsed_value = _safe_float(value)
        if count is None or parsed_value is None or parsed_value < 0:
            continue
        count_int = int(count)
        if count_int > 0:
            avg_values[key] = float(parsed_value) / float(count_int)
            source_notes.append(f"quality_value_{key}_avg_value_derived")
        elif abs(parsed_value) <= 0.0001:
            avg_values[key] = 0.0
            source_notes.append(f"quality_value_{key}_avg_value_derived")

    for key, avg in tuple(avg_values.items()):
        quality_value = quality_values.get(key)
        fixed_count = fixed_counts.get(key)
        if fixed_count is not None:
            if not _quality_count_matches_value_inputs(
                int(fixed_count),
                avg,
                _safe_float(quality_value),
            ):
                source_notes.append(f"quality_value_{key}_avg_count_conflict")
            continue
        if quality_value is None:
            continue
        projection_status = {
            "q4": q4_projection_status,
            "q5": q5_projection_status,
            "q6": q6_projection_status,
        }.get(key)
        if (
            key in {"q4", "q5", "q6"}
            and _catalog_value_joint_projection_enabled(key)
        ):
            # The joint projector has already tested this avg/total pair against every reachable
            # repeat-allowed catalog state.  An empty, ambiguous or unavailable projection must not
            # be overwritten by the legacy arithmetic quotient below.
            _append_source_note_once(
                source_notes,
                f"quality_value_{key}_avg_joint_projection:{projection_status}",
            )
            continue
        derived_count = _avg_value_count_from_total(avg, quality_value)
        derived_via_tolerance = False
        if derived_count is None:
            derived_count = _avg_value_count_from_total_with_tolerance(
                avg,
                quality_value,
                total_count=total_count,
            )
            derived_via_tolerance = derived_count is not None
        if derived_count is None:
            source_notes.append(f"quality_value_{key}_avg_value_conflict")
            continue
        fixed_counts[key] = derived_count
        min_counts[key] = derived_count
        if derived_via_tolerance:
            source_notes.append(f"quality_value_{key}_count_derived_product_tolerance")
        else:
            source_notes.append(f"quality_value_{key}_count_derived")

    for key, cells in quality_cells.items():
        if key in avg_cells:
            continue
        count = fixed_counts.get(key)
        if count is not None and count > 0 and cells >= 0:
            avg_cells[key] = float(cells) / float(count)
            source_notes.append(f"quality_cells_{key}_avg_derived")

    for key, avg in tuple(avg_cells.items()):
        if key in fixed_counts or avg is None:
            continue
        cells = quality_cells.get(key)
        derived_count = _avg_count_from_cells(avg, cells, key)
        if derived_count is None:
            continue
        fixed_counts[key] = derived_count
        min_counts[key] = derived_count
        source_notes.append(f"quality_cells_{key}_count_derived")

    for key, avg in tuple(avg_cells.items()):
        cells = quality_cells.get(key)
        if cells is None:
            continue
        cells_int = int(round(float(cells)))
        fixed_count = fixed_counts.get(key)
        if fixed_count is not None:
            if not _avg_matches_exact_grid(int(fixed_count), avg, cells_int):
                source_notes.append(f"quality_cells_{key}_avg_count_conflict")
        elif _avg_count_from_cells(avg, cells, key) is None:
            source_notes.append(f"quality_cells_{key}_avg_cells_conflict")

    pre_layout_soft_avg_cell_keys = _derive_soft_public_avg_cell_keys(
        source_notes=source_notes,
        fixed_counts=fixed_counts,
        quality_cells=quality_cells,
    )
    _apply_aisha_derived_q5_cells_from_exact_count_avg(
        hero=hero,
        map_id=map_id,
        phase=phase,
        total_count=total_count,
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        avg_cells=avg_cells,
        quality_cells=quality_cells,
        quality_cell_floors=quality_cell_floors,
        quality_cell_floor_item_counts=quality_cell_floor_item_counts,
        soft_avg_cell_keys=pre_layout_soft_avg_cell_keys,
        source_notes=source_notes,
    )

    _apply_public_max_quality_ceiling(
        _extract_public_max_quality(
            snapshot,
            treasure_appraisal=treasure_appraisal,
        ),
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        source_notes=source_notes,
    )

    # Scope the high-tier-cell grid target to Aisha. The estimate ignores
    # public-reveal cell floors (e.g. a single q6 with 15 cells), so for other
    # heroes it can land below the minimum reachable grid and break red-reveal
    # combos (no_reachable_combo / count_prior fallback). Generalizing it with
    # floor-awareness is a v0.2 follow-up.
    if normalize_hero_key(hero) == "aisha" and not snapshot.get("_skip_high_tier_grid_target"):
        total_grid_target = _apply_total_grid_target_from_known_high_tier_cells(
            phase=phase,
            total_count=total_count,
            total_grid_target=total_grid_target,
            fixed_counts=fixed_counts,
            quality_cells=quality_cells,
            avg_cells=avg_cells,
            source_notes=source_notes,
            quality_values=quality_values,
            quality_cell_floors=quality_cell_floors,
            quality_cell_floor_item_counts=quality_cell_floor_item_counts,
        )

    round_no = _safe_int(context.get("round") or snapshot.get("round"))
    total_grid_target = _apply_layout_depth_hints_from_snapshot(
        snapshot=snapshot,
        hero=hero,
        round_no=round_no,
        total_grid_target=total_grid_target,
        source_notes=source_notes,
        total_count=total_count,
    )

    soft_avg_cell_keys = _derive_soft_public_avg_cell_keys(
        source_notes=source_notes,
        fixed_counts=fixed_counts,
        quality_cells=quality_cells,
    )
    if os.environ.get(BIDKING_DISABLE_MAX_FOOTPRINT_AVG_VALUE_FLOOR) != "1":
        for key in ("q4", "q5", "q6"):
            if key in soft_avg_cell_keys:
                continue
            resolved_floor = _max_footprint_avg_catalog_floor(key, avg_cells.get(key))
            if resolved_floor is None:
                continue
            floor_value, max_cells, item_ids = resolved_floor
            quality_min_total_value_floors[key] = max(
                quality_min_total_value_floors.get(key, 0.0),
                float(floor_value),
            )
            identity = str(item_ids[0]) if len(item_ids) == 1 else f"{len(item_ids)}ids"
            _append_source_note_once(
                source_notes,
                f"max_footprint_avg_value_floor:{key}:{max_cells}cells:"
                f"{floor_value}:{identity}:count_unlocked",
            )
    q5_avg = _safe_float(avg_cells.get("q5"))
    q5_known_cells = _safe_float(quality_cell_floors.get("q5"))
    q5_known_cell_items = int(quality_cell_floor_item_counts.get("q5", 0) or 0)
    if (
        q5_avg is not None
        and q5_avg > 0
        and q5_known_cells is not None
        and q5_known_cells >= q5_known_cell_items > 0
        and abs(q5_known_cells - round(q5_known_cells)) <= 0.0001
        and _q5_known_item_cell_compose_enabled("q5")
    ):
        _append_source_note_once(source_notes, Q5_KNOWN_ITEM_COMPOSE_NOTE)
    if (
        q5_avg is not None
        and q5_avg > 0
        and _q5_catalog_cell_compose_enabled("q5")
        and _avg_grid_options(1, q5_avg)
        and not _avg_grid_options(1, q5_avg, "q5")
    ):
        # Audit marker: the reading is globally composable only because another quality owns that
        # footprint. It does not claim an exact gold count; it records only that count==1 was pruned.
        _append_source_note_once(source_notes, Q5_CATALOG_CELL_COMPOSE_NOTE)
    for key in sorted(soft_avg_cell_keys):
        _append_source_note_once(source_notes, f"public_{key}_avg_cells_soft_pending_count")

    soft_avg_value_keys = _derive_soft_public_avg_value_keys(
        source_notes=source_notes,
        fixed_counts=fixed_counts,
        quality_values=quality_values,
        avg_values=avg_values,
    )
    _apply_public_avg_value_integer_product_min_counts(
        soft_avg_value_keys=soft_avg_value_keys,
        avg_values=avg_values,
        min_counts=min_counts,
        quality_count_cells_options=quality_count_cells_options,
        source_notes=source_notes,
    )
    for key in sorted(soft_avg_value_keys):
        _append_source_note_once(source_notes, f"public_{key}_avg_value_soft_pending_count")

    if (
        os.environ.get(BIDKING_DISABLE_AISHA_EXACT_RED_CELLS_VALUE) != "1"
        and normalize_hero_key(hero) == "aisha"
        and phase == "bidding"
        and _exact_integer_quality_cell(quality_cells.get("q6")) is not None
        and quality_cell_floors.get("q6", 0.0) > 0
    ):
        # A partial item's footprint is already contained in the measured q6 total.  Retaining the
        # redundant floor lets a tiny revealed item re-shape the q6 count posterior and can lower the
        # quote even though the exact total cells did not change (2548).  Keep the physical q6 fact and
        # known value, but remove only the subsumed aggregate cell floor from downstream priors.
        quality_cell_floors.pop("q6", None)
        quality_cell_floor_item_counts.pop("q6", None)
        _append_source_note_once(source_notes, "q6_partial_cell_floor_subsumed_by_exact_total")

    total_grid_target = normalize_grid_cell_target(total_grid_target)
    (
        shape_average_value_floors,
        shape_average_active_support,
    ) = _shape_average_active_joint_facts(
        snapshot,
        phase=phase,
        current_session=current_session,
        map_id=map_id,
        total_count=total_count,
        fixed_counts=fixed_counts,
        quality_cells=quality_cells,
        physical_candidate_domains=physical_candidate_domains,
        source_notes=source_notes,
    )
    if shape_average_active_support:
        _append_source_note_once(
            source_notes,
            "shape_avg_4cell_complete_joint_active" if all(row.get("footprint_cells") == 4 for row in shape_average_active_support)
            else "shape_avg_five_bucket_complete_joint_active",
        )

    return RefEvidence(
        hero=hero,
        map_id=map_id,
        phase=phase,
        total_count=total_count,
        fixed_counts=fixed_counts,
        min_counts=min_counts,
        count_sums=count_sums,
        avg_cells=avg_cells,
        quality_cells=quality_cells,
        quality_cell_floors=quality_cell_floors,
        quality_cell_floor_item_counts=quality_cell_floor_item_counts,
        avg_values=avg_values,
        quality_values=quality_values,
        quality_value_floors=quality_value_floors,
        quality_catalog_min_value_floors=quality_catalog_min_value_floors,
        quality_min_total_value_floors=quality_min_total_value_floors,
        quality_value_floor_item_counts=quality_value_floor_item_counts,
        split_counts=split_counts,
        split_quality_cells=split_quality_cells,
        split_avg_cells=split_avg_cells,
        random_value_floors=random_value_floors,
        total_grid_target=total_grid_target,
        soft_avg_cell_keys=soft_avg_cell_keys,
        soft_avg_value_keys=soft_avg_value_keys,
        v3_conservative=str(decision.get("defend_bid") or ""),
        v3_balanced=str(decision.get("attack_bid") or ""),
        v3_aggressive=str(decision.get("stop_price") or ""),
        source_notes=tuple(dict.fromkeys(source_notes)),
        random_sample=_random_sample_quality_counts(snapshot),
        q4_known_item_facts=q4_known_item_facts,
        q5_known_item_facts=q5_known_item_facts,
        q6_known_item_facts=q6_known_item_facts,
        quality_count_cells_options=quality_count_cells_options,
        quality_count_cells_value_options=quality_count_cells_value_options,
        quality_avg_value_intervals=quality_avg_value_intervals,
        q6_full_avg_support=q6_full_avg_support,
        public_category_total_value_floor=public_category_total_value_floor,
        physical_candidate_domains=physical_candidate_domains,
        hard_public_avg_values=hard_public_avg_values,
        total_grid_options=total_grid_options,
        shape_average_value_floors=shape_average_value_floors,
        shape_average_subset_floor=max((float(row.get("combined_total_value_floor", 0))
                                        for row in shape_average_active_support), default=0.0),
        shape_average_active_support=shape_average_active_support,
        ahmed_q1_q5_current_context_bound=(
            ahmed_q1_q5_current_context_bound
        ),
    )


@lru_cache(maxsize=4096)
def _composable_grid_total_set(count: int) -> frozenset[int]:
    """Membership-optimised view of `_composable_grid_options` (O(1) `grid in set`).
    Hot path: `can_compose_grid_total` was rebuilding the subset-sum reachable DP on every
    call (42k calls / ~4s on a rich activity-map round). The reachable totals depend only on
    `count`, so cache them once and test membership — behaviour-identical (verified for
    count 0..60 across all grids), pure speedup."""
    return frozenset(_composable_grid_options(count))


def can_compose_grid_total(count: int, grid: int) -> bool:
    if count == 0:
        return grid == 0
    if count < 0 or grid < count or grid > 18 * count:
        return False
    if os.environ.get("AHMAD_DISABLE_COMPOSE_CACHE") == "1":
        # Original per-call subset-sum DP (kept for A/B byte-identity verification).
        valid_sizes = (1, 2, 3, 4, 5, 6, 8, 9, 10, 12, 15, 16, 18)
        reachable = {0}
        for _ in range(count):
            reachable = {
                current + size
                for current in reachable
                for size in valid_sizes
                if current + size <= grid
            }
            if not reachable:
                return False
        return grid in reachable
    return grid in _composable_grid_total_set(count)


@lru_cache(maxsize=4096)
def _composable_grid_options(count: int) -> tuple[int, ...]:
    if count < 0:
        return ()
    if count == 0:
        return (0,)
    # 一次子集和 DP 求出「恰好 count 件」可组成的全部总格，而非对 range(count, 18*count+1)
    # 里每个候选格各跑一遍完整 DP（原写法 O(count^3) → 高总数时单次可达数十秒，是 live 低信息
    # 长推理的真正热点）。reachable 集合对所有候选格相同，算一次即可。结果与逐格调用
    # can_compose_grid_total 完全一致（已对 count 0..50 逐一核验），纯提速、零语义改动。
    valid_sizes = (1, 2, 3, 4, 5, 6, 8, 9, 10, 12, 15, 16, 18)
    cap = 18 * count
    reachable = {0}
    for _ in range(count):
        reachable = {
            current + size
            for current in reachable
            for size in valid_sizes
            if current + size <= cap
        }
    return tuple(sorted(grid for grid in reachable if grid >= count))


@lru_cache(maxsize=4096)
def _catalog_quality_composable_grid_options(
    table_quality: int, count: int
) -> tuple[int, ...]:
    """Reachable totals for exactly ``count`` items of one catalog quality."""
    if count < 0:
        return ()
    if count == 0:
        return (0,)
    valid_sizes = _catalog_cell_sizes_by_table_quality().get(int(table_quality), ())
    if not valid_sizes:
        return ()
    cap = max(valid_sizes) * count
    reachable = {0}
    for _ in range(count):
        reachable = {
            current + size
            for current in reachable
            for size in valid_sizes
            if current + size <= cap
        }
    return tuple(sorted(grid for grid in reachable if grid >= count))


def _composable_grid_options_for_quality(key: str | None, count: int) -> tuple[int, ...]:
    """Quality-aware composition where a catalog distinction is part of the contract.

    Keep the existing global composition as a fail-open fallback when the item table is unavailable.
    q5 prevents q2/q3/q4-only footprints from leaking into gold evidence. q6 independently uses the
    real red catalog, whose maximum is 20 cells and which has no 18-cell collectible.
    """
    quality_key = str(key or "").strip().lower()
    table_quality: int | None = None
    if quality_key == "q5" and os.environ.get(Q5_CATALOG_CELL_COMPOSE_DISABLE) != "1":
        table_quality = 5
    elif quality_key == "q6" and os.environ.get(Q6_CATALOG_CELL_COMPOSE_DISABLE) != "1":
        table_quality = 6
    if table_quality is not None:
        options = _catalog_quality_composable_grid_options(table_quality, int(count))
        if options:
            return options
    return _composable_grid_options(int(count))


def _catalog_quality_grid_ceiling(key: str | None, count: int) -> int | None:
    """Physical maximum for a displayed quality/count arm, or ``None`` when unavailable.

    Do not fall back to the cross-quality union here: a missing catalog must leave the existing room
    band untouched rather than silently imposing the legacy 18-cell red ceiling.
    """
    quality_key = str(key or "").strip().lower()
    if quality_key == "q5":
        if os.environ.get(Q5_CATALOG_CELL_COMPOSE_DISABLE) == "1":
            return None
        table_quality = 5
    elif quality_key == "q6":
        if os.environ.get(Q6_CATALOG_CELL_COMPOSE_DISABLE) == "1":
            return None
        table_quality = 6
    else:
        return None
    sizes = _catalog_cell_sizes_by_table_quality().get(table_quality, ())
    if not sizes or int(count) < 0:
        return None
    return int(max(sizes)) * int(count)


def _catalog_quality_single_item_grid_bounds(
    key: str | None,
) -> tuple[int, int] | None:
    """Return a validated single-item catalog domain's inclusive bounds."""

    quality_key = str(key or "").strip().lower()
    if quality_key == "q5":
        if os.environ.get(Q5_CATALOG_CELL_COMPOSE_DISABLE) == "1":
            return None
    elif quality_key == "q6":
        if os.environ.get(Q6_CATALOG_CELL_COMPOSE_DISABLE) == "1":
            return None
    else:
        return None
    table_quality = _quality_key_item_table_quality(quality_key)
    if table_quality is None:
        return None
    try:
        domain = _catalog_quality_composable_grid_options(table_quality, 1)
    except (ArithmeticError, TypeError, ValueError):
        return None
    if type(domain) is not tuple or not domain:  # noqa: E721 - internal domain invariant
        return None
    if any(
        type(option) is not int  # noqa: E721 - reject bool/subclasses/protocols
        or option <= 0
        or option > PUBLIC_AVG_CELLS_MAX_VALUE
        for option in domain
    ):
        return None
    normalized = tuple(sorted(set(domain)))
    if domain != normalized:
        return None
    return normalized[0], normalized[-1]


def _q5_catalog_cell_compose_enabled(key: str | None) -> bool:
    return (
        str(key or "").strip().lower() == "q5"
        and os.environ.get(Q5_CATALOG_CELL_COMPOSE_DISABLE) != "1"
        and bool(_catalog_cell_sizes_by_table_quality().get(5))
    )


def _can_compose_grid_total_for_quality(key: str | None, count: int, grid: int) -> bool:
    return int(grid) in _composable_grid_options_for_quality(key, int(count))


def _composable_grid_options_with_q6_catalog(key: str | None, count: int) -> tuple[int, ...]:
    """Use the real catalog only for red; preserve the legacy domain for every other tier."""
    if str(key or "").strip().lower() == "q6":
        return _composable_grid_options_for_quality("q6", int(count))
    return _composable_grid_options(int(count))


def _can_compose_grid_total_with_q6_catalog(
    key: str | None,
    count: int,
    grid: int,
) -> bool:
    return int(grid) in _composable_grid_options_with_q6_catalog(key, int(count))


def _q5_known_item_cell_compose_enabled(key: str | None) -> bool:
    return (
        _q5_catalog_cell_compose_enabled(key)
        and os.environ.get(Q5_KNOWN_ITEM_COMPOSE_DISABLE) != "1"
    )


def _q5_known_item_cell_components(evidence: "RefEvidence") -> tuple[int, int] | None:
    """Return the exact (known_count, known_cells) base for q5 residual composition.

    ``quality_cell_floors`` remains a floor for the whole tier because hidden gold may exist, but
    each contributing minimap/reveal footprint is exact for that physical item. The paired
    ``quality_cell_floor_item_counts`` field tells us how many revealed items produced the sum.
    """
    if not _q5_known_item_cell_compose_enabled("q5"):
        return None
    known_count = int((evidence.quality_cell_floor_item_counts or {}).get("q5", 0) or 0)
    raw_cells = _safe_float((evidence.quality_cell_floors or {}).get("q5"))
    if known_count <= 0 or raw_cells is None or raw_cells <= 0:
        return None
    known_cells = int(round(raw_cells))
    if abs(raw_cells - known_cells) > 0.0001 or known_cells < known_count:
        return None
    return known_count, known_cells


def _q5_known_item_cell_compose_matches(
    count: int,
    grid: int,
    evidence: "RefEvidence",
) -> bool:
    """Whether total q5 (count, grid) can contain the already revealed gold footprint base."""
    components = _q5_known_item_cell_components(evidence)
    if components is None:
        return True
    known_count, known_cells = components
    remaining_count = int(count) - known_count
    remaining_cells = int(grid) - known_cells
    if remaining_count < 0 or remaining_cells < 0:
        return False
    return _can_compose_grid_total_for_quality("q5", remaining_count, remaining_cells)


def _q6_known_item_exact_cells_residual(
    count: int,
    grid: int | float,
    evidence: "RefEvidence",
) -> tuple[int, int, int] | None:
    """Return the known value and unknown q6 count/cells for exact residual solving."""

    if (
        _run_env_get(Q6_KNOWN_ITEM_EXACT_CELLS_RESIDUAL_DISABLE) == "1"
        or not evidence.q6_known_item_facts
    ):
        return None
    exact_cells = _quality_exact_cells("q6", evidence)
    grid_value = _safe_float(grid)
    if exact_cells is None or grid_value is None:
        return None
    grid_int = int(round(grid_value))
    if abs(grid_value - grid_int) > 0.0001 or grid_int != int(exact_cells):
        return None
    if any(
        type(identity) is not str  # noqa: E721 - exact internal fact row
        or not identity
        or type(cells) is not int  # noqa: E721 - reject bool/subclasses
        or cells <= 0
        or type(value) is not int  # noqa: E721 - reject bool/subclasses
        or value <= 0
        for identity, cells, value in evidence.q6_known_item_facts
    ):
        return None
    known_count = len(evidence.q6_known_item_facts)
    known_cells = sum(cells for _, cells, _ in evidence.q6_known_item_facts)
    known_value = sum(value for _, _, value in evidence.q6_known_item_facts)
    return (
        known_value,
        int(count) - known_count,
        grid_int - known_cells,
    )


def _q6_known_item_exact_cells_compose_matches(
    count: int,
    grid: int | float,
    evidence: "RefEvidence",
) -> bool:
    residual = _q6_known_item_exact_cells_residual(count, grid, evidence)
    if residual is None:
        return True
    _known_value, remaining_count, remaining_cells = residual
    if remaining_count < 0 or remaining_cells < 0:
        return False
    return _can_compose_grid_total_for_quality(
        "q6",
        remaining_count,
        remaining_cells,
    )


def _q6_known_item_exact_cells_catalog_value_floor(
    key: str,
    *,
    count: int,
    grid: int | float,
    evidence: "RefEvidence",
) -> float:
    """Return the catalog floor after subtracting correlated known q6 items."""

    if key != "q6":
        return 0.0
    residual = _q6_known_item_exact_cells_residual(count, grid, evidence)
    if residual is None:
        return 0.0
    known_value, remaining_count, remaining_cells = residual
    if remaining_count < 0 or remaining_cells < 0:
        return 0.0
    residual_minimum = _catalog_min_total_value_for_quality_count_cells(
        6,
        remaining_count,
        remaining_cells,
    )
    if residual_minimum is None:
        return 0.0
    return float(known_value + residual_minimum)


AVG_GRID_OPTIONS_RUN_CACHE_DISABLE = "AHMAD_DISABLE_AVG_GRID_OPTIONS_RUN_CACHE"
AVG_GRID_OPTIONS_RUN_CACHE_MAX_ENTRIES = 256


def _avg_grid_catalog_semantics(key: str) -> tuple[Any, ...] | None:
    """Return an immutable content signature for the catalog domain used by ``key``.

    The catalog loader is process-cached but its returned mapping can be reconciled in place by
    tests or a long-lived caller.  Object identity and the catalog-mode boolean therefore do not
    identify the domain consumed by the quality-aware composer.  Cache only a strict internal
    catalog shape and bind the run-local key to its exact integer content.  An unexpected shape
    bypasses this optimization instead of invoking user-defined hashing/equality methods or
    inventing a sentinel generation that could alias two different domains.
    """
    quality_key = str(key or "").strip().lower()
    if quality_key == "q5":
        table_quality = 5
        disabled = os.environ.get(Q5_CATALOG_CELL_COMPOSE_DISABLE) == "1"
    elif quality_key == "q6":
        table_quality = 6
        disabled = os.environ.get(Q6_CATALOG_CELL_COMPOSE_DISABLE) == "1"
    else:
        return ("catalog_not_used",)
    if disabled:
        return ("catalog_disabled", table_quality)

    catalog = _catalog_cell_sizes_by_table_quality()
    if type(catalog) is not dict:  # noqa: E721 - stable internal cache-key contract
        return None
    domain = catalog.get(table_quality, ())
    if type(domain) is not tuple:  # noqa: E721 - do not hash a mutable/custom container
        return None
    if any(type(size) is not int or size <= 0 for size in domain):  # noqa: E721
        return None
    if domain != tuple(sorted(set(domain))):
        return None
    return ("catalog_domain", table_quality, domain)


def _avg_grid_options_for_evidence(
    count: int,
    avg: float | None,
    key: str,
    evidence: "RefEvidence",
) -> list[int]:
    def compute_uncached() -> list[int]:
        options = _avg_grid_options(count, avg, key)
        if key != "q5" or avg is None:
            return options
        return [
            grid
            for grid in options
            if _q5_known_item_cell_compose_matches(count, grid, evidence)
        ]

    run_cache = _RUN_CACHE.get()
    if (
        run_cache is None
        or normalize_hero_key(evidence.hero) != "ethan"
        or _run_env_get(AVG_GRID_OPTIONS_RUN_CACHE_DISABLE) == "1"
    ):
        # Keep direct helper calls, every other hero, and the rollback arm on the exact legacy path.
        return compute_uncached()

    q5_components = (
        _q5_known_item_cell_components(evidence)
        if key == "q5" and avg is not None
        else None
    )

    def compute() -> tuple[int, ...]:
        options = _avg_grid_options(count, avg, key)
        if q5_components is None:
            return tuple(options)
        known_count, known_cells = q5_components
        return tuple(
            grid
            for grid in options
            if int(count) >= known_count
            and int(grid) >= known_cells
            and _can_compose_grid_total_for_quality(
                "q5",
                int(count) - known_count,
                int(grid) - known_cells,
            )
        )

    # A RefEvidence instance is frozen but its mapping fields are mutable.  Key the only evidence
    # content this helper consumes instead of its identity.  The catalog mapping can likewise be
    # reconciled in place, so bind q5/q6 to validated immutable domain content, not just a mode bit.
    # The ContextVar is created and reset at the public run boundary, so this bounded bucket cannot
    # cross sessions, threads, or processes.
    catalog_semantics = _avg_grid_catalog_semantics(key)
    if catalog_semantics is None:
        return compute_uncached()
    cache_key = (
        int(count),
        avg,
        key,
        q5_components,
        catalog_semantics,
    )
    cache = run_cache.setdefault("avg_grid_options_for_evidence", {})
    cached = cache.get(cache_key, _ENV_MISSING)
    if cached is not _ENV_MISSING:
        return list(cached)
    result = compute()
    if len(cache) < AVG_GRID_OPTIONS_RUN_CACHE_MAX_ENTRIES:
        cache[cache_key] = result
    return list(result)


AISHA_HIDDEN_HT_GRID_SPREAD_DISABLE = "AISHA_DISABLE_HIDDEN_HIGHTIER_GRID_SPREAD"  # default ON
_AISHA_GEOM_CENTER_PULL = 0.8  # how far to float the grid center toward the full-row geometric value
# Unpinned gold/red footprints: instead of one mean-sized estimate, spread over a per-item SIZE range
# (small..big) with a right-skewed plausibility prior. The mean is most likely but big gold/red are
# real -- without this the grid band collapses (N hidden items * a constant mean = constant cells
# regardless of the count split; 2501 R4: 9 hidden items truly hold 61 cells = 6.8/item vs ~2.7).
# Size multipliers RELATIVE to the tier's own DEFAULT_GRID_MEANS, so the mid (×1.0) == the baseline
# mean estimate and the p50 (reference) does NOT shift -- only the thin tails widen p10/p90 for the
# small/big possibility. Symmetric-ish weight around ×1.0 keeps the median at the mean.
_HIDDEN_HT_CELL_SIZE_PRIOR = ((0.60, 0.42), (1.0, 1.00), (1.45, 0.42))


def _cell_unknown_hightier_keys(evidence: "RefEvidence") -> list[str]:
    """High-tier tiers (gold/red) whose footprint is genuinely unknown (no exact cells, no avg) --
    pure size-prior. These are the ones a single mean under-estimates when the item is big."""
    out: list[str] = []
    for key in ("q5", "q6"):
        if _quality_exact_cells(key, evidence) is not None:
            continue
        if evidence.avg_cells.get(key) is not None:
            continue
        out.append(key)
    return out


@lru_cache(maxsize=4096)
def _hidden_hightier_cell_options_cached(
    key: str,
    count: int,
    floor: int,
    center: float,
    q5_big: float,
    q6_catalog_disabled: bool = False,
) -> tuple[tuple[float, float], ...]:
    domain = (
        _composable_grid_options(int(count))
        if str(key or "").strip().lower() == "q6" and q6_catalog_disabled
        else _composable_grid_options_with_q6_catalog(key, count)
    )
    composable = tuple(
        option
        for option in domain
        if option >= floor
    )
    if not composable:
        return ((float(count), 1.0),)
    size_prior = _HIDDEN_HT_CELL_SIZE_PRIOR
    if key == "q5" and q5_big > 0:
        size_prior = (size_prior[0], size_prior[1], (q5_big, size_prior[2][1]))
    by_cells: dict[int, float] = {}
    for mult, weight in size_prior:
        nearest = min(composable, key=lambda option: (abs(option - center * mult), option))
        by_cells[nearest] = max(by_cells.get(nearest, 0.0), weight)
    return tuple((float(cells), weight) for cells, weight in by_cells.items())


def _hidden_hightier_cell_options(
    key: str, count: int, evidence: "RefEvidence", center_cells: float | None = None
) -> list[tuple[float, float]]:
    """Representative (cells, prior_weight) for an unpinned high-tier tier's footprint: a symmetric
    SIZE range (small..big) around `center_cells` (default the count*mean), composable for `count`
    items and >= the cell floor. Centering on the combo's OWN fitted grid keeps the p50 == the combo
    total (no band shift) while still floating small/big; only the geometric center-shift raises the
    genuine under-floor cases. Dedup keeps the max weight for a shared composable cell total."""
    count = int(count)
    if count <= 0:
        return [(0.0, 1.0)]
    floor = _quality_cell_floor_for_grid_fit(key, evidence, count)
    center = (
        float(center_cells)
        if center_cells and center_cells > 0
        else count * DEFAULT_GRID_MEANS.get(key, 2.4)
    )
    q5_big = 0.0
    if key == "q5":
        # Calibration knob (DEFAULT OFF). The big tier mult 1.45 (×2.8≈4.06 cells) can't reach 9-18-cell
        # gold 展品 → big-gold-vault total grid UNDER-fill. It is part of the cache key, never hidden.
        try:
            q5_big = float(_run_env_get("AISHA_HIDDEN_HT_SIZE_PRIOR_Q5_BIG", 0.0) or 0.0)
        except (TypeError, ValueError):
            q5_big = 0.0
    args = (
        key,
        count,
        floor,
        center,
        q5_big,
        _run_env_get(Q6_CATALOG_CELL_COMPOSE_DISABLE) == "1",
    )
    if _run_env_get("AHMAD_DISABLE_HIDDEN_HT_OPTION_CACHE") == "1":
        options = _hidden_hightier_cell_options_cached.__wrapped__(*args)
    else:
        options = _hidden_hightier_cell_options_cached(*args)
    return list(options)


def _ref_format_game_avg(cells: int, count: int, *, max_decimals: int = 2) -> str:
    if count <= 0 or cells < 0:
        return ""
    decimals = max(2, max_decimals)
    scale = 10**decimals
    floored_scaled = (int(cells) * scale) // int(count)
    int_part, frac_value = divmod(floored_scaled, scale)
    digits = str(frac_value).zfill(decimals)
    if int(cells) * scale == floored_scaled * int(count):
        digits = digits.rstrip("0")
    return f"{int_part}.{digits}" if digits else str(int_part)


def _ref_parse_display_avg(text: str) -> float | None:
    value = str(text or "").strip().replace(",", "")
    if not value or "e" in value.lower():
        return None
    if "." in value:
        int_part, frac_part = value.split(".", 1)
        if not int_part.isdigit() or not frac_part.isdigit():
            return None
    elif not value.isdigit():
        return None
    try:
        return float(value)
    except ValueError:
        return None


def _ref_avg_display_decimals(display_text: str) -> int:
    value = str(display_text or "").strip()
    if "." not in value:
        return 0
    return len(value.split(".", 1)[1])


def _ref_avg_display_product_tolerance(display_text: str, count: int) -> float:
    decimals = _ref_avg_display_decimals(display_text)
    if decimals < 2:
        return 0.0001
    return max(0.0001, (0.5 * (10**-decimals) * max(1, int(count))) + 1e-9)


def _ref_avg_looks_like_display_reading(avg: float) -> bool:
    if not math.isfinite(avg):
        return False
    for decimals in (3, 2, 1, 0):
        rounded = round(avg, decimals)
        if abs(avg - rounded) <= 1e-9:
            return True
    return False


def _ref_normalize_avg_value_wire(avg: float | None) -> float | None:
    """Snap protocol float averages to UI decimals before fraction/count parsing.

    Client avg prices often arrive as binary floats (total/count). Feeding those
    directly into Fraction.limit_denominator(60) can pick a wrong rational on the
    full magnitude (e.g. 6659.21435546875 -> 93229/14).
    """
    if avg is None:
        return None
    value = float(avg)
    if not math.isfinite(value) or value < 0:
        return None
    if _ref_avg_looks_like_display_reading(value):
        for decimals in (3, 2, 1, 0):
            rounded = round(value, decimals)
            if abs(value - rounded) <= 1e-9:
                return rounded
    wire = Fraction(value).limit_denominator(65536)
    if abs(float(wire) - value) <= 1e-9:
        wired = float(wire)
        # Skip decimal places finer than the float32 wire's own precision. The client sends a float32
        # (total/count); its ULP at e.g. 25726 is ~0.002, so any "3rd decimal" is binary NOISE, not a
        # real display digit. The old loop snapped 25726.69921875 -> 25726.699, giving a bogus fraction
        # 25726699/1000 (denom 1000) that breaks the integer-product count filter (count must clear
        # the denominator). The true UI display is 1-2 decimals (25726.7 -> 257267/10, denom 10;
        # 30889.572265625 -> 30889.57 -> denom 100), which is what pins gold count (.7 => not 5; 7-case).
        ulp32 = 2.0 ** (math.frexp(wired)[1] - 24)
        for decimals in (3, 2, 1, 0):
            if (0.5 * 10**-decimals) < ulp32:
                continue  # decimal below the float32 noise floor -> spurious, not a real display digit
            rounded = round(wired, decimals)
            if abs(wired - rounded) <= (0.5 * 10**-decimals) + 1e-9:
                return rounded
    return value


def _ref_avg_value_decimal_text(avg: float) -> str:
    return format(float(avg), ".10f").rstrip("0").rstrip(".")


def _ref_avg_value_product_tolerance(count: int, avg: float) -> float:
    text = _ref_avg_value_decimal_text(avg)
    decimals = len(text.split(".", 1)[1]) if "." in text else 0
    return max(0.0001, (0.5 * 10**-decimals) * max(1, int(count)) + 1e-6)


def _ref_public_avg_value_wire_normalized(evidence: RefEvidence, key: str) -> bool:
    return f"public_{key}_avg_value_wire_normalized" in evidence.source_notes


def _filter_quality_counts_for_avg_value(
    key: str,
    candidates: Iterable[int],
    evidence: RefEvidence,
) -> list[int]:
    ordered = sorted({int(value) for value in candidates})
    avg = evidence.avg_values.get(key)
    if key in evidence.soft_avg_value_keys and _avg_value_has_positive_signal(avg):
        if key in {"q4", "q5", "q6"} and _catalog_value_joint_projection_enabled(
            key
        ):
            supported_counts = {
                int(count)
                for count, _cells in (evidence.quality_count_cells_options or {}).get(
                    key, ()
                )
            }
            if supported_counts:
                return [value for value in ordered if value in supported_counts]
            if key != "q4":
                # q5/q6 use the absence of a validated joint as an explicit soft/full-domain state.
                return ordered
            # q4 has no item-value joint to replace its established soft-average contract. Fall
            # through instead of silently discarding the normalized-wire count domain (Aisha 0052).
        # A precise *fractional* tier-mean price pins the count: total value = avg*count must be an
        # integer, so count is a multiple of the reduced denominator (93229/14 -> multiple of 14;
        # 44925/8 -> multiple of 8). Apply this even when the mean isn't a single catalog item value.
        # Gate on denominator>1: an integer-valued avg (e.g. 31560) constrains nothing, so it must NOT
        # be used to spuriously collapse the count (esp. not to 1 -- see does_not_lock_one).
        normalized = _ref_normalize_avg_value_wire(avg)
        avg_fraction = _avg_value_fraction(normalized) if normalized is not None else None
        if avg_fraction is not None and avg_fraction.denominator > 1:
            filtered = [
                value
                for value in ordered
                if _avg_value_count_matches_for_public_evidence(
                    key, value, avg, evidence.source_notes
                )
            ]
            if filtered:
                return filtered
            if (
                f"public_{key}_avg_value" in evidence.source_notes
                and not _ref_public_avg_value_wire_normalized(evidence, key)
                and os.environ.get(
                    "BIDKING_DISABLE_PRECISE_PUBLIC_AVG_VALUE_ULP_COUNT_LOCK"
                )
                != "1"
            ):
                # An untouched public float32 wire has a complete half-ULP feasibility interval.
                # No match is a genuine conflict and must reach the established presence-fallback
                # retry; silently keeping every prior candidate would discard the exact mean.
                return []
        if not _avg_is_exact_catalog_item_value(key, avg):
            return [value for value in ordered if value != 1]
        filtered = [
            value
            for value in ordered
            if _avg_value_count_matches_for_public_evidence(
                key, value, avg, evidence.source_notes
            )
        ]
        if filtered:
            return filtered
        return []
    if (
        ordered
        and avg is not None
        and _ref_public_avg_value_wire_normalized(evidence, key)
    ):
        return ordered
    return [
        value
        for value in ordered
        if _quality_count_matches_value_evidence(key, value, evidence)
    ]


def _ref_avg_matches_game_display(count: int, avg: float | None, grid: int) -> bool:
    if avg is None:
        return True
    if count <= 0:
        return grid == 0 and abs(float(avg)) <= 0.0001
    if abs(float(avg) * count - grid) <= 0.0001:
        return True
    if not _ref_avg_looks_like_display_reading(float(avg)):
        return False
    display_text = _ref_format_game_avg(grid, count)
    display_value = _ref_parse_display_avg(display_text)
    if display_value is None:
        return False
    product_tolerance = _ref_avg_display_product_tolerance(display_text, count)
    if abs(float(avg) * count - grid) <= product_tolerance:
        return True
    return abs(display_value - float(avg)) <= 1e-9


def _avg_grid_options(
    count: int, avg: float | None, quality_key: str | None = None
) -> list[int]:
    if count < 0:
        return []
    if count == 0:
        return [0] if avg in (None, 0) else []
    low = count
    if str(quality_key or "").strip().lower() == "q6":
        composable_domain = _composable_grid_options_for_quality("q6", count)
        high = max(composable_domain) if composable_domain else 18 * count
    else:
        high = 18 * count
    if avg is None:
        return list(range(low, high + 1))
    target = avg * count
    tolerance = 0.0001
    candidates = {
        int(math.floor(target)),
        int(round(target)),
        int(math.ceil(target)),
    }
    options = [
        grid
        for grid in sorted(candidates)
        if low <= grid <= high
        and abs(grid - target) <= tolerance
        and _can_compose_grid_total_for_quality(quality_key, count, grid)
    ]
    if options:
        return options
    exact_options = [
        grid
        for grid in range(low, high + 1)
        if abs(grid - target) <= tolerance
        and _can_compose_grid_total_for_quality(quality_key, count, grid)
    ]
    if exact_options:
        return exact_options
    return [
        grid
        for grid in range(low, high + 1)
        if _ref_avg_matches_game_display(count, avg, grid)
        and _can_compose_grid_total_for_quality(quality_key, count, grid)
    ]


def _public_total_avg_cells_grid_options(
    total_count: int,
    total_avg_cells: float | None,
) -> tuple[int, ...]:
    """Catalog-reachable integer totals for one hard count/all-items mean.

    Reuse the engine's game-display average semantics, but deliberately omit a
    quality key: this fact covers the whole warehouse and must never inherit a
    q4/q5/q6 footprint domain.
    """
    count = int(total_count)
    avg = _safe_float(total_avg_cells)
    if count <= 0 or count > 512 or avg is None or not math.isfinite(avg) or avg <= 0:
        return ()
    return tuple(_avg_grid_options(count, float(avg), None))


def _avg_count_from_cells(
    avg: float | None, cells: Any, quality_key: str | None = None
) -> int | None:
    if avg is None or cells in (None, ""):
        return None
    try:
        cells_value = float(str(cells).replace(",", "").strip())
    except (TypeError, ValueError):
        return None
    if cells_value < 0:
        return None
    cells_int = int(round(cells_value))
    if abs(cells_value - cells_int) > 0.0001:
        return None
    if avg == 0:
        return 0 if cells_int == 0 else None
    count = int(round(cells_int / avg))
    if count > 0 and abs(avg * count - cells_int) <= 0.0001:
        if _can_compose_grid_total_for_quality(quality_key, count, cells_int):
            return count
    display_candidates = [
        candidate
        for candidate in range(1, cells_int + 1)
        if _ref_avg_matches_game_display(candidate, avg, cells_int)
        and _can_compose_grid_total_for_quality(quality_key, candidate, cells_int)
    ]
    if len(display_candidates) == 1:
        return display_candidates[0]
    return None


def _avg_matches_exact_grid(count: int, avg: float | None, grid: int) -> bool:
    return _ref_avg_matches_game_display(count, avg, grid)


def _avg_value_fraction(avg: float | None) -> Fraction | None:
    if avg is None:
        return None
    normalized = _ref_normalize_avg_value_wire(avg)
    if normalized is None:
        return None
    value = float(normalized)
    if not math.isfinite(value) or value < 0:
        return None
    if value == 0:
        return Fraction(0, 1)
    text = _ref_avg_value_decimal_text(value)
    if "." not in text:
        return Fraction(int(text), 1)
    whole, frac = text.split(".", 1)
    digits = len(frac)
    exact = Fraction(int(whole) * 10**digits + int(frac), 10**digits)
    return exact.limit_denominator(10_000)


def _avg_value_has_positive_signal(avg: float | None) -> bool:
    fraction = _avg_value_fraction(avg)
    return fraction is not None and fraction > 0


def _avg_value_count_matches(count: int, avg: float | None) -> bool:
    normalized = _ref_normalize_avg_value_wire(avg)
    if normalized is None:
        return True
    if normalized == 0:
        return count == 0
    if count <= 0:
        return False
    # Authoritative count constraint: test the RAW float32 wire against the integer-product rule with a
    # ULP-scaled tolerance, rather than the decimal-snapped `normalized`. The client avg is a float32 of
    # (integer total / integer count); at magnitude >= 65536 its ULP (~0.008) exceeds a 1-decimal grid,
    # so `_ref_normalize_avg_value_wire` snaps the wire to a spurious low denominator (e.g.
    # f32(196609/3)=65536.3359 -> 65536.3 = 655363/10) that no longer encodes total/count. The prior
    # denom<=24 exact-fraction lock then treated denom 10 as authoritative and REJECTED the true count 3
    # (-> no_reachable / wrong lock). 21461.8 (denom 5, true count 5) and 65536.3 (denom 10, snapped
    # artifact) are indistinguishable by denominator, so a denom threshold cannot work. Testing the raw
    # wire fixes both: accept count iff |raw*count - round(raw*count)| <= k * ulp32(raw) * count.
    # f32(total/count) is within 0.5*ulp32 of total/count. Keep the broad 4-ULP legacy default here
    # because some callers hold a decimal-normalized wire rather than the raw float32; the
    # evidence-aware wrapper below can prove when a public value was NOT normalized and safely use
    # the exact half-ULP interval.
    # Revert to the prior decimal-fraction path: AHMAD_DISABLE_AVG_VALUE_ULP_COUNT_LOCK=1.
    # Tune the ULP factor globally: AHMAD_AVG_VALUE_ULP_K (legacy default 4).
    if os.environ.get("AHMAD_DISABLE_AVG_VALUE_ULP_COUNT_LOCK") != "1":
        raw = float(avg)
        if math.isfinite(raw) and raw > 0:
            try:
                ulp_k = float(os.environ.get("AHMAD_AVG_VALUE_ULP_K", "4"))
            except (TypeError, ValueError):
                ulp_k = 4.0
            ulp32 = 2.0 ** (math.frexp(raw)[1] - 24)
            product = raw * int(count)
            return abs(product - round(product)) <= ulp_k * ulp32 * int(count)
    fraction = _avg_value_fraction(normalized)
    if fraction is not None and fraction > 0:
        if (fraction.numerator * int(count)) % fraction.denominator == 0:
            return True
        # When a full-precision float32 wire of a true (integer total / integer count) is recovered to
        # a SMALL reduced denominator, the integer-product constraint is EXACT: count must be a multiple
        # of that denominator. A clean terminating decimal like 21461.8 (=107309/5, denom 5) otherwise
        # falls through to the display-decimals tolerance below (0.5*10^-1*count = 0.05*count) which is
        # too loose and wrongly admits near-miss counts (count=4 -> 21461.8*4 = 85847.2, exactly 0.2 off
        # = the 1-decimal tolerance -> leaks in beside the true count=5). Gate on a SMALL denominator:
        # a real wire float of total/count reduces to denom <= the (small) per-quality count, while a
        # 2-decimal display TRUNCATION (e.g. 5747.33 = 574733/100, denom 100) yields a spurious large
        # denom whose exact constraint (count multiple of 100) is unreachable -> keep the tolerant
        # fallback for those. Revert: AHMAD_DISABLE_AVG_VALUE_EXACT_FRACTION_LOCK=1;
        # tune: AHMAD_AVG_VALUE_EXACT_FRACTION_MAX_DENOM (default 24).
        try:
            max_denom = int(os.environ.get("AHMAD_AVG_VALUE_EXACT_FRACTION_MAX_DENOM", "24"))
        except (TypeError, ValueError):
            max_denom = 24
        if (
            os.environ.get("AHMAD_DISABLE_AVG_VALUE_EXACT_FRACTION_LOCK") != "1"
            and fraction.denominator <= max_denom
            and abs(float(fraction) - float(normalized)) <= 1e-9
        ):
            return False
    product = float(normalized) * int(count)
    tolerance = _ref_avg_value_product_tolerance(int(count), float(normalized))
    return abs(product - round(product)) <= tolerance


def _avg_value_count_matches_for_public_evidence(
    key: str,
    count: int,
    avg: float | None,
    source_notes: Iterable[str],
) -> bool:
    notes = set(source_notes)
    is_exact_public_wire = (
        f"public_{key}_avg_value" in notes
        and f"public_{key}_avg_value_wire_normalized" not in notes
    )
    if (
        not is_exact_public_wire
        or os.environ.get("BIDKING_DISABLE_PRECISE_PUBLIC_AVG_VALUE_ULP_COUNT_LOCK") == "1"
    ):
        return _avg_value_count_matches(count, avg)
    if avg is None or count <= 0:
        return _avg_value_count_matches(count, avg)
    raw = float(avg)
    if not math.isfinite(raw) or raw <= 0:
        return _avg_value_count_matches(count, avg)
    try:
        ulp_k = float(os.environ.get("AHMAD_AVG_VALUE_ULP_K", "0.5"))
    except (TypeError, ValueError):
        ulp_k = 0.5
    ulp32 = 2.0 ** (math.frexp(raw)[1] - 24)
    product = raw * int(count)
    # 2407 q5 avg 37494.125 is the exact public wire: 8 items gives integer total 299953, while the
    # legacy 4-ULP interval also admitted 9 (337447.125) and leaked an impossible 8/8/9 count range.
    # Half an IEEE float32 ULP is the complete rounding interval for an unmodified wire. Decimal-snapped
    # wires deliberately stay on the legacy path above because their extra normalization error can
    # exceed that interval. Rollback: BIDKING_DISABLE_PRECISE_PUBLIC_AVG_VALUE_ULP_COUNT_LOCK=1.
    return abs(product - round(product)) <= ulp_k * ulp32 * int(count)


def _avg_value_total_from_count(avg: float, count: int) -> float | None:
    fraction = _avg_value_fraction(avg)
    if fraction is None:
        return None
    return float(fraction * int(count))


def _avg_value_count_from_total(avg: float | None, total_value: Any) -> int | None:
    fraction = _avg_value_fraction(avg)
    value = _safe_float(total_value)
    if fraction is None or value is None or value < 0:
        return None
    total_fraction = Fraction(float(value)).limit_denominator(100)
    if fraction == 0:
        return 0 if total_fraction == 0 else None
    if total_fraction <= 0:
        return None
    count_fraction = total_fraction / fraction
    if count_fraction.denominator != 1 or count_fraction < 0:
        return None
    return int(count_fraction)


def _quality_count_product_tolerance_match(
    count: int,
    avg: float | None,
    exact_value: float | None,
    *,
    tolerance: float = 0.5,
) -> bool:
    if avg is None or exact_value is None or count <= 0:
        return False
    derived_total = _avg_value_total_from_count(float(avg), count)
    if derived_total is None:
        derived_total = float(avg) * int(count)
    return abs(float(exact_value) - derived_total) <= tolerance


def _avg_value_count_from_total_with_tolerance(
    avg: float | None,
    total_value: Any,
    *,
    total_count: int | None = None,
) -> int | None:
    """Recover integer count when wire-normalized avg breaks strict rational derive."""
    value = _safe_float(total_value)
    if avg is None or value is None or value <= 1e-9 or abs(float(avg)) <= 1e-9:
        return None
    approximate = max(1, int(round(float(value) / float(avg))))
    upper = int(total_count) if total_count and total_count > 0 else approximate + 3
    upper = min(max(upper, approximate), 200)
    lower = max(1, approximate - 3)
    candidates = [
        count
        for count in range(lower, upper + 1)
        if _quality_count_product_tolerance_match(count, avg, value)
    ]
    if len(candidates) == 1:
        return candidates[0]
    return None


def _choose_avg_grid_option(
    count: int,
    avg: float | None,
    options: list[int],
) -> float | None:
    if not options:
        return None
    if count <= 0:
        return 0.0
    if avg is None:
        return float(options[len(options) // 2])
    target = avg * count
    return float(min(options, key=lambda grid: (abs(grid - target), grid)))


def _log_fact(n):
    return math.lgamma(n + 1)


def _weighted_quantile(rows: list[tuple[float, float]], q: float) -> float | None:
    if not rows:
        return None
    rows = sorted(rows)
    total = sum(weight for _, weight in rows)
    if total <= 0:
        return rows[len(rows) // 2][0]
    threshold = total * q
    cumulative = 0.0
    for value, weight in rows:
        cumulative += weight
        if cumulative >= threshold:
            return value
    return rows[-1][0]


def _aisha_b6_coherent_joint_fit(
    combos: Sequence[RefCombo],
    *,
    max_log_weight: float,
    total_grid_mid: float,
) -> float | None:
    """Return B6's P50 red-room ratio without composing independent tier modes.

    ``RefCombo.grids`` is the warehouse-wide joint state: every non-red footprint and the q6
    footprint on a row belong to the same count/grid hypothesis.  Keep that row intact while
    comparing it with one selected total-grid arm, then take the posterior P50 of the resulting room
    ratios.  This is a joint non-red/q6 room-risk distribution, not a sum of quality marginals.  The
    caller admits this comparison only when total cells are direct hard evidence; a soft total-grid
    arm is not a safe ownership boundary for overriding the established B6 tradeoff.  A zero-red row has
    nothing to strip and contributes a full-fit state.
    """
    if not math.isfinite(float(total_grid_mid)) or float(total_grid_mid) < 0.0:
        return None
    weighted_fits: list[tuple[float, float]] = []
    for combo in combos:
        red_cells = max(0.0, float(combo.grids.get("q6", 0.0) or 0.0))
        nonred_cells = sum(
            max(0.0, float(combo.grids.get(key, 0.0) or 0.0))
            for key in ("q1", "q3", "q4", "q5")
        )
        fit = (
            1.0
            if red_cells <= 0.0
            else min(
                1.0,
                max(0.0, float(total_grid_mid) - nonred_cells) / red_cells,
            )
        )
        weight = math.exp(max(-745.0, float(combo.weight) - float(max_log_weight)))
        if math.isfinite(weight) and weight > 0.0:
            weighted_fits.append((fit, weight))
    return _weighted_quantile(weighted_fits, 0.50)


def _aisha_soft_total_q6_joint_distribution(
    combos: Sequence[RefCombo],
    *,
    evidence: RefEvidence,
    round_no: int | None,
    minimap_items: list[dict[str, Any]],
    total_grid_range: Sequence[int | None],
    quality_count_ranges: Mapping[str, Sequence[int | None]],
    quality_cells_ranges: Mapping[str, Sequence[int | None]],
    combo_support_complete: bool,
    max_log_weight: float,
    item_values: dict[str, float],
) -> dict[str, Any] | None:
    """Condition soft total-grid arms and q6 value on one physical joint.

    This is deliberately narrower than the display-only red/empty band.  Every non-red quality and
    the residual q6 count must already be a complete singleton in both the combo support and the
    published ranges.  The soft geometric total then contributes three *probabilistic* arms; it never
    becomes direct red evidence or an exact lock.
    """

    def _has_relevant_conflict_provenance(source_notes: Sequence[object]) -> bool:
        """Reject a pristine-singleton projection when its source facts disagree.

        Published ranges can remain singleton after an exact public row loses a conflict with an
        already-present hard fact.  That is useful for the legacy estimator, but it is not a sound
        ownership boundary for this second-stage joint conditioning.  Require the q1-q5 count/cell
        evidence to be conflict-free rather than treating the surviving value as unanimous.
        """

        for raw_note in source_notes:
            if type(raw_note) is not str:  # noqa: E721 - internal provenance is plain text
                continue
            if "conflict" not in raw_note:
                continue
            if raw_note.startswith(("public_", "hard_conflict:")):
                return True
            if any(quality in raw_note for quality in ("q1", "q3", "q4", "q5")) and any(
                semantic in raw_note
                for semantic in ("count", "cells", "avg", "split", "outline")
            ):
                return True
        return False

    if (
        _run_env_get(BIDKING_DISABLE_AISHA_SOFT_TOTAL_Q6_JOINT) == "1"
        or normalize_hero_key(evidence.hero) != "aisha"
        or type(evidence.map_id) is not int  # noqa: E721 - exact normalized scalar only
        or evidence.map_id // 100 != 56
        or evidence.phase != "bidding"
        or round_no != 5
        or not combo_support_complete
        or not combos
        or not _has_explicit_total_count_source(evidence.source_notes)
        or _has_relevant_conflict_provenance(evidence.source_notes)
        or _hard_total_grid_target_int(evidence) is not None
        or _quality_has_direct_count_grid_value_evidence("q6", evidence)
        or any(_safe_int(item.get("quality")) == 6 for item in minimap_items)
        or TOTAL_GRID_SOFT_FORCED_RED_TAIL_NOTE not in evidence.source_notes
        or TOTAL_GRID_FROM_HIGH_TIER_CELLS_NOTE not in evidence.source_notes
        or len(total_grid_range) != 3
    ):
        return None

    def _integral(value: object, *, positive: bool = False) -> int | None:
        if type(value) is int:  # noqa: E721 - exact internal scalar only
            parsed = value
        elif (  # noqa: E721 - exact internal scalar only
            type(value) is float
            and math.isfinite(value)
            and value.is_integer()
        ):
            parsed = int(value)
        else:
            return None
        if parsed < 0 or (positive and parsed <= 0):
            return None
        return parsed

    total_count = _integral(evidence.total_count, positive=True)
    if total_count is None:
        return None

    exact_counts: dict[str, int] = {}
    exact_cells: dict[str, int] = {}
    for key in ("q1", "q3", "q4", "q5"):
        combo_counts = {_integral(combo.counts.get(key)) for combo in combos}
        combo_cells = {_integral(combo.grids.get(key)) for combo in combos}
        if None in combo_counts or None in combo_cells:
            return None
        if len(combo_counts) != 1 or len(combo_cells) != 1:
            return None
        count = next(iter(combo_counts))
        cells = next(iter(combo_cells))
        count_range = quality_count_ranges.get(key)
        cells_range = quality_cells_ranges.get(key)
        if (
            count is None
            or cells is None
            or not count_range
            or not cells_range
            or len(count_range) != 3
            or len(cells_range) != 3
            or any(_integral(value) != count for value in count_range)
            or any(_integral(value) != cells for value in cells_range)
        ):
            return None
        exact_counts[key] = count
        exact_cells[key] = cells

    q6_counts = {_integral(combo.counts.get("q6"), positive=True) for combo in combos}
    if None in q6_counts or len(q6_counts) != 1:
        return None
    q6_count = next(iter(q6_counts))
    q6_range = quality_count_ranges.get("q6")
    if (
        q6_count is None
        or not q6_range
        or len(q6_range) != 3
        or any(_integral(value, positive=True) != q6_count for value in q6_range)
        or exact_counts["q1"]
        + exact_counts["q3"]
        + exact_counts["q4"]
        + exact_counts["q5"]
        + q6_count
        != total_count
        or any(sum(int(combo.counts[key]) for key in QUALITY_KEYS) != total_count for combo in combos)
    ):
        return None

    total_arms = tuple(_integral(value, positive=True) for value in total_grid_range)
    if any(value is None for value in total_arms):
        return None
    nonred_cells = sum(exact_cells.values())
    residual_arms = tuple(int(value) - nonred_cells for value in total_arms if value is not None)
    if (
        len(residual_arms) != 3
        or len(set(residual_arms)) < 2
        or any(
            residual < q6_count
            or not _can_compose_grid_total_for_quality("q6", q6_count, residual)
            for residual in residual_arms
        )
    ):
        return None

    weighted_values: list[tuple[float, float]] = []
    weighted_red_cells: list[tuple[float, float]] = []
    weighted_red_values: list[tuple[float, float]] = []
    weighted_count_cells: list[tuple[int, int, float]] = []
    for combo in combos:
        combo_weight = math.exp(max(-745.0, float(combo.weight) - float(max_log_weight)))
        if not math.isfinite(combo_weight) or combo_weight <= 0.0:
            continue
        old_red = _quality_value_for_evidence(
            "q6",
            count=q6_count,
            grid=float(combo.grids.get("q6", q6_count * DEFAULT_GRID_MEANS["q6"])),
            item_values=item_values,
            evidence=evidence,
        )
        for residual, arm_weight in zip(
            residual_arms,
            AISHA_SOFT_TOTAL_Q6_JOINT_ARM_WEIGHTS,
            strict=True,
        ):
            weight = combo_weight * arm_weight
            grids = dict(combo.grids)
            grids["q6"] = float(residual)
            red_center = _quality_value_for_evidence(
                "q6",
                count=q6_count,
                grid=float(residual),
                item_values=item_values,
                evidence=evidence,
            )
            center = float(combo.value) - float(old_red) + float(red_center)
            spread = _combo_value_uncertainty(combo.counts, grids, item_values, evidence)
            for value, point_weight in _combo_value_distribution_points(
                center,
                spread,
                evidence,
                counts=combo.counts,
                grids=grids,
                item_values=item_values,
            ):
                weighted_values.append((value, weight * point_weight))
            red_spread = _quality_value_uncertainty(
                "q6",
                count=q6_count,
                grid=float(residual),
                item_values=item_values,
                evidence=evidence,
            )
            for value, point_weight in _quality_value_distribution_points(
                "q6",
                center=red_center,
                spread=red_spread,
                count=q6_count,
                grid=float(residual),
                item_values=item_values,
                evidence=evidence,
            ):
                weighted_red_values.append((value, weight * point_weight))
            weighted_red_cells.append((float(residual), weight))
            weighted_count_cells.append((q6_count, residual, weight))

    if not weighted_values or not weighted_red_cells or not weighted_red_values:
        return None
    return {
        "weighted_values": weighted_values,
        "weighted_red_cells": weighted_red_cells,
        "weighted_red_values": weighted_red_values,
        "weighted_count_cells": weighted_count_cells,
        "q6_count": q6_count,
    }


def _candidate_distribution(
    rows: list[tuple[float, float]], *, top_k: int = 6, min_prob: float = 0.02
) -> tuple[tuple[int, float], ...]:
    """Aggregate weighted (value, weight) rows into a normalized candidate distribution
    [(int_value, prob), ...] sorted by prob desc (ties -> smaller value first). This is the same
    weighted mass the lo/mid/hi quantiles come from, just kept per-value instead of collapsed to
    endpoints — it powers the overlay hover "最可能5(72%) · 也可能6(18%)/7(10%)" when a quality count/
    cells is probabilistically (not exactly) locked. Drops candidates below min_prob and caps at top_k
    (but always keeps at least the top one). Additive: never feeds the estimate, display-only."""
    agg: dict[int, float] = {}
    total = 0.0
    for value, weight in rows:
        w = float(weight)
        if w <= 0.0:
            continue
        iv = int(round(float(value)))
        agg[iv] = agg.get(iv, 0.0) + w
        total += w
    if total <= 0.0 or not agg:
        return ()
    ordered = sorted(((v, w / total) for v, w in agg.items()), key=lambda vp: (-vp[1], vp[0]))
    trimmed = [(v, p) for v, p in ordered if p >= min_prob][:top_k]
    return tuple(trimmed) if trimmed else (ordered[0],)


def _joint_count_cells_distribution(
    rows: list[tuple[int, int, float]],
    *,
    top_k: int = 8,
    min_prob: float = 0.01,
    required_counts: Iterable[int] = (),
) -> tuple[tuple[int, int, float], ...]:
    """Aggregate feasible (count, cells) states without destroying their correlation.

    Probabilities retain their share of the full distribution.  Low-probability/tail states are omitted
    from the tooltip payload and the UI reports their remaining mass as ``其他`` instead of renormalizing
    the visible rows to 100%.
    """
    agg: dict[tuple[int, int], float] = {}
    total = 0.0
    for count, cells, weight in rows:
        w = float(weight)
        if w <= 0.0:
            continue
        state = (int(round(count)), int(round(cells)))
        agg[state] = agg.get(state, 0.0) + w
        total += w
    if total <= 0.0 or not agg:
        return ()
    ordered = sorted(
        ((count, cells, weight / total) for (count, cells), weight in agg.items()),
        key=lambda row: (-row[2], row[0], row[1]),
    )
    required = {int(count) for count in required_counts}
    required_rows: list[tuple[int, int, float]] = []
    for count in sorted(required):
        row = next((candidate for candidate in ordered if candidate[0] == count), None)
        if row is not None:
            required_rows.append(row)
    capacity = max(top_k, len(required_rows))
    selected = {row[:2]: row for row in required_rows}
    for row in ordered:
        if len(selected) >= capacity:
            break
        if row[2] >= min_prob:
            selected.setdefault(row[:2], row)
    trimmed = sorted(
        selected.values(),
        key=lambda row: (-row[2], row[0], row[1]),
    )
    return tuple(trimmed) if trimmed else (ordered[0],)


def _wire_visible_marginal_support(
    candidates: Sequence[tuple[int, float]],
) -> tuple[tuple[int, float], ...]:
    """Keep every selected physical arm positive after four-decimal encoding."""

    if not candidates:
        return ()
    minimum = 1.0 / _CANDIDATE_PROBABILITY_WIRE_SCALE
    probabilities = [float(probability) for _value, probability in candidates]
    deficit = sum(max(0.0, minimum - probability) for probability in probabilities)
    if deficit > 0.0:
        donor = max(range(len(probabilities)), key=probabilities.__getitem__)
        if probabilities[donor] - deficit < minimum:
            return tuple(candidates)
        probabilities[donor] -= deficit
        probabilities = [max(minimum, probability) for probability in probabilities]
    return tuple(
        (int(value), probabilities[index])
        for index, (value, _probability) in enumerate(candidates)
    )


def _wire_visible_joint_support(
    candidates: Sequence[tuple[int, int, float]],
) -> tuple[tuple[int, int, float], ...]:
    """Joint counterpart of :func:`_wire_visible_marginal_support`."""

    marginal = _wire_visible_marginal_support(
        tuple((index, probability) for index, (_count, _cells, probability) in enumerate(candidates))
    )
    probabilities = [probability for _index, probability in marginal]
    return tuple(
        (int(count), int(cells), probabilities[index])
        for index, (count, cells, _probability) in enumerate(candidates)
    )


def _count_values(
    total_count: int,
    key: str,
    evidence: RefEvidence,
    reserve: int,
) -> list[int]:
    fixed = evidence.fixed_counts.get(key)
    if fixed is not None:
        fixed_int = int(fixed)
        if not _quality_count_matches_value_evidence(key, fixed_int, evidence):
            return []
        return [fixed_int]
    minimum = _effective_min_count(key, evidence)
    maximum = total_count - reserve
    if maximum < minimum:
        return []
    values = _filter_quality_counts_for_avg_value(
        key,
        range(minimum, maximum + 1),
        evidence,
    )
    avg = evidence.avg_cells.get(key)
    if avg is not None and avg > 0 and fixed is None:
        fast_path = (
            _should_use_exact_total_avg_cells_fast_path(evidence)
            and key not in evidence.soft_avg_cell_keys
        )
        # Wire-precision public avg_cells (e.g. 10/3 = 3.3333332, not a 2-decimal display round)
        # implies the tier's total cells = avg*count is an exact integer.  Keep display-like public
        # readings soft by default so a later conflicting clue can still unlock a stale skill mean.
        # Ahmed's public-only q4 path is the narrow exception: once the exact total is known, 4541's
        # 2.125 reading permits 8 items / 17 cells, not 6 / 14 or 10 / 24.
        wire_soft = (
            evidence.phase != "settled"
            and key in evidence.soft_avg_cell_keys
            and (
                not _ref_avg_looks_like_display_reading(float(avg))
                or _ahmed_public_q4_avg_antilock_enabled(key, evidence)
            )
        )
        direct_grid_soft = _aisha_public_avg_direct_grid_domain_enabled(
            key,
            evidence,
        )
        if fast_path or wire_soft or direct_grid_soft:
            avg_valid = [
                value
                for value in values
                if _avg_grid_options_for_evidence(value, avg, key, evidence)
            ]
            if avg_valid or _q5_catalog_cell_compose_enabled(key):
                return avg_valid
    return values


def _aisha_public_avg_direct_grid_domain_enabled(
    key: str,
    evidence: RefEvidence,
) -> bool:
    """Use a public average as a physical domain, without upgrading it to an exact lock.

    Exact-total Aisha snapshots take the direct count/grid enumerator rather than the
    multinomial-prior enumerator.  The prior path already intersects every public
    average with the game's displayed-average arithmetic; the direct path historically
    did so only for wire-looking floats.  A display-like 2.75 therefore admitted counts
    whose total cells could never display as 2.75.  Once an independently hard total
    grid is present, keep every arithmetically reachable arm but reject those impossible
    count/grid pairs.
    """
    avg = _safe_float(evidence.avg_cells.get(key))
    return (
        _run_env_get(AISHA_PUBLIC_AVG_DIRECT_GRID_DOMAIN_DISABLE) != "1"
        and normalize_hero_key(evidence.hero) == "aisha"
        and key == "q4"
        and evidence.phase != "settled"
        and key in evidence.soft_avg_cell_keys
        and avg is not None
        and avg > 0.0
        and _hard_total_grid_target_int(evidence) is not None
    )


def _hard_avg_cells_min_count(key: str, evidence: RefEvidence) -> int | None:
    """Smallest physically feasible count implied by a hard positive tier average.

    A positive hard average proves the tier exists, but it does not necessarily mean
    "one item": the total cells must also be an integer, catalog-composable footprint.
    For example, 34/7 gold cells has its first feasible count at seven. Rounded display
    readings can admit several counts; taking only the minimum preserves every higher
    solution instead of falsely locking the reduced-fraction denominator.
    """
    if (
        evidence.phase == "settled"
        or evidence.fixed_counts.get(key) is not None
        or key in evidence.soft_avg_cell_keys
    ):
        return None
    avg = _safe_float(evidence.avg_cells.get(key))
    if avg is None or avg <= 0:
        return None
    for count in range(1, _TOTAL_COUNT_PRIOR_WINDOW_CAP + 1):
        if _avg_grid_options_for_evidence(count, avg, key, evidence):
            return count
    return None


def _effective_min_count(key: str, evidence: RefEvidence) -> int:
    minimum = max(0, int(evidence.min_counts.get(key, 0)))
    max_cells_per_item = (
        _catalog_quality_grid_ceiling("q6", 1)
        if str(key).strip().lower() == "q6"
        else None
    ) or 18
    if key == "q1":
        minimum = max(minimum, _split_low_quality_q1_count_floor(evidence))
    exact_cells = _quality_exact_cells(key, evidence)
    if exact_cells is not None and exact_cells > 0:
        minimum = max(
            minimum,
            int(math.ceil(exact_cells / float(max_cells_per_item))),
            1,
        )
    cell_floor = _quality_cell_floor(key, evidence)
    if cell_floor > 0:
        minimum = max(
            minimum,
            int(math.ceil(cell_floor / float(max_cells_per_item))),
            1,
        )
    exact_value = _quality_exact_value(key, evidence)
    if exact_value is not None and exact_value > 0:
        minimum = max(minimum, 1)
    if _quality_value_floor(key, evidence) > 0:
        minimum = max(minimum, 1)
    if (
        evidence.phase != "settled"
        and evidence.fixed_counts.get(key) is None
        and evidence.avg_cells.get(key) is not None
        and (evidence.avg_cells.get(key) or 0.0) > 0
    ):
        minimum = max(minimum, 1)
    if (
        evidence.phase != "settled"
        and evidence.fixed_counts.get(key) is None
        and evidence.avg_values.get(key) is not None
        and _avg_value_has_positive_signal(evidence.avg_values.get(key))
    ):
        minimum = max(minimum, 1)
    return minimum


def _quality_exact_cells(key: str, evidence: RefEvidence) -> int | None:
    value = evidence.quality_cells.get(key)
    if value is None:
        return None
    parsed_value = _safe_float(value)
    if parsed_value is None or not math.isfinite(parsed_value):
        return None
    parsed = int(round(parsed_value))
    return max(0, parsed)


def _quality_cell_floor(key: str, evidence: RefEvidence) -> int:
    value = evidence.quality_cell_floors.get(key)
    if value is None:
        return 0
    parsed = _safe_float(value)
    if parsed is None or parsed <= 0:
        return 0
    return max(0, int(math.ceil(parsed - 1e-6)))


def _quality_cell_floor_for_count(key: str, evidence: RefEvidence, count: int) -> int:
    """BUG-L (2026-07-11, 群友 #8 ahmed 2407: "为什么还可以 2件12格的可能在里面"): the revealed cell floor
    only covers the items it was revealed FROM (`quality_cell_floor_item_counts`). Every other item of
    the tier still occupies at least one cell of its own, so the honest floor for a `count`-item combo
    is `floor + (count − floor_items)` — never the bare footprint (which let a 2-red combo sit at the
    12-cell footprint of the ONE revealed red, i.e. the second red got 0 cells). Also never below
    `count` (1 cell per item). Kill: BIDKING_DISABLE_PER_ITEM_CELL_FLOOR=1.
    """
    floor = _quality_cell_floor(key, evidence)
    if _run_env_get("BIDKING_DISABLE_PER_ITEM_CELL_FLOOR") == "1":
        return floor
    count = max(0, int(count))
    floor_items = int((evidence.quality_cell_floor_item_counts or {}).get(key, 0) or 0)
    if floor > 0 and floor_items > 0:
        floor += max(0, count - floor_items)
    return max(floor, count)


def _aisha_partial_red_floor_applies_to_count(
    key: str,
    evidence: RefEvidence,
    count: int,
) -> bool:
    return bool(
        key == "q6"
        and normalize_hero_key(evidence.hero) == "aisha"
        and evidence.phase == "bidding"
        and key not in evidence.fixed_counts
        and _partial_red_floor_has_unmeasured_items(
            count,
            quality_cell_floors=evidence.quality_cell_floors,
            quality_cell_floor_item_counts=evidence.quality_cell_floor_item_counts,
        )
    )


def _aisha_partial_red_floor_avg_can_use_catalog_fallback(
    key: str,
    avg: Any,
) -> bool:
    """Allow floor reconciliation only for a catalog-physical per-item average."""

    if type(avg) is int:  # noqa: E721 - exact internal scalar boundary
        if avg <= 0 or avg > PUBLIC_AVG_CELLS_MAX_VALUE:
            return False
        value = float(avg)
    elif type(avg) is float:  # noqa: E721 - reject subclasses/coercion
        if (
            not math.isfinite(avg)
            or avg <= 0.0
            or avg > PUBLIC_AVG_CELLS_MAX_VALUE
        ):
            return False
        value = avg
    else:
        return False
    bounds = _catalog_quality_single_item_grid_bounds(key)
    if bounds is None:
        return False
    lower, upper = bounds
    return float(lower) <= value <= float(upper)


def _quality_cell_floor_for_grid_fit(
    key: str,
    evidence: RefEvidence,
    count: int,
) -> int:
    if key == "q6" and (
        normalize_hero_key(evidence.hero) in _draw_hero_count_keys()
        or _aisha_partial_red_floor_applies_to_count(key, evidence, count)
    ):
        return _quality_cell_floor_for_count(key, evidence, count)
    return _quality_cell_floor(key, evidence)


def _draw_hero_revealed_cells_exact_for_count(
    key: str,
    evidence: RefEvidence,
    count: int,
) -> int | None:
    """Return exact q6 cells when a draw-hero candidate contains only footprint-known reds.

    A reveal remains a floor while the candidate contains additional hidden reds. When the candidate
    count equals the number of revealed reds that contributed exact footprints, however, no unknown
    red remains: two revealed 1-cell reds in a two-red candidate are exactly two cells, not a fresh
    ``2 * q6_size_prior`` estimate. Scope stays on draw-hero q6, matching the existing output anchor.
    Rollback (core fit + output anchor): DRAW_HERO_DISABLE_EXACT_REVEALED_RED_CELLS=1.
    """
    if key != "q6" or normalize_hero_key(evidence.hero) not in _draw_hero_count_keys():
        return None
    if _run_env_get("DRAW_HERO_DISABLE_EXACT_REVEALED_RED_CELLS") == "1":
        return None
    candidate_count = max(0, int(count))
    floor_items = int((evidence.quality_cell_floor_item_counts or {}).get(key, 0) or 0)
    if candidate_count <= 0 or floor_items <= 0 or candidate_count != floor_items:
        return None
    floor = _quality_cell_floor(key, evidence)
    return floor if floor >= candidate_count else None


def _quality_exact_value(key: str, evidence: RefEvidence) -> float | None:
    value = evidence.quality_values.get(key)
    if value is None:
        return None
    parsed = _safe_float(value)
    if parsed is None or parsed < 0:
        return None
    return parsed


def _quality_value_floor(key: str, evidence: RefEvidence) -> float:
    value = evidence.quality_value_floors.get(key)
    parsed = _safe_float(value)
    if parsed is None or parsed <= 0:
        return 0.0
    return float(parsed)


def _quality_catalog_min_value_floor(key: str, evidence: RefEvidence) -> float:
    value = (evidence.quality_catalog_min_value_floors or {}).get(key)
    parsed = _safe_float(value)
    if parsed is None or parsed <= 0:
        return 0.0
    return float(parsed)


def _quality_min_total_value_floor(key: str, evidence: RefEvidence) -> float:
    value = (evidence.quality_min_total_value_floors or {}).get(key)
    parsed = _safe_float(value)
    if parsed is None or parsed <= 0:
        return 0.0
    return float(parsed)


def _known_item_value_floor(key: str, evidence: RefEvidence) -> float:
    """Combined per-quality floor without double-counting overlapping evidence."""
    return max(
        _quality_value_floor(key, evidence) + _quality_catalog_min_value_floor(
            key, evidence
        ),
        _quality_min_total_value_floor(key, evidence),
    )


def _hard_quality_avg_value_totals(
    evidence: RefEvidence,
) -> dict[str, float]:
    """Return uniquely implied q4/q5 totals from hard count × tier mean.

    Public-origin means additionally require a validated current raw row joined
    to a conflict-free aggregate ledger. Structured/manual means retain the
    existing decimal-interval semantics and do not need public authority.
    """
    if _run_env_get(HARD_QUALITY_AVG_VALUE_QUOTE_FLOOR_DISABLE) == "1":
        return {}
    if evidence.phase == "settled":
        return {}
    totals: dict[str, float] = {}
    for key in ("q4", "q5"):
        count_raw = evidence.fixed_counts.get(key)
        public_origin = f"public_{key}_avg_value" in evidence.source_notes
        avg_raw = (
            evidence.hard_public_avg_values.get(key)
            if public_origin
            else evidence.avg_values.get(key)
        )
        if (
            count_raw is None
            or avg_raw is None
            or key in evidence.soft_avg_value_keys
            or _quality_exact_value(key, evidence) is not None
        ):
            continue
        if public_origin and key not in evidence.hard_public_avg_values:
            continue
        count = int(count_raw)
        avg = _safe_float(avg_raw)
        if count <= 0 or avg is None or avg <= 0.0:
            continue
        if not _quality_count_matches_value_evidence(key, count, evidence):
            continue
        product = float(avg) * count
        if not math.isfinite(product):
            continue
        exact_public_wire = (
            public_origin
            and not _ref_public_avg_value_wire_normalized(evidence, key)
        )
        if exact_public_wire:
            ulp32 = 2.0 ** (math.frexp(float(avg))[1] - 24)
            radius = 0.5 * ulp32 * count
        else:
            radius = _ref_avg_value_product_tolerance(count, float(avg))
        epsilon = max(1e-9, abs(product) * 1e-12)
        lower = math.ceil(product - radius - epsilon)
        upper = math.floor(product + radius + epsilon)
        if lower != upper:
            continue
        totals[key] = float(lower)
    return totals


def _known_quality_value_total_floor(evidence: RefEvidence) -> float:
    """Return the hard lower bound supplied by known per-quality values.

    ``quality_values`` is an exact whole-quality total, while
    the priced-item and exact-footprint item floors cover disjoint revealed
    items within that same quality and are additive. The maximum-footprint
    average floor can overlap either of them, so it is combined by ``max``.
    The resulting floor and exact whole-quality total are alternative bounds.
    Distinct qualities are additive.
    """
    hard_avg_totals = _hard_quality_avg_value_totals(evidence)
    return sum(
        max(
            _quality_exact_value(key, evidence) or 0.0,
            hard_avg_totals.get(key, 0.0),
            _known_item_value_floor(key, evidence),
            float(evidence.shape_average_value_floors.get(key, 0.0) or 0.0),
        )
        for key in QUALITY_KEYS
    )


def _partial_known_quality_value_state(
    key: str,
    *,
    count: int,
    grid: float,
    item_values: dict[str, float],
    evidence: RefEvidence,
) -> tuple[float, int, float, float] | None:
    """Decompose partially revealed quality value into known sum + unknown parts.

    Unknown reds use per-item default value as the hard floor and remaining grid
    cells (total grid minus known cells) for the grid-conditioned center estimate.
    """
    known_sum = _quality_value_floor(key, evidence)
    if known_sum <= 0 or count <= 0:
        return None
    known_count = evidence.quality_value_floor_item_counts.get(key, 0)
    if known_count <= 0 or count <= known_count:
        return None
    known_cells = float(evidence.quality_cell_floors.get(key, 0.0))
    remaining_count = count - known_count
    remaining_grid = max(float(remaining_count), grid - known_cells)
    unknown_default = remaining_count * item_values[key]
    unknown_grid_value = _quality_value_for_grid(
        key,
        count=remaining_count,
        grid=remaining_grid,
        item_values=item_values,
    )
    return known_sum, remaining_count, unknown_default, unknown_grid_value


AISHA_PINNED_RED_CATALOG_FLOOR_DISABLE = (
    "BIDKING_DISABLE_AISHA_PINNED_RED_CATALOG_FLOOR"
)


def _aisha_pinned_red_catalog_value_floor(
    key: str,
    *,
    count: int,
    grid: float,
    evidence: RefEvidence,
) -> float:
    """Catalog floor for a reconciled red residual, scoped to fully pinned Aisha."""
    if (
        key != "q6"
        or _run_env_get(AISHA_PINNED_RED_CATALOG_FLOOR_DISABLE) == "1"
        or normalize_hero_key(evidence.hero) != "aisha"
        or evidence.phase != "bidding"
        or not _is_grid_identity_pass(evidence)
        or not _is_pure_prior_red(evidence)
        or any(
            _exact_integer_quality_cell(evidence.quality_cells.get(nonred)) is None
            for nonred in ("q1", "q3", "q4", "q5")
        )
    ):
        return 0.0
    grid_int = int(round(float(grid)))
    if count <= 0 or grid_int <= 0 or abs(float(grid) - grid_int) > 0.0001:
        return 0.0
    minimum = _catalog_min_total_value_for_quality_count_cells(6, int(count), grid_int)
    return float(minimum or 0)


def _quality_value_floor_for_count(
    key: str,
    *,
    count: int,
    grid: float,
    item_values: dict[str, float],
    evidence: RefEvidence,
) -> float:
    catalog_min = _quality_catalog_min_value_floor(key, evidence)
    quality_total_min = _quality_min_total_value_floor(key, evidence)
    residual_catalog_min = _aisha_pinned_red_catalog_value_floor(
        key,
        count=count,
        grid=grid,
        evidence=evidence,
    )
    known_q6_residual_catalog_min = (
        _q6_known_item_exact_cells_catalog_value_floor(
            key,
            count=count,
            grid=grid,
            evidence=evidence,
        )
    )
    shape_average_min = float(
        evidence.shape_average_value_floors.get(key, 0.0) or 0.0
    )
    partial = _partial_known_quality_value_state(
        key,
        count=count,
        grid=grid,
        item_values=item_values,
        evidence=evidence,
    )
    if partial is not None:
        known_sum, _remaining_count, unknown_default, _unknown_grid_value = partial
        return max(
            known_sum + unknown_default,
            known_sum + catalog_min,
            residual_catalog_min,
            known_q6_residual_catalog_min,
            quality_total_min,
            shape_average_min,
        )
    known_sum = _quality_value_floor(key, evidence)
    if count <= 0:
        return max(
            0.0,
            known_sum + catalog_min,
            residual_catalog_min,
            known_q6_residual_catalog_min,
            quality_total_min,
            shape_average_min,
        )
    return max(
        known_sum + catalog_min,
        residual_catalog_min,
        known_q6_residual_catalog_min,
        quality_total_min,
        shape_average_min,
    )


def _quality_count_matches_value_inputs(
    count: int,
    avg: float | None,
    exact_value: float | None,
) -> bool:
    if (
        exact_value is not None
        and count > 0
        and _avg_value_has_positive_signal(avg)
    ):
        # A public float32 average may be decimal-normalized before it reaches this
        # validator.  In that case its product can sit just outside the narrower
        # single-signal ULP interval even though the independently observed exact
        # quality total identifies the same integer count (4501 Maria R3:
        # 69200.3359375 -> 69200.3, and 69200.3 * 3 = 207600.9 vs total 207601).
        # Validate the paired evidence with the same bounded product tolerance used
        # when deriving the count; otherwise extraction locks the count and
        # enumeration immediately rejects it, spuriously downgrading the public avg.
        return _quality_count_product_tolerance_match(
            count,
            avg,
            exact_value,
        )
    if not _avg_value_count_matches(count, avg):
        return False
    if exact_value is None:
        return True
    if count <= 0:
        return abs(float(exact_value)) <= 0.0001
    if avg is None:
        return exact_value > 0
    derived_total = _avg_value_total_from_count(float(avg), count)
    if derived_total is None:
        return False
    return abs(float(exact_value) - derived_total) <= 0.5


def _quality_count_matches_value_evidence(
    key: str,
    count: int,
    evidence: RefEvidence,
) -> bool:
    exact_value = _quality_exact_value(key, evidence)
    if (
        key in evidence.soft_avg_value_keys
        and evidence.fixed_counts.get(key) is None
        and exact_value is None
    ):
        if key in {"q4", "q5", "q6"} and _catalog_value_joint_projection_enabled(
            key
        ):
            supported_counts = {
                int(candidate_count)
                for candidate_count, _cells in (
                    evidence.quality_count_cells_options or {}
                ).get(key, ())
            }
            if supported_counts:
                return int(count) in supported_counts
            if key != "q4":
                return True
            # With no q4 catalog joint, retain the pre-existing soft-average predicate. Treating an
            # empty projection as "all counts valid" diverges from the q4 candidate filter.
        avg = evidence.avg_values.get(key)
        if not _avg_is_exact_catalog_item_value(key, avg):
            return int(count) != 1
        return _quality_count_matches_value_inputs(
            count,
            avg,
            None,
        )
    # Symmetric to the avg path above (6456-6457): the game's per-item gold(q5) prices are EXACT catalog
    # values, so a single gold item's value must equal some single-item catalog price. When only a TOTAL
    # gold value is known (no avg) and that total matches NO single-item catalog price, it cannot be one
    # item — it is >=2 items summed. The avg path already excludes count=1 for a non-catalog avg; the total
    # path fell through to _quality_count_matches_value_inputs(count, None, exact_value) which returns
    # exact_value>0 for ANY count, letting count=1 slip through unchecked. Gold only (author domain: red
    # has its own residual pipeline); soft/unlocked tier only; relies on the same complete-catalog trust as
    # the avg path (Item.txt + items.json new-item backfill, _apply_exact_catalog_value_locks premise).
    # env AHMAD_DISABLE_GOLD_TOTAL_NONCATALOG_MIN2=1 reverts.
    if (
        os.environ.get("AHMAD_DISABLE_GOLD_TOTAL_NONCATALOG_MIN2") != "1"
        and key == "q5"
        and int(count) == 1
        and evidence.fixed_counts.get(key) is None
        and exact_value is not None
        and evidence.avg_values.get(key) is None
        and not _exact_catalog_contains_value(key, exact_value)
    ):
        return False
    return _quality_count_matches_value_inputs(
        count,
        evidence.avg_values.get(key),
        exact_value,
    )


def _hard_total_grid_target_int(evidence: RefEvidence) -> int | None:
    return _hard_total_grid_target_from_notes(
        evidence.total_grid_target,
        evidence.source_notes,
    )


def _enforce_hard_total_grid_range(
    evidence: RefEvidence,
    grid_range: tuple[int | None, int | None, int | None],
) -> tuple[int | None, int | None, int | None]:
    """Keep a target classified as hard exact at the public display boundary."""
    hard_target = _hard_total_grid_target_int(evidence)
    if hard_target is not None:
        return (hard_target, hard_target, hard_target)
    if len(evidence.total_grid_options) > 1:
        # Every feasible count combo is expanded once per authoritative total-grid arm with
        # the same prior weight.  Rebuild that uniform hard disjunction at the public boundary:
        # hero-specific geometry transforms must neither widen it nor select one arm by prior.
        weighted_options = [
            (float(option), 1.0) for option in evidence.total_grid_options
        ]
        return tuple(
            int(round(_weighted_quantile(weighted_options, quantile)))
            for quantile in (0.10, 0.50, 0.90)
        )
    return grid_range


def _finalize_total_grid_range(
    evidence: RefEvidence,
    grid_range: tuple[int | None, int | None, int | None],
) -> tuple[int | None, int | None, int | None]:
    """Enforce the total-grid contract at the public engine boundary."""
    grid_range = _enforce_hard_total_grid_range(evidence, grid_range)
    if any(value is None for value in grid_range):
        return grid_range

    low, mid, high = sorted(int(value) for value in grid_range if value is not None)
    return (low, mid, high)


def _finalize_published_ref_result(result: RefResult) -> RefResult:
    if not isinstance(result, RefResult):
        # Structural cache tests replace the implementation with a scalar sentinel. Production
        # implementations always return RefResult; keep the wrapper transparent to test doubles.
        return result
    if TOTAL_AVG_CELLS_GRID_SUPPORT_INCOMPLETE_NOTE in result.notes:
        # The evidence still records the authoritative arms for diagnostics,
        # but no display finalizer may project them over an unmaterialized joint.
        return result
    final_range = _finalize_total_grid_range(result.evidence, result.total_grid_range)
    if final_range != result.total_grid_range:
        result = replace(result, total_grid_range=final_range)
    result = _floor_published_quality_cells_to_counts(result)
    return _apply_ahmed_public_q4_reachable_tail_display(result)


def _floor_published_quality_cells_to_counts(result: RefResult) -> RefResult:
    """Keep every published quality arm physically possible without inventing absent cells."""

    if _run_env_get("BIDKING_DISABLE_QUALITY_CELL_COUNT_FLOOR_HOTFIX2") == "1":
        return result
    count_ranges = result.quality_count_ranges
    cell_ranges = result.quality_cells_ranges
    if not isinstance(count_ranges, dict) or not isinstance(cell_ranges, dict):
        return result
    updated = dict(cell_ranges)
    changed_notes: list[str] = []
    for key in QUALITY_KEYS:
        counts = count_ranges.get(key)
        cells = cell_ranges.get(key)
        if not counts or not cells or len(counts) != 3 or len(cells) != 3:
            continue
        new_cells: list[int | None] = []
        for count, cell in zip(counts, cells, strict=True):
            if cell is None or count is None:
                new_cells.append(cell)
            else:
                new_cells.append(max(int(cell), int(count)))
        new_range = tuple(new_cells)
        old_range = tuple(cells)
        if new_range != old_range:
            updated[key] = new_range
            changed_notes.append(
                "quality_cells_per_item_floor:"
                f"{key}:" + "/".join(str(value) for value in old_range)
                + "->" + "/".join(str(value) for value in new_range)
            )
    if not changed_notes:
        return result
    red_cells_range = result.red_cells_range
    if "q6" in updated:
        red_cells_range = tuple(updated["q6"])
    return replace(
        result,
        quality_cells_ranges=updated,
        red_cells_range=red_cells_range,
        notes=tuple(dict.fromkeys((*result.notes, *changed_notes))),
    )


def _aisha_q5q6_correlated_physical_grid_floors(
    evidence: RefEvidence,
    quality_count_ranges: Mapping[str, Sequence[int | None]],
    quality_cells_ranges: Mapping[str, Sequence[int | None]],
) -> tuple[int, int, int] | None:
    """Hard per-arm grid floors when only gold/red counts remain complementary.

    With exact total/q1/q3/q4 counts and cells, a hard gold average makes each displayed q5
    count/cells arm arithmetic.  Red is its exact count complement; align the red count/cells marginal
    back to those complementary arms before flooring the total.  A later spatial cap may narrow an
    estimate, but it cannot publish a total below that composition (5608 R4 otherwise became 2 red
    items in 0 cells with zero value).
    """
    if (
        _run_env_get(AISHA_Q5Q6_CORRELATED_PHYSICAL_GUARD_DISABLE) == "1"
        or normalize_hero_key(evidence.hero) != "aisha"
        or evidence.phase == "settled"
        or evidence.total_count is None
        or _hard_total_grid_target_int(evidence) is not None
        or evidence.fixed_counts.get("q5") is not None
        or evidence.fixed_counts.get("q6") is not None
        or "q5" in evidence.soft_avg_cell_keys
        or float(evidence.avg_cells.get("q5") or 0.0) <= 0.0
        or not _is_pure_prior_red(evidence)
    ):
        return None

    fixed_count_total = 0
    fixed_cell_total = 0
    for key in ("q1", "q3", "q4"):
        fixed = evidence.fixed_counts.get(key)
        exact_cells = _quality_exact_cells(key, evidence)
        count_range = quality_count_ranges.get(key)
        cells_range = quality_cells_ranges.get(key)
        if (
            fixed is None
            or exact_cells is None
            or not count_range
            or not cells_range
            or len(count_range) != 3
            or len(cells_range) != 3
            or any(value is None or int(value) != int(fixed) for value in count_range)
            or any(value is None or int(value) != int(exact_cells) for value in cells_range)
        ):
            return None
        fixed_count_total += int(fixed)
        fixed_cell_total += int(exact_cells)

    residual_count = int(evidence.total_count) - fixed_count_total
    q5_counts = quality_count_ranges.get("q5")
    q5_cells = quality_cells_ranges.get("q5")
    q6_counts = quality_count_ranges.get("q6")
    q6_cells = quality_cells_ranges.get("q6")
    if (
        residual_count < 0
        or not q5_counts
        or not q5_cells
        or not q6_counts
        or not q6_cells
        or len(q5_counts) != 3
        or len(q5_cells) != 3
        or len(q6_counts) != 3
        or len(q6_cells) != 3
        or len({int(value) for value in q5_counts if value is not None}) <= 1
    ):
        return None

    desired_q6_counts: list[int] = []
    for raw_count in q5_counts:
        if raw_count is None:
            return None
        desired = residual_count - int(raw_count)
        if desired < 0:
            return None
        desired_q6_counts.append(desired)
    unused_q6_indexes = list(range(3))
    aligned_q6_cells: list[int] = []
    for desired in desired_q6_counts:
        match = next(
            (
                index
                for index in unused_q6_indexes
                if q6_counts[index] is not None
                and int(q6_counts[index]) == int(desired)
            ),
            None,
        )
        if match is None or q6_cells[match] is None:
            return None
        red_cells = int(q6_cells[match])
        if red_cells < desired or (desired == 0 and red_cells != 0):
            return None
        unused_q6_indexes.remove(match)
        aligned_q6_cells.append(red_cells)

    floors: list[int] = []
    q5_avg = float(evidence.avg_cells["q5"])
    for raw_count, raw_cells, q6_grid in zip(q5_counts, q5_cells, aligned_q6_cells):
        if raw_count is None or raw_cells is None:
            return None
        q5_count = int(raw_count)
        q5_grid = int(raw_cells)
        if q5_count < 0 or q5_count > residual_count:
            return None
        if q5_grid not in _avg_grid_options(q5_count, q5_avg, "q5"):
            return None
        floors.append(fixed_cell_total + q5_grid + int(q6_grid))
    return tuple(floors)


def _is_grid_identity_pass(evidence: RefEvidence) -> bool:
    """族D pass 2: total_grid_target is the engine's own anchored total, re-injected to reconcile the
    tiers. Distinguishable from a real tool total by its note (see GRID_IDENTITY_RECONCILE_NOTE_PREFIX)."""
    return any(
        str(note).startswith(GRID_IDENTITY_RECONCILE_NOTE_PREFIX)
        for note in evidence.source_notes
    )


def _soft_total_grid_floor_int(evidence: RefEvidence) -> int | None:
    """Soft lower bound on total grid cells from a `total_grid_floor:<N>` note (unpinned-tail
    experiment). Unlike the hard target, grids only have to sum to AT LEAST this — the range is
    free to expand above it via minimap/footroom."""
    for note in evidence.source_notes:
        if note.startswith(TOTAL_GRID_FLOOR_NOTE_PREFIX):
            try:
                return int(note[len(TOTAL_GRID_FLOOR_NOTE_PREFIX):])
            except ValueError:
                return None
    return None


def _split_low_quality_q1_floor_parts_from_maps(
    split_counts: dict[str, int],
    split_quality_cells: dict[str, float],
) -> tuple[int, int, int]:
    count_floor = 0
    exact_count_for_cells = 0
    exact_cells = 0
    for split_key in LOW_SPLIT_KEYS:
        raw_count = split_counts.get(split_key)
        raw_cells = split_quality_cells.get(split_key)
        count = max(0, int(raw_count)) if raw_count is not None else None
        cells = None
        if raw_cells is not None:
            cells = max(0, int(round(float(raw_cells))))

        if count is not None:
            count_floor += count
        elif cells is not None and cells > 0:
            count_floor += max(1, int(math.ceil(cells / 18.0)))

        if cells is None:
            continue
        if count is None:
            count_for_cells = 0 if cells == 0 else max(1, int(math.ceil(cells / 18.0)))
        else:
            count_for_cells = count
        exact_count_for_cells += count_for_cells
        exact_cells += cells
    return count_floor, exact_count_for_cells, exact_cells


def _split_low_quality_q1_grid_extra_from_maps(
    split_counts: dict[str, int],
    split_quality_cells: dict[str, float],
) -> int:
    _count_floor, exact_count_for_cells, exact_cells = _split_low_quality_q1_floor_parts_from_maps(
        split_counts,
        split_quality_cells,
    )
    return max(0, exact_cells - exact_count_for_cells)


def _split_low_quality_q1_count_floor(evidence: RefEvidence) -> int:
    count_floor, _exact_count_for_cells, _exact_cells = _split_low_quality_q1_floor_parts_from_maps(
        evidence.split_counts,
        evidence.split_quality_cells,
    )
    return count_floor


def _split_low_quality_q1_grid_floor(count: int, evidence: RefEvidence) -> int:
    if count <= 0:
        return 0
    return int(count) + _split_low_quality_q1_grid_extra_from_maps(
        evidence.split_counts,
        evidence.split_quality_cells,
    )


def _split_low_quality_q1_grid_matches(
    count: int,
    grid: float,
    evidence: RefEvidence,
) -> bool:
    floor = _split_low_quality_q1_grid_floor(count, evidence)
    return float(grid) + 1e-6 >= float(floor)


def _default_total_count(map_id: int | None) -> int:
    calibrated = _SHIPWRECK_CALIBRATED_PRIOR.get()
    if calibrated is not None and calibrated['map_id'] == map_id:
        return int(round(calibrated['count_mean']))
    if map_id is None:
        return 28
    family = int(map_id) // 100
    if family in {21, 22}:
        return 24
    if family == 23:
        return 27
    if family in {25, 45}:
        return 33
    if family == 24:
        return 28
    if family == 26:
        return 33
    if family == 56 and not os.environ.get("AHMAD_DISABLE_RANK56_COUNT_CENTER"):
        # 56xx 排位图真实仓远大于 classic 28: §5 实测 637 局结算真值件数中位 37(均值 36.9,
        # range 10-51),且**逐图中位高度收敛在 36-38**(5601-5611 每图)→ 单一中心 37 即可,
        # 逐图细分(±1)收益微小不做。bd3119e 只接了品质先验(q6 5%→10%)未接件数中心 →
        # 非 ahmed 英雄(ethan/aisha/sophie/gabriela)在 56xx 件数/格子/价值系统性欠 ~24%;
        # ahmed 走公开极品存量硬锁不受此默认中心影响。env AHMAD_DISABLE_RANK56_COUNT_CENTER=1 回退 28。
        return 37
    return 28


