def _empirical_count_prior_036(
    snapshot: Any, evidence: RefEvidence,
) -> tuple[int, int] | None:
    """Select a soft map prior from this call's current, non-player context.

    No context is cached across calls; no revealed/settlement truth is read.
    Explicit N, other heroes/generations, conflicting mirrors and player-owned
    warehouses retain their existing behavior. Unknown/open provenance can use
    an empirical prior without being relabeled official.
    """
    if (
        _run_env_get(EMPIRICAL_COUNT_PRIOR_036_DISABLE) == "1"
        or normalize_hero_key(evidence.hero) not in {"ahmed", "aisha"}
        or evidence.phase not in {"reading", "bidding"}
        or evidence.total_count is not None
        or type(evidence.map_id) is not int
        or evidence.map_id not in EMPIRICAL_COUNT_PRIOR_036_CENTERS
        or _SHIPWRECK_CALIBRATED_PRIOR.get() is not None
    ):
        return None
    root = _exact_warehouse_quote_source_dict(snapshot)
    if root is None:
        return None
    owners = [root]
    if "ui_contract" in root:
        ui = _exact_warehouse_quote_source_dict(root["ui_contract"])
        if ui is None:
            return None
        for key in ("context", "source"):
            if key in ui:
                owner = _exact_warehouse_quote_source_dict(ui[key])
                if owner is None:
                    return None
                owners.append(owner)
    mid = evidence.map_id
    generation = EMPIRICAL_COUNT_PRIOR_036_GENERATION
    sessions, stability, sources = [], [], []
    for owner in owners:
        if "hero" in owner and owner["hero"] is not None:
            if type(owner["hero"]) is not str or normalize_hero_key(owner["hero"]) != normalize_hero_key(evidence.hero):
                return None
        if "hero_id" in owner and owner["hero_id"] is not None:
            raw_hero = owner["hero_id"]
            if type(raw_hero) not in (int, str) or re.fullmatch(r"[0-9]+", str(raw_hero)) is None:
                return None
            if HERO_BY_ID.get(int(raw_hero)) != normalize_hero_key(evidence.hero):
                return None
        for key in ("map_id", "model_map_id"):
            if key in owner and owner[key] is not None:
                value = owner[key]
                if type(value) not in (int, str) or str(value) != str(mid):
                    return None
        if owner.get("map_alias") or owner.get("map_alias_mode"):
            return None
        if "phase" in owner and owner["phase"] != evidence.phase:
            return None
        if "session_id" in owner:
            sessions.append(owner["session_id"])
        if "warehouse_game_version_session_stable" in owner:
            stability.append(owner["warehouse_game_version_session_stable"])
        for key in ("warehouse_source_generation", "game_version"):
            if key in owner and (type(owner[key]) is not str or owner[key] != generation):
                return None
        if "warehouse_source" in owner:
            source = _exact_warehouse_quote_source_dict(owner["warehouse_source"])
            if source is None:
                return None
            sources.append(source)
    if (
        not sessions
        or any(type(s) is not str or s != sessions[0] for s in sessions)
        or not stability or any(value is not True for value in stability)
        or not sources
    ):
        return None
    session_match = re.fullmatch(rf"{mid}:([1-9][0-9]{{0,19}})", sessions[0])
    if session_match is None:
        return None
    runtime_epoch = int(session_match.group(1))
    if runtime_epoch >= 2**64:
        return None
    # Both optional aliases name the same runtime epoch, not two independent
    # mirror groups. Accept canonical wire text or integers, never coercions.
    for owner in owners:
        for key in ("epoch", "session_epoch"):
            if key in owner and type(owner[key]) is str and len(owner[key]) > 20:
                return None
            if key in owner and _ahmed_q1_q5_context_wire_int(
                owner[key], text=type(owner[key]) is str, minimum=1,
            ) != runtime_epoch:
                return None
    qualification = sources[0].get("qualification")
    if type(qualification) is not str or qualification not in {"official_random_warehouse", "postupdate_unknown_warehouse_source"}:
        return None
    expected = {
        "qualification": qualification, "map_id": mid, "table_status": "verified",
        "source_generation": generation, "map_profile_generation": generation,
        "game_version": generation, "map_table_build": "25795126",
        "owner_evidence_status": "absent", "source_conflict": False,
        "quarantine_required": False, "config": None,
        "official_distribution_eligible": qualification == "official_random_warehouse",
        "map_table_sha256": "7abe97f33ec48c8b18887de5abcddc1969b5decc2b9be30b1f8fd73f5b71c9fc",
        "expected_map_table_sha256": "7abe97f33ec48c8b18887de5abcddc1969b5decc2b9be30b1f8fd73f5b71c9fc",
        "map_source_contract_sha256": "b6e0635f8033bb20dbac7a6c6a985fe5bd4d923da1bf9a2d3d21dd524273a6f3",
        "expected_map_source_contract_sha256": "b6e0635f8033bb20dbac7a6c6a985fe5bd4d923da1bf9a2d3d21dd524273a6f3",
    }
    for source in sources:
        if any(key not in source or type(source[key]) is not type(want) or source[key] != want for key, want in expected.items()):
            return None
    for owner in owners:
        for key, want in (("warehouse_source_qualification", qualification), ("official_distribution_eligible", expected["official_distribution_eligible"])):
            if key in owner and (type(owner[key]) is not type(want) or owner[key] != want):
                return None
    return EMPIRICAL_COUNT_PRIOR_036_CENTERS[mid]


def _known_count_floor(evidence: RefEvidence) -> int:
    fixed_total = sum(max(0, int(value)) for value in evidence.fixed_counts.values())
    # Preserve the legacy non-additive presence floor. Positive avg/cells/value signals can imply
    # "this tier exists", but some of those signals are soft or display-facing and must not be added
    # on top of every fixed tier (E15: doing so raises the no-red low arm from 0 to a 20-cell red).
    legacy_presence_total = sum(_effective_min_count(key, evidence) for key in QUALITY_KEYS)
    quality_floors: dict[str, int] = {}
    for key in QUALITY_KEYS:
        fixed = evidence.fixed_counts.get(key)
        if fixed is not None:
            quality_floors[key] = max(0, int(fixed))
            continue
        explicit_minimum = max(0, int(evidence.min_counts.get(key, 0)))
        if key == "q1":
            explicit_minimum = max(
                explicit_minimum,
                _split_low_quality_q1_count_floor(evidence),
            )
        avg_minimum = _hard_avg_cells_min_count(key, evidence) or 0
        quality_floors[key] = max(explicit_minimum, int(avg_minimum))
    total_floor = sum(quality_floors.values())
    for group_key, keys in (
        ("q4q5", ("q4", "q5")),
        ("q5q6_min", ("q5", "q6")),
        ("q4q5q6", ("q4", "q5", "q6")),
    ):
        group_total = evidence.count_sums.get(group_key)
        if group_total is None:
            continue
        member_floor = sum(quality_floors[key] for key in keys)
        total_floor = max(
            total_floor,
            total_floor - member_floor + max(0, int(group_total)),
        )
    return max(fixed_total, legacy_presence_total, total_floor)


def _fixed_quality_counts_exhaust_total_grid(evidence: RefEvidence) -> bool:
    """Whether fixed quality counts consume the exact total and every occupied tier has exact cells."""
    if evidence.total_count is None:
        return False
    fixed_total = sum(max(0, int(value)) for value in evidence.fixed_counts.values())
    if fixed_total != int(evidence.total_count):
        return False
    for key, raw_count in evidence.fixed_counts.items():
        count = max(0, int(raw_count))
        if count <= 0:
            continue
        if _quality_exact_cells(key, evidence) is not None:
            continue
        avg = evidence.avg_cells.get(key)
        if avg is None or key in evidence.soft_avg_cell_keys:
            return False
        if len(_avg_grid_options_for_evidence(count, float(avg), key, evidence)) != 1:
            return False
    return True


def _positive_quality_cell_keys(evidence: RefEvidence) -> list[str]:
    return [
        key
        for key, value in evidence.quality_cells.items()
        if (_safe_float(value) or 0.0) > 0.0001
    ]


def _quality_cells_fully_pinned(evidence: RefEvidence) -> bool:
    """True when every positive quality_cells tier also has a matching fixed count."""
    keys = _positive_quality_cell_keys(evidence)
    if len(keys) < 2:
        return False
    for key in keys:
        fixed = evidence.fixed_counts.get(key)
        cells = _quality_exact_cells(key, evidence)
        if fixed is None or cells is None:
            return False
        if not _can_compose_grid_total_with_q6_catalog(key, int(fixed), int(cells)):
            return False
    return True


def _quality_cells_blocks_sparse_exact_prior(evidence: RefEvidence) -> bool:
    if not evidence.quality_cells:
        return False
    positive_keys = [
        key
        for key, value in evidence.quality_cells.items()
        if (_safe_float(value) or 0.0) > 0.0001
    ]
    # One tier total-cells hint (e.g. public 200011 gold cells) still leaves the
    # count split underdetermined; the prior sampler can honor it via
    # _quality_exact_cells. Multiple tier totals need the full search path.
    return len(positive_keys) >= 2


def _should_use_sparse_exact_total_prior(evidence: RefEvidence) -> bool:
    if evidence.total_count is None or evidence.phase == "settled":
        return False
    pinned_quality_cells = _quality_cells_fully_pinned(evidence)
    if evidence.count_sums:
        return False
    if _quality_cells_blocks_sparse_exact_prior(evidence) and not pinned_quality_cells:
        return False
    nonzero_fixed_count = sum(1 for value in evidence.fixed_counts.values() if int(value) > 0)
    if nonzero_fixed_count > 1:
        if not pinned_quality_cells:
            return False
        # The pinned-cells + many-fixed sparse-prior route is an Aisha hidden-sample
        # perf path (avoids high-total enumeration blowup). Other heroes keep exact
        # enumeration so pinned red-reveal states resolve to status "ok" rather than
        # falling back to count_prior.
        if normalize_hero_key(evidence.hero) != "aisha":
            return False
        if evidence.total_count is None or int(evidence.total_count) < 40:
            return False
    if nonzero_fixed_count == 1 and len(evidence.avg_cells) > 2 and not pinned_quality_cells:
        return False
    # Exact total count alone still leaves the count split underdetermined. Use the
    # probability prior sampler instead of full nested enumeration so live/manual
    # sparse states stay responsive without relying on max_combos truncation order.
    return True


def _sparse_exact_high_total_tight_prior(evidence: RefEvidence) -> bool:
    if evidence.total_count is None or int(evidence.total_count) < 50:
        return False
    if not _should_use_sparse_exact_total_prior(evidence):
        return False
    fixed_nonzero = sum(1 for value in evidence.fixed_counts.values() if int(value) > 0)
    return fixed_nonzero <= 2


