def _apply_ahmed_public_q4_reachable_tail_display(result: RefResult) -> RefResult:
    """Restore Ahmed public-q4 reachable support at the final display boundary only."""
    evidence = result.evidence
    if (
        _run_env_get(AHMED_PUBLIC_Q4_REACHABLE_TAIL_DISPLAY_DISABLE) == "1"
        or not _ahmed_public_q4_avg_antilock_enabled("q4", evidence)
        or f"{AVG_MULTIPLE_WIDEN_NOTE_PREFIX}q4" not in result.notes
        or result.quality_lock.get("q4")
        != {"strength": "probabilistic", "reason": "combo_multi_solution"}
    ):
        return result

    old_count_range = result.quality_count_ranges.get("q4")
    old_cells_range = result.quality_cells_ranges.get("q4")
    count_candidates = result.quality_count_candidates.get("q4", ())
    joint_candidates = result.quality_count_cells_candidates.get("q4", ())
    if (
        not old_count_range
        or not old_cells_range
        or any(value is None for value in old_count_range)
        or any(value is None for value in old_cells_range)
        or len({int(value) for value in old_count_range if value is not None}) != 1
    ):
        return result

    center_count = int(old_count_range[1])
    reachable_support = sorted(
        {
            int(value)
            for value, probability in count_candidates
            if float(probability) > 0.0
        }
    )
    lower = [count for count in reachable_support if count < center_count]
    upper = [count for count in reachable_support if count > center_count]
    low_count = lower[-1] if lower else center_count
    high_count = upper[0] if upper else center_count
    if low_count == center_count == high_count:
        return result

    def cells_for_count(count: int, fallback: int | None) -> int | None:
        rows = [
            (int(cells), float(probability))
            for candidate_count, cells, probability in joint_candidates
            if int(candidate_count) == count and float(probability) > 0.0
        ]
        if not rows:
            return fallback
        return max(rows, key=lambda row: (row[1], -row[0]))[0]

    low_cells = cells_for_count(low_count, old_cells_range[0])
    high_cells = cells_for_count(high_count, old_cells_range[2])
    quality_count_ranges = dict(result.quality_count_ranges)
    quality_cells_ranges = dict(result.quality_cells_ranges)
    quality_count_ranges["q4"] = (low_count, center_count, high_count)
    quality_cells_ranges["q4"] = (
        low_cells,
        old_cells_range[1],
        high_cells,
    )
    return replace(
        result,
        quality_count_ranges=quality_count_ranges,
        quality_cells_ranges=quality_cells_ranges,
        notes=tuple(
            dict.fromkeys(
                (
                    *result.notes,
                    AHMED_PUBLIC_Q4_AVG_ANTILOCK_NOTE,
                    AHMED_PUBLIC_Q4_REACHABLE_TAIL_DISPLAY_NOTE,
                )
            )
        ),
    )
