def _ahmed_q4_arm_probability(value: Any) -> float | None:
    """Normalize one posterior mass without coercing malformed metadata."""

    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    try:
        probability = float(value)
    except (OverflowError, TypeError, ValueError):
        return None
    if (
        not math.isfinite(probability)
        or probability < 0.0
        or probability > 1.0
    ):
        return None
    return probability


def _ahmed_q4_arm_probability_eligible(value: Any) -> bool:
    probability = _ahmed_q4_arm_probability(value)
    return (
        probability is not None
        and probability >= AHMED_NONOFFICIAL_Q4_ARM_MIN_POSTERIOR
    )


def _ahmed_q4_arm_summary_eligible(row: Any) -> bool:
    if not isinstance(row, (tuple, list)) or len(row) < 3:
        return False
    return _ahmed_q4_arm_probability_eligible(row[2])


def _risk_ceiling_exceeds_ordinary(risk_value: Any, ordinary_value: Any) -> bool:
    if (
        isinstance(risk_value, bool)
        or isinstance(ordinary_value, bool)
        or not isinstance(risk_value, (int, float))
        or not isinstance(ordinary_value, (int, float))
    ):
        return False
    try:
        risk = float(risk_value)
        ordinary = float(ordinary_value)
    except (OverflowError, TypeError, ValueError):
        return False
    return (
        math.isfinite(risk)
        and math.isfinite(ordinary)
        and risk > ordinary
    )


