def _exact_total_q1_avg_domain_untighten_enabled(evidence: RefEvidence) -> bool:
    if os.environ.get("AHMAD_DISABLE_EXACT_TOTAL_Q1_AVG_DOMAIN") == "1":
        return False
    if evidence.fixed_counts.get("q1") is not None:
        return False
    if evidence.avg_cells.get("q1") is None:
        return False
    return _sparse_exact_high_total_tight_prior(evidence)


def _ahmed_public_q4_avg_antilock_enabled(
    key: str,
    evidence: RefEvidence,
) -> bool:
    """Keep a public-only purple mean from masquerading as an exact count.

    A public mean still constrains a positive q4 count to a composable footprint,
    but it does not choose between feasible count multiples.  On Ahmed's sparse
    exact-total path the multinomial window can contain only the first multiple;
    that is a prior truncation, not a game-provided count lock.
    """
    return (
        _run_env_get(AHMED_PUBLIC_Q4_AVG_ANTILOCK_DISABLE) != "1"
        and key == "q4"
        and normalize_hero_key(evidence.hero) == "ahmed"
        and key in evidence.soft_avg_cell_keys
        and evidence.fixed_counts.get(key) is None
        and evidence.total_count is not None
    )


def _ahmed_q1_residual_display_antilock_enabled(evidence: RefEvidence) -> bool:
    """Do not render a low-probability zero-red arm as an impossible outcome.

    A hard q1 mean can leave several exact count multiples.  Ahmed 2549 R3 kept
    q1=21/q6=0 in the combo posterior, but its 3.4% mass sat below p10, so both
    tiers rendered as zero-width 14/7 ranges.  This is a display uncertainty
    repair only; combo weights and quote percentiles stay unchanged.
    """
    return (
        _run_env_get(AHMED_Q1_RESIDUAL_DISPLAY_ANTILOCK_DISABLE) != "1"
        and normalize_hero_key(evidence.hero) == "ahmed"
        and evidence.phase != "settled"
        and evidence.total_count is not None
        and evidence.fixed_counts.get("q1") is None
        and evidence.fixed_counts.get("q6") is None
        and (evidence.avg_cells.get("q1") or 0.0) > 0
        and "q1" not in evidence.soft_avg_cell_keys
        and int(evidence.min_counts.get("q6", 0) or 0) == 0
        and evidence.avg_cells.get("q6") is None
        and evidence.quality_cells.get("q6") is None
    )


def _ahmed_q1_q6_positive_residual_antilock_candidate(
    evidence: RefEvidence,
) -> bool:
    """Recognize the positive-red q1-average contract independent of rollback.

    Ahmed 2502 R3 had an exact total plus hard q1/q4/q5 footprint means and
    exact q3/q5 counts. The full arithmetic support retained both
    ``q1=16/q6=2`` and ``q1=8/q6=10``. The latter carried less than the public
    candidate threshold, so the API dropped it and then labelled the remaining
    row as ``derived_single_solution``. A display threshold may hide clutter;
    it must never upgrade a multi-solution posterior into game-provided truth.

    Direct q1/q4/q6 facts, a hard total grid, soft means, conflicts, settlement
    and other heroes remain untouched. Quote weights stay unchanged; this is a
    support/publication repair, not single-sample prior calibration.
    """

    in_scope = bool(
        normalize_hero_key(evidence.hero) == "ahmed"
        and evidence.phase == "bidding"
        and evidence.total_count is not None
        and evidence.total_grid_target is None
        and not evidence.total_grid_options
        and _has_explicit_total_count_source(evidence.source_notes)
        and set(evidence.fixed_counts) == {"q3", "q5"}
        and (evidence.avg_cells.get("q1") or 0.0) > 0.0
        and (evidence.avg_cells.get("q4") or 0.0) > 0.0
        and (evidence.avg_cells.get("q5") or 0.0) > 0.0
        and not {"q1", "q4", "q5"}.intersection(evidence.soft_avg_cell_keys)
        and not _quality_has_evidence_beyond_avg_cells("q1", evidence)
        and not _quality_has_evidence_beyond_avg_cells("q4", evidence)
        and not _quality_has_direct_count_grid_value_evidence("q6", evidence)
        and not any(
            type(note) is not str or "conflict" in note
            for note in evidence.source_notes
        )
    )
    if not in_scope:
        return False

    # Prove from the hard arithmetic that every feasible sibling leaves a
    # positive q6 residual.  This is the generic distinction between 2502 and
    # the older 2549 zero-red family: both have the same evidence *shape*, but
    # 2549 can fill the exact total with q1+q3+q4+q5 and must retain its legacy
    # enumeration.  The proof uses the existing physical avg-cell domains; it
    # is not keyed to a map, price, count or captured sample.
    total = int(evidence.total_count or 0)
    fixed_nonred = sum(
        int(evidence.fixed_counts[key]) for key in ("q3", "q5")
    )
    feasible_by_key: dict[str, tuple[int, ...]] = {}
    for key in ("q1", "q4"):
        avg = _safe_float(evidence.avg_cells.get(key))
        if avg is None or avg <= 0.0:
            return False
        minimum = _effective_min_count(key, evidence)
        ceiling = min(total, _physical_count_ceiling(total, key, evidence))
        feasible_counts = tuple(
            count
            for count in range(minimum, ceiling + 1)
            if _avg_grid_options_for_evidence(count, avg, key, evidence)
        )
        if not feasible_counts:
            return False
        feasible_by_key[key] = feasible_counts
    physical_pairs = tuple(
        (q1, total - fixed_nonred - q1 - q4)
        for q1 in feasible_by_key["q1"]
        for q4 in feasible_by_key["q4"]
        if total - fixed_nonred - q1 - q4 >= 0
    )
    return bool(
        physical_pairs
        and len({q1 for q1, _q6 in physical_pairs}) > 1
        and len({q6 for _q1, q6 in physical_pairs}) > 1
        and all(q6 > 0 for _q1, q6 in physical_pairs)
    )


def _ahmed_q1_q6_positive_residual_antilock_enabled(
    evidence: RefEvidence,
) -> bool:
    """Keep a positive-red q1-average sibling arm from masquerading as exact."""

    return bool(
        _run_env_get(AHMED_Q1_Q6_POSITIVE_RESIDUAL_ANTILOCK_DISABLE) != "1"
        and _ahmed_q1_q6_positive_residual_antilock_candidate(evidence)
    )


def _ahmed_q5_residual_display_antilock_enabled(evidence: RefEvidence) -> bool:
    """Keep an avg-feasible zero-red gold sibling visible at the API boundary.

    Ahmed 4509 R5 fixes q1/q3 and resolves q4 from exact value plus footprint mean. The remaining
    ten items have two physical splits: q5=5/q6=5 and q5=10/q6=0. The latter survives the posterior
    but sits below p10, so both tiers render as exact 5/5 even though ``quality_lock`` is
    probabilistic. This gate is deliberately limited to that evidence family; the late projection
    changes no weights, quotes, total-grid policy, or internal red-tail decision.
    """
    return bool(
        _run_env_get(AHMED_Q5_RESIDUAL_DISPLAY_ANTILOCK_DISABLE) != "1"
        and normalize_hero_key(evidence.hero) == "ahmed"
        and evidence.phase != "settled"
        and evidence.total_count is not None
        and evidence.total_grid_target is None
        and {"q1", "q3"}.issubset(evidence.fixed_counts)
        and evidence.fixed_counts.get("q5") is None
        and evidence.fixed_counts.get("q6") is None
        and (evidence.avg_cells.get("q5") or 0.0) > 0.0
        and "q5" not in evidence.soft_avg_cell_keys
        and (evidence.avg_cells.get("q4") or 0.0) > 0.0
        and evidence.quality_values.get("q4") is not None
        and bool((evidence.quality_count_cells_options or {}).get("q4"))
        and not _quality_has_direct_count_grid_value_evidence("q6", evidence)
    )


def _ahmed_q5_avg_overbound_fail_open_enabled(
    evidence: RefEvidence,
    *,
    published_count_range: tuple[int | None, int | None, int | None],
) -> bool:
    """Suppress a projected q5 singleton when the hard mean still permits >6 items.

    Ahmed 5609 exposes an exact total plus a hard q5 footprint mean.  The physical
    domain correctly retains the integer-product arms 6/12/18/24, but the prior
    posterior can push every arm above six below the public display threshold.  A
    displayed q5=6 then becomes an apparent exact lock and its residual can create
    six nonexistent reds.  Hotfix1 does not attempt the deferred >5 composition
    solver: it publishes no derived lock or quote for this incomplete shape instead.
    """
    visible_counts = {
        int(value) for value in published_count_range if value is not None
    }
    if not (
        _run_env_get(AHMED_Q5_AVG_OVERBOUND_FAIL_OPEN_DISABLE) != "1"
        and normalize_hero_key(evidence.hero) == "ahmed"
        and evidence.map_id == 5609
        and evidence.phase == "bidding"
        and evidence.total_count is not None
        and _has_explicit_total_count_source(evidence.source_notes)
        and evidence.total_grid_target is None
        and evidence.fixed_counts.get("q5") is None
        and (evidence.avg_cells.get("q5") or 0.0) > 0.0
        and "q5" not in evidence.soft_avg_cell_keys
        and "skill_1002041_q5_avg_cells" in evidence.source_notes
        and "public_q5_avg_cells" not in evidence.source_notes
        and not _quality_has_evidence_beyond_avg_cells("q5", evidence)
        and not _quality_has_direct_count_grid_value_evidence("q6", evidence)
        and len(visible_counts) == 1
    ):
        return False
    total = int(evidence.total_count or 0)
    ceiling = _physical_count_ceiling(total, "q5", evidence)
    physical_count_support = {
        count
        for count in range(1, ceiling + 1)
        if _avg_grid_options_for_evidence(
            count,
            float(evidence.avg_cells.get("q5") or 0.0),
            "q5",
            evidence,
        )
    }
    return len(physical_count_support) > 1 and max(physical_count_support) > 6


def _complete_gt5_physical_count_domains(
    evidence: RefEvidence,
) -> dict[str, tuple[int, ...]]:
    """Return complete count domains proved by one physical >5 constraint.

    The multinomial prior ranks warehouse compositions; it is not allowed to
    delete a count that still satisfies an exact count/cells equation or a
    catalog-backed joint domain.  This helper builds only the per-quality
    *physical* count domain.  The normal warehouse enumerator still intersects
    it with total count/cells, every sibling quality, map/phase evidence and the
    existing value posterior.

    Averages never become ``fixed_counts`` here.  Float32 average-cells rows are
    converted to their integer, catalog-composable count/cells arms, while
    average-value rows participate only through the canonical catalog joint
    states already stored in ``quality_count_cells_options``.
    """
    if (
        _run_env_get(COMPLETE_GT5_JOINT_SUPPORT_DISABLE) == "1"
        or evidence.phase != "bidding"
        or evidence.total_count is None
        or type(evidence.total_count) is not int  # noqa: E721 - normalized scalar
        or evidence.total_count <= 5
        # Specialized Ahmed contracts own these exact evidence shapes.  The
        # generic >5 publisher must stay out even when either specialized kill
        # switch is set, so each rollback still reproduces its exact parent.
        or _ahmed_q1_q6_positive_residual_antilock_candidate(evidence)
        or _ahmed_q1_q5_empty_support_antilock_candidate(evidence)
        or any(
            type(note) is not str  # noqa: E721 - stable internal note boundary
            or "conflict" in note
            for note in evidence.source_notes
        )
    ):
        return {}

    total = int(evidence.total_count)
    domains: dict[str, tuple[int, ...]] = {}
    joint_options = evidence.quality_count_cells_options or {}
    legacy_5609_false_lock_requested = bool(
        _run_env_get(AHMED_Q5_AVG_OVERBOUND_FAIL_OPEN_DISABLE) == "1"
        and normalize_hero_key(evidence.hero) == "ahmed"
        and evidence.map_id == 5609
        and "skill_1002041_q5_avg_cells" in evidence.source_notes
        and "public_q5_avg_cells" not in evidence.source_notes
    )
    if legacy_5609_false_lock_requested:
        # This environment switch is the named historical rollback arm for the
        # whole Ahmed 5609 false-lock family.  Letting a sibling q1/q4 average
        # activate the new joint publisher would make that rollback only
        # partially effective and would no longer reproduce the old wire.
        return {}
    for key in QUALITY_KEYS:
        if evidence.fixed_counts.get(key) is not None:
            continue
        minimum = max(0, int(_effective_min_count(key, evidence)))
        ceiling = min(total, _physical_count_ceiling(total, key, evidence))
        if ceiling < minimum:
            continue

        constraints: list[set[int]] = []
        avg = _safe_float(evidence.avg_cells.get(key))
        if (
            avg is not None
            and avg > 0.0
            and key not in evidence.soft_avg_cell_keys
        ):
            constraints.append(
                {
                    count
                    for count in range(minimum, ceiling + 1)
                    if _avg_grid_options_for_evidence(
                        count,
                        avg,
                        key,
                        evidence,
                    )
                }
            )

        exact_cells = _quality_exact_cells(key, evidence)
        if exact_cells is not None:
            constraints.append(
                {
                    count
                    for count in range(minimum, ceiling + 1)
                    if _can_compose_grid_total_with_q6_catalog(
                        key,
                        count,
                        int(exact_cells),
                    )
                }
            )

        catalog_joint = joint_options.get(key, ())
        if catalog_joint:
            constraints.append(
                {
                    int(count)
                    for count, _cells in catalog_joint
                    if minimum <= int(count) <= ceiling
                }
            )

        if not constraints:
            continue
        physical = set(range(minimum, ceiling + 1))
        for constraint in constraints:
            physical.intersection_update(constraint)
        physical = {
            count
            for count in physical
            if _quality_count_matches_value_evidence(
                key,
                count,
                evidence,
            )
        }
        if len(physical) > 1 and max(physical) > 5:
            domains[key] = tuple(sorted(physical))
    return domains


def _ahmed_q5_residual_quote_safety_evidence(evidence: RefEvidence) -> bool:
    """Match the physical q5/q6 residual family without coupling to the display rollback.

    The display repair and this quote policy have separate rollback switches and separate
    responsibilities. Keep the evidence predicate local so disabling either change cannot
    silently disable the other.
    """
    return bool(
        normalize_hero_key(evidence.hero) == "ahmed"
        and evidence.phase != "settled"
        and evidence.total_count is not None
        and evidence.total_grid_target is None
        and {"q1", "q3"}.issubset(evidence.fixed_counts)
        and evidence.fixed_counts.get("q5") is None
        and evidence.fixed_counts.get("q6") is None
        and (evidence.avg_cells.get("q5") or 0.0) > 0.0
        and "q5" not in evidence.soft_avg_cell_keys
        and (
            (
                (evidence.avg_cells.get("q4") or 0.0) > 0.0
                and evidence.quality_values.get("q4") is not None
                and bool((evidence.quality_count_cells_options or {}).get("q4"))
            )
            or (
                evidence.fixed_counts.get("q4") is not None
                and (evidence.avg_cells.get("q4") or 0.0) > 0.0
            )
        )
        and not _quality_has_direct_count_grid_value_evidence("q6", evidence)
    )


_WAREHOUSE_QUOTE_SOURCE_CONTAINER_MAX_KEYS = 512
_WAREHOUSE_QUOTE_SOURCE_KEY_MAX_LENGTH = 128
_WAREHOUSE_QUOTE_SOURCE_SHA256_LENGTH = 64
_WAREHOUSE_QUOTE_SOURCE_FIELDS = (
    "warehouse_source",
    "warehouse_source_qualification",
    "official_distribution_eligible",
    "quote_policy",
)
_WAREHOUSE_QUOTE_SOURCE_MISSING = object()
_WAREHOUSE_QUOTE_PROVENANCE_FIELDS = (
    "qualification",
    "official_distribution_eligible",
    "quote_policy",
    "map_id",
    "table_status",
    "source_generation",
    "auction_mode",
    "source_conflict",
    "quarantine_required",
    "parser_replay_eligible",
    "map_table_sha256",
    "expected_map_table_sha256",
    "map_source_contract_sha256",
    "expected_map_source_contract_sha256",
)
_WAREHOUSE_QUOTE_PROVENANCE_PREPARED_AUTH_KEY = secrets.token_bytes(32)
_WAREHOUSE_QUOTE_PROVENANCE_PREPARED_MARKER_KEY = (
    "_bidking_internal_warehouse_quote_provenance_prepared"
)
_WAREHOUSE_QUOTE_PROVENANCE_PREPARED_DECISION_KEY = (
    "_bidking_internal_warehouse_quote_provenance_decision"
)
_WAREHOUSE_QUOTE_PROVENANCE_QUALIFICATIONS = frozenset(
    {
        "postupdate_unknown_warehouse_source",
        "player_custom_warehouse",
    }
)


@dataclass(frozen=True)
class _WarehouseQuoteProvenanceDecision:
    legacy_qualification: str | None
    gabriela_qualification: str | None


_WAREHOUSE_QUOTE_PROVENANCE_RUN_DECISION: ContextVar[
    _WarehouseQuoteProvenanceDecision | None
] = ContextVar(
    "ahmad_ref_engine_warehouse_quote_provenance_decision",
    default=None,
)


def _exact_warehouse_quote_source_dict(value: Any) -> dict[str, Any] | None:
    """Return a bounded exact dict without invoking Mapping/key protocol hooks."""

    if type(value) is not dict:  # noqa: E721 - subclasses are untrusted wire values
        return None
    if dict.__len__(value) > _WAREHOUSE_QUOTE_SOURCE_CONTAINER_MAX_KEYS:
        return None
    keys = tuple(dict.keys(value))
    if any(
        type(key) is not str  # noqa: E721 - collision-capable subclasses are unsafe
        or len(key) > _WAREHOUSE_QUOTE_SOURCE_KEY_MAX_LENGTH
        for key in keys
    ):
        return None
    return value


def _warehouse_quote_source_contract_projection(
    snapshot: Mapping[str, Any],
) -> tuple[str, tuple[str, bool, str] | None]:
    """Project every warehouse-source declaration as one fail-closed contract.

    ``unsafe`` means a container/key/scalar could execute user protocol code and
    must also be removed before product-summary consumers inspect the snapshot.
    ``invalid`` covers exact-builtin partial/conflicting declarations.  Neither
    state is eligible for quote/risk policy.
    """

    root = _exact_warehouse_quote_source_dict(snapshot)
    if root is None:
        return "unsafe", None

    owners: list[dict[str, Any]] = [root]
    ui_contract_value = dict.get(
        root,
        "ui_contract",
        _WAREHOUSE_QUOTE_SOURCE_MISSING,
    )
    if ui_contract_value is not _WAREHOUSE_QUOTE_SOURCE_MISSING:
        ui_contract = _exact_warehouse_quote_source_dict(ui_contract_value)
        if ui_contract is None:
            return "unsafe", None
        for owner_key in ("context", "source"):
            owner_value = dict.get(
                ui_contract,
                owner_key,
                _WAREHOUSE_QUOTE_SOURCE_MISSING,
            )
            if owner_value is _WAREHOUSE_QUOTE_SOURCE_MISSING:
                continue
            owner = _exact_warehouse_quote_source_dict(owner_value)
            if owner is None:
                return "unsafe", None
            owners.append(owner)

    qualifications: list[str] = []
    eligibility_flags: list[bool] = []
    quote_policies: list[str] = []
    provenance_signatures: list[
        tuple[bool, bool | None, bool, str | None, str | None]
    ] = []
    complete_source_count = 0
    declaration_seen = False

    for owner in owners:
        nested_value = dict.get(
            owner,
            "warehouse_source",
            _WAREHOUSE_QUOTE_SOURCE_MISSING,
        )
        legacy_values = tuple(
            dict.get(owner, source_field, _WAREHOUSE_QUOTE_SOURCE_MISSING)
            for source_field in (
                "warehouse_source_qualification",
                "official_distribution_eligible",
                "quote_policy",
            )
        )
        owner_declared = (
            nested_value is not _WAREHOUSE_QUOTE_SOURCE_MISSING
            or any(
                value is not _WAREHOUSE_QUOTE_SOURCE_MISSING
                for value in legacy_values
            )
        )
        if not owner_declared:
            continue
        declaration_seen = True
        # Declarations are owner-scoped contracts, not a bag of fields that may be
        # completed by a different owner. Legacy aliases may corroborate a nested
        # contract, but they cannot stand in for its provenance.
        if nested_value is not _WAREHOUSE_QUOTE_SOURCE_MISSING:
            nested = _exact_warehouse_quote_source_dict(nested_value)
            if nested is None:
                return "unsafe", None
            qualification = dict.get(
                nested,
                "qualification",
                _WAREHOUSE_QUOTE_SOURCE_MISSING,
            )
            eligible = dict.get(
                nested,
                "official_distribution_eligible",
                _WAREHOUSE_QUOTE_SOURCE_MISSING,
            )
            policy = dict.get(
                nested,
                "quote_policy",
                _WAREHOUSE_QUOTE_SOURCE_MISSING,
            )
            if any(
                value is _WAREHOUSE_QUOTE_SOURCE_MISSING
                for value in (qualification, eligible, policy)
            ):
                return "invalid", None
            if type(qualification) is not str or type(policy) is not str:  # noqa: E721
                if type(qualification) not in {type(None), bool, int, float, bytes} or type(
                    policy
                ) not in {type(None), bool, int, float, bytes}:
                    return "unsafe", None
                return "invalid", None
            if type(eligible) is not bool:  # noqa: E721
                if type(eligible) not in {type(None), int, float, str, bytes}:
                    return "unsafe", None
                return "invalid", None
            if (
                len(qualification) > _WAREHOUSE_QUOTE_SOURCE_KEY_MAX_LENGTH
                or len(policy) > _WAREHOUSE_QUOTE_SOURCE_KEY_MAX_LENGTH
            ):
                return "invalid", None
            qualifications.append(qualification)
            eligibility_flags.append(eligible)
            quote_policies.append(policy)
            quarantine = dict.get(
                nested,
                "quarantine_required",
                _WAREHOUSE_QUOTE_SOURCE_MISSING,
            )
            actual_hash = dict.get(
                nested,
                "map_table_sha256",
                _WAREHOUSE_QUOTE_SOURCE_MISSING,
            )
            expected_hash = dict.get(
                nested,
                "expected_map_table_sha256",
                _WAREHOUSE_QUOTE_SOURCE_MISSING,
            )
            if quarantine is not _WAREHOUSE_QUOTE_SOURCE_MISSING:
                if type(quarantine) is not bool:  # noqa: E721 - exact wire scalar
                    if type(quarantine) not in {
                        type(None),
                        int,
                        float,
                        str,
                        bytes,
                    }:
                        return "unsafe", None
                    return "invalid", None
                if quarantine:
                    return "invalid", None
            hash_presence = (
                actual_hash is not _WAREHOUSE_QUOTE_SOURCE_MISSING,
                expected_hash is not _WAREHOUSE_QUOTE_SOURCE_MISSING,
            )
            if hash_presence[0] != hash_presence[1]:
                return "invalid", None
            normalized_actual: str | None = None
            normalized_expected: str | None = None
            if hash_presence[0]:
                for hash_value in (actual_hash, expected_hash):
                    if type(hash_value) is not str:  # noqa: E721 - exact wire scalar
                        if type(hash_value) not in {
                            type(None),
                            bool,
                            int,
                            float,
                            bytes,
                        }:
                            return "unsafe", None
                        return "invalid", None
                    if (
                        len(hash_value) != _WAREHOUSE_QUOTE_SOURCE_SHA256_LENGTH
                        or re.fullmatch(r"[0-9a-fA-F]{64}", hash_value) is None
                    ):
                        return "invalid", None
                normalized_actual = actual_hash.lower()
                normalized_expected = expected_hash.lower()
                if normalized_actual != normalized_expected:
                    return "invalid", None
            provenance_signatures.append(
                (
                    quarantine is not _WAREHOUSE_QUOTE_SOURCE_MISSING,
                    quarantine
                    if quarantine is not _WAREHOUSE_QUOTE_SOURCE_MISSING
                    else None,
                    hash_presence[0],
                    normalized_actual,
                    normalized_expected,
                )
            )
            complete_source_count += 1
        else:
            return "invalid", None

        for source_field, expected_type, target in (
            ("warehouse_source_qualification", str, qualifications),
            ("official_distribution_eligible", bool, eligibility_flags),
            ("quote_policy", str, quote_policies),
        ):
            value = dict.get(owner, source_field, _WAREHOUSE_QUOTE_SOURCE_MISSING)
            if value is _WAREHOUSE_QUOTE_SOURCE_MISSING:
                continue
            declaration_seen = True
            if type(value) is not expected_type:  # noqa: E721 - exact wire scalars only
                if type(value) not in {type(None), bool, int, float, str, bytes}:
                    return "unsafe", None
                return "invalid", None
            if (  # noqa: E721 - exact wire scalars only
                type(value) is str  # noqa: E721 - exact wire scalars only
                and len(value) > _WAREHOUSE_QUOTE_SOURCE_KEY_MAX_LENGTH
            ):
                return "invalid", None
            target.append(value)

    if not declaration_seen:
        return "missing", None
    if complete_source_count == 0:
        return "invalid", None
    if (
        len(set(qualifications)) != 1
        or len(set(eligibility_flags)) != 1
        or len(set(quote_policies)) != 1
        or len(set(provenance_signatures)) != 1
    ):
        return "invalid", None
    return (
        "valid",
        (
            qualifications[0],
            eligibility_flags[0],
            quote_policies[0],
        ),
    )


def _drop_rejected_warehouse_quote_source_fields(
    snapshot: dict[str, Any],
) -> dict[str, Any]:
    """Remove rejected source declarations before summary/API fallback consumers."""

    root = _exact_warehouse_quote_source_dict(snapshot)
    if root is None:
        return {}
    payload = dict.copy(root)
    for source_field in _WAREHOUSE_QUOTE_SOURCE_FIELDS:
        dict.pop(payload, source_field, None)

    ui_contract_value = dict.get(
        root,
        "ui_contract",
        _WAREHOUSE_QUOTE_SOURCE_MISSING,
    )
    ui_contract = _exact_warehouse_quote_source_dict(ui_contract_value)
    if ui_contract is None:
        payload["ui_contract"] = {}
        return payload

    projected_ui_contract = dict.copy(ui_contract)
    for owner_key in ("context", "source"):
        owner_value = dict.get(
            ui_contract,
            owner_key,
            _WAREHOUSE_QUOTE_SOURCE_MISSING,
        )
        owner = _exact_warehouse_quote_source_dict(owner_value)
        if owner is None:
            if owner_value is not _WAREHOUSE_QUOTE_SOURCE_MISSING:
                dict.pop(projected_ui_contract, owner_key, None)
            continue
        projected_owner = dict.copy(owner)
        for source_field in _WAREHOUSE_QUOTE_SOURCE_FIELDS:
            dict.pop(projected_owner, source_field, None)
        projected_ui_contract[owner_key] = projected_owner
    payload["ui_contract"] = projected_ui_contract
    return payload


def _stabilize_nonofficial_warehouse_source_snapshot(
    snapshot: dict[str, Any],
) -> dict[str, Any]:
    status, _contract = _warehouse_quote_source_contract_projection(snapshot)
    if status not in {"unsafe", "invalid"}:
        return snapshot
    return _drop_rejected_warehouse_quote_source_fields(snapshot)


def _nonofficial_warehouse_quote_qualification(snapshot: Mapping[str, Any]) -> str | None:
    """Return one fully consistent, explicit non-official source qualification."""

    return _warehouse_quote_provenance_decision(
        snapshot,
        map_id=4501,
    ).legacy_qualification


def _stable_nonofficial_warehouse_quote_owner(
    owner: Any,
    *,
    map_id: int,
) -> tuple[str, tuple[Any, ...] | None]:
    """Project one complete Gabriela provenance owner without value magic."""

    exact_owner = _exact_warehouse_quote_source_dict(owner)
    if exact_owner is None:
        return ("invalid", None)
    raw_source = dict.get(
        exact_owner,
        "warehouse_source",
        _WAREHOUSE_QUOTE_SOURCE_MISSING,
    )
    aliases = {
        field: dict.get(exact_owner, field, _WAREHOUSE_QUOTE_SOURCE_MISSING)
        for field in (
            "warehouse_source_qualification",
            "official_distribution_eligible",
            "quote_policy",
        )
    }
    if raw_source is _WAREHOUSE_QUOTE_SOURCE_MISSING and all(
        value is _WAREHOUSE_QUOTE_SOURCE_MISSING for value in aliases.values()
    ):
        return ("absent", None)
    source = _exact_warehouse_quote_source_dict(raw_source)
    if source is None:
        return ("invalid", None)
    values = tuple(
        dict.get(source, field, _WAREHOUSE_QUOTE_SOURCE_MISSING)
        for field in _WAREHOUSE_QUOTE_PROVENANCE_FIELDS
    )
    if any(value is _WAREHOUSE_QUOTE_SOURCE_MISSING for value in values):
        return ("invalid", None)
    (
        qualification,
        eligible,
        quote_policy,
        raw_map_id,
        table_status,
        source_generation,
        auction_mode,
        source_conflict,
        quarantine_required,
        parser_replay_eligible,
        table_sha,
        expected_table_sha,
        contract_sha,
        expected_contract_sha,
    ) = values
    bounded_strings = (
        qualification,
        quote_policy,
        table_status,
        source_generation,
        auction_mode,
        table_sha,
        expected_table_sha,
        contract_sha,
        expected_contract_sha,
    )
    if (
        any(
            type(value) is not str  # noqa: E721 - reject subclasses
            or len(value) > PUBLIC_AVG_JSON_MAX_STRING_LENGTH
            for value in bounded_strings
        )
        or qualification not in _WAREHOUSE_QUOTE_PROVENANCE_QUALIFICATIONS
        or eligible is not False
        or quote_policy != "advisory_only_no_clamp"
        or type(raw_map_id) is not int  # noqa: E721 - reject bool/subclasses
        or raw_map_id != map_id
        or table_status != "verified"
        or source_generation != "postupdate_player_warehouse_activity"
        or auction_mode != "open"
        or source_conflict is not False
        or quarantine_required is not False
        or parser_replay_eligible is not True
        or not table_sha
        or table_sha != expected_table_sha
        or not contract_sha
        or contract_sha != expected_contract_sha
    ):
        return ("invalid", None)
    expected_aliases = {
        "warehouse_source_qualification": qualification,
        "official_distribution_eligible": eligible,
        "quote_policy": quote_policy,
    }
    for field, value in aliases.items():
        if value is _WAREHOUSE_QUOTE_SOURCE_MISSING:
            continue
        expected = expected_aliases[field]
        if type(value) is not type(expected) or value != expected:  # noqa: E721
            return ("invalid", None)
    return ("valid", values)


def _atomic_nonofficial_warehouse_quote_provenance(
    snapshot: Any,
    *,
    map_id: int,
) -> _WarehouseQuoteProvenanceDecision:
    """Classify legacy and Gabriela owners atomically before lossy projection."""

    invalid = _WarehouseQuoteProvenanceDecision(None, None)
    root = _exact_warehouse_quote_source_dict(snapshot)
    if root is None or type(map_id) is not int:  # noqa: E721
        return invalid

    legacy_status, legacy_contract = _warehouse_quote_source_contract_projection(root)
    legacy_qualification: str | None = None
    if legacy_status == "valid" and legacy_contract is not None:
        qualification, eligible, policy = legacy_contract
        if (
            qualification in _WAREHOUSE_QUOTE_PROVENANCE_QUALIFICATIONS
            and eligible is False
            and policy == "advisory_only_no_clamp"
        ):
            legacy_qualification = qualification

    owners: list[dict[str, Any]] = []
    raw_ui_contract = dict.get(root, "ui_contract", _WAREHOUSE_QUOTE_SOURCE_MISSING)
    if raw_ui_contract is not _WAREHOUSE_QUOTE_SOURCE_MISSING:
        ui_contract = _exact_warehouse_quote_source_dict(raw_ui_contract)
        if ui_contract is None:
            return invalid
        for field in ("context", "source"):
            raw_owner = dict.get(ui_contract, field, _WAREHOUSE_QUOTE_SOURCE_MISSING)
            if raw_owner is _WAREHOUSE_QUOTE_SOURCE_MISSING:
                continue
            owner = _exact_warehouse_quote_source_dict(raw_owner)
            if owner is None:
                return invalid
            owners.append(owner)
    owners.append(root)

    strict_canonical: tuple[Any, ...] | None = None
    strict_invalid = False
    for owner in owners:
        status, candidate = _stable_nonofficial_warehouse_quote_owner(
            owner,
            map_id=map_id,
        )
        if status == "invalid":
            strict_invalid = True
        elif status == "valid" and candidate is not None:
            if strict_canonical is None:
                strict_canonical = candidate
            elif candidate != strict_canonical:
                strict_invalid = True
    gabriela_qualification = (
        None
        if strict_invalid or strict_canonical is None
        else strict_canonical[0]
    )
    if legacy_qualification is None:
        gabriela_qualification = None
    return _WarehouseQuoteProvenanceDecision(
        legacy_qualification=legacy_qualification,
        gabriela_qualification=gabriela_qualification,
    )


def _warehouse_quote_provenance_decision_auth_payload(
    decision: _WarehouseQuoteProvenanceDecision,
) -> bytes | None:
    legacy = decision.legacy_qualification
    gabriela = decision.gabriela_qualification
    if legacy is None:
        return b"v1\n-\n-" if gabriela is None else None
    if (
        type(legacy) is not str  # noqa: E721 - exact builtin only
        or legacy not in _WAREHOUSE_QUOTE_PROVENANCE_QUALIFICATIONS
        or (
            gabriela is not None
            and (
                type(gabriela) is not str  # noqa: E721
                or gabriela != legacy
            )
        )
    ):
        return None
    return b"v1\n" + legacy.encode("ascii") + b"\n" + (
        b"-" if gabriela is None else gabriela.encode("ascii")
    )


def _warehouse_quote_provenance_prepared_marker(
    decision: _WarehouseQuoteProvenanceDecision,
) -> str:
    payload = _warehouse_quote_provenance_decision_auth_payload(decision)
    if payload is None:
        raise ValueError("invalid warehouse quote provenance decision")
    return hmac.digest(
        _WAREHOUSE_QUOTE_PROVENANCE_PREPARED_AUTH_KEY,
        payload,
        "sha256",
    ).hex()


def _warehouse_quote_provenance_prepared_decision_row(
    raw_decision: Any,
) -> _WarehouseQuoteProvenanceDecision | None:
    if (
        type(raw_decision) is not dict  # noqa: E721 - exact JSON row only
        or not _has_exact_bounded_json_keys(raw_decision)
        or set(dict.keys(raw_decision))
        != {"legacy_qualification", "gabriela_qualification"}
    ):
        return None
    decision = _WarehouseQuoteProvenanceDecision(
        legacy_qualification=dict.get(raw_decision, "legacy_qualification"),
        gabriela_qualification=dict.get(raw_decision, "gabriela_qualification"),
    )
    return (
        decision
        if _warehouse_quote_provenance_decision_auth_payload(decision) is not None
        else None
    )


def _prepared_warehouse_quote_provenance_decision(
    snapshot: Any,
    *,
    map_id: int,
) -> _WarehouseQuoteProvenanceDecision | None:
    invalid = _WarehouseQuoteProvenanceDecision(None, None)
    root = _exact_warehouse_quote_source_dict(snapshot)
    if root is None:
        return None
    raw_marker = dict.get(
        root,
        _WAREHOUSE_QUOTE_PROVENANCE_PREPARED_MARKER_KEY,
        _WAREHOUSE_QUOTE_SOURCE_MISSING,
    )
    raw_decision = dict.get(
        root,
        _WAREHOUSE_QUOTE_PROVENANCE_PREPARED_DECISION_KEY,
        _WAREHOUSE_QUOTE_SOURCE_MISSING,
    )
    if (
        raw_marker is _WAREHOUSE_QUOTE_SOURCE_MISSING
        and raw_decision is _WAREHOUSE_QUOTE_SOURCE_MISSING
    ):
        return None
    if type(raw_marker) is not str or len(raw_marker) != 64:  # noqa: E721
        return invalid
    decision = _warehouse_quote_provenance_prepared_decision_row(raw_decision)
    if decision is None:
        return invalid
    expected_marker = _warehouse_quote_provenance_prepared_marker(decision)
    if not hmac.compare_digest(raw_marker, expected_marker):
        return invalid
    current = _atomic_nonofficial_warehouse_quote_provenance(root, map_id=map_id)
    return decision if current == decision else invalid


def _warehouse_quote_provenance_decision(
    snapshot: Any,
    *,
    map_id: int,
) -> _WarehouseQuoteProvenanceDecision:
    active = _WAREHOUSE_QUOTE_PROVENANCE_RUN_DECISION.get()
    if active is not None:
        return active
    prepared = _prepared_warehouse_quote_provenance_decision(
        snapshot,
        map_id=map_id,
    )
    if prepared is not None:
        return prepared
    return _atomic_nonofficial_warehouse_quote_provenance(snapshot, map_id=map_id)


def _nonofficial_warehouse_quote_provenance_verified(
    snapshot: Mapping[str, Any],
    *,
    map_id: int,
) -> bool:
    return (
        _warehouse_quote_provenance_decision(
            snapshot,
            map_id=map_id,
        ).gabriela_qualification
        is not None
    )


def _ahmed_nonofficial_q4_avg_arm_safety_evidence(evidence: RefEvidence) -> bool:
    """Identify Ahmed hard-average states whose q4 count is still a physical multiple choice.

    The actual arm count is checked after combo enumeration. This predicate only establishes that
    the ambiguity comes from the intended evidence family, not from an exact q4 count/cells/value
    fact. Source qualification is checked separately against the original snapshot.
    """
    return bool(
        normalize_hero_key(evidence.hero) == "ahmed"
        and evidence.phase != "settled"
        and evidence.total_count is not None
        and evidence.total_grid_target is None
        and evidence.fixed_counts.get("q4") is None
        and _quality_exact_cells("q4", evidence) is None
        and _quality_exact_value("q4", evidence) is None
        and not (evidence.quality_count_cells_options or {}).get("q4")
        and (evidence.avg_cells.get("q4") or 0.0) > 0.0
        and "q4" not in evidence.soft_avg_cell_keys
        and (evidence.avg_cells.get("q5") or 0.0) > 0.0
        and "q5" not in evidence.soft_avg_cell_keys
        and evidence.fixed_counts.get("q3") is not None
        and (
            evidence.fixed_counts.get("q1") is not None
            or (
                (evidence.avg_cells.get("q1") or 0.0) > 0.0
                and "q1" not in evidence.soft_avg_cell_keys
            )
        )
    )


def _ahmed_soft_q4_low_red_gap_antilock_enabled(
    evidence: RefEvidence,
    prior_combos: Sequence[RefCombo],
    widen_fired: set[str],
) -> bool:
    """Retry an Ahmed soft-purple split when the red prior skips 1–3 items.

    2601 R2 had an exact total, one exact blue count, a public-only purple
    average and a hard skill gold average.  Their feasible q4/q5 counts left
    three items for q1+q6, but the sparse q6 prior domain was ``0, 4..15``:
    the minimum anchor kept zero while omitting every small positive red
    count.  The only joint combo therefore rendered q6=0 as an exact fact.

    This is deliberately evidence-shaped.  A hard/soft q1 anchor, total-grid
    target, red evidence, or any additional fixed tier routes through the
    existing inference paths instead.  In particular, the real Ahmed 2505
    zero-red control has a hard q1 average and does not enter this retry.
    """
    if _run_env_get(AHMED_SOFT_Q4_LOW_RED_GAP_ANTILOCK_DISABLE) == "1":
        return False
    if normalize_hero_key(evidence.hero) != "ahmed" or evidence.phase == "settled":
        return False
    if evidence.total_count is None or evidence.total_grid_target is not None:
        return False
    if set(evidence.fixed_counts) != {"q3"}:
        return False
    if evidence.avg_cells.get("q1") is not None or evidence.fixed_counts.get("q1") is not None:
        return False
    if (
        "q4" not in evidence.soft_avg_cell_keys
        or (evidence.avg_cells.get("q4") or 0.0) <= 0
        or "public_q4_avg_cells" not in evidence.source_notes
    ):
        return False
    if (
        (evidence.avg_cells.get("q5") or 0.0) <= 0
        or "q5" in evidence.soft_avg_cell_keys
        or "skill_1002041_q5_avg_cells" not in evidence.source_notes
        or "q5" not in widen_fired
    ):
        return False
    if (
        evidence.fixed_counts.get("q6") is not None
        or int(evidence.min_counts.get("q6", 0) or 0) > 0
        or evidence.avg_cells.get("q6") is not None
        or evidence.avg_values.get("q6") is not None
        or evidence.quality_cells.get("q6") is not None
        or evidence.quality_values.get("q6") is not None
        or evidence.quality_cell_floors.get("q6") is not None
        or evidence.quality_value_floors.get("q6") is not None
        or evidence.quality_catalog_min_value_floors.get("q6") is not None
        or evidence.quality_min_total_value_floors.get("q6") is not None
        or evidence.q6_known_item_facts
        # ``random_value_floors`` stores (sample_count, total_value_floor), not
        # (quality, value).  Low-signal draws remain a whole-vault soft weight;
        # high-signal draws are already normalized into q6 min/value floors above.
    ):
        return False
    return (
        len(prior_combos) == 1
        and int(prior_combos[0].counts.get("q6", 0)) == 0
    )


def _quality_has_direct_count_grid_value_evidence(
    key: str,
    evidence: RefEvidence,
) -> bool:
    """Whether a tier carries evidence that a prior-only retry must not override."""
    return bool(
        evidence.fixed_counts.get(key) is not None
        or int(evidence.min_counts.get(key, 0) or 0) > 0
        or evidence.avg_cells.get(key) is not None
        or evidence.avg_values.get(key) is not None
        or evidence.quality_cells.get(key) is not None
        or evidence.quality_values.get(key) is not None
        or evidence.quality_cell_floors.get(key) is not None
        or evidence.quality_value_floors.get(key) is not None
        or evidence.quality_catalog_min_value_floors.get(key) is not None
        or evidence.quality_min_total_value_floors.get(key) is not None
        or key in (evidence.quality_count_cells_options or {})
        or (key == "q4" and evidence.q4_known_item_facts)
        or (key == "q5" and evidence.q5_known_item_facts)
        or (key == "q6" and evidence.q6_known_item_facts)
    )


def _quality_has_evidence_beyond_avg_cells(
    key: str,
    evidence: RefEvidence,
) -> bool:
    """Whether a hard-average retry would override a stronger fact for ``key``."""
    return bool(
        evidence.fixed_counts.get(key) is not None
        or int(evidence.min_counts.get(key, 0) or 0) > 0
        or evidence.avg_values.get(key) is not None
        or evidence.quality_cells.get(key) is not None
        or evidence.quality_values.get(key) is not None
        or evidence.quality_cell_floors.get(key) is not None
        or evidence.quality_value_floors.get(key) is not None
        or evidence.quality_catalog_min_value_floors.get(key) is not None
        or evidence.quality_min_total_value_floors.get(key) is not None
        or key in (evidence.quality_count_cells_options or {})
        or (key == "q4" and evidence.q4_known_item_facts)
        or (key == "q5" and evidence.q5_known_item_facts)
        or (key == "q6" and evidence.q6_known_item_facts)
    )


def _ahmed_nonofficial_sparse_avg_low_quality_cycle_enabled(
    snapshot: Mapping[str, Any],
    evidence: RefEvidence,
    prior_combos: Sequence[RefCombo],
    widen_fired: set[str],
) -> bool:
    """Break the sparse-prior feedback loop seen in Ahmed 2404.

    With only total count, exact blue count and Ahmed's hard gold/purple means,
    the high-total fast path can force the still-unknown low tier to zero.  The
    exact-total remainder then appears to prove five red items.  When the later
    white+green total-cells scan arrives, the same narrow domain becomes
    unreachable and the product has no quote to render.

    Re-enumerate the normal prior domain only for an explicit non-official
    advisory source and only while low-quality count remains unknown.  Hard
    q4/q5 means and an optional positive merged-low total-cells fact remain
    constraints in the retry; direct red or stronger sibling evidence is a
    fail-closed no-op.
    """
    if (
        _run_env_get(AHMED_NONOFFICIAL_SPARSE_AVG_LOW_QUALITY_CYCLE_DISABLE)
        == "1"
    ):
        return False
    if _nonofficial_warehouse_quote_qualification(snapshot) is None:
        return False
    if normalize_hero_key(evidence.hero) != "ahmed" or evidence.phase == "settled":
        return False
    if (
        evidence.total_count is None
        or _hard_total_grid_target_int(evidence) is not None
        or not _has_explicit_total_count_source(evidence.source_notes)
        or not _sparse_exact_high_total_tight_prior(evidence)
        or set(evidence.fixed_counts) != {"q3"}
    ):
        return False
    if (
        evidence.avg_cells.get("q1") is not None
        or evidence.avg_values.get("q1") is not None
        or evidence.quality_values.get("q1") is not None
        or evidence.quality_cell_floors.get("q1") is not None
        or evidence.quality_value_floors.get("q1") is not None
        or evidence.quality_catalog_min_value_floors.get("q1") is not None
        or evidence.quality_min_total_value_floors.get("q1") is not None
        or "q1" in (evidence.quality_count_cells_options or {})
    ):
        return False
    low_cells = evidence.quality_cells.get("q1")
    if low_cells is not None and (_safe_float(low_cells) or 0.0) <= 0.0:
        return False
    if (
        (evidence.avg_cells.get("q5") or 0.0) <= 0.0
        or "q5" in evidence.soft_avg_cell_keys
        or "skill_1002041_q5_avg_cells" not in evidence.source_notes
        or "q5" not in widen_fired
        or _quality_has_evidence_beyond_avg_cells("q5", evidence)
    ):
        return False
    q4_avg = evidence.avg_cells.get("q4")
    if q4_avg is not None and (
        (_safe_float(q4_avg) or 0.0) <= 0.0
        or "q4" in evidence.soft_avg_cell_keys
        or "skill_1002042_q4_avg_cells" not in evidence.source_notes
        or _quality_has_evidence_beyond_avg_cells("q4", evidence)
    ):
        return False
    if _quality_has_direct_count_grid_value_evidence("q6", evidence):
        return False
    # Before q4 arrives this evidence family is exactly the R2 false-zero arm:
    # raw tight support still contains tiny positive-red rows, but the published
    # posterior collapses to q6=0.  Once q4 arrives, require the tighter symptom
    # (zero-low arm or no reachable arm) before retrying.
    return (
        q4_avg is None
        or not prior_combos
        or all(int(combo.counts.get("q1", 0)) == 0 for combo in prior_combos)
    )


def _aisha_q5_q6_residual_antilock_enabled(
    evidence: RefEvidence,
    prior_combos: Sequence[RefCombo],
    widen_fired: set[str],
) -> bool:
    """Restore only the red residual paired with hard q4/q5 arithmetic.

    4541 R3 has exact q1/q3 counts and hard q4/q5 means.  The q5 arithmetic widen correctly
    re-admits the reachable gold multiples, but the independent tight q6 prior can either leave only
    a prior-favoured zero-red state or omit every exact-total composition.  Preserve the surviving
    q4 state when there is one; otherwise derive q4 from its own hard-mean domain, then retry only the
    q5/q6 exact-total complements.  This is not a global prior-radius widen.
    """
    return bool(
        _run_env_get(AISHA_Q5_Q6_RESIDUAL_ANTILOCK_DISABLE) != "1"
        and normalize_hero_key(evidence.hero) == "aisha"
        and evidence.phase != "settled"
        and evidence.total_count is not None
        and evidence.total_grid_target is None
        and _sparse_exact_high_total_tight_prior(evidence)
        and set(evidence.fixed_counts) == {"q1", "q3"}
        and evidence.fixed_counts.get("q4") is None
        and evidence.fixed_counts.get("q5") is None
        and (evidence.avg_cells.get("q4") or 0.0) > 0.0
        and (evidence.avg_cells.get("q5") or 0.0) > 0.0
        and "q4" not in evidence.soft_avg_cell_keys
        and "q5" not in evidence.soft_avg_cell_keys
        and "q5" in widen_fired
        and not _quality_has_direct_count_grid_value_evidence("q6", evidence)
        and len(prior_combos) <= 1
        and (
            not prior_combos
            or int(prior_combos[0].counts.get("q6", 0)) == 0
        )
    )


def _aisha_q5_q6_residual_count_overrides(
    total: int,
    *,
    evidence: RefEvidence,
    probs: dict[str, float],
    prior_combo: RefCombo | None,
) -> dict[str, tuple[int, ...]] | None:
    fixed_q1 = evidence.fixed_counts.get("q1")
    fixed_q3 = evidence.fixed_counts.get("q3")
    if fixed_q1 is None or fixed_q3 is None:
        return None
    if prior_combo is not None:
        q4_values = [int(prior_combo.counts["q4"])]
    else:
        q4_values = _prior_count_values(
            total,
            "q4",
            evidence,
            probs,
            set(),
        )
    q5_values = _prior_count_values(
        total,
        "q5",
        evidence,
        probs,
        set(),
    )
    paired_q4: set[int] = set()
    paired_q5: set[int] = set()
    residual_q6: set[int] = set()
    fixed_low = int(fixed_q1) + int(fixed_q3)
    for q4 in q4_values:
        for q5 in q5_values:
            q6 = int(total) - fixed_low - int(q4) - int(q5)
            if q6 < 0:
                continue
            paired_q4.add(int(q4))
            paired_q5.add(int(q5))
            residual_q6.add(q6)
    if not paired_q5 or not any(value > 0 for value in residual_q6):
        return None
    return {
        "q1": (int(fixed_q1),),
        "q3": (int(fixed_q3),),
        "q4": tuple(sorted(paired_q4)),
        "q5": tuple(sorted(paired_q5)),
        "q6": tuple(sorted(residual_q6)),
    }


def _aisha_hard_avg_physical_support_antilock_enabled(
    evidence: RefEvidence,
    prior_combos: Sequence[RefCombo],
    widen_fired: set[str],
) -> bool:
    """Keep a soft sparse prior from masquerading as a hard Aisha lock.

    The game facts in this lane prove the total, q1/q3 counts and q4/q5
    count-to-grid arithmetic.  They do not choose one of the remaining
    catalog-composable q4/q5/q6 complements.  The multinomial prior remains
    the weight/rank function, but it must not delete those physical arms.
    """

    return bool(
        _run_env_get(AISHA_HARD_AVG_PHYSICAL_SUPPORT_ANTILOCK_DISABLE) != "1"
        and normalize_hero_key(evidence.hero) == "aisha"
        and evidence.phase == "bidding"
        and evidence.total_count is not None
        and _hard_total_grid_target_int(evidence) is None
        and _sparse_exact_high_total_tight_prior(evidence)
        and set(evidence.fixed_counts) == {"q1", "q3"}
        and len(prior_combos) == 1
        and not (
            "q5" in widen_fired
            and int(prior_combos[0].counts.get("q6", 0)) == 0
        )
        and all(
            (evidence.avg_cells.get(key) or 0.0) > 0.0
            and key not in evidence.soft_avg_cell_keys
            and not _quality_has_evidence_beyond_avg_cells(key, evidence)
            for key in ("q4", "q5")
        )
        and not _quality_has_direct_count_grid_value_evidence("q6", evidence)
        and not any(
            type(note) is not str or "conflict" in note
            for note in evidence.source_notes
        )
    )


def _aisha_hard_avg_physical_count_overrides(
    total: int,
    *,
    evidence: RefEvidence,
) -> dict[str, tuple[int, ...]] | None:
    """Enumerate the hard-arithmetic and catalog physical count domain."""

    fixed_q1 = evidence.fixed_counts.get("q1")
    fixed_q3 = evidence.fixed_counts.get("q3")
    if fixed_q1 is None or fixed_q3 is None:
        return None

    domains: dict[str, tuple[int, ...]] = {
        "q1": (int(fixed_q1),),
        "q3": (int(fixed_q3),),
    }
    for key in ("q4", "q5"):
        avg = _safe_float(evidence.avg_cells.get(key))
        minimum = _effective_min_count(key, evidence)
        ceiling = min(int(total), _physical_count_ceiling(total, key, evidence))
        if avg is None or avg <= 0.0 or ceiling < minimum:
            return None
        values = tuple(
            count
            for count in range(minimum, ceiling + 1)
            if _avg_grid_options_for_evidence(count, avg, key, evidence)
        )
        if not values:
            return None
        domains[key] = values

    residual_max = (
        int(total)
        - int(fixed_q1)
        - int(fixed_q3)
        - min(domains["q4"])
        - min(domains["q5"])
    )
    q6_minimum = _effective_min_count("q6", evidence)
    if residual_max < q6_minimum:
        return None
    q6_values = tuple(
        count
        for count in range(q6_minimum, residual_max + 1)
        if _composable_grid_options_with_q6_catalog("q6", count)
        and _quality_count_matches_value_evidence("q6", count, evidence)
    )
    if not q6_values:
        return None
    domains["q6"] = q6_values
    return domains


def _aisha_q5q6_exact_residual_count_support(
    evidence: RefEvidence,
) -> tuple[tuple[int, ...], dict[str, tuple[int, ...]]] | None:
    """Return the complete q5/q6 physical count domain for an exact residual body.

    In this narrow Aisha state, q1/q3/q4 counts and cells are already exact, while
    the hard warehouse grid closes q5 and q6 cells without proving either count.
    A total-count prior and the per-quality multinomial windows may rank those
    physical arms, but they must not erase catalog-composable count/cell states.
    """

    if (
        _run_env_get(AISHA_Q5Q6_EXACT_RESIDUAL_COUNT_SUPPORT_DISABLE) == "1"
        or normalize_hero_key(evidence.hero) != "aisha"
        or evidence.phase != "bidding"
        or evidence.total_count is not None
        or _hard_total_grid_target_int(evidence) is None
        or AISHA_POST_SPLIT_TOTAL_GRID_RESIDUAL_NOTE not in evidence.source_notes
        or "quality_cells_q6_from_total_grid_residual" not in evidence.source_notes
        or evidence.fixed_counts.get("q5") is not None
        or evidence.fixed_counts.get("q6") is not None
        or any(
            evidence.fixed_counts.get(key) is None
            or _quality_exact_cells(key, evidence) is None
            for key in ("q1", "q3", "q4")
        )
        or _quality_exact_cells("q5", evidence) is None
        or _quality_exact_cells("q6", evidence) is None
        or any(key in (evidence.quality_count_cells_options or {}) for key in ("q5", "q6"))
        or any(
            type(note) is not str or "conflict" in note
            for note in evidence.source_notes
        )
    ):
        return None

    q5_cells = int(_quality_exact_cells("q5", evidence) or 0)
    q6_cells = int(_quality_exact_cells("q6", evidence) or 0)
    q5_minimum = int(_effective_min_count("q5", evidence))
    q6_minimum = int(_effective_min_count("q6", evidence))
    q5_values = tuple(
        count
        for count in range(q5_minimum, q5_cells + 1)
        if _can_compose_grid_total_with_q6_catalog("q5", count, q5_cells)
        and _q5_known_item_cell_compose_matches(count, q5_cells, evidence)
        and _quality_count_matches_value_evidence("q5", count, evidence)
    )
    q6_values = tuple(
        count
        for count in range(q6_minimum, q6_cells + 1)
        if _can_compose_grid_total_with_q6_catalog("q6", count, q6_cells)
        and _q6_known_item_exact_cells_compose_matches(count, q6_cells, evidence)
        and _quality_count_matches_value_evidence("q6", count, evidence)
    )
    if not q5_values or not q6_values:
        return None

    fixed_total = sum(int(evidence.fixed_counts[key]) for key in ("q1", "q3", "q4"))
    totals = tuple(
        sorted(
            {
                fixed_total + q5 + q6
                for q5 in q5_values
                for q6 in q6_values
                if fixed_total + q5 + q6 <= _TOTAL_COUNT_PRIOR_WINDOW_CAP
            }
        )
    )
    if not totals:
        return None
    return totals, {"q5": q5_values, "q6": q6_values}


def _aisha_q5_value_q4_avg_residual_antilock_enabled(
    evidence: RefEvidence,
    prior_combos: Sequence[RefCombo],
) -> bool:
    """Let hard q4 arithmetic reach a q5-count-proven Aisha residual.

    A public q5 average value plus an exact q5 total can prove one count, and the
    repeat-allowed q5 catalog independently confirms that count.  Aisha 4501 had
    q5=4 on both signals, while a hard q4 average required a multiple-of-six q4
    count.  The multinomial q4 window stopped at 12, so no q4+q6 complement
    remained and the generic no-combo fallback discarded the q5 average, reopening
    q5=9.  Widen only q4's hard-average domain; q6 keeps its existing prior domain,
    and every stronger q4/q6 fact keeps this retry dormant.
    """
    if (
        _run_env_get(AISHA_Q5_VALUE_Q4_AVG_RESIDUAL_ANTILOCK_DISABLE) == "1"
        or normalize_hero_key(evidence.hero) != "aisha"
        or evidence.phase == "settled"
        or prior_combos
        or evidence.total_count is None
        or evidence.total_grid_target is not None
        or not _has_explicit_total_count_source(evidence.source_notes)
        or set(evidence.fixed_counts) != {"q1", "q3", "q5"}
        or evidence.fixed_counts.get("q4") is not None
        or (evidence.avg_cells.get("q4") or 0.0) <= 0.0
        or "q4" in evidence.soft_avg_cell_keys
        or _quality_has_evidence_beyond_avg_cells("q4", evidence)
        or _quality_has_direct_count_grid_value_evidence("q6", evidence)
    ):
        return False

    q5_count = int(evidence.fixed_counts["q5"])
    q5_avg = _safe_float(evidence.avg_values.get("q5"))
    q5_total = _safe_float(evidence.quality_values.get("q5"))
    q5_options = (evidence.quality_count_cells_options or {}).get("q5") or ()
    return bool(
        q5_count > 0
        and q5_avg is not None
        and q5_total is not None
        and _quality_count_matches_value_inputs(q5_count, q5_avg, q5_total)
        and q5_options
        and all(int(count) == q5_count for count, _cells in q5_options)
        and f"{Q5_CATALOG_PROJECTION_NOTE}:count:{q5_count}"
        in evidence.source_notes
    )


def _aisha_q5_value_q4_avg_count_overrides(
    total: int,
    *,
    evidence: RefEvidence,
) -> dict[str, tuple[int, ...]] | None:
    """Return every physically reachable q4 count allowed by its hard average."""
    minimum = _effective_min_count("q4", evidence)
    ceiling = min(int(total), _physical_count_ceiling(total, "q4", evidence))
    avg = _safe_float(evidence.avg_cells.get("q4"))
    if avg is None or avg <= 0.0 or ceiling < minimum:
        return None
    values = tuple(
        count
        for count in range(minimum, ceiling + 1)
        if _avg_grid_options_for_evidence(count, avg, "q4", evidence)
    )
    return {"q4": values} if values else None


def _aisha_q4_avg_q5_value_residual_count_overrides(
    total: int,
    *,
    evidence: RefEvidence,
    prior_combos: Sequence[RefCombo],
) -> dict[str, tuple[int, ...]] | None:
    """Restore a physical q4/q5/q6 residual rejected by independent tight priors.

    With exact q1/q3 counts, a wire-level q4 mean can leave a q5+q6 residual
    larger than the two independent high-total prior windows combined.  Those
    windows rank unknown counts; they are not game evidence and must not blank
    an otherwise reachable state.  This retry keeps every hard sibling fact,
    enumerates the q4 mean's physical count domain, and lets q5/q6 share the
    exact residual.  The q5 total value remains a likelihood/range constraint,
    never a synthetic count lock.
    """
    if (
        _run_env_get(AISHA_Q4_AVG_Q5_VALUE_RESIDUAL_DOMAIN_DISABLE) == "1"
        or normalize_hero_key(evidence.hero) != "aisha"
        or evidence.phase == "settled"
        or prior_combos
        or evidence.total_count is None
        or int(evidence.total_count) != int(total)
        or _hard_total_grid_target_int(evidence) is not None
        or not _has_explicit_total_count_source(evidence.source_notes)
        or not _sparse_exact_high_total_tight_prior(evidence)
        or set(evidence.fixed_counts) != {"q1", "q3"}
        or (evidence.avg_cells.get("q4") or 0.0) <= 0.0
        or "q4" in evidence.soft_avg_cell_keys
        or _quality_has_evidence_beyond_avg_cells("q4", evidence)
        or evidence.avg_cells.get("q5") is not None
        or evidence.avg_values.get("q5") is not None
        or evidence.quality_cells.get("q5") is not None
        or (evidence.quality_values.get("q5") or 0.0) <= 0.0
        or evidence.quality_cell_floors.get("q5") is not None
        or evidence.quality_value_floors.get("q5") is not None
        or evidence.quality_catalog_min_value_floors.get("q5") is not None
        or evidence.quality_min_total_value_floors.get("q5") is not None
        or "q5" in (evidence.quality_count_cells_options or {})
        or evidence.q5_known_item_facts
        or _quality_has_direct_count_grid_value_evidence("q6", evidence)
        or f"{Q5_EXACT_VALUE_CELLS_NOTE}:value_only_guard:0"
        not in evidence.source_notes
    ):
        return None

    q4_avg = _safe_float(evidence.avg_cells.get("q4"))
    if q4_avg is None or q4_avg <= 0.0:
        return None
    q4_min = _effective_min_count("q4", evidence)
    q4_max = min(
        int(total),
        _physical_count_ceiling(total, "q4", evidence),
    )
    q4_values = tuple(
        count
        for count in range(q4_min, q4_max + 1)
        if _avg_grid_options_for_evidence(count, q4_avg, "q4", evidence)
    )
    if not q4_values:
        return None

    fixed_low = sum(int(evidence.fixed_counts[key]) for key in ("q1", "q3"))
    residual_max = int(total) - fixed_low - min(q4_values)
    if residual_max < 0:
        return None
    q5_values = tuple(
        count
        for count in range(
            _effective_min_count("q5", evidence),
            residual_max + 1,
        )
        if _quality_count_matches_value_evidence("q5", count, evidence)
    )
    q6_values = tuple(
        range(_effective_min_count("q6", evidence), residual_max + 1)
    )
    if not q5_values or not q6_values:
        return None
    return {
        "q4": q4_values,
        "q5": q5_values,
        "q6": q6_values,
    }


def _aisha_q6_exact_residual_count_override(
    total: int,
    *,
    evidence: RefEvidence,
) -> dict[str, tuple[int, ...]] | None:
    """Return the arithmetic q6 residual when four hard sibling counts exhaust the total.

    Aisha 2541 R4 has exact q1/q3/q4 counts and a q5 count proven jointly by gold average-cells plus
    gold total value.  Those four hard counts leave q6=8, but the independent map prior stops at six
    and can otherwise empty the candidate set.  This is used only as a no-combo retry: the prior may
    rank a reachable residual, but it cannot veto one implied by exact count identities.
    """
    if _run_env_get(AISHA_Q6_EXACT_RESIDUAL_ANTILOCK_DISABLE) == "1":
        return None
    if normalize_hero_key(evidence.hero) != "aisha" or evidence.phase == "settled":
        return None
    if evidence.total_count is None or int(evidence.total_count) != int(total):
        return None
    if not _has_explicit_total_count_source(evidence.source_notes):
        return None
    if set(evidence.fixed_counts) != {"q1", "q3", "q4", "q5"}:
        return None
    residual = int(total) - sum(
        max(0, int(evidence.fixed_counts[key])) for key in ("q1", "q3", "q4", "q5")
    )
    if residual < _effective_min_count("q6", evidence):
        return None
    if not _quality_count_matches_value_evidence("q6", residual, evidence):
        return None
    return {"q6": (residual,)}


def _aisha_q6_soft_total_residual_count_override(
    total: int,
    *,
    evidence: RefEvidence,
) -> dict[str, tuple[int, ...]] | None:
    """Readmit the q6 complement of four hard siblings for one soft total arm.

    The total itself remains a geometry/count-prior candidate, but once that arm is being tested
    and q1/q3/q4/q5 are exact, q6 is its arithmetic complement.  A per-quality statistical window
    may rank that count; it must not make the entire arm unreachable.  Scope this retry to Aisha's
    hard-grid late reveal with an observed red floor, and invoke it only after normal enumeration
    produced no combo.
    """
    if _run_env_get(AISHA_Q6_SOFT_TOTAL_RESIDUAL_ANTILOCK_DISABLE) == "1":
        return None
    if (
        normalize_hero_key(evidence.hero) != "aisha"
        or evidence.phase == "settled"
        or evidence.total_count is not None
        or _hard_total_grid_target_int(evidence) is None
        or set(evidence.fixed_counts) != {"q1", "q3", "q4", "q5"}
        or (
            int(evidence.min_counts.get("q6", 0) or 0) <= 0
            and not evidence.q6_known_item_facts
        )
    ):
        return None
    residual = int(total) - sum(
        max(0, int(evidence.fixed_counts[key]))
        for key in ("q1", "q3", "q4", "q5")
    )
    if residual < _effective_min_count("q6", evidence):
        return None
    if not _quality_count_matches_value_evidence("q6", residual, evidence):
        return None
    return {"q6": (residual,)}


def _ahmed_q1_q5_low_red_gap_antilock_enabled(
    evidence: RefEvidence,
    prior_combos: Sequence[RefCombo],
) -> bool:
    """Retry a screenshot-confirmed sparse Ahmed shape whose q6 prior omits 1–2.

    This differs from the 2601 soft-q4 repair: q1 and q5 are hard means here, while purple has no
    evidence at all.  A retry is accepted only when the original result is a sole zero-red combo and
    the low-gap domain actually adds a positive-red alternative.
    """
    return bool(
        _run_env_get(AHMED_Q1_Q5_LOW_RED_GAP_ANTILOCK_DISABLE) != "1"
        and normalize_hero_key(evidence.hero) == "ahmed"
        and evidence.phase != "settled"
        and evidence.total_count is not None
        and evidence.total_grid_target is None
        and _sparse_exact_high_total_tight_prior(evidence)
        and set(evidence.fixed_counts) == {"q3"}
        and (evidence.avg_cells.get("q1") or 0.0) > 0.0
        and (evidence.avg_cells.get("q5") or 0.0) > 0.0
        and "q1" not in evidence.soft_avg_cell_keys
        and "q5" not in evidence.soft_avg_cell_keys
        and "skill_1002041_q5_avg_cells" in evidence.source_notes
        and not _quality_has_direct_count_grid_value_evidence("q4", evidence)
        and not _quality_has_direct_count_grid_value_evidence("q6", evidence)
        and len(prior_combos) == 1
        and int(prior_combos[0].counts.get("q6", 0)) == 0
    )


def _ahmed_q1_q5_context_wire_int(
    value: Any,
    *,
    text: bool,
    minimum: int = 0,
) -> int | None:
    if text:
        parsed = (
            int(value)
            if type(value) is str  # noqa: E721 - exact JSON mirror scalar
            and re.fullmatch(r"0|[1-9][0-9]*", value)
            else None
        )
    else:
        parsed = value if type(value) is int else None  # noqa: E721
    if parsed is None or parsed < minimum:
        return None
    return int(parsed)


def _ahmed_q1_q5_single_identity_row(
    container: Any,
    *,
    id_key: str,
    expected_id: int,
) -> dict[str, Any] | None:
    if type(container) not in {list, tuple}:  # noqa: E721
        return None
    candidates: list[dict[str, Any]] = []
    for row in container:
        if type(row) is not dict or any(type(key) is not str for key in row):  # noqa: E721
            return None
        raw_id = row.get(id_key)
        parsed_id = (
            raw_id
            if type(raw_id) is int  # noqa: E721
            else int(raw_id)
            if type(raw_id) is str  # noqa: E721
            and re.fullmatch(r"[1-9][0-9]*", raw_id)
            else None
        )
        if parsed_id == expected_id:
            candidates.append(row)
    return candidates[0] if len(candidates) == 1 else None


def _ahmed_q1_q5_optional_epoch_signature(
    row: Mapping[str, Any],
    *,
    text: bool,
    runtime_epoch: int,
) -> tuple[tuple[str, bool, int | None], ...] | None:
    signature: list[tuple[str, bool, int | None]] = []
    for key in ("session_epoch", "epoch"):
        present = key in row
        parsed = (
            _ahmed_q1_q5_context_wire_int(
                row.get(key),
                text=text,
                minimum=1,
            )
            if present
            else None
        )
        if present and parsed != runtime_epoch:
            return None
        signature.append((key, present, parsed))
    return tuple(signature)


def _ahmed_q1_q5_action_identity_signature(
    row: Mapping[str, Any],
    *,
    ui_mirror: bool,
    session_id: str,
    runtime_epoch: int,
    observed_round: int,
    action_round: int,
) -> tuple[Any, ...] | None:
    required = {
        "action_id",
        "result",
        "result_field",
        "result_wire_type",
        "result_raw_hex",
        "session_id",
        "round",
        "source_message_id",
        "source_kind",
        "sort",
    }
    if not required <= row.keys():
        return None
    action_id = _ahmed_q1_q5_context_wire_int(
        row.get("action_id"), text=ui_mirror, minimum=1
    )
    result_field = _ahmed_q1_q5_context_wire_int(
        row.get("result_field"), text=ui_mirror, minimum=1
    )
    row_round = _ahmed_q1_q5_context_wire_int(
        row.get("round"), text=ui_mirror, minimum=1
    )
    source_message_id = _ahmed_q1_q5_context_wire_int(
        row.get("source_message_id"), text=ui_mirror, minimum=1
    )
    promoted_action_round = _ahmed_q1_q5_context_wire_int(
        row.get("promoted_action_round"), text=ui_mirror, minimum=1
    )
    sort_id = _ahmed_q1_q5_context_wire_int(
        row.get("sort"), text=ui_mirror, minimum=0
    )
    raw_result = row.get("result")
    if ui_mirror:
        parsed_result = (
            float(raw_result)
            if type(raw_result) is str  # noqa: E721
            and re.fullmatch(r"(?:0|[1-9][0-9]*)(?:\.[0-9]+)?", raw_result)
            else None
        )
    else:
        parsed_result = raw_result if type(raw_result) is float else None  # noqa: E721
    raw_hex = row.get("result_raw_hex")
    if (
        action_id != 100110
        or result_field != 11
        or row_round != observed_round
        or source_message_id is None
        or sort_id is None
        or type(row.get("result_wire_type")) is not str  # noqa: E721
        or row.get("result_wire_type") != "float32"
        or type(raw_hex) is not str  # noqa: E721
        or re.fullmatch(r"[0-9a-f]{8}", raw_hex) is None
        or type(row.get("session_id")) is not str  # noqa: E721
        or row.get("session_id") != session_id
        or type(row.get("source_kind")) is not str  # noqa: E721
        or parsed_result is None
        or not math.isfinite(parsed_result)
        or parsed_result <= 0.0
    ):
        return None
    direct_response = row.get("source_kind") == "direct_action_response"
    completed_replay = (
        row.get("source_kind") == "state_replay"
        and source_message_id == 0x0025
        and promoted_action_round == action_round
        and row_round + 1 == action_round
        and row.get("promotion_reason") == "completed_round_state_replay"
    )
    if not (direct_response or completed_replay):
        return None
    epochs = _ahmed_q1_q5_optional_epoch_signature(
        row,
        text=ui_mirror,
        runtime_epoch=runtime_epoch,
    )
    try:
        wire_result = struct.unpack("<f", bytes.fromhex(raw_hex))[0]
        canonical_raw = struct.pack("<f", parsed_result).hex()
    except (OverflowError, struct.error, ValueError):
        return None
    if (
        epochs is None
        or not math.isfinite(wire_result)
        or parsed_result != wire_result
        or canonical_raw != raw_hex
    ):
        return None
    return (
        raw_hex,
        session_id,
        row_round,
        source_message_id,
        sort_id,
        promoted_action_round,
        epochs,
    )


_AHMED_Q1_Q5_CURRENT_ACTION_PROJECTION_FIELDS = (
    "action_id",
    "result",
    "result_field",
    "result_wire_type",
    "result_raw_hex",
    "session_id",
    "round",
    "source_message_id",
    "source_kind",
    "sort",
    "promoted_action_round",
    "promotion_reason",
    "revealed_items",
)


def _ahmed_current_action_structured_target(
    action_id: int,
) -> tuple[str, str, frozenset[tuple[str, ...]]] | None:
    """Map one action to the monitor-owned aggregate/path it updates."""

    if type(action_id) is not int or action_id <= 0:  # noqa: E721
        return None
    text = str(action_id)
    quality = ACTION_AVG_CELLS.get(text)
    if quality is not None:
        bucket = "1" if quality == "q1" else quality.removeprefix("q")
        return "avg_cells", quality, frozenset({("bucket", bucket, "avg_cells")})
    quality = ACTION_TOTAL_CELLS.get(text)
    if quality is not None:
        bucket = "1" if quality == "q1" else quality.removeprefix("q")
        return (
            "quality_cells",
            quality,
            frozenset(
                {
                    ("bucket", bucket, "cells"),
                    ("bucket", bucket, "total_cells"),
                }
            ),
        )
    quality = ACTION_VALUE_SUM.get(text)
    if quality is not None:
        bucket = "1" if quality == "q1" else quality.removeprefix("q")
        return (
            "quality_values",
            quality,
            frozenset(
                {
                    ("bucket", bucket, "value"),
                    ("bucket", bucket, "value_sum"),
                    ("bucket", bucket, "total_value"),
                }
            ),
        )
    quality = ACTION_COUNTS.get(text)
    if quality is not None:
        bucket = "1" if quality == "q1" else quality.removeprefix("q")
        return "counts", quality, frozenset({("bucket", bucket, "count")})
    return None


def _ahmed_current_action_ui_marker_matches(
    snapshot: dict[str, Any],
    row: dict[str, Any],
) -> bool:
    ui_contract = dict.get(snapshot, "ui_contract")
    actions = dict.get(ui_contract, "actions") if type(ui_contract) is dict else None  # noqa: E721
    ui_rows = dict.get(actions, "results") if type(actions) is dict else None  # noqa: E721
    if type(ui_rows) not in {list, tuple}:  # noqa: E721
        return False
    matches: list[dict[str, Any]] = []
    for ui_row in ui_rows:
        if type(ui_row) is not dict or any(type(key) is not str for key in ui_row):  # noqa: E721
            return False
        identity = (
            _ahmed_q1_q5_context_wire_int(
                dict.get(ui_row, "action_id"), text=True, minimum=1
            ),
            _ahmed_q1_q5_context_wire_int(
                dict.get(ui_row, "sort"), text=True, minimum=0
            ),
            _ahmed_q1_q5_context_wire_int(
                dict.get(ui_row, "round"), text=True, minimum=1
            ),
        )
        if identity == (
            dict.get(row, "action_id"),
            dict.get(row, "sort"),
            dict.get(row, "round"),
        ):
            matches.append(ui_row)
    return bool(
        len(matches) == 1
        and dict.get(matches[0], "promoted_action_round")
        == str(dict.get(row, "promoted_action_round"))
        and dict.get(matches[0], "promotion_reason")
        == "completed_round_state_replay"
    )


def _ahmed_current_action_structured_marker_matches(
    snapshot: dict[str, Any],
    row: dict[str, Any],
) -> bool:
    expected = {
        key: dict.get(row, key)
        for key in _AHMED_Q1_Q5_CURRENT_ACTION_PROJECTION_FIELDS
        if dict.__contains__(row, key)
    }
    for owner_key in ("structured_ref_inputs", "ahmad_ref_inputs"):
        owner = dict.get(snapshot, owner_key)
        if type(owner) is not dict:  # noqa: E721
            continue
        if not dict.__contains__(owner, "current_action_results"):
            continue
        rows = dict.get(owner, "current_action_results")
        if type(rows) not in {list, tuple}:  # noqa: E721
            return False
        matches = [
            candidate
            for candidate in rows
            if type(candidate) is dict  # noqa: E721
            and dict.get(candidate, "action_id") == dict.get(row, "action_id")
        ]
        if len(matches) != 1:
            return False
        candidate = matches[0]
        if set(dict.keys(candidate)) != set(expected):
            return False
        for key, value in expected.items():
            other = dict.get(candidate, key)
            if (
                type(value) not in {type(None), int, float, str}  # noqa: E721
                or type(other) is not type(value)
                or other != value
            ):
                return False
    # Missing projection is accepted only at prepare: the exact root/UI pair is
    # projected immediately afterwards. Any present owner must already agree.
    return True


def _without_ahmed_current_action_structured_fact(
    owner: Any,
    target: tuple[str, str, frozenset[tuple[str, ...]]],
) -> Any:
    if type(owner) is not dict:  # noqa: E721
        return owner
    aggregate_key, quality, paths = target
    payload = dict.copy(owner)
    raw_updates = dict.get(owner, "field_updates")
    replacement = _ENV_MISSING
    if type(raw_updates) is list:  # noqa: E721 - monitor-owned JSON list
        targeted_indices = [
            index
            for index, update in enumerate(raw_updates)
            if type(update) is dict  # noqa: E721
            and type(dict.get(update, "path")) is list  # noqa: E721
            and all(type(part) is str for part in dict.get(update, "path"))  # noqa: E721
            and tuple(dict.get(update, "path")) in paths
        ]
        rejected_index = targeted_indices[-1] if targeted_indices else None
        remaining_updates = [
            update
            for index, update in enumerate(raw_updates)
            if index != rejected_index
        ]
        for index in reversed(targeted_indices[:-1]):
            update = raw_updates[index]
            replacement = dict.get(update, "value")
            break
        payload["field_updates"] = remaining_updates
    aggregate = dict.get(owner, aggregate_key)
    if type(aggregate) is dict:  # noqa: E721
        updated_aggregate = dict.copy(aggregate)
        if replacement is _ENV_MISSING:
            updated_aggregate.pop(quality, None)
        else:
            updated_aggregate[quality] = replacement
        payload[aggregate_key] = updated_aggregate
    payload.pop("current_action_results", None)
    return payload


def _stabilize_ahmed_current_action_publication(snapshot: Any) -> Any:
    """Withhold one cumulative replay result until its canonical marker commits."""

    if type(snapshot) is not dict or not _ahmed_q1_q5_raw_context_guard_targeted(snapshot):  # noqa: E721
        return snapshot
    phase = dict.get(snapshot, "phase")
    if type(phase) is not str:  # noqa: E721
        return snapshot
    if phase == "settled":
        payload = dict.copy(snapshot)

        def without_marker(value: Any) -> Any:
            if type(value) is not list:  # noqa: E721
                return value
            cleaned: list[Any] = []
            for row in value:
                if type(row) is not dict:  # noqa: E721
                    cleaned.append(row)
                    continue
                item = dict.copy(row)
                item.pop("promoted_action_round", None)
                item.pop("promotion_reason", None)
                cleaned.append(item)
            return cleaned

        payload["action_result_rows"] = without_marker(
            dict.get(snapshot, "action_result_rows")
        )
        ui_contract = dict.get(snapshot, "ui_contract")
        actions = dict.get(ui_contract, "actions") if type(ui_contract) is dict else None  # noqa: E721
        if type(ui_contract) is dict and type(actions) is dict:  # noqa: E721
            filtered_actions = dict.copy(actions)
            filtered_actions["results"] = without_marker(
                dict.get(actions, "results")
            )
            filtered_contract = dict.copy(ui_contract)
            filtered_contract["actions"] = filtered_actions
            payload["ui_contract"] = filtered_contract
        for owner_key in ("structured_ref_inputs", "ahmad_ref_inputs"):
            owner = dict.get(snapshot, owner_key)
            if type(owner) is dict and dict.__contains__(owner, "current_action_results"):  # noqa: E721
                filtered_owner = dict.copy(owner)
                filtered_owner.pop("current_action_results", None)
                payload[owner_key] = filtered_owner
        return payload
    if phase != "bidding":
        return snapshot
    session_id = dict.get(snapshot, "session_id")
    action_round = dict.get(snapshot, "action_round")
    observed_round = dict.get(snapshot, "observed_round")
    rows = dict.get(snapshot, "action_result_rows")
    if (
        type(session_id) is not str  # noqa: E721
        or type(action_round) is not int  # noqa: E721
        or type(observed_round) is not int  # noqa: E721
        or action_round != observed_round + 1
        or type(rows) is not list  # noqa: E721
    ):
        return snapshot
    candidates = [
        (index, row)
        for index, row in enumerate(rows)
        if (
            type(row) is dict  # noqa: E721
            and type(dict.get(row, "session_id")) is str  # noqa: E721
            and dict.get(row, "session_id") == session_id
            and type(dict.get(row, "source_kind")) is str  # noqa: E721
            and dict.get(row, "source_kind") == "state_replay"
            and type(dict.get(row, "source_message_id")) is int  # noqa: E721
            and dict.get(row, "source_message_id") == 0x0025
            and type(dict.get(row, "round")) is int  # noqa: E721
            and dict.get(row, "round") == observed_round
            and type(dict.get(row, "sort")) is int  # noqa: E721
            and _ahmed_current_action_structured_target(dict.get(row, "action_id"))
            is not None
        )
    ]
    if not candidates:
        return snapshot
    current_sort = max(dict.get(row, "sort") for _index, row in candidates)
    latest = [(index, row) for index, row in candidates if dict.get(row, "sort") == current_sort]
    current_index, current = latest[-1]
    marker_valid = bool(
        type(dict.get(current, "promoted_action_round")) is int  # noqa: E721
        and dict.get(current, "promoted_action_round") == action_round
        and dict.get(current, "promotion_reason")
        == "completed_round_state_replay"
        and _ahmed_current_action_ui_marker_matches(snapshot, current)
        and _ahmed_current_action_structured_marker_matches(snapshot, current)
    )
    if marker_valid:
        return snapshot
    target = _ahmed_current_action_structured_target(dict.get(current, "action_id"))
    if target is None:
        return snapshot
    payload = dict.copy(snapshot)
    payload["action_result_rows"] = [
        row for index, row in enumerate(rows) if index != current_index
    ]
    ui_contract = dict.get(snapshot, "ui_contract")
    actions = dict.get(ui_contract, "actions") if type(ui_contract) is dict else None  # noqa: E721
    ui_rows = dict.get(actions, "results") if type(actions) is dict else None  # noqa: E721
    if type(ui_contract) is dict and type(actions) is dict and type(ui_rows) is list:  # noqa: E721
        filtered_actions = dict.copy(actions)
        filtered_results: list[Any] = []
        for row in ui_rows:
            matches_current = bool(
                type(row) is dict  # noqa: E721
                and _ahmed_q1_q5_context_wire_int(
                    dict.get(row, "action_id"), text=True, minimum=1
                )
                == dict.get(current, "action_id")
                and _ahmed_q1_q5_context_wire_int(
                    dict.get(row, "sort"), text=True, minimum=0
                )
                == dict.get(current, "sort")
                and _ahmed_q1_q5_context_wire_int(
                    dict.get(row, "round"), text=True, minimum=1
                )
                == dict.get(current, "round")
            )
            if not matches_current:
                filtered_results.append(row)
        filtered_actions["results"] = filtered_results
        filtered_contract = dict.copy(ui_contract)
        filtered_contract["actions"] = filtered_actions
        payload["ui_contract"] = filtered_contract
    for owner_key in ("structured_ref_inputs", "ahmad_ref_inputs"):
        if dict.__contains__(snapshot, owner_key):
            payload[owner_key] = _without_ahmed_current_action_structured_fact(
                dict.get(snapshot, owner_key), target
            )
    return payload


def _with_ahmed_q1_q5_current_action_projection(snapshot: Any) -> Any:
    """Carry exact promoted root facts into the structured engine owner.

    Real monitor artifacts already publish this projection.  The preparation
    boundary also derives it for older/package-shaped snapshots after a caller
    has atomically promoted matching root/UI rows.  An existing projection is
    never repaired or overwritten: malformed/conflicting evidence remains a
    fail-closed input for the binding validator below.
    """

    if type(snapshot) is not dict:  # noqa: E721 - external boundary
        return snapshot
    structured = dict.get(snapshot, "structured_ref_inputs")
    if type(structured) is not dict:  # noqa: E721
        return snapshot
    if dict.__contains__(structured, "current_action_results"):
        return snapshot
    rows = dict.get(snapshot, "action_result_rows")
    if type(rows) not in {list, tuple}:  # noqa: E721
        return snapshot
    projected: list[dict[str, Any]] = []
    for row in rows:
        if type(row) is not dict or any(type(key) is not str for key in row):  # noqa: E721
            return snapshot
        if (
            type(dict.get(row, "promoted_action_round")) is not int  # noqa: E721
            or dict.get(row, "promotion_reason")
            != "completed_round_state_replay"
        ):
            continue
        projected.append(
            {
                key: dict.get(row, key)
                for key in _AHMED_Q1_Q5_CURRENT_ACTION_PROJECTION_FIELDS
                if dict.__contains__(row, key)
            }
        )
    if not projected:
        return snapshot
    payload = dict.copy(snapshot)
    structured_payload = dict.copy(structured)
    structured_payload["current_action_results"] = projected
    payload["structured_ref_inputs"] = structured_payload
    ahmad_inputs = dict.get(snapshot, "ahmad_ref_inputs")
    if (
        type(ahmad_inputs) is dict  # noqa: E721
        and not dict.__contains__(ahmad_inputs, "current_action_results")
    ):
        ahmad_payload = dict.copy(ahmad_inputs)
        ahmad_payload["current_action_results"] = [dict(row) for row in projected]
        payload["ahmad_ref_inputs"] = ahmad_payload
    return payload


def _ahmed_q1_q5_skill_identity_signature(
    row: Mapping[str, Any],
    *,
    session_id: str,
    runtime_epoch: int,
    observed_round: int,
) -> tuple[Any, ...] | None:
    skill_id = _ahmed_q1_q5_context_wire_int(
        row.get("skill_id"), text=False, minimum=1
    )
    hero_id = _ahmed_q1_q5_context_wire_int(
        row.get("hero_id"), text=False, minimum=1
    )
    result_field = _ahmed_q1_q5_context_wire_int(
        row.get("result_field"), text=False, minimum=1
    )
    round_index = _ahmed_q1_q5_context_wire_int(
        row.get("round_index"), text=False, minimum=1
    )
    sort_id = _ahmed_q1_q5_context_wire_int(
        row.get("sort"), text=False, minimum=0
    )
    result = row.get("result")
    if (
        skill_id != 1002041
        or hero_id != 204
        or result_field != 11
        or round_index is None
        or round_index > observed_round
        or sort_id is None
        or type(result) is not float  # noqa: E721 - exact runtime scalar
        or not math.isfinite(result)
        or result <= 0.0
    ):
        return None
    raw_session = row.get("session_id")
    if "session_id" in row and (
        type(raw_session) is not str  # noqa: E721
        or raw_session != session_id
    ):
        return None
    epochs = _ahmed_q1_q5_optional_epoch_signature(
        row,
        text=False,
        runtime_epoch=runtime_epoch,
    )
    try:
        if struct.unpack("<f", struct.pack("<f", result))[0] != result:
            return None
        result_raw = struct.pack("<f", result).hex()
    except (OverflowError, struct.error, ValueError):
        return None
    if epochs is None:
        return None
    return (
        result_raw,
        round_index,
        sort_id,
        "session_id" in row,
        raw_session,
        epochs,
    )


def _ahmed_q1_q5_current_context_binding_valid(
    snapshot: Any,
) -> bool:
    """Prove the narrow q1/q5 retry belongs to one current snapshot runtime."""

    if type(snapshot) is not dict:  # noqa: E721
        return False
    ui_contract = snapshot.get("ui_contract")
    context = ui_contract.get("context") if type(ui_contract) is dict else None  # noqa: E721
    actions = ui_contract.get("actions") if type(ui_contract) is dict else None  # noqa: E721
    ui_source = ui_contract.get("source") if type(ui_contract) is dict else None  # noqa: E721
    if any(type(value) is not dict for value in (ui_contract, context, actions, ui_source)):  # noqa: E721
        return False
    root_hero = snapshot.get("hero")
    context_hero = context.get("hero")
    if (
        type(root_hero) is not str  # noqa: E721 - exact runtime scalar
        or type(context_hero) is not str  # noqa: E721 - exact runtime scalar
        or normalize_hero_key(root_hero) != "ahmed"
        or normalize_hero_key(context_hero) != "ahmed"
        or type(snapshot.get("phase")) is not str  # noqa: E721
        or type(context.get("phase")) is not str  # noqa: E721
        or snapshot.get("phase").strip().lower() != "bidding"
        or context.get("phase").strip().lower() != "bidding"
    ):
        return False
    root_map = _ahmed_q1_q5_context_wire_int(
        snapshot.get("map_id"), text=False, minimum=1
    )
    context_map = _ahmed_q1_q5_context_wire_int(
        context.get("map_id"), text=False, minimum=1
    )
    root_model_map = _ahmed_q1_q5_context_wire_int(
        snapshot.get("model_map_id"), text=False, minimum=1
    )
    context_model_map = _ahmed_q1_q5_context_wire_int(
        context.get("model_map_id"), text=False, minimum=1
    )
    root_round = _ahmed_q1_q5_context_wire_int(
        snapshot.get("round"), text=False, minimum=1
    )
    root_action_round = _ahmed_q1_q5_context_wire_int(
        snapshot.get("action_round"), text=False, minimum=1
    )
    context_round = _ahmed_q1_q5_context_wire_int(
        context.get("round"), text=False, minimum=1
    )
    context_action_round = _ahmed_q1_q5_context_wire_int(
        context.get("action_round"), text=False, minimum=1
    )
    root_observed_round = _ahmed_q1_q5_context_wire_int(
        snapshot.get("observed_round"), text=False, minimum=1
    )
    context_observed_round = _ahmed_q1_q5_context_wire_int(
        context.get("observed_round"), text=False, minimum=1
    )
    if (
        root_map is None
        or root_map != context_map
        or root_model_map != root_map
        or context_model_map != root_map
        or root_round is None
        or root_round != root_action_round
        or root_round != context_round
        or root_round != context_action_round
        or root_observed_round is None
        or root_observed_round != context_observed_round
        or root_observed_round > root_round
    ):
        return False
    root_session = snapshot.get("session_id")
    context_session = context.get("session_id")
    if (
        type(root_session) is not str  # noqa: E721
        or type(context_session) is not str  # noqa: E721
        or root_session != context_session
        or not root_session.isascii()
    ):
        return False
    match = re.fullmatch(
        r"(?P<map>[1-9][0-9]*):(?P<runtime>[1-9][0-9]*)",
        root_session,
    )
    if match is None or int(match.group("map")) != root_map:
        return False
    runtime_epoch = int(match.group("runtime"))
    for owner in (snapshot, context):
        epochs = _ahmed_q1_q5_optional_epoch_signature(
            owner,
            text=False,
            runtime_epoch=runtime_epoch,
        )
        if epochs is None:
            return False
    root_created_at = snapshot.get("created_at")
    ui_created_at = ui_source.get("created_at")
    if (
        isinstance(root_created_at, bool)
        or isinstance(ui_created_at, bool)
        or type(root_created_at) not in {int, float}  # noqa: E721
        or type(ui_created_at) not in {int, float}  # noqa: E721
        or not math.isfinite(float(root_created_at))
        or not math.isfinite(float(ui_created_at))
        or float(root_created_at) <= 0.0
    ):
        return False
    created_at_matches = float(root_created_at) == float(ui_created_at)
    if not created_at_matches:
        heartbeat_at = snapshot.get("snapshot_heartbeat_at")
        if (
            isinstance(heartbeat_at, bool)
            or type(heartbeat_at) not in {int, float}  # noqa: E721
            or not math.isfinite(float(heartbeat_at))
            or float(heartbeat_at) != float(root_created_at)
            or float(root_created_at) < float(ui_created_at)
        ):
            return False
    raw_action = _ahmed_q1_q5_single_identity_row(
        snapshot.get("action_result_rows"),
        id_key="action_id",
        expected_id=100110,
    )
    ui_action = _ahmed_q1_q5_single_identity_row(
        actions.get("results"),
        id_key="action_id",
        expected_id=100110,
    )
    structured = snapshot.get("structured_ref_inputs")
    structured_action = (
        _ahmed_q1_q5_single_identity_row(
            structured.get("current_action_results"),
            id_key="action_id",
            expected_id=100110,
        )
        if type(structured) is dict  # noqa: E721
        else None
    )
    raw_skill = _ahmed_q1_q5_single_identity_row(
        snapshot.get("skill_reveal_rows"),
        id_key="skill_id",
        expected_id=1002041,
    )
    mirror_skill = _ahmed_q1_q5_single_identity_row(
        snapshot.get("skill_reveals"),
        id_key="skill_id",
        expected_id=1002041,
    )
    if any(row is None for row in (raw_action, ui_action, raw_skill, mirror_skill)):
        return False
    raw_action_signature = _ahmed_q1_q5_action_identity_signature(
        raw_action,
        ui_mirror=False,
        session_id=root_session,
        runtime_epoch=runtime_epoch,
        observed_round=root_observed_round,
        action_round=root_action_round,
    )
    ui_action_signature = _ahmed_q1_q5_action_identity_signature(
        ui_action,
        ui_mirror=True,
        session_id=root_session,
        runtime_epoch=runtime_epoch,
        observed_round=root_observed_round,
        action_round=root_action_round,
    )
    structured_action_signature = (
        _ahmed_q1_q5_action_identity_signature(
            structured_action,
            ui_mirror=False,
            session_id=root_session,
            runtime_epoch=runtime_epoch,
            observed_round=root_observed_round,
            action_round=root_action_round,
        )
        if structured_action is not None
        else None
    )
    raw_skill_signature = _ahmed_q1_q5_skill_identity_signature(
        raw_skill,
        session_id=root_session,
        runtime_epoch=runtime_epoch,
        observed_round=root_observed_round,
    )
    mirror_skill_signature = _ahmed_q1_q5_skill_identity_signature(
        mirror_skill,
        session_id=root_session,
        runtime_epoch=runtime_epoch,
        observed_round=root_observed_round,
    )
    structured_action_valid = (
        raw_action.get("source_kind") != "state_replay"
        or (
            structured_action_signature is not None
            and structured_action_signature == raw_action_signature
        )
    )
    return bool(
        raw_action_signature is not None
        and raw_action_signature == ui_action_signature
        and structured_action_valid
        and raw_skill_signature is not None
        and raw_skill_signature == mirror_skill_signature
    )


def _ahmed_q1_q5_raw_context_guard_targeted(snapshot: Any) -> bool:
    """Recognize the narrow Ahmed shape without coercing untrusted hero values."""

    if type(snapshot) is not dict:  # noqa: E721 - exact external boundary
        return False
    ui_contract = dict.get(snapshot, "ui_contract")
    context = (
        dict.get(ui_contract, "context")
        if type(ui_contract) is dict  # noqa: E721 - exact external boundary
        else None
    )
    heroes = (
        dict.get(snapshot, "hero"),
        dict.get(context, "hero")
        if type(context) is dict  # noqa: E721 - exact external boundary
        else None,
    )
    return any(
        type(hero) is str and normalize_hero_key(hero) == "ahmed"  # noqa: E721
        for hero in heroes
    )


def _ahmed_q1_q5_context_prepared_marker(bound: bool) -> str:
    if type(bound) is not bool:  # noqa: E721 - authenticated exact scalar
        raise ValueError("invalid Ahmed q1/q5 context decision")
    payload = b"v1\nbound\n1" if bound else b"v1\nbound\n0"
    return hmac.digest(
        _AHMED_Q1_Q5_CONTEXT_PREPARED_AUTH_KEY,
        payload,
        "sha256",
    ).hex()


def _prepared_ahmed_q1_q5_raw_context_binding(
    snapshot: Any,
) -> bool | None:
    """Read one authenticated pre-stabilizer identity decision.

    A true marker is accepted only while the current snapshot independently
    passes the complete identity validator.  A false marker intentionally
    survives a lossy scope projection: that is the case where prepare repaired
    a conflicting/missing raw root hero from the UI mirror.
    """

    if type(snapshot) is not dict:  # noqa: E721 - exact external boundary
        return None
    marker = dict.get(
        snapshot,
        _AHMED_Q1_Q5_CONTEXT_PREPARED_MARKER_KEY,
        _ENV_MISSING,
    )
    decision = dict.get(
        snapshot,
        _AHMED_Q1_Q5_CONTEXT_PREPARED_DECISION_KEY,
        _ENV_MISSING,
    )
    if marker is _ENV_MISSING and decision is _ENV_MISSING:
        return None
    if (
        type(marker) is not str  # noqa: E721 - exact authenticated scalar
        or len(marker) != 64
        or type(decision) is not bool  # noqa: E721 - reject truthy subclasses
    ):
        return False
    expected = _ahmed_q1_q5_context_prepared_marker(decision)
    if not hmac.compare_digest(marker, expected):
        return False
    if decision and not _ahmed_q1_q5_current_context_binding_valid(snapshot):
        return False
    return decision


def _ahmed_q1_q5_raw_context_binding_decision(snapshot: Any) -> bool:
    prepared = _prepared_ahmed_q1_q5_raw_context_binding(snapshot)
    if prepared is not None:
        return prepared
    return _ahmed_q1_q5_current_context_binding_valid(snapshot)


def _ahmed_q1_q5_empty_support_antilock_candidate(
    evidence: RefEvidence,
) -> bool:
    """Recognize the Ahmed empty-window contract independent of rollback.

    Exact total + q3 count + hard q1/q5 means can leave a small arithmetic
    residual for q4/q6.  The high-total multinomial window is a rank prior, not
    a game rule; if all of its q4/q6 values sit above that residual it must not
    turn a physically reachable vault into ``no_reachable_combo``.
    """

    return bool(
        normalize_hero_key(evidence.hero) == "ahmed"
        and evidence.phase == "bidding"
        and evidence.total_count is not None
        and evidence.total_grid_target is None
        and _has_explicit_total_count_source(evidence.source_notes)
        and _sparse_exact_high_total_tight_prior(evidence)
        and set(evidence.fixed_counts) == {"q3"}
        and (evidence.avg_cells.get("q1") or 0.0) > 0.0
        and (evidence.avg_cells.get("q5") or 0.0) > 0.0
        and "q1" not in evidence.soft_avg_cell_keys
        and "q5" not in evidence.soft_avg_cell_keys
        and "action_100110_q1_avg_cells" in evidence.source_notes
        and "skill_1002041_q5_avg_cells" in evidence.source_notes
        and evidence.ahmed_q1_q5_current_context_bound
        and not _quality_has_direct_count_grid_value_evidence("q4", evidence)
        and not _quality_has_direct_count_grid_value_evidence("q6", evidence)
        and not any(
            type(note) is not str or "conflict" in note
            for note in evidence.source_notes
        )
    )


def _ahmed_q1_q5_empty_support_antilock_enabled(
    evidence: RefEvidence,
    prior_combos: Sequence[RefCombo],
) -> bool:
    """Retry one real Ahmed empty-window shape from its physical count domain."""

    return bool(
        _run_env_get(AHMED_Q1_Q5_EMPTY_SUPPORT_ANTILOCK_DISABLE) != "1"
        and _ahmed_q1_q5_empty_support_antilock_candidate(evidence)
        and not prior_combos
    )


def _ahmed_q1_q5_empty_support_count_overrides(
    total: int,
    *,
    evidence: RefEvidence,
) -> dict[str, tuple[int, ...]] | None:
    """Return complete hard-arithmetic count domains for the narrow retry."""

    fixed_q3 = evidence.fixed_counts.get("q3")
    if fixed_q3 is None:
        return None

    domains: dict[str, tuple[int, ...]] = {"q3": (int(fixed_q3),)}
    for key in ("q1", "q5"):
        avg = _safe_float(evidence.avg_cells.get(key))
        minimum = _effective_min_count(key, evidence)
        ceiling = min(int(total), _physical_count_ceiling(total, key, evidence))
        if avg is None or avg <= 0.0 or ceiling < minimum:
            return None
        values = tuple(
            count
            for count in range(minimum, ceiling + 1)
            if _avg_grid_options_for_evidence(count, avg, key, evidence)
            and _quality_count_matches_value_evidence(key, count, evidence)
        )
        if not values:
            return None
        domains[key] = values

    for key in ("q4", "q6"):
        minimum = _effective_min_count(key, evidence)
        ceiling = min(int(total), _physical_count_ceiling(total, key, evidence))
        if ceiling < minimum:
            return None
        values = tuple(
            count
            for count in range(minimum, ceiling + 1)
            if _composable_grid_options_with_q6_catalog(key, count)
            and _quality_count_matches_value_evidence(key, count, evidence)
        )
        if not values:
            return None
        domains[key] = values
    return domains


def _ahmed_absent_q4_zero_antilock_enabled(
    evidence: RefEvidence,
    prior_combos: Sequence[RefCombo],
    widen_fired: set[str],
) -> bool:
    """Retry the sparse Ahmed shape when an unknown q4 becomes exact zero."""
    return bool(
        _run_env_get(AHMED_ABSENT_Q4_ZERO_ANTILOCK_DISABLE) != "1"
        and normalize_hero_key(evidence.hero) == "ahmed"
        and evidence.phase == "bidding"
        and evidence.total_count is not None
        and evidence.total_grid_target is None
        and _has_explicit_total_count_source(evidence.source_notes)
        and _sparse_exact_high_total_tight_prior(evidence)
        and set(evidence.fixed_counts) == {"q3"}
        and (evidence.avg_cells.get("q1") or 0.0) > 0.0
        and (evidence.avg_cells.get("q5") or 0.0) > 0.0
        and "q1" not in evidence.soft_avg_cell_keys
        and "q5" not in evidence.soft_avg_cell_keys
        and "skill_1002041_q5_avg_cells" in evidence.source_notes
        and "public_q5_avg_cells" not in evidence.source_notes
        and "q5" in widen_fired
        and not _quality_has_direct_count_grid_value_evidence("q4", evidence)
        and not _quality_has_direct_count_grid_value_evidence("q6", evidence)
        and len(prior_combos) == 1
        and int(prior_combos[0].counts.get("q4", 0)) == 0
    )


def _union_exact_total_q1_avg_feasible_counts(
    *,
    key: str,
    values: set[int],
    evidence: RefEvidence,
    minimum: int,
    maximum: int,
    expected: float,
    sigma: float,
    avg: float,
    tight_radius: int,
    widen_fired: set[str] | None = None,
) -> set[int]:
    if key == "q1" and _exact_total_q1_avg_domain_untighten_enabled(evidence):
        full_radius = max(1, min(5, int(math.ceil(1.6 * sigma))))
        full_lower = max(minimum, int(math.floor(expected - full_radius)))
        tight_lower = max(minimum, int(math.floor(expected - tight_radius)))
        for value in range(minimum, maximum + 1):
            if not _avg_grid_options(value, avg, key):
                continue
            # Only restore counts cut off on the LOW side of the tight window. The 2402 false-lock
            # case is avg-feasible q1=10 falling below tight_lower=11; widening the upper tail (e.g.
            # q1=21) on other vaults was an unrelated band stretch.
            if full_lower <= value < tight_lower:
                values.add(value)
        return values
    # High-tier (q4/q5/q6) anti-false-lock via avg_cells (env AHMAD_ENABLE_GOLDPURPLE_ANTILOCK, default
    # OFF). When the avg_cells integer-grid intersection has collapsed the window to a SINGLE value V (a
    # manufactured unique lock, e.g. ahmed 2505 purple: tight window [12..17] ∩ grid-feasible {6,12,18,24}
    # = {12}, truth 18 one step above the tight upper), re-admit the nearest grid-feasible neighbor on
    # EACH side within the untightened full-radius window (or one feasibility-step beyond its edge). Unlike
    # the q1 branch this includes the HIGH side (2505's truth is above the window) — safe here because it
    # fires ONLY on single-value collapse, so it cannot band-stretch a multi-value window.
    public_q4_antilock = _ahmed_public_q4_avg_antilock_enabled(key, evidence)
    if (
        (
            os.environ.get("AHMAD_ENABLE_GOLDPURPLE_ANTILOCK") == "1"
            or public_q4_antilock
        )
        and key in ("q4", "q5", "q6")
        and len(values) == 1
        and evidence.fixed_counts.get(key) is None
    ):
        before = set(values)
        full_radius = max(1, min(5, int(math.ceil(1.6 * sigma))))
        full_lower = max(minimum, int(math.floor(expected - full_radius)))
        full_upper = min(maximum, int(math.ceil(expected + full_radius)))
        v_lock = next(iter(values))
        for candidate in range(v_lock - 1, minimum - 1, -1):
            if _avg_grid_options(candidate, avg, key):
                if candidate >= full_lower - (v_lock - candidate):
                    values.add(candidate)
                break
        for candidate in range(v_lock + 1, maximum + 1):
            if _avg_grid_options(candidate, avg, key):
                if candidate <= full_upper + (candidate - v_lock):
                    values.add(candidate)
                break
        if public_q4_antilock and values != before and widen_fired is not None:
            widen_fired.add(key)
    return values


def _has_explicit_total_count_source(source_notes: tuple[str, ...]) -> bool:
    for note in source_notes:
        if note in EXACT_TOTAL_COUNT_SOURCE_NOTES:
            return True
        if any(note.startswith(f"{prefix}:") for prefix in EXACT_TOTAL_COUNT_SOURCE_NOTES):
            return True
    return False


def _non_total_count_evidence_strength(evidence: RefEvidence) -> int:
    score = 0
    if evidence.split_counts:
        score += 2
    if evidence.count_sums:
        score += 2
    score += sum(1 for value in evidence.fixed_counts.values() if int(value) > 0)
    score += sum(1 for value in evidence.min_counts.values() if int(value) > 0)
    if evidence.avg_cells:
        score += 1
    if evidence.avg_values or evidence.quality_values:
        score += 1
    return score


def _should_use_exact_total_avg_cells_fast_path(evidence: RefEvidence) -> bool:
    """Exact total + avg_cells live states eligible for §50-2 micro-optimizations."""
    if evidence.total_count is None or evidence.phase in {"settled", "manual"}:
        return False
    if _quality_cells_blocks_sparse_exact_prior(evidence):
        return False
    if not evidence.avg_cells:
        return False
    return any((avg or 0) > 0 for avg in evidence.avg_cells.values())


def _nearest_composable_default_grid(
    count: int,
    default: float,
    *,
    cell_floor: int,
    quality_key: str | None = None,
) -> float | None:
    candidate = int(round(default))
    if candidate < cell_floor:
        candidate = cell_floor
    if _can_compose_grid_total_with_q6_catalog(quality_key, count, candidate):
        return float(candidate)
    return None


def _count_prior_center_from_grid_quality_residual(
    evidence: RefEvidence,
    *,
    source_notes: list[str],
    baseline_center: int,
) -> int | None:
    """Estimate count-prior center from total grid minus pinned tier cells (grid+quality path)."""
    grid_target = evidence.total_grid_target
    if grid_target is None or float(grid_target) <= 0:
        return None
    if _non_total_count_evidence_strength(evidence) < 2:
        return None

    known_cells_total = 0
    for key in QUALITY_KEYS:
        exact = _exact_integer_quality_cell(evidence.quality_cells.get(key))
        if exact is not None:
            known_cells_total += exact

    fixed_sum = sum(max(0, int(value)) for value in evidence.fixed_counts.values())
    per_item = _residual_per_item_cell_estimate(
        fixed_counts=evidence.fixed_counts,
        avg_cells=evidence.avg_cells,
        source_notes=source_notes,
    )
    if per_item <= 0:
        return None
    residual_grid = max(0.0, float(grid_target) - float(known_cells_total))
    residual_items = int(round(residual_grid / per_item))
    estimated = max(fixed_sum + residual_items, fixed_sum, 1)
    _append_source_note_once(source_notes, "total_count_prior_center_from_grid_quality_residual")
    return max(int(baseline_center), int(estimated), 1)


def _should_defer_total_count_prior(evidence: RefEvidence) -> bool:
    """Live quotes always run count_prior; grid-only defer removed after cap/perf work.

    Mapping total grid (and avg cells) to item-count prior still needs audit (v0.2).
    """
    del evidence
    return False


# Draw/lottery-hero count + value calibration constants and scale logic live in draw_hero_policy
# (imported at the top). The engine keeps only the orchestration below, which needs RefEvidence /
# normalize_hero_key / _default_total_count. _draw_hero_count_keys / _draw_hero_count_scale are the
# policy functions (env A/B overrides included).


def _draw_hero_count_center(
    center: int,
    evidence: RefEvidence,
    notes: list[str],
    round_no: int | None = None,
    occ_cap: float | None = None,
    center_informed: bool = False,
) -> int:
    if _SHIPWRECK_CALIBRATED_PRIOR.get() is not None:
        return center  # this population's measured N already includes its hero mix
    if evidence.total_count is not None:  # total locked -> prior unused, do not touch
        return center
    if normalize_hero_key(evidence.hero) not in _draw_hero_count_keys():
        return center  # scope: only draw-heroes; aisha/ahmed/ethan/maria/etc. unchanged
    scale = _draw_hero_count_scale(round_no)
    map_default = _default_total_count(evidence.map_id)
    floor = int(round(map_default * scale))
    # Occupancy cap (opt-in): bound the map-constant boost floor by the OBSERVED (de-exploded) grid
    # so small vaults aren't floored up to the map average. Only caps the BOOST ceiling — the evidence
    # `center` is still the lower bound (max below), so occ_cap never pushes the count below evidence.
    if occ_cap is not None:
        capped = min(floor, int(round(occ_cap)))
        if capped < floor:
            notes.append(f"draw_hero_count_occ_cap:{floor}->{capped}")
        floor = capped
    # Informed-center guard (2026-06-29, live 5605 gabriela R3/R4): the boost floor is a MAP CONSTANT
    # (map_default*scale) meant to compensate draw-heroes' sparse-reveal UNDER-estimate. But when the
    # evidence center is itself GRID/DEPTH-DERIVED (center_informed, e.g. total_count_from_grid_avg_cells
    # via the visible-depth anchor + per-item residual), it is a PHYSICAL read of the vault, not a sparse
    # under-estimate — so the map-constant floor over-shoots it (5605: informed center 41, floor 52,
    # truth 34 -> boost forced 41->52 -> q6=8 vs truth 5, balanced +39%). When the center is informed,
    # skip the floor override entirely: trust the physical read over the map constant. The boost still
    # fires for the under-informed path (no avg_cells hint -> bare map default -> sparse reveals plausibly
    # under-counted). The occ_cap above still bounds the floor for the under-informed path. Rollback
    # DRAW_HERO_DISABLE_INFORMED_CENTER_GUARD=1. Default ON.
    if (
        center_informed
        and os.environ.get("DRAW_HERO_DISABLE_INFORMED_CENTER_GUARD") != "1"
    ):
        if floor > int(center):
            notes.append(f"draw_hero_count_informed_center_guard:informed{int(center)}(floor{floor} skipped)")
        return int(center)
    boosted = max(int(center), floor)
    if boosted != int(center):
        rtag = round_no if round_no is not None else "?"
        notes.append(f"draw_hero_count_center_boost:{int(center)}->{boosted}@r{rtag}({scale:g})")
    return boosted


def _hero_value_scale(hero: str | None) -> float:
    """Scoped value-percentile multiplier for a hero (1.0 = unchanged).

    Thin wrapper: normalise the hero key, then delegate to draw_hero_policy
    (which holds the DRAW_HERO_VALUE_SCALE table + the HERO_VALUE_SCALE_OVERRIDE env A/B).
    """
    return _policy_hero_value_scale(normalize_hero_key(str(hero or "")))


def _fixed_count_reachable_total_band(
    evidence: RefEvidence,
    probs: dict[str, float] | None,
    *,
    base_total: int,
) -> tuple[int, int] | None:
    """Reachable total-count band [lo, hi] implied by the FIXED (hard) per-quality counts.

    Fixed counts come from public info / skill reveals / scan props — absolute values that
    pin the corresponding qualities exactly. So total = Σfixed + Σ(free-quality counts), and
    each free quality can only contribute within its own prior count window. Totals OUTSIDE
    [lo, hi] therefore admit ZERO combos in the enumerator, regardless of the soft count prior.

    This lets the soft count center (e.g. grid/avg_cells hint, which over-states on a
    footroom-inflated grid) YIELD to the hard fixed counts instead of overriding them: when the
    soft window sits entirely above this band, the engine would enumerate only infeasible totals
    and return no_reachable_combo (observed live: 2405/2410/2501 decision rounds). Intersecting
    the soft window with this band is loss-free (it only drops totals that have no combo anyway).

    Returns None when nothing is fixed (no hard pin → no constraint) or probs is unavailable.
    The free windows are sized at `base_total` (the soft window's upper, generous). This keeps
    `hi` from under-stating the reachable max on DEEP near-full vaults — where the high soft
    center is legitimate and the free mid/high tiers genuinely large — so the band does not
    wrongly narrow them. The conflict cases are still caught because there the only free tier is
    red (q6), whose prob is tiny so its window max stays small even at a high base_total."""
    if probs is None or not evidence.fixed_counts:
        return None
    fixed_total = sum(max(0, int(value)) for value in evidence.fixed_counts.values())
    base_total = max(int(base_total), fixed_total + 8)
    lo = fixed_total
    hi = fixed_total
    for key in QUALITY_KEYS:
        if key in evidence.fixed_counts:
            continue
        free_min = _effective_min_count(key, evidence)
        lo += free_min
        window = _prior_count_values(base_total, key, evidence, probs)
        hi += max(window) if window else free_min
    if hi < lo:
        hi = lo
    return lo, hi


# Soft prior window cap for total-item enumeration. Ship/activity maps often declare
# 55-66 exact items; the old cap (60) emptied range() when center>~64 (early-nodisplay audit).
_TOTAL_COUNT_PRIOR_WINDOW_CAP = 100
AISHA_LOW_TIER_COUNT_UPPER_DISABLE = "BIDKING_DISABLE_AISHA_LOW_TIER_COUNT_UPPER"
AISHA_LOW_TIER_COUNT_UPPER_NOTE = "aisha_low_tier_count_upper"
AISHA_LOW_TIER_RESIDUAL_CENTER_CAP_DISABLE = (
    "BIDKING_DISABLE_AISHA_LOW_TIER_RESIDUAL_CENTER_CAP"
)
AISHA_LOW_TIER_COUNT_UPPER_QUANTILE = 0.975
AISHA_LOW_TIER_SPATIAL_LOW_RATIO = 0.90
AISHA_LOW_TIER_SPATIAL_HIGH_RATIO = 1.12
AISHA_LOW_TIER_SPATIAL_NOTE = "aisha_low_tier_spatial_grid_anchor"


def _aisha_low_tier_count_upper(
    evidence: RefEvidence,
    probs: dict[str, float],
    *,
    round_no: int | None,
) -> int | None:
    """Upper total-count cross-check from exact q1+q3 counts.

    The depth/grid hint assumes a generic cells-per-item ratio and can explode on a
    large-item vault. Exact low-tier counts provide an independent binomial view of
    total items. Use its generous p97.5 only as an upper bound on that soft ratio hint.
    """
    if (
        _run_env_get(AISHA_LOW_TIER_COUNT_UPPER_DISABLE) == "1"
        or normalize_hero_key(evidence.hero) != "aisha"
        or round_no is None
        or int(round_no) < 3
        or evidence.total_count is not None
        or any(evidence.fixed_counts.get(key) is None for key in ("q1", "q3"))
        or any(
            _exact_integer_quality_cell(evidence.quality_cells.get(key)) is None
            for key in ("q1", "q3")
        )
    ):
        return None
    locked_low = sum(max(0, int(evidence.fixed_counts[key])) for key in ("q1", "q3"))
    p_low = float(probs.get("q1", 0.0)) + float(probs.get("q3", 0.0))
    if locked_low <= 0 or not 0.05 < p_low < 0.95:
        return None

    rows: list[tuple[int, float]] = []
    for total in range(locked_low, _TOTAL_COUNT_PRIOR_WINDOW_CAP + 1):
        log_weight = (
            math.lgamma(total + 1)
            - math.lgamma(locked_low + 1)
            - math.lgamma(total - locked_low + 1)
            + locked_low * math.log(p_low)
            + (total - locked_low) * math.log1p(-p_low)
        )
        rows.append((total, log_weight))
    max_log_weight = max(weight for _total, weight in rows)
    weights = [
        (total, math.exp(max(-745.0, weight - max_log_weight)))
        for total, weight in rows
    ]
    weight_sum = sum(weight for _total, weight in weights)
    cumulative = 0.0
    for total, weight in weights:
        cumulative += weight
        if cumulative >= AISHA_LOW_TIER_COUNT_UPPER_QUANTILE * weight_sum:
            return total
    return weights[-1][0]


def _aisha_early_round_count_window_bounds(
    *,
    center: int,
    count_floor: int,
    notes: list[str],
) -> tuple[int, int]:
    """±2 count prior window for audit_aisha_early_round (R1–R2 live cap path).

    May return lower>upper when center exceeds AISHA_EARLY_ROUND_COUNT_WINDOW_CAP; caller
    should run fixed-band clamp first, then _maybe_expand_aisha_early_inverted_count_window.
    """
    del notes  # expand note is emitted only after band clamp fails to restore a range
    lower = max(count_floor, center - 2, 1)
    upper = min(
        AISHA_EARLY_ROUND_COUNT_WINDOW_CAP,
        max(lower, center + 2),
    )
    return lower, upper


def _maybe_expand_aisha_early_inverted_count_window(
    *,
    lower: int,
    upper: int,
    center: int,
    count_floor: int,
    notes: list[str],
) -> tuple[int, int]:
    """After fixed-band clamp: expand center±2 only if the capped window is still empty."""
    if lower <= upper:
        return lower, upper
    if os.environ.get(AISHA_DISABLE_EARLY_COUNT_WINDOW_EXPAND) == "1":
        return lower, upper
    lower = max(count_floor, center - 2, 1)
    upper = min(_TOTAL_COUNT_PRIOR_WINDOW_CAP, max(lower, center + 2))
    notes.append(
        f"{AISHA_EARLY_ROUND_COUNT_WINDOW_EXPANDED_NOTE}:{lower}-{upper}@center{center}"
    )
    return lower, upper


def _total_count_candidates(
    evidence: RefEvidence,
    notes: list[str],
    *,
    early_round_lightweight: bool = False,
    avg_cells_count_hint: int | None = None,
    avg_cells_count_hint_public: bool = False,
    round_no: int | None = None,
    probs: dict[str, float] | None = None,
    occ_cap: float | None = None,
    ethan_rough_grid_hint: int | None = None,
    empirical_count_center: int | None = None,
) -> tuple[list[int], int | None]:
    calibrated = _SHIPWRECK_CALIBRATED_PRIOR.get()
    prior_radius = int(math.ceil(2*calibrated['count_sd'])) if calibrated is not None else 4
    if evidence.total_count is not None:
        total_count = int(evidence.total_count)
        fixed_total = sum(max(0, int(value)) for value in evidence.fixed_counts.values())
        if evidence.phase == "manual" and fixed_total != total_count:
            notes.append("manual_total_count_prior_enumeration")
            return [total_count], total_count
        if _should_use_sparse_exact_total_prior(evidence):
            if (
                _quality_cells_fully_pinned(evidence)
                and _quality_cells_blocks_sparse_exact_prior(evidence)
                and int(total_count) >= 40
            ):
                notes.append("pinned_quality_cells_sparse_prior")
            notes.append("sparse_exact_total_prior_enumeration")
            return [total_count], total_count
        return [total_count], None
    map_center = (
        empirical_count_center
        if calibrated is None and type(empirical_count_center) is int
        and 1 <= empirical_count_center <= _TOTAL_COUNT_PRIOR_WINDOW_CAP
        else _default_total_count(evidence.map_id)
    )
    victor_high_total = _victor_three_means_high_count_sum(evidence)
    fixed_low_counts = [
        evidence.fixed_counts.get(key)
        for key in QUALITY_KEYS
        if key not in {"q4", "q5", "q6"}
    ]
    if victor_high_total is not None and all(
        type(count) is int and count >= 0 for count in fixed_low_counts
    ):
        # The fixed complementary tiers and the high-tier sum cover the
        # entire canonical quality partition.  This is a hard candidate N,
        # not a new observed total_count; minima cannot supply this proof.
        total_count = victor_high_total + sum(fixed_low_counts)
        _append_source_note_once(
            notes, f"victor_three_means_total_from_fixed_low:{total_count}"
        )
        return [total_count], total_count
    has_live_input = bool(
        evidence.source_notes
        or evidence.fixed_counts
        or evidence.min_counts
        or evidence.count_sums
        or evidence.avg_cells
        or evidence.avg_values
        or evidence.quality_values
        or evidence.total_grid_target
    )
    if not has_live_input:
        if evidence.phase in {"settled", "manual"}:
            return [], None
        center = max(map_center, _known_count_floor(evidence))
        center = _draw_hero_count_center(center, evidence, notes, round_no=round_no, occ_cap=occ_cap)
        if early_round_lightweight and calibrated is None:
            lower, upper = _aisha_early_round_count_window_bounds(
                center=center,
                count_floor=_known_count_floor(evidence),
                notes=notes,
            )
            notes.append(AISHA_EARLY_ROUND_COUNT_PRIOR_WINDOW_NOTE)
            lower, upper = _maybe_expand_aisha_early_inverted_count_window(
                lower=lower,
                upper=upper,
                center=center,
                count_floor=_known_count_floor(evidence),
                notes=notes,
            )
        else:
            lower = max(_known_count_floor(evidence), center - prior_radius, 1)
            upper = min(_TOTAL_COUNT_PRIOR_WINDOW_CAP, max(lower, center + prior_radius))
        notes.append("total_count_from_map_default_prior")
        notes.append(f"total_count_prior_center:{center}")
        return list(range(lower, upper + 1)), center
    for key in QUALITY_KEYS:
        avg_minimum = _hard_avg_cells_min_count(key, evidence)
        if avg_minimum is not None and avg_minimum > 1:
            _append_source_note_once(
                notes,
                f"hard_{key}_avg_cells_min_count:{avg_minimum}",
            )
    if _should_defer_total_count_prior(evidence) and calibrated is None:
        notes.append("waiting_total_count")
        notes.append("waiting_total_count:grid_only")
        return [], None
    center = max(map_center, _known_count_floor(evidence))
    residual_center = _count_prior_center_from_grid_quality_residual(
        evidence,
        source_notes=notes,
        baseline_center=center,
    )
    low_tier_upper = (
        _aisha_low_tier_count_upper(evidence, probs, round_no=round_no)
        if probs is not None
        else None
    )
    _is_ethan_count = normalize_hero_key(evidence.hero) == "ethan"
    _ethan_grid_count = (
        os.environ.get("ETHAN_DISABLE_GRID_COUNT_WINDOW") != "1"
        and _is_ethan_count
        and evidence.total_grid_target is not None
        and evidence.total_grid_target > 0
    )
    if residual_center is not None:
        center = residual_center
        if (
            _run_env_get(AISHA_LOW_TIER_RESIDUAL_CENTER_CAP_DISABLE) != "1"
            and low_tier_upper is not None
            and int(center) > int(low_tier_upper)
        ):
            old_center = int(center)
            center = int(low_tier_upper)
            notes.append(
                f"{AISHA_LOW_TIER_COUNT_UPPER_NOTE}_center:"
                f"{old_center}->{int(low_tier_upper)}"
            )
        # Ethan Phase-1 fix (2026-07-05, rv_analyze OLD pool): the residual center OVERRODE the
        # grid-implied floor — deep villa vaults (grid 119-139, truth 42-47 items) kept center 28
        # (map default) because the residual read low, and the ±4 window then EXCLUDED the truth
        # (窗含真率 59-77% at R2-R4, est med -6..-8.5 items). For ethan (grid-primary: the total
        # grid anchor is his best-calibrated signal, MAE 4-6%) the anchored grid is a hard count
        # floor story: count >= grid / (generous cells-per-item). Take max, don't override.
        if _ethan_grid_count:
            _g_floor = int(round(float(evidence.total_grid_target) / 3.6))
            if _g_floor > center:
                center = _g_floor
                notes.append(f"ethan_grid_count_center_floor:{_g_floor}")
    elif evidence.total_grid_target is not None and evidence.total_grid_target > 0:
        center = max(center, int(round(evidence.total_grid_target / 3.0)), 1)
    # Public all-items avg-cells cross-check: when the public total_avg_cells is known, the geometry
    # grid + avg pin count = grid / avg (avg_cells_count_hint). BIDIRECTIONAL (2026-06-20, user-designed,
    # eval_avg_conform: 件数 bias -4.4->-0.4, 符合度好, 总格不受损): make count CONFORM to the public
    # avg in BOTH directions — not just raise an under-estimate, also lower an over-estimate — so the
    # displayed count/grid satisfy grid = count×avg. (Old behaviour was one-directional > center only,
    # which left count un-conformed when grid/avg < the prior.) Rollback AISHA_DISABLE_AVG_COUNT_CONFORM=1.
    if avg_cells_count_hint is not None:
        # BIDIRECTIONAL conform 只在 hint 来自【公开均格】时(精确约束)生效; 来自残差 per-item 估计
        # (无公开均格, 不可靠)时保持旧【单向只上修】—— 否则会把真密深仓(2410)误压欠(残差 hint<先验)。
        if avg_cells_count_hint_public and not os.environ.get("AISHA_DISABLE_AVG_COUNT_CONFORM"):
            if int(avg_cells_count_hint) != int(center):
                center = int(avg_cells_count_hint)
                notes.append(f"total_count_from_grid_avg_cells:{center}")
        elif avg_cells_count_hint > int(center):  # 残差 hint 或 flag 关闭 → 单向只上修
            center = int(avg_cells_count_hint)
            notes.append(f"total_count_from_grid_avg_cells:{center}")
    # center_informed: True when the center was set from a grid/depth-derived hint
    # (avg_cells_count_hint, public or residual) rather than left at the bare map default.
    # This tells _draw_hero_count_center's informed-center guard to trust the physical read
    # over the map-constant boost floor when the vault reads smaller than the map median.
    center_informed = avg_cells_count_hint is not None
    center = _draw_hero_count_center(center, evidence, notes, round_no=round_no, occ_cap=occ_cap, center_informed=center_informed)
    if early_round_lightweight and calibrated is None:
        lower, upper = _aisha_early_round_count_window_bounds(
            center=center,
            count_floor=_known_count_floor(evidence),
            notes=notes,
        )
        notes.append(AISHA_EARLY_ROUND_COUNT_PRIOR_WINDOW_NOTE)
    else:
        lower = max(_known_count_floor(evidence), center - prior_radius, 1)
        upper = max(lower, center + prior_radius)
        # Ethan Phase-1 fix, part 2: villa item counts vary 26-47 (cells/item 2.4-3.9) — a ±4
        # window around ANY single center cannot cover the family variance. With an anchored grid,
        # open the UPPER side to grid/2.4 (dense-packing reading) so the enumeration can reach
        # deep-vault truths; prior weights still concentrate mass near the center, and 56xx/NEW
        # (窗含真率 94-97% already) only gains ~1 slot. Kill: ETHAN_DISABLE_GRID_COUNT_WINDOW=1.
        if _ethan_grid_count:
            _g_upper = int(round(float(evidence.total_grid_target) / 2.4))
            if _g_upper > upper:
                upper = _g_upper
                notes.append(f"ethan_grid_count_window_upper:{_g_upper}")
        elif (
            os.environ.get("ETHAN_DISABLE_GRID_COUNT_WINDOW") != "1"
            and _is_ethan_count
            and ethan_rough_grid_hint is not None
            and ethan_rough_grid_hint > 0
        ):
            # Guard-fallback games (no anchored target): open the upper side from the ROUGH
            # rectangle read only — no center shift, prior weights untouched.
            _g_upper = int(round(float(ethan_rough_grid_hint) / 2.4))
            if _g_upper > upper:
                upper = _g_upper
                notes.append(f"ethan_rough_grid_count_window_upper:{_g_upper}")
        upper = min(_TOTAL_COUNT_PRIOR_WINDOW_CAP, upper)
    # Hard fixed counts cap the soft prior: clamp the window to the reachable band implied by
    # the fixed per-quality counts (totals outside it have zero combos). Loss-free; when the soft
    # window sits entirely above the band (soft center over-states vs the fixed counts), re-anchor
    # to the band so the engine enumerates the feasible totals instead of returning
    # no_reachable_combo. Only bites when something is fixed (band is None otherwise).
    band = (
        None
        if os.environ.get("AISHA_DISABLE_FIXED_BAND_CLAMP") == "1"
        else _fixed_count_reachable_total_band(evidence, probs, base_total=upper)
    )
    if band is not None:
        band_lo, band_hi = band
        clamped_lo = max(lower, band_lo)
        clamped_hi = min(upper, band_hi)
        if clamped_lo > clamped_hi:
            notes.append(f"count_window_reanchored_to_fixed_band:{lower}-{upper}->{band_lo}-{band_hi}")
            lower, upper = band_lo, band_hi
            center = max(band_lo, min(center, band_hi))
        elif (clamped_lo, clamped_hi) != (lower, upper):
            notes.append(f"count_window_clamped_to_fixed_band:{lower}-{upper}->{clamped_lo}-{clamped_hi}")
            lower, upper = clamped_lo, clamped_hi
            center = max(lower, min(center, upper))
    if early_round_lightweight:
        lower, upper = _maybe_expand_aisha_early_inverted_count_window(
            lower=lower,
            upper=upper,
            center=center,
            count_floor=_known_count_floor(evidence),
            notes=notes,
        )
        center = max(lower, min(center, upper))
    notes.append("total_count_from_ref_count_prior")
    notes.append(f"total_count_prior_center:{center}")
    return list(range(lower, upper + 1)), center


def _readmit_soft_avg_value_lock_neighbors(
    key: str,
    result: list[int],
    evidence: RefEvidence,
    *,
    minimum: int,
    maximum: int,
    expected: float,
    sigma: float,
) -> list[int]:
    """Anti-false-lock for high-tier (q4/q5/q6) avg_value collapse (env AHMAD_ENABLE_GOLDPURPLE_ANTILOCK,
    default OFF). When a soft_avg_value tier's divisor-multiple filter has collapsed the count-prior
    window to a SINGLE value V (a manufactured unique lock, e.g. ahmed 2501 purple: window [8..19] ∩
    divisor-multiples {7,14,21,28} = {14}, truth 7 sits one step below the window floor), re-admit the
    nearest divisor-multiple neighbor on each side that the window cut off — within the untightened
    full-radius window, or exactly one feasibility-step beyond its edge — so the point-lock becomes a
    bracketing range. Truth-agnostic (the multinomial weight still ranks the admitted counts); fires
    ONLY on single-value collapse, so multi-value windows and genuinely-pinned tiers (nearest neighbor
    ≥2 steps outside full radius) are untouched. Default OFF pending a full-library sweep."""
    if os.environ.get("AHMAD_ENABLE_GOLDPURPLE_ANTILOCK") != "1":
        return result
    if key not in ("q4", "q5", "q6") or len(result) != 1:
        return result
    if key not in evidence.soft_avg_value_keys:
        return result
    v_lock = int(result[0])
    avg = evidence.avg_values.get(key)
    if avg is None or not _avg_value_has_positive_signal(avg):
        return result
    full_radius = max(1, min(5, int(math.ceil(1.6 * sigma))))
    full_lower = max(minimum, int(math.floor(expected - full_radius)))
    full_upper = min(maximum, int(math.ceil(expected + full_radius)))
    out = set(result)
    # nearest divisor-multiple strictly below the lock
    for candidate in range(v_lock - 1, minimum - 1, -1):
        if _avg_value_count_matches_for_public_evidence(
            key, candidate, avg, evidence.source_notes
        ):
            step = v_lock - candidate
            if candidate >= full_lower - step:  # within full window or one feasibility-step beyond edge
                out.add(candidate)
            break
    # nearest divisor-multiple strictly above the lock
    for candidate in range(v_lock + 1, maximum + 1):
        if _avg_value_count_matches_for_public_evidence(
            key, candidate, avg, evidence.source_notes
        ):
            step = candidate - v_lock
            if candidate <= full_upper + step:
                out.add(candidate)
            break
    return sorted(out)


def _physical_count_ceiling(total: int, key: str, evidence: RefEvidence) -> int:
    """Hard upper bound on this tier's count: the total minus every OTHER tier's committed items
    (fixed counts, or their effective minimum when unfixed). Unlike the multinomial prior window this
    is arithmetic, not belief — used by the BUG-G false-lock widen below."""
    used = 0
    for other in QUALITY_KEYS:
        if other == key:
            continue
        fixed_other = evidence.fixed_counts.get(other)
        if fixed_other is not None:
            used += max(0, int(fixed_other))
        else:
            used += max(0, int(_effective_min_count(other, evidence)))
    return max(0, int(total) - used)


def _victor_three_means_high_count_sum(evidence: RefEvidence) -> int | None:
    """Identify the live hard three-average / high-tier-sum evidence family.

    The sum bounds all three count domains without a probability window.  A
    soft mean, another hero or a non-live phase retains its existing lane.
    """
    high_total = evidence.count_sums.get("q4q5q6")
    if (
        normalize_hero_key(evidence.hero) != "victor"
        or evidence.phase not in {"reading", "bidding"}
        or type(high_total) is not int
        or high_total < 0
    ):
        return None
    for key in ("q4", "q5", "q6"):
        avg = evidence.avg_cells.get(key)
        if (
            type(avg) not in (int, float)
            or not math.isfinite(avg)
            or avg <= 0.0
            or key in evidence.soft_avg_cell_keys
        ):
            return None
    return high_total


def _prior_count_values(
    total: int,
    key: str,
    evidence: RefEvidence,
    probs: dict[str, float],
    widen_fired: set[str] | None = None,
    *,
    tight_high_total: bool | None = None,
    admit_low_q6_gap: bool = False,
) -> list[int]:
    fixed = evidence.fixed_counts.get(key)
    exact_cells = _quality_exact_cells(key, evidence)
    if fixed is not None:
        fixed_int = max(0, int(fixed))
        if exact_cells is not None and not _can_compose_grid_total_with_q6_catalog(
            key, fixed_int, exact_cells
        ):
            return []
        if not _quality_count_matches_value_evidence(key, fixed_int, evidence):
            return []
        return [fixed_int]
    minimum = _effective_min_count(key, evidence)
    maximum = total
    if exact_cells is not None:
        maximum = min(maximum, exact_cells)
        if exact_cells == 0:
            maximum = 0
            minimum = max(minimum, 0)
    victor_high_total = _victor_three_means_high_count_sum(evidence)
    if victor_high_total is not None and key in {"q4", "q5", "q6"}:
        # The three hard means constrain integer count/cell pairs, not the
        # reduced denominator alone.  Keep every possible multiple in all
        # three tiers; q4-only widening still lets q5/q6 priors erase arms.
        reserve = sum(
            int(evidence.fixed_counts[other])
            if other in evidence.fixed_counts
            else _effective_min_count(other, evidence)
            for other in ("q4", "q5", "q6")
            if other != key
        )
        maximum = min(
            maximum,
            victor_high_total - reserve,
            _physical_count_ceiling(total, key, evidence),
        )
        return _filter_quality_counts_for_avg_value(
            key,
            (
                count
                for count in range(minimum, maximum + 1)
                if _avg_grid_options_for_evidence(
                    count, evidence.avg_cells[key], key, evidence
                )
                and (
                    exact_cells is None
                    or _can_compose_grid_total_with_q6_catalog(
                        key, count, exact_cells
                    )
                )
            ),
            evidence,
        )
    p = max(0.0, min(1.0, float(probs.get(key, 0.0))))
    expected = total * p
    sigma = math.sqrt(max(0.75, total * p * max(0.0, 1.0 - p)))
    radius = max(1, min(5, int(math.ceil(1.6 * sigma))))
    tight_radius = radius
    tight_prior_enabled = (
        _sparse_exact_high_total_tight_prior(evidence)
        if tight_high_total is None
        else bool(tight_high_total)
    )
    if tight_prior_enabled:
        tight_radius = max(1, min(radius, 2))
        radius = tight_radius
    lower = max(minimum, int(math.floor(expected - radius)))
    upper = min(maximum, int(math.ceil(expected + radius)))
    anchors = {
        minimum,
        int(round(expected)),
        int(math.floor(expected)),
        int(math.ceil(expected)),
    }
    values = {value for value in range(lower, upper + 1)}
    values.update(value for value in anchors if minimum <= value <= maximum)
    if admit_low_q6_gap and key == "q6" and minimum == 0 and 0 in values:
        positive_values = [value for value in values if value > 0]
        if positive_values:
            # A soft prior window may start at four or higher while retaining
            # zero as a disconnected minimum anchor.  The caller has already
            # established that no red fact justifies that gap.
            values.update(range(1, min(positive_values)))
    if (
        f"public_{key}_avg_value_presence_fallback"
        in evidence.source_notes
    ):
        # This path runs only after the original sparse domain produced zero combos and a positive
        # public mean was downgraded. Expand only that tier, and only to the arithmetic ceiling left
        # by the exact total and every other tier's hard/minimum count. The global max_combos budget
        # still bounds successful enumeration; unaffected tiers retain their sparse windows.
        presence_ceiling = min(
            maximum,
            _physical_count_ceiling(total, key, evidence),
        )
        if presence_ceiling >= minimum:
            values.update(range(minimum, presence_ceiling + 1))
    avg = evidence.avg_cells.get(key)
    if avg is not None and avg > 0:
        avg_valid = [
            value
            for value in range(minimum, maximum + 1)
            if _avg_grid_options_for_evidence(value, avg, key, evidence)
        ]
        if avg_valid or _q5_catalog_cell_compose_enabled(key):
            # Wire-precision avg_cells (e.g. 10/3 = 3.3333332, not a 2-decimal display) means the
            # tier total cells = avg*count is an exact integer, so the count must compose an integer
            # grid at that avg. Drop prior-window counts that can't (q4 avg 10/3 -> only multiples of
            # 3; 4/7/10 are impossible) by INTERSECTING, instead of just unioning the feasible set in.
            #
            # 族A / BUG-I (2026-07-11, 群友 #4 5605 金 4/5/6 @均格3.5 · #13 5606 紫 7/9/12 @均格2.25):
            # the old gate SKIPPED the intersection whenever the avg looked like a clean display value
            # ("so a true 2-decimal avg never over-prunes") — and then arithmetically IMPOSSIBLE counts
            # sailed through: avg 3.5 needs an integer grid, so 5 golds would need 17.5 cells; the truth
            # (6 golds × 3.5 = 21 cells) was displayed alongside an impossible 5. That exemption was
            # unnecessary: `_avg_grid_options` ALREADY handles display rounding — it accepts every grid
            # whose GAME-DISPLAYED average equals the reading (_ref_avg_matches_game_display), so a
            # rounded avg keeps all counts it could legitimately have come from and only drops the ones
            # it could not. Intersect for every non-settled avg; `or feasible` keeps the set non-empty
            # if our display formatting ever disagrees with the game's, so we can never prune to nothing.
            #
            # BUG-I refinement (审计窗口 2026-07-11 对抗验证: 4/1435 ahmed 局把真值件数剪出了范围).
            # Their counter-example is instructive: ahmed 5605 R4, q1 均格 **2.0**, truth 17 items/34
            # cells — 17 × 2.0 = 34, perfectly feasible. It was NOT pruned by arithmetic. With a
            # denominator-1 avg EVERY count composes an integer grid, so `avg_valid` covers the whole
            # physical range and the OLD union quietly REPLACED the multinomial window with it; the
            # truth (17, outside the window [10..16]) rode in on that accident. Intersecting restored
            # the window and dropped it. An avg that rules NOTHING out must not narrow anything, so
            # only intersect when the feasible set is a strict subset of the window's own span — i.e.
            # when the avg genuinely constrains (3.5 -> evens, 2.25 -> multiples of 4). Otherwise keep
            # the old union byte-for-byte. Kill: BIDKING_DISABLE_AVG_DISPLAY_FEASIBILITY=1.
            _avg_constrains = len(avg_valid) < (maximum - minimum + 1)
            if (
                evidence.phase != "settled"
                and _avg_constrains
                and (
                    not _ref_avg_looks_like_display_reading(float(avg))
                    or not _avg_display_feasibility_disabled()
                )
            ):
                feasible = set(avg_valid)
                narrowed = {value for value in values if value in feasible}
                # BUG-G (2026-07-11, 群友加菲 aisha 5606 R4 金假锁): the intersection is a SOFT prior
                # window ∩ a HARD arithmetic constraint. When the multinomial window (probs*total ±
                # 1.6σ) happens to straddle only ONE feasible multiple, the result is a ZERO-WIDTH
                # count "lock" that the evidence never justified — 5606: 金均格 7.2 = 36/5 → counts
                # must be multiples of 5, but the q5 window [2,8] kept only 5, so 金 locked 5件/36格
                # while the truth was 10件/72格 (极品估价 552,983 → 55.3k/件 at 10 vs an absurd
                # 110.6k/件 at 5). The residual 12 items were then all shoved into red ([7,7,7] vs
                # truth 2). Widen back to every arithmetically-feasible multiple that FITS PHYSICALLY
                # (total − other tiers' fixed/min counts) whenever the intersection collapses to a
                # single value: a soft belief must never delete a physically reachable composition.
                # The combo weights then decide honestly (value-plausibility bias below picks 10).
                # Kill: BIDKING_DISABLE_AVG_MULTIPLE_FALSE_LOCK_WIDEN=1.
                # HIGH TIERS ONLY (q5/q6). The damage this repairs is the gold/red cascade: a
                # too-low gold count dumps its items into the red residual (5606: 红 [7,7,7] vs
                # truth 2). The low tiers already own dedicated antilock features for the same
                # arithmetic (q1: EXACT_TOTAL_Q1_AVG_DOMAIN untighten; q4/q5: goldpurple antilock),
                # and an unscoped widen collided with both — it broke their rollback baselines and
                # dragged q1's calibrated lower tail down (2408: lo 10 -> 5, a prior-implausible
                # low multiple). Keep this lever to the tier family the author actually reported.
                if (
                    key in ("q5", "q6")
                    and len(narrowed) <= 1
                    and os.environ.get("BIDKING_DISABLE_AVG_MULTIPLE_FALSE_LOCK_WIDEN") != "1"
                ):
                    ceiling = _physical_count_ceiling(total, key, evidence)
                    reachable = {value for value in feasible if value <= ceiling}
                    if len(reachable) > len(narrowed):
                        narrowed = narrowed | reachable
                        if widen_fired is not None:
                            widen_fired.add(key)
                values = narrowed or feasible
            else:
                values.update(avg_valid)
        values = _union_exact_total_q1_avg_feasible_counts(
            key=key,
            values=values,
            evidence=evidence,
            minimum=minimum,
            maximum=maximum,
            expected=expected,
            sigma=sigma,
            avg=float(avg),
            tight_radius=tight_radius,
            widen_fired=widen_fired,
        )
    avg_value = evidence.avg_values.get(key)
    if avg_value is not None and _avg_value_has_positive_signal(avg_value):
        if key not in evidence.soft_avg_value_keys:
            avg_value_valid = [
                value
                for value in range(minimum, maximum + 1)
                if _quality_count_matches_value_evidence(key, value, evidence)
            ]
            if avg_value_valid:
                values.update(avg_value_valid)
        elif (
            os.environ.get("AHMAD_DISABLE_SOFT_AVG_VALUE_FULL_DOMAIN") != "1"
            and evidence.total_count is None
            and str(evidence.hero or "") in SOFT_AVG_VALUE_WIDEN_HEROES
        ):
            # B4 (gabriela 2402 q4 avg 5497.61 -> truth 13, engine gave [5,8,11]): a fractional public
            # tier-mean is an EXACT integer-product constraint (total value = avg*count integer -> count is
            # a multiple of the reduced denominator). _filter_quality_counts_for_avg_value applies this
            # divisor lock for soft keys too, but can only KEEP counts already in `values`; when the true
            # multiple falls outside the probability window (total_count=None draw-heroes: window centered
            # on total*p, e.g. total 30 -> q4 ~[7..12], excludes 13) the lock never sees it and the tier
            # stays wrongly wide. Union the full-domain divisor-multiples so the lock can reach them --
            # symmetric with the avg_cells full-domain union above, using the SAME predicate the lock
            # applies (only counts the lock would keep are admitted). Gated on a fractional denominator
            # (the lock's own gate): an integer-valued mean constrains nothing and must not widen.
            avg_fraction = _avg_value_fraction(avg_value)
            if avg_fraction is not None and avg_fraction.denominator > 1:
                # Reach only divisor-multiples that are (a) near the probability window (within one extra
                # radius of its edges) and (b) JOINTLY FEASIBLE — a count > maximum - sum(other tiers' min
                # counts) leaves no room for the rest and would only trip the avg_value conflict fallback
                # (which discards ALL public avgs and re-runs), not lock anything. gabriela q4 13 (other_min
                # 1, fits total 30) locks; aisha 2402 injected q4 14 (other_min 25, cannot fit) does not.
                other_min = sum(_effective_min_count(k, evidence) for k in QUALITY_KEYS if k != key)
                near_lo = max(minimum, lower - radius)
                near_hi = min(maximum, upper + radius, maximum - other_min)
                soft_valid = [
                    value
                    for value in range(near_lo, near_hi + 1)
                    if _avg_value_count_matches_for_public_evidence(
                        key, value, avg_value, evidence.source_notes
                    )
                ]
                if soft_valid:
                    values.update(soft_valid)
    if exact_cells is not None:
        valid = _filter_quality_counts_for_avg_value(
            key,
            (
                value
                for value in sorted(values)
                if _can_compose_grid_total_with_q6_catalog(key, value, exact_cells)
            ),
            evidence,
        )
        if valid:
            return valid
        return _filter_quality_counts_for_avg_value(
            key,
            (
                value
                for value in range(minimum, maximum + 1)
                if _can_compose_grid_total_with_q6_catalog(key, value, exact_cells)
            ),
            evidence,
        )
    result = _filter_quality_counts_for_avg_value(key, sorted(values), evidence)
    return _readmit_soft_avg_value_lock_neighbors(
        key, result, evidence, minimum=minimum, maximum=maximum, expected=expected, sigma=sigma
    )


def _evidence_grid_avg_cells_log_penalties(
    counts: dict[str, int],
    grids: dict[str, float],
    evidence: RefEvidence,
    *,
    include_grid_target: bool = True,
) -> float:
    logw = 0.0
    if include_grid_target and evidence.total_grid_target is not None:
        total_grid = sum(grids.values())
        diff = total_grid - evidence.total_grid_target
        logw -= min(30.0, (diff * diff) / (2 * 6.0 * 6.0))
    for key, avg in evidence.avg_cells.items():
        count = counts.get(key, 0)
        if count <= 0 or avg is None or avg <= 0:
            continue
        if (
            key == "q5"
            and count
            in _aisha_q5_exact_value_public_avg_supported_counts(evidence)
        ):
            # The hard-total grid fitter assigns the unpinned q5/q6 residual before
            # the public joint is reconciled. In the guarded state the exact catalog
            # has independently proved that this q5 count can realize the public
            # average (for example 7/14), so scoring the provisional 7/28 fit against
            # avg=2.0 double-counts a geometry that is replaced at publication time.
            # Skip only this one soft-average contribution. The hard total-grid
            # penalty, generic count prior and exact-value likelihood all remain.
            continue
        sigma = {
            "q1": 0.35,
            "q3": 0.35,
            "q4": 0.45,
            "q5": 0.55,
            "q6": 0.70,
        }.get(key, 0.55) / max(1.0, math.sqrt(count))
        diff = grids.get(key, 0.0) / count - avg
        logw -= min(30.0, 0.5 * (diff * diff) / (sigma * sigma))
    return logw


def _aisha_q5_exact_value_public_avg_supported_counts(
    evidence: RefEvidence,
) -> frozenset[int]:
    """Reachable q5 counts for the narrow 4501 exact-value/public-average lane.

    Public avg-cells stays soft: unsupported counts are not removed. This helper
    only prevents an exact catalog-supported count from being penalized against
    the fitter's pre-reconciliation q5 grid.
    """
    if (
        _run_env_get(AISHA_Q5_EXACT_VALUE_PUBLIC_AVG_SUPPORT_DISABLE) == "1"
        or normalize_hero_key(evidence.hero) != "aisha"
        or int(evidence.map_id or 0) != 4501
        or evidence.phase != "bidding"
        or evidence.total_count is None
        or not any(
            note in EXACT_TOTAL_COUNT_SOURCE_NOTES
            for note in evidence.source_notes
        )
        or _hard_total_grid_target_int(evidence) is None
        or not any(
            note in AISHA_Q5_EXACT_VALUE_PUBLIC_AVG_HARD_TOTAL_GRID_NOTES
            for note in evidence.source_notes
        )
        or "q5" not in evidence.soft_avg_cell_keys
        or "public_q5_avg_cells" not in evidence.source_notes
        or evidence.fixed_counts.get("q5") is not None
        or evidence.quality_cells.get("q5") is not None
        or evidence.q5_known_item_facts
        or any(
            evidence.fixed_counts.get(key) is None
            or _quality_exact_cells(key, evidence) is None
            for key in ("q1", "q3", "q4")
        )
        or _quality_has_direct_count_grid_value_evidence("q6", evidence)
    ):
        return frozenset()
    total_value = _quality_exact_value("q5", evidence)
    avg_cells = _safe_float(evidence.avg_cells.get("q5"))
    if (
        total_value is None
        or avg_cells is None
        or avg_cells <= 0
    ):
        return frozenset()
    status, states = _cached_aisha_q5_exact_value_public_avg_support(
        float(total_value),
        float(avg_cells),
        int(evidence.total_count),
        tuple(evidence.q5_known_item_facts),
    )
    counts = frozenset(int(count) for count, _cells in states)
    return counts if status == "ok" and len(counts) > 1 else frozenset()


# Per-item cell size of a high tier GROWS with its known cell total: big gold/red hoards hold bigger
# items (scripts/audit_high_tier_cells_to_count.py, aisha library). A clamped linear divisor fit to
# the per-cell-bucket means; count center = known_cells / divisor. The combo multinomial alone centers
# the count on probs*total and ignores this, so a large known gold footprint under-counts (2406 R3:
# 28 gold cells -> engine 5 vs 6 truth; 28/4.6 ~= 6). (slope, intercept, lo, hi)
_HIGH_TIER_CELL_DIVISOR_FIT = {
    "q5": (0.0975, 1.87, 2.2, 4.8),  # gold: cells 4->2.3 ... 28->4.6
    "q6": (0.110, 2.10, 2.2, 5.6),  # red:  cells 4->2.5 ... 16->3.9 ... plateau
}
# H5 (2026-07-10): family-refit divisor tables — calibrated, then REFUTED on the value sweep.
# DEFAULT OFF (opt-in AISHA_ENABLE_FAMILY_HIGH_TIER_DIVISOR=1); kept as a documented negative result.
# Calibration: 4969-warehouse full pool, split-half CV (scripts/_tmp_h5_fit_models.py). The refits DO
# beat the old 400-sample global fit on marginal count error (q5: ship 1.47->1.34, villa 1.07->0.96,
# 56xx 1.15->1.09, hidden 2.83->1.99) — but the 200-cap aisha clean_eval OFF/ON sweep was NET NEGATIVE:
# changed=8, better=0, WORSE=8 (2501r5 -21.2->-22.6, 2510r5 -39.0->-40.2, 5601r3 -11.8->-13.2,
# 2501r4 +23.3->+28.4 ...), scope audit clean. Mechanism: the lever fires exactly on "gold cells known
# via tool + red invisible" RED-HEAVY vaults, where the family marginal (dominated by small-gold
# typical vaults) pushes the gold count UP (ship @12格 2.65/件 vs global 3.04) -> red residual gets
# squeezed -> deeper red under-estimates. The old global fit's higher divisors are accidentally
# red-protective in this regime. Marginal count-CV is the WRONG loss here; do not re-ship this without
# a red-protective loss design. Also refuted on the same pool: cross-tier "vault size regime" scaling
# (locked q3+q4 per-item size; beta 0.03-0.25, r<=0.14, CV gain nil). The flagged bug vaults (2508
# gold 4.0格/件@12, 2501 4.5@18, 5609 7.5@15) are in-family outliers no center model reaches; their
# remaining money is red PRICE (H7 phase2 / H2 domain). Families with <120 samples fall back to global.
_HIGH_TIER_CELL_DIVISOR_FIT_BY_FAMILY: dict[str, dict[str, tuple[float, float, float, float]]] = {
    "q5": {
        "shipwreck": (0.075, 1.75, 2.00, 5.00),
        "villa": (0.115, 1.65, 1.80, 5.00),
        "map_56xx": (0.115, 1.65, 2.00, 5.40),
        "map_23xx": (0.190, 1.35, 1.80, 5.00),
        "hidden": (0.055, 1.50, 2.47, 5.27),
    },
    "q6": {
        "shipwreck": (0.155, 1.50, 1.80, 6.26),
        "villa": (0.200, 1.40, 1.80, 6.33),
        "map_56xx": (0.125, 1.60, 1.80, 5.43),
        "hidden": (0.060, 1.50, 2.25, 4.83),
    },
}
HIGH_TIER_FAMILY_DIVISOR_NOTE_PREFIX = "hightier_family_divisor:"
# Strength of the soft pull toward the cell-implied count center (Gaussian sigma; larger = weaker).
HIGH_TIER_KNOWN_CELLS_COUNT_BIAS_SIGMA = 2.0


def _family_high_tier_divisor_enabled() -> bool:
    # DEFAULT OFF — proven net-negative on the value sweep (see H5 comment above). Opt-in for
    # re-calibration experiments only.
    return os.environ.get("AISHA_ENABLE_FAMILY_HIGH_TIER_DIVISOR") == "1"


def _high_tier_count_center_from_cells(
    key: str, cells: int, *, family: str | None = None
) -> float | None:
    fit = None
    if family is not None and _family_high_tier_divisor_enabled():
        fit = _HIGH_TIER_CELL_DIVISOR_FIT_BY_FAMILY.get(key, {}).get(family)
    if fit is None:
        fit = _HIGH_TIER_CELL_DIVISOR_FIT.get(key)
    if fit is None or cells <= 0:
        return None
    slope, intercept, lo, hi = fit
    divisor = min(hi, max(lo, intercept + slope * cells))
    return cells / divisor


def _known_cells_count_bias_log(counts: dict[str, int], evidence: RefEvidence) -> float:
    """Aisha-only soft nudge of a high-tier combo count toward its cell-implied center.

    When q5/q6 CELLS are known (e.g. gold via 极品扫描) but the count is not locked, the empirical
    cells->count center (which rises with the hoard size) corrects the multinomial's probs*total
    under-count. A loose Gaussian keeps it a nudge, not an override -- combos still satisfy the hard
    cell composition; this only reweights which surviving count is most likely.
    """
    if normalize_hero_key(evidence.hero) != "aisha":
        return 0.0
    sigma = HIGH_TIER_KNOWN_CELLS_COUNT_BIAS_SIGMA
    try:
        sigma = float(os.environ.get("AISHA_HIGH_TIER_COUNT_BIAS_SIGMA", sigma))
    except (TypeError, ValueError):
        pass
    if sigma <= 0:
        return 0.0
    family = _ethan_map_family(evidence.map_id)
    bias = 0.0
    for key in ("q5", "q6"):
        if key in evidence.fixed_counts:
            continue  # count already locked -> nothing to nudge
        exact = _exact_integer_quality_cell(evidence.quality_cells.get(key))
        if exact is None or exact <= 0:
            continue
        center = _high_tier_count_center_from_cells(key, int(exact), family=family)
        if center is None:
            continue
        bias -= 0.5 * ((float(counts[key]) - center) / sigma) ** 2
    return bias


# BUG-G (2026-07-11, 群友加菲 aisha 5606 R4): 金均格 7.2 + 金总价 552,983 SAME ROUND, yet the count
# multiple ambiguity {5,10,15} (integer-product constraint on avg 36/5=72/10) resolved to the SMALLEST
# multiple → 金假锁 5件/36格 vs truth 10件/72格. Downstream chain: total 41 locked → residual 12 items
# all shoved into red → q6 [7,7,7] vs truth 2. The soft total-grid target (engine's own 133 estimate;
# truth 148) penalized the q5=10 composition (~2.0 log) and the multinomial prefers fewer golds — while
# the VALUE evidence sat unused: 5件→110.6k/件 (extreme tail) vs 10件→55.3k/件 (dead center of the
# cpi=7.2 unit-value distribution). This bias prices each candidate count's implied unit value against
# Q5_SIZE_VALUE_POINTS (29,131-settlement calibration, corr≈0.9 — the audit window's 912aa6c table)
# in log space: at σ=0.30 the wrong multiple pays ~3.0, beating the grid-target pull. Fires only in
# the NARROW both-signals regime (q5 avg exact non-soft + q5 value_sum + count unfixed), hero-agnostic.
# Kill: BIDKING_DISABLE_Q5_VALUE_COUNT_BIAS=1.
Q5_AVG_VALUE_COUNT_SIGMA_LOG = 0.30
Q5_VALUE_COUNT_BIAS_NOTE = "q5_value_count_bias_active"
AVG_MULTIPLE_WIDEN_NOTE_PREFIX = "avg_multiple_false_lock_widen:"


def _q5_value_sum_count_multiple_bias_log(
    counts: dict[str, int], evidence: RefEvidence
) -> float:
    if os.environ.get("BIDKING_DISABLE_Q5_VALUE_COUNT_BIAS") == "1":
        return 0.0
    if "q5" in evidence.fixed_counts:
        return 0.0  # count already locked -> nothing to disambiguate
    if "q5" in getattr(evidence, "soft_avg_cell_keys", ()):
        return 0.0  # public soft avg is not the exact tool wire
    avg = evidence.avg_cells.get("q5")
    vsum = evidence.quality_values.get("q5")
    if avg is None or float(avg) <= 0 or not vsum or float(vsum) <= 0:
        return 0.0
    # Only a MULTIPLE ambiguity is this bias's business. An avg with denominator 1 (e.g. 3.0) imposes
    # no integer-product constraint, so the count is not multiple-locked and the value evidence has no
    # multiple to choose between — second-guessing the combo weights there is out of scope and measured
    # harmful (aisha 2401 R5, avg 3.0: the nudge shifted red and pushed an already-over row +39%→+46%).
    if Fraction(float(avg)).limit_denominator(50).denominator < 2:
        return 0.0
    n = int(counts.get("q5", 0) or 0)
    if n <= 0:
        return 0.0
    center = _q5_size_unit_value(float(avg))
    if center <= 0:
        return 0.0
    dev = math.log((float(vsum) / n) / center)
    return -0.5 * (dev / Q5_AVG_VALUE_COUNT_SIGMA_LOG) ** 2


# A revealed GIANT red (one q6 collectible occupying many cells) is the same evidence whether it
# arrives via 公开红 (public max-cell info) or 巨物抽样 (skill) — both land in q6 cell_floor via
# _coarse_quality_reveal_floors. The giant dominates the red value (its footprint is most of the red
# space), so the residual UNREVEALED red is near zero — but the multinomial count prior
# (probs['q6']*total) is blind to the reveal and piles ~p6*total phantom reds on top (4531 R4: q6
# count center ~6 vs truth 2; balanced 1.80M vs truth 854k). Nudge q6 toward the REVEALED count.
GIANT_RED_REVEAL_MIN_CELLS = 8.0          # a single revealed red >= this is "giant"
GIANT_RED_REVEAL_MIN_CELLS_PER_ITEM = 6.0  # avg revealed-red cells; below this it's normal red
AISHA_GIANT_RED_COUNT_PRIOR_SIGMA = 1.0


def _revealed_giant_red_count_bias_log(counts: dict[str, int], evidence: RefEvidence) -> float:
    """Aisha-only soft nudge of the q6 (red) combo count toward the REVEALED count when a GIANT red
    is revealed. A loose Gaussian keeps it a nudge, not a clamp — combos still satisfy the hard cell
    floor and the count can rise back under hard evidence. STRICTLY gated on a giant reveal so normal
    small revealed red (which the engine already UNDER-counts library-wide — Phase A) is never
    touched: the gate is a structural no-op whenever red is invisible (no q6 cell_floor). Rollback
    BIDKING_DISABLE_AISHA_GIANT_RED_COUNT=1."""
    if normalize_hero_key(evidence.hero) != "aisha":
        return 0.0
    if os.environ.get("BIDKING_DISABLE_AISHA_GIANT_RED_COUNT") == "1":
        return 0.0
    if "q6" in evidence.fixed_counts:
        return 0.0  # red count already locked -> nothing to nudge
    revealed = int(evidence.min_counts.get("q6", 0) or 0)
    if revealed <= 0:
        return 0.0  # no revealed red -> invisible/pure-prior, leave the under-count path alone
    cell_floor = _quality_cell_floor("q6", evidence)
    if cell_floor < GIANT_RED_REVEAL_MIN_CELLS:
        return 0.0  # revealed red is not giant
    if cell_floor / max(1, revealed) < GIANT_RED_REVEAL_MIN_CELLS_PER_ITEM:
        return 0.0  # many small revealed reds, not a single giant
    sigma = AISHA_GIANT_RED_COUNT_PRIOR_SIGMA
    try:
        sigma = float(os.environ.get("AISHA_GIANT_RED_COUNT_SIGMA", sigma))
    except (TypeError, ValueError):
        pass
    if sigma <= 0:
        return 0.0
    center = max(1, revealed)
    return -0.5 * ((float(counts.get("q6", 0)) - center) / sigma) ** 2


# Draw-hero (sophie/gabriela) revealed-red count anchor. When a draw hero's skill/tool reveals a red
# (gabriela 技能 gives the 轮廓 -> a known-footprint red lands in min_counts.q6 / q6 cell_floor), the
# multinomial count prior is blind to the reveal and keeps piling ~p6*total phantom reds ON TOP of the
# single revealed red (live gabriela 2401 R4: 1 red revealed @1cell, but q6 count [1,3,5], cells
# [3,10,16], 参考 758k; settled truth 2 reds/3 cells). The giant-red anchor above is aisha-only AND
# giant-gated, so a NORMAL (small) revealed red on a draw hero is anchored by nothing. This is the
# draw-hero analogue: a loose Gaussian nudges q6 toward the revealed count -- NOT a clamp, so the
# prior can still keep weight at revealed+1 (the author accepts conservative low-red but hidden reds
# may exist: 2401 真 2 reds, 1 revealed). Draw-hero ONLY (aisha/ahmed untouched); no-op once red count
# is locked or no red is revealed. Complementary to the no-red damp below (that treats 0-red vaults;
# this treats revealed-red vaults -- mutually exclusive on the q6-reveal gate). Rollback
# DRAW_HERO_DISABLE_REVEALED_RED_COUNT=1; sigma DRAW_HERO_REVEALED_RED_COUNT_SIGMA (default 1.0).
#
# A quality-only RANDOM reveal (宝光四鉴/双鉴 or matching public info) is different: seeing one red in
# a random sample is evidence that the vault contains red, but it is not evidence that the sampled red
# is nearly the whole red population.  The old sigma=1 anchor treated both channels alike and therefore
# collapsed q6 from 2/4/6 to 1/2/3 as soon as 宝光 showed one shapeless red (2546 R1), cutting the quote
# 837k -> 547k.  Keep the original tight anchor for any real q6 footprint, but use a much looser sigma
# for quality-only red.  This preserves a weak pull toward the observed floor without turning a random
# hit into an enumeration.  Rollback only this distinction with
# DRAW_HERO_DISABLE_QUALITY_ONLY_RED_RELAX=1; tune the loose path independently with
# DRAW_HERO_QUALITY_ONLY_RED_COUNT_SIGMA.
DRAW_HERO_REVEALED_RED_COUNT_SIGMA = 1.0
DRAW_HERO_QUALITY_ONLY_RED_COUNT_SIGMA = 4.0
DRAW_HERO_DISABLE_REVEALED_RED_COUNT = "DRAW_HERO_DISABLE_REVEALED_RED_COUNT"
DRAW_HERO_DISABLE_QUALITY_ONLY_RED_RELAX = "DRAW_HERO_DISABLE_QUALITY_ONLY_RED_RELAX"
DRAW_HERO_QUALITY_ONLY_RED_COUNT_SIGMA_ENV = "DRAW_HERO_QUALITY_ONLY_RED_COUNT_SIGMA"
DRAW_HERO_QUALITY_ONLY_RED_RELAX_NOTE = "draw_quality_only_red_count_relax"


def _draw_hero_revealed_red_count_state(
    evidence: RefEvidence,
) -> tuple[float, int, bool, bool]:
    """Return sigma, revealed count, anchor-active and quality-only-relax-active."""
    sigma = DRAW_HERO_REVEALED_RED_COUNT_SIGMA
    try:
        sigma = float(os.environ.get("DRAW_HERO_REVEALED_RED_COUNT_SIGMA", sigma))
    except (TypeError, ValueError):
        pass
    quality_only = (
        normalize_hero_key(evidence.hero) in _draw_hero_count_keys()
        and _quality_cell_floor("q6", evidence) <= 0
    )
    relax_requested = (
        quality_only
        and os.environ.get(DRAW_HERO_DISABLE_QUALITY_ONLY_RED_RELAX) != "1"
    )
    if relax_requested:
        loose_sigma = DRAW_HERO_QUALITY_ONLY_RED_COUNT_SIGMA
        try:
            loose_sigma = float(
                os.environ.get(
                    DRAW_HERO_QUALITY_ONLY_RED_COUNT_SIGMA_ENV,
                    loose_sigma,
                )
            )
        except (TypeError, ValueError):
            pass
        # The existing global sigma remains an escape hatch for an even looser experiment.  A local
        # quality-only override cannot accidentally make this path tighter than the proven footprint
        # path; the rollback switch is required to restore legacy sigma=1 semantics.
        sigma = max(float(sigma), float(loose_sigma))
    revealed = int(evidence.min_counts.get("q6", 0) or 0)
    if revealed <= 0 and _quality_cell_floor("q6", evidence) > 0:
        revealed = 1
    anchor_active = (
        os.environ.get(DRAW_HERO_DISABLE_REVEALED_RED_COUNT) != "1"
        and normalize_hero_key(evidence.hero) in _draw_hero_count_keys()
        and "q6" not in evidence.fixed_counts
        and revealed > 0
        and sigma > 0
    )
    return sigma, revealed, anchor_active, anchor_active and relax_requested


def _draw_hero_revealed_red_count_sigma(evidence: RefEvidence) -> tuple[float, bool]:
    """Return ``(sigma, quality_only_relax_active)`` for the draw-red count anchor."""
    sigma, _revealed, _anchor_active, relax_active = (
        _draw_hero_revealed_red_count_state(evidence)
    )
    return sigma, relax_active


def _draw_hero_quality_only_red_relax_note(evidence: RefEvidence) -> str | None:
    sigma, _revealed, _anchor_active, relax_active = (
        _draw_hero_revealed_red_count_state(evidence)
    )
    if not relax_active:
        return None
    return f"{DRAW_HERO_QUALITY_ONLY_RED_RELAX_NOTE}:{sigma:g}"


def _draw_hero_revealed_red_count_anchor_log(
    counts: dict[str, int], evidence: RefEvidence
) -> float:
    sigma, revealed, anchor_active, _relax_active = (
        _draw_hero_revealed_red_count_state(evidence)
    )
    if not anchor_active:
        return 0.0
    center = max(1, revealed)
    return -0.5 * ((float(counts.get("q6", 0)) - center) / sigma) ** 2


def _draw_hero_revealed_red_cells_options(
    count: int, revealed_count: int, revealed_cells: int
) -> tuple[int, ...]:
    """Red cells for a draw-hero combo when reveals pin a KNOWN red footprint, WITHOUT a count
    hard-lock. The existing red-cells lock (a) only fires when the red count collapses to a unique
    value; a draw hero's red count is a soft prior ([1,2,3]) so it never locks -> the red cells fall
    back to the flat ``count * 3.2`` size prior, which gives a revealed 1-cell red 3 cells (gabriela
    2401: cells [3,10,16] vs truth 3). Here the ``revealed_count`` reds contribute their EXACT
    footprint (``revealed_cells``) and only the phantom reds BEYOND the revealed count get the size
    prior. count < revealed_count -> caller falls back (shouldn't happen: min_counts floors the count
    at the reveal). Rollback at the call site via DRAW_HERO_DISABLE_REVEALED_RED_CELLS=1."""
    phantom = int(count) - int(revealed_count)
    if phantom <= 0:
        return (int(revealed_cells),)
    base = int(revealed_cells)
    default = phantom * DEFAULT_GRID_MEANS["q6"]
    ranked = sorted(
        _composable_grid_options_for_quality("q6", phantom),
        key=lambda option: (abs(option - default), option),
    )
    return tuple(base + option for option in ranked[:DISPLAY_GRID_TOPK])


# Draw heroes (sophie/gabriela/...) reveal items at RANDOM (skill + tools sample the whole vault),
# so accumulating reveals with ZERO revealed red is genuine NEGATIVE evidence: the more of the vault
# seen without a red, the less likely any hidden red remains. The multinomial count prior is blind to
# this and keeps piling ~p6*total phantom reds (live gabriela 2403: q6 center 2, truth 0 -> R5 参考
# 786k vs 真值 398k, +387k phantom-red over-bid on a red=0 villa; settled w/ red=0 known -> 391k≈真值).
# For a combo hypothesizing r reds out of N total with k confirmed non-red reveals, the chance all r
# reds avoided the k ~uniform reveals is ((N-k)/N)^r -> log-weight r*log(1 - k/N). STRENGTH scales it
# (1=pure Bayesian; tuned up because the multinomial prior is strong). Graduated by construction: few
# reveals barely damp, deep rounds (high k/N, still 0 red) drive red->0. Draw-hero ONLY (aisha/ahmed
# red paths untouched); no-op once a red is revealed or red count is locked. Author-confirmed
# (2026-06-23): no red drawn => low-red expectation. Rollback DRAW_HERO_DISABLE_NO_RED_DAMP=1.
# A1 (2026-06-24, faithful-table calibration): base STRENGTH 3.5 -> 2.0 and make it ROUND-AWARE.
# The faithful 97-sample replay (build_monitor_artifact + reference engine, vs settled truth) showed
# the shipped 3.5 OVER-damps: at the decision round the no-red (red0) bucket bias is 3.5=-19% vs
# 2.0=-8% vs off=+50% — 2.0 nails red0 — and 3.5 needlessly over-suppresses the red-present buckets
# (which gate off on reveal, but their un-revealed early-round combos still get damped). The author's
# framing: EARLY rounds should trust the prior (count/grid already accurate) => damp ~0; LATER rounds
# with still-no-red => ramp the damp up. So scale the (now 2.0) base by a linear round ramp:
# R1->0 (pure prior), R2->0.67, R3->1.33, R4+/decision->2.0. Round unknown => full strength (the old
# behaviour; conservative). Rollback to flat 3.5: set DRAW_HERO_NO_RED_DAMP_STRENGTH=3.5 and
# DRAW_HERO_NO_RED_DAMP_DISABLE_ROUND_RAMP=1. The 2403 red=0 justification still holds: its damp fires
# at R4/R5 (ramp full) so red still -> 0 (verified).
DRAW_HERO_NO_RED_DAMP_STRENGTH = 2.0    # was 3.5; faithful table: decision red0 2.0=-8% beats 3.5=-19%
DRAW_HERO_NO_RED_DAMP_RAMP_START_ROUND = 1  # rounds <= this -> ramp factor 0 (pure prior, no damp early)
DRAW_HERO_NO_RED_DAMP_RAMP_FULL_ROUND = 4   # rounds >= this -> ramp factor 1 (full base strength)
DRAW_HERO_NO_RED_DAMP_MIN_REVEALS = 3   # need a few non-red reveals before trusting the negative evidence
DRAW_HERO_NO_RED_DAMP_FRAC_CAP = 0.9    # avoid log(0) when nearly the whole vault is seen
# Aisha shares the SAME no-red negative-evidence count damp (root fix for the pure-prior red +100%
# over-count: the multinomial deposits ~probs.q6*total reds and ignores accumulated non-red reveals;
# §5-confirmed on 16 vaults with k=12-40 non-red seen yet est 4-6 red / true 0-3). Lower strength than
# draw (2.0): aisha's outline/quality coverage is noisier negative evidence than an explicit draw reveal.
# Default ON (author 2026-06-27; AISHA_ENABLE_NO_RED_DAMP=0 to disable); same q6-locked / red-revealed no-op + round-ramp.
AISHA_NO_RED_DAMP_STRENGTH = 0.7
# With LEVER1 (honest red count) + the coupled masking-off, aisha's balanced sits slightly conservative
# (~-8% overall on 68 NEW samples); a small safety lift re-centers it into the blessed -2~-5% band
# (pure-prior -11%->~-5%, revealed -6%->~0). Applied only when AISHA_ENABLE_NO_RED_DAMP=1 + no explicit
# safety_factor. env AISHA_NO_RED_DAMP_SAFETY overrides.
AISHA_NO_RED_DAMP_SAFETY = 0.90
# LEVER1 map-aware ratescale ramp (2026-06-27, DEFAULT OFF — opt-in via AISHA_NO_RED_DAMP_MAP_AWARE=1):
# the no-red count damp strength is scaled by a two-knob ramp on the map's q6 prior rate —
# factor = clamp((rate-LO)/(HI-LO), 0, 1). Measured engine
# q6 priors: 24xx=0.050, 25xx=0.074, 56xx=0.100. Real aisha NEW (settled) shows 56xx needs the FULL
# legacy press (its prior over-deposits red → press lands red median 0) while 25xx must NOT be pressed
# (its prior ≈ truth → OFF gives red median 0, but legacy over-presses to -25%). The families are only
# 1.36x apart in rate so a simple min(1,rate/REF) can't separate them; the steep ramp [LO,HI] does:
# 56xx (0.100≥HI) → factor 1 (full press kept); 25xx (0.074<LO) → factor 0 (no press); 24xx (0.050) →
# 0. Crucially factor=0 zeroes the PRESS but _aisha_no_red_damp_active stays True (it keys off the
# round ramp, not this factor) so the phantom-red value masking stays OFF → 25xx value keeps the good
# masking-off level instead of dropping to the damp-OFF level. env _RATE_LO / _RATE_HI override.
AISHA_NO_RED_DAMP_RATE_LO = 0.078
AISHA_NO_RED_DAMP_RATE_HI = 0.095
# Ethan shares the no-red damp but keyed on CELL evidence, not item-count reveals. Ethan never reveals
# red pre-R5, yet 普品/良品扫描 give EXACT low/mid cells (q1/q3) and quality outlines give q2/q4 cells —
# all CONFIRMED non-red. The multinomial still deposits ~probs.q6*total phantom red regardless, ballooning
# BOTH grid and value (live 2509 沉船: true 0 red, engine reserved 7 red cells / ~520k phantom red value →
# balanced 616k vs truth 113k = 5.4x over). Press red by the fraction of the vault GRID already confirmed
# non-red (ethan is grid-primary, so cell-fraction is the natural negative-evidence signal). The evidence
# self-separates families with NO map flag: low-tier vaults (lots of scanned non-red cells → high frac) get
# the strongest press, high-tier 56xx (less scanned coverage → lower frac) a mild one.
# DEFAULT OFF (pre-release: only validated on 2 live games — 2509 phantom→0, 5610 −5% safe-side — NOT
# full-pool; ethan is deferred to a next-version multi-angle workflow). Opt-in ETHAN_ENABLE_NO_RED_DAMP=1.
# When OFF the ethan path is byte-identical to legacy. Same q6-locked / red-revealed no-op + round-ramp as
# draw/aisha. NOTE: this damps red VALUE (over-bid danger), NOT total grid — damped red count reallocates
# to gold/purple so the grid stays ~same; the residual grid over is gold/purple per-item-cells variance on
# low-tier vaults (irreducible without a total anchor). See HANDOFF_ethan_no_red_damp_value_phantom_2026-06-28.
ETHAN_NO_RED_DAMP_STRENGTH = 2.5  # PRELIM (frac-scaled, 2-game tune): 56xx real red −2~−8% safe-side, 25xx phantom→0
ETHAN_NO_RED_DAMP_MIN_FRAC = 0.35  # require ≥35% of grid confirmed non-red before pressing (thin-evidence guard)


def _draw_hero_no_red_damp_round_ramp(round_no: int | None) -> float:
    """Linear round ramp in [0,1]: 0 at/below RAMP_START_ROUND (early = pure prior), 1 at/above
    RAMP_FULL_ROUND (late = full strength). Unknown round -> 1.0 (conservative, = old flat behaviour)."""
    if round_no is None:
        return 1.0
    if os.environ.get("DRAW_HERO_NO_RED_DAMP_DISABLE_ROUND_RAMP") == "1":
        return 1.0
    lo = DRAW_HERO_NO_RED_DAMP_RAMP_START_ROUND
    hi = DRAW_HERO_NO_RED_DAMP_RAMP_FULL_ROUND
    r = int(round_no)
    if r <= lo:
        return 0.0
    if r >= hi:
        return 1.0
    return (r - lo) / float(hi - lo)


def _draw_hero_no_red_count_damp_log(
    counts: dict[str, int], evidence: RefEvidence, total: int, round_no: int | None = None,
    probs: dict[str, float] | None = None, grids: dict[str, float] | None = None,
) -> float:
    if os.environ.get("DRAW_HERO_DISABLE_NO_RED_DAMP") == "1":
        return 0.0
    hero_key = normalize_hero_key(evidence.hero)
    is_draw = hero_key in _draw_hero_count_keys()
    is_aisha = hero_key == "aisha" and os.environ.get("AISHA_ENABLE_NO_RED_DAMP", "1") != "0"
    is_ethan = hero_key == "ethan" and os.environ.get("ETHAN_ENABLE_NO_RED_DAMP", "0") == "1"
    if not (is_draw or is_aisha or is_ethan):
        return 0.0
    if "q6" in evidence.fixed_counts:
        return 0.0  # red count locked -> nothing to damp
    mc = evidence.min_counts or {}
    # ANY red evidence -> not a no-red vault, leave the count alone. A coarse red reveal lands in
    # min_counts.q6; a SHAPE-revealed red (T2/T3 — 巨物 / gabriela 技能轮廓) lands in the q6 cell floor
    # (NOT the coarse count). Check both so a visibly-revealed red is never wrongly damped.
    if int(mc.get("q6", 0) or 0) > 0 or _quality_cell_floor("q6", evidence) > 0:
        return 0.0
    red = int(counts.get("q6", 0) or 0)
    if red <= 0 or int(total) <= 0:
        return 0.0
    if is_ethan:
        # Cell-evidence variant (ethan is grid-primary; see ETHAN_NO_RED_DAMP_* constants). Negative
        # evidence = the fraction of THIS combo's grid already pinned to a confirmed non-red quality by
        # 扫描/品质轮廓 (quality_cells q1/q2/q3/q4/q5). The more of the vault is confirmed non-red, the
        # less room is left for the multinomial's phantom red, so press it down by that fraction.
        total_cells = float(sum(grids.values())) if grids else 0.0
        if total_cells <= 0:
            return 0.0
        known_non_red = sum(
            float((evidence.quality_cells or {}).get(q, 0) or 0)
            for q in ("q1", "q2", "q3", "q4", "q5")
        )
        if known_non_red <= 0:
            return 0.0
        frac = min(DRAW_HERO_NO_RED_DAMP_FRAC_CAP, known_non_red / total_cells)
        if frac < ETHAN_NO_RED_DAMP_MIN_FRAC:
            return 0.0
        try:
            strength = float(os.environ.get("ETHAN_NO_RED_DAMP_STRENGTH", ETHAN_NO_RED_DAMP_STRENGTH))
        except (TypeError, ValueError):
            strength = ETHAN_NO_RED_DAMP_STRENGTH
        strength *= _draw_hero_no_red_damp_round_ramp(round_no)  # early rounds trust the prior
        if strength <= 0:
            return 0.0
        # Scale by frac itself (not just log(1-frac)) so the press is STEEPLY higher on low-tier vaults
        # (high confirmed-non-red coverage → near-certain there is little/no red) and gentle on high-tier
        # 56xx (lower coverage → real hidden red survives). Sharpens the family self-separation.
        return strength * frac * float(red) * math.log(max(1e-9, 1.0 - frac))
    # k = confirmed NON-red reveals (known quality != red). Unknown-quality reveals are NOT counted
    # (they could be red) -> conservative.
    k = sum(int(mc.get(q, 0) or 0) for q in ("q1", "q2", "q3", "q4", "q5"))
    if k < DRAW_HERO_NO_RED_DAMP_MIN_REVEALS:
        return 0.0
    env_key, default_strength = (
        ("AISHA_NO_RED_DAMP_STRENGTH", AISHA_NO_RED_DAMP_STRENGTH) if is_aisha
        else ("DRAW_HERO_NO_RED_DAMP_STRENGTH", DRAW_HERO_NO_RED_DAMP_STRENGTH)
    )
    try:
        strength = float(os.environ.get(env_key, default_strength))
    except (TypeError, ValueError):
        strength = default_strength
    strength *= _draw_hero_no_red_damp_round_ramp(round_no)  # A1: early rounds trust the prior
    if strength <= 0:
        return 0.0
    frac = min(DRAW_HERO_NO_RED_DAMP_FRAC_CAP, float(k) / float(total))
    # LEVER1 map-aware ratescale ramp — DEFAULT OFF (pre-release compromise, author 2026-06-27).
    # Opt-in: AISHA_NO_RED_DAMP_MAP_AWARE=1 ramp / =excess press-above-mode / =0/unset legacy flat.
    # WHAT IT FIXES: the flat penalty `strength*red*log(1-frac)` is MAP-AGNOSTIC — k non-red reveals
    # drive `frac` regardless of the map's red rate. aisha's tier-SKILL reveals are non-red BY
    # CONSTRUCTION (red is never skill-revealable), so on low-red maps they are NOT random anti-red
    # evidence yet the flat damp treats them as such → over-presses GENUINE red (real aisha NEW: 25xx
    # red median -25% over-pressed; 56xx median 0 legacy-correct). The ramp scales strength by the map
    # q6 rate so 56xx (rate≥HI) keeps full press while 25xx (rate<LO) relaxes — validated to fix red
    # COUNT (25xx -25%→0, 56xx kept) on real+synth NEW.
    # WHY DEFAULT OFF: honest red count UNMASKS a downstream over-estimate — the balanced percentile
    # slide + F1/F2/F3 red masking were CALIBRATED to compensate the OLD red-under-count, so once the
    # count is honest they over-shoot and BALANCED value over-estimates on low-red maps (25xx median
    # -10.5%→+25% = over-bid risk). The red per-ITEM value is NOT the culprit (per-map check: table is
    # accurate, 1.02 on the high-n maps; the family-level +14% was small-n sampling noise). The real
    # root fix = recalibrate that compensation chain for honest red count (deferred aisha-value Phase1,
    # touches balanced → all heroes). Until then legacy flat (slight red under-count, value safe-side)
    # is the shipped default. See docs/HANDOFF_lever1_value_coupling_2026-06-27. Draw heroes always use
    # legacy full-press (design target red→0, e.g. 2403) — unaffected by this flag.
    red_to_press = float(red)
    mode = os.environ.get("AISHA_NO_RED_DAMP_MAP_AWARE", "0")
    if mode not in ("0", "") and is_aisha and probs is not None:
        red_rate = float(probs.get("q6", 0.0) or 0.0)
        if mode == "excess":
            expected_red = red_rate * float(total)  # press only red above the prior mode
            red_to_press = max(0.0, float(red) - expected_red)
        else:  # ratescale (default): two-knob ramp on the map red rate (see constants above)
            try:
                lo = float(os.environ.get("AISHA_NO_RED_DAMP_RATE_LO", AISHA_NO_RED_DAMP_RATE_LO))
                hi = float(os.environ.get("AISHA_NO_RED_DAMP_RATE_HI", AISHA_NO_RED_DAMP_RATE_HI))
            except (TypeError, ValueError):
                lo, hi = AISHA_NO_RED_DAMP_RATE_LO, AISHA_NO_RED_DAMP_RATE_HI
            factor = 1.0 if hi <= lo else min(1.0, max(0.0, (red_rate - lo) / (hi - lo)))
            strength *= factor
            if strength <= 0:
                return 0.0
    if red_to_press <= 0:
        return 0.0
    return strength * red_to_press * math.log(max(1e-9, 1.0 - frac))


def _aisha_no_red_damp_active(evidence: RefEvidence, round_no: int | None) -> bool:
    """True when the aisha no-red COUNT damp (LEVER1) is actively correcting the phantom red on THIS
    vault (enabled, pure-prior, k>=MIN_REVEALS non-red seen, round ramped in). When True, the red count
    is now honest, so the phantom-red-calibrated BALANCE masking (pure-prior percentile clamp + D1 red
    value cap) is double-correcting and must be skipped -> couples the two halves into one switch
    (AISHA_ENABLE_NO_RED_DAMP). When False (early round / low k / red revealed) the masking stays on."""
    if normalize_hero_key(evidence.hero) != "aisha":
        return False
    if os.environ.get("AISHA_ENABLE_NO_RED_DAMP", "1") == "0" or os.environ.get("DRAW_HERO_DISABLE_NO_RED_DAMP") == "1":
        return False
    if "q6" in evidence.fixed_counts:
        return False
    mc = evidence.min_counts or {}
    if int(mc.get("q6", 0) or 0) > 0 or _quality_cell_floor("q6", evidence) > 0:
        return False
    k = sum(int(mc.get(q, 0) or 0) for q in ("q1", "q2", "q3", "q4", "q5"))
    if k < DRAW_HERO_NO_RED_DAMP_MIN_REVEALS:
        return False
    return _draw_hero_no_red_damp_round_ramp(round_no) > 0


def _hidden_gold_count_down_bias_log(
    counts: dict[str, int],
    evidence: RefEvidence,
    probs: dict[str, float],
    total: int,
    round_no: int | None = None,
    grids: dict[str, float] | None = None,
) -> float:
    """Narrow calibration hook (DEFAULT OFF; delta=0 → no-op). Aisha hidden gold (q5) COUNT is
    over-estimated (+1.1 hidden / +1.36 small-mid; gold_calib doc §1) which the 2.8 cells/item center
    turns into small/mid-vault grid OVER-fill (the enemy). Soft-press the q5 count DOWN toward a lower
    center. Gated narrow (gold_calib doc §3 + 2026-06-21 narrow A/B):
      - DECISION-ROUND gate (round_no >= 4, None → skip): the over-fill was measured at R4; don't apply
        early. This is what excludes the 2 regression guards (test_..._good_regression_balanced_bid[2501]
        + 0052_r3_live_bridge) — neither sets a round context, so cdown stays off in them. (124 designed
        cases pass with cdown ON; verified.)
      - precise q5 cells/avg present (极品扫描/均格) → already accurate, skip.
      - prior gold center <= cap: a count-proxy size cap; meant to spare big-gold vaults, but it is
        IMPERFECT — big 展品 (9-18 cells, FEW items → low count center) slip through, so cdown still
        deepens their under-fill. CONSEQUENCE: even narrowed, cdown is COMPENSATORY (hidden MAE
        unchanged 5.7; big MAE 5.9→7.5): it reduces the small/mid over-fill ENEMY and the count-bias
        root (+1.1→+0.4) but relocates error into deeper big under-fill. Per 口径 (over=enemy, hidden
        under=acceptable) that trade is defensible, but it is NOT a clean error reduction → kept DEFAULT
        OFF; enable + A/B live before shipping. The clean fix needs the big-展品 cells/item issue (size
        prior can't reach 9-18-cell 展品), a separate change.
    Env: AISHA_GOLD_COUNT_DOWN (delta, 0=off), _SIGMA, _MAX_CENTER, _MIN_ROUND."""
    if normalize_hero_key(evidence.hero) != "aisha":
        return 0.0
    try:
        delta = float(os.environ.get("AISHA_GOLD_COUNT_DOWN", 0.0) or 0.0)
    except (TypeError, ValueError):
        return 0.0
    if delta <= 0 or "q5" in evidence.fixed_counts:
        return 0.0
    # Decision-round gate: the over-fill was measured at R4 (judge round, most info). Only fire when the
    # round is KNOWN to be R4+ — unknown round → stay off (conservative). Excludes early rounds (less
    # info) and the 0052 R3 live-bridge guard / 2501 regression guard (neither sets a round context).
    try:
        min_round = int(os.environ.get("AISHA_GOLD_COUNT_DOWN_MIN_ROUND", 4))
    except (TypeError, ValueError):
        min_round = 4
    if round_no is None or int(round_no) < min_round:
        return 0.0
    qc = evidence.quality_cells.get("q5")
    if qc is not None and float(qc) > 0:  # 极品扫描给精确格 → 已准, 不压
        return 0.0
    if evidence.avg_cells.get("q5") is not None:  # 极品均格 → 已约束, 不压
        return 0.0
    gold_center = float(probs.get("q5", 0.0)) * float(total)
    try:
        cap = float(os.environ.get("AISHA_GOLD_COUNT_DOWN_MAX_CENTER", 7.0))
    except (TypeError, ValueError):
        cap = 7.0
    if gold_center > cap:  # 尝试不压大仓金(但 big 展品件数少→中心低→挡不住, 见 docstring 补偿性)
        return 0.0
    # Vault-GRID size gate (better signal for big 展品 than count center: 展品 take cells → big total
    # grid even when item count is low). Skip cdown when the vault's total grid exceeds the threshold.
    # Default 0 = off. This is the knob to make the press SIZE-DYNAMIC (spare big vaults). gold_calib WF.
    if grids is not None:
        try:
            max_grid = float(os.environ.get("AISHA_GOLD_COUNT_DOWN_MAX_GRID", 0.0) or 0.0)
        except (TypeError, ValueError):
            max_grid = 0.0
        if max_grid > 0:
            vault_grid = evidence.total_grid_target if evidence.total_grid_target else sum(grids.values())
            if float(vault_grid) > max_grid:
                return 0.0
        # Remaining/hidden-grid gate (user idea): hidden high-tier space = vault grid − KNOWN visible
        # cells. Big gold 展品 are hidden → big remaining; small gold → small. Better discriminator than
        # total grid (which is dominated by known low-tier cells). Skip cdown when remaining > N. 0=off.
        try:
            max_remain = float(os.environ.get("AISHA_GOLD_COUNT_DOWN_MAX_REMAINING", 0.0) or 0.0)
        except (TypeError, ValueError):
            max_remain = 0.0
        if max_remain > 0:
            vg = evidence.total_grid_target if evidence.total_grid_target else sum(grids.values())
            known = sum(float(v) for v in (evidence.quality_cells or {}).values())
            if float(vg) - known > max_remain:
                return 0.0
    try:
        sigma = float(os.environ.get("AISHA_GOLD_COUNT_DOWN_SIGMA", 1.5))
    except (TypeError, ValueError):
        sigma = 1.5
    if sigma <= 0:
        return 0.0
    center = max(0.0, gold_center - delta)
    return -0.5 * ((float(counts.get("q5", 0)) - center) / sigma) ** 2


def _prior_log_weight(
    counts: dict[str, int],
    grids: dict[str, float],
    *,
    total: int,
    total_prior_center: int,
    evidence: RefEvidence,
    probs: dict[str, float],
    item_values: dict[str, float] | None = None,
    round_no: int | None = None,
) -> float:
    logw = _log_fact(total)
    for key in QUALITY_KEYS:
        count = counts[key]
        logw -= _log_fact(count)
        if count:
            logw += count * math.log(max(1e-9, probs[key]))
    calibrated = _SHIPWRECK_CALIBRATED_PRIOR.get()
    count_sigma = float(calibrated['count_sd']) if calibrated is not None else 4.0
    count_center = (float(calibrated['count_mean']) if calibrated is not None
                    and total_prior_center == int(round(calibrated['count_mean'])) else total_prior_center)
    logw -= ((total - count_center) ** 2) / (2 * count_sigma * count_sigma)
    logw += _known_cells_count_bias_log(counts, evidence)
    logw += _q5_value_sum_count_multiple_bias_log(counts, evidence)
    logw += _revealed_giant_red_count_bias_log(counts, evidence)
    logw += _draw_hero_revealed_red_count_anchor_log(counts, evidence)
    logw += _draw_hero_no_red_count_damp_log(counts, evidence, total, round_no, probs, grids)
    logw += _hidden_gold_count_down_bias_log(counts, evidence, probs, total, round_no, grids)
    logw += _random_sample_hypergeom_log(counts, evidence, probs)
    logw += _evidence_grid_avg_cells_log_penalties(counts, grids, evidence)
    avg_value_penalty, _ = _soft_public_avg_value_log_weight(
        counts,
        grids,
        evidence,
        item_values=item_values,
    )
    logw += avg_value_penalty
    return logw


def _soft_public_avg_value_log_weight(
    counts: dict[str, int],
    grids: dict[str, float],
    evidence: RefEvidence,
    *,
    item_values: dict[str, float] | None = None,
) -> tuple[float, bool]:
    item_values = item_values or {}
    penalty = 0.0
    applied = False
    for key in evidence.soft_avg_value_keys:
        if key in (evidence.quality_count_cells_value_options or {}):
            # The strict Float32 equation has already been intersected with canonical exact totals.
            # A second Gaussian likelihood would double-count the same public fact.
            continue
        avg = evidence.avg_values.get(key)
        count = int(counts.get(key, 0))
        if avg is None or not _avg_value_has_positive_signal(avg) or count <= 0:
            continue
        grid = float(grids.get(key, count * DEFAULT_GRID_MEANS[key]))
        tier_total = _quality_value_for_evidence(
            key,
            count=count,
            grid=grid,
            item_values=item_values,
            evidence=evidence,
        )
        combo_avg = tier_total / count
        cv = VALUE_UNCERTAINTY_CV.get(key, 0.20)
        sigma = max(8_000.0, float(avg) * cv / math.sqrt(max(1, count)))
        diff = combo_avg - float(avg)
        penalty -= min(25.0, 0.5 * (diff / sigma) ** 2)
        applied = True
    return penalty, applied


def _count_sum_matches(counts: dict[str, int], evidence: RefEvidence) -> bool:
    q4q5 = evidence.count_sums.get("q4q5")
    if q4q5 is not None and counts.get("q4", 0) + counts.get("q5", 0) != int(q4q5):
        return False
    q5q6_min = evidence.count_sums.get("q5q6_min")
    if (
        q5q6_min is not None
        and counts.get("q5", 0) + counts.get("q6", 0) < int(q5q6_min)
    ):
        return False
    q4q5q6 = evidence.count_sums.get("q4q5q6")
    if (
        q4q5q6 is not None
        and counts.get("q4", 0) + counts.get("q5", 0) + counts.get("q6", 0)
        != int(q4q5q6)
    ):
        return False
    return True


def _random_value_floor(evidence: RefEvidence) -> int | float | None:
    floors: list[int | float] = []
    for sample_count, value_floor in evidence.random_value_floors:
        if type(sample_count) is not int or sample_count not in RANDOM_AVG_SAMPLE_COUNTS:
            continue
        if type(value_floor) not in (int, float):
            continue
        if type(value_floor) is int:
            try:
                finite_floor = math.isfinite(float(value_floor))
            except (OverflowError, TypeError, ValueError):
                continue
            if finite_floor and value_floor > 0:
                floors.append(value_floor)
        elif math.isfinite(value_floor) and value_floor > 0:
            floors.append(value_floor)
    if not floors:
        return None
    return max(floors)


def _random_value_floor_log_weight(value: float, evidence: RefEvidence) -> float:
    floor = _random_value_floor(evidence)
    if floor is None or value >= floor:
        return 0.0
    floor_float = float(floor)
    scale = max(30_000.0, floor_float * 0.25)
    diff = (floor_float - value) / scale
    return -min(25.0, 0.5 * diff * diff)


def _ahmed_q4_exact_value_likelihood_refinement_enabled(
    evidence: RefEvidence,
) -> bool:
    """Whether q4 has the exact private two-signal lane this refinement owns."""
    q4_options = (evidence.quality_count_cells_options or {}).get("q4", ())
    return (
        _run_env_get(Q4_EXACT_VALUE_LIKELIHOOD_REFINEMENT_DISABLE) != "1"
        and normalize_hero_key(evidence.hero) == "ahmed"
        and _quality_exact_value("q4", evidence) is not None
        and (evidence.avg_cells.get("q4") or 0.0) > 0
        and "q4" not in evidence.soft_avg_cell_keys
        and len(q4_options) > 1
        and evidence.fixed_counts.get("q4") is None
    )


def _ahmed_q4_sparse_exact_value_likelihood_guard_enabled(
    evidence: RefEvidence,
) -> bool:
    """Whether the reachable exact q4 support is sparse enough to temper the likelihood."""
    q4_options = (evidence.quality_count_cells_options or {}).get("q4", ())
    enabled = (
        _ahmed_q4_exact_value_likelihood_refinement_enabled(evidence)
        and _run_env_get(Q4_SPARSE_EXACT_VALUE_LIKELIHOOD_GUARD_DISABLE) != "1"
        and len(q4_options) <= Q4_SPARSE_EXACT_VALUE_MAX_STATES
    )
    if not enabled:
        return enabled

    # The catalog options are only a per-quality domain. With exact total + q1/q3 counts, sibling
    # count domains can still make one row unreachable in the warehouse-wide joint posterior.
    # Tempering from that raw domain leaks its tiny q4 tail into correlated q5/q6 marginals (4509
    # R5). Require every q4 row to survive the same residual q5/q6 checks used by enumeration.
    if evidence.total_count is None or not {"q1", "q3"}.issubset(
        evidence.fixed_counts
    ):
        return True
    total = int(evidence.total_count)
    q1 = int(evidence.fixed_counts["q1"])
    q3 = int(evidence.fixed_counts["q3"])
    q6_min = int(evidence.min_counts.get("q6", 0))
    for q4, q4_cells in q4_options:
        residual = total - q1 - q3 - int(q4)
        reachable = False
        for q5 in _count_values(residual, "q5", evidence, q6_min):
            q6 = residual - int(q5)
            counts = {"q1": q1, "q3": q3, "q4": int(q4), "q5": int(q5), "q6": q6}
            if q6 < _effective_min_count("q6", evidence):
                continue
            fixed_q6 = evidence.fixed_counts.get("q6")
            if fixed_q6 is not None and q6 != int(fixed_q6):
                continue
            if not _quality_count_matches_value_evidence("q6", q6, evidence):
                continue
            if not _count_sum_matches(counts, evidence):
                continue
            grids = _grids_for_counts(counts, evidence)
            if grids is None or int(round(grids["q4"])) != int(q4_cells):
                continue
            reachable = True
            break
        if not reachable:
            return False
    return True


def _ahmed_q4_exact_value_likelihood_multiplier(evidence: RefEvidence) -> float:
    if not _ahmed_q4_exact_value_likelihood_refinement_enabled(evidence):
        return 1.0
    if _ahmed_q4_sparse_exact_value_likelihood_guard_enabled(evidence):
        return Q4_SPARSE_EXACT_VALUE_LIKELIHOOD_MULTIPLIER
    return Q4_EXACT_VALUE_LIKELIHOOD_MULTIPLIER


def _quality_exact_value_log_weight(
    counts: dict[str, int],
    grids: dict[str, float],
    item_values: dict[str, float],
    evidence: RefEvidence,
) -> tuple[float, bool]:
    penalty = 0.0
    applied = False
    for key in QUALITY_KEYS:
        if key in evidence.avg_values:
            continue
        exact_value = _quality_exact_value(key, evidence)
        if exact_value is None or exact_value <= 0:
            continue
        count = int(counts.get(key, 0))
        if count <= 0:
            continue
        center = _quality_value_for_grid(
            key,
            count=count,
            grid=grids.get(key, count * DEFAULT_GRID_MEANS[key]),
            item_values=item_values,
        )
        cv = VALUE_UNCERTAINTY_CV.get(key, 0.20)
        scale = max(20_000.0, center * cv / math.sqrt(max(1, count)))
        diff = (float(exact_value) - center) / scale
        contribution = min(25.0, 0.5 * diff * diff)
        if key == "q4":
            contribution *= _ahmed_q4_exact_value_likelihood_multiplier(evidence)
        penalty -= contribution
        applied = True
    return penalty, applied


def _enumerate_prior_count_combos(
    total: int,
    *,
    evidence: RefEvidence,
    probs: dict[str, float],
    total_prior_center: int,
    max_new: int,
    item_values: dict[str, float] | None = None,
    round_no: int | None = None,
    widen_fired: set[str] | None = None,
    tight_high_total: bool | None = None,
    admit_low_q6_gap: bool = False,
    count_value_overrides: Mapping[str, Sequence[int]] | None = None,
) -> list[RefCombo]:
    if max_new <= 0:
        return []
    values = {
        key: _prior_count_values(
            total,
            key,
            evidence,
            probs,
            widen_fired,
            tight_high_total=tight_high_total,
            admit_low_q6_gap=admit_low_q6_gap,
        )
        for key in QUALITY_KEYS
    }
    if count_value_overrides:
        for key, override in count_value_overrides.items():
            if key not in values:
                continue
            values[key] = sorted(
                {
                    int(value)
                    for value in override
                    if 0 <= int(value) <= int(total)
                }
            )
    combos: list[RefCombo] = []
    q1_fixed = evidence.fixed_counts.get("q1")
    victor_high_total = _victor_three_means_high_count_sum(evidence)
    for q3 in values["q3"]:
        for q4 in values["q4"]:
            for q5 in values["q5"]:
                q6_values = values["q6"]
                if victor_high_total is not None:
                    residual_q6 = victor_high_total - q4 - q5
                    q6_values = [residual_q6] if residual_q6 in values["q6"] else []
                for q6 in q6_values:
                    q1 = total - q3 - q4 - q5 - q6
                    if q1_fixed is not None and q1 != int(q1_fixed):
                        continue
                    if q1 not in values["q1"]:
                        continue
                    counts = {"q1": q1, "q3": q3, "q4": q4, "q5": q5, "q6": q6}
                    if not _count_sum_matches(counts, evidence):
                        continue
                    if any(counts[key] < _effective_min_count(key, evidence) for key in QUALITY_KEYS):
                        continue
                    q6_variants = _q6_full_avg_combo_variants(counts, evidence)
                    q6_variant_log_weight = (
                        -math.log(len(q6_variants)) if q6_variants else 0.0
                    )
                    for grids, value_overrides in q6_variants:
                        combos.append(
                            RefCombo(
                                counts=counts,
                                grids=grids,
                                value=0.0,
                                weight=_prior_log_weight(
                                    counts,
                                    grids,
                                    total=total,
                                    total_prior_center=total_prior_center,
                                    evidence=evidence,
                                    probs=probs,
                                    item_values=item_values,
                                    round_no=round_no,
                                )
                                + q6_variant_log_weight,
                                total_grid=sum(grids.values()),
                                quality_value_overrides=value_overrides,
                            )
                        )
                        if len(combos) >= max_new:
                            return combos
    return combos


def _allocate_integer_counts(total: int, weights: dict[str, float]) -> dict[str, int]:
    keys = list(weights)
    weight_total = sum(max(0.0, weights[key]) for key in keys) or 1.0
    raw = {key: total * max(0.0, weights[key]) / weight_total for key in keys}
    out = {key: int(math.floor(value)) for key, value in raw.items()}
    remainder = total - sum(out.values())
    order = sorted(keys, key=lambda key: raw[key] - out[key], reverse=True)
    for key in order[: max(0, remainder)]:
        out[key] += 1
    return out


def _victor_three_means_hard_grid_witnesses(
    combos: Sequence[RefCombo],
    *,
    evidence: RefEvidence,
    probs: dict[str, float],
    total_prior_center: int,
    max_new: int,
    max_probes: int,
    item_values: dict[str, float],
    round_no: int | None,
) -> tuple[list[RefCombo], bool]:
    """Prove missing high-tier arms with bounded low-tier physical witnesses.

    A hard grid can correlate a high-tier arm with a low count outside the
    total/low-tier prior windows.  Preserve the existing weighted body and
    find one legal low-tier body for each missing high-tier arm.  No soft grid
    estimate bounds this proof, and an exhausted probe budget is incomplete.
    """
    high_total = _victor_three_means_high_count_sum(evidence)
    hard_grid = _hard_total_grid_target_int(evidence)
    hard_grid_sources = (
        HARD_TOTAL_GRID_SOURCE_NOTES - {TOTAL_GRID_FROM_HIGH_TIER_CELLS_NOTE}
    ) | {TOTAL_AVG_CELLS_GRID_ARM_NOTE, TOTAL_AVG_CELLS_GRID_COMPOSITION_UNIQUE_NOTE}
    if (
        high_total is None or hard_grid is None or evidence.total_count is not None
        or not any(note in hard_grid_sources for note in evidence.source_notes)
    ):
        return [], True
    minimum_low = {
        key: int(evidence.fixed_counts[key])
        if key in evidence.fixed_counts
        else _effective_min_count(key, evidence)
        for key in ("q1", "q3")
    }
    domain_total = high_total + sum(minimum_low.values())
    domains = {
        key: _prior_count_values(domain_total, key, evidence, probs)
        for key in ("q4", "q5", "q6")
    }
    represented = {
        tuple(int(combo.counts[key]) for key in ("q4", "q5", "q6"))
        for combo in combos
    }

    def ordered_low_counts(key: str, ceiling: int) -> Iterable[int]:
        minimum = minimum_low[key]
        fixed = evidence.fixed_counts.get(key)
        if fixed is not None:
            if minimum <= ceiling:
                yield minimum
            return
        exact_cells = _quality_exact_cells(key, evidence)
        if exact_cells is not None:
            ceiling = min(ceiling, exact_cells)
        if ceiling < minimum:
            return
        center = min(ceiling, max(minimum, int(round(total_prior_center * probs[key]))))
        # Lazy nearest-first iteration avoids materializing an unbounded low
        # count space; the caller's probe budget limits actual candidate work.
        for distance in range(max(center - minimum, ceiling - center) + 1):
            if center - distance >= minimum:
                yield center - distance
            if distance and center + distance <= ceiling:
                yield center + distance

    witnesses: list[RefCombo] = []
    probes = 0
    for q4 in domains["q4"]:
        for q5 in domains["q5"]:
            q6 = high_total - q4 - q5
            arm = (q4, q5, q6)
            if q6 not in domains["q6"] or arm in represented:
                continue
            high_counts = dict(zip(("q4", "q5", "q6"), arm))
            if not _count_sum_matches(high_counts, evidence):
                continue
            minimum_high_cells = 0
            maximum_high_cells = 0
            for key, count in high_counts.items():
                options = _avg_grid_options_for_evidence(
                    count, evidence.avg_cells[key], key, evidence
                )
                exact_cells = _quality_exact_cells(key, evidence)
                joint_cells = _quality_joint_cells_for_count(key, count, evidence)
                options = [
                    cells for cells in options
                    if (exact_cells is None or cells == exact_cells)
                    and (joint_cells is None or cells in joint_cells)
                    and cells >= _quality_cell_floor_for_grid_fit(key, evidence, count)
                ]
                if not options:
                    break
                minimum_high_cells += min(options)
                maximum_high_cells += max(options)
            else:
                exact_low_cells = [_quality_exact_cells(key, evidence) for key in ("q1", "q3")]
                if all(cells is not None for cells in exact_low_cells):
                    required_high_cells = hard_grid - sum(int(cells) for cells in exact_low_cells)
                    if not minimum_high_cells <= required_high_cells <= maximum_high_cells:
                        continue
                if probes >= max_probes:
                    return witnesses, False
                probes += 1
                remaining_cells = hard_grid - minimum_high_cells
                found = False
                for q3 in ordered_low_counts("q3", remaining_cells - minimum_low["q1"]):
                    for q1 in ordered_low_counts("q1", remaining_cells - q3):
                        if probes >= max_probes:
                            return witnesses, False
                        probes += 1
                        counts = {"q1": q1, "q3": q3, **high_counts}
                        if any(
                            not _quality_count_matches_value_evidence(key, counts[key], evidence)
                            for key in ("q1", "q3")
                        ):
                            continue
                        if not _q6_full_avg_combo_variants(counts, evidence):
                            continue
                        rows = _enumerate_prior_count_combos(
                            sum(counts.values()), evidence=evidence, probs=probs,
                            total_prior_center=total_prior_center,
                            max_new=max_new - len(witnesses),
                            item_values=item_values, round_no=round_no,
                            count_value_overrides={key: (count,) for key, count in counts.items()},
                        )
                        witnesses.extend(rows)
                        if len(witnesses) >= max_new:
                            return witnesses, False
                        found = True
                        break
                    if found:
                        break
    return witnesses, True


def _prior_counts_for_total(
    total: int,
    evidence: RefEvidence,
    probs: dict[str, float],
) -> dict[str, int] | None:
    counts = {key: 0 for key in QUALITY_KEYS}
    fixed_keys: set[str] = set()
    for key, value in evidence.min_counts.items():
        counts[key] = max(counts[key], max(0, int(value)))
    for key, value in evidence.fixed_counts.items():
        counts[key] = max(0, int(value))
        fixed_keys.add(key)

    for group_key, group_keys_tuple in (
        ("q4q5", ("q4", "q5")),
        ("q4q5q6", ("q4", "q5", "q6")),
    ):
        group_sum = evidence.count_sums.get(group_key)
        if group_sum is None:
            continue
        group_total = max(0, int(group_sum))
        fixed_group = sum(counts[key] for key in group_keys_tuple)
        if fixed_group > group_total:
            return None
        missing_group = group_total - fixed_group
        group_keys = [key for key in group_keys_tuple if key not in fixed_keys]
        if group_keys and missing_group:
            group_alloc = _allocate_integer_counts(
                missing_group,
                {key: probs[key] for key in group_keys},
            )
            for key, value in group_alloc.items():
                counts[key] += value
                fixed_keys.add(key)
        elif missing_group:
            return None

    used = sum(counts.values())
    if used > total:
        return None
    free_keys = [key for key in QUALITY_KEYS if key not in fixed_keys]
    if free_keys:
        alloc = _allocate_integer_counts(total - used, {key: probs[key] for key in free_keys})
        for key, value in alloc.items():
            counts[key] += value
    elif used != total:
        return None
    if any(counts[key] < _effective_min_count(key, evidence) for key in QUALITY_KEYS):
        return None
    if any(
        not _quality_count_matches_value_evidence(key, counts[key], evidence)
        for key in QUALITY_KEYS
    ):
        return None
    if not _count_sum_matches(counts, evidence):
        return None
    return counts


def _quality_joint_cells_for_count(
    key: str,
    count: int,
    evidence: RefEvidence,
) -> tuple[int, ...] | None:
    """Return the hard cells domain paired with ``count``, or None when unconstrained.

    An empty tuple means a joint constraint exists but this count has no feasible catalog state.
    """
    if key == "q4" and _run_env_get(Q4_EXACT_VALUE_CELLS_DISABLE) == "1":
        return None
    if key == "q5" and _run_env_get(Q5_CATALOG_JOINT_STATE_DISABLE) == "1":
        return None
    options_by_quality = evidence.quality_count_cells_options or {}
    if key not in options_by_quality:
        return None
    return tuple(
        sorted(
            {
                int(cells)
                for candidate_count, cells in options_by_quality[key]
                if int(candidate_count) == int(count)
            }
        )
    )


def _grids_for_counts(
    counts: dict[str, int],
    evidence: RefEvidence,
) -> dict[str, float] | None:
    grids: dict[str, float] = {}
    fixed_grid_keys = set(evidence.quality_cells)
    is_ethan_grid = _is_ethan_grid_mean(evidence.hero)
    for key in QUALITY_KEYS:
        count = counts[key]
        joint_cells = _quality_joint_cells_for_count(key, count, evidence)
        if joint_cells == ():
            return None
        exact_cells = _quality_exact_cells(key, evidence)
        revealed_exact_cells = _draw_hero_revealed_cells_exact_for_count(
            key,
            evidence,
            count,
        )
        if exact_cells is None and revealed_exact_cells is not None:
            exact_cells = revealed_exact_cells
            fixed_grid_keys.add(key)
        cell_floor = _quality_cell_floor_for_grid_fit(key, evidence, count)
        avg = evidence.avg_cells.get(key)
        if exact_cells is not None:
            if exact_cells < cell_floor:
                return None
            if joint_cells is not None and int(exact_cells) not in joint_cells:
                return None
            if not _can_compose_grid_total_with_q6_catalog(key, count, exact_cells):
                return None
            if key == "q6" and not _q6_known_item_exact_cells_compose_matches(
                count,
                exact_cells,
                evidence,
            ):
                return None
            if not _avg_matches_exact_grid(count, avg, exact_cells):
                return None
            if (
                avg is not None
                and key == "q5"
                and not _q5_known_item_cell_compose_matches(count, exact_cells, evidence)
            ):
                return None
            grids[key] = float(exact_cells)
        elif count <= 0:
            if cell_floor > 0:
                return None
            grids[key] = 0.0
        elif avg is not None:
            if key in evidence.soft_avg_cell_keys:
                default = count * float(avg)
                options = [
                    option
                    for option in (
                        joint_cells
                        if joint_cells is not None
                        else _composable_grid_options_with_q6_catalog(key, int(count))
                    )
                    if option >= cell_floor
                    and (
                        key != "q5"
                        or _q5_known_item_cell_compose_matches(count, option, evidence)
                    )
                ]
                if not options:
                    return None
                grids[key] = float(
                    min(options, key=lambda option: (abs(option - default), option))
                )
            else:
                partial_red_floor = _aisha_partial_red_floor_applies_to_count(
                    key,
                    evidence,
                    count,
                )
                partial_red_avg_is_physical = (
                    not partial_red_floor
                    or _aisha_partial_red_floor_avg_can_use_catalog_fallback(
                        key,
                        avg,
                    )
                )
                if not partial_red_avg_is_physical:
                    return None
                options = _avg_grid_options_for_evidence(count, avg, key, evidence)
                if joint_cells is not None:
                    options = [option for option in options if option in joint_cells]
                if cell_floor > 0:
                    options = [option for option in options if option >= cell_floor]
                if (
                    not options
                    and partial_red_floor
                    and partial_red_avg_is_physical
                ):
                    # A displayed average is an approximate clue. If its nominal
                    # product conflicts with a revealed physical footprint, keep the
                    # nearest catalog state at or above that floor instead of either
                    # accepting impossible cells or dropping the whole result.
                    options = [
                        option
                        for option in (
                            joint_cells
                            if joint_cells is not None
                            else _composable_grid_options_with_q6_catalog(key, int(count))
                        )
                        if option >= cell_floor
                    ]
                selected = _choose_avg_grid_option(count, avg, options)
                if selected is None:
                    return None
                grids[key] = selected
        else:
            default = count * _grid_mean(key, is_ethan_grid)
            if joint_cells is not None:
                options = [option for option in joint_cells if option >= cell_floor]
                if not options:
                    return None
                grids[key] = float(min(options, key=lambda option: (abs(option - default), option)))
            elif cell_floor > 0:
                if (
                    _should_use_exact_total_avg_cells_fast_path(evidence)
                    and evidence.total_grid_target is None
                ):
                    fast_grid = _nearest_composable_default_grid(
                        int(count),
                        default,
                        cell_floor=cell_floor,
                        quality_key=key,
                    )
                    if fast_grid is not None:
                        grids[key] = fast_grid
                    else:
                        options = [
                            option
                            for option in _composable_grid_options_with_q6_catalog(key, int(count))
                            if option >= cell_floor
                        ]
                        if not options:
                            return None
                        grids[key] = float(
                            min(options, key=lambda option: (abs(option - default), option))
                        )
                else:
                    options = [
                        option
                        for option in _composable_grid_options_with_q6_catalog(key, int(count))
                        if option >= cell_floor
                    ]
                    if not options:
                        return None
                    grids[key] = float(min(options, key=lambda option: (abs(option - default), option)))
            else:
                grids[key] = default
    fit_option_overrides: dict[str, tuple[int, ...]] = {}
    for key in QUALITY_KEYS:
        joint_options = _quality_joint_cells_for_count(key, counts[key], evidence)
        options = tuple(joint_options) if joint_options is not None else None
        if _aisha_public_avg_direct_grid_domain_enabled(key, evidence):
            avg_options = tuple(
                _avg_grid_options_for_evidence(
                    int(counts[key]),
                    evidence.avg_cells.get(key),
                    key,
                    evidence,
                )
            )
            options = (
                avg_options
                if options is None
                else tuple(option for option in options if option in avg_options)
            )
        if options is not None:
            fit_option_overrides[key] = options
    fitted = _fit_grids_to_total_target(
        grids,
        counts,
        evidence.avg_cells,
        evidence.total_grid_target,
        fixed_grid_keys=fixed_grid_keys,
        soft_avg_cell_keys=evidence.soft_avg_cell_keys,
        cell_floors={
            key: _quality_cell_floor_for_grid_fit(key, evidence, counts[key])
            for key in QUALITY_KEYS
        },
        exact_dp=not _is_grid_identity_pass(evidence),
        option_overrides=fit_option_overrides,
        prefer_contiguous_slack_exact=(
            TOTAL_AVG_CELLS_GRID_ARM_NOTE in evidence.source_notes
        ),
    )
    hard_total = _hard_total_grid_target_int(evidence)
    if hard_total is not None and abs(sum(fitted.values()) - hard_total) > 0.0001:
        return None
    if hard_total is not None:
        # If every tier except one is hard-pinned, the last tier is the exact arithmetic
        # residual.  The proportional fallback in _fit_grids_to_total_target is useful for
        # wide multi-tier targets, but for this one-free-tier case it can manufacture an
        # impossible footprint (4550 R5: one red item stretched from 3 to 27 cells).  Reject
        # that count candidate instead of letting display code revive its old size prior.
        scalable_keys = [
            key
            for key in QUALITY_KEYS
            if not _grid_fixed_for_total_target(
                key,
                counts=counts,
                avg_cells=evidence.avg_cells,
                fixed_grid_keys=fixed_grid_keys,
                soft_avg_cell_keys=evidence.soft_avg_cell_keys,
            )
        ]
        if len(scalable_keys) == 1:
            residual_key = scalable_keys[0]
            residual_cells = float(fitted.get(residual_key, 0.0))
            residual_int = int(round(residual_cells))
            if (
                abs(residual_cells - residual_int) > 0.0001
                or not _can_compose_grid_total_with_q6_catalog(
                    residual_key, int(counts[residual_key]), residual_int
                )
            ):
                return None
    soft_floor = _soft_total_grid_floor_int(evidence)
    if soft_floor is not None and sum(fitted.values()) + 1e-6 < soft_floor:
        return None
    for key in QUALITY_KEYS:
        fitted_floor = _quality_cell_floor_for_grid_fit(key, evidence, counts[key])
        if fitted.get(key, 0.0) + 1e-6 < fitted_floor:
            return None
        joint_cells = _quality_joint_cells_for_count(key, counts[key], evidence)
        if joint_cells is not None:
            fitted_cells = float(fitted.get(key, 0.0))
            fitted_int = int(round(fitted_cells))
            if abs(fitted_cells - fitted_int) > 0.0001 or fitted_int not in joint_cells:
                return None
        if _aisha_public_avg_direct_grid_domain_enabled(key, evidence):
            fitted_cells = float(fitted.get(key, 0.0))
            fitted_int = int(round(fitted_cells))
            if (
                abs(fitted_cells - fitted_int) > 0.0001
                or fitted_int
                not in _avg_grid_options_for_evidence(
                    int(counts[key]),
                    evidence.avg_cells.get(key),
                    key,
                    evidence,
                )
            ):
                return None
    if not _split_low_quality_q1_grid_matches(counts.get("q1", 0), fitted.get("q1", 0.0), evidence):
        return None
    return fitted


def _grid_states_for_counts(
    counts: dict[str, int],
    evidence: RefEvidence,
) -> tuple[dict[str, float], ...]:
    """Materialize every authoritative all-items-average grid arm.

    Each arm is fitted as a hard equality and then revalidated as an integer,
    per-quality catalog-composable state.  This prevents the proportional grid
    fallback or a count prior from manufacturing one exact-looking residual.
    """
    options = tuple(sorted(set(int(value) for value in evidence.total_grid_options)))
    if len(options) <= 1:
        grids = _grids_for_counts(counts, evidence)
        return () if grids is None else (grids,)

    states: list[dict[str, float]] = []
    seen: set[tuple[int, ...]] = set()
    for target in options:
        arm_evidence = replace(
            evidence,
            total_grid_target=float(target),
            total_grid_options=(),
            source_notes=tuple(
                dict.fromkeys(
                    (*evidence.source_notes, TOTAL_AVG_CELLS_GRID_ARM_NOTE)
                )
            ),
        )
        grids = _grids_for_counts(counts, arm_evidence)
        if grids is None or abs(sum(grids.values()) - int(target)) > 0.0001:
            continue
        integer_cells: list[int] = []
        valid = True
        for key in QUALITY_KEYS:
            cells = float(grids.get(key, 0.0))
            rounded = int(round(cells))
            if (
                abs(cells - rounded) > 0.0001
                or not _can_compose_grid_total_with_q6_catalog(
                    key,
                    int(counts.get(key, 0)),
                    rounded,
                )
            ):
                valid = False
                break
            integer_cells.append(rounded)
        signature = tuple(integer_cells)
        if not valid or signature in seen:
            continue
        seen.add(signature)
        states.append(
            {
                key: float(integer_cells[index])
                for index, key in enumerate(QUALITY_KEYS)
            }
        )
    return tuple(states)


def _resolve_total_avg_cells_options_for_exact_counts(
    evidence: RefEvidence,
) -> RefEvidence:
    """Narrow the whole-warehouse support only from an exact count composition.

    A sparse prior is never authority to select one total-grid arm.  When fixed
    quality counts already exhaust the hard total, however, per-tier catalog and
    cell constraints are authoritative and may prove some arms unreachable.
    """
    options = tuple(sorted(set(int(value) for value in evidence.total_grid_options)))
    if evidence.total_count is None or len(options) <= 1:
        return evidence
    counts = {
        key: max(0, int(evidence.fixed_counts.get(key, 0)))
        for key in QUALITY_KEYS
    }
    if sum(counts.values()) != int(evidence.total_count):
        return evidence
    states = _grid_states_for_counts(counts, evidence)
    surviving = tuple(
        sorted(
            {
                int(round(sum(float(value) for value in grids.values())))
                for grids in states
            }
        )
    )
    if not surviving or surviving == options:
        return evidence
    notes = tuple(evidence.source_notes) + (
        (
            f"{TOTAL_AVG_CELLS_GRID_OPTIONS_NOTE}:composition_filter:"
            + ",".join(str(option) for option in options)
            + "->"
            + ",".join(str(option) for option in surviving)
        ),
    )
    if len(surviving) == 1:
        return replace(
            evidence,
            total_grid_target=float(surviving[0]),
            total_grid_options=surviving,
            source_notes=notes + (TOTAL_AVG_CELLS_GRID_COMPOSITION_UNIQUE_NOTE,),
        )
    return replace(
        evidence,
        total_grid_options=surviving,
        source_notes=notes,
    )


def _aisha_exact_total_layout_grid_support(
    combos: list[RefCombo],
    *,
    evidence: RefEvidence,
    minimap_items: list[dict[str, Any]],
    raw_deepest: int,
    max_combos: int,
    notes: list[str],
) -> list[RefCombo]:
    """Retain soft physical grid arms after an exact item-count update.

    Sparse exact-total enumeration chooses one representative grid for each
    count row as a latency optimization. That point is not a measured total-cell
    equality. When independent minimap geometry is materially larger, preserve
    composable center/high grid arms for the same count row so value and grid
    consumers share the same physical support. An authoritative issue26 total-
    grid disjunction always wins; this soft expansion is admitted only when no
    hard total-grid arm exists.
    """
    if (
        _run_env_get(AISHA_EXACT_TOTAL_GRID_SUPPORT_DISABLE) == "1"
        or normalize_hero_key(evidence.hero) != "aisha"
        or evidence.phase != "bidding"
        or evidence.total_count is None
        or evidence.total_grid_target is not None
        or bool(evidence.total_grid_options)
        or not _has_explicit_total_count_source(evidence.source_notes)
        or not _should_use_exact_total_avg_cells_fast_path(evidence)
        or AISHA_PARTIAL_RED_FLOOR_INFERRED_TOTAL_SOFT_NOTE in notes
        or not combos
        or not minimap_items
        or int(raw_deepest or 0) <= 0
        or all(
            _quality_exact_cells(key, evidence) is not None
            for key in QUALITY_KEYS
        )
    ):
        return combos

    max_log_weight = max(combo.weight for combo in combos)
    prior_mid = _weighted_quantile(
        [
            (
                float(combo.total_grid),
                math.exp(max(-745.0, combo.weight - max_log_weight)),
            )
            for combo in combos
        ],
        0.50,
    )
    if prior_mid is None:
        return combos
    prior_anchor = max(
        float(prior_mid),
        float(count_implied_grid_floor(notes) or 0),
    )
    layout_mid = max(
        int(_known_minimap_cells(minimap_items) or 0),
        int(_occupancy_adjusted_depth_grid(minimap_items, int(raw_deepest))),
    )
    if layout_mid <= prior_anchor + 1.0:
        return combos
    layout_high = min(
        int(raw_deepest) * AISHA_GRID_COLUMNS,
        int(round(layout_mid + (layout_mid - prior_anchor))),
    )
    targets = tuple(sorted({int(layout_mid), int(layout_high)}))

    expanded: list[RefCombo] = []
    for combo in combos:
        fixed_grid_keys = set(evidence.quality_cells)
        for key in QUALITY_KEYS:
            if (
                _quality_exact_cells(key, evidence) is not None
                or _draw_hero_revealed_cells_exact_for_count(
                    key,
                    evidence,
                    int(combo.counts[key]),
                )
                is not None
            ):
                fixed_grid_keys.add(key)
        rows: list[dict[str, float]] = [dict(combo.grids)]
        seen = {
            tuple(
                round(float(combo.grids.get(key, 0.0)), 6)
                for key in QUALITY_KEYS
            )
        }
        per_count_floors = {
            key: _quality_cell_floor_for_grid_fit(
                key,
                evidence,
                int(combo.counts[key]),
            )
            for key in QUALITY_KEYS
        }
        fit_option_overrides: dict[str, tuple[int, ...]] = {}
        for key in QUALITY_KEYS:
            joint_options = _quality_joint_cells_for_count(
                key,
                int(combo.counts[key]),
                evidence,
            )
            options = tuple(joint_options) if joint_options is not None else None
            if _aisha_public_avg_direct_grid_domain_enabled(key, evidence):
                avg_options = tuple(
                    _avg_grid_options_for_evidence(
                        int(combo.counts[key]),
                        evidence.avg_cells.get(key),
                        key,
                        evidence,
                    )
                )
                options = (
                    avg_options
                    if options is None
                    else tuple(option for option in options if option in avg_options)
                )
            if options is not None:
                fit_option_overrides[key] = options
        for target in targets:
            if float(target) <= float(combo.total_grid) + 0.5:
                continue
            fitted = _fit_grids_to_total_target(
                dict(combo.grids),
                combo.counts,
                evidence.avg_cells,
                float(target),
                fixed_grid_keys=fixed_grid_keys,
                soft_avg_cell_keys=evidence.soft_avg_cell_keys,
                cell_floors=per_count_floors,
                exact_dp=True,
                option_overrides=fit_option_overrides,
            )
            if abs(sum(fitted.values()) - float(target)) > 0.0001:
                continue
            fitted_ints: dict[str, int] = {}
            malformed = False
            for key in QUALITY_KEYS:
                fitted_cells = float(fitted.get(key, 0.0))
                fitted_int = int(round(fitted_cells))
                if (
                    not math.isfinite(fitted_cells)
                    or abs(fitted_cells - fitted_int) > 0.0001
                    or fitted_cells + 1e-6 < per_count_floors[key]
                    or not _can_compose_grid_total_with_q6_catalog(
                        key,
                        int(combo.counts[key]),
                        fitted_int,
                    )
                ):
                    malformed = True
                    break
                joint_cells = _quality_joint_cells_for_count(
                    key,
                    int(combo.counts[key]),
                    evidence,
                )
                if joint_cells is not None and fitted_int not in joint_cells:
                    malformed = True
                    break
                if (
                    _aisha_public_avg_direct_grid_domain_enabled(key, evidence)
                    and fitted_int
                    not in _avg_grid_options_for_evidence(
                        int(combo.counts[key]),
                        evidence.avg_cells.get(key),
                        key,
                        evidence,
                    )
                ):
                    malformed = True
                    break
                if key == "q5" and not _q5_known_item_cell_compose_matches(
                    int(combo.counts[key]),
                    fitted_int,
                    evidence,
                ):
                    malformed = True
                    break
                if key == "q6" and not _q6_known_item_exact_cells_compose_matches(
                    int(combo.counts[key]),
                    fitted_int,
                    evidence,
                ):
                    malformed = True
                    break
                fitted_ints[key] = fitted_int
            if malformed:
                continue
            if not _split_low_quality_q1_grid_matches(
                int(combo.counts.get("q1", 0)),
                float(fitted_ints["q1"]),
                evidence,
            ):
                continue
            signature = tuple(
                round(float(fitted.get(key, 0.0)), 6)
                for key in QUALITY_KEYS
            )
            if signature in seen:
                continue
            seen.add(signature)
            rows.append(fitted)
        row_weight = combo.weight - math.log(len(rows))
        expanded.extend(
            RefCombo(
                counts=combo.counts,
                grids=grids,
                value=combo.value,
                weight=row_weight,
                total_grid=sum(grids.values()),
            )
            for grids in rows
        )
    if len(expanded) <= len(combos) or len(expanded) > int(max_combos):
        return combos
    _append_source_note_once(
        notes,
        f"{AISHA_EXACT_TOTAL_GRID_SUPPORT_NOTE}:"
        f"prior{int(round(prior_anchor))}:"
        f"layout{layout_mid}:hi{layout_high}",
    )
    return expanded


def _q6_full_avg_combo_variants(
    counts: dict[str, int],
    evidence: RefEvidence,
) -> tuple[tuple[dict[str, float], dict[str, float] | None], ...]:
    states = tuple(
        (int(count), int(cells), int(value))
        for count, cells, value in (
            evidence.quality_count_cells_value_options or {}
        ).get("q6", ())
        if int(count) == int(counts.get("q6", 0))
    )
    if not states:
        if "q6" in (evidence.quality_count_cells_value_options or {}):
            return ()
        return tuple(
            (grids, None)
            for grids in _grid_states_for_counts(counts, evidence)
        )

    variants: list[tuple[dict[str, float], dict[str, float] | None]] = []
    for _count, cells, total_value in states:
        forced_cells = dict(evidence.quality_cells)
        forced_cells["q6"] = float(cells)
        for grids in _grid_states_for_counts(
            counts,
            replace(evidence, quality_cells=forced_cells),
        ):
            if abs(float(grids.get("q6", 0.0)) - cells) > 0.0001:
                continue
            variants.append((grids, {"q6": float(total_value)}))
    unique: dict[
        tuple[tuple[tuple[str, float], ...], tuple[tuple[str, float], ...]],
        tuple[dict[str, float], dict[str, float] | None],
    ] = {}
    for grids, overrides in variants:
        key = (
            tuple(sorted((name, float(value)) for name, value in grids.items())),
            tuple(sorted((name, float(value)) for name, value in (overrides or {}).items())),
        )
        unique[key] = (grids, overrides)
    return tuple(unique.values())


def _quality_value_for_grid(
    key: str,
    *,
    count: int,
    grid: float,
    item_values: dict[str, float],
) -> float:
    if count <= 0:
        return 0.0
    base_total = count * item_values[key]
    # The zero point of the size premium is the TRUE mean cells/item, not the cells prior — see
    # VALUE_SIZE_PREMIUM_REF_CELLS for why those are different numbers with different jobs.
    mean = max(1.0, _value_size_premium_ref(key))
    avg = max(1.0, grid / count)
    impact_ratio = _value_size_premium_ratio(key)
    adjustment = (avg - mean) * item_values[key] * impact_ratio * count
    cap = base_total * (0.20 if key == "q1" else 0.35)
    adjustment = max(-cap, min(cap, adjustment))
    return max(float(count), base_total + adjustment)


def _quality_value_for_evidence(
    key: str,
    *,
    count: int,
    grid: float,
    item_values: dict[str, float],
    evidence: RefEvidence,
) -> float:
    exact_value = _quality_exact_value(key, evidence)
    if exact_value is not None:
        return float(exact_value)
    exact_red_cells_target = (
        _aisha_exact_red_cells_value_target(evidence) if key == "q6" else None
    )
    partial = _partial_known_quality_value_state(
        key,
        count=count,
        grid=grid,
        item_values=item_values,
        evidence=evidence,
    )
    if partial is not None:
        known_sum, _remaining_count, unknown_default, unknown_grid_value = partial
        grid_center = known_sum + unknown_grid_value
        default_floor = known_sum + unknown_default
        catalog_floor = known_sum + _quality_catalog_min_value_floor(key, evidence)
        known_q6_residual_catalog_floor = (
            _q6_known_item_exact_cells_catalog_value_floor(
                key,
                count=count,
                grid=grid,
                evidence=evidence,
            )
        )
        avg_value = evidence.avg_values.get(key)
        if avg_value is not None:
            total = _avg_value_total_from_count(float(avg_value), int(count))
            if total is not None:
                return max(
                    default_floor,
                    grid_center,
                    catalog_floor,
                    known_q6_residual_catalog_floor,
                    total,
                    exact_red_cells_target or 0.0,
                )
        return max(
            default_floor,
            grid_center,
            catalog_floor,
            known_q6_residual_catalog_floor,
            exact_red_cells_target or 0.0,
        )
    value_floor = _quality_value_floor_for_count(
        key,
        count=count,
        grid=grid,
        item_values=item_values,
        evidence=evidence,
    )
    avg_value = evidence.avg_values.get(key)
    if avg_value is not None:
        total = _avg_value_total_from_count(float(avg_value), int(count))
        if total is not None:
            return max(value_floor, total)
    if exact_red_cells_target is not None:
        return max(value_floor, exact_red_cells_target)
    return max(
        value_floor,
        _quality_value_for_grid(
            key,
            count=count,
            grid=grid,
            item_values=item_values,
        ),
    )


def _value_distribution_points_with_floor(
    center: float,
    spread: float,
    floor: float,
) -> tuple[tuple[float, float], ...]:
    return tuple(
        (max(float(floor), value), weight)
        for value, weight in _value_distribution_points(center, spread)
    )


def _quality_value_distribution_points(
    key: str,
    *,
    center: float,
    spread: float,
    count: int,
    grid: float,
    item_values: dict[str, float],
    evidence: RefEvidence,
) -> tuple[tuple[float, float], ...]:
    return _value_distribution_points_with_floor(
        center,
        spread,
        _quality_value_floor_for_count(
            key,
            count=count,
            grid=grid,
            item_values=item_values,
            evidence=evidence,
        ),
    )


def _total_value_floor(
    evidence: RefEvidence,
    *,
    counts: dict[str, int] | None = None,
    grids: dict[str, float] | None = None,
    item_values: dict[str, float] | None = None,
) -> float:
    # 200044 is a category/tag-set subtotal.  It constrains the final whole-vault
    # quote but, without category identity or membership, cannot be assigned to
    # individual posterior states.  Injecting it here winsorizes every modeled
    # point to K when K is large and fabricates an exact posterior.  The terminal
    # quote boundary below remains responsible for enforcing the hard lower bound.
    if counts is None or grids is None or item_values is None:
        return sum(
            _known_item_value_floor(key, evidence) for key in QUALITY_KEYS
        )
    return sum(
        _quality_value_floor_for_count(
            key,
            count=counts[key],
            grid=grids.get(key, counts[key] * DEFAULT_GRID_MEANS[key]),
            item_values=item_values,
            evidence=evidence,
        )
        for key in QUALITY_KEYS
    )


def _combo_value_distribution_points(
    center: float,
    spread: float,
    evidence: RefEvidence,
    *,
    counts: dict[str, int],
    grids: dict[str, float],
    item_values: dict[str, float],
) -> tuple[tuple[float, float], ...]:
    return _value_distribution_points_with_floor(
        center,
        spread,
        _total_value_floor(
            evidence,
            counts=counts,
            grids=grids,
            item_values=item_values,
        ),
    )


def _combo_value_distribution_points_with_quality_scales(
    counts: dict[str, int],
    grids: dict[str, float],
    item_values: dict[str, float],
    evidence: RefEvidence,
    quality_scales: dict[str, float],
    quality_value_overrides: Mapping[str, float] | None = None,
) -> tuple[tuple[float, float], ...]:
    """Build one internally correlated value distribution with selected tiers scaled."""
    center = 0.0
    variance = 0.0
    floor = 0.0
    for key in QUALITY_KEYS:
        count = counts[key]
        grid = grids.get(key, count * DEFAULT_GRID_MEANS[key])
        scale = max(0.0, float(quality_scales.get(key, 1.0)))
        override = (quality_value_overrides or {}).get(key)
        center += scale * (
            float(override)
            if override is not None
            else _quality_value_for_evidence(
                key,
                count=count,
                grid=grid,
                item_values=item_values,
                evidence=evidence,
            )
        )
        spread = (
            0.0
            if override is not None
            else _quality_value_uncertainty(
                key,
                count=count,
                grid=grid,
                item_values=item_values,
                evidence=evidence,
            )
        )
        variance += (scale * spread) ** 2
        floor += scale * _quality_value_floor_for_count(
            key,
            count=count,
            grid=grid,
            item_values=item_values,
            evidence=evidence,
        )
    return _value_distribution_points_with_floor(center, math.sqrt(variance), floor)


def _combo_value(
    counts: dict[str, int],
    grids: dict[str, float],
    item_values: dict[str, float],
    evidence: RefEvidence,
    quality_value_overrides: Mapping[str, float] | None = None,
) -> float:
    return sum(
        (
            float((quality_value_overrides or {})[key])
            if key in (quality_value_overrides or {})
            else _quality_value_for_evidence(
                key,
                count=counts[key],
                grid=grids.get(key, counts[key] * DEFAULT_GRID_MEANS[key]),
                item_values=item_values,
                evidence=evidence,
            )
        )
        for key in QUALITY_KEYS
    )


def _quality_value_uncertainty(
    key: str,
    *,
    count: int,
    grid: float,
    item_values: dict[str, float],
    evidence: RefEvidence,
) -> float:
    if count <= 0:
        return 0.0
    if _quality_exact_value(key, evidence) is not None:
        return 0.0
    avg_value = evidence.avg_values.get(key)
    if (
        avg_value is not None
        and _avg_value_total_from_count(float(avg_value), int(count)) is not None
    ):
        return 0.0
    exact_red_cells_target = (
        _aisha_exact_red_cells_value_target(evidence) if key == "q6" else None
    )
    if exact_red_cells_target is not None:
        cv = VALUE_UNCERTAINTY_CV.get(key, 0.20)
        return max(0.0, exact_red_cells_target * cv / math.sqrt(max(1, int(count))))
    known_count = evidence.quality_value_floor_item_counts.get(key, 0)
    known_sum = _quality_value_floor(key, evidence)
    if known_count > 0 and known_sum > 0 and count > known_count:
        known_cells = float(evidence.quality_cell_floors.get(key, 0.0))
        remaining_count = count - known_count
        remaining_grid = max(float(remaining_count), grid - known_cells)
        center = _quality_value_for_grid(
            key,
            count=remaining_count,
            grid=remaining_grid,
            item_values=item_values,
        )
        cv = VALUE_UNCERTAINTY_CV.get(key, 0.20)
        return max(0.0, center * cv / math.sqrt(max(1, remaining_count)))
    center = _quality_value_for_grid(
        key,
        count=count,
        grid=grid,
        item_values=item_values,
    )
    cv = VALUE_UNCERTAINTY_CV.get(key, 0.20)
    return max(0.0, center * cv / math.sqrt(max(1, int(count))))


def _combo_value_uncertainty(
    counts: dict[str, int],
    grids: dict[str, float],
    item_values: dict[str, float],
    evidence: RefEvidence,
    quality_value_overrides: Mapping[str, float] | None = None,
) -> float:
    variance = 0.0
    for key in QUALITY_KEYS:
        if key in (quality_value_overrides or {}):
            continue
        spread = _quality_value_uncertainty(
            key,
            count=counts[key],
            grid=grids.get(key, counts[key] * DEFAULT_GRID_MEANS[key]),
            item_values=item_values,
            evidence=evidence,
        )
        variance += spread * spread
    return math.sqrt(variance)


def _value_distribution_points(
    center: float,
    spread: float,
) -> tuple[tuple[float, float], ...]:
    if spread < 1.0:
        return ((center, 1.0),)
    return tuple(
        (max(0.0, center + offset * spread), weight)
        for offset, weight in VALUE_DISTRIBUTION_POINTS
    )


def _grid_display_signature(
    evidence: RefEvidence,
) -> tuple[tuple[int | None, ...], tuple[float | None, ...], int | None]:
    run_cache = _RUN_CACHE.get()
    memo_key = ("grid_display_signature", id(evidence))
    if run_cache is not None:
        cached = run_cache["memo"].get(memo_key)
        if cached is not None and cached[0] is evidence:
            return cached[1]
    exact = tuple(_quality_exact_cells(key, evidence) for key in QUALITY_KEYS)
    avg = tuple(
        round(float(evidence.avg_cells[key]), 6)
        if key in evidence.avg_cells
        else None
        for key in QUALITY_KEYS
    )
    target_int = None
    if evidence.total_grid_target is not None:
        rounded = int(round(float(evidence.total_grid_target)))
        if abs(float(evidence.total_grid_target) - rounded) <= 0.25:
            target_int = rounded
    result = (exact, avg, target_int)
    if run_cache is not None:
        # Retain the evidence object with the value so Python id reuse cannot alias another retry pass.
        run_cache["memo"][memo_key] = (evidence, result)
    return result


def _cached_grid_constraint_options(
    key: str,
    count: int,
    exact_cells: int | None,
    avg: float | None,
) -> tuple[int, ...] | None:
    if exact_cells is not None:
        if not _can_compose_grid_total_with_q6_catalog(key, count, exact_cells):
            return ()
        if not _avg_matches_exact_grid(count, avg, exact_cells):
            return ()
        return (exact_cells,)
    if count <= 0:
        return (0,)
    if avg is not None:
        return tuple(_avg_grid_options(count, avg, key))
    return None


@lru_cache(maxsize=20000)
def _display_grid_options_no_residual(
    key: str,
    count: int,
    exact_cells: int | None,
    avg: float | None,
    is_ethan: bool = False,
    center_int: int | None = None,
    q5_catalog_disabled: bool = False,
    q6_catalog_disabled: bool = False,
    calibration_key: str = '',
) -> tuple[int, ...]:
    """The (key,count)-only branch of `_display_grid_options_cached`: the result when the
    cross-quality residual lock cannot fire (i.e. not every *other* quality is exact-pinned).
    Keyed only on this quality's own (key,count,exact,avg) — independent of the other
    qualities' counts — so it stays hot across the combo enumeration (the full-counts_tuple
    key in the wrapper otherwise misses ~83%: 40k distinct of 48k calls, while the real
    distinct (key,count) space is only ~50). Byte-identical: when the wrapper detects
    all_other_exact is False it produces exactly these candidates; the residual branch
    (all_other_exact True) is handled in the wrapper and never reaches here.

    `center_int` (族D) is the combo's OWN reconciled grid for this tier, rounded to an int so the
    cache stays hot (the raw float would key every combo separately). It replaces the count×prior
    default as the ranking center, which is what keeps Σ(displayed cells) == the total grid.
    The catalog-disable booleans are cache-key inputs; nested helpers read the matching run env."""
    constrained = _cached_grid_constraint_options(key, count, exact_cells, avg)
    if constrained is not None:
        return constrained
    candidates = _composable_grid_options_with_q6_catalog(key, count)
    default = (
        float(center_int)
        if center_int is not None and center_int > 0
        else count * _grid_mean(key, is_ethan)
    )
    ranked = sorted(candidates, key=lambda option: (abs(option - default), option))
    return tuple(ranked[:DISPLAY_GRID_TOPK])


@lru_cache(maxsize=20000)
def _display_grid_options_cached(
    counts_tuple: tuple[int, ...],
    key: str,
    exact_tuple: tuple[int | None, ...],
    avg_tuple: tuple[float | None, ...],
    target_int: int | None,
    is_ethan: bool = False,
    center_int: int | None = None,
    q5_catalog_disabled: bool = False,
    q6_catalog_disabled: bool = False,
    calibration_key: str = '',
) -> tuple[int, ...]:
    key_index = QUALITY_KEYS.index(key)
    count = counts_tuple[key_index]
    exact_cells = exact_tuple[key_index]
    avg = avg_tuple[key_index]
    constrained = _cached_grid_constraint_options(key, count, exact_cells, avg)
    if constrained is not None:
        return constrained
    # Determine whether the cross-quality residual lock can fire. It requires every *other*
    # quality to have exactly one constrained option; only then does the result depend on the
    # full counts_tuple. Otherwise the result is a pure function of (key,count,exact,avg) and
    # we route through the tight-key cache (default ON; rollback restores the inline path).
    residual = target_int
    all_other_exact = target_int is not None
    if all_other_exact:
        for idx, other_key in enumerate(QUALITY_KEYS):
            if other_key == key:
                continue
            other_options = _cached_grid_constraint_options(
                other_key,
                counts_tuple[idx],
                exact_tuple[idx],
                avg_tuple[idx],
            )
            if other_options is None or len(other_options) != 1:
                all_other_exact = False
                break
            residual -= other_options[0]
    if not all_other_exact:
        if _run_env_get("AHMAD_DISABLE_GFC_PERKEY_CACHE") != "1":
            return _display_grid_options_no_residual(
                key,
                count,
                exact_cells,
                avg,
                is_ethan,
                center_int,
                q5_catalog_disabled,
                q6_catalog_disabled,
                calibration_key,
            )
        candidates = _composable_grid_options_with_q6_catalog(key, count)
        default = (
            float(center_int)
            if center_int is not None and center_int > 0
            else count * _grid_mean(key, is_ethan)
        )
        ranked = sorted(candidates, key=lambda option: (abs(option - default), option))
        return tuple(ranked[:DISPLAY_GRID_TOPK])
    # Residual lock: every OTHER tier is exact-pinned, so this tier's cells are the arithmetic
    # remainder. Already identity-consistent — the combo center cannot improve on it.
    candidates = tuple(
        option
        for option in _composable_grid_options_with_q6_catalog(key, count)
        if option == residual
    )
    default = count * _grid_mean(key, is_ethan)
    ranked = sorted(candidates, key=lambda option: (abs(option - default), option))
    return tuple(ranked[:DISPLAY_GRID_TOPK])


def _hard_total_residual_grid_option(
    counts: dict[str, int],
    evidence: RefEvidence,
    key: str,
) -> int | None:
    """Return this tier's exact residual for one correlated hard-total arm.

    This is deliberately conditional on one count combination, not a global
    lock: another surviving gold/red arm may produce another residual.  It only
    prevents a later size/floor prior from widening arithmetic already fixed by
    the hard total and the other four constrained tiers.
    """
    if _run_env_get(HARD_TOTAL_JOINT_CELLS_DISABLE) == "1":
        return None
    exact, avg, _ = _grid_display_signature(evidence)
    # The grid-identity second pass deliberately injects the engine's own SOFT total estimate.  It may
    # use residual arithmetic to reconcile a candidate, but it is not a tool/public hard total and must
    # not activate the hard-total joint lock (2550 otherwise collapsed 14/24/35 red cells to 24/24/24).
    target_int = _hard_total_grid_target_int(evidence)
    if target_int is None:
        return None
    residual = int(target_int)
    for index, other_key in enumerate(QUALITY_KEYS):
        if other_key == key:
            continue
        options = _cached_grid_constraint_options(
            other_key,
            int(counts[other_key]),
            exact[index],
            avg[index],
        )
        if options is None or len(options) != 1:
            return None
        residual -= int(options[0])
    if residual < _quality_cell_floor_for_grid_fit(
        key,
        evidence,
        int(counts[key]),
    ):
        return None
    if not _can_compose_grid_total_with_q6_catalog(key, int(counts[key]), residual):
        return None
    return residual


def _grid_identity_display_center(
    key: str, evidence: RefEvidence, combo_grid: float | None
) -> int | None:
    """族D: the combo's OWN reconciled grid for this tier, to be used as the display ranking center.

    Gate on `total_grid_target`: only then has _fit_grids_to_total_target actually reallocated the
    tiers to sum to the total. Without a target the fit returns the grids untouched, so combo_grid
    IS the naive count×prior — and the partial-floor re-centring further down (2401 R3: a revealed
    15-cell red car + 2 anchor-only reds) is strictly better than inheriting it. Returning None here
    leaves the legacy center in place, which is why this lever is a no-op on target-less games."""
    if combo_grid is None or combo_grid <= 0:
        return None
    if evidence.total_grid_target is None and not evidence.total_grid_options:
        return None
    if _run_env_get(GRID_IDENTITY_RECONCILE_DISABLE) == "1":
        return None
    if not _grid_identity_hero_in_scope(normalize_hero_key(evidence.hero)):
        return None
    return int(round(float(combo_grid)))


def _display_grid_options_for_quality(
    counts: dict[str, int],
    evidence: RefEvidence,
    key: str,
    combo_grid: float | None = None,
) -> tuple[int, ...]:
    exact, avg, target_int = _grid_display_signature(evidence)
    is_ethan = _is_ethan_grid_mean(evidence.hero)
    center_int = _grid_identity_display_center(key, evidence, combo_grid)
    options = _display_grid_options_cached(
        tuple(int(counts[item]) for item in QUALITY_KEYS),
        key,
        exact,
        avg,
        target_int,
        is_ethan,
        center_int,
        _run_env_get(Q5_CATALOG_CELL_COMPOSE_DISABLE) == "1",
        _run_env_get(Q6_CATALOG_CELL_COMPOSE_DISABLE) == "1",
        str((_SHIPWRECK_CALIBRATED_PRIOR.get() or {}).get('candidate_sha256','')),
    )
    count = int(counts.get(key, 0))
    hard_total_residual = _hard_total_residual_grid_option(counts, evidence, key)
    joint_cells = _quality_joint_cells_for_count(key, count, evidence)
    if joint_cells is not None:
        constrained = _cached_grid_constraint_options(
            key,
            count,
            exact[QUALITY_KEYS.index(key)],
            avg[QUALITY_KEYS.index(key)],
        )
        candidates = tuple(
            option
            for option in joint_cells
            if (constrained is None or option in constrained)
            and (hard_total_residual is None or option == hard_total_residual)
        )
        default = (
            float(center_int)
            if center_int is not None and center_int > 0
            else count * _grid_mean(key, is_ethan)
        )
        options = tuple(
            sorted(candidates, key=lambda option: (abs(option - default), option))[
                :DISPLAY_GRID_TOPK
            ]
        )
    cell_floor = _quality_cell_floor(key, evidence)
    if cell_floor > 0:
        # Partial-known floor center (2026-07-04, 2401 R3 diag): when the floor covers only SOME of
        # the quality's items (e.g. one revealed 15-cell red car + 2 anchor-only reds of unknown
        # size), the expected total is floor + unknown_n*grid_mean — NOT count*grid_mean (9.6),
        # which ranked the ≥floor candidates down to [15,16,17] against truth 21 (car 15 + 4 + 2).
        # Anchor-only reveals carry no cells, so floor_items < count is exactly this case.
        # Rollback: AHMAD_DISABLE_PARTIAL_FLOOR_CENTER=1.
        floor_items = int((evidence.quality_cell_floor_item_counts or {}).get(key, 0))
        unknown_n = max(0, count - floor_items)
        partial_known = (
            floor_items > 0
            and unknown_n > 0
            and hard_total_residual is None
            and _quality_exact_cells(key, evidence) is None
            and evidence.avg_cells.get(key) is None
            # Asymmetric: only re-center when the KNOWN items are larger than the size prior (the
            # under-count direction, e.g. 2401's 15-cell car). Known small items would pull the
            # center DOWN below the generic prior — net-negative on the 886-game sweep.
            and float(cell_floor) / float(floor_items) >= _grid_mean(key, is_ethan)
            and _run_env_get("AHMAD_DISABLE_PARTIAL_FLOOR_CENTER") != "1"
        )
        # partial_known keeps priority over the 族D combo center: it encodes a REVEALED oversized item
        # (a floor the fit never sees), whereas the combo center only encodes the total-grid identity.
        default = (
            float(cell_floor) + unknown_n * _grid_mean(key, is_ethan)
            if partial_known
            else (
                float(center_int)
                if center_int is not None and center_int > 0
                else count * _grid_mean(key, is_ethan)
            )
        )
        if partial_known:
            # The cached option table only carries the count*grid_mean NEIGHBOURHOOD, so re-ranking
            # its ≥floor survivors cannot reach the corrected center (gabriela 5606 R3: cached
            # {15,16,17} ≥ floor 12, center 24.8 unreachable). Rank the full composable candidate
            # set around floor + unknown*mean instead.
            candidates = tuple(
                option
                for option in (
                    joint_cells
                    if joint_cells is not None
                    else _composable_grid_options_with_q6_catalog(key, count)
                )
                if option >= cell_floor
            )
            ranked = sorted(candidates, key=lambda option: (abs(option - default), option))
            options = tuple(ranked[:DISPLAY_GRID_TOPK]) or options
        # BUG-L: the floor covers only the items it was revealed from — every OTHER item of this tier
        # still occupies at least one cell (see _quality_cell_floor_for_count).
        effective_floor = _quality_cell_floor_for_count(key, evidence, count)
        filtered = tuple(option for option in options if option >= effective_floor)
        if not filtered and effective_floor > cell_floor:
            # the cached neighbourhood may sit entirely below the corrected floor -> rebuild from the
            # composable set instead of silently falling back to an impossible option
            rebuilt = tuple(
                option
                for option in (
                    joint_cells
                    if joint_cells is not None
                    else _composable_grid_options_with_q6_catalog(key, count)
                )
                if option >= effective_floor
            )
            if rebuilt:
                ranked = sorted(rebuilt, key=lambda option: (abs(option - default), option))
                filtered = tuple(ranked[:DISPLAY_GRID_TOPK])
        if filtered:
            options = filtered
        elif _quality_exact_cells(key, evidence) is not None or evidence.avg_cells.get(key) is not None:
            return ()
        else:
            candidates = tuple(
                option
                for option in (
                    joint_cells
                    if joint_cells is not None
                    else _composable_grid_options_with_q6_catalog(key, count)
                )
                if option >= cell_floor
            )
            ranked = sorted(candidates, key=lambda option: (abs(option - default), option))
            options = tuple(ranked[:DISPLAY_GRID_TOPK])
    if key == "q5" and evidence.avg_cells.get("q5") is not None:
        filtered = tuple(
            option
            for option in options
            if _q5_known_item_cell_compose_matches(count, option, evidence)
        )
        if filtered:
            options = filtered
        elif _q5_known_item_cell_components(evidence) is not None:
            return ()
    if key == "q1":
        floor = _split_low_quality_q1_grid_floor(count, evidence)
        if floor > 0:
            filtered = tuple(option for option in options if option >= floor)
            if filtered:
                return filtered
            if _quality_exact_cells(key, evidence) is not None or evidence.avg_cells.get(key) is not None:
                return ()
            candidates = tuple(
                option
                for option in _composable_grid_options_with_q6_catalog(key, count)
                if option >= floor
            )
            default = count * DEFAULT_GRID_MEANS[key]
            ranked = sorted(candidates, key=lambda option: (abs(option - default), option))
            return tuple(ranked[:DISPLAY_GRID_TOPK])
    if options:
        return options
    # A hard exact/average constraint that has no legal footprint rejects this
    # count candidate. Falling back to count×prior would silently erase the
    # evidence in the rendered (count, cells) pair.
    if (
        _quality_exact_cells(key, evidence) is not None
        or (
            evidence.avg_cells.get(key) is not None
            and key not in evidence.soft_avg_cell_keys
        )
    ):
        return ()
    if cell_floor > 0:
        return ()
    if joint_cells is not None:
        return joint_cells
    fallback = int(round(counts.get(key, 0) * _grid_mean(key, is_ethan)))
    if _can_compose_grid_total_with_q6_catalog(key, int(counts.get(key, 0)), fallback):
        return (fallback,)
    return _composable_grid_options_with_q6_catalog(key, int(counts.get(key, 0)))[:1]


def _red_cell_option_distribution(
    options: tuple[int, ...],
    *,
    count: int,
    center_cells: float | None,
    low_tail_enabled: bool,
) -> tuple[tuple[int, float], ...]:
    """Weighted q6 footprint states for E09, preserving the legacy arm when disabled.

    The enabled distribution is deliberately asymmetric: cloud p10/p25 supply the two low states,
    while 48% stays on the legacy center and the remaining 26% stays on its neighboring display
    states.  Duplicate composable totals are merged.  Callers still pin p50/p90 to the legacy
    quantiles, so this distribution cannot silently re-center 参考 or widen the E10 high tail.
    """
    base = tuple(int(option) for option in options)
    if not base:
        return ()
    if not low_tail_enabled or int(count) <= 0:
        probability = 1.0 / len(base)
        return tuple((option, probability) for option in base)

    center = (
        float(center_cells)
        if center_cells is not None and float(center_cells) > 0
        else int(count) * DEFAULT_GRID_MEANS["q6"]
    )
    center_option = min(base, key=lambda option: (abs(option - center), option))
    other_options = tuple(option for option in base if option != center_option)
    by_cells: dict[int, float] = {center_option: RED_CPI_LEGACY_CENTER_MASS}
    remaining_mass = 1.0 - RED_CPI_LEGACY_CENTER_MASS - sum(
        weight for _cpi, weight in RED_CPI_LOW_TAIL_POINTS
    )
    if other_options:
        neighbor_weight = remaining_mass / len(other_options)
        for option in other_options:
            by_cells[option] = by_cells.get(option, 0.0) + neighbor_weight
    else:
        by_cells[center_option] += remaining_mass

    composable = _composable_grid_options_for_quality("q6", int(count))
    for cells_per_item, weight in RED_CPI_LOW_TAIL_POINTS:
        target = int(count) * cells_per_item
        option = min(composable, key=lambda value: (abs(value - target), value))
        by_cells[option] = by_cells.get(option, 0.0) + weight
    total = sum(by_cells.values())
    return tuple((cells, weight / total) for cells, weight in by_cells.items())


def _public_quality_avg_value_notes(notes: Iterable[str]) -> list[str]:
    return [
        str(note)
        for note in notes
        if re.fullmatch(r"public_q[456]_avg_value", str(note))
    ]


def _public_avg_value_presence_fallback_keys(snapshot: dict[str, Any]) -> frozenset[str]:
    raw = snapshot.get(PUBLIC_AVG_VALUE_PRESENCE_FALLBACK_KEYS)
    if not isinstance(raw, (list, tuple, set, frozenset)):
        return frozenset()
    return frozenset(str(key) for key in raw if str(key) in {"q4", "q5", "q6"})


def _positive_public_avg_value_fallback_keys(
    snapshot: dict[str, Any],
    public_avg_notes: Iterable[str],
) -> frozenset[str]:
    note_keys = {
        match.group(1)
        for note in public_avg_notes
        if (match := re.fullmatch(r"public_(q[456])_avg_value", str(note)))
        is not None
    }
    if not note_keys:
        return frozenset()
    ui_contract = snapshot.get("ui_contract")
    if not isinstance(ui_contract, dict):
        return frozenset()
    constraints = ui_contract.get("constraints")
    if not isinstance(constraints, dict):
        return frozenset()
    public_info = constraints.get("public_info")
    if not isinstance(public_info, dict):
        return frozenset()
    return frozenset(
        key
        for key, value in _public_quality_avg_values(public_info).items()
        if key in note_keys and _avg_value_has_positive_signal(value)
    )


def _without_public_quality_avg_values(
    snapshot: dict[str, Any],
    *,
    presence_fallback_keys: Iterable[str] = (),
) -> dict[str, Any]:
    cloned = copy.deepcopy(snapshot)
    ui_contract = cloned.get("ui_contract")
    if not isinstance(ui_contract, dict):
        return cloned
    constraints = ui_contract.get("constraints")
    if not isinstance(constraints, dict):
        return cloned
    public_info = constraints.get("public_info")
    if not isinstance(public_info, dict):
        return cloned

    def keep(row: Any) -> bool:
        if not isinstance(row, dict):
            return True
        semantic = str(row.get("semantic") or "")
        return semantic not in PUBLIC_AVG_VALUES

    for key in ("public_numeric_facts", "public_avg_values"):
        rows = public_info.get(key)
        if isinstance(rows, list):
            public_info[key] = [row for row in rows if keep(row)]
    keys = sorted({str(key) for key in presence_fallback_keys if str(key) in {"q4", "q5", "q6"}})
    if keys:
        cloned[PUBLIC_AVG_VALUE_PRESENCE_FALLBACK_KEYS] = keys
    return cloned


def _avg_display_feasibility_disabled() -> bool:
    """BUG-I kill: restore the pre-2026-07-11 behaviour (display-rounded avgs skip the integer-product
    intersection, and a tool-provided avg is downgraded to soft whenever public info repeats it)."""
    return os.environ.get("BIDKING_DISABLE_AVG_DISPLAY_FEASIBILITY") == "1"


def _derive_soft_public_avg_cell_keys(
    *,
    source_notes: Iterable[str],
    fixed_counts: dict[str, int],
    quality_cells: dict[str, float],
) -> frozenset[str]:
    notes_list = [str(note) for note in source_notes]
    # 族A / BUG-I (2026-07-11, 群友 #13 aisha 5606 R3 紫 7/9/12 @均格2.25): a tier whose avg_cells also
    # arrived from a TOOL (优品均格 100112 / 金色均格 100113 -> note `action_<id>_<tier>_avg_cells`) is HARD
    # evidence — the game told us that tier's exact average. The soft flag exists for a PUBLIC-only avg
    # (a prior before the tier's count is known), but it was being set purely on the presence of the
    # public note, so a tool-provided avg got DOWNGRADED whenever public info happened to repeat it —
    # and the downgrade skips the integer-product constraint, letting arithmetically impossible counts
    # through (avg 2.25 admits only multiples of 4, yet the engine displayed 7/9/12; truth 8).
    tool_avg_keys = (
        set()
        if _avg_display_feasibility_disabled()
        else {
            m.group(1)
            for note in notes_list
            if "_conflict" not in note
            if (
                m := re.fullmatch(
                    r"(?:action|skill)_\d+_(q[1-6])_avg_cells(?:_.*)?",
                    note,
                )
            )
            is not None
        }
    )
    soft: set[str] = set()
    for note in notes_list:
        match = re.fullmatch(r"public_(q[456])_avg_cells", note)
        if not match:
            continue
        key = match.group(1)
        if fixed_counts.get(key) is not None:
            continue
        if key in quality_cells:
            continue
        if key in tool_avg_keys:
            continue  # a tool gave this tier's avg -> hard evidence, not a soft public prior
        soft.add(key)
    return frozenset(soft)


def _apply_aisha_derived_q5_cells_from_exact_count_avg(
    *,
    hero: str,
    map_id: int | None,
    phase: str,
    total_count: int | None,
    fixed_counts: dict[str, int],
    min_counts: dict[str, int],
    avg_cells: dict[str, float],
    quality_cells: dict[str, float],
    quality_cell_floors: dict[str, float],
    quality_cell_floor_item_counts: dict[str, int],
    soft_avg_cell_keys: frozenset[str],
    source_notes: list[str],
) -> None:
    """Promote one unique Aisha q5 count×hard-average product to exact cells.

    The 5602 incident had all non-red tiers physically pinned except q5:
    q5 count=4 and a hard tool average=6.0 already imply exactly 24 cells.
    Leaving that arithmetic only in combo generation made the upstream layout
    count anchor treat the 24 cells as unknown and exclude the zero-red arm.

    This is deliberately narrower than a generic count/average materializer:
    Aisha bidding on 56xx without an explicit total count, q1/q3/q4 already
    exact, no direct q6 evidence, a hard q5 average, and exactly one
    catalog-composable q5 cell total.  Older map families and snapshots with
    an exact total count already have working count/layout anchors; changing
    those paths regressed clean official examples during the 5602 A/B.
    Conflicts fail closed and leave the legacy evidence untouched.
    """
    if (
        _run_env_get(AISHA_DERIVED_Q5_PINNED_NONRED_DISABLE) == "1"
        or normalize_hero_key(hero) != "aisha"
        or _ethan_map_family(map_id) != "map_56xx"
        or str(phase or "").strip().lower() != "bidding"
        or total_count is not None
        or "q5" in quality_cells
        or "q5" in soft_avg_cell_keys
        or fixed_counts.get("q5") is None
        or avg_cells.get("q5") is None
        or fixed_counts.get("q6") is not None
        or min_counts.get("q6", 0) > 0
        or quality_cells.get("q6") is not None
        or avg_cells.get("q6") is not None
        or any(fixed_counts.get(key) is None for key in ("q1", "q3", "q4"))
        or any(
            _exact_integer_quality_cell(quality_cells.get(key)) is None
            for key in ("q1", "q3", "q4")
        )
    ):
        return

    count = int(fixed_counts["q5"])
    avg = _safe_float(avg_cells.get("q5"))
    if count <= 0 or avg is None or not math.isfinite(avg) or avg <= 0:
        return
    options = _avg_grid_options(count, float(avg), "q5")
    if len(options) != 1:
        return
    cells = int(options[0])
    if cells < count or not _can_compose_grid_total_for_quality("q5", count, cells):
        return

    floor_raw = _safe_float(quality_cell_floors.get("q5"))
    if floor_raw is not None and floor_raw > float(cells) + 0.0001:
        _append_source_note_once(
            source_notes,
            f"{AISHA_DERIVED_Q5_COUNT_AVG_CELLS_NOTE}_conflict:floor",
        )
        return
    known_count = max(0, int(quality_cell_floor_item_counts.get("q5", 0) or 0))
    if known_count > 0 and floor_raw is not None:
        known_cells = int(round(float(floor_raw)))
        if (
            abs(float(floor_raw) - float(known_cells)) > 0.0001
            or known_count > count
            or known_cells > cells
            or not _can_compose_grid_total_for_quality(
                "q5",
                count - known_count,
                cells - known_cells,
            )
        ):
            _append_source_note_once(
                source_notes,
                f"{AISHA_DERIVED_Q5_COUNT_AVG_CELLS_NOTE}_conflict:known_items",
            )
            return

    quality_cells["q5"] = float(cells)
    _append_source_note_once(
        source_notes,
        f"{AISHA_DERIVED_Q5_COUNT_AVG_CELLS_NOTE}:{count}x{float(avg):g}={cells}",
    )


def _derive_soft_public_avg_value_keys(
    *,
    source_notes: Iterable[str],
    fixed_counts: dict[str, int],
    quality_values: dict[str, float],
    avg_values: dict[str, float],
) -> frozenset[str]:
    soft: set[str] = set()
    for note in source_notes:
        match = re.fullmatch(r"public_(q[456])_avg_value", str(note))
        if not match:
            continue
        key = match.group(1)
        if fixed_counts.get(key) is not None:
            continue
        if key in quality_values:
            continue
        if key not in avg_values:
            continue
        soft.add(key)
    return frozenset(soft)


def _public_avg_value_soft_pending(
    key: str,
    *,
    source_notes: Iterable[str],
    fixed_counts: dict[str, int],
    quality_values: dict[str, float],
    avg_values: dict[str, float],
) -> bool:
    if not any(str(note) == f"public_{key}_avg_value" for note in source_notes):
        return False
    if fixed_counts.get(key) is not None:
        return False
    if key in quality_values:
        return False
    return key in avg_values


def _public_quality_avg_cells_notes(notes: Iterable[str]) -> list[str]:
    return [
        str(note)
        for note in notes
        if re.fullmatch(r"public_q[456]_avg_cells", str(note))
    ]


def _without_public_avg_cell_constraints(
    snapshot: dict[str, Any],
    avg_cell_notes: Iterable[str],
) -> dict[str, Any]:
    qualities: set[str] = set()
    for note in avg_cell_notes:
        match = re.fullmatch(r"public_(q[456])_avg_cells", str(note))
        if match:
            qualities.add(match.group(1))
    if not qualities:
        return snapshot
    cloned = copy.deepcopy(snapshot)
    for container_key in ("structured_ref_inputs",):
        container = cloned.get(container_key)
        if not isinstance(container, dict):
            continue
        avg_cells = container.get("avg_cells")
        if isinstance(avg_cells, dict):
            container["avg_cells"] = {
                key: value for key, value in avg_cells.items() if key not in qualities
            }
    ui_contract = cloned.get("ui_contract")
    if isinstance(ui_contract, dict):
        constraints = ui_contract.get("constraints")
        if isinstance(constraints, dict):
            public_info = constraints.get("public_info")
            if isinstance(public_info, dict):
                blocked = {f"{quality}_avg_cells" for quality in ("q4", "q5", "q6")}

                def keep(row: Any) -> bool:
                    if not isinstance(row, dict):
                        return True
                    return str(row.get("semantic") or "") not in blocked

                for key in ("public_numeric_facts", "public_avg_values"):
                    rows = public_info.get(key)
                    if isinstance(rows, list):
                        public_info[key] = [row for row in rows if keep(row)]
    return cloned


def _with_public_quality_avg_fallback_notes(
    result: RefResult,
    *,
    public_avg_value_notes: Iterable[str],
    public_avg_cell_notes: Iterable[str],
) -> RefResult:
    downgrade_notes = ["public_quality_avg_value_conflict_fallback"]
    downgrade_notes.extend(f"{note}_downgraded" for note in public_avg_value_notes)
    if public_avg_cell_notes:
        downgrade_notes.append("public_quality_avg_cells_conflict_fallback")
        downgrade_notes.extend(f"{note}_downgraded" for note in public_avg_cell_notes)
    notes = tuple(dict.fromkeys([*result.notes, *downgrade_notes]))
    evidence = replace(
        result.evidence,
        source_notes=tuple(dict.fromkeys([*result.evidence.source_notes, *downgrade_notes])),
    )
    return replace(result, notes=notes, evidence=evidence)


def _retry_without_public_quality_avg_values(
    snapshot: dict[str, Any],
    *,
    public_avg_notes: Iterable[str],
    static_data: dict[str, Any],
    safety_factor: float,
    max_combos: int,
) -> RefResult | None:
    notes = list(public_avg_notes)
    if not notes:
        return None
    presence_keys = _positive_public_avg_value_fallback_keys(snapshot, notes)
    result = run_reference_engine(
        _without_public_quality_avg_values(
            snapshot,
            presence_fallback_keys=presence_keys,
        ),
        static_data=static_data,
        safety_factor=safety_factor,
        max_combos=max_combos,
        _allow_public_avg_fallback=False,
    )
    if result.status not in {"ok", "count_prior"}:
        return None
    return _with_public_quality_avg_fallback_notes(
        result,
        public_avg_value_notes=notes,
        public_avg_cell_notes=(),
    )


def _retry_without_public_avg_constraints(
    snapshot: dict[str, Any],
    *,
    public_avg_value_notes: Iterable[str],
    public_avg_cell_notes: Iterable[str],
    static_data: dict[str, Any],
    safety_factor: float,
    max_combos: int,
) -> RefResult | None:
    value_notes = list(public_avg_value_notes)
    cell_notes = list(public_avg_cell_notes)
    if not value_notes and not cell_notes:
        return None
    working = snapshot
    if value_notes:
        presence_keys = _positive_public_avg_value_fallback_keys(working, value_notes)
        working = _without_public_quality_avg_values(
            working,
            presence_fallback_keys=presence_keys,
        )
    if cell_notes:
        working = _without_public_avg_cell_constraints(working, cell_notes)
    result = run_reference_engine(
        working,
        static_data=static_data,
        safety_factor=safety_factor,
        max_combos=max_combos,
        _allow_public_avg_fallback=False,
    )
    if result.status not in {"ok", "count_prior"}:
        return None
    return _with_public_quality_avg_fallback_notes(
        result,
        public_avg_value_notes=value_notes,
        public_avg_cell_notes=cell_notes,
    )


HIGH_TIER_GRID_RELAXED_NOTE = "high_tier_grid_target_relaxed_no_reachable"


ETHAN_VALUE_CELL_FLOOR_RELAXED_NOTE = "ethan_value_cell_floor_relaxed_no_reachable"
ETHAN_OCCUPANCY_TARGET_RELAXED_NOTE = "ethan_occupancy_target_relaxed_no_reachable"


def _retry_without_ethan_occupancy_target(
    snapshot: dict[str, Any],
    *,
    static_data: dict[str, Any],
    safety_factor: float,
    max_combos: int,
) -> RefResult | None:
    """The occupancy grid estimate is an ESTIMATE (partial-reveal rectangle minus a calibrated
    bottom deficit) applied as an EQUALITY anchor; scan/appraisal results are PROOFS. A deep-scan
    game can prove more cells than the anchor allows (live 2401 R4 hotfix3, 群友: 良品62格 +
    优品均格2.889锁26紫格 + 极品扫描23格 + q1件下限 > anchor 110 -> every combo rejected ->
    overlay showed 外援未就绪/'-' at a fully-scanned decision round). When the anchor is the
    blocker, re-run once without it — the count/cells evidence then drives the grid directly."""
    working = dict(snapshot)
    working["_ethan_disable_occupancy_target"] = True
    result = run_reference_engine(
        working,
        static_data=static_data,
        safety_factor=safety_factor,
        max_combos=max_combos,
        _allow_public_avg_fallback=False,
        _allow_high_tier_grid_fallback=False,
        _allow_sparse_soft_fallback=False,
    )
    if result.status not in {"ok", "count_prior"}:
        return None
    notes = list(result.notes)
    _append_source_note_once(notes, ETHAN_OCCUPANCY_TARGET_RELAXED_NOTE)
    return replace(result, notes=tuple(notes))


def _retry_without_ethan_value_cell_floor(
    snapshot: dict[str, Any],
    *,
    static_data: dict[str, Any],
    safety_factor: float,
    max_combos: int,
) -> RefResult | None:
    """The ethan value->cells floor divides an EXACT quality value by the family p75 per-cell
    price; a game priced above p75 (small dear purples) makes the floor overshoot the true cells
    and can reject every combo together with the full-outline totals (real59: 2502/5608 went
    no_reachable). The warehouse is always feasible — when the floor is the blocker, re-run once
    without it (floor is a display/prior aid, never worth blanking the round)."""
    working = dict(snapshot)
    working["_ethan_disable_value_cell_floor"] = True
    result = run_reference_engine(
        working,
        static_data=static_data,
        safety_factor=safety_factor,
        max_combos=max_combos,
        _allow_public_avg_fallback=False,
        _allow_high_tier_grid_fallback=False,
        _allow_sparse_soft_fallback=False,
    )
    if result.status not in {"ok", "count_prior"}:
        return None
    notes = list(result.notes)
    _append_source_note_once(notes, ETHAN_VALUE_CELL_FLOOR_RELAXED_NOTE)
    return replace(result, notes=tuple(notes))


def _retry_without_high_tier_grid_target(
    snapshot: dict[str, Any],
    *,
    static_data: dict[str, Any],
    safety_factor: float,
    max_combos: int,
) -> RefResult | None:
    """The high-tier-cell grid target is a DERIVED heuristic (raises the total grid from known
    q3–q5 cells + residual items). It ignores public-reveal cell floors (a single q6 red revealed
    at N cells) and a residual tier's known avg_cells, so it can pin the total grid BELOW the
    physical minimum and reject every combo — at the decision round the overlay then shows no quote
    at all (2537 R4: derived target 83 < physical min 87 → no_reachable_combo). The real warehouse
    is always feasible, so when the derived target is the blocker, re-run once without it and let the
    count_prior path produce an estimate. Only fires on an otherwise-empty combo set, so it cannot
    change any sample that already quotes."""
    working = dict(snapshot)
    working["_skip_high_tier_grid_target"] = True
    result = run_reference_engine(
        working,
        static_data=static_data,
        safety_factor=safety_factor,
        max_combos=max_combos,
        _allow_public_avg_fallback=False,
        _allow_high_tier_grid_fallback=False,
    )
    if result.status not in {"ok", "count_prior"}:
        return None
    notes = list(result.notes)
    _append_source_note_once(notes, HIGH_TIER_GRID_RELAXED_NOTE)
    return replace(result, notes=tuple(notes))


SPARSE_EARLY_SOFT_TARGET_RELAXED_NOTE = "sparse_early_soft_target_relaxed_no_reachable"


def _retry_without_sparse_early_soft_target(
    snapshot: dict[str, Any],
    *,
    static_data: dict[str, Any],
    safety_factor: float,
    max_combos: int,
) -> RefResult | None:
    """Draw-hero (sophie/gabriela/...) sparse-early soft target is a CAP to curb early-round
    over-estimation, NOT a settled total. It feeds _fit_grids_to_total_target as an EQUALITY anchor,
    so when a high tier is count-locked (public 极品存量 q5=8) with a cell floor, the cap can sit
    below the floor-implied minimum and reject every combo -> no_reachable blank (live gabriela 2403
    R3: cap 52, q5=8 locked @ floor 11 -> feasible total <= 52-11+8 = 49 < count band floor 50 ->
    every combo rejected). The real vault is feasible, so on an otherwise-empty combo set drop the
    soft cap once and let the visible-depth anchor own the grid range (same as R5). Only fires when
    the combo set is empty, so it cannot change any sample that already quotes."""
    working = dict(snapshot)
    working["_skip_sparse_early_soft_target"] = True
    result = run_reference_engine(
        working,
        static_data=static_data,
        safety_factor=safety_factor,
        max_combos=max_combos,
        _allow_public_avg_fallback=False,
        _allow_high_tier_grid_fallback=False,
        _allow_sparse_soft_fallback=False,
    )
    if result.status not in {"ok", "count_prior"}:
        return None
    notes = list(result.notes)
    _append_source_note_once(notes, SPARSE_EARLY_SOFT_TARGET_RELAXED_NOTE)
    return replace(result, notes=tuple(notes))


AISHA_RED_ROOM_REWEIGHT_NOTE_PREFIX = "aisha_red_room_reweight:"
_AISHA_RED_ROOM_MIN_ROUND = 3
_AISHA_RED_ROOM_MIN_ROOM = 3.0  # cap - non_red below this is geometry noise, not real red space (R6)
_AISHA_RED_ROOM_TIGHT_MAX = 10.0  # only tight vaults (low-red signature) carry false-positive red;
# large room = deep/rich vault where red genuinely fills space (high-red, accurate) -> leave alone
_AISHA_RED_ROOM_RED_VOL = 3.2  # avg red (q6) cells per item, for cells<->count of the room ceiling
_AISHA_RED_ROOM_TIER_SLACK = 2.0  # allow up to 2x the map-tier expected red before the room binds
_AISHA_RED_ROOM_PENALTY = 0.35  # log-weight penalty per red CELL over the ceiling (soft, not a hard cut)
# Fully-pinned non-red special case (2026-07-05, live 5608 aisha R4/R5): when 普/良/优/极 scans pin
# q1+q3+q4+q5 cells EXACTLY, red is a pure grid RESIDUAL = layout_total − pinned_nonred. This is a
# geometric identity independent of _is_pure_prior_red — a weak min_q6>=1 floor does NOT make the
# count-prior's 16-23 red cells real when only 1-5 grid cells remain. Slack absorbs the layout's own
# ±few-cell error (5608: grid_hi 84 vs truth total 85 → residual 5, +slack 2 covers truth red 6).
_AISHA_RED_ROOM_PINNED_SLACK = 2.0
_AISHA_RED_ROOM_PINNED_FLOOR_SLACK = 10.0
AISHA_PINNED_RED_RESIDUAL_FLOOR_NOTE = "aisha_pinned_red_residual_floor"
AISHA_PINNED_RED_RESIDUAL_FLOOR_DISABLE = (
    "BIDKING_DISABLE_AISHA_PINNED_RED_RESIDUAL_FLOOR"
)
AISHA_PINNED_NONRED_ROOM_HI_DISABLE = "BIDKING_DISABLE_AISHA_PINNED_NONRED_ROOM_HI"
AISHA_PINNED_NONRED_ROOM_HI_NOTE = "aisha_pinned_nonred_red_room_hi"
AISHA_PINNED_NONRED_RESIDUAL_BAND_NOTE = "aisha_pinned_nonred_red_residual_band"
AISHA_PINNED_NONRED_RESIDUAL_BAND_DISABLE = (
    "BIDKING_DISABLE_AISHA_PINNED_NONRED_RESIDUAL_BAND"
)


def _aisha_q6_candidate_probability(value: Any) -> float | None:
    """Validate one producer-facing probability without coercing malformed values."""

    if type(value) is int:  # noqa: E721 - bool must remain invalid
        return 1.0 if value == 1 else None
    if type(value) is float:  # noqa: E721 - match the strict producer boundary
        if math.isfinite(value) and 0.0 < value <= 1.0:
            return value
    return None


def _aisha_q6_soft_marginal_can_be_discarded(candidates: Any) -> bool:
    """Accept only a well-formed, non-exact native marginal candidate set."""

    if type(candidates) not in (list, tuple):  # noqa: E721 - exact native rows
        return False
    seen: set[int] = set()
    total = 0.0
    probabilities: list[float] = []
    for row in candidates:
        if type(row) not in (list, tuple) or len(row) != 2:  # noqa: E721
            return False
        value, raw_probability = row
        probability = _aisha_q6_candidate_probability(raw_probability)
        if type(value) is not int or value < 0 or probability is None:  # noqa: E721
            return False
        if value in seen:
            return False
        seen.add(value)
        total += probability
        probabilities.append(probability)
    if total > 1.000001:
        return False
    return not (len(probabilities) == 1 and probabilities[0] == 1.0)


def _aisha_q6_soft_composition_can_be_discarded(result: RefResult) -> bool:
    """Gate q6 joint/lock omission to a validated stale probabilistic bundle.

    The residual projection cannot prove that malformed, exact, or internally
    conflicting composition metadata is stale. Preserve such authoritative input so
    the strict composition producer can continue to fail closed instead of turning a
    conflict into a locally unavailable q6 row.
    """

    joints = result.quality_count_cells_candidates
    locks = result.quality_lock
    count_marginals = result.quality_count_candidates
    cells_marginals = result.quality_cells_candidates
    if any(
        type(container) is not dict  # noqa: E721 - refuse coercive subclasses
        for container in (joints, locks, count_marginals, cells_marginals)
    ):
        return False
    if ("q6" in joints) != ("q6" in locks):
        return False
    if "q6" not in joints:
        return False

    lock = locks["q6"]
    if type(lock) is not dict or any(  # noqa: E721 - exact JSON-shaped metadata
        type(key) is not str for key in lock  # noqa: E721
    ):
        return False
    strength = lock.get("strength")
    reason = lock.get("reason")
    if (
        type(strength) is not str  # noqa: E721
        or strength.lower() != "probabilistic"
        or (reason is not None and type(reason) is not str)  # noqa: E721
    ):
        return False

    candidates = joints["q6"]
    if type(candidates) not in (list, tuple) or not candidates:  # noqa: E721
        return False
    seen: set[tuple[int, int]] = set()
    total = 0.0
    probabilities: list[float] = []
    for row in candidates:
        if type(row) not in (list, tuple) or len(row) != 3:  # noqa: E721
            return False
        count, cells, raw_probability = row
        probability = _aisha_q6_candidate_probability(raw_probability)
        if (
            type(count) is not int  # noqa: E721
            or count < 0
            or type(cells) is not int  # noqa: E721
            or cells < 0
            or probability is None
        ):
            return False
        identity = (count, cells)
        if identity in seen:
            return False
        seen.add(identity)
        total += probability
        probabilities.append(probability)
    if total > 1.000001 or (
        len(probabilities) == 1 and probabilities[0] == 1.0
    ):
        return False

    for marginals in (count_marginals, cells_marginals):
        if "q6" in marginals and not _aisha_q6_soft_marginal_can_be_discarded(
            marginals["q6"]
        ):
            return False
    return True


def _apply_aisha_pinned_nonred_room_hi(
    result: RefResult,
    evidence: RefEvidence,
    *,
    round_no: int | None,
) -> RefResult:
    """Reconcile the red count/cells/value band to the geometry residual.

    Once q1/q3/q4/q5 cells are exact, every total-grid arm leaves one red residual.
    Pair each arm with its red-count percentile and the nearest real q6 catalog
    composition. This keeps the entire row coherent; the old high-only patch could show
    2 red / 40 cells beside a value priced from 6 cells.
    """
    if result.q5_total_cells_value_summary.get("physical_joint") is True:
        # This lane already publishes the same catalog-conditioned q6 owner in
        # count/cells/value space. Re-projecting it as a pure-prior residual
        # would erase the very tail that the physical domains established.
        return result
    if AISHA_MULTICOUNT_Q5_CELLS_INFERRED_TOTAL_SOFT_NOTE in evidence.source_notes:
        # The pricing posterior already contains the anti-correlated q5/q6 count
        # rows and their q6 catalog cells. Re-projecting only the three display
        # percentiles through a total-grid residual would discard that joint and
        # can trim its reachable tail (2524: 3 red / 23 cells). Keep the genuine
        # joint; the soft total/layout range remains available separately.
        return result

    # The older 5608 cut-only residual is applied after combo aggregation, so its
    # clipped red cells cannot be mapped back to the pre-clamp q6 probability rows.
    # Keep the count marginal and publish the clipped cells consistently. A validated
    # soft q6 bundle is stale after this projection and can be removed atomically;
    # authoritative or malformed metadata must survive for producer fail-closed.
    if (
        result.red_cells_range
        and any(
            str(note).startswith("aisha_pinned_red_residual:")
            for note in result.notes
        )
    ):
        discard_q6_composition = _aisha_q6_soft_composition_can_be_discarded(
            result
        )
        clipped_cells = tuple(result.red_cells_range)
        quality_cells_ranges = dict(result.quality_cells_ranges)
        quality_cells_ranges["q6"] = clipped_cells
        quality_cells_candidates = dict(result.quality_cells_candidates)
        quality_count_cells_candidates = dict(result.quality_count_cells_candidates)
        quality_lock = dict(result.quality_lock)
        if discard_q6_composition:
            quality_cells_candidates.pop("q6", None)
            quality_count_cells_candidates.pop("q6", None)
            quality_lock.pop("q6", None)
        result = replace(
            result,
            quality_cells_ranges=quality_cells_ranges,
            quality_cells_candidates=quality_cells_candidates,
            quality_count_cells_candidates=quality_count_cells_candidates,
            quality_lock=quality_lock,
        )

    if (
        _run_env_get(AISHA_PINNED_NONRED_ROOM_HI_DISABLE) == "1"
        or normalize_hero_key(evidence.hero) != "aisha"
        or evidence.phase != "bidding"
        or round_no is None
        or int(round_no) < _AISHA_RED_ROOM_MIN_ROUND
        or evidence.total_grid_target is not None
        or not _is_pure_prior_red(evidence)
        or _quality_exact_cells("q6", evidence) is not None
        or evidence.avg_cells.get("q6") is not None
        or result.status not in {"ok", "count_prior"}
        or not result.total_grid_range
        or result.total_grid_range[2] is None
        or not result.red_cells_range
        or result.red_cells_range[2] is None
    ):
        return result

    pinned_nonred: list[int] = []
    for key in ("q1", "q3", "q4", "q5"):
        cells = _exact_integer_quality_cell(evidence.quality_cells.get(key))
        if cells is None:
            return result
        pinned_nonred.append(int(cells))

    nonred_total = sum(pinned_nonred)
    if (
        _run_env_get(Q6_CATALOG_CELL_COMPOSE_DISABLE) == "1"
        or _run_env_get(AISHA_PINNED_NONRED_RESIDUAL_BAND_DISABLE) == "1"
    ):
        # Preserve the pre-F05 residual display for the dedicated rollback and for the existing
        # q6-domain rollback: high-only red-or-empty room, quote/value untouched.
        room_hi = max(
            0,
            int(round(float(result.total_grid_range[2]))) - nonred_total,
        )
        count_hi = result.red_count_range[2] if result.red_count_range else None
        catalog_hi = (
            _catalog_quality_grid_ceiling("q6", int(count_hi))
            if count_hi is not None
            and _run_env_get(Q6_CATALOG_CELL_COMPOSE_DISABLE) != "1"
            else None
        )
        if catalog_hi is not None:
            room_hi = min(room_hi, int(catalog_hi))
        old_hi = int(result.red_cells_range[2])
        if room_hi <= old_hi:
            return result
        legacy_cells = (
            result.red_cells_range[0],
            result.red_cells_range[1],
            room_hi,
        )
        legacy_quality_cells = dict(result.quality_cells_ranges)
        legacy_quality_cells["q6"] = legacy_cells
        return replace(
            result,
            red_cells_range=legacy_cells,
            quality_cells_ranges=legacy_quality_cells,
            notes=tuple(
                dict.fromkeys(
                    list(result.notes)
                    + [f"{AISHA_PINNED_NONRED_ROOM_HI_NOTE}:{old_hi}->{room_hi}"]
                )
            ),
        )

    residual_targets = tuple(
        max(0, int(round(float(total or 0))) - nonred_total)
        for total in result.total_grid_range
    )
    counts = result.red_count_range or (None, None, None)
    old_red_cells = tuple(result.red_cells_range)
    new_cells: list[int | None] = []
    for index, (target, count) in enumerate(zip(residual_targets, counts)):
        if count is None:
            new_cells.append(old_red_cells[index])
            continue
        options = _composable_grid_options_with_q6_catalog("q6", int(count))
        if not options:
            new_cells.append(old_red_cells[index])
            continue
        if index == 0:
            below = [value for value in options if value <= target]
            chosen = max(below) if below else min(options)
        elif index == 2:
            above = [value for value in options if value >= target]
            chosen = min(above) if above else max(options)
        else:
            chosen = min(options, key=lambda value: (abs(value - target), value))
        new_cells.append(int(chosen))
    if all(value is not None for value in new_cells):
        new_cells[1] = max(int(new_cells[0]), int(new_cells[1]))
        new_cells[2] = max(int(new_cells[1]), int(new_cells[2]))
    new_red_cells = tuple(new_cells)

    old_red_values = tuple(result.red_value_range or (None, None, None))
    new_red_values: list[int | None] = []
    for old_value, count, cells in zip(old_red_values, counts, new_red_cells):
        floor = (
            _catalog_min_total_value_for_quality_count_cells(6, int(count), int(cells))
            if count is not None and cells is not None
            else None
        )
        if old_value is None:
            new_red_values.append(floor)
        else:
            new_red_values.append(max(int(old_value), int(floor or 0)))
    if (
        new_red_cells == old_red_cells
        and tuple(new_red_values) == old_red_values
    ):
        return result

    quality_cells_ranges = dict(result.quality_cells_ranges)
    quality_cells_ranges["q6"] = new_red_cells
    quality_cells_candidates = dict(result.quality_cells_candidates)
    quality_count_cells_candidates = dict(result.quality_count_cells_candidates)
    quality_lock = dict(result.quality_lock)
    if _aisha_q6_soft_composition_can_be_discarded(result):
        quality_cells_candidates.pop("q6", None)
        quality_count_cells_candidates.pop("q6", None)
        quality_lock.pop("q6", None)
    return replace(
        result,
        red_cells_range=new_red_cells,
        red_value_range=tuple(new_red_values),
        quality_cells_ranges=quality_cells_ranges,
        # Validated soft rows were generated before projecting the spatial residual and can
        # contain stale pairs such as 2件/6格 beside a displayed 2件/32格 arm, so omit that bundle
        # atomically. Preserve authoritative or malformed rows for producer fail-closed.
        quality_cells_candidates=quality_cells_candidates,
        quality_count_cells_candidates=quality_count_cells_candidates,
        quality_lock=quality_lock,
        notes=tuple(
            dict.fromkeys(
                list(result.notes)
                + [
                    f"{AISHA_PINNED_NONRED_RESIDUAL_BAND_NOTE}:"
                    f"{'/'.join(str(value) for value in old_red_cells)}->"
                    f"{'/'.join(str(value) for value in new_red_cells)}"
                ]
            )
        ),
    )


def _aisha_red_room_reweighted_combos(
    combos: list[RefCombo],
    *,
    hero_key: str,
    round_no: int | None,
    evidence: RefEvidence,
    probs: dict[str, float],
    geom_capacity: float | None,
    notes: list[str],
    non_red_pinned_cells: float | None = None,
) -> list[RefCombo]:
    """Aisha pure-prior red: soft-reweight combos by how well their red CELLS fit the geometric room.

    Red is invisible to Aisha, so its per-vault count comes from the flat map prior and over-states a
    tight low-red vault (eval: low-red +424k). The room = a RED-INDEPENDENT capacity (layout geometry
    total_grid_target, NOT the combo total_grid which already bakes in red -> circular) minus the
    estimated non-red cells. Combos whose red overshoots min(room, map-tier expected red x slack) are
    exponentially down-weighted, trimming the false-positive red without a hard cut. The map-tier
    factor keeps low-tier maps (P(q6) tiny -> empty space is NOT red) from reading空 as red room.

    Strictly isolated: aisha only, pure-prior red only (never touches a revealed/locked red -> keeps
    _is_pure_prior_red input unchanged, so the value cap stays armed), decision rounds only. NEVER
    writes evidence. Rollback: BIDKING_DISABLE_AISHA_RED_ROOM=1.
    """
    if str(hero_key or "").strip().lower() != "aisha":
        return combos
    if os.environ.get("BIDKING_DISABLE_AISHA_RED_ROOM") == "1":
        return combos
    # Fully-pinned non-red (all four non-red tiers exact) makes red a hard grid residual — fire even
    # when a weak min_q6>=1 floor flips _is_pure_prior_red to False (the overcount is still prior).
    fully_pinned = non_red_pinned_cells is not None and float(non_red_pinned_cells) > 0
    if not combos or (not fully_pinned and not _is_pure_prior_red(evidence)):
        return combos
    if round_no is None or int(round_no) < _AISHA_RED_ROOM_MIN_ROUND:
        return combos
    if geom_capacity is None or float(geom_capacity) <= 0:
        return combos
    max_logw = max(combo.weight for combo in combos)
    weight_of = lambda combo: math.exp(max(-745.0, combo.weight - max_logw))  # noqa: E731
    if fully_pinned:
        # Exact pinned non-red cells (not the combo median, which the phantom red already inflates).
        non_red = float(non_red_pinned_cells)
    else:
        non_red = _weighted_quantile(
            [
                (sum(float(combo.grids.get(key, 0.0)) for key in QUALITY_KEYS if key != "q6"), weight_of(combo))
                for combo in combos
            ],
            0.5,
        )
    if non_red is None:
        return combos
    room = float(geom_capacity) - float(non_red)
    if room < _AISHA_RED_ROOM_MIN_ROOM and not fully_pinned:
        return combos
    if room > _AISHA_RED_ROOM_TIGHT_MAX and not fully_pinned:
        # Large room = a deep/rich vault where the geometric signal is reliable and red genuinely
        # fills space (high-red bucket, accurate at baseline). Only tight vaults (low-red's signature)
        # carry the false-positive red worth trimming -> don't touch large-room vaults (no high-red hit).
        # (Fully-pinned bypasses this: the residual IS the room, trusted at any size.)
        return combos
    if fully_pinned:
        # Red = layout_total − pinned_nonred, + slack for the layout's own error. Grid conservation,
        # not a tier-prior guess — the residual directly ceils red cells.
        red_cell_ceiling = max(0.0, room) + _AISHA_RED_ROOM_PINNED_SLACK
        # The inverse physical constraint matters on a large residual: if q1/q3/q4/q5 cells are all
        # exact, a red-count arm whose REAL catalog footprints cannot reach even the conservative
        # residual is not a plausible "empty room" interpretation. Keep 10 cells of layout slack and
        # penalise only the remaining shortfall. This is the fully-pinned counterpart to the existing
        # overshoot ceiling, not the disproven generic large-room richness lift.
        red_cell_floor = max(0.0, room - _AISHA_RED_ROOM_PINNED_FLOOR_SLACK)
    else:
        total_med = _weighted_quantile([(float(sum(combo.counts.values())), weight_of(combo)) for combo in combos], 0.5) or 0.0
        p6 = max(1e-9, float(probs.get("q6", 0.0)))
        tier_red_cells = total_med * p6 * _AISHA_RED_ROOM_RED_VOL * _AISHA_RED_ROOM_TIER_SLACK
        red_cell_ceiling = min(room, tier_red_cells)
    changed = False
    floor_changed = False
    out: list[RefCombo] = []
    for combo in combos:
        over = float(combo.grids.get("q6", 0.0)) - red_cell_ceiling
        under = 0.0
        if (
            fully_pinned
            and _run_env_get(AISHA_PINNED_RED_RESIDUAL_FLOOR_DISABLE) != "1"
            and red_cell_floor >= AISHA_PINNED_RED_RESIDUAL_VALUE_MIN_CELLS
        ):
            catalog_hi = _catalog_quality_grid_ceiling("q6", int(combo.counts.get("q6", 0)))
            under = max(0.0, red_cell_floor - float(catalog_hi or 0))
            floor_changed = floor_changed or under > 0
        if over > 0:
            changed = True
        if over > 0 or under > 0:
            out.append(
                replace(
                    combo,
                    weight=combo.weight - _AISHA_RED_ROOM_PENALTY * (over + under),
                )
            )
        else:
            out.append(combo)
    if changed:
        _append_source_note_once(
            notes, f"{AISHA_RED_ROOM_REWEIGHT_NOTE_PREFIX}cap{int(round(red_cell_ceiling))}_room{int(round(room))}"
        )
    if floor_changed:
        _append_source_note_once(
            notes,
            f"{AISHA_PINNED_RED_RESIDUAL_FLOOR_NOTE}:"
            f"{int(round(red_cell_floor))}_room{int(round(room))}",
        )
    return out


def _aisha_known_red_residual_value_targets(
    *,
    hero_key: str,
    evidence: RefEvidence,
    total_grid_range: tuple[int | None, int | None, int | None] | None,
    quality_cells_ranges: dict[str, tuple[int | None, int | None, int | None]],
) -> tuple[tuple[float, float, float], tuple[float, float, float]] | None:
    """Price only the hidden red mass left beyond correlated known red items.

    This is deliberately narrower than the rejected global grid-identity value pass.  When all
    non-red cells are fixed, the spatial total's remainder is red.  If exact revealed red items cover
    only part of that remainder, the extra cells must belong to hidden red items; they are not a size
    premium on the already-priced items.  The conservative target keeps only the known hard value,
    while the middle/high targets price the hidden residual at the family mean per-cell value.
    """
    if (
        hero_key != "aisha"
        or evidence.phase != "bidding"
        or _run_env_get(AISHA_KNOWN_RED_RESIDUAL_VALUE_DISABLE) == "1"
        or "q6" in (evidence.quality_count_cells_value_options or {})
        or _quality_exact_value("q6", evidence) is not None
        or not total_grid_range
        or len(total_grid_range) != 3
        or any(value is None for value in total_grid_range)
    ):
        return None

    # Aggregate floor counts can be equal while describing different physical items (one value-only
    # runtime and one footprint-only runtime).  Residual pricing may subtract only facts whose raw
    # rows correlate value and cells by runtime/local identity.  Catalog footprint minima remain
    # separate lower bounds and never become an exact known-price component here.
    known_facts = evidence.q6_known_item_facts
    if not known_facts:
        return None
    known_cells = float(sum(int(cells) for _, cells, _ in known_facts))
    known_value = float(sum(int(value) for _, _, value in known_facts))

    nonred_by_tier = [0.0, 0.0, 0.0]
    for key in ("q1", "q3", "q4", "q5"):
        band = quality_cells_ranges.get(key)
        if (
            not band
            or len(band) != 3
            or any(value is None for value in band)
            or int(band[0]) != int(band[1])
            or int(band[1]) != int(band[2])
        ):
            return None
        for index, value in enumerate(band):
            nonred_by_tier[index] += float(value)

    residual_cells = tuple(
        max(known_cells, float(total_grid_range[index]) - nonred_by_tier[index])
        for index in range(3)
    )
    if (
        residual_cells[1] < AISHA_PINNED_RED_RESIDUAL_VALUE_MIN_CELLS
        or residual_cells[1] <= known_cells + 0.5
    ):
        return None

    percell = _ethan_resid_red_percell(_ethan_map_family(evidence.map_id))
    targets = (
        known_value,
        known_value + max(0.0, residual_cells[1] - known_cells) * percell,
        known_value + max(0.0, residual_cells[2] - known_cells) * percell,
    )
    return residual_cells, targets


def _high_tier_floor_extra(
    snapshot: dict[str, Any],
    evidence: "RefEvidence",
    notes: list[str],
) -> tuple[float, int]:
    """Residual count-anchor correction for a publicly-revealed LARGE high-tier item.

    A revealed big q5/q6 item (e.g. a 16-cell red car from 巨物抽样) contributes a public
    `cell_floor` that is NOT an exact pin. The residual count-anchor below only subtracts
    `_exact_integer_quality_cell` tiers from the grid before dividing by the per-item average, so
    the big item's cells stay in the residual and get counted as ~floor/per_item PHANTOM items (a
    16-cell red -> ~6 items) -> total count inflated -> q5/q6 over-packed -> combos collapse to 3
    -> band collapses + red value locked high (observed: 2405 R3, total 49 vs truth ~43).

    Fix: deduct that floor from the residual and refill the tier's `min_count` (the big item is ~1
    item, not floor/per_item). Returns (cells_to_deduct, min_items_to_refill).

    GATED to the bug trigger so R4 / normal samples stay byte-identical: fires only when q5 cells
    are UNKNOWN (not exact-pinned) -- once q5 cells are pinned the residual already absorbs the
    high-tier cells correctly and deducting again would over-shrink. Default ON; rollback
    AISHA_DISABLE_Q5FIX=1.
    """
    if os.environ.get("AISHA_DISABLE_Q5FIX") == "1":
        return 0.0, 0
    # Per-tier q6 extension (2026-06-29, live 5605 gabriela R3/R4): the legacy function-level
    # gate below (early-return when q5 is exact-pinned) correctly prevents double-deducting q5,
    # but it ALSO disabled the q6 floor deduction. A vault can have q5 EXACTLY pinned (public
    # 1x1 gold -> quality_cells.q5=1.0) yet still carry a revealed LARGE red (q6 cell_floor=16,
    # q6 NOT exact) whose 16 cells then stayed in the residual and got divided by per_item (~2.5)
    # into ~6 phantom reds, inflating total_count (52 vs truth 34) and q6 (8 vs truth 5). The
    # per-tier `continue` inside the loop already skips a pinned tier, so the q6 deduction is
    # safe even when q5 is pinned. DEFAULT ON (2026-06-29): A/B test confirmed incremental value
    # on top of the draw_hero_count_boost informed-center guard (5605 center 50->41 -> q6 8->7,
    # balanced 1.46M->1.27M at R3) with no regression. The boost guard must be ON for this to
    # surface. Rollback AISHA_DISABLE_Q6FLOOR_DEDUCT=1.
    enable_q6_floor_deduct = os.environ.get("AISHA_DISABLE_Q6FLOOR_DEDUCT") != "1"
    # Gate: q5 cells known (e.g. R4 pins q5=14) -> residual already correct, do not double-deduct.
    if _exact_integer_quality_cell(evidence.quality_cells.get("q5")) is not None and not enable_q6_floor_deduct:
        return 0.0, 0
    try:
        _counts, cell_floors, _value_floors = _public_quality_reveal_floors(snapshot)
    except Exception:
        return 0.0, 0
    extra_cells = 0.0
    extra_items = 0
    for tier in ("q5", "q6"):
        floor = cell_floors.get(tier)
        if not floor or float(floor) <= 0:
            continue
        if _exact_integer_quality_cell(evidence.quality_cells.get(tier)) is not None:
            continue  # this tier's cells are pinned -> already correctly subtracted
        min_items = int(evidence.min_counts.get(tier, 1) or 1)
        extra_cells += float(floor)
        extra_items += min_items
        notes.append(f"aisha_q5fix_hightier_floor:{tier}:{int(float(floor))}cells+{min_items}item")
    return extra_cells, extra_items


# CANDIDATE (default OFF; env AISHA_ENABLE_TOTAL_AVG_GRID_CLAMP=1 to enable). Author intent:
# during bidding the engine grid estimate is PRIMARY, but must not VIOLATE the public 总均格
# feasible band. Public 总均格 (200014) + the count range give total_cells ∈ [avg×count_lo,
# avg×count_hi]; clamp the grid range into that band (range constraint, NOT a point-lock).
# Motivation: faithful replay shows 总均格 is present from R1 but never constrains grid during
# bidding (the hard/soft lock is gated on count-known / post-settlement), so the engine grid
# often UNDER-shoots (31-sample batch: engine grid MAPE 7.7% vs 总均格×count 3.4%). This clamp
# fills that gap. STRICT NO-OP when 总均格 absent (>93% of samples) or count range unusable.
# Downstream count/value coupling is intentionally NOT re-fed here — measured via faithful A/B.
AISHA_ENABLE_TOTAL_AVG_GRID_CLAMP = "AISHA_ENABLE_TOTAL_AVG_GRID_CLAMP"


def _apply_total_avg_cells_grid_feasibility(
    total_grid_range: tuple[int | None, int | None, int | None],
    notes: list[str],
    *,
    total_avg_cells: float | None,
    quality_count_ranges: dict[str, tuple[int | None, int | None, int | None]],
) -> tuple[int | None, int | None, int | None]:
    """Clamp the grid range into the public-总均格 feasible band [avg×count_lo, avg×count_hi].
    No-op if 总均格 absent, count range unusable, or the range already lies inside the band."""
    if not total_avg_cells or total_avg_cells <= 0:
        return total_grid_range
    lo_sum = hi_sum = 0
    saw = False
    for rng in quality_count_ranges.values():
        if not rng:
            continue
        c_lo, _c_mid, c_hi = rng
        if c_lo is not None:
            lo_sum += int(c_lo); saw = True
        if c_hi is not None:
            hi_sum += int(c_hi); saw = True
    if not saw or hi_sum <= 0 or lo_sum > hi_sum:
        return total_grid_range
    band_lo = int(round(total_avg_cells * lo_sum))
    band_hi = int(round(total_avg_cells * hi_sum))
    if band_lo > band_hi:
        band_lo, band_hi = band_hi, band_lo
    g_lo, g_mid, g_hi = total_grid_range

    def _clamp(v: int | None) -> int | None:
        if v is None:
            return None
        return min(max(int(v), band_lo), band_hi)

    new = (_clamp(g_lo), _clamp(g_mid), _clamp(g_hi))
    # keep monotonic lo<=mid<=hi after clamping
    vals = [x for x in new if x is not None]
    if vals and new != total_grid_range:
        lo, mid, hi = new
        if lo is not None and mid is not None and lo > mid:
            lo = mid
        if hi is not None and mid is not None and hi < mid:
            hi = mid
        new = (lo, mid, hi)
        notes.append(
            f"total_avg_cells_grid_feasibility_clamp:{band_lo}-{band_hi}"
            f":{total_grid_range}->{new}"
        )
        return new
    return total_grid_range


