def _is_shipwreck_map(map_id: Any) -> bool:
    if map_id is None:
        return False
    try:
        m = int(map_id)
    except (TypeError, ValueError):
        return False
    # 25xx/35xx/45xx are all shipwreck (matches _ethan_map_family + monitor._map_family_from_id
    # prefix 25/35/45). 35xx (cat 201, e.g. 3501-3520 in maps.json) was MISSING here — an audit-found
    # consistency bug (2026-07-06) that would have skipped the activity boost on 35xx activity ids.
    return 2500 <= m < 2600 or 3500 <= m < 3600 or 4500 <= m < 4600


def _is_activity_shipwreck_map(map_id: Any) -> bool:
    """Activity-exclusive shipwreck map numbers X511-X520 (2511-2520 / 4511-4520). Census (2026-07-06):
    zero pre-activity samples for any of these ids; settled red rate 12.1% vs normal X501-X510 7.3%.
    Normal wreckage (X501-X510) and the older X531+ ships are NOT activity even during the window."""
    if not _is_shipwreck_map(map_id):
        return False
    lo = int(map_id) % 100
    return 11 <= lo <= 20


def _is_red_crate_activity_shipwreck_map(map_id: Any) -> bool:
    """2026-07-16 red-crate activity blocks, kept separate from X511-X520."""
    if not _is_shipwreck_map(map_id):
        return False
    try:
        mid = int(map_id)
    except (TypeError, ValueError):
        return False
    return 2541 <= mid <= 2550 or 4541 <= mid <= 4550


def _is_current_activity_shipwreck_map(map_id: Any) -> bool:
    """Return whether a stable source map id belongs to the 2026-07-30 event."""

    if type(map_id) is int:  # noqa: E721 - reject bool/subclass protocol hooks
        mid = map_id
    elif (
        type(map_id) is str  # noqa: E721 - accept the plain wire spelling only
        and len(map_id) == 4
        and map_id.isascii()
        and map_id.isdecimal()
    ):
        mid = int(map_id)
    else:
        return False
    return 2521 <= mid <= 2530 or 4521 <= mid <= 4530


def _is_collection_activity_shipwreck_map(map_id: Any) -> bool:
    """Return the exact 2026-08-13 collection-activity cohort.

    The updated game's ``ActivityMap`` rows 10003 and 10103 bind
    ``ui_activity_desc3`` (collectible-count probability up) to X531-X540 on
    the open and sealed shipwreck arms respectively.  This intentionally does
    not infer any future reserved block: ordinary maps, 35xx hero activities,
    and all other unknown ids remain outside the temporary overlay.
    """

    status, mid = _current_activity_map_scalar(map_id)
    if status == "invalid" or mid is None:
        return False
    return 2531 <= mid <= 2540 or 4531 <= mid <= 4540


def _current_activity_exact_dict_field(
    container: Any,
    name: str,
) -> tuple[str, Any]:
    """Read one exact-string field without invoking mapping or key protocols."""

    if type(container) is not dict:  # noqa: E721 - external container boundary
        return "invalid", _CURRENT_ACTIVITY_MAP_FIELD_MISSING
    found = _CURRENT_ACTIVITY_MAP_FIELD_MISSING
    for key, value in dict.items(container):
        if type(key) is not str:  # noqa: E721 - reject collision/subclass keys
            return "invalid", _CURRENT_ACTIVITY_MAP_FIELD_MISSING
        if str.__eq__(key, name):
            found = value
    if found is _CURRENT_ACTIVITY_MAP_FIELD_MISSING:
        return "absent", found
    return "present", found


