def _update606_changed_route_map_value(
    value: Any,
) -> tuple[str, int | None]:
    """Read one exact four-digit map owner without broad coercion."""

    if type(value) is int:  # noqa: E721 - bool/subclasses are not wire ids
        if 1_000 <= value <= 9_999:
            return "present", value
        return "invalid", None
    if (
        type(value) is str  # noqa: E721 - accept only the plain wire spelling
        and len(value) == 4
        and value.isascii()
        and value.isdecimal()
    ):
        return "present", int(value)
    if type(value) is str:  # noqa: E721 - JSON builtin aliases only
        projected = _safe_int(value)
        if projected in UPDATE606_CHANGED_ROUTE_MAP_IDS:
            return "invalid_target", projected
    # Invalid builtin subclasses must never reach the legacy coercive parser.
    # Read only their base payload, without invoking overridden conversion or
    # comparison hooks, so a disguised changed id still quarantines the call.
    if isinstance(value, int):
        for map_id in UPDATE606_CHANGED_ROUTE_MAP_IDS:
            if int.__eq__(value, map_id) is True:
                return "invalid_target", map_id
    if isinstance(value, str):
        for map_id in UPDATE606_CHANGED_ROUTE_MAP_IDS:
            if str.__eq__(value, str(map_id)) is True:
                return "invalid_target", map_id
    if isinstance(value, float):
        try:
            numerator, denominator = float.as_integer_ratio(value)
        except (OverflowError, ValueError):
            return "invalid", None
        if denominator == 1 and numerator in UPDATE606_CHANGED_ROUTE_MAP_IDS:
            return "invalid_target", numerator
        # A finite fractional value is never a valid map owner.  Preserve the
        # negative authority target when the legacy downstream ``int``
        # projection would nevertheless alias it onto a changed route, so the
        # route gate can fail closed before that coercive fallback is reached.
        projected = (
            numerator // denominator
            if numerator >= 0
            else -((-numerator) // denominator)
        )
        if projected in UPDATE606_CHANGED_ROUTE_MAP_IDS:
            return "invalid_target", projected
    return "invalid", None


def _update606_changed_route_reason(map_id: int) -> str | None:
    for candidate, reason in UPDATE606_CHANGED_ROUTE_REASON_BY_MAP:
        if candidate == map_id:
            return reason
    return None


def _update606_changed_route_dict_field(
    container: Any,
    name: str,
) -> tuple[str, Any, bool]:
    """Read an underlying dict slot and flag every non-exact container/key."""

    if type(container) is dict:  # noqa: E721 - ordinary JSON object
        status, value = _current_activity_exact_dict_field(container, name)
        return status, value, status == "invalid"
    if not isinstance(container, dict):
        return "invalid", _CURRENT_ACTIVITY_MAP_FIELD_MISSING, True
    found = _CURRENT_ACTIVITY_MAP_FIELD_MISSING
    invalid = True
    for key, value in dict.items(container):
        if type(key) is not str:  # noqa: E721 - no key coercion
            continue
        if str.__eq__(key, name):
            found = value
    if found is _CURRENT_ACTIVITY_MAP_FIELD_MISSING:
        return "absent", found, invalid
    return "present", found, invalid


SHIPWRECK_CALIBRATED_RELATIVE = "data/processed/shipwreck_calibrated_b049.json"
SHIPWRECK_CALIBRATED_BYTES = 2039
SHIPWRECK_CALIBRATED_SHA256 = "0e9a3400aef9a057ccea16494fd57bf52716edbcace80c46cfce7e073da2edee"
SHIPWRECK_PARAMETER_GENERATION = "b049c3-2026-09-10-597"
# Raw catalog-valued settlement parameters must not use the fitted-price ratio.
# Each of the ten unchanged 2501..2510 economic peers yields this same ratio:
# 282293.9971958062 / 299986.51032494527, after the new 675-item support.
# Count/quality/cell parameters remain historical empirical estimates; neither
# this transfer nor the unchanged route proves current-season accuracy.
SHIPWRECK_036_RAW_Q6_CATALOG_SCALE = 0.9410223042697001


def _shipwreck_calibrated_model(map_id: int, *, generation: str = SHIPWRECK_PARAMETER_GENERATION) -> dict[str, Any] | None:
    if type(map_id) is not int or map_id not in (2511,4511):
        return None
    if type(generation) is not str or generation not in (SHIPWRECK_PARAMETER_GENERATION, "76b7ca-2026-10-08-723"):
        return None
    try:
        raw=_aisha_q5_total_cells_plaintext_bytes(ROOT / SHIPWRECK_CALIBRATED_RELATIVE)
        if (len(raw),hashlib.sha256(raw).hexdigest()) != (SHIPWRECK_CALIBRATED_BYTES,SHIPWRECK_CALIBRATED_SHA256):
            return None
        document=json.loads(raw)
        if document['schema']!='shipwreck_calibrated_b049_v1' or document['generation']!='b049c3-2026-09-10-597':
            return None
        model=dict(document['maps'][str(map_id)])
        model.update(schema=document['schema'],generation=document['generation'],input_sha256=document['input_sha256'],
            split_policy_sha256=document['split_policy_sha256'],qualification=document['qualification'],
            model_sha256=SHIPWRECK_CALIBRATED_SHA256,official_distribution_authority=False,replay_eligible=False,tuning_pool_eligible=False)
        if generation != SHIPWRECK_PARAMETER_GENERATION:
            if _current_rankmap_distribution_generation_status() != ("ok", generation):
                return None
            # Verify current plaintext before any warmed quote can reuse this
            # transfer, including catalog geometry/value changes or loss of K.
            for relative, expected in _AISHA_Q5_TOTAL_CELLS_GENERATION_FILES.items():
                if relative in _CURRENT_RANKMAP_GENERATION_FILES:
                    continue  # Already checked by this call's common authority.
                current_raw = _aisha_q5_total_cells_plaintext_bytes(ROOT / relative)
                if (len(current_raw), hashlib.sha256(current_raw).hexdigest()) != expected:
                    return None
            model['quality_values'] = dict(model['quality_values'])
            model['quality_values']['q6'] *= SHIPWRECK_036_RAW_Q6_CATALOG_SCALE
            model.update(
                schema='shipwreck_calibrated_transfer_036_v1', generation=generation,
                parameter_generation=SHIPWRECK_PARAMETER_GENERATION,
                quality_value_scales={'q6': SHIPWRECK_036_RAW_Q6_CATALOG_SCALE},
                reference_peer_ids=list(range(2501, 2511)),
                transfer_policy='unchanged_route_historical_count_quality_cells; current_raw_q6_catalog_ratio',
                current_input_sha256={path: pin[1] for path, pin in _AISHA_Q5_TOTAL_CELLS_GENERATION_FILES.items()},
                qualification=model['qualification'] + '; current-generation algorithm transfer, not current-season training',
            )
        return model
    except Exception:  # noqa: BLE001 - unavailable or changed calibration cannot borrow a legacy prior
        return None


def _reference_input_check_context(function):
    """Share fresh checks only within one outer call, never across snapshots."""
    @wraps(function)
    def run(*args, **kwargs):
        if _REFERENCE_INPUT_CHECKS.get() is not None:
            return function(*args, **kwargs)
        token = _REFERENCE_INPUT_CHECKS.set({})
        try:
            return function(*args, **kwargs)
        finally:
            _REFERENCE_INPUT_CHECKS.reset(token)
    return run


def _shipwreck_calibrated_context(function):
    """Bind a qualified empirical prior only during this ordinary engine call."""
    @wraps(function)
    def run(snapshot, *args, **kwargs):
        target=None
        prior_route = (
            _wuqilin_5215_pending_scope_state(snapshot) is not None
            or _update606_large_auction_pending_scope_state(snapshot) is not None
            or _chenmei_zhenhai_pending_scope_state(snapshot) is not None
            or _current_rankmap_authority_scope_state(snapshot) is not None
        )
        if type(snapshot) is dict and not prior_route:
            ui=dict.get(snapshot,'ui_contract');context=dict.get(ui,'context') if type(ui) is dict else None
            for owner in (snapshot,context):
                if type(owner) is dict:
                    raw=dict.get(owner,'map_id')
                    if type(raw) in (int,str) and raw in (2511,4511,'2511','4511'):
                        target=int(raw);break
        prior=None
        if target is not None:
            state=_shipwreck_calibrated_scope_state(snapshot,target)
            if state!='ok':
                result=_update606_changed_route_pending_result(state,target)
                return replace(result,notes=result.notes+(f'shipwreck_calibrated_unavailable:{state}',))
            prior=_shipwreck_calibrated_model(target, generation=CURRENT_RANKMAP_PACKAGE_GENERATION)
            if prior is None:
                result=_update606_changed_route_pending_result('calibration_input_unavailable',target)
                return replace(result,notes=result.notes+('shipwreck_calibrated_unavailable:calibration_input_unavailable',))
        token=_SHIPWRECK_CALIBRATED_PRIOR.set(prior)
        try:
            result=function(snapshot,*args,**kwargs)
            if prior is not None and result.balanced is not None:
                metadata={key:prior[key] for key in ('schema','generation','map_id','candidate_sha256','input_sha256',
                    'split_policy_sha256','model_sha256','train_sessions','count_mean','count_sd','quality_probs',
                    'quality_values','quality_cells','qualification','official_distribution_authority','replay_eligible','tuning_pool_eligible')}
                metadata.update({key: prior[key] for key in ('parameter_generation', 'quality_value_scales',
                    'reference_peer_ids', 'transfer_policy', 'current_input_sha256') if key in prior})
                result=replace(result,empirical_calibration=metadata,provisional_quote={})
            return result
        finally:
            _SHIPWRECK_CALIBRATED_PRIOR.reset(token)
    return _reference_input_check_context(run)


def _shipwreck_calibrated_scope_state(snapshot: Any, map_id: int) -> str:
    """Validate every current raw owner; absence of a PW2 owner is NOT official.

    This is deliberately not cached: a newly arrived owner/conflict/version
    declaration must revoke an earlier quote in the same session.
    """
    root = _exact_warehouse_quote_source_dict(snapshot)
    if root is None:
        return "invalid_owner"
    owners = [root]
    if "ui_contract" in root:
        ui = _exact_warehouse_quote_source_dict(root["ui_contract"])
        if ui is None:
            return "invalid_owner"
        for key in ("context", "source"):
            if key in ui:
                owner = _exact_warehouse_quote_source_dict(ui[key])
                if owner is None:
                    return "invalid_owner"
                owners.append(owner)
    maps, sessions, phases, stable = [], [], [], []
    epochs: dict[str,list[Any]] = {}
    sources = []
    generation = CURRENT_RANKMAP_PACKAGE_GENERATION
    build = {SHIPWRECK_PARAMETER_GENERATION: "25221911", "76b7ca-2026-10-08-723": "25795126"}.get(generation)
    if build is None:
        return "generation_conflict"
    for owner in owners:
        for key in ('epoch','session_epoch'):
            if key in owner:
                epochs.setdefault(key,[]).append(owner[key])
        for key, target in (("map_id", maps), ("session_id", sessions), ("phase", phases),
                            ("warehouse_game_version_session_stable", stable)):
            if key in owner:
                target.append(owner[key])
        if "warehouse_source" in owner:
            sources.append(owner["warehouse_source"])
        if "model_map_id" in owner and owner["model_map_id"] is not None and (
            type(owner["model_map_id"]) is not int or owner["model_map_id"] != map_id
        ):
            return "map_alias_conflict"
        if owner.get("map_alias") or owner.get("map_alias_mode"):
            return "map_alias_conflict"
        for key, expected in (("warehouse_source_generation", generation),
            ("warehouse_source_qualification", "postupdate_unknown_warehouse_source" if map_id==2511 else "official_random_warehouse"),
            ("official_distribution_eligible", map_id==4511)):
            if key in owner and (type(owner[key]) is not type(expected) or owner[key] != expected):
                return "source_alias_conflict"
        if type(owner.get("formal_mode_reason")) is str and owner["formal_mode_reason"] == "game_generation_unverified":
            return "game_generation_unverified"
    if not maps or any(type(value) not in (int, str) or value not in (map_id, str(map_id)) for value in maps):
        return "map_conflict"
    if not sessions or any(type(value) is not str or not value.startswith(f"{map_id}:")
        or not value[5:].isascii() or not value[5:].isdecimal() or value != sessions[0] for value in sessions):
        return "session_conflict"
    tail = sessions[0][5:]
    if len(tail) > 20 or not re.fullmatch(r"[1-9][0-9]*", tail) or int(tail) > 2**64 - 1:
        return "session_conflict"
    if not phases or any(type(value) is not str or value not in ("reading", "bidding") or value != phases[0] for value in phases):
        return "not_live_pre_settlement"
    if not stable or any(value is not True for value in stable):
        return "session_generation_unverified"
    for values in epochs.values():
        if any(not ((type(value) is int and 0 < value <= 2**64 - 1 and value == int(tail))
                    or (type(value) is str and value == tail)) for value in values):
            return "epoch_conflict"
    expected = {
        "qualification": "postupdate_unknown_warehouse_source" if map_id==2511 else "official_random_warehouse",
        "reason": "pw2_open_owner_block_absent" if map_id==2511 else "pw2_sealed_owner_block_absent",
        "map_id": map_id, "table_status": "verified", "explicit_source": "",
        "source_generation": generation, "map_profile_generation": generation, "game_version": generation,
        "map_table_build": build, "auction_mode": "open" if map_id==2511 else "sealed", "owner_evidence_status": "absent",
        "source_conflict": False, "quarantine_required": False, "official_distribution_eligible": map_id==4511,
        "parser_replay_eligible": True, "quote_policy": "advisory_only_no_clamp",
        "map_table_sha256": "7abe97f33ec48c8b18887de5abcddc1969b5decc2b9be30b1f8fd73f5b71c9fc",
        "expected_map_table_sha256": "7abe97f33ec48c8b18887de5abcddc1969b5decc2b9be30b1f8fd73f5b71c9fc",
        "map_source_contract_sha256": "b6e0635f8033bb20dbac7a6c6a985fe5bd4d923da1bf9a2d3d21dd524273a6f3",
        "expected_map_source_contract_sha256": "b6e0635f8033bb20dbac7a6c6a985fe5bd4d923da1bf9a2d3d21dd524273a6f3",
    }
    if not sources:
        return "source_missing"
    for value in sources:
        source = _exact_warehouse_quote_source_dict(value)
        if source is None or any(type(source.get(key)) is not type(want) or source.get(key) != want for key, want in expected.items()):
            return "source_conflict"
        if source.get('config') is not None:
            return "source_conflict"
    return "ok" if _shipwreck_calibrated_model(map_id, generation=generation) is not None else "calibration_input_unavailable"


def _activity_2511_provisional_scope_state(snapshot: Any) -> str:
    """Compatibility name for older panel revocation callers; no old sidecar read."""
    return _shipwreck_calibrated_scope_state(snapshot,2511)


def _update606_changed_route_scope_state(
    snapshot: Any,
) -> tuple[str, int | None] | None:
    """Quarantine exact update606 route drift before any quote fallback.

    The generation-bound package contract proves only that these BidMap route
    cells changed and that same-generation derived outputs exclude them.  It
    does not authorize carrying legacy Drop weights across the route change.
    """

    root_status, root_value, root_invalid = _update606_changed_route_dict_field(
        snapshot, "map_id"
    )
    ui_status, ui_contract, ui_invalid = _update606_changed_route_dict_field(
        snapshot, "ui_contract"
    )
    context_status = "absent"
    context_value = _CURRENT_ACTIVITY_MAP_FIELD_MISSING
    invalid = root_invalid or ui_invalid
    if ui_status == "present":
        container_status, context, container_invalid = (
            _update606_changed_route_dict_field(ui_contract, "context")
        )
        invalid = invalid or container_invalid
        if container_status == "present":
            context_status, context_value, context_invalid = (
                _update606_changed_route_dict_field(context, "map_id")
            )
            invalid = invalid or context_invalid

    values: list[int] = []
    invalid = invalid or context_status == "invalid"
    for status, raw_value in (
        (root_status, root_value),
        (context_status, context_value),
    ):
        if status != "present":
            continue
        value_status, map_id = _update606_changed_route_map_value(raw_value)
        if value_status == "invalid_target" and map_id is not None:
            invalid = True
            values.append(map_id)
            continue
        if value_status != "present" or map_id is None:
            invalid = True
            continue
        values.append(map_id)

    changed_values = [
        map_id
        for map_id in values
        if _update606_changed_route_reason(map_id) is not None
    ]
    if not changed_values:
        return None
    target = changed_values[0]
    if invalid or any(map_id != target for map_id in values):
        return "map_conflict", target
    if target in (2511,4511) and _shipwreck_calibrated_scope_state(snapshot,target) == "ok":
        return None
    if (
        target in CURRENT_RANKMAP_CHANGED_ROUTE_MAP_IDS
        and _current_rankmap_distribution_generation_status()[0] == "ok"
    ):
        return None
    return "no_approved_distribution", target


def _current_rankmap_map_value(value: Any) -> tuple[str, int | None]:
    """Read one target map id without permitting coercive aliases."""

    if type(value) is int:  # noqa: E721
        return ("present", value) if 1_000 <= value <= 9_999 else ("invalid", None)
    if (
        type(value) is str  # noqa: E721
        and len(value) == 4
        and value.isascii()
        and value.isdecimal()
    ):
        return "present", int(value)
    if type(value) is str:  # noqa: E721
        projected = _safe_int(value)
        if projected in CURRENT_MODEL_AUTHORITY_MAP_IDS:
            return "invalid_target", projected
    if isinstance(value, int):
        for map_id in CURRENT_MODEL_AUTHORITY_MAP_IDS:
            if int.__eq__(value, map_id) is True:
                return "invalid_target", map_id
    if isinstance(value, str):
        for map_id in CURRENT_MODEL_AUTHORITY_MAP_IDS:
            if str.__eq__(value, str(map_id)) is True:
                return "invalid_target", map_id
    if isinstance(value, float):
        try:
            numerator, denominator = float.as_integer_ratio(value)
        except (OverflowError, ValueError):
            return "invalid", None
        projected = (
            numerator // denominator
            if numerator >= 0
            else -((-numerator) // denominator)
        )
        if projected in CURRENT_MODEL_AUTHORITY_MAP_IDS:
            return "invalid_target", projected
    return "invalid", None


def _current_rankmap_authority_scope_state(
    snapshot: Any,
) -> tuple[str, int | None] | None:
    """Require the current profile on its 112 ordinary/ranked physical maps."""

    root_status, root_value, root_invalid = _update606_changed_route_dict_field(
        snapshot, "map_id"
    )
    ui_status, ui_contract, ui_invalid = _update606_changed_route_dict_field(
        snapshot, "ui_contract"
    )
    context_status = "absent"
    context_value = _CURRENT_ACTIVITY_MAP_FIELD_MISSING
    invalid = root_invalid or ui_invalid
    if ui_status == "present":
        container_status, context, container_invalid = (
            _update606_changed_route_dict_field(ui_contract, "context")
        )
        invalid = invalid or container_invalid
        if container_status == "present":
            context_status, context_value, context_invalid = (
                _update606_changed_route_dict_field(context, "map_id")
            )
            invalid = invalid or context_invalid
    values: list[int] = []
    invalid = invalid or context_status == "invalid"
    for status, raw_value in (
        (root_status, root_value),
        (context_status, context_value),
    ):
        if status != "present":
            continue
        value_status, map_id = _current_rankmap_map_value(raw_value)
        if value_status == "invalid_target" and map_id is not None:
            invalid = True
            values.append(map_id)
            continue
        if value_status != "present" or map_id is None:
            invalid = True
            continue
        values.append(map_id)
    targets = [map_id for map_id in values if map_id in CURRENT_MODEL_AUTHORITY_MAP_IDS]
    if not targets:
        return None
    target = targets[0]
    if invalid or any(map_id != target for map_id in values):
        return "map_conflict", target
    status, _generation = _current_rankmap_distribution_generation_status()
    if status != "ok":
        return status, target
    status, _baseline = _aisha_q5_total_cells_catalog_generation_status()
    if status != "ok":
        return status, target
    return None


def _wuqilin_5215_pending_scope_state(snapshot: Any) -> str | None:
    """Select the dedicated 5215 boundary before generic special-pool fallback.

    This target detector grants no source authority. Raw malformed aliases also
    reach the dedicated boundary, which validates them before quoting.
    """
    owners = [snapshot]
    status, ui, invalid = _update606_changed_route_dict_field(snapshot, "ui_contract")
    if status == "present":
        status, context, bad = _update606_changed_route_dict_field(ui, "context")
        invalid = invalid or bad
        if status == "present":
            owners.append(context)
    values = []
    for owner in owners:
        status, raw, bad = _update606_changed_route_dict_field(owner, "map_id")
        invalid = invalid or bad
        if status != "present":
            continue
        value_status, value = _current_activity_map_scalar(raw)
        if value_status == "invalid":
            invalid = True
            # Only builtin payloads: never call arbitrary __int__/__str__.
            if isinstance(raw, int) and int.__eq__(raw, 5215) is True:
                value = 5215
            elif isinstance(raw, str):
                base = str.__str__(raw)
                if _safe_int(base) == 5215:
                    value = 5215
            elif isinstance(raw, float):
                try:
                    numerator, denominator = float.as_integer_ratio(raw)
                    if numerator // denominator == 5215:
                        value = 5215
                except (OverflowError, ValueError):
                    pass
        values.append(value)
    if 5215 not in values:
        return None
    if invalid or any(value != 5215 for value in values):
        return "map_conflict"
    return "scoped_model_target"


def _wuqilin_5215_pending_result(state: str) -> RefResult:
    return _update606_pending_result(
        extract_evidence({"map_id": 5215}),
        state,
        note_prefix="wuqilin_5215_adaptation_pending",
    )


def _wuqilin_5215_quote_result(snapshot: dict[str, Any], *, safety_factor: float | None) -> RefResult:
    import wuqilin_5215_quote_model as model

    state = model.scope_state(snapshot, expected_generation=CURRENT_RANKMAP_PACKAGE_GENERATION)
    if state != "ok":
        return _wuqilin_5215_pending_result(state)
    try:
        # Input bytes are checked before the result cache; a changed/missing
        # model input immediately revokes previously valid same-session quotes.
        model.load_model(lambda relative: _aisha_q5_total_cells_plaintext_bytes(ROOT / relative),
                         generation=CURRENT_RANKMAP_PACKAGE_GENERATION)
        key = json.dumps(snapshot, ensure_ascii=False, sort_keys=True, allow_nan=False)
        return _wuqilin_5215_cached_quote(key, safety_factor)
    except (model.ModelInputError, TypeError, ValueError) as error:
        return _wuqilin_5215_pending_result(str(error))


@lru_cache(maxsize=32)
def _wuqilin_5215_cached_quote(snapshot_json: str, safety_factor: float | None) -> RefResult:
    import wuqilin_5215_quote_model as model

    snapshot = json.loads(snapshot_json)
    evidence = extract_evidence(snapshot)
    peers = model.load_model(lambda relative: _aisha_q5_total_cells_plaintext_bytes(ROOT / relative),
                             generation=CURRENT_RANKMAP_PACKAGE_GENERATION)
    antique_count, observed = model.observations(snapshot, _iter_skill_reveal_dict_rows(snapshot), evidence.physical_candidate_domains)
    try:
        posterior = model.posterior(peers, evidence, antique_count, observed)
    except model.ModelInputError as error:
        if str(error) != 'posterior_sampling_exhausted_for_constraints':
            raise
        # One bounded deeper pass for rare hard cell constraints. Exhaustion
        # remains an input/support limitation, not proof of mathematical conflict.
        posterior = model.posterior(peers, evidence, antique_count, observed, draws=65536)
    value_range = posterior['value_range']
    multipliers = quote_safety_multipliers(0.85 if safety_factor is None else safety_factor)
    quotes = [int(round(value * multiplier)) for value, multiplier in zip(value_range, multipliers)]
    quotes[1] = max(quotes[:2])
    quotes[2] = max(quotes)
    metadata = {key: list(value) if isinstance(value, tuple) else value for key, value in posterior.items() if key not in
                ('value_range', 'quality_count_ranges', 'quality_cells_ranges', 'red_value_range', 'total_grid_range',
                 'quality_count_candidates','quality_cells_candidates','quality_count_cells_candidates','quality_count_arms','quality_lock')}
    metadata.update(schema=model.MODEL_VERSION, map_id=5215, model_map_id=5215,
                    official_distribution_authority=False, reference_peer_ids=list(range(2501, 2511)),
                    generation=CURRENT_RANKMAP_PACKAGE_GENERATION,
                    parameter_generation=model.GENERATION,
                    transfer_qualification='unchanged_5215_route; current_catalog_and_peer_values; historical_count_prior',
                    input_sha256={key: value[1] for key, value in model.input_profile(CURRENT_RANKMAP_PACKAGE_GENERATION).items()})
    return RefResult(
        status='provisional_estimated', source=model.MODEL_VERSION,
        conservative=quotes[0], balanced=quotes[1], aggressive=quotes[2],
        value_p25=value_range[0], value_p50=value_range[1], value_p75=value_range[2],
        combo_count=posterior['accepted_draws'],
        red_count_range=posterior['quality_count_ranges']['q6'],
        red_cells_range=posterior['quality_cells_ranges']['q6'],
        red_value_range=posterior['red_value_range'],
        quality_count_ranges=posterior['quality_count_ranges'],
        quality_cells_ranges=posterior['quality_cells_ranges'],
        total_grid_range=posterior['total_grid_range'],
        notes=tuple(evidence.source_notes) + ('wuqilin_5215_algorithm_estimate',),
        evidence=evidence, provisional_quote=metadata,
        quality_count_candidates=posterior['quality_count_candidates'],
        quality_cells_candidates=posterior['quality_cells_candidates'],
        quality_count_cells_candidates=posterior['quality_count_cells_candidates'],
        quality_count_arms=posterior['quality_count_arms'],quality_lock=posterior['quality_lock'],
    )


def _chenmei_zhenhai_pending_scope_state(snapshot: Any) -> str | None:
    """Fail closed when either raw owner identifies locked map 5506.

    This consumes only the exact root/context JSON shape.  It intentionally
    does not inspect the campaign window: the observed activity schedule is
    not evidence that the map itself has opened or that its bid rules are
    known.  An absent 5506 id leaves every existing map untouched.
    """

    root_map_status, root_map_value = _current_activity_exact_dict_field(
        snapshot, "map_id"
    )
    root_hero_status, root_hero_value = _current_activity_exact_dict_field(
        snapshot, "hero"
    )
    ui_status, ui_contract = _current_activity_exact_dict_field(
        snapshot, "ui_contract"
    )
    context_map_status = "absent"
    context_map_value = _CURRENT_ACTIVITY_MAP_FIELD_MISSING
    context_hero_status = "absent"
    context_hero_value = _CURRENT_ACTIVITY_MAP_FIELD_MISSING
    ui_invalid = ui_status == "invalid"
    if ui_status == "present":
        if type(ui_contract) is not dict:  # noqa: E721 - no Mapping fallback
            ui_invalid = True
        else:
            context_status, context = _current_activity_exact_dict_field(
                ui_contract, "context"
            )
            if context_status == "invalid" or (
                context_status == "present" and type(context) is not dict
            ):
                ui_invalid = True
            elif context_status == "present":
                context_map_status, context_map_value = (
                    _current_activity_exact_dict_field(context, "map_id")
                )
                context_hero_status, context_hero_value = (
                    _current_activity_exact_dict_field(context, "hero")
                )

    map_values: list[int] = []
    map_invalid = ui_invalid or root_map_status == "invalid" or (
        context_map_status == "invalid"
    )
    for status, raw_value in (
        (root_map_status, root_map_value),
        (context_map_status, context_map_value),
    ):
        if status != "present":
            continue
        value_status, map_id = _chenmei_zhenhai_pending_map_value(raw_value)
        if value_status != "present" or map_id is None:
            map_invalid = True
            continue
        map_values.append(map_id)

    if CHENMEI_ZHENHAI_PENDING_MAP_ID not in map_values:
        return None
    if map_invalid or any(
        map_id != CHENMEI_ZHENHAI_PENDING_MAP_ID for map_id in map_values
    ):
        return "map_conflict"

    hero_values: list[str] = []
    hero_invalid = root_hero_status == "invalid" or context_hero_status == "invalid"
    for status, raw_value in (
        (root_hero_status, root_hero_value),
        (context_hero_status, context_hero_value),
    ):
        if status == "absent":
            continue
        if status != "present":
            hero_invalid = True
            continue
        hero_values.append(_chenmei_zhenhai_pending_hero_value(raw_value))

    if hero_invalid or any(value != "chenmei" for value in hero_values):
        return "hero_conflict"
    if not hero_values:
        return "hero_missing"
    return "preopen"


_AUCTION_HALL_6001_RECEIPT_KEYS = (
    "schema_version",
    "status",
    "generation",
    "map_id",
    "drop_pool_id",
    "table_identity",
    "primary_scenario",
    "primary_support_items",
    "upper_envelope_scenario",
    "upper_envelope_items",
    "provisional_distribution_available",
    "provisional_quote_available",
    "distribution_authority",
    "official_quote_authority",
    "bid_mode",
    "confidence",
)


def _auction_hall_6001_plain_string_fields(
    value: Any,
    expected_keys: tuple[str, ...],
) -> dict[str, Any] | None:
    if type(value) is not dict:  # noqa: E721 - external boundary
        return None
    fields: dict[str, Any] = {}
    for key, field_value in dict.items(value):
        if type(key) is not str or key not in expected_keys:  # noqa: E721
            return None
        fields[key] = field_value
    if len(fields) != len(expected_keys):
        return None
    return fields


def _auction_hall_6001_canonical_receipt(value: Any) -> dict[str, Any] | None:
    fields = _auction_hall_6001_plain_string_fields(
        value,
        _AUCTION_HALL_6001_RECEIPT_KEYS,
    )
    if fields is None:
        return None
    identity = _auction_hall_6001_plain_string_fields(
        fields["table_identity"],
        ("bytes", "sha256"),
    )
    if identity is None:
        return None
    if (
        type(fields["schema_version"]) is not int  # noqa: E721
        or fields["schema_version"] != 1
        or type(fields["status"]) is not str  # noqa: E721
        or not str.__eq__(fields["status"], "provisional_estimated")
        or type(fields["generation"]) is not str  # noqa: E721
        or not str.__eq__(
            fields["generation"],
            AUCTION_HALL_6001_HISTORICAL_GENERATION,
        )
        or type(fields["map_id"]) is not int  # noqa: E721
        or fields["map_id"] != 6001
        or type(fields["drop_pool_id"]) is not int  # noqa: E721
        or fields["drop_pool_id"] != 2601
        or type(identity["bytes"]) is not int  # noqa: E721
        or identity["bytes"] != AUCTION_HALL_6001_SHADOW_BYTES
        or type(identity["sha256"]) is not str  # noqa: E721
        or not str.__eq__(identity["sha256"], AUCTION_HALL_6001_SHADOW_SHA256)
        or type(fields["primary_scenario"]) is not str  # noqa: E721
        or not str.__eq__(
            fields["primary_scenario"],
            AUCTION_HALL_6001_PRIMARY_SCENARIO,
        )
        or type(fields["primary_support_items"]) is not int  # noqa: E721
        or fields["primary_support_items"] != 673
        or type(fields["upper_envelope_scenario"]) is not str  # noqa: E721
        or not str.__eq__(
            fields["upper_envelope_scenario"],
            AUCTION_HALL_6001_UPPER_SCENARIO,
        )
        or type(fields["upper_envelope_items"]) is not int  # noqa: E721
        or fields["upper_envelope_items"] != 680
        or fields["provisional_distribution_available"] is not True
        or fields["provisional_quote_available"] is not True
        or fields["distribution_authority"] is not False
        or fields["official_quote_authority"] is not False
        or type(fields["bid_mode"]) is not str  # noqa: E721
        or not str.__eq__(fields["bid_mode"], "provisional_estimated_only")
        or type(fields["confidence"]) is not str  # noqa: E721
        or not str.__eq__(
            fields["confidence"],
            "weak_family_2601_generation_bound",
        )
    ):
        return None
    return {
        "schema_version": 1,
        "status": "provisional_estimated",
        "generation": AUCTION_HALL_6001_HISTORICAL_GENERATION,
        "map_id": 6001,
        "drop_pool_id": 2601,
        "table_identity": {
            "bytes": AUCTION_HALL_6001_SHADOW_BYTES,
            "sha256": AUCTION_HALL_6001_SHADOW_SHA256,
        },
        "primary_scenario": AUCTION_HALL_6001_PRIMARY_SCENARIO,
        "primary_support_items": 673,
        "upper_envelope_scenario": AUCTION_HALL_6001_UPPER_SCENARIO,
        "upper_envelope_items": 680,
        "provisional_distribution_available": True,
        "provisional_quote_available": True,
        "distribution_authority": False,
        "official_quote_authority": False,
        "bid_mode": "provisional_estimated_only",
        "confidence": "weak_family_2601_generation_bound",
    }


def _auction_hall_6001_receipt_shape(value: Any) -> bool:
    return _auction_hall_6001_canonical_receipt(value) is not None


def _auction_hall_6001_snapshot_receipt(
    snapshot: Any,
) -> tuple[str, dict[str, Any]]:
    root_status, root_value = _current_activity_exact_dict_field(
        snapshot,
        "auction_hall_6001_provisional",
    )
    ui_status, ui_contract = _current_activity_exact_dict_field(
        snapshot,
        "ui_contract",
    )
    root_receipt = _auction_hall_6001_canonical_receipt(root_value)
    if root_status != "present" or root_receipt is None:
        return "receipt_missing_or_invalid", {}
    if ui_status != "present" or type(ui_contract) is not dict:  # noqa: E721
        return "ui_receipt_missing_or_invalid", {}
    reference_status, reference = _current_activity_exact_dict_field(
        ui_contract,
        "distribution_reference",
    )
    reference_receipt = _auction_hall_6001_canonical_receipt(reference)
    if reference_status != "present" or reference_receipt is None:
        return "receipt_mixed", {}
    if root_receipt != reference_receipt:
        return "receipt_mixed", {}
    return "ok", root_receipt


def _auction_hall_6001_quantile(values: list[int], probability: float) -> int:
    ordered = sorted(values)
    if not ordered:
        return 0
    position = probability * (len(ordered) - 1)
    low = int(math.floor(position))
    high = int(math.ceil(position))
    if low == high:
        return int(ordered[low])
    fraction = position - low
    return int(round(ordered[low] + fraction * (ordered[high] - ordered[low])))


@lru_cache(maxsize=64)
def _auction_hall_6001_value_quantiles(
    total_count: int,
) -> tuple[tuple[int, int, int], tuple[int, int, int]]:
    status, document = _load_auction_hall_6001_shadow()
    if status != "ok":
        raise ValueError(f"6001 sidecar unavailable: {status}")
    rows = document["items"]
    cumulative: list[float] = []
    values: list[int] = []
    qualities: list[int] = []
    running = 0.0
    for row in rows:
        probability = float(
            row["scenario_probabilities"][AUCTION_HALL_6001_PRIMARY_SCENARIO]
        )
        if probability <= 0.0:
            continue
        running += probability
        cumulative.append(running)
        values.append(int(row["normalized_value"]))
        qualities.append(int(row["quality"]))
    cumulative[-1] = 1.0
    seed = int(AUCTION_HALL_6001_SHADOW_SHA256[:16], 16) ^ int(total_count)
    rng = random.Random(seed)
    totals: list[int] = []
    red_totals: list[int] = []
    for _trial in range(4_096):
        total = 0
        red_total = 0
        for _draw in range(total_count):
            index = min(
                bisect_left(cumulative, rng.random()),
                len(values) - 1,
            )
            value = values[index]
            total += value
            if qualities[index] == 6:
                red_total += value
        totals.append(total)
        red_totals.append(red_total)
    return (
        tuple(
            _auction_hall_6001_quantile(totals, probability)
            for probability in (0.25, 0.50, 0.75)
        ),
        tuple(
            _auction_hall_6001_quantile(red_totals, probability)
            for probability in (0.25, 0.50, 0.75)
        ),
    )


def _auction_hall_6001_quality_count_ranges(
    total_count: int,
    document: dict[str, Any],
) -> dict[str, tuple[int, int, int]]:
    quality_mass = document["summary"]["scenarios"][
        AUCTION_HALL_6001_PRIMARY_SCENARIO
    ]["quality_mass"]
    result: dict[str, tuple[int, int, int]] = {}
    for key in QUALITY_KEYS:
        probability = float(quality_mass[key])
        mean = total_count * probability
        spread = 0.67448975 * math.sqrt(
            total_count * probability * (1.0 - probability)
        )
        result[key] = (
            max(0, int(math.floor(mean - spread))),
            max(0, int(round(mean))),
            min(total_count, int(math.ceil(mean + spread))),
        )
    return result


_AUCTION_HALL_6001_STRUCTURED_OWNER_KEYS = (
    "structured_ref_inputs",
    "hero_ref_inputs",
    "aisha_ref_inputs",
    "ahmad_ref_inputs",
    "victor_ref_inputs",
)
_AUCTION_HALL_6001_TOTAL_COUNT_KEYS = (
    "total_count",
    "total_item_count",
    "session_total_count",
    "session_total_item_count",
)


def _auction_hall_6001_exact_total_count(
    snapshot: Any,
) -> tuple[str, int | None]:
    """Read only an exact builtin count without invoking external protocols."""

    if type(snapshot) is not dict:  # noqa: E721 - external boundary
        return "invalid", None
    containers = [snapshot]
    ui_status, ui_contract = _current_activity_exact_dict_field(
        snapshot,
        "ui_contract",
    )
    if ui_status == "invalid":
        return "invalid", None
    if ui_status == "present":
        if type(ui_contract) is not dict:  # noqa: E721
            return "invalid", None
        containers.append(ui_contract)
        constraints_status, constraints = _current_activity_exact_dict_field(
            ui_contract,
            "constraints",
        )
        if constraints_status == "invalid":
            return "invalid", None
        if constraints_status == "present":
            if type(constraints) is not dict:  # noqa: E721
                return "invalid", None
            containers.append(constraints)

    counts: list[int] = []
    for container in containers:
        for owner_key in _AUCTION_HALL_6001_STRUCTURED_OWNER_KEYS:
            owner_status, owner = _current_activity_exact_dict_field(
                container,
                owner_key,
            )
            if owner_status == "invalid":
                return "invalid", None
            if owner_status != "present":
                continue
            if type(owner) is not dict:  # noqa: E721 - reject Mapping hooks
                return "invalid", None
            for count_key in _AUCTION_HALL_6001_TOTAL_COUNT_KEYS:
                count_status, value = _current_activity_exact_dict_field(
                    owner,
                    count_key,
                )
                if count_status == "invalid":
                    return "invalid", None
                if count_status != "present":
                    continue
                if type(value) is not int or not 1 <= value <= 512:  # noqa: E721
                    return "invalid", None
                counts.append(value)
    if not counts:
        return "missing", None
    if any(value != counts[0] for value in counts[1:]):
        return "conflict", None
    return "ok", counts[0]


def _auction_hall_6001_safe_evidence(
    snapshot: Any,
) -> tuple[str, RefEvidence]:
    """Build the 6001 evidence from plain internal values only."""

    count_status, total_count = _auction_hall_6001_exact_total_count(snapshot)
    hero_status, hero = _current_activity_exact_dict_field(snapshot, "hero")
    phase_status, phase = _current_activity_exact_dict_field(snapshot, "phase")
    internal: dict[str, Any] = {
        "hero": hero if hero_status == "present" and type(hero) is str else "",  # noqa: E721
        "map_id": 6001,
        "phase": (
            phase
            if phase_status == "present" and type(phase) is str  # noqa: E721
            else ""
        ),
    }
    if count_status == "ok" and total_count is not None:
        internal["structured_ref_inputs"] = {"total_count": total_count}
    return count_status, extract_evidence(internal)


def _auction_hall_6001_provisional_result(
    snapshot: dict[str, Any],
    state: str,
    *,
    safety_factor: float | None,
) -> RefResult:
    if CURRENT_RANKMAP_PACKAGE_GENERATION == '76b7ca-2026-10-08-723':
        if state == 'map_conflict':
            return _update606_pending_result(extract_evidence({'map_id': 6001}), state,
                note_prefix='auction_hall_6001_model_unavailable')
        return _auction_hall_6001_current_result(snapshot, safety_factor=safety_factor)
    total_count_status, evidence = _auction_hall_6001_safe_evidence(snapshot)
    if state != "provisional":
        return _update606_pending_result(
            evidence,
            state,
            note_prefix=UPDATE606_LARGE_AUCTION_PENDING_NOTE_PREFIX,
        )
    receipt_status, receipt = _auction_hall_6001_snapshot_receipt(snapshot)
    sidecar_status, document = _load_auction_hall_6001_shadow()
    if receipt_status != "ok" or sidecar_status != "ok":
        return _update606_pending_result(
            evidence,
            (
                receipt_status
                if receipt_status != "ok"
                else sidecar_status
            ),
            note_prefix=AUCTION_HALL_6001_PROVISIONAL_NOTE_PREFIX,
        )
    total_count = evidence.total_count
    if (
        total_count_status != "ok"
        or type(total_count) is not int  # noqa: E721
        or not 1 <= total_count <= 512
    ):
        return replace(
            _update606_pending_result(
                evidence,
                "missing_total_count",
                note_prefix=AUCTION_HALL_6001_PROVISIONAL_NOTE_PREFIX,
            ),
            status="missing_total_count",
        )
    value_range, red_value_range = _auction_hall_6001_value_quantiles(
        total_count
    )
    multipliers = quote_safety_multipliers(
        0.85 if safety_factor is None else safety_factor
    )
    quote_values = [
        int(round(value * multiplier))
        for value, multiplier in zip(value_range, multipliers)
    ]
    quote_values[1] = max(quote_values[0], quote_values[1])
    quote_values[2] = max(quote_values[1], quote_values[2])
    quality_ranges = _auction_hall_6001_quality_count_ranges(
        total_count,
        document,
    )
    primary_summary = document["summary"]["scenarios"][
        AUCTION_HALL_6001_PRIMARY_SCENARIO
    ]
    upper_summary = document["summary"]["scenarios"][
        AUCTION_HALL_6001_UPPER_SCENARIO
    ]
    provisional_receipt = {
        **receipt,
        "total_count": total_count,
        "official_distribution_authority": False,
        "official_quote_authority": False,
        "provisional_distribution_available": True,
        "provisional_quote_available": True,
        "value_quantile_method": "deterministic_4096_draw_monte_carlo",
        "primary_quality_mass": {
            key: float(primary_summary["quality_mass"][key])
            for key in QUALITY_KEYS
        },
    }
    return RefResult(
        status="provisional_estimated",
        source="auction_hall_6001_shadow",
        conservative=quote_values[0],
        balanced=quote_values[1],
        aggressive=quote_values[2],
        value_p25=value_range[0],
        value_p50=value_range[1],
        value_p75=value_range[2],
        combo_count=4_096,
        red_count_range=quality_ranges["q6"],
        red_cells_range=(None, None, None),
        red_value_range=red_value_range,
        quality_count_ranges=quality_ranges,
        quality_cells_ranges={
            key: (None, None, None) for key in QUALITY_KEYS
        },
        total_grid_range=(None, None, None),
        notes=(
            "auction_hall_6001_provisional_estimated",
            f"auction_hall_6001_shadow:{AUCTION_HALL_6001_SHADOW_SHA256}",
            "auction_hall_6001_official_authority_false",
        ),
        evidence=evidence,
        risk_ceiling={
            "mode": "provisional_sensitivity_upper_envelope",
            "affects_bid": False,
            "primary_expected_normalized_value_per_draw": primary_summary[
                "expected_normalized_value_per_draw"
            ],
            "upper_expected_normalized_value_per_draw": upper_summary[
                "expected_normalized_value_per_draw"
            ],
        },
        provisional_quote=provisional_receipt,
    )


def _auction_hall_6001_current_scope_state(snapshot: Any) -> str:
    import auction_hall_6001_quote_model as model

    # The public normalizer may retain a safe map number while preserving a
    # negative raw-identity marker. Never turn that marker into model authority.
    if _update606_large_auction_pending_scope_state(snapshot) == 'map_conflict':
        return 'map_conflict'
    return model.scope_state(snapshot)


def _auction_hall_6001_current_result(snapshot: Any, *, safety_factor: float | None) -> RefResult:
    import auction_hall_6001_quote_model as model

    state = _auction_hall_6001_current_scope_state(snapshot)
    if state == 'ok':
        state = _current_rankmap_distribution_generation_status()[0]
    if state != 'ok':
        return _update606_pending_result(extract_evidence({'map_id': 6001}), state,
            note_prefix='auction_hall_6001_model_unavailable')
    try:
        # Qualification precedes even a warm same-input result. No current
        # source/credential failure may borrow an old 6001 sidecar or quote.
        model.load_model(lambda path: _aisha_q5_total_cells_plaintext_bytes(ROOT / path))
        key = json.dumps(snapshot, ensure_ascii=False, sort_keys=True, allow_nan=False)
        return _auction_hall_6001_current_cached_quote(key, safety_factor)
    except model.MathematicalConflict as error:
        return _update606_pending_result(extract_evidence({'map_id': 6001}),
            'proved_public_conflict:' + str(error), note_prefix='auction_hall_6001_model_unavailable')
    except (model.ModelInputError, TypeError, ValueError) as error:
        return _update606_pending_result(extract_evidence({'map_id': 6001}),
            str(error), note_prefix='auction_hall_6001_model_unavailable')


@lru_cache(maxsize=24)
def _auction_hall_6001_current_cached_quote(snapshot_json: str, safety_factor: float | None) -> RefResult:
    import auction_hall_6001_quote_model as model

    snapshot = json.loads(snapshot_json)
    evidence = extract_evidence(snapshot)
    hall = model.load_model(lambda path: _aisha_q5_total_cells_plaintext_bytes(ROOT / path))
    posterior = model.posterior(hall, evidence, snapshot=snapshot, draws=512)
    if posterior['status'] != 'ok':
        return replace(_update606_pending_result(evidence, posterior['reason'],
            note_prefix='auction_hall_6001_model_unavailable'), status='computational_insufficient')
    value_range = posterior['value_range']
    quartiles = posterior['value_quartiles']
    multipliers = quote_safety_multipliers(0.85 if safety_factor is None else safety_factor)
    quotes = [int(round(value * factor)) for value, factor in zip(value_range, multipliers)]
    quotes[1] = max(quotes[:2])
    quotes[2] = max(quotes)
    metadata = {key: value for key, value in posterior.items() if key not in (
        'value_range', 'value_quartiles', 'quality_count_ranges', 'quality_cells_ranges',
        'quality_value_ranges', 'total_grid_range')}
    metadata.update(model_map_id=6001, input_sha256={path: pin[1] for path, pin in model.INPUTS.items()},
        official_quote_authority=False, provisional_distribution_available=True,
        provisional_quote_available=True, count_uncertainty_kind='algorithm_posterior_not_prediction_error',
        primary_quality_mass={q: float(posterior['quality_count_means'][q] / posterior['count_mean'])
                              for q in QUALITY_KEYS})
    return RefResult(status='provisional_estimated', source=model.MODEL_VERSION,
        conservative=quotes[0], balanced=quotes[1], aggressive=quotes[2],
        value_p25=quartiles[0], value_p50=quartiles[1], value_p75=quartiles[2],
        combo_count=posterior['accepted'],
        red_count_range=tuple(posterior['quality_count_ranges']['q6']),
        red_cells_range=tuple(posterior['quality_cells_ranges']['q6']),
        red_value_range=tuple(posterior['quality_value_ranges']['q6']),
        quality_count_ranges={q: tuple(v) for q, v in posterior['quality_count_ranges'].items()},
        quality_cells_ranges={q: tuple(v) for q, v in posterior['quality_cells_ranges'].items()},
        total_grid_range=tuple(posterior['total_grid_range']),
        notes=tuple(evidence.source_notes) + ('auction_hall_6001_algorithm_estimate',),
        evidence=evidence, provisional_quote=metadata,
        quality_lock={q: {'strength': 'exact' if q in evidence.fixed_counts else 'probabilistic',
                          'reason': 'exact_lock' if q in evidence.fixed_counts else 'combo_multi_solution'}
                      for q in QUALITY_KEYS})


def _update606_large_auction_pending_scope_state(snapshot: Any) -> str | None:
    """Scope map 6001 to its exact provisional path without parent aliases."""

    guard_status, guard = _current_activity_exact_dict_field(
        snapshot,
        _CURRENT_ACTIVITY_RAW_MAP_GUARD_KEY,
    )
    guard_blocked = (
        guard_status == "present"
        and type(guard) is str  # noqa: E721
        and str.__eq__(guard, _CURRENT_ACTIVITY_RAW_MAP_BLOCKED)
    )
    root_status, root_value = _current_activity_exact_dict_field(snapshot, "map_id")
    ui_status, ui_contract = _current_activity_exact_dict_field(
        snapshot, "ui_contract"
    )
    context_status = "absent"
    context_value = _CURRENT_ACTIVITY_MAP_FIELD_MISSING
    invalid = (
        root_status == "invalid"
        or ui_status == "invalid"
        or guard_status == "invalid"
        or (guard_status == "present" and not guard_blocked)
    )
    if ui_status == "present":
        if type(ui_contract) is not dict:  # noqa: E721
            invalid = True
        else:
            container_status, context = _current_activity_exact_dict_field(
                ui_contract, "context"
            )
            if container_status == "invalid" or (
                container_status == "present"
                and type(context) is not dict  # noqa: E721
            ):
                invalid = True
            elif container_status == "present":
                context_status, context_value = _current_activity_exact_dict_field(
                    context, "map_id"
                )

    values: list[int] = []
    invalid = invalid or context_status == "invalid"
    for status, raw_value in (
        (root_status, root_value),
        (context_status, context_value),
    ):
        if status != "present":
            continue
        value_status, map_id = _update606_large_auction_pending_map_value(raw_value)
        if value_status != "present" or map_id is None:
            invalid = True
            continue
        values.append(map_id)

    if UPDATE606_LARGE_AUCTION_PENDING_MAP_ID not in values:
        return None
    if guard_blocked or invalid or any(
        map_id != UPDATE606_LARGE_AUCTION_PENDING_MAP_ID for map_id in values
    ):
        return "map_conflict"
    return (
        "provisional"
        if CURRENT_RANKMAP_PACKAGE_GENERATION
        == AUCTION_HALL_6001_HISTORICAL_GENERATION
        else "dormant_current_generation"
    )


def _update606_pending_result(
    evidence: RefEvidence,
    state: str,
    *,
    note_prefix: str,
) -> RefResult:
    """Return the ordinary no-quote shape consumed by every existing surface."""

    return RefResult(
        status="no_reachable_combo",
        source="ref_v0",
        conservative=None,
        balanced=None,
        aggressive=None,
        value_p25=None,
        value_p50=None,
        value_p75=None,
        combo_count=0,
        red_count_range=(None, None, None),
        red_cells_range=(None, None, None),
        red_value_range=(None, None, None),
        quality_count_ranges={},
        quality_cells_ranges={},
        total_grid_range=(None, None, None),
        notes=(f"{note_prefix}:{state}",),
        evidence=evidence,
    )


def _update606_changed_route_pending_result(
    state: str,
    map_id: int | None,
) -> RefResult:
    # A negative route-authority decision must not ask the generic evidence
    # parser to coerce any remaining external value.  Preserve only the exact
    # map identity already obtained without user conversion hooks.
    evidence = extract_evidence(
        {"map_id": map_id}
        if type(map_id) is int and map_id in UPDATE606_CHANGED_ROUTE_MAP_IDS
        else {}
    )
    note_prefix = UPDATE606_CHANGED_ROUTE_NOTE_PREFIX
    if state == "no_approved_distribution" and map_id is not None:
        reason = _update606_changed_route_reason(map_id)
        if reason is not None:
            note_prefix = (
                f"{note_prefix}:{UPDATE606_RUNTIME_PACKAGE_GENERATION}"
                f":{map_id}:{reason}"
            )
    return _update606_pending_result(
        evidence,
        state,
        note_prefix=note_prefix,
    )


def _current_rankmap_authority_pending_result(
    state: str,
    map_id: int | None,
) -> RefResult:
    evidence = extract_evidence(
        {"map_id": map_id}
        if type(map_id) is int and map_id in CURRENT_RANKMAP_MAP_IDS
        else {}
    )
    return _update606_pending_result(
        evidence,
        state,
        note_prefix=(
            f"{CURRENT_RANKMAP_AUTHORITY_NOTE_PREFIX}:"
            f"{CURRENT_RANKMAP_PACKAGE_GENERATION}:"
            f"{map_id if map_id is not None else 'unknown'}"
        ),
    )


def _chenmei_zhenhai_pending_result(
    evidence: RefEvidence,
    state: str,
) -> RefResult:
    return _update606_pending_result(
        evidence,
        state,
        note_prefix=CHENMEI_ZHENHAI_PENDING_NOTE_PREFIX,
    )


def _current_activity_map_scalar(value: Any) -> tuple[str, int | None]:
    """Project one raw map scalar without lossy numeric/string coercion."""

    if type(value) is int:  # noqa: E721 - bool/subclasses are invalid
        map_id = value
        if not 0 <= map_id <= 9_999:
            return "invalid", None
    elif (
        type(value) is str  # noqa: E721 - accept only the plain wire spelling
        and len(value) == 4
        and all("0" <= char <= "9" for char in value)
    ):
        map_id = (
            (ord(value[0]) - 48) * 1000
            + (ord(value[1]) - 48) * 100
            + (ord(value[2]) - 48) * 10
            + ord(value[3])
            - 48
        )
    else:
        return "invalid", None
    return (
        ("eligible", map_id)
        if _is_current_activity_shipwreck_map(map_id)
        else ("not_activity", map_id)
    )


def _current_activity_raw_map_decision(
    snapshot: Any,
) -> tuple[str, int | None, str | None]:
    """Classify root/context map owners before any lossy product projection.

    The JSON-safe guard only carries a negative decision.  An external caller
    can therefore disable this temporary overlay, but can never forge an
    eligible activity map.
    """

    guard_status, guard = _current_activity_exact_dict_field(
        snapshot,
        _CURRENT_ACTIVITY_RAW_MAP_GUARD_KEY,
    )
    if guard_status == "invalid":
        return "invalid", None, "root"
    if guard_status == "present":
        if (
            type(guard) is str  # noqa: E721 - negative marker is exact-only
            and str.__eq__(guard, _CURRENT_ACTIVITY_RAW_MAP_BLOCKED)
        ):
            return "blocked", None, None
        return "invalid", None, "guard"

    root_status, root_map = _current_activity_exact_dict_field(
        snapshot,
        "map_id",
    )
    if root_status == "invalid":
        return "invalid", None, "root"

    ui_status, ui_contract = _current_activity_exact_dict_field(
        snapshot,
        "ui_contract",
    )
    context_status = "absent"
    context_map = _CURRENT_ACTIVITY_MAP_FIELD_MISSING
    if ui_status == "invalid":
        return "invalid", None, "root"
    if ui_status == "present" and ui_contract is not None:
        if type(ui_contract) is not dict:  # noqa: E721 - no Mapping fallback
            return "invalid", None, "ui_contract"
        context_field_status, context = _current_activity_exact_dict_field(
            ui_contract,
            "context",
        )
        if context_field_status == "invalid":
            return "invalid", None, "ui_contract"
        if context_field_status == "present" and context is not None:
            if type(context) is not dict:  # noqa: E721 - no Mapping fallback
                return "invalid", None, "context"
            context_status, context_map = _current_activity_exact_dict_field(
                context,
                "map_id",
            )
            if context_status == "invalid":
                return "invalid", None, "context"

    candidates: list[int] = []
    for status, raw_value in (
        (root_status, root_map),
        (context_status, context_map),
    ):
        if status != "present":
            continue
        scalar_status, map_id = _current_activity_map_scalar(raw_value)
        if scalar_status == "invalid" or map_id is None:
            return "invalid", None, "map"
        candidates.append(map_id)
    if not candidates:
        return "absent", None, None
    if any(map_id != candidates[0] for map_id in candidates[1:]):
        return "conflict", None, "map"
    map_id = candidates[0]
    return (
        ("eligible", map_id, None)
        if _is_current_activity_shipwreck_map(map_id)
        else ("not_activity", map_id, None)
    )


def _stabilize_current_activity_raw_map_snapshot(
    snapshot: Any,
    *,
    raw_decision: tuple[str, int | None, str | None] | None = None,
) -> dict[str, Any]:
    """Carry raw map invalid/conflict state through panel JSON projections."""

    decision, _map_id, scope = (
        raw_decision
        if raw_decision is not None
        else _current_activity_raw_map_decision(snapshot)
    )
    if decision in {"eligible", "not_activity", "absent", "blocked"}:
        return snapshot
    if type(snapshot) is not dict or scope == "root":  # noqa: E721
        return {
            _CURRENT_ACTIVITY_RAW_MAP_GUARD_KEY:
                _CURRENT_ACTIVITY_RAW_MAP_BLOCKED
        }

    payload = dict.copy(snapshot)
    if scope == "ui_contract":
        payload["ui_contract"] = {}
    elif scope == "context":
        ui_contract = dict.get(payload, "ui_contract")
        if type(ui_contract) is dict:  # noqa: E721 - classifier proved exact
            stable_ui = dict.copy(ui_contract)
            stable_ui["context"] = {}
            payload["ui_contract"] = stable_ui
    elif scope == "map":
        if _current_activity_exact_dict_field(payload, "map_id")[0] == "present":
            payload["map_id"] = None
        ui_contract = dict.get(payload, "ui_contract")
        if type(ui_contract) is dict:  # noqa: E721 - classifier proved exact
            context = dict.get(ui_contract, "context")
            if type(context) is dict:  # noqa: E721 - classifier proved exact
                stable_context = dict.copy(context)
                if (
                    _current_activity_exact_dict_field(
                        stable_context,
                        "map_id",
                    )[0]
                    == "present"
                ):
                    stable_context["map_id"] = None
                stable_ui = dict.copy(ui_contract)
                stable_ui["context"] = stable_context
                payload["ui_contract"] = stable_ui
    payload[_CURRENT_ACTIVITY_RAW_MAP_GUARD_KEY] = (
        _CURRENT_ACTIVITY_RAW_MAP_BLOCKED
    )
    return payload


def stabilize_reference_engine_external_snapshot(snapshot: Any) -> dict[str, Any]:
    """Remove unsafe owner containers without erasing builtin map conflicts."""

    ui_status, ui_contract = _current_activity_exact_dict_field(
        snapshot,
        "ui_contract",
    )
    if ui_status == "invalid":
        return {
            _CURRENT_ACTIVITY_RAW_MAP_GUARD_KEY:
                _CURRENT_ACTIVITY_RAW_MAP_BLOCKED
        }
    if ui_status != "present" or ui_contract is None:
        return snapshot
    payload = dict.copy(snapshot)
    if type(ui_contract) is not dict:  # noqa: E721 - reject Mapping hooks
        payload["ui_contract"] = {}
        payload[_CURRENT_ACTIVITY_RAW_MAP_GUARD_KEY] = (
            _CURRENT_ACTIVITY_RAW_MAP_BLOCKED
        )
        return payload
    context_status, context = _current_activity_exact_dict_field(
        ui_contract,
        "context",
    )
    if context_status == "invalid" or (
        context_status == "present"
        and context is not None
        and type(context) is not dict  # noqa: E721
    ):
        stable_ui = dict.copy(ui_contract)
        stable_ui["context"] = {}
        payload["ui_contract"] = stable_ui
        payload[_CURRENT_ACTIVITY_RAW_MAP_GUARD_KEY] = (
            _CURRENT_ACTIVITY_RAW_MAP_BLOCKED
        )
    return payload


def _stabilize_activity_and_warehouse_snapshot(
    snapshot: Any,
) -> tuple[dict[str, Any], str]:
    """Apply both raw decisions without letting either lossy view erase the other."""

    activity_decision = _current_activity_raw_map_decision(snapshot)
    warehouse_status, _warehouse_contract = (
        _warehouse_quote_source_contract_projection(snapshot)
    )
    payload = snapshot
    if warehouse_status in {"unsafe", "invalid"}:
        # Stabilize owner containers before any hero/context lookup.  The raw
        # activity decision is retained separately so removing an unsafe
        # context cannot turn an invalid activity map into a valid root-only
        # map, while the activity projection cannot erase warehouse rejection.
        payload = _drop_rejected_warehouse_quote_source_fields(payload)
    payload = _stabilize_current_activity_raw_map_snapshot(
        payload,
        raw_decision=activity_decision,
    )
    return payload, warehouse_status


_ACTIVITY_TIMESTAMP_MISSING = object()


def _exact_snapshot_field(snapshot: Any, name: str) -> Any:
    """Read one exact-string root field without invoking mapping/key protocols."""

    if type(snapshot) is not dict:  # noqa: E721 - external container boundary
        return _ACTIVITY_TIMESTAMP_MISSING
    for key, value in dict.items(snapshot):
        if type(key) is not str:  # noqa: E721 - collision/subclass keys are invalid
            return _ACTIVITY_TIMESTAMP_MISSING
        if str.__eq__(key, name):
            return value
    return _ACTIVITY_TIMESTAMP_MISSING


def _current_activity_snapshot_in_window(snapshot: Any) -> bool:
    """Require an exact numeric event timestamp in the half-open Beijing window."""

    timestamp = _exact_snapshot_field(snapshot, "created_at")
    if timestamp is _ACTIVITY_TIMESTAMP_MISSING:
        timestamp = _exact_snapshot_field(snapshot, "client_ts")
    if type(timestamp) is int:  # noqa: E721 - bool/subclasses must fail closed
        pass
    elif type(timestamp) is float:  # noqa: E721 - no conversion protocols
        if not math.isfinite(timestamp):
            return False
    else:
        return False
    return (
        CURRENT_ACTIVITY_SHIPWRECK_RED_BOOST_START_EPOCH
        <= timestamp
        < CURRENT_ACTIVITY_SHIPWRECK_RED_BOOST_END_EPOCH
    )


def _collection_activity_snapshot_in_window(snapshot: Any) -> bool:
    """Require an exact numeric capture time in the announced one-week window."""

    timestamp = _exact_snapshot_field(snapshot, "created_at")
    if timestamp is _ACTIVITY_TIMESTAMP_MISSING:
        timestamp = _exact_snapshot_field(snapshot, "client_ts")
    if type(timestamp) is int:  # noqa: E721 - bool/subclasses must fail closed
        pass
    elif type(timestamp) is float:  # noqa: E721 - no conversion protocols
        if not math.isfinite(timestamp):
            return False
    else:
        return False
    return (
        SHIPWRECK_COLLECTION_ACTIVITY_RED_BOOST_START_EPOCH
        <= timestamp
        < SHIPWRECK_COLLECTION_ACTIVITY_RED_BOOST_END_EPOCH
    )


def _current_activity_phase_eligible(phase: Any) -> bool:
    """Keep the temporary prior on live inference and out of settlement review."""

    return (
        type(phase) is str  # noqa: E721 - reject protocol-bearing subclasses
        and phase.isascii()
        and phase.strip().lower() in {"reading", "bidding"}
    )


def _apply_activity_shipwreck_red_boost(
    probs: dict[str, float],
    map_id: Any,
    snapshot: dict[str, Any],
    notes: list[str],
    *,
    phase: Any = None,
    current_activity_raw_map_decision: (
        tuple[str, int | None, str | None] | None
    ) = None,
) -> dict[str, float]:
    """Apply the independently calibrated q6 priors for shipwreck activity map blocks.

    X511-X520 uses the older 1.74 regime and its existing time-window backstop. The
    2026-07-16 red-crate blocks (2541-2550 / 4541-4550) use the milder 1.22 regime and
    are gated by their activity-exclusive source map ids.  The 2026-07-30 blocks
    (2521-2530 / 4521-4530) require their exact one-week Beijing window and apply the
    independently reversible 1.5 q6-weight overlay.  The
    2026-08-13 collection activity reuses the StaticData-confirmed X531-X540
    cohort on the 25xx/45xx shipwreck arms and the announced one-week Beijing
    window.  Its sample-calibrated 1.11 q6-weight overlay is independent from
    the older 2026-07-30 1.5 regime: the collection event primarily increases
    total item count, so reusing 1.5 on quality composition would double-count
    the observed quantity lift.
    The red-crate regime has its own ``AHMAD_DISABLE_RED_CRATE_SHIPWRECK_RED_BOOST=1``
    kill switch and ``AHMAD_RED_CRATE_SHIPWRECK_RED_BOOST_FACTOR`` override; both
    default to enabled with :data:`RED_CRATE_SHIPWRECK_RED_BOOST_FACTOR`.

    For the older X511-X520 regime, boost the q6 prior (see the module comment).
    Gated on the map NUMBER (activity-exclusive ids), NOT the match date — this fixes the old
    mis-classification that boosted normal X501-X510 games played during the window. The time window
    is now only an optional AUTO-EXPIRE backstop: if a reliable date is present AND it is OUTSIDE the
    (loose) window, skip — so a future non-activity reuse of these ids after the window won't boost.
    A missing/unreliable date does NOT block the boost (the map number itself proves activity).
    Kill-switch AHMAD_DISABLE_ACTIVITY_SHIPWRECK_RED_BOOST=1; factor AHMAD_ACTIVITY_SHIPWRECK_RED_BOOST_FACTOR;
    window ACTIVITY_START/ACTIVITY_END; force-on ignore-expiry AHMAD_FORCE_ACTIVITY_SHIPWRECK_RED_BOOST=1."""
    is_legacy_activity = _is_activity_shipwreck_map(map_id)
    is_red_crate_activity = _is_red_crate_activity_shipwreck_map(map_id)
    if current_activity_raw_map_decision is None:
        current_status, current_map_id = _current_activity_map_scalar(map_id)
    else:
        current_status, current_map_id, _scope = (
            current_activity_raw_map_decision
        )
    evidence_map_status, evidence_map_id = _current_activity_map_scalar(map_id)
    is_current_activity = (
        current_status == "eligible"
        and current_map_id is not None
        and evidence_map_status == "eligible"
        and evidence_map_id == current_map_id
    )
    is_collection_activity = (
        current_status == "not_activity"
        and current_map_id is not None
        and evidence_map_status == "not_activity"
        and evidence_map_id == current_map_id
        and _is_collection_activity_shipwreck_map(current_map_id)
    )
    if (
        not is_legacy_activity
        and not is_red_crate_activity
        and not is_current_activity
        and not is_collection_activity
    ):
        return probs  # ordinary wreckage and unrelated old ships stay at steady-state

    if is_current_activity:
        if os.environ.get(CURRENT_ACTIVITY_SHIPWRECK_RED_BOOST_DISABLE) == "1":
            return probs
        if not _current_activity_phase_eligible(phase):
            return probs
        if not _current_activity_snapshot_in_window(snapshot):
            return probs
        factor = CURRENT_ACTIVITY_SHIPWRECK_RED_BOOST_FACTOR
        note_prefix = "current_activity_shipwreck_red_boost"
    elif is_collection_activity:
        if os.environ.get(SHIPWRECK_COLLECTION_ACTIVITY_RED_BOOST_DISABLE) == "1":
            return probs
        if not _current_activity_phase_eligible(phase):
            return probs
        if not _collection_activity_snapshot_in_window(snapshot):
            return probs
        factor = SHIPWRECK_COLLECTION_ACTIVITY_RED_BOOST_FACTOR
        note_prefix = "shipwreck_collection_activity_red_boost"
    elif is_red_crate_activity:
        if os.environ.get("AHMAD_DISABLE_RED_CRATE_SHIPWRECK_RED_BOOST") == "1":
            return probs
        try:
            factor = float(
                os.environ.get(
                    "AHMAD_RED_CRATE_SHIPWRECK_RED_BOOST_FACTOR",
                    RED_CRATE_SHIPWRECK_RED_BOOST_FACTOR,
                )
            )
        except (TypeError, ValueError):
            factor = RED_CRATE_SHIPWRECK_RED_BOOST_FACTOR
        note_prefix = "red_crate_shipwreck_red_boost"
    else:
        if os.environ.get("AHMAD_DISABLE_ACTIVITY_SHIPWRECK_RED_BOOST") == "1":
            return probs
        factor = None
        note_prefix = "activity_shipwreck_red_boost"

    if os.environ.get("AHMAD_FORCE_ACTIVITY_SHIPWRECK_RED_BOOST") != "1":
        if is_legacy_activity:
            ts = snapshot.get("created_at")
            if not isinstance(ts, (int, float)):
                ts = snapshot.get("client_ts")
            # Only the AUTO-EXPIRE side of the window binds: a date OUTSIDE the window skips; a missing
            # date still boosts (the activity-exclusive map number is sufficient evidence).
            if isinstance(ts, (int, float)):
                import datetime
                try:
                    start = datetime.datetime.strptime(
                        os.environ.get("ACTIVITY_START", ACTIVITY_SHIPWRECK_RED_BOOST_START), "%Y-%m-%d %H:%M:%S"
                    ).timestamp()
                    end = datetime.datetime.strptime(
                        os.environ.get("ACTIVITY_END", ACTIVITY_SHIPWRECK_RED_BOOST_END), "%Y-%m-%d %H:%M:%S"
                    ).timestamp()
                except (TypeError, ValueError):
                    start = end = None
                if start is not None and end is not None and not (start <= float(ts) <= end):
                    return probs  # outside the (loose) window -> auto-expire
    if factor is None:
        try:
            factor = float(
                os.environ.get(
                    "AHMAD_ACTIVITY_SHIPWRECK_RED_BOOST_FACTOR",
                    ACTIVITY_SHIPWRECK_RED_BOOST_FACTOR,
                )
            )
        except (TypeError, ValueError):
            factor = ACTIVITY_SHIPWRECK_RED_BOOST_FACTOR
    if factor <= 1.0 or probs.get("q6", 0.0) <= 0:
        return probs
    boosted = dict(probs)
    boosted["q6"] = boosted["q6"] * factor
    total = sum(boosted.values())
    if total <= 0:
        return probs
    boosted = {k: v / total for k, v in boosted.items()}
    notes.append(f"{note_prefix}:{factor}")
    return boosted


@_shipwreck_calibrated_context
def _run_reference_engine_impl(
    snapshot: dict[str, Any],
    *,
    static_data: dict[str, Any] | None = None,
    safety_factor: float | None = None,
    max_combos: int = 50000,
    _allow_public_avg_fallback: bool = True,
    _allow_high_tier_grid_fallback: bool = True,
    _allow_sparse_soft_fallback: bool = True,
    _grid_identity_target: int | None = None,
) -> RefResult:
    current_activity_raw_map_decision = _current_activity_raw_map_decision(
        snapshot
    )
    wuqilin_pending_state = _wuqilin_5215_pending_scope_state(snapshot)
    if wuqilin_pending_state is not None:
        return _wuqilin_5215_quote_result(snapshot, safety_factor=safety_factor)
    large_auction_pending_state = (
        _update606_large_auction_pending_scope_state(snapshot)
    )
    if large_auction_pending_state is not None:
        return _auction_hall_6001_provisional_result(
            snapshot,
            large_auction_pending_state,
            safety_factor=safety_factor,
        )
    zhenhai_pending_state = _chenmei_zhenhai_pending_scope_state(snapshot)
    if zhenhai_pending_state is not None:
        return _chenmei_zhenhai_pending_result(
            extract_evidence(snapshot), zhenhai_pending_state
        )
    rankmap_pending_state = _current_rankmap_authority_scope_state(snapshot)
    if rankmap_pending_state is not None:
        state, map_id = rankmap_pending_state
        return _current_rankmap_authority_pending_result(state, map_id)
    changed_route_pending_state = _update606_changed_route_scope_state(snapshot)
    if changed_route_pending_state is not None:
        state, map_id = changed_route_pending_state
        return _update606_changed_route_pending_result(state, map_id)
    static_data = static_data or load_reference_static_data()
    evidence = extract_evidence(snapshot)
    evidence = _resolve_total_avg_cells_options_for_exact_counts(evidence)
    if _grid_identity_target is not None:
        # 族D pass 2: the spatially-anchored total grid, injected so the grid fit reconciles the tiers
        # against it. The note goes into evidence.source_notes (NOT just the local list) because that is
        # what _hard_total_grid_target_int reads, and it is what keeps this target SOFT — a bare integer
        # total_grid_target is treated as a HARD equality and rejects every combo that cannot compose it
        # exactly (5611: floors make the anchored 83 unreachable -> all combos die -> blank panel, the
        # same trap the sparse-early cap hit on sophie 2403). This is the engine's own estimate, not a
        # tool reading; it must steer the allocation and never veto a combo.
        evidence = replace(
            evidence,
            total_grid_target=float(_grid_identity_target),
            source_notes=tuple(evidence.source_notes)
            + (f"{GRID_IDENTITY_RECONCILE_NOTE_PREFIX}{int(_grid_identity_target)}",),
        )
    notes = list(evidence.source_notes)
    if any(
        _aisha_public_avg_direct_grid_domain_enabled(key, evidence)
        for key in QUALITY_KEYS
    ):
        _append_source_note_once(
            notes,
            AISHA_PUBLIC_AVG_DIRECT_GRID_DOMAIN_NOTE,
        )
    if _aisha_q5_exact_value_public_avg_supported_counts(evidence):
        _append_source_note_once(
            notes,
            AISHA_Q5_EXACT_VALUE_PUBLIC_AVG_SUPPORT_NOTE,
        )
    draw_quality_only_relax_note = _draw_hero_quality_only_red_relax_note(evidence)
    if draw_quality_only_relax_note is not None:
        notes.append(draw_quality_only_relax_note)
    # Ethan value->cells floor (2026-07-05, author live games 2401/2407): 优品估价/极品估价 give an
    # EXACT per-quality value; per-cell settled price is near-constant per family (tables above), so
    # value/percell_p75 is a hard MIN-cells proof the count×mean prior badly misses on big-item
    # vaults (2401 truth q4 47 cells @5.2/item vs mean-2.9 display 17/23/29). Floor only (never a
    # cap) — a low per-game price means MORE cells, never fewer. quality_cell_floors is a mutable
    # dict inside the frozen RefEvidence, so the floor is visible to every downstream consumer.
    # Kill: ETHAN_DISABLE_VALUE_CELL_FLOOR=1.
    if (
        os.environ.get("ETHAN_DISABLE_VALUE_CELL_FLOOR") != "1"
        and not snapshot.get("_ethan_disable_value_cell_floor")
        and normalize_hero_key(evidence.hero) == "ethan"
    ):
        for _vq in ("q4", "q5"):
            _exact_v = evidence.quality_values.get(_vq)
            if _exact_v is None or float(_exact_v) <= 0:
                continue
            if evidence.quality_cells.get(_vq) is not None:
                continue  # exact cells already known -> no floor needed
            _pc = _ethan_quality_percell(_vq, evidence.map_id)
            if not _pc:
                continue
            _floor_cells = float(_exact_v) / _pc[2]
            if _floor_cells > float(evidence.quality_cell_floors.get(_vq) or 0.0):
                evidence.quality_cell_floors[_vq] = _floor_cells
                notes.append(f"ethan_{_vq}_value_cell_floor:{_floor_cells:.1f}")
    early_round_lightweight = bool(snapshot.get("audit_aisha_early_round"))
    engine_pass = str(snapshot.get("audit_aisha_engine_pass") or "").strip()
    if early_round_lightweight:
        max_combos = min(max_combos, AISHA_EARLY_ROUND_MAX_COMBOS)
        _append_source_note_once(notes, AISHA_EARLY_ROUND_LIGHTWEIGHT_NOTE)
    if engine_pass in {AISHA_ENGINE_PASS_SKILL, AISHA_ENGINE_PASS_ITEM}:
        _append_source_note_once(notes, f"aisha_engine_pass:{engine_pass}")
    if not is_supported_ref_hero(evidence.hero):
        return RefResult(
            status="not_structured_hero",
            source="ref_v0",
            conservative=None,
            balanced=None,
            aggressive=None,
            value_p25=None,
            value_p50=None,
            value_p75=None,
            combo_count=0,
            red_count_range=(None, None, None),
            red_cells_range=(None, None, None),
            red_value_range=(None, None, None),
            quality_count_ranges={},
            quality_cells_ranges={},
            total_grid_range=(None, None, None),
            notes=("current_hero_not_supported",),
            evidence=evidence,
        )
    hero_key = normalize_hero_key(evidence.hero)
    if hero_key and hero_key not in STRUCTURED_REF_HERO_KEYS:
        notes.append("generic_ref_hero")

    if any(note.startswith("hard_conflict:") for note in notes):
        return RefResult(
            status="no_reachable_combo",
            source="ref_v0",
            conservative=None,
            balanced=None,
            aggressive=None,
            value_p25=None,
            value_p50=None,
            value_p75=None,
            combo_count=0,
            red_count_range=(None, None, None),
            red_cells_range=(None, None, None),
            red_value_range=(None, None, None),
            quality_count_ranges={},
            quality_cells_ranges={},
            total_grid_range=(None, None, None),
            notes=tuple(dict.fromkeys(notes + ["constraints_conflict_or_too_strict"])),
            evidence=evidence,
        )

    # Per-hero truth-value regime: migrated heroes (e.g. ahmed) use the empirical settled per-quality
    # values + a re-calibrated quote safety factor (the honest p50 needs less discount than legacy).
    # env AHMAD_USE_DROP_TABLE_VALUE force-on(=1)/off(=0) overrides membership for A/B; the safety
    # override applies only when value is actually on via the regime (not under a global env force).
    _env_value = os.environ.get("AHMAD_USE_DROP_TABLE_VALUE")
    _regime_sf = _VALUE_REGIME_HERO_SAFETY.get(hero_key)
    if _env_value == "0":
        _value_on = False
    elif _env_value and _env_value != "0":
        _value_on = True
    else:
        _value_on = _regime_sf is not None
    # safety_factor=None means "use the default": fill it with the per-hero regime factor (truth-value
    # heroes need less discount on their honest p50) or the global 0.85. An EXPLICIT safety_factor from
    # the caller (tests / A/B harness) is always respected verbatim.
    if safety_factor is None:
        safety_factor = 0.85
        if _value_on and _regime_sf is not None and _env_value is None:
            safety_factor = _regime_sf
            notes.append(f"value_regime_safety:{hero_key}:{_regime_sf}")
        elif hero_key == "aisha" and os.environ.get("AISHA_ENABLE_NO_RED_DAMP", "1") != "0":
            try:
                safety_factor = float(os.environ.get("AISHA_NO_RED_DAMP_SAFETY", AISHA_NO_RED_DAMP_SAFETY))
            except (TypeError, ValueError):
                safety_factor = AISHA_NO_RED_DAMP_SAFETY
            notes.append(f"aisha_no_red_damp_safety:{safety_factor}")

    calibrated_shipwreck = _SHIPWRECK_CALIBRATED_PRIOR.get()
    if calibrated_shipwreck is not None:
        item_values = dict(calibrated_shipwreck["quality_values"])
        price_note = f"shipwreck_empirical_quality_values:{evidence.map_id}"
        _q5sv_note = None
    else:
        item_values, price_note = _quality_item_values(evidence.map_id, static_data, value_on=_value_on)
        item_values, _q5sv_note = _apply_q5_size_conditioned_value(item_values, evidence, _value_on)
    if calibrated_shipwreck is not None:
        probs = dict(calibrated_shipwreck["quality_probs"])
        prob_note = f"shipwreck_empirical_quality_probs:{evidence.map_id}"
        notes.append(f"shipwreck_empirical_calibrated:{SHIPWRECK_CALIBRATED_SHA256}")
    else:
        probs, prob_note = _quality_probabilities(evidence.map_id, static_data)
        probs = _apply_activity_shipwreck_red_boost(
            probs,
            evidence.map_id,
            snapshot,
            notes,
            phase=evidence.phase,
            current_activity_raw_map_decision=current_activity_raw_map_decision,
        )
    notes.extend([price_note, prob_note])
    if _q5sv_note:
        notes.append(_q5sv_note)
    random_floor = _random_value_floor(evidence)
    if random_floor is not None:
        notes.append(f"random_value_floor_soft_weight:{int(round(random_floor))}")
    # Minimap depth is independent of count, so compute it BEFORE the count candidates: combined
    # with the public all-items avg-cells it anchors count = grid / avg (the grid<->count cross-check).
    snapshot_round = _snapshot_round_no(snapshot)
    minimap_items = _minimap_items_from_snapshot(snapshot)
    raw_deepest = _deepest_minimap_bottom_row(minimap_items)
    known_minimap_cells = _known_minimap_cells(minimap_items)
    # Anchor the count to the OBSERVED minimap grid (count ~= grid / per-item avg-cells), not just
    # the weak map-default prior. The minimap depth is a strong count-independent signal; without it
    # the count systematically under-estimates (live 2409 R3: prior ~28 vs truth 46). Two flavours:
    #   - public total_avg_cells present -> count = grid / total_avg (most accurate cross-check), or
    #   - else use the per-quality residual per-item avg (generalised grid->count).
    # Only LIFTS toward the observed grid (max with the default center downstream); count-locked /
    # no-minimap heroes are untouched.
    avg_cells_count_hint: int | None = None
    avg_cells_count_hint_public = False  # True 仅当 hint = 公开均格(total_avg_cells)推得; 残差估计=False
    total_avg_cells = evidence.avg_cells.get("total")
    if (
        evidence.total_count is None
        and raw_deepest
        and raw_deepest > 0
        and _non_total_count_evidence_strength(evidence) >= 2
    ):
        rect_depth_grid = int(raw_deepest) * AISHA_GRID_COLUMNS
        # Lone-deep discount: a big item alone in a deep cell with no neighbours supporting that depth
        # makes raw_deepest*columns over-state the grid (~+10 cells; user-flagged on 2402/2410).
        # Re-anchor to the supported depth once the vault is mostly revealed. The reveal-completeness
        # gate (>=45% of the rectangle known) is the real guard against early sparse views; the round
        # floor only blocks R1. Small vaults reveal most by R2 (2410 R2 completeness 0.51) and need the
        # discount on the COUNT anchor, while normal early vaults (R2 ~0.31) fall below the gate.
        lone_deep_min_round = 2
        try:
            lone_deep_min_round = int(os.environ.get("AISHA_LONE_DEEP_MIN_ROUND", lone_deep_min_round))
        except (TypeError, ValueError):
            pass
        if (
            snapshot_round is not None
            and int(snapshot_round) >= lone_deep_min_round
            and rect_depth_grid > 0
            and (known_minimap_cells or 0) / rect_depth_grid >= 0.45
        ):
            adjusted = _occupancy_adjusted_depth_grid(minimap_items, int(raw_deepest))
            if adjusted < rect_depth_grid:
                notes.append(f"aisha_lone_deep_depth_discount:{rect_depth_grid}->{adjusted}")
                rect_depth_grid = adjusted
        depth_grid = max(int(known_minimap_cells or 0), rect_depth_grid)
        if total_avg_cells and total_avg_cells > 0:
            if depth_grid > 0:
                avg_cells_count_hint = int(round(depth_grid / float(total_avg_cells)))
                avg_cells_count_hint_public = True  # 来自公开均格 → 允许双向 conform
        else:
            per_item = _residual_per_item_cell_estimate(
                fixed_counts=evidence.fixed_counts,
                avg_cells=evidence.avg_cells,
                source_notes=notes,
                quality_probs=probs,
                fallback=COUNT_ANCHOR_RESIDUAL_ITEM_CELL_ESTIMATE,
                min_counts=evidence.min_counts,
                quality_cell_floors=evidence.quality_cell_floors,
            )
            if per_item > 0 and depth_grid > 0:
                known_q_cells = sum(
                    _exact_integer_quality_cell(evidence.quality_cells.get(k)) or 0
                    for k in QUALITY_KEYS
                )
                fixed_sum = sum(max(0, int(v)) for v in evidence.fixed_counts.values())
                # A publicly-revealed LARGE high-tier item (e.g. a 16-cell red car) leaves a
                # cell_floor that isn't exact-pinned, so its big cells would otherwise be divided by
                # the per-item average into ~floor/per_item phantom items. Deduct that floor and
                # refill it as ~1 item. Gated to q5-cells-unknown (the bug trigger); R4/normal
                # samples untouched. Rollback AISHA_DISABLE_Q5FIX=1. (2405 R3: hint 49 -> 44)
                _q5fix_cells, _q5fix_items = _high_tier_floor_extra(snapshot, evidence, notes)
                residual_items = int(
                    round(max(0.0, depth_grid - known_q_cells - _q5fix_cells) / per_item)
                )
                avg_cells_count_hint = fixed_sum + residual_items + _q5fix_items
        # Richness lift (experiment, env-toggleable AISHA_DISABLE_RICHNESS_LIFT=1): once a low/mid
        # tier is LOCKED (e.g. blue q3 at R3) and exceeds its prior expectation, the vault is rich
        # and the grid alone may under-state the total on a scattered layout. Lift toward the
        # richness-implied total = locked_low / P(low), blended 50% and capped at 1.25x so a
        # high-low-tier vault can't over-count. Helps the mid-round high-tier (purple/gold) estimate
        # which is otherwise total-limited (2402 R3: hint 34 -> 38 == truth).
        derived_q5_pinned_nonred = (
            any(
                str(note).startswith(f"{AISHA_DERIVED_Q5_COUNT_AVG_CELLS_NOTE}:")
                for note in evidence.source_notes
            )
            and all(
                _exact_integer_quality_cell(evidence.quality_cells.get(key)) is not None
                for key in ("q1", "q3", "q4", "q5")
            )
        )
        if avg_cells_count_hint and derived_q5_pinned_nonred:
            # The low-tier richness lift is a fallback for partially observed vaults.
            # Once this successor has completed the exact non-red physical body, using
            # the same low-tier counts to inflate total count would double-count belief
            # and recreate the 5602 phantom-red branch.
            notes.append(AISHA_DERIVED_Q5_PINNED_NONRED_RICHNESS_SKIP_NOTE)
        elif avg_cells_count_hint and os.environ.get("AISHA_DISABLE_RICHNESS_LIFT") != "1":
            locked_low = sum(int(evidence.fixed_counts.get(k, 0) or 0) for k in ("q1", "q3"))
            p_low = float(probs.get("q1", 0.0)) + float(probs.get("q3", 0.0))
            if locked_low > 0 and p_low > 0.05:
                richness_total = locked_low / p_low
                base = int(avg_cells_count_hint)
                if richness_total > base:
                    blended = int(round(base + 0.5 * (richness_total - base)))
                    lifted = min(blended, int(round(base * 1.25)))
                    if lifted > base:
                        avg_cells_count_hint = lifted
                        notes.append(f"aisha_richness_total_lift:{lifted}")
        # The residual grid/count conversion above assumes an ordinary item-size mix. When q1+q3
        # have both been scanned exactly, their observed count supplies an independent total-count
        # posterior. Cap only the SOFT residual hint at its generous p97.5; public total-average cells
        # remain exact/bidirectional and bypass this gate. This separates "many cells" from "many
        # items" on large-item warehouses (2549 R3: depth hint 76, low-tier p97.5 59, truth 52).
        low_tier_upper = (
            None
            if avg_cells_count_hint_public
            else _aisha_low_tier_count_upper(evidence, probs, round_no=snapshot_round)
        )
        if (
            avg_cells_count_hint is not None
            and low_tier_upper is not None
            and int(avg_cells_count_hint) > int(low_tier_upper)
        ):
            old_hint = int(avg_cells_count_hint)
            avg_cells_count_hint = int(low_tier_upper)
            notes.append(
                f"{AISHA_LOW_TIER_COUNT_UPPER_NOTE}:{old_hint}->{int(low_tier_upper)}"
            )
    # Draw-hero count occupancy cap. The flat count boost floors to map_prior*scale regardless of vault
    # size -> est pins ~map-constant (truth 24 and 55 both ~38-40), over-shooting small vaults. Bound the
    # boost floor by the OBSERVED (de-exploded) grid / divisor (empirically grid_mid/2.5 ~= truth across
    # small+large brackets). Computed OUTSIDE the strength>=2 gate above (draw early rounds = strength 1)
    # and de-explodes a lone-deep bottom item directly here (aisha's 0.45-completeness discount gate never
    # fires for sparse draw views; _occupancy_adjusted_depth_grid is a no-op unless genuinely lone-deep).
    # draw-only; aisha untouched.
    # Default ON (rollback: DRAW_HERO_DISABLE_OCC_CAP=1). Caps the map-prior count boost by the visible
    # grid capacity so small/shallow vaults don't claim more items than the cells can hold (synthetic +
    # per-vault evidence 2026-06-23: small-vault count over% 80->60, ALL over% 53->40; large near no-op).
    # Includes R1 (round>=1): small-vault R1 was the last uncapped over-estimate (e.g. 2405 R1 35 vs grid
    # 38/truth 26). When R1's view is deep, eff_grid is large and the cap stays loose, so it self-gates.
    draw_occ_cap: float | None = None
    if (
        not os.environ.get("DRAW_HERO_DISABLE_OCC_CAP")
        and evidence.total_count is None
        and normalize_hero_key(evidence.hero) in _draw_hero_count_keys()
        and raw_deepest
        and int(raw_deepest) > 0
        and snapshot_round is not None
        and int(snapshot_round) >= 1
    ):
        de_exploded = _occupancy_adjusted_depth_grid(minimap_items, int(raw_deepest))
        eff_grid = max(int(known_minimap_cells or 0), int(de_exploded))
        divisor = _draw_hero_occ_cap_divisor()
        if eff_grid > 0 and divisor > 0:
            draw_occ_cap = eff_grid / divisor
            rect_grid = int(raw_deepest) * AISHA_GRID_COLUMNS
            if int(de_exploded) < rect_grid:
                notes.append(f"draw_occ_cap_deexplode:{rect_grid}->{int(de_exploded)}")
            notes.append(f"draw_occ_cap:{draw_occ_cap:.1f}")
    # Ethan rough-grid window hint (Phase-1 part 3): when the occupancy guards fall back (thin
    # reveal) there is NO total_grid_target, so the count window has no geometry signal at all —
    # deep vaults (rv_analyze: truth 47 items, window 24-32) stay excluded. Compute a guard-free
    # ROUGH rectangle read (raw deepest row × columns) and pass it ONLY to open the window's upper
    # side (never shifts the center — prior weights untouched). Kill: ETHAN_DISABLE_GRID_COUNT_WINDOW.
    _ethan_rough_grid_hint = None
    if (
        os.environ.get("ETHAN_DISABLE_GRID_COUNT_WINDOW") != "1"
        and hero_key == "ethan"
        and evidence.total_grid_target is None
        and raw_deepest
        and int(raw_deepest) > 0
    ):
        _ethan_rough_grid_hint = int(raw_deepest) * AISHA_GRID_COLUMNS
    empirical_count_prior = _empirical_count_prior_036(snapshot, evidence)
    if empirical_count_prior is not None:
        notes.append(
            f"empirical_count_prior_036:{evidence.map_id}:"
            f"{empirical_count_prior[0]}:{empirical_count_prior[1]}"
        )
    total_candidates, total_prior_center = _total_count_candidates(
        evidence,
        notes,
        early_round_lightweight=early_round_lightweight,
        avg_cells_count_hint=avg_cells_count_hint,
        avg_cells_count_hint_public=avg_cells_count_hint_public,
        round_no=snapshot_round,
        probs=probs,
        occ_cap=draw_occ_cap,
        ethan_rough_grid_hint=_ethan_rough_grid_hint,
        empirical_count_center=empirical_count_prior[0] if empirical_count_prior is not None else None,
    )
    if empirical_count_prior is not None and total_prior_center is not None:
        # Finite combo budgets must visit the selected/reanchored center before
        # spending every slot on the smallest admitted total. No new hard lock.
        total_candidates.sort(key=lambda n: (abs(n - total_prior_center), n))
    if calibrated_shipwreck is not None and evidence.total_count is None and total_prior_center is not None:
        # The existing finite combo budget must not spend itself exclusively
        # on the small-N tail of a wider empirical prior. Retain the actual
        # evidence-reanchored center and visit its most likely N states first.
        center = (calibrated_shipwreck['count_mean']
                  if total_prior_center == int(round(calibrated_shipwreck['count_mean'])) else total_prior_center)
        total_candidates.sort(key=lambda n:(abs(n-center),n))
    q5q6_exact_residual_support = _aisha_q5q6_exact_residual_count_support(
        evidence
    )
    q5q6_exact_residual_overrides: Mapping[str, Sequence[int]] | None = None
    if q5q6_exact_residual_support is not None:
        physical_totals, q5q6_exact_residual_overrides = (
            q5q6_exact_residual_support
        )
        total_candidates = sorted(set(total_candidates).union(physical_totals))
        _append_source_note_once(
            notes,
            AISHA_Q5Q6_EXACT_RESIDUAL_COUNT_SUPPORT_NOTE,
        )
    # Count→grid floor helps early live rounds (e.g. R1 total grid too low) but shifts
    # R3+ fatbeans regression baselines; keep it on R1–R2 until v0.1.9 audit closes.
    count_for_grid_floor = evidence.total_count if evidence.total_count is not None else total_prior_center
    if (
        count_for_grid_floor is not None
        and snapshot_round is not None
        and int(snapshot_round) <= 2
    ):
        apply_count_implied_grid_floor(
            hero_key=hero_key,
            total_count=int(count_for_grid_floor),
            total_grid_target=evidence.total_grid_target,
            source_notes=notes,
            round_no=int(snapshot_round),
            raw_deepest=raw_deepest,
        )
    exact_total_avg_fast_path = _should_use_exact_total_avg_cells_fast_path(evidence)
    complete_gt5_count_domains = _complete_gt5_physical_count_domains(evidence)
    if not total_candidates:
        return RefResult(
            status="missing_total_count",
            source="ref_v0",
            conservative=None,
            balanced=None,
            aggressive=None,
            value_p25=None,
            value_p50=None,
            value_p75=None,
            combo_count=0,
            red_count_range=(None, None, None),
            red_cells_range=(None, None, None),
            red_value_range=(None, None, None),
            quality_count_ranges={},
            quality_cells_ranges={},
            total_grid_range=(None, None, None),
            notes=tuple(notes + ["waiting_total_count"]),
            evidence=evidence,
        )

    requested_max_combos = max_combos
    victor_three_means_support = (
        _victor_three_means_high_count_sum(evidence) is not None
    )
    if victor_three_means_support:
        _append_source_note_once(notes, "victor_three_means_joint_support")
    ahmed_q1_q6_positive_residual_probe = (
        _ahmed_q1_q6_positive_residual_antilock_enabled(evidence)
    )
    # A hard total-grid disjunction may publish only when its materialized
    # joint support is known complete.  One sentinel beyond the caller's cap
    # distinguishes an exactly-full support from a truncated prefix.
    if (
        evidence.total_grid_options
        or victor_three_means_support
        or ahmed_q1_q6_positive_residual_probe
        or complete_gt5_count_domains
        or (evidence.quality_count_cells_value_options or {}).get("q6")
    ):
        max_combos = requested_max_combos + 1
    combos: list[RefCombo] = []
    # This is the authoritative enumeration state for consumers that need the
    # *complete* support, rather than the currently materialized prefix. Keep
    # it separate from the human-readable notes: a capped prefix can look like
    # a singleton even though unexplored arms still exist.
    combo_support_complete = True
    absent_q4_widen_probe_incomplete = False
    absent_q4_global_probe_attempted = False
    quality_value_soft_weight_applied = False
    public_avg_value_soft_weight_applied = False
    q3_min = evidence.fixed_counts.get("q3", evidence.min_counts.get("q3", 0))
    q4_min = evidence.fixed_counts.get("q4", evidence.min_counts.get("q4", 0))
    q5_min = evidence.fixed_counts.get("q5", evidence.min_counts.get("q5", 0))
    q6_min = evidence.fixed_counts.get("q6", evidence.min_counts.get("q6", 0))

    _widen_fired: set[str] = set()  # BUG-G scope audit: which tiers had a false-lock widen
    if total_prior_center is not None:
        if _sparse_exact_high_total_tight_prior(evidence):
            notes.append("sparse_exact_high_total_tight_prior")
            if _exact_total_q1_avg_domain_untighten_enabled(evidence):
                _append_source_note_once(notes, EXACT_TOTAL_Q1_AVG_DOMAIN_NOTE)
        for total in total_candidates:
            q5_total_cells_zero_overrides = (
                _aisha_q5_total_cells_exact_zero_count_overrides(
                    snapshot,
                    evidence,
                    total,
                )
            )
            if complete_gt5_count_domains:
                count_value_overrides: dict[str, Sequence[int]] | None = dict(
                    complete_gt5_count_domains
                )
                if q5q6_exact_residual_overrides is not None:
                    count_value_overrides.update(q5q6_exact_residual_overrides)
                if q5_total_cells_zero_overrides is not None:
                    count_value_overrides.update(q5_total_cells_zero_overrides[0])
            else:
                # The named gate/rollback arm must reproduce the exact parent
                # precedence.  Merging these two independent overrides changes
                # sparse Ahmed/Aisha support even when the >5 joint feature is
                # disabled.
                count_value_overrides = (
                    q5_total_cells_zero_overrides[0]
                    if q5_total_cells_zero_overrides is not None
                    else q5q6_exact_residual_overrides
                )
            absent_q4_global_takeover = False
            absent_q4_complete_at_budget = False
            prior_combos = _enumerate_prior_count_combos(
                total,
                evidence=evidence,
                probs=probs,
                total_prior_center=total_prior_center,
                max_new=max_combos - len(combos),
                item_values=item_values,
                round_no=snapshot_round,
                widen_fired=_widen_fired,
                count_value_overrides=count_value_overrides,
            )
            if not prior_combos:
                residual_override = _aisha_q6_exact_residual_count_override(
                    total,
                    evidence=evidence,
                )
                residual_note = AISHA_Q6_EXACT_RESIDUAL_ANTILOCK_NOTE
                if residual_override is None:
                    residual_override = _aisha_q6_soft_total_residual_count_override(
                        total,
                        evidence=evidence,
                    )
                    residual_note = AISHA_Q6_SOFT_TOTAL_RESIDUAL_ANTILOCK_NOTE
                if residual_override is not None:
                    residual_combos = _enumerate_prior_count_combos(
                        total,
                        evidence=evidence,
                        probs=probs,
                        total_prior_center=total_prior_center,
                        max_new=max_combos - len(combos),
                        item_values=item_values,
                        round_no=snapshot_round,
                        widen_fired=set(),
                        count_value_overrides=residual_override,
                    )
                    if residual_combos:
                        prior_combos = residual_combos
                        notes.append(residual_note)
            # 4542 R2: the matching public+skill gold average is hard evidence, but widening q5
