    weighted_red_cells: list[tuple[float, float]] = []
    weighted_red_value: list[tuple[float, float]] = []
    weighted_red_cells_by_count: dict[int, list[tuple[float, float]]] = {}
    weighted_red_value_by_count: dict[int, list[tuple[float, float]]] = {}
